INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Sakla Yaralarını', 'kendine-sakla-yaralarini-nuri-can-yqgay', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gül yaprağı gibi yaşam ayaklar altında 

nereye baksan hüzün konar gözlerine 

yıllardır ki ırmağı yaralı canevinin 

akıp gider sancıyarak mevsimlere

çekilir bir köşeye seyredersin sessizce 

sessizlik ki, içine gömdüğün o derin çığlık 

ay küs, kayıp iz sürdüğün samanyolu 

güneş de doğmuyor yüreğine artık 

yüz üstü bırakıp gitti gecelerde yıldızlar 

ah! nereye baksan tül kanaması ince sızılar 

kör karanlıklardasın ey kalbim 

uçurumlar kadar derin ve yalnız 

günahkârsın ey kalbim, günahkar 

bütün mevsimleri sevmekten suçlusun 

bütün çocukları sevmekten

sevmelerin ki, kıyametten beter

anlaki affetmiyor seni hayat 

bir elinde ölüm fermanı 

bir elinde aşk 

aşk ki, ürküttüğün bir mavi kuş 

üşür durur pencerende her sabah 

vuruldun, vuruldun işte ey kalbim 

sevda bir yana düştü, hüzün bir yana 

hayatın keyfi kendine, efkârı sana kaldı 

ay kanaması 

ince bir ışığın kavşağında 

üşüyen bir serçe titremesi şimdi 

yaralı yalnızlığın 

incitir durur bakışlarındaki ince hüznü 

öyle kırılgan öyle ürkek 

sen ki, kocaman sevdaların büyüsü 

dikbaşlı yamaçların örtüsüydün 

ömürsüzde olsa bir gelinciğin sevinci

savrulup gitsede uçurumdan uçuruma

yine de ısıtabilir bir avuç mavi yaprağını

aldırma yürü 

kendine sakla gece karası hüznünü

kendine sakla yaralarını ey kalbim 

kimse bilmesin....

..', 'Bir gül yaprağı gibi yaşam ayaklar altında  nereye baksan hüzün konar gözlerine  yıllardır ki ırmağı yaralı canevinin  akıp gider sancıyarak...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kendine-sakla-yaralarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbet Bir Gün', 'elbet-bir-gun-murat-kilic-2-a7z7k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlıyorsun! 

Adı yankılanıyorken dizelerde,

Kara kalemle çizilmiş bir sebebe,

Yanıyorsun! 

Hayatı sorguladıkça,

Susuyorsun! 

Öyle soğumuşsun ki! 

Gülünce ışıldayan gözlerin,

Umut katarları taşıyan ellerin,

Bu katkılı havayı özümseyen sesin,

Şimdi bir emanet gibi üzerinde…

Hayattır bu biliyorsun.

Karanlık kuyular her daim var.

Belki onların içerisinde,

Belki de kenarındasın.

Unutma ki; 

Seni unutulmaya kelepçeleyenlerle,

Elbet bir gün hesaplaşacaksın.', 'Ağlıyorsun!  Adı yankılanıyorken dizelerde, Kara kalemle çizilmiş bir sebebe, Yanıyorsun!  Hayatı sorguladıkça, Susuyorsun!  Öyle soğumuşsun...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/elbet-bir-gun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-murat-kilic-2-dqk6v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık ve durgun bir deniz! 

Üzerinde birbirinden ziyade,

Allı yeşilli yüz binlerce fener.

Sayılamayan yılların gelip geçmişi,

Sonsuzluğun nehridir geceler.

Kimi solgun kimi suçsuz,

Kimi haylaz bir çocuk olup,

Geçiverir ağır ağır seneler.

Düne bir gün daha ekleyen,

Günün son demidir geceler.

Uzanıp bir bakıver,

Şu sonsuzluk tarlasına.

Sayamadığın kadar irili ufaklı çiçekler.

Sana da bir hikaye yazdırır elbet,

Uykusuzluk yarenidir geceler.

Bir dilek tutarsın bazısında,

Yahut uzanırsın mehtabına sevgilinle.

Hâli aynıdır değişse de mevsimler.

Kuytuluklarında hayatlar yaşatan,

Yüreğin aşk şehridir geceler. 

Vazgeçilir gibi değil,

Nasıl geçilsin bu emsalsizlikten.

Ki anlatmaya yetmez tüm heceler.

En tarifsiz halleriyle yalnızların,

Biricik umut yelkenidir geceler.', 'Karanlık ve durgun bir deniz!  Üzerinde birbirinden ziyade, Allı yeşilli yüz binlerce fener. Sayılamayan yılların gelip geçmişi, Sonsuzluğun...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/geceler-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-murat-kilic-2-a5g32', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimsesizlik giysisine büründüm bir anda.

Solmuş anılar yığınla durur bir yanda.

Hasretliğim! Ne kadar beni sevmiyor olsan da.

Ben seni canımdan çok seviyorum küçüğüm.

Bakmıyorsun artık o zakkumlu pencereden dışarı.

Bin yerden yara aldı gönül hisarı.

Tenime aşina ettim yağmuru karı rüzgarı.

Hala kapında iki büklüm duruyorum küçüğüm.

Yüzüm seher bekler bitmez gecem var.

Dilimde söylenmedik nice hecem var.

Baharda yeşerttiğim bin bir gülcem var.

Gülceleri bir bir sana sunuyorum küçüğüm.

Artık dayanamam bir mateme daha.

Çıkmaz belki son nefesim sabaha.

Madem yoksun, canım sunarım Allah’a.

Yokluğun ölüm demek, ölüyorum küçüğüm.

Zaman hep böyle geçer diye sanma.

Ben bir yandım sakın sen de yanma.

Sana kırgınım dargınım küskünüm amma,

Seni çiçeğin suya hasretliği gibi özlüyorum küçüğüm.', 'Kimsesizlik giysisine büründüm bir anda. Solmuş anılar yığınla durur bir yanda. Hasretliğim! Ne kadar beni sevmiyor olsan da. Ben seni canım...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kucugum-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Bile', 'cocuklar-bile-murat-kilic-2-x442w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum hangi rıhtımın,

Hangi beyhude gemisindesin.

Ömür yangını bir şehrin,

Hangi sabahçı kahvesindesin.

Şimdi, bana uzak o şehrin,

İsimsiz sabahında uyanıyorsun.

Beni karanlığa mahkum edip,

Yeni bir güneşe boyanıyorsun.

Öyle hırçın ve öfkelisin ki,

Sanki istiyorsun ömrüm solsun.

Bir rüzgar estirki bana,

Benden de sana yağmur olsun.

Bana ne yaptın böyle.

Düşünürken seni buluttur iki gözüm.

Toprağım kuru, solgun yaprağım,

Hazan mevsimine dönmüş gündüzüm.

Bu asilik bu anlamsız inat,

Bitirmeden bizi dön geri.

Elerinin sıcaklığına özlemdeyim.

Şimdi sen yoksun lakin,

Seni bekleyen bir tek ben değilim.

Hâlâ kapısında,

Sırma saçlı umut gözlü,

Küçük çocuklar oynar bahçemizin.

Elerinde şekerlemelerle.

Geri döneceğin günü bekleyerek,', 'Bilmiyorum hangi rıhtımın, Hangi beyhude gemisindesin. Ömür yangını bir şehrin, Hangi sabahçı kahvesindesin. Şimdi, bana uzak o şehrin, İsim...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cocuklar-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle', 'dinle-murat-kilic-2-7dr6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz mehtabı sarıyorken,

O lacivert derinliklerine.

Elini daldır hayata ki,

Bir şeyler takılsın ellerine. 

Telaşım sende son bulur,

Ey kanatların sahnesi gökyüzü.

Bağrına basıver beni de,

Bulutlarında taşı bu sözsüzü.

Dinle bu güzel musikiyi,

Tıkama özgürlüğe kulaklarını.

Salıver kendini mayhoş bahara,

Korkma, hayata aç kanatlarını.

Göreceksin ki  daha beyaz,

Uçuyorken kuşların kanatları,

Yol güneşe göğüs verdikçe,

Başlar dağların saltanatları.

Dinle beni! 

Dinle! 

Sonra adımı yaz sayfalara.

Dört tarafımı sar soluksuzca,

Yak beni! 

Sal küllerimi azgın dalgalara.', 'Deniz mehtabı sarıyorken, O lacivert derinliklerine. Elini daldır hayata ki, Bir şeyler takılsın ellerine.  Telaşım sende son bulur, Ey kana...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dinle-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '....Turkuaz....', 'turkuaz-naime-erlacin-5ir2p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“iki dirhem bir çekirdek”liğin* 

hayasız kibri vuruyor yüzüme

katı yürekli katışıksızlığı

kendini beğenmişliği

turkuazın 

tılsımlı ölümsüzlüğüne

-yenilgisi cevherin-

uykular 

maviden kalan 

düş sevinci

gidişin infazdır ey! 

gelişin 

hücre aydınlığı 

vazgeçtim güneşin altın kâsesinden

terk ettim bütün tonlarını o rengin

biliyorsun adımı

çoktandır turkuaz koydum bu yüzden

bir gönül takısıyım şimdi mavinin koynunda…

(*)    “İki dirhem, bir çekirdek”: 1844 sonrası İstanbul Darphanesinde basılan Osmanlı Sikkesindeki altın ağırlığı. Mükemmeliyeti temsil ettiği için, halk diline de bir deyim olarak girmiştir. Turkuaz ise, sevenlerinin gözünde altın sikkeden çok daha değerlidir. Koruyucu, kollayıcı, asla yanıltmazlığı ile güven verici…Sevgi ve aşkın temeli! 

(9 Ağustos 2005)', '“iki dirhem bir çekirdek”liğin*  hayasız kibri vuruyor yüzüme katı yürekli katışıksızlığı kendini beğenmişliği turkuazın  tılsımlı ölümsüzlü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turkuaz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzen Çıkar', 'uzen-cikar-halil-kesken-kovh3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağ olsanda taş olsan da

Seni de bir ezen çıkar

Kral olsan, baş olsanda

Seni de bir üzen çıkar

Anlamazsın neler olmuş

Sevda, umut nerde kalmış

Mutluluğu kimler çalmış

Seni de bir soyan çıkar

Hayatın yok dur butonu

Eline verir bastonu

En vefalı can dostunu

Yarı yolda koyan çıkar

Ünün gitse arşa değin

Sınırı var her bir şeyin

Bükülmez sanma bileğin

Seni de bir yenen çıkar

Kimsenin ahı kalmıyor

Kader gülmezse gülmüyor

Ömür sonsuza sürmüyor

Seni de bir gömen çıkar', 'Dağ olsanda taş olsan da Seni de bir ezen çıkar Kral olsan, baş olsanda Seni de bir üzen çıkar Anlamazsın neler olmuş Sevda, umut nerde kalm...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzen-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Deniz', 'garip-deniz-murat-kilic-2-qrf12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün yarından daha ümitsiz.

Karamsarlığın kıyısındayım.

Ürpertilerle yaşıyorum olduğumdan beri.

Hüzünlerin uykusundayım.

Yağmur yüklü uykuların rüyasında ıslanıp,

Paramparça yerine koydum yine yüreğimi.

Değmez diye geçirerek limitsiz ömrümü,

Zulümlerin kor yangınına verdim ellerimi.

Ne geçti hasretten başka elime.

Yıpranmanın ne olduğunu gördüm.

Bilinenlerden bir pay alırım sanarak,

Can havlinde yaşayıp uzaklara sürüldüm.

Sonu ne olacak kim bilir.

Uyanması var mı bu rüyanın? 

Gülüp geçeceğimi söylesem bile,

Sağaltabilir miyim üzerini bu yaranın? 

Garip bir deniz olmuş,

Buzla kaplı her yanım.

Ne halimden anlayanım olur,

Ne de bir soranım.

Ben bahtı kara, yüzüne hasret,

Teninin kokusuna özlemle; 

Belki bir gün bir köşede yığılır kalırım.', 'Bugün yarından daha ümitsiz. Karamsarlığın kıyısındayım. Ürpertilerle yaşıyorum olduğumdan beri. Hüzünlerin uykusundayım. Yağmur yüklü uykul...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/garip-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzüm', 'gokyuzum-murat-kilic-2-0eybw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sadece iki karış kadardı gökyüzüm.

Buğusunu sildiğim camdan bakardım ona.

Maviliği o kadar iç gıcıklayıcıydı ki; 

Ellerimi uzatıp dokunmak isterdim.

Yakalamaya çalışırdım yıldızlarını.

Küçük damlalarla ıslatırdı penceremi.

Benim gökyüzümdü bana aitti.

Her halini seviyordum onun.

Sadece uyuyakaldığım zamanlar ayrıydık.

Sevdalım, çocukluk aşkım, gökyüzüm.

Ve yıldızlar…

Yamalı çorabımdan dökülen bilyelerim gibi.

Sana yapmayı hayal ettiğim taç gibi yıldızlar.

Her gece bir başka güzel,

Her gece bir başka alımlıydılar.

Bende bir gökyüzü var ki sorma gitsin.

Bulutlarında koştuğum

Yağmurunda yoğrulduğum,

Her gün doğuşunda yeniden doğduğum,

Bana mahsus bir gökyüzüm var.', 'Sadece iki karış kadardı gökyüzüm. Buğusunu sildiğim camdan bakardım ona. Maviliği o kadar iç gıcıklayıcıydı ki;  Ellerimi uzatıp dokunmak i...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gokyuzum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünde Yoksun', 'bugunde-yoksun-murat-kilic-2-8r8x3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözler sabah özleminde, uykusuz geceler.

Yaşlanıyor yüzüm, silik aynalar gibi.

Sadece adını yankılatıyorsun içimde.

Sesime ses olmuyorsun,

Hiç ulaşılmayan uzaklar gibi,

Bugünde yoksun.

Başım dik ama içim ezik.

Dağlarım tipili, yollarım boran.

Hasretin esaretindeki gönlüme,

Bir ışık yakmıyorsun.

Çöküyorken üzerime bu zifiri duman,

Bugünde yoksun.

Hayal artık bir saniyeyi,

Seninle ortadan bölmek.

Damlalar deniz olmuşken gözlerimde, yine; 

“Acı senin, yaşa” diyorsun.

Şarkılarım sahibini arıyorken böyle divane,

Bugünde yoksun.', 'Gözler sabah özleminde, uykusuz geceler. Yaşlanıyor yüzüm, silik aynalar gibi. Sadece adını yankılatıyorsun içimde. Sesime ses olmuyorsun, H...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bugunde-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıklar Sahibesi', 'isiklar-sahibesi-murat-kilic-2-tw0g0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyuyor musun? 

Bir ezgi salınıyor rüzgarda,

Duyuyor musun gece mavisi.

Çok mu uzaklardasın yoksa,

Çok mu imkansızsın ışıklar sahibesi.

Ben bilmem sonumu,

Işıklar senin, olan biten sensin.

Gözlerim uykulara limansız hâlâ,

Olan, olmayan, bilinen sensin.

Işıklar ki; gözünde parıldar,

Işıldar adınla bu şehir.

Tenimde derin bir yangın başlatır,

Dudağındaki yıllanmış zehi

Uyumak mümkün değil,

Gözümü tırmalıyor mektubun.

Yollara nasıl hükmüm geçsin,

Beni tanımayan bu yol, senin yolun.

Umudum gözlerinde solgun,

Gözlerin gecelerin işkencesi.

Gövdem  bu savaştan oldukça yorgun,

Yelkenlerim denizinin acemisi.

İklimlere yazılıp sürgün gibi,

Dantel gibi örülür yaprağım.

Bir bulutun yoksunuyum divanda,

Kurudur, çatlamıştır alın toprağım.

Aç kalbini gireyim artık içeri.

Tutmaz oldu ellerim, parmaklarım.', 'Duyuyor musun?  Bir ezgi salınıyor rüzgarda, Duyuyor musun gece mavisi. Çok mu uzaklardasın yoksa, Çok mu imkansızsın ışıklar sahibesi. Ben ...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/isiklar-sahibesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın ve minnacık Köpeği…', 'kadin-ve-minnacik-kopegi-hikmet-feridun-demir-sv803', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün, on Ağıstos ikibinbeş.

Bugün sokakta bir Kadın gördüm.

minnacık Köpeğini göğsüne bastırmış,

tekbaşına, umursamazca, birazda ürkek…

ilgimi çekti, baktı bana boş gözlerle…

Göz göze geldik, boşlukta buldum kendimi…

Bu gün caddede bir Kadın gördüm,

Almanyanın şirin bir kasabasında,

tekbaşına minnacık Köpeği kucağında…

Bu gün sokakta bir Kadın gördüm, 

gögsüne bastırmış minnacık köpeğini

Tüm sevgisini ona vermişcesine...

Kalbi ona akmışcasına sıkıca göğsüne bastırmış

Her şeyini ona vermişcesine...

Bu gün bir Kadın gördüm sokaklarında,

Almanyanın şirin bir kasabasının…

Aradığı sevgiyi bulmuş gibi...

Dünya umrunda değilmiş gibi

Mutluluğunu minnacıkta bulmuş gibi…

Bu gün sokakta bir Kadın gördüm...

Tüm sevgisini minnacık Köpeğine vermiş...

Aradığı sevgiyi minnacıkta bulmuş...

10.08.2005 

Wermelskirchen-Almanya', 'Bu gün, on Ağıstos ikibinbeş. Bugün sokakta bir Kadın gördüm. minnacık Köpeğini göğsüne bastırmış, tekbaşına, umursamazca, birazda ürkek… il...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kadin-ve-minnacik-kopegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm', 'kordugum-murat-kilic-2-urhl7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceleri gündüzleri karıştırmak yazık şey.

Hüzünleri katmak hep hayata, kahretmek…

Bir kördüğümü çözmeye çalışırken,

Bilinmez uçurumlara sürüklenmek…

Tüm baharları koynumda saklamışken,

Hiç bilmeden seni bende yitirmek…

Ne kahreden bir yangındır bilir misin? 

Gurbetini içerimde büyütmek.

Yine bir kördüğüm.

Yine bir yalanın içindeyim.

Kollarım sarılamamaktan yorgun.

Bilinmez bir kederin eşiğindeyim.

Uyumadan avuntulara sarılarak,

Yaşayabilmenin derdindeyim.

Acılarım var benim.

Nice yaralardan devşirilmiş.

Göz yaşlarım var.

Bir ormanı saran yapraklar gibi.

Mevsimsiz soluyorum ve çaresizce,

Avuntusuzluğun hüznüyle yaşayıp,

Günden güne ölüyorum,

Kuruyan topraklar gibi.

Gün bitti yine yüzüm kederli.

Unutulmuş hüviyetimle bir köşede oturuyorum.

Bir sorgu çemberinin tam ortasında,

Günden güne çürüyorum.', 'Geceleri gündüzleri karıştırmak yazık şey. Hüzünleri katmak hep hayata, kahretmek… Bir kördüğümü çözmeye çalışırken, Bilinmez uçurumlara sür...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kordugum-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Hikayem', 'kucuk-bir-hikayem-murat-kilic-2-rpht8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz manzaralı olmasada,

Yaşadığım yerleri seviyorum.

Sabah kuş sesleriyle uyanmayı,

Kireçli musluk suyuyla,

Yüzümü yıkamayı seviyorum.

Birkaç zeytinle yapıyorum kahvaltımı.

Üzerine paşa çayı dedirten bir çayla,

Tamamlıyorum sabahı.

Üzerimi değiştirip alel acele,

Salıveriyorum kendimi çocuk bağrışmalarına.

Küçük su birikintilerinde

Kağıttan gemi yüzdürüyorum.

İşimde sıkıldığımı hissettiğim çocuklarla,

Güle ağlaya top oynuyorum.

Sağa sola koşuyorum minik bedenler arasında,

Onları izliyorum bazen yüzümde tebessümle.

Dört tarafı alçak damlardan ibaret bir yer burası.

Etrafta gökkuşağı renginde toprak yapılı evler…

Dünyadan bir başka güzel buralar.

Tüm güzelliğiyle yaşıyorum bu cenneti; 

Çocukluğumla gençliğimi harmanlayarak…

Sonra caddeye çıkıyorum.

Araba katarları arasındayım.

Eskiden kalma huyumla,

Arabaların arkasına takılıyorum.

Her çeyrek başı geçen belediye otobüslerinin,

Camlarımda saçlarımı tarıyorum.

Hayata el sallıyorum.

…. …. …. …. …. …. ….

Çamurlu yollardan geri dönüyorum eve.

Kuyruğunu ekmek poşetlerinden yaptığım,

Çıtasının birini yara bandıyla sardığım,

Uçurtmayı alıyorum.

Ellerimden tutuyorum arkadaşlarımın.

Şehri kartal heybetiyle gözleyen tepeye gidiyorum.

Tepede asker gibi dizilmiş

Havalandırma borularını

Atlama tahtası benzetmesiyle

Üzerinden atlıyorum.

Arkadaşlarımla saklambaç oynuyorum.

Ne kadar saklasam da kendimi onlardan; 

Büyüdüğümü saklayamıyorum.

Kendim için yaptığım oyuncaklarda,

Şimdi tanımadığım çocuklar mutlu oluyor.

Ben ise tren garında bilet kesen

Kompartıman biletçisi gibi kalıyorum yanlarında.

Umutlar benim ama sevinen başkaları.', 'Deniz manzaralı olmasada, Yaşadığım yerleri seviyorum. Sabah kuş sesleriyle uyanmayı, Kireçli musluk suyuyla, Yüzümü yıkamayı seviyorum. Bir...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kucuk-bir-hikayem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecaz Hayatı', 'mecaz-hayati-murat-kilic-2-urmel', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buğulara yazdım ilk cümleleri.

Nehirlere kağıttan yelken yaptım.

Şehirleri yollarda yudumladım,

Uykuda düş kurarken niceleri.

“Bulut” adı asıl yağdığındadır.

Yüzün ışığı söndüğünde gece,

Çatlamışlığına derman der ise,

“Toprak Dua” kabul olduğundadır.

Bir sürgüne mahkum ve bir de mecbur,

Oldu bu haykırış sıktıkça dişini.

Hep hüzünlü şarkılar çalan sesini,

Duyuruyordu öksüz bir tambur.

Uçuyorken daha bir güzel kuşlar.

Açarken daha endamlı bir çiçek.

Lakin bilinmez oldu geçmiş gelecek; 

Unuttu sırayı iklimler, kışlar.

Aklımın kara kutusunu açsan,

Kanatlanır yaralı bin güvercin.

Her susuşta bir ömrünü yitirenin,

Ağıdını duysan diyorum, anlasan.

Yağmasın yağmur, kurusun; ne çıkar.

Hiç önemli değil güneş doğmasın.

Adın bilinmezleri sağıma yamasın,

Beni bende yaşlandırdığın kadar.

“Sonsuz” mecazına koşarken atım.

Bu maviliğin göze ilişmesi.

İçimdeki kelebeğin kanat sesi.

Uçmak diken, takılan saltanatım.

Her gülüşte susmalara ağlayan,

Ömür yangını olmuştur vuslatım.', 'Buğulara yazdım ilk cümleleri. Nehirlere kağıttan yelken yaptım. Şehirleri yollarda yudumladım, Uykuda düş kurarken niceleri. “Bulut” adı as...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mecaz-hayati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-necla-i-lhan-6cnjg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ömür ki,

aşka adanmış.

Bazen ayrılık,

kimi zaman hüzün.

Hepsi boş,,anlamı yok onun için

Ne gecenin,ne de gündüzün.

Bir kadeh içki,sığınacağı liman çoğuzaman

her akşam bir barda

efkar dağıtır,döker içindekileri.

Belki bir dost bulur o''nu anlayacak,

zor bulunur,be dostum! 

Boşa devirdin kadehleri.

Keşke ağlayabilsen,

akıtabilsen gözyaşlarını pınarından.

Oysa,

kan ağlıyor yüreği ayrılık acısından.

Hey dostum! Gülümse,

Uğraşma zamanı döndürmek için geriye

Yeni aşklara aç yelkenini.

Gülümse..

Gülümse..', 'Bir ömür ki, aşka adanmış. Bazen ayrılık, kimi zaman hüzün. Hepsi boş,,anlamı yok onun için Ne gecenin,ne de gündüzün. Bir kadeh içki,sığına...', ARRAY['Türk Edebiyatı','Şiir','Necla İlhan']::text[], 8.5, '{"poet":"Necla İlhan","poet_slug":"necla-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulumse-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Bir Özlem', 'oylesine-bir-ozlem-murat-kilic-2-c2u5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi mevsimi söyleyeyim sana! 

Hiç biri özlemedi seni benim kadar.

Hiçbir sahil beklemedi bir damla maviliği,

Benim seni beklediğim kadar.

Dünyanın her köşesinde,

Zümrüt gözlerinin özlemiyle,

Sonsuzluğa yürüyorken,

Garip bir esinti sarıyordu beni.

Ellerimin titrekliğiyle sana uzanıyordum.

Sana uzatıyordum demet demet hayallerimi.

Sen ise şehirler kadar büyüyordun içimde.

Sadece kendime büyütüyordum seni.

Sen içimde büyüdükçe,

Daha da seviyordum ellerini gözlerini…

Saçlarına renk renk kelebekler konduruyor,

Ardından mahrem bir göze gizliyordum.

Kendimle özümseyip,

Kendimle yoğuruyordum seni.

Şimdi çok uzaklarda bir yerdesin belki.

Tahmin edemediğin kadar özlüyorum.

Ellerini, gözlerini… 

Hem de ölesiye! 

Tüm acılarını ve sevinçlerini,

Yüreğimde taşıyarak.

Başkalaşmadan, unutmadan; 

Yakışırcasına yaşayarak.

Gözlerimde senden kalan,

Son tebessüme kadar

Yaşayacağım seni.', 'Hangi mevsimi söyleyeyim sana!  Hiç biri özlemedi seni benim kadar. Hiçbir sahil beklemedi bir damla maviliği, Benim seni beklediğim kadar. ...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/oylesine-bir-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-guzin-eye-dundar-xzo5z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ırmak gibi 

başladı hayat

kaynaktan dağlara

ışıldayarak

debisi arttıkça

hırçınlaşarak

yokuşu kayaları

hiç sarmadımı

gün gün çağlayana

kanatlanarak

sakin bir ovada

ipek bir çarşaf

cana can verip

kucak açarak

dipsiz kuyularda

kaybolmadımı

yağmurla birleşip

coşup taşarak

sellerden ak kardan

umutlanarak

bir gezgin gibi 

düşüp kalkarak

Tanrı ya her yeni gün....

yalvarmadımı..', 'Bir ırmak gibi  başladı hayat kaynaktan dağlara ışıldayarak debisi arttıkça hırçınlaşarak yokuşu kayaları hiç sarmadımı gün gün çağlayana ka...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayat-232-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**(Ç) alındı (Ç) içeğim**', 'c-alindi-c-icegim-seyhmus-sevilmez-mo4od', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çorak Çalılıklarda

Çırpınan

Çiçeğimdin...

Çehremi Çevreleyen

Çizgilerden Çerçevem,

Çokça Çalınan Çalgılardaki

Çaresizliğimdin...

Çok Çabaladım Çiçeğim

Çok! 

Çalımlarınla Çeliştim

Çekingenlik Çizgilerimiz

Çakışınca 

Çirkeflik Çullandı Çevremize 

Çalılıklardan Çıkarıp

Çamurlara Çırpmışlar Çiçeğimi

Çıngıraklara Çanlar Çalınır,

Çimenler Çöl Çayırlara Çöker

Çehremdeki Çizgilerinde 

Çibanlar Çağlaşır...

Çengelli Çapraz Çivilerle

Çoktan Çakıldım Çarmıha

Çoktan! ..

Çünkü Çalındı Çiçeğim

09.08.2005', 'Çorak Çalılıklarda Çırpınan Çiçeğimdin... Çehremi Çevreleyen Çizgilerden Çerçevem, Çokça Çalınan Çalgılardaki Çaresizliğimdin... Çok Çabalad...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/c-alindi-c-icegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklık Yükünü Sardım Sırtıma', 'asiklik-yukunu-sardim-sirtima-umut-gungor-gws5i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşıklık yükünü sardım sırtıma,

Dertli nağmeleri söyler dururum,

Gül yüzlü yarimi alsam yanıma,

Diyerek gönülden çağlar dururum.

Bakma karışan saç dökülen yaşa,

Haykırdım sevgimi ben dağa taşa,

Kalbimi kaptırdım bir kara kaşa,

Diyerek gönülden çağlar dururum.

Ağlamak ne demek yasa durmuşken,

Şu kafamı taştan taşa vurmuşken,

Mutluluk yoluna köprü kurmuşken,

Diyerek gönülden çağlar dururum.

Bir mezarda bana kazın demiştim,

Taşa sevdiğimi yazın demiştim,

Sırasımı şimdi sazın demiştim,

Diyerek gönülden çağlar dururum.

Bir söze darılıp gitmez diyordum,

Aşkımız çok büyük bitmez diyordum,

Beni bırakıpta yitmez diyordum,

Diyerek gönülden çağlar dururum.', 'Aşıklık yükünü sardım sırtıma, Dertli nağmeleri söyler dururum, Gül yüzlü yarimi alsam yanıma, Diyerek gönülden çağlar dururum. Bakma karışa...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asiklik-yukunu-sardim-sirtima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek Yüzlü Bebeğim', 'melek-yuzlu-bebegim-i-lknur-cekici-nn7pb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylarca bekledim seni

O gülen gözlerini

Minicik ellerini

Mis kokulu tenini

Sonunda doğdun oğlum

Neşeye boğdun oğlum

Benim bir parçam

Canımın içi oğlum

Korusun tanrım seni

Soldurmasın gül yüzünü

Melek yüzlü bebeğim

Birtanemsin sen benim

                            (Sevgili arkadaşımın Birtanesine) 

                            GÖYNÜK', 'Aylarca bekledim seni O gülen gözlerini Minicik ellerini Mis kokulu tenini Sonunda doğdun oğlum Neşeye boğdun oğlum Benim bir parçam Canımın...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/melek-yuzlu-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağırdı Gözleri Nasıl Gitmeyim', 'cagirdi-gozleri-nasil-gitmeyim-umut-gungor-uqgs5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çağırdı gözleri nasıl gitmeyim,

Çıra gibi eriyipte bitmeyim,

Şunun şurasında yeni yetmeyim,

Öyle bir güzelki sormayın gitsin.

Gözleri yüreği aldı yürüdü,

Sevgi bahçesine beni sürüdü,

Güzel çiçeklerle teni bürüdü,

Öyle bir güzelki sormayın gitsin.

Endamı bedeni sarstı yerinden,

Yürekten bağlandım ona derinden,

Heyecandan kalkamadım yerimden,

Öyle bir güzelki sormayın gitsin.', 'Çağırdı gözleri nasıl gitmeyim, Çıra gibi eriyipte bitmeyim, Şunun şurasında yeni yetmeyim, Öyle bir güzelki sormayın gitsin. Gözleri yüreği...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cagirdi-gozleri-nasil-gitmeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burcum', 'burcum-mehmet-akif-kurtoglu-nx39n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu şiir benim yazdığım ilk şiirim ve gerçekten şiirde başarılı olduğuma inanıyorum.önceleri inanmazdım ama şimdi...', 'bu şiir benim yazdığım ilk şiirim ve gerçekten şiirde başarılı olduğuma inanıyorum.önceleri inanmazdım ama şimdi......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Kurtoğlu']::text[], 8.5, '{"poet":"Mehmet Akif Kurtoğlu","poet_slug":"mehmet-akif-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/burcum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zzzzz / Yar Beni -1*', 'zzzzz-yar-beni-1-bir-mim-kemal-ertugrul-9iba0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yar beni yar yar beni

Hem sever sayar beni

Sakın eller duymasın

Defe koyarlar beni

Yar beni yar yar beni

Nasılsa duyar beni

Sırrımız bizde kalsın

Bilmesin ağyar beni

Yar beni yar yar beni

Öpmeden uyar beni

Ne zaman el uzatsam

Ağlatır o yar beni

* yar beni; sevgili anlamında...', 'Yar beni yar yar beni Hem sever sayar beni Sakın eller duymasın Defe koyarlar beni Yar beni yar yar beni Nasılsa duyar beni Sırrımız bizde k...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zzzzz-yar-beni-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim', 'sevgim-hidir-altas-ramdy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlatması zor ve uzundur

Everesttende yüksektir ulaşılamaz

Okyanustan genişmi geniştir

Hepside küçük kalır sevgimden

Ulaşmak ister garip gönlüm

Anlatmak isterim aylarca

Ne akşam olsa nede sabah

Günler yetmez anlatmak için sevgimi

Bir adım ötede oturur evinde

Ulaşamam ona kolum kısa kalır

Aramızda sıra dağlar dizili

Defterime yazabilirim ancak sevgimi

Turhani dinler sadece ben okuyunca

Defterim sararır gider yıllar sonra

Okutamam bir türlü yazdıklarımı

İçimde ukde kalır; söyleyemem sevgimi', 'Anlatması zor ve uzundur Everesttende yüksektir ulaşılamaz Okyanustan genişmi geniştir Hepside küçük kalır sevgimden Ulaşmak ister garip gön...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanırım', 'kiskanirim-husniye-akarin-vgq07', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çıkma evden hasta desinler

Açma pencereni hapis desinler

Yatağa düşmüş verem desinler

Kıskanırım sana bakan gözleri

Çıkma sokağa aziz desinler

Kimseyle konuşma dilsiz desinler

Bakma etrafa kör desinler

Kıskanırım sana bakan gözleri

Saçlarını tarama rezil desinler

Güzel giyinme fakir desinler

Kimsesiz bu erkek yetim desinler

Kıskanırım sana bakan gözleri', 'Çıkma evden hasta desinler Açma pencereni hapis desinler Yatağa düşmüş verem desinler Kıskanırım sana bakan gözleri Çıkma sokağa aziz desinl...', ARRAY['Türk Edebiyatı','Şiir','Hüsniye Akarın']::text[], 8.5, '{"poet":"Hüsniye Akarın","poet_slug":"husniye-akarin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiskanirim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^ RapunzeL ^', 'rapunzel-ayse-i-smetoglu-7ulxx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yasak bir sızıntı gibi aktı saçları

.......................................... modern tuğlalardan 

Küstah sarmaşığın kulesinde,

Dinamite giden mor kıvılcımdı 

........................................... zaman! ! 

Bir patlamanın eşiğine saklanmıştı 

Aşkın sözde kuralları

Ve gizlendiği yerden,

Uluorta kopardı isyan çığlıkları...

RapunzeL! ! senin tahammül sınırlarına 

.......................................... bir dokunulsa! 

Ağırır parmaklar 

Büzüşür uçlar

İşte o an 

Limon kokulu buklelerinden

Dökülür karşılıksız aşklar...', 'Yasak bir sızıntı gibi aktı saçları .......................................... modern tuğlalardan  Küstah sarmaşığın kulesinde, Dinamite gid...', ARRAY['Türk Edebiyatı','Şiir','Ayşe İsmetoğlu']::text[], 8.5, '{"poet":"Ayşe İsmetoğlu","poet_slug":"ayse-i-smetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/rapunzel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahraman Olmak İstemiyorum', 'kahraman-olmak-i-stemiyorum-melih-coskun-e8z5j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kahraman olmak istemiyorum artık 

Sevilmek istiyorum sadece sevdiğim kadar,

Hep ayıpmış gibi sakladım göz yaşlarımı bugüne kadar

Artık ağlamak istiyorum 

Dizeler döküp geceler boyu 

Denizi maviye 

Geceyi siyahı

Ve yarını umuda boyadığım için değil 

Sadece varolduğum için sevilmek istiyorum. 

Sadece insan olduğum için 

Paylaşsınlar benimle bir somun ekmeği 

Ve sadece aynı gökyüzüne uyandığım için 

Günaydın desinler bana 

Ve hiçbir sebep olmaksızın 

Gülerek baksınlar istiyorum gözlerimin içine 

Kahraman olmak istemiyorum artık ben 

Sadece sevilmek istiyorum 

Sevebildiğim için çıkarsızca...', 'Kahraman olmak istemiyorum artık  Sevilmek istiyorum sadece sevdiğim kadar, Hep ayıpmış gibi sakladım göz yaşlarımı bugüne kadar Artık ağlam...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kahraman-olmak-istemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mikdat Bal Üstat’a Hürmeten', 'mikdat-bal-ustat-a-hurmeten-kamber-bal-c62pc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün çok hastayım

Dizelerinizle yastayım

Şimdi sizden de ustayım

Çekip gidemezsiniz

Ay gibi paralayıp, gün gibi söndüm

Şaşırdım kaldım,divane gibi döndüm

Yad elinde bir goncacık güldüm

Dermeden çekip gidemezsiniz

Açız engin bilgilerinize

Gelemedim henüz denginize

Doyamadan sevginize

Unutup gidemezsiniz

Henüz yeşermiş fidanken

Acı verdi bu zamansız diken

Vazgeç vakit erkenken

Kanımızı kurutup gidemezsiniz

Seversen Allah’ı bir hal ol

Bal içinde Gerçek Bal ol

Hünkar dergahına yol ol

Süzmeden çekip gidemezsiniz

2005  Sayın Mikdat Bal Üstadın Gidiyorum Artık Şiirine Cevaben Yazıldı', 'Bu gün çok hastayım Dizelerinizle yastayım Şimdi sizden de ustayım Çekip gidemezsiniz Ay gibi paralayıp, gün gibi söndüm Şaşırdım kaldım,div...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mikdat-bal-ustat-a-hurmeten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Kere Aşık Oldum Sadece', 'ben-bir-kere-asik-oldum-sadece-melih-coskun-8zpze', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.......Ben bir kere aşık oldum sadece. Küçücük bir gülümsemeyle başladı her şey. Oysa hiç kimseden hiçbir şey istememiştim ben. 

.......Daha önce de kalbimin hızla çarptığı zamanlar olmuştu hayatımda. Ama hiçbir zaman böyle sıkışmamıştı göğsüm, böylesine ağrımamıştı sol yanım ve böylesine güzel gelmemişti daha önce dinlediğim hiçbir şarkı. 

.......Ben bir kere aşık oldum sadece. Gelip geçici hüzünlerdi diğerleri sadece o çok sevdiğim şiirdeki  “ters yönlerde ilerleyip bir süre sonra gözden kaybolan trenler” gibi yada Edip Cansever’in dizelerindeki caz müziği gibi gelip geçici hüzünlerdi yıllar sonra adlarını bile hatırlayamadığım. 

.......Ben bir kere aşık oldum sadece. Beş yaşında bir çocuğun etrafına sürekli gülücükler saçan bakışlarıydı tutulduğum,  “Üniversiteli bir kız rüyasıydı” sen benim hiçbir şeyimsin diyerek kendime bile yalanlar söylediğim.

.......Hiç bir şeyim eksik değil sanıyordum atabilmek için yüreğimi aşk denen kuyunun bilinmeyen karaltısına. Sevgiliye söylenebilecek en güzel sözler ezberimdeydi hala ve kendimden bile vazgeçebilme kabiliyetiyle hazırdı gönlüm damdan düşer gibi ayaklarımın dibine yuvarlanan aşka.     

.......Oysa ne kadar yanıldığımı zaman gösterdi bana. Sabahlara kadar konuşabilecekken ve anlatabilecekken bildiğim her şeyi sevgiye dair, susmak düştü yine payıma. Çünkü dünyanın  en zor şeyiydi bir sevgiyi söyleyebilmek şayet gerçekten seviyorsanız. Kaybedeceklerini göze alamamak ve inadına her gün biraz daha kaybetmektir artık yaşanılan.

.......Oysa ne kadar isterdim bir kerecik olsun kendini benim gözlerimle görebilmeni. Belki o zaman anlardın, beni sevmeyecek olsan bile neler çektiğimi. 

.......Ben bir kere aşık oldum sadece

.......Gerisi mi? 

.......Boşver gerisini.........................!', '.......Ben bir kere aşık oldum sadece. Küçücük bir gülümsemeyle başladı her şey. Oysa hiç kimseden hiçbir şey istememiştim ben.  .......Daha...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-bir-kere-asik-oldum-sadece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı gerçekler', 'aci-gercekler-husniye-akarin-swku6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum canım seni sevmek yasak bana

Ama bırakta ona ben karar vereyim

Herşeyin zoru güzeldir be gülüm

Kaçmak deyil çözüm onu zorda olsa

Paylaşmaktır yaşamaktır be gülüm

Seni sevmek acı versede bana 

Ben senin gibi kaçmayacağım canım

Hatırlıyormusun bir sözün vardı

Acıyı yaşamadan onun acı olduğunu

Anlayamazsın diyordun

İşte ben buradayım ya sen; 

Neredesin şimdi

Hadi git gidebilirsen

Ben tek başıma yaşarım şimdi

Ama şunu bilki güzelim

Sende bir gün yaşayacaksın

Acı nedir anlayacaksın

Ozaman etrafına baktığında

Seni benden başka sevenin kalmayacak

Be gülüm şimdi gidebilirsin', 'Biliyorum canım seni sevmek yasak bana Ama bırakta ona ben karar vereyim Herşeyin zoru güzeldir be gülüm Kaçmak deyil çözüm onu zorda olsa P...', ARRAY['Türk Edebiyatı','Şiir','Hüsniye Akarın']::text[], 8.5, '{"poet":"Hüsniye Akarın","poet_slug":"husniye-akarin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aci-gercekler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüsün Yagmur Ciceginde Temmuzum', 'gulusun-yagmur-ciceginde-temmuzum-ozenc-yasar-lflsc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüsün yagmur ciceginde temmuzum

taslara degince sular

derin bir nehirin

Yüreginde geceler 

Her günün ardinda 

Beklenir doguma gülen gözlerin 

sen temmuzum

adin sicak yaz gecelerinde

dilin safliginda susar yeryüzü 

gülüsünü kesmesin ömrün yarisinda yagmurlar 

ellerin icimizde yitik bir gencligin isyani

gelecek suskun savaslar misali

kitlenmis kapilar acamiyorsa korkulari

arka sokaklarda yol gezer 

kelebek ucusunda acemiligin annesi

birakir yarinlarini yol agzina ferman olmus gölgelere

yari ciplak kuskanatinda savaslarin yorgun hali

gözlerin dünyanin her yerinde

bakiyor dogdugun temmuza

her yalnizligin icinde sen olursun mutlak

temmuzum

oglum

Cayan Rodam

özlem kiyi olmus baba yüreginde

sen geldin kirlenmemis temmuz cicegiyle

büyü kavgasiz cocuk olma

dünyayi kirletenleri unutma öfkende

bakistik su gülüslerinde sen aramiza katilinca

cigliksa umuttu sabahlara inen 

yalaz rüzgarlarda estin 

iki temmuz alevlerinde yanan yasama inat

aydinlik habercisiydi kollarima verilen

yakinligin rengidir umudun 

her bakista canli bir hayat izinde

vakit buldukca atlar kosusunda büyürsün

Cayanim Rodam 

Temmuz gülüsün gözleri kaldi bana

Kizil bir gül gibi yesermeye 

Savaslarin kani olmasa yalanlar

Mutlu dogar yeryüzüne 

Kipriklerimi oksarken

Yollar kisa kalir ömrün uzunlugunda

Temmuz cicegim

Yüregimin varligi

Oglum Cayan Roda

06. 07.05

A. Özenc Yasar', 'Gülüsün yagmur ciceginde temmuzum taslara degince sular derin bir nehirin Yüreginde geceler  Her günün ardinda  Beklenir doguma gülen gözler...', ARRAY['Türk Edebiyatı','Şiir','Özenç Yaşar']::text[], 8.5, '{"poet":"Özenç Yaşar","poet_slug":"ozenc-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gulusun-yagmur-ciceginde-temmuzum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat Gecenin İkisi', 'saat-gecenin-i-kisi-ufuk-coban-feocm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerime uyku girmiyor, daha kaç saat uykusuzum bilmiyorum,

Seni düşünmekten başım kokunun sindiği yastığa gitmiyor,

Odamda hep aynı şarkı bir türlü bitmek bilmiyor,

Ne anı, ne kader, ne de gözlerin hiçbiri silinmiyor.

Saat gecenin ikisi, daha ne kadar kederdeyim bilinmez,

Sigaram da yok ki içeyim, dumanı boğsun ciğerlerimi,

Unutmaya çalışsam da unutacak bir şey yok üzerimde,

Herşey işlemiş, girmiş delmiş sevda yüklü yüreğimi.

Gözlerim daha açık kalır mı bilmem ışık olmadan,

Gitmek için bir başka kapı bulunur mu bu evde? 

Hepsi kapanmış açılmıyor yeni bir sokağa,

Herşey toplanmış anılardan, kilitlenmiş sessizliğe.

Gitmeli miydin, bir gece vakti hayatımdan uzaklara,

Kapatmalı mıydın kapıları bir daha dokunmamacasına? 

Saat gecenin ikisi, ben hala senin hayalinde,

Benim gibi saatim de durmuş gecenin ikisinde.

10/08/2005 12:24', 'Gözlerime uyku girmiyor, daha kaç saat uykusuzum bilmiyorum, Seni düşünmekten başım kokunun sindiği yastığa gitmiyor, Odamda hep aynı şarkı ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saat-gecenin-ikisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-meral-vurgun-g47d0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Meinem Vater

ich hätte meinen Vater gerne als jungen Mann erlebt

er erzählt nicht viel von sich

aber einige Prinzipien wiederholt er ständig 

alles muss seine Ordnung haben

vor anderen sollte man nie schlecht dastehen

er hatte immer einen Fünfzigmarkschein

im Geldbeutel

nicht um ihn auszugeben, sondern

um ihn dabei zu haben

mein Vater wuchs in Pommern auf

es müssen ziemlich raue Sitten gewesen sein

auf den Höfen

dann die Flucht vor den Russen

lange bevor er meine Mutter traf

entdeckte er seine Liebe zu den Traktoren

er arbeitete sich zum Kfz-Meister hoch

ich erlebte ihn als einen Mann, der

strikt nach seinen Prinzipien lebt

wenn ich ihm heute begegne

bewundere ich seine Geradlinigkeit bis ins Alter

sein Jähzorn verrauchte, und ich höre

ein gutes Stück Weisheit, wenn 

er wieder von seinen Prinzipien anfängt

...

es darf nur nicht zu viel werden

Ralph Raske

BABAMA

babamı genç bir adamken yaşamak isterdim

fazla anlatmazdı kendini

ama bazı prensiplerini tekrarlardı sürekli

onun nizamında olmalıydı her şey

insan başkalarının önünde asla kötü durmamalıydı

kesesinde her zaman elli Mark’kı olurdu

harcamak için değildi, aksine

yanında bulunması içindi 

Pomeranya’da büyümüş babam

mutlaka pütür pütür geleneklerle olmalı

avlularda

Ruslar’dan kaçış sonra

annemle karşılaşmadan uzun zaman önce

keşfetmiş sevgisini traktörlere

çalışmış yükselmek uğruna, teknikerlik ustalığına 

onu yaşadım katı prensipli bir adam olarak

bu gün karşılaşsaydım eğer onunla

yaşlanıncaya kadar hayran kalırdım doğruluğuna

anlık öfkesi tüterdi ve duyardım

iyi bir parça aydınlık, 

prensipleriyle o yeniden başlasaydı eğer

...

daha fazlası da olamazdı

Çeviren Meral Vurgun', 'Meinem Vater ich hätte meinen Vater gerne als jungen Mann erlebt er erzählt nicht viel von sich aber einige Prinzipien wiederholt er ständig...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/babama-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Barıştır', 'ask-baristir-suna-aras-4njyk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk suçsa

Ben bütün suçları üstüme alıyorum

Hadi can “can cana”

Aşkın en güzel suçuna.

Bir dilim gökyüzü duruyor masada

İşte tam da yanında

Senden beni yaratan bir dünya daha

Ellerimi bulayıp oraya

Resmini çiziyorum

Biraz ötende duran

Ay dede yalnızlığıma.

Tam da o anda

Ya bir yıldız kümesi

Serçe sürüsü ya da

Bir çığlık bırakıp gidiyor ikimizin arasına

Ve ben düşüyorum sisler içinde sen

Yüreğimin ortasına.

Keşke bir ad bulabilseydim

Seni seviyorumlara

Yaşam denebilir mi acaba? 

Ya da

Bir buğday tarlası olmak Küba’da

Ve gündoğumu Nemrut’ta

İlk doğanın yansıması bakışlara

Ah o deli sevinç

Bir çocuğun ilk adımı hayata

Korkusuz koşabilmek sana

Dünya barışına imza

Koyabilecekmişim gibi bir aşkla.

Elimden tuttuğun an beni

Aşklar kavuşmak olsa

Tohum sen toprağı ben

Yeni bir dünya işte

AŞK…

Barışı ikimizden.', 'Aşk suçsa Ben bütün suçları üstüme alıyorum Hadi can “can cana” Aşkın en güzel suçuna. Bir dilim gökyüzü duruyor masada İşte tam da yanında ...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ask-baristir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paranoya', 'paranoya-mehmet-ferhat-bir-i63wh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'paranoyaların sonu yok 

sınırsız beslenen 

düşlerle 

atardamarları yalnızlığın

acaba noktalarında nöbet bekleyen

paranoya

kurumuş kaynaklarda

nöbet tutmak mı? 

yalnız başına

yılkı atlarını düşünür oldum

ulu çayırların kıyılarında

ardımda çöl gibi

yalnızlık bırakmış geliyorum

aş değil istediğim su değil

dudak izlerim kaldı

dalgalı kıyılarda

vahalarda ümitsiz kaynaklarda

nöbetlerde kaldı bakışlarım

kumul ufuklarda

vaha suları doldurdum

gözyaşımın yerine

vahalar kurudu kaldı

sen gelince yalnızlığım yalnız kaldı

yılkı atlarını düşünür oldum

çayır başlarında

bir adım sonra sen

ardımda bedevi yalnızlık çadırları

S harfleri bıraktım

çöl üstünde

altında sahipsiz hayatlar

kumullar aştım

kum kadar çok

paranoyalarımı bıraktım

bıraktım gözyaşlarımla birlikte

bir ayağımda çayır serinliğin

bir ayağım çöl yalnızlığımda

(13.04.1998)', 'paranoyaların sonu yok  sınırsız beslenen  düşlerle  atardamarları yalnızlığın acaba noktalarında nöbet bekleyen paranoya kurumuş kaynaklard...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ferhat Bir']::text[], 8.5, '{"poet":"Mehmet Ferhat Bir","poet_slug":"mehmet-ferhat-bir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/paranoya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtirafımdır Emel Bu Sana Anlatılmayanlarıyla...', 'i-tirafimdir-emel-bu-sana-anlatilmayanlariyla-ali-baksi-aihlm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kızmıyorum artık kimselere 

Sevinçleri seçtim yokluğunda bilsinler 

Damlalarla aksın göz yaşlarım sel olsun yarınki umutlarımda

Varsın gitsin söylesinler sana bana yarınların yokluğunu umutsuzluğunu 

Yaşanmışlarım var yaşanacaklarımla üst üste koyuyorum

Ben bu dünyanın parçasıyım seninle olsamda olmasamda kalbimle

İcimde var olan senle olan düşler sakağında yalnız değiliz 

Ben bir elmanın yarısıyım kendi sokağımda parçalama ne olur

Düşlerim var ömrümün ta sonunda kol kola yıllarca dualarla

Yürüyorum sıkışmış dar kaldırımlarda senle olan duygularımla

Ne olur sorma sakın bakışlarımı çok aradım yıllarca

Dönüyor dünyam baş ucumda gene sen varsın iyiki varsın

Söyleyemem sevdiğimi sevgi değil benimkisi aşka yakın ötesi

Dinle benim avuntumdur sana esen rüzgara söyledim şarkımı

Senin içindi bu sözlerim özlerinde bizim içindir çalan şarkıların

Buraya bahar erken gelir açan çiçeklerdir sendeki buse buram buram

Kar gibi düşlerimiz var hayellerimizde pırıl pırıl saflığımızda

Buralarda gök kuşağıyım göcebe  yıllar sonra gideceğim ruhumla

Ardımda bıraktığım ben ve benliğimde sen olacaksın 

Bırakmalıyız iyiliğin ötesinde mutluğumuzu coçuklarımıza

Miras değil yaşanabilir güzel bir dünya bırakmak arda

Ayna değilim parlayamam portre bir dünya bakarsan

Gözlerimde umudu ve yarınları görürsün istersen

Gecmişle vedalaştım helalleştim kimseye kızmıyorum

Yürüyorum arda bıraktığım anılarımla yarınlarımıza

Hatırlarız geçmişin arda bıraktığı elma parçalarını

Belki geç olur paylaşmanın değerini bilmenin gecesi

Ama en sonunda huzuru bulmaktır yaşamın ötesi

Yarın yeniden güneş doğacak o gün bizim için aydınlanacak 

Sevgi değil aşktır artık buradan ötesi…', 'Kızmıyorum artık kimselere  Sevinçleri seçtim yokluğunda bilsinler  Damlalarla aksın göz yaşlarım sel olsun yarınki umutlarımda Varsın gitsi...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/itirafimdir-emel-bu-sana-anlatilmayanlariyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimler', 'resimler-mehmet-ferhat-bir-l5sx8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'zaman gene adil davranmadı bu yaz

zor kalktım üstüme yuvarlanan yalnızlığımdan

saatler seninle geçerken beynimde

yeraltımda

ve güneş tam tepedeyken

bana kalan zamanların sensizliğiyle uyandım

resimler geçti zihnimin kuyularında

ak tuvale sarılı cesedim

saat adımlarıyla geçti önümden

bir başka hayale ait

kaşmir ceket giyen bedenimdi taşıyan

ölümü

ahirkapı açıklarında yüzerken gördüm

cesedimi

sırtımda bir kılıç balığı

ellerimde şeffaf nü tuvaller

ağzımda ritüeller ritüeller

trolle avlanan bir balıkçı çekti kayığına

bir gazeteci makinesine

hamur sayfalar üzerinde boyandı cesedim

baskıda çıktı ortaya

işkence izlerim

kurtarılmış bölgeler yarattım kaderimde

rüyalarımda sala dinleyip

göz kapaklarım aynada inerken secdeye

(28.04.1998)', 'zaman gene adil davranmadı bu yaz zor kalktım üstüme yuvarlanan yalnızlığımdan saatler seninle geçerken beynimde yeraltımda ve güneş tam tep...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ferhat Bir']::text[], 8.5, '{"poet":"Mehmet Ferhat Bir","poet_slug":"mehmet-ferhat-bir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/resimler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim olacak', 'benim-olacak-mikdat-bal-wkh7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürü dünya dön dünya

Sana sevgim son dünya

Senin gibi on dünya

En az benim olacak

Senden bıktım diyorum

Bırakıp gidiyorum

Seni terkediyorum

Bu naz benim olacak

Ben seni boşuyorum

Menzile koşuyorum

Bir umut taşıyorum

Niyaz benim olacak

Seni sevmek pişmanlık

Bu dünya da sultanlık

Verilse de bir anlık

Biraz benim olacak

Yıllar gün gibi geçti

Beni ayakta biçti

Kazandığım bir hiçti

Ayaz benim olacak

İstersen unut beni

İster isen yut beni

Bağrında uyut beni

Son gaz benim olacak

Dürülmüştür sahifen

Yok senin ağan, efen

Kara bağrında kefen

Beyaz benim olacak

Bal der bitti savaşım

Ahirettir telaşım

Hayırlı bir ulaşım

Feyyaz benim olacak', 'Yürü dünya dön dünya Sana sevgim son dünya Senin gibi on dünya En az benim olacak Senden bıktım diyorum Bırakıp gidiyorum Seni terkediyorum ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/benim-olacak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevzuat', 'mevzuat-gultekin-mustafa-owkop', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rengin avuntusu ve bir yelpaze serinliği

Daha ne ister insan, zaten kaybetmiş derinliği

Derinliği de biz yaratmadık mı

Saçma savruk dünyada; 

Saçma salak diyaloglarda böyle kelimeleri şımartmadık mı? 

Bu mevzular hiç yoktu ben doğarken

Yalnızken yaşarmış oysa insan, tam ufaktan keyfi yokken

Zamanını iyi bellemek lazım şiir yazmanın,uyku da var...

Ha pardon ben daha doğmadım,

Mecaza yüklenen bir marazım

Doğum günümü iptal ettim,

Her temmuz yeniden doğmam lazım.', 'Rengin avuntusu ve bir yelpaze serinliği Daha ne ister insan, zaten kaybetmiş derinliği Derinliği de biz yaratmadık mı Saçma savruk dünyada;...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mevzuat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalana Adalet Yok mu?', 'kalana-adalet-yok-mu-gultekin-mustafa-b4muf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalanlara hiç acıma yok mu? 

Bir terslik var bu işlerde ulu manitu! 

Gidene de dur denmiyor heyhat! 

Ve fakat kalanın günahı nedir? 

Kalana kalın geliyor gidenin acısı.

Avutmazlıklardan avutmazlık beğen işin yoksa.

Gidecek olan belli etsin kardeşim! 

Aniden olunca kötü oluyoz buralarda! 

Ahanda vakit böbrek sancısı.', 'Kalanlara hiç acıma yok mu?  Bir terslik var bu işlerde ulu manitu!  Gidene de dur denmiyor heyhat!  Ve fakat kalanın günahı nedir?  Kalana ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalana-adalet-yok-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mine Çiçeği', 'mine-cicegi-nesrin-gocmen-puxd0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir peri yarattın, gönül selinde, 

Neler çektin neler, yaban elinde. 

Yanarak yoruldun, kahrın çölünde, 

Gülümse yaşama, Mine Çiçeği... 

* 

Işıklar yanıyor, pencerelerde, 

Anılar kaynıyor, tencerelerde, 

Arkadaşın, dostun acaba nerde? 

Gülümse yaşama, Mine Çiçeği... 

* 

Umudu kopartıp, hüzünde pişme, 

Baharı bırakıp, hazana düşme, 

Bugünü karartıp, yarına şaşma, 

Gülümse yaşama, Mine Çiçeği. 

* 

Kırkıncı yılında, zaman karardı, 

Yaşanan her anın, varılmaz yardı. 

Bu akşam yanında, olsam ne vardı? 

Candostum, sırdaşım Mine Çiçeği.... 

. 

10/08/2005', 'Bir peri yarattın, gönül selinde,  Neler çektin neler, yaban elinde.  Yanarak yoruldun, kahrın çölünde,  Gülümse yaşama, Mine Çiçeği...  *  ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mine-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıklık', 'kiriklik-gokhan-oflazoglu-9xr1a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her zaman bir kırıklık

olarak kalır yaşam.

Tadı burdan damıtırız.

En derinimizden kopan

liflere tutunup sallanırız 

çocuklar gibi. Burukluğumuzla

ayakta kaldığımız, zaferimiz.

Karmakarış hayat bir bir

çözülür, berraklaşır su.

Elimizde kalan hiçtir.

Biz bu suyu içeriz.

10/08/2005', 'Her zaman bir kırıklık olarak kalır yaşam. Tadı burdan damıtırız. En derinimizden kopan liflere tutunup sallanırız  çocuklar gibi. Burukluğu...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiriklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yücelerde Horon', 'yucelerde-horon-nevzat-erkol-p0wkj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuzey dağları set çektiğinde

Yıldıza, karayele,

Kaçkarlar’ dan kaç kar

Kaç bahar

Boran

Yel, sel geçti

Fırtına vadisinden.

Kaç kez kesildi insan ayağı

Kaçkarlar’ ın eteğinden

Kim bilir.

İnsanoğlunu çağırdı

Göz etti yücelerden,

El etti durdu

Zamanın içlerinden

Çağların ötesinden.

Kutsal bir tutku gibi

Yürüdü uşakları,

Arhavi’ den, Çayeli’ den

Hemşin’ den.

* * *

Dorukları sis bürürdü

Yollarını ses, seda

Süreğen türkülerdi ağan

Kemençe telinde esriyip,

Fırtına deresinden.

Yaylalar dostluğa yurt oldu,

Horona sevdalı insanı

Kadınından, erkeğinden,

Kuşa kurda dost oldu.

* * *

Akşamın serinidir

Rüzgârın faslı başlar,

Yeşil siyaha dönerken 

Gece dallarla rakseder.

Dolunay bakar yüceden

Ağustosta bir geceden

Ayder’e selâm eder.

Çağlayanlar köpük-revan

Nazlı bir gelin tülüdür,

Salınır iner Kaçkar’ ın 

Terlemiş perçeminden.

* * *

Sıcak bir yayla evinde

İnsanla doğa iç içe; 

Baba Mehmet

Anne Kader

Ve Ayder’ in şirin kızı

Küçük Güneyce.

Ey doğa tutkunları

Dağlara vurulmuşlar,

Biz yolcuyuz bu gece.

Hoşça kalın can dostlar

Çıkageliriz bir gün

İmbatlarla Ege’ den,

Sessizce ve gizlice.

01.09.1999', 'Kuzey dağları set çektiğinde Yıldıza, karayele, Kaçkarlar’ dan kaç kar Kaç bahar Boran Yel, sel geçti Fırtına vadisinden. Kaç kez kesildi in...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Erkol']::text[], 8.5, '{"poet":"Nevzat Erkol","poet_slug":"nevzat-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/yucelerde-horon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala Yürümediğim Yollar Var Aklımda...', 'hala-yurumedigim-yollar-var-aklimda-ertan-akbayrak-zqo0d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hala yürümediğim yollar var aklımda

Sana ait kalmış umutlar ardımda

Ne bugündür yaşadığım ne de dün,yarınlar yürür sevgisiz Akşamlarımın aynasında...

Ve şimdi yürüyorum yarım bıraktığın o yolda

bir o yana bir bu yana...! 

Seslenirken ölüyorum, sana...

Görmüyormusun,aşk yoksulu...! duysana...

Gergin...zayıf bir ip ellerimin arasında...

Avuçlarım hala korkak aşkların telaşında

ne sen kaldın yarınlarımın soğuk baharlarında

ne umut... Eylül yine bedbaht bir kadın telaşında...

Sor bakalım şimdi,geriye kalan yaşanmışlıklara...

neler söyler,neler fısıldar sana...

kanma sakın...sanma...sen, sen ol aldanma...

DÖNÜŞÜ YOK O YOLUN,HADİ SEVGİLİ,YARINLARA...!', 'Hala yürümediğim yollar var aklımda Sana ait kalmış umutlar ardımda Ne bugündür yaşadığım ne de dün,yarınlar yürür sevgisiz Akşamlarımın ayn...', ARRAY['Türk Edebiyatı','Şiir','Ertan Akbayrak']::text[], 8.5, '{"poet":"Ertan Akbayrak","poet_slug":"ertan-akbayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hala-yurumedigim-yollar-var-aklimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-mensuri-tas-py55u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir nasihat versem kıssadan hisse

Önce kendi nefsim sonra herkese

Tedbirin al kalma yağmura sise

Çamur deryasına dalarsan olmaz

Fakirin cebinde soysuzun eli 

Çok büyüktür elbet bunun vebali

Beslenip sevilen karga misali

Sahibin gözünü oyarsan olmaz

Muhabbeti hoşgörüyü silerek

Her gün yeni bir oyuna gelerek

Bu benden şu senden yana diyerek

Vatanı milleti bölersen olmaz

Kendini uzak tut ah ile vah tan

Kurtar bedenini şirkten günahtan

''Rabbena''hep bana deyip ALLAH''tan 

Herşeyi kendine dilersen olmaz

Anneni babanı dostunu dinle 

Düşmanında gelse karşıla gülle 

Düşüp kalkmayasın kara cahille 

Başını belaya sokarsan olmaz

Sevgi bayrağını en önde taşı

Fakir ile bölüş ekmeği aşı

Zulme uğrayanlar dökerken yaşı

Bıyığın altından gülersen olmaz

Unutma ALLAH’ın aciz kulusun

Kulluğun yapmazsan ceza bulursun

Hemde yalancının mumu olsursun

Yatsıya varmadan sönersen olmaz

Aldanıp vazgeçme kendi özünden 

Ateşe yanarsın elin yüzünden 

Mensuri hele sen kendi sözünden

Bahane arayıp dönersen olmaz

                   07.05.2004', 'Bir nasihat versem kıssadan hisse Önce kendi nefsim sonra herkese Tedbirin al kalma yağmura sise Çamur deryasına dalarsan olmaz Fakirin cebi...', ARRAY['Türk Edebiyatı','Şiir','Mensuri Taş']::text[], 8.5, '{"poet":"Mensuri Taş","poet_slug":"mensuri-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/nasihat-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkediş', 'terkedis-mensuri-tas-ay6g6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Terkedip giderken arkana bakıp

Sevgili yarine acımadın mı? 

Benim düşmanımı koluna takıp

Yüzüme bakmaya utanmadın mı? 

Hatırlarsan bunu sen istemiştin 

Senden başkasına bakmam demiştin

Daha ben ölmeden mezarım eştin

Gençliğime kıydın utanmadın mı? 

Nasıl unutursun nasıl sen beni 

Kalbime çizmiştimsenin resmini

Dilime yazmıştım güzel ismini

O güzel isminden utanmadın mı? 

                           16.05.1975', 'Terkedip giderken arkana bakıp Sevgili yarine acımadın mı?  Benim düşmanımı koluna takıp Yüzüme bakmaya utanmadın mı?  Hatırlarsan bunu sen ...', ARRAY['Türk Edebiyatı','Şiir','Mensuri Taş']::text[], 8.5, '{"poet":"Mensuri Taş","poet_slug":"mensuri-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/terkedis-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk destanı', 'ask-destani-fatih-gundogdu-qhco7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle tanıdım ben aşkı sevdayı

Fakat geç kalmışım ben ölüyorum.

Yıkardım aşkından yalan dünyayı

Fakat geç kalmışım ben ölüyorum

Sana zaafım vardı ta en başından

Yanağındaki gamzeden, hilal kaşından

Ağlamam gerekirken senin aşkından

Aklımı yitirdim; ben gülüyorum

Geceye yıldızsın, güneş gündüze

Güzelliğin getirir alemi dize

Görünme ellere gelirsin göze

Seni kıskanırlar, ben biliyorum.

Suçlumuyum seni bunca sevdim diye

Söyle bana sevdiğim bunca naz niye

Gün olur da benim olursun diye

Allah''tan her seher ben diliyorum

''Zamane''yim senden yaşanmaz ayrı

Yetsin artık sevdiğim bu hasret gayrı

Duyduğun şu garibin sesine doğru

Ya sen gel, ya da ben geliyorum.', 'Seninle tanıdım ben aşkı sevdayı Fakat geç kalmışım ben ölüyorum. Yıkardım aşkından yalan dünyayı Fakat geç kalmışım ben ölüyorum Sana zaafı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Gündoğdu']::text[], 8.5, '{"poet":"Fatih Gündoğdu","poet_slug":"fatih-gundogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgiliye-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-elazigli-mustafa-kaya-x5d6l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmur yağıyordu.

suya vuran soğuk

gökyüzünden içime işliyor.

bulutların gri öfkesi,

maviye düşüyor.

ve ben bu ıslak demde

yapayalnızım bu şehirde..

balıkların çığlıklarına karışıyor nefesim.

ve taş binalardan sarkan hüzün,

modernitenin acımasızlığı.

yalıların direnişi sürüyor

üst üste taş yığını şehir,

denizi hançerliyor. 

ağaçlara güz vurmuş.

rıhtımı döven lodos çağırıyor

ruhum hıçkırıklarla dolu

ve istanbul üşüyor...ben  üşüyorum....

                                                             mustafa kaya / istanbul

                                                             09.07.2004', 'yağmur yağıyordu. suya vuran soğuk gökyüzünden içime işliyor. bulutların gri öfkesi, maviye düşüyor. ve ben bu ıslak demde yapayalnızım bu ş...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/usuyorum-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessüm', 'tebessum-elazigli-mustafa-kaya-efccz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşadığım şehir mavi bir kumaş.

yeşilden maviye akan bir derinlik.

boğazın dantel kıyıları gülümser

benimse ruhum kanıyor,

demirden yokuşlarda..

içimde ki korku,

alıp sevdasını insanın uzaklaşan gemiler.

gözleri kara sevgilim

uzun kara saçlarını tut

poyraz esecek bu akşam

ellerimi tutacak karanlık

yıldızsız gökyüzü kaderim.

bir gemi geçiyor

aklım gidiyor,

alacak düşlerimden seni.

istanbul

bir siyah dantel gece

bir ömre bedel sevgiler nerede..? 

ve yalnızlığımı çekiyor bir balıkçı teknesi

katrana dönüşen mavide

yakamozlar tutuyor beni.

bir tebessümüne hasret kaldım

bin derde düştüm

mehtap gülecek sen düşersen geceme

bir tebessümüne....

                                                                     09..08.2005 / istanbul

                                                                     mustafa kaya', 'yaşadığım şehir mavi bir kumaş. yeşilden maviye akan bir derinlik. boğazın dantel kıyıları gülümser benimse ruhum kanıyor, demirden yokuşlar...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tebessum-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerekçesi Mavi-II', 'gerekcesi-mavi-ii-ugur-deniz-ulkegul-svu70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-I-

İçerde acı tarhana kokusu

Akşam vakti yemek telaşı

Ve şehrin

Sokaktan gelen garip uğultusu…

Beyaz gömleğimi bulamadım dolapta

Bir de Pantolonum kahverengi olan

Oysa biliyorum söylemişti anam; 

Ütüledim koydum

Ne bu acelen, de bakalım deli oğlan? 

-II-

Yürüsem gökkuşağının üstüne

Buluttan bir tutam mavi koparsam

Silsem kan rengi sancıları içinden

Umudu yeni baştan boyasam…

Sonra bir memleket türküsü söylesem

Sazım kırılmasa, kopmasa bam telim

Sürgüne vurulmasam, hani ölmesem

Yarım kalmasa bir de, söylediklerim...

Düne yazılmış mektupları alsam

Geç kalmış sözleri, eskimiş özlemleri

Yarına postalasam…

Bir çocuğun ellerine tutuştursam

Yüreğimde saklı duran tebessümleri

Sana yollasam…

Çocuk ölmese

Tetik düşmese

Namlu doğrulmasa…

Bir annenin feryadına

Karışmasa sessizliğim

Düşlerim kanamasa…



-III-

Bir şiir yazdım

İçinde ben vardım, ellerin vardı…

Katline ferman konmuştu sözün

Sus vakti dolar gözlerin, ağlardı…

Göçmen kuş mevsimiydi

Umuda kanat çırpardı yüreğimiz

Buz keserdi korkular,

Birbirine değince tenimiz, yanardı…

Ben bu aşk’ta firarım güzel

Dilimde Fail-i meçhul gazel

Bir seher vakti sürgüne vuruldum…

Tutanaklarda sorgulandı gençliğim

Eylül pazarında satıldı çocukluğum…

Yüzümde senden kalma tebessüm

Yaylım ateşine tutulurken düşlerim

Bir dağ yamacında unutuldum….

-IV-

İçerde acı tarhana kokusu

Bir kardeşimin sesi yok ortalıkta

Bir de anamın o tatlı gülümsemesi…

Mustafa geldi az önce

Oysa koşar sarılırdı beni görünce

Seslendim, kimse duymuyor, neden? 

Tam iki saat oldu orada,

Babam ayırmıyor gözlerini pencereden..

-V-

Yürüsem gökkuşağının üstüne

Buluttan bir tutam mavi koparsam

Silsem kan rengi sancıları içinden

Umudu yeni baştan boyasam…

Balık olsam yüzsem denizde

Kuş olsam kanat çırpsam

Gerekçesi mavi düşler kursam

Bahçenizde…

Şimdi kan rengi anılarım

Utanıyor kendinden insanlığım

Dolaşırken içinizde…', '-I- İçerde acı tarhana kokusu Akşam vakti yemek telaşı Ve şehrin Sokaktan gelen garip uğultusu… Beyaz gömleğimi bulamadım dolapta Bir de Pan...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/gerekcesi-mavi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Sözcükler', 'kirik-sozcukler-ozan-ozel-utnww', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir düşüşün ardından

sesim kırıldı 

sözcüklerim

seni seviyorum deyişim kırık

ki o yüzdendir

sana olan aşkımı

gözlerimle anlatışım

böyle doyumsızca bakışım...', 'bir düşüşün ardından sesim kırıldı  sözcüklerim seni seviyorum deyişim kırık ki o yüzdendir sana olan aşkımı gözlerimle anlatışım böyle doyu...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kirik-sozcukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-gorkem-kaya-n3ag9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlemek

herşeyi özlemek

Susadın mı 

kana

kana

su içmeli

Çişin geldiği zaman

kime ne? 

Duvarlara işe

ya da bir incir ağacı bul şehirde

sulanacak

Acıktın mı 

tıka

basa

yemek ye

Canın sevişmek mi çekti

halının üzerinde 

sere 

serpe

Uyumak mı geçti içinden

aldırma 

yüzünü okşayan güne

gerin

ha

gerin 

incecik pikenin içinde

Rakıysa aklına düşen

kur sofranı

bul kadehine bir eş

Yağmur mu yağıyor yazın

fırla sokağa 

yalın ayak

bir türkü bula dudağına

ister

çökertmeden çık

ister

Çanakkale içinde dolaş

Şiir mi yazasın 

var

ver 

sırtını Galata Kulesi’ne

yaz

ha

yaz

sonra

yırt yazdıklarına inat

Aylaklık güzel meslek

vallahi

bir de olmasa 

sevmek,

sevilmek

Hadi şimdi bul bakalım 

bulabilirsen

seni

özlediklerinle sevecek

Senin 

özledikleriyle seveceğin

bir aylak.........

....................

Hişt sen! 

Özledim seni

hadi 

gel yine bize,

özlediklerinle...

...................

Adam özetledi hayatı

“Yaa hayat bu işte”

 Özlemek işte bu...



(Bir İstanbul gecesinde yaşamın özetini özlemekle anlatan adama..)', 'Özlemek herşeyi özlemek Susadın mı  kana kana su içmeli Çişin geldiği zaman kime ne?  Duvarlara işe ya da bir incir ağacı bul şehirde sulana...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/yasamak-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyan', 'papatyan-hulya-arikan-vxic6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben 

Beyaz, narin papatyan

Her bir yaprağıma düşlerimi yazıp sundum sana

Belki gelirsin diye

Umutla boy verdim her doğan günde

Süzülen kartalda bakışlarını gördüm

Avundum...

Deli rüzgar nefesin diye

Soludum...

Başımda bekleyen çılgın bulut...sendin

Üzerime düşen her damlanda hayat buldum, büyüdüm

Üşüdüm de...Sensiz inen gecede

Kapattım düş kokan yaprağımı yanlızlıkta

Soluktu yarına hayallerim

Yinede umuda dönük yüzüm

Seni bekledim...

Ellerini bekledim...Sararsın diye

Bak zamansız kışa döndü baharım

Doruklarda çetin geçer bu mevsim

Hani tutunacak toprağımda kalmadı sarp kayalıkta

Yıllara meydan okuyan cılız bedenim düşüyor

görüyormusun...

Sadeliğimi gizleyen beyazım soluyor

Gelecekmisin...

Sevdanı yazdığın sayfalarının koynunda

Düş kokan

Umut kokan

Aşk kokan

Kurumuş papatyanı saklarmısın...

25/04/2005

İstanbul', 'Ben  Beyaz, narin papatyan Her bir yaprağıma düşlerimi yazıp sundum sana Belki gelirsin diye Umutla boy verdim her doğan günde Süzülen karta...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arıkan']::text[], 8.5, '{"poet":"Hülya Arıkan","poet_slug":"hulya-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/papatyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Güneş', 'esmer-gunes-gulsen-gonenc-j4bfq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ansızın kopan umarsızlık fırtınası,

Yalancı güneşin habercisi.

Yalancı güneş, esmer güneş; 

''Hayır! ''larla ışığı emen,

İçten içe eriten.

Aşk insanı korur mu?', 'Ansızın kopan umarsızlık fırtınası, Yalancı güneşin habercisi. Yalancı güneş, esmer güneş;  ''Hayır! ''larla ışığı emen, İçten içe eriten. Aşk...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/esmer-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı', 'sari-gulsen-gonenc-qf8ao', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim demiş aşkın rengi kırmızı? 

Benim aşkım sarı.

Sonbaharda düşmüş yaprak gibi,

Çatlak ressamın buhran tablosu gibi,

Yolcu alıp indiren taksi gibi,

Kendi içinde patlamaları olan Güneş gibi.

Açık sarı

Koyu sarı

Ama hep sarı.', 'Kim demiş aşkın rengi kırmızı?  Benim aşkım sarı. Sonbaharda düşmüş yaprak gibi, Çatlak ressamın buhran tablosu gibi, Yolcu alıp indiren tak...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sari-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Saati', 'ask-saati-tulay-sustam-5jxoo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu yürek sana kurulu

ne zaman sorsalar

ya -seni ben- geçiyor

yada -bana sen- var

bu yürek sana kurulu

o yüzden peşinde ki akrebim

yokluğunda her saliseye zehirim akıyor

aşk saati sensiz çaldı, zaman durdu', 'bu yürek sana kurulu ne zaman sorsalar ya -seni ben- geçiyor yada -bana sen- var bu yürek sana kurulu o yüzden peşinde ki akrebim yokluğunda...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manile 3', 'manile-3-mehmet-isikoglu-v1zvu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sözler size ey ozanlar 

Nerde kaldı söz erleri

Sohbetleri özler canlar 

Haykırıyor birileri 

İrtibatta yarar var 

Sevgilerde karar var 

Selam olsun dostlara 

Kalbimizde sürur var

Sesinizi duymak gerek 

Geleneğe uymak gerek 

Meydanlara bekliyorum 

Atışmaya doymak gerek

10.08.05', 'Sözler size ey ozanlar  Nerde kaldı söz erleri Sohbetleri özler canlar  Haykırıyor birileri  İrtibatta yarar var  Sevgilerde karar var  Sela...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/manile-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir İstanbul Yeter', 'bana-bir-i-stanbul-yeter-yavuz-bayram-caliskan-lj2e7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana aşıklığımdan memnun musun? 

Bakışlarımdan, umudumdan,

Seni yangınlarla sardığımdan,

Uçuverirsin diye konuşamam,

Gözlerimin dilini anlasana.

Ne sevi dolu bir yol, deniz ve boğaz

Hisardan süzülen ışıklar ve saçların,

İçimiz yanacak gibi bir his var.

Gözlerimi aleve diktim, 

Ateşlere çıplak yürek yürüdüm

Galiba bu aşk şarabından ki kadehler içilecek.

Tekneler savda yolunu yaran tekneler.

Esirinim oldum, bir dokunuş canımı alır,

Düş kırıklığı, gurur incinmesi, çaresiz düşler,

Hepsine gözlerimi kapıyorum.

Beni hissettin mi acaba? 

Sıradan bir gün değil, sıradan bir bakış hiç değil,

Yakamozların yansımaları nasıl olacak? 

Kaçış olanaksız, alev alevim,

Kapıyı kim çalıyor? Heyecanlar.

Her şeye yetişmek beni yormuyor,

Hayatı yeşertmek, seninle yaşamak,

Denizi dinlemek ve yosunlarla seni içime çekebilmek,

Bir damla mutluluk yüreğimde, hissettim.

İlk kez ve gerçekten.

Senin buğulu gözlerin en güzel değerin.

O günü nasıl unutabilirim,

Saçların dağınık, rüzgarda,

Bir hayal girdi kapıdan,

Alın yazım yırtıldı,

Tek umdum gözlerin bunu böyle bilesin.

Güneş batmasın ki umdum aydınlık kalsın.

Neredeydin şimdiye kadar? 

Ama bir güzel canına okudun yüreğimin.

Ben yalnız kalamam kardelen çiçeğim,

Güzel ve narin bakıyorsun,

Tenindeki ateşleri ciğerime atıyorsun,

Bu ummandan aşk ve sevgiyi doldururum,

Ama denizlere bir batıp bir çıkıyorsun.

Geri döndüremem gemileri,

Güzelliğini aya atsan peşinden koşarım.

Serpildiğini hiç mi fark etmedin çöllere.

Sularından çıkmak aklıma bile gelmiyor,

Yarınlarını tümüyle fethetmeye karalıyım.

Ellerimin arasından akıp gidiyor saçların,

Her şeyleri istiyor canım, zirvedeki karı bile.

Dolu dolu aşkları yaşa, sen doymazsın,

Ama bana bir İstanbul yeter.', 'Sana aşıklığımdan memnun musun?  Bakışlarımdan, umudumdan, Seni yangınlarla sardığımdan, Uçuverirsin diye konuşamam, Gözlerimin dilini anlas...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bana-bir-istanbul-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metafor, durağan: Bir rotasyon - Felsefi denemede deneysel şiir karalaması', 'metafor-duragan-bir-rotasyon-felsefi-denemede-deneysel-siir-karalamasi-akin-akca-u899n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şeyi önceden biliyorduk, şimdi sadece hatırlıyoruz -Platon

_

Gidebilen şey öç göçleridir hep, gidebiliyorsa -korku savştırmak, karmaştırmak 

için: Adrenalindir o! 

- hep o daha bir katar geri dönüşlerdir ve bunun karekökü ise.

Sezgi, hayat için ileri atılımıysa düzülen essai’lerin yaşama

ve bir ibreysek bu sezgi tepkini ortaya koyduğun

ve öte yanda değişmezler’in asıl kendi, bilmek olduğunda; 

dönüşmeyenleri bulmak yeniden, kopya etmek de olmayacaktır.

Asıl kopya sezgilerin ile yetinmektir, karanlığın hakimiyetine direnmek.

Bir gömlek daha üstü denemelerdir, yaratıcı olan ve bir sonuca ulaşma kılıfı için de fazla sığ …

Dolaşır devamlı, evet durakları vardır, ama hep nefes alır.

Bunların ötesinde, bilmek, sezgi, yaratıcılık ve yaşamda denemeler, hepsi de iç içedirler.

Bir bütün halinde, onlar; hayatın kendisidirler.

İmgeler giriyor işin içine, çünkü ayna benzetmeler 

sıra dışı biçimde işlerliğini yitiriyor; mecaz var, akisler yok.

Bilmek buysa, nerden geldiğimizin bir kaç önemi hak; 

gibi, gibi’yi burada kullanabiliriz sanki …

Ve/ tabi üç nokta’yı …

Ama nereye gittiğimizin önemi var, amaç önemli; 

o tek nokta, sadece paylaşılan mutluluk adına.

demiştik ya ama paylaşım değildir ‘gibi’ lafı benzetmesi,

sadece mecazlamalardır ve (bu)   paylaşımsa

sezgiyle iç güdü ya da dürtünün toplamı

veya birbirinden çıkarılmasının bunların, bilmek.

*

Edilgen olmayan sevgi, toplayıcılıkla geçinmiyor.

Bu yüzden kaçınılmaz bir biçimde doğaçlama içgüdü dışa vuruyor 

kendini ve uyaranı’nı almıyor gün ışığının! 

Gerçeklik arayıp, bulup toplamıyor ve sanki bir gizem! 

Ama ‘deneyleme yok’ o ‘bir kerede oldu bitti sezgi’:

içgüdüsel de değilmiş ki; değil edilgen, başlı başı etken! 

Bilmek var oluyor gibi bu noktada, bir kerelik bir 

algılayış karmaşası, ‘Rimbaud kaosyenleri’ olan tuhaflığın ve

gerçekleri umursamaksızın beliriveren ortaya ‘sezgi’

ile ‘içgüdü’; içinden doğru sezgi’nin, dış dünyadan bilgi aşırıcı..

İki örgü süresiz birleştiğinde ya da birbirinden ayrıştığında.

Yine de akla doluşmakta olan çılgınca bir fikre göre:

artık kadın başladı çırpınmaya, sözde aile özgürlemeye -

pinek ‘haset cee sine leyerek’, 

tahta sert yapısından yumuşacık insan yüreğinin; 

pit pinti, Pinokyo eğlence parkında, şıralar ağaçlardan..

- pineklemeye, erkek; öncesi de var! 

:Bunu öngörmüş ise Tesla, son vermeli o bir şeye de! ! 

Neye? sarf bilmek eyleminin sonuçlara götürüşlerine; 

insanın yani, bunlardan alıkonulma olasılıklarına:

Bazen üç nokta değil, nokta yeğ; virgül söz konusu değilse.

Ancak değil şu demek de; varılacak bu, hepsi mutluluk.

*

Korkma! 

ölünce de kalır enerji, görkemli asaleti zerafetinin aşkın sevgisinin! 

Susmak bilmediğince, tahterevalli bebek beşiği; 

yukarı ışıtılan selvinin zerkedilip toprak altından; toprak altından

fırlayan eller itişerek -oracığı kazar, kızışarak

- dallarını kırdığında kıkırdayıveripe, sallayıp o tüm gövdeyi kök hücrelerinden! ! 

Bu bir gidiş, çevrim; şer kötücül çoğul yığınlarını tığ

içinden ayıkladıkça yeni doğmuş bebeğe senfonik kostüm,

bir habis bakteriye, seçmek kolay ve tosun-tek ışıldatmak yine! 

Kimbilir, belki de çok fazla bilmeni istediğim için

felsefeye düzenli eğilebildim ve istemeni dilediğim; 

kalman, gitmemen; insan tarafım ağır hala sanırım.

-

Essai (Montaigne’ce) : essay=deneme

Karmaştırmak=savştırmak=savuşturmak

Kaosyen lafı Arthur Rimbaud tarzı bir kelime (alıntı)

Metafor: birseyin sembolik olarak baska birseye benzetilmesi ama bu yapilirken ''gibi'' lafinin kullanilmamasi. bkz: mecaz)

Rotasyon: dönme eylemi. yerkure gibi herhangi bir cismin kendi ekseni etrafinda donmesi

eksisozluk', 'Her şeyi önceden biliyorduk, şimdi sadece hatırlıyoruz -Platon _ Gidebilen şey öç göçleridir hep, gidebiliyorsa -korku savştırmak, karmaştır...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/metafor-duragan-bir-rotasyon-felsefi-denemede-deneysel-siir-karalamasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerini Uzattın (89)', 'ellerini-uzattin-89-i-brahim-arslan-87u2i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ellerini uzattın,

dokunamadım ellerine

kaç zaman,

dayandım hasretine...

hasret kaldım..

resmine bakarak

gün tamamladım

her sigaramda

seni çektim içime

kayboldu hayalin

bu gece

ellerini uzattın,

dokunamadım ellerine....

sesin geldi,

sevdiğini söyledin,

dön dedin,dön! 

sana dönemedim...

bana bakma sen,

benim bitmez hiç hasretliğim

hayalinle yıllar yılı

yaşamayı icabında bilirim...

ya sen,

bekliyorsun

gözlerinde var mı yaş...

benim ağladığım bu vakitte

sende ağlıyormusun...

ellerini uzattın

dokunamadım ellerine,

beni merak etme

her adımımda sana geliyor...

uzaklaşıyorum...

ama merak etme beni

yaşıyorum...

hayalin

ah o

hayalin...

olmasa bir akşam yanımda

birde ellerini uzattığında

dokunabilsem ellerine...

bana bakma sen

benim bitmez hiç hasretliğim,

hayalinle yıllar yılı

yaşamayı icabında bilirim...

ama hasretlik çekmek

zormuş mapus damında...', 'ellerini uzattın, dokunamadım ellerine kaç zaman, dayandım hasretine... hasret kaldım.. resmine bakarak gün tamamladım her sigaramda seni çe...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ellerini-uzattin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Doğdun (90)', 'i-yi-ki-dogdun-90-i-brahim-arslan-85ff2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'esirgedin benden

bir gülümsemeydi istediğim,kalpten

bir sıcak lafın,içten..

bir babadan isteği gibi evladın

bende sevmeni istedim baba gibi...

sevmeni istedim,yalandan değil

ne yazık! yapmacık sevdalar...

bir mumdum yanan,üfledin.söndüm

iyi ki doğdun....

esirgedin benden

sanki senden istedim

yıldızlardan köprü

kurmayı

ve denizden güneşi

çıkarıp almayı

avucumun içine koymayı....

sevginin tarifini unuttum işte

bir kafes içinde kuşum şimdi

özgürlüğün tadını unuttum işte

dünya uçsuz bucaksızmış,kime ne

benim dünyam şimdi bu kafes işte

iki günlük hürriyeti 

esirgedin benden...

hayret,

gözlerinin içinde

bir merhamet seziyorum

bir merhameti esirgeme benden,

diye dua ediyorum...

iki günlük hürriyeti

iki günlük dünya için 

esirgeme benden...

gözyaşımın hakkı için,

eğer göz yaşı akıtmışsan.

ne yazık,yapmacık sevdalar...

ben ölürüm,belki,yapmacık bir bakış için...

senin için bile,senin için bile...

ya ben seni niye sevdim

bir mumdum yanan,üfledin,söndüm...

iyi ki doğdun....', 'esirgedin benden bir gülümsemeydi istediğim,kalpten bir sıcak lafın,içten.. bir babadan isteği gibi evladın bende sevmeni istedim baba gibi....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/iyi-ki-dogdun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyarı & Ölüm', 'uyari-olum-caglar-asik-j2aag', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Coşkun ırmak, seli gibi.

Seher vakti, bülbül gibi.

Çölde kalan, yolcu gibi.

Aşkla yanan, aşık gibi.

&

Derman arar, hasta gibi.

Ferman dinler, asker gibi.

Zaman harcar, bitmez gibi.

Geldin, gittin rüzgar gibi.

&

Çağı aşar, koşar gibi.

Sözü olur, ağlar gibi.

Kimi günde, dağlar gibi.

Neyin kaldı, baki gibi.

&

Ölen beden, toprak gibi.

Haktan kaçar, bilmez gibi.

Ruhu sağır, duymaz gibi.

Ecel yakın, şu an gibi.

&

Korku sarar, yangın gibi.

Kaçış yoktur, yalan gibi.

Tadan bilir, aslı gibi.

Ruhu ağlar, nehir gibi.

&

Duyan şaşkın, bakar gibi.

Kaza olmuş, afet gibi.

Bir gün seni, bulur gibi.

Hazır olsan, yolcu gibi.

&

Sefer biter, döner gibi.

Çağrı alır, durmaz gibi.

Ruhu gider, kalmaz gibi.

Yaşlar akar, dinmez gibi.

&

Aşkla yağan, yağmur gibi.

Ümit çağla, rahmet gibi. 

Sevdan varsa, sonsuz gibi.

Kavuş sende, mecnun gibi.

&

İstanbul – 10.08.2005

Çağlar Aşık – Uyarı & Ölüm - Hece: 8', 'Coşkun ırmak, seli gibi. Seher vakti, bülbül gibi. Çölde kalan, yolcu gibi. Aşkla yanan, aşık gibi. & Derman arar, hasta gibi. Ferman dinler...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/uyari-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Yarınların Kızı (91)', 'guzel-yarinlarin-kizi-91-i-brahim-arslan-4nmuc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel yarınların kızı,

ben çoban kılıklı aşık,

yarını olmayan belki,

ama kapına gelmişim,

tık tık,karşına dikilmişim...

elimde kurumuş bir çiçek

sana vermedim attım yere,

sende kahkaha atmasaydın

belki o kurumuş çiçek

yeşerecekti elinde...

biranda muhasebesini yaptım,

bir hızlı dönüşüm vardı geri

sen masallardaki periydin

ne yapacaksın,böyle bir prensi? 

dur,dedin.durmadım

arkamdan koştun

çektin kolumdan,

_al! dedin,

manalı baktım yüzüne,

o zaman daha da anladım.

ben senin sevgine

sende benim sevgime layık değilsin...

hanımefendi dedim

_ben dilenci değilim...

...

_ya neye geldin,

 ne işin var kapımızda? 

sustum,sustum

başımı önüme eğdim

sırf yine gül diye

_seni sevdiğimi söyleyecektim,dedim...

...

hatta bende güldüm

ama sen gülmedin

şöyle bir tipime baktın,

senin neyine sevmek,der  gibi

bana öyle geldi

yanılmışım

_yakışıklısın, dedin

özür diledin benden

_ben bu evin hizmetçisiyim dedin

üzerimdeki elbiseler hanımımın...

...

sanki güneş bir daha doğdu battı.

yere attığım kurumuş gülü aldım

_madem ki öyle,dedim al

 bunu sana getirmiştim...

kız öyle bir gülme gülüyordu ki

dünyalar benim oldu derken

asıl bombayı patlattı,

ve hala kulağımda çınlayan

şu sözleri dedi

_salak,aptal

 şaka yaptım,şaka yaptım...

dünyalar başıma yıkılmıştı işte

o  güzel yarınların kızıydı...

SON', 'Güzel yarınların kızı, ben çoban kılıklı aşık, yarını olmayan belki, ama kapına gelmişim, tık tık,karşına dikilmişim... elimde kurumuş bir ç...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/guzel-yarinlarin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Koparsa...', 'bir-koparsa-can-ceylan-bvsui', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ardımızda boynu bükük ümitler

Gözden ırak güdük kaldı seçilmez

Aklımızda en olmadık fikirler

Bir koparsa fırtınadan geçilmez', 'Ardımızda boynu bükük ümitler Gözden ırak güdük kaldı seçilmez Aklımızda en olmadık fikirler Bir koparsa fırtınadan geçilmez...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-koparsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gar Saati', 'gar-saati-ertugrul-sakar-eggns', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kondüktördür

Ne makinist

Ne yolcudur

Ne karşılayan

Ne öten düdük

Ne anons sesi

Ne kaçar

Ne kovalar

Ne endişe vardır

Ne telaş

Ne geçmiştir

Ne de ati

Bir derviş kalbidir

Gar Saati', 'Ne kondüktördür Ne makinist Ne yolcudur Ne karşılayan Ne öten düdük Ne anons sesi Ne kaçar Ne kovalar Ne endişe vardır Ne telaş Ne geçmiştir...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gar-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilebilsem (92)', 'bir-bilebilsem-92-i-brahim-arslan-wrefj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sefer mi var 

Bu sefer nereye? 

Adım adım

Gidiyorum ölmeye...

Arkamdan benden başka

Gelen mi var...

Biraz mola vermek yok

Bir ağacın altında

Biraz uyumaktan başka

Ve bir dileğim...

Koparan ne beni vatanımdan

Bu dünya denen yerin

ALTIDA TOPRAK,ÜSTÜDE

Üstümde bir gömlekle

Bazen bir kefenle,gidiyorum

Sefer mi var.

Bu sefer nereye? 

Bir bilebilsem...

2005', 'Sefer mi var  Bu sefer nereye?  Adım adım Gidiyorum ölmeye... Arkamdan benden başka Gelen mi var... Biraz mola vermek yok Bir ağacın altında...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-bilebilsem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dicleye Sürgün Bir Ozanım', 'dicleye-surgun-bir-ozanim-fatih-suretli-ytdre', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Durgunum bu akşam dağlar misali. Ahlar karışmış Fırat’ın akışına. Anlıyorum ki bu acı gelip geçici değil gülüm. Dicle kan ağlıyor gözlerimde. Yüreğimde Ararat’ın isyanından bir fırtına kopmuş. 

Gözlerine sürgün bir divaneyim anlayacağın. Yaralarım var tuza bulanan. Bu aşkın enkazından sağ çıkar mıyım bilmem. Gözlerine bir daha bakmak içindir bu çırpınış. Bu acı çığlık mutluluğa olan özlemimdir. Sesinden bir türküdür sevda dolanır dilimde. 

Şimdi bu kentin sevda kokan caddelerinden seni dileniyorum senden habersiz. Yüreğimde güneşin böğründen kopan bir ateş yanar. Okyanuslara atasım gelir kendimi kangren gecelerimin mehtabında. Ellerin bir ateştir. Tutsam yanarım sönmek bilmez yangınlarda. Gözlerin yayından çıkmış bir oktur. Baksam ölürüm. 

Dicle’ye sürgün bir ozanım ben. Dersim’de turna semahıyım, Munzur çayında boğulur sesim. Sipan’da Siyabend’in sevdasıdır yüreğim. Geceler boyu Xece’nın saçlarına asılırım. Çarmıha gerilirim sorgusuz sualsiz. 

Bak yine karanlık çöktü bu kentin bütün hücrelerine. Acılarım bitmek bilmez Nemrut’un karına benzer. Oy benim kangren yaram, deli sevdam, hasretim oy. Her gece intiharlarla süslenir rüyalarım. Git de gideyim. Kal de ömrün olayım.', 'Durgunum bu akşam dağlar misali. Ahlar karışmış Fırat’ın akışına. Anlıyorum ki bu acı gelip geçici değil gülüm. Dicle kan ağlıyor gözlerimde...', ARRAY['Türk Edebiyatı','Şiir','Fatih Suretli']::text[], 8.5, '{"poet":"Fatih Suretli","poet_slug":"fatih-suretli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dicleye-surgun-bir-ozanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin Tuz Olsun Yaralarıma', 'gidisin-tuz-olsun-yaralarima-fatih-suretli-7wqsu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cümle cemaat yalnızlık 

Dost olmuş yine yüreğime 

Az sonra bir yıldız daha 

İntihar edecek mavi göğünden 

Sen gideceksin biliyorum 

Kayıp gidecek ellerin ellerimden 

Ellerin temmuz yangınıdır ellerimde 

Dört iklim, 

Yedi kıta 

Üzerime devrildi bak 

Haydi git gülüm 

Aldırma nisan yağmuru gözlerime 

Gidişin tuz olsun yaralarıma.', 'Cümle cemaat yalnızlık  Dost olmuş yine yüreğime  Az sonra bir yıldız daha  İntihar edecek mavi göğünden  Sen gideceksin biliyorum  Kayıp gi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Suretli']::text[], 8.5, '{"poet":"Fatih Suretli","poet_slug":"fatih-suretli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidisin-tuz-olsun-yaralarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-fatih-suretli-4vj3k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz çocukken; 

Direnirdik büyümeye 

Sahil kentlerinde. 

Oysa zaman; 

Dalgalar gibi gelip geçiyordu. 

Uzaklarda yelkenlerini suya indirmiş 

Gemilere bakar; 

Düşlerimizi martılara kanat yapardık. 

Biz çocukken; 

Acı nedir bilmezdik 

Karıncayı bile incitmezdik 

Bir parça ekmek elimizde 

Koşardık mahallenin sokaklarında 

Biz çocukken; 

Gökyüzü örtülürdü üzerimize 

Yarım kalmış sevda anılarını 

Anlamazdık 

Sevda nedir? 

Seven kimdir, sevilen kim? 

Dinlerdik sadece 

Koynumuzda yıldızlardan bir ordu 

Biz çocukken; 

Mayın tarlaları vardı (ki hala var)

Postal sesleri bölerdi 

Uykumuzun en derin yerini 

Güneş bir doğsa 

Karanlığın üzerine der; 

Şafağı beklerdik umutla 

Biz çocukken; 

Kardeşti hüzünlerimiz 

Hüzünleri körebe yapar 

Bir güzel dalga geçerdik 

Biz çocukken; 

Savaş vardı dünyanın bir yerinde 

Bizde de savaş vardı 

Böbürlenirdik 

Oysa onların savaşı bir katliam 

Bizim savaş 

Barış dolu bir yürekti 

Ve şimdi büyüdük 

Hayatı gördük, sevdayı anladık 

Keşke hep çocuk kalsaydık…', 'Biz çocukken;  Direnirdik büyümeye  Sahil kentlerinde.  Oysa zaman;  Dalgalar gibi gelip geçiyordu.  Uzaklarda yelkenlerini suya indirmiş  G...', ARRAY['Türk Edebiyatı','Şiir','Fatih Suretli']::text[], 8.5, '{"poet":"Fatih Suretli","poet_slug":"fatih-suretli","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cocuklugum-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Yoluna Bakmıyor Artık', 'gozlerim-yoluna-bakmiyor-artik-murat-demir-mfbtz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarsın yüreğimi hasretin kol kol

Ne vardı ki zaten ızdıraptan bol

Şimdiyse el değil benden duymuş ol 

Gözlerim yoluna bakmıyor artık

Varıp uzaklara gurbet oldun ya

Yabancı bağlar da dala kondun ya

Beni yaprak yaprak sen soldurdun ya

Aşkın güllerimi açmıyor artık

Bana şu dünyayı eğledinya dar

İstemem alnından dökülsede ar

Gönül ocağımda bir kibrit kadar

Sevdan ateşimi yakmıyor artık

Sensiz ne çıksa da fiilzlerimden

Fark etmez gitsede can dizlerimden

Bil ki senin için şu gözlerimden

Bir damla yaş bile akmıyor artık

Murat der ağlarken eskiden çok kez

Mendilim olmuştu metrelerce bez

Şimdi ister öldür istersende ez

Beni hiçbir acı yıkmıyor artık', 'Sarsın yüreğimi hasretin kol kol Ne vardı ki zaten ızdıraptan bol Şimdiyse el değil benden duymuş ol  Gözlerim yoluna bakmıyor artık Varıp u...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerim-yoluna-bakmiyor-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksüz Vatanın Ağacı (93)', 'oksuz-vatanin-agaci-93-i-brahim-arslan-892ij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sende öksüz vatanın ağacı,

BENDE,bir yürek var ikimizde de,

Korku  bilmeyen.ama bazende

Hiç atmayan,ikimiz içinde

Bir güneş var...can veren

Yapraklarına,bana da

Yaşama hevesi veren...

Sende öksüz vatanın ağacı

BENDE

Daha çok günler var diyorlar

Görecek.Aldanma! 

Hayata sıkı sıkı bağlanmak,

Akıl karı mı? 

Ya yarın göremezsen güneşi

Yarın ikimiz için doğmazsa,

Yapraklarına su taşıyamazsan,

Sen yakacak olursun 

Ya ben...dallarına kurduğum

Salıncağı da alır giderim...

27.02.2005', 'Sende öksüz vatanın ağacı, BENDE,bir yürek var ikimizde de, Korku  bilmeyen.ama bazende Hiç atmayan,ikimiz içinde Bir güneş var...can veren ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oksuz-vatanin-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuracaksan Kendin Vur', 'vuracaksan-kendin-vur-murat-demir-lqzv6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni her gün kandırma

Başkasına vurdurma

İstiyorsan hiç durma

Vuracaksan kendin vur

Ne döktür allarımı

Ne kestir yollarımı

Gül dolu dallarımı

Kıracaksan kendin kır

Dert olsan da canımda

Kan olup damarımda

Ömür boyu yanımda

Duracaksan kendin dur

Köz etmeden çıramı

Atlatmadan sıramı

İyileşmez yaramı

Saracaksan kendin sar

Ocağımı söndürüp

Güllerimi soldurup

Saçlarımı yoldurup

Yakacaksan kendin yak

Derdim aşsada bini

Hiçe sayıp sevgimi

Seni seven kalbimi

Sökeceksen kendin sök

Gökten yıldızı,ayı

İster aşkı sevdayı

Başıma şu dünyayı

Yıkacaksan kendin yık

Uyacaksan marşıma

Girip gönül çarşıma

İnsan gibi karşıma

Çıkacaksan kendin çık

Boran edip kışımı

Zehirleyip aşımı

Gözlerimden yaşımı

Dökeceksen kendin dök', 'Beni her gün kandırma Başkasına vurdurma İstiyorsan hiç durma Vuracaksan kendin vur Ne döktür allarımı Ne kestir yollarımı Gül dolu dallarım...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/vuracaksan-kendin-vur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk (94)', 'yokluk-94-i-brahim-arslan-zt8pe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittim ve geldim,

Yokluk denilen yere

Eli boş gittim,

Dolu geldim

Ne yılan gördüm

Ne böcek...

Rüya değildi

Hakikatmıydı bilmiyorum,

Tek gördüğüm

Milyon kadar vardı benden

Hepsinin başı önüne eğik...

Kimisi eşek şeklinde

Kimisi köpek

25,02,2005', 'Gittim ve geldim, Yokluk denilen yere Eli boş gittim, Dolu geldim Ne yılan gördüm Ne böcek... Rüya değildi Hakikatmıydı bilmiyorum, Tek görd...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yokluk-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye İlk Teklif', 'sevgiliye-i-lk-teklif-gokhan-saluk-633pq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni bir ben bilirim birde sen

Bir ben severim birde yine ben

Seni öylesine benimsemişim ki

Seni benden almak mı yürek sayarım

Biliyorum sevgilim ben kendimce

Olmadık duaya amin dedim

Birde dereyi görmeden paçamı sıvadım

Olmak yada olmamak mı senin elinde

Sen şimdi bana olmaz diyorsun

Sen sarhoşsun kızım ne dediğini bilmiyorsun

Senle olmaz Gökhan diyorsun 

Şu inadını bırak sana olan sevgimi biliyorsun', 'Seni bir ben bilirim birde sen Bir ben severim birde yine ben Seni öylesine benimsemişim ki Seni benden almak mı yürek sayarım Biliyorum sev...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Saluk']::text[], 8.5, '{"poet":"Gökhan Saluk","poet_slug":"gokhan-saluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiliye-ilk-teklif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Mevsimi', 'bahar-mevsimi-latif-bati-xfza4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökte Güneş ışıl ışıl,

Sular akar şırıl şırıl,

Kuşlar öter  cıvıl cıvıl,

Ne güzel bahar mevsimi! 

Ağaç açar çiçek çiçek,

Uçar rengârenk kelebek,

Yerde gezer bin bir böcek,

Ne güzel bahar mevsimi! 

Şimşek çakar çatır çatır,

Yağmur yağar şakır şakır,

Şenleniyor benim hatır,

Ne güzel bahar mevsimi! 

Kırmızı, sarı, mor güller,

Ötüşür güzel bülbüller,

Gönlümü açar sümbüller,

Ne güzel bahar mevsimi! 

Kış yer yüzünden kürünür,

Her yer yeşile bürünür,

Çiçekler çok hoş görünür,

Ne güzel bahar mevsimi! 

Gök gürülder gümbür gümbür,

Kutlanan yeni bir gündür,

Toplu, davullu bir düğündür,

Ne güzel bahar mevsimi!', 'Gökte Güneş ışıl ışıl, Sular akar şırıl şırıl, Kuşlar öter  cıvıl cıvıl, Ne güzel bahar mevsimi!  Ağaç açar çiçek çiçek, Uçar rengârenk kele...', ARRAY['Türk Edebiyatı','Şiir','Latif Batı']::text[], 8.5, '{"poet":"Latif Batı","poet_slug":"latif-bati","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bahar-mevsimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemek Aşka Kadardır', 'ozlemek-aska-kadardir-bahri-yildirim-f9ta0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece daha geçti

Sensiz katledildi düşlerim

Yüreğim yandı aşk ateşlerinde

Dilim dönüp, dön diyemedim

Hemen gel diyemedim

Görmesin diye gözyaşlarımı kimseler

Perdelerimi öyle sıkıca çektim.

Işıklardan gözlerini kıskandım

İstemedim toz konsun gülüşüne

Sıkıca kapattım gözlerimi

Yokluğunu görmeyeyim diye.

Adını söyledim canıma

Sevdiğimi söyledim koynuma

Seni çağırdım düşlerime

Sol yanımı hep boş bıraktım

Ansızın gelecek diye...

Geldin,Sağolasın! 

Gelişinle yeniden alevlendi aşklar

Özlemlerim titredi.

Aşk doldu penceremden.

Gökyüzünden aşk yağdı.

Sen halâ kavuşmaların tadındasın

Özlemlerim bitti,çok şükür

Sakın unutma, canımın yarısı

Özlemek,aşka kadardır.

ÖZLEMİN AŞKIN KADARDIR

Gülabi DENİZ', 'Bir gece daha geçti Sensiz katledildi düşlerim Yüreğim yandı aşk ateşlerinde Dilim dönüp, dön diyemedim Hemen gel diyemedim Görmesin diye gö...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozlemek-aska-kadardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Ve Öz Aşk', 'kisa-ve-oz-ask-gokhan-saluk-dut6i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeni bir aşka yakalandım yar da

Aşk için her gün başı boş gezdim

Yapacak o kadar çok işim vardı

Yakalandım bende aşk diye gezdim

Daha sonra kurtuldum aşk denilen beladan

Çevremdeki umutsuz bekleyen genç aşıklara

Öyle başı boşlar ki ümitsiz

Onların aşkları mı kurtulmaz artık çaresiz

Kendini tanıyan adam takılmaz

Neymiş bu, başa bela aldırmaz

Adı vardı bunun hiçbir bela kaldırmaz

“hah aşk elbet” aşk adamı barındırmaz', 'Yeni bir aşka yakalandım yar da Aşk için her gün başı boş gezdim Yapacak o kadar çok işim vardı Yakalandım bende aşk diye gezdim Daha sonra ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Saluk']::text[], 8.5, '{"poet":"Gökhan Saluk","poet_slug":"gokhan-saluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kisa-ve-oz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistinli Çocuk', 'filistinli-cocuk-latif-bati-xfcjj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben  Filistinli çocuk…

Sizin yuvanız gibi sıcacık,

Benim de yuvam vardı ufacık.

Siz ne kadar şanslısınız! 

Rüyalarınız bile şen, şakrak,

Ben ise rüyamdan bile ağlayarak,

Gece uykumun arasında,

Uyanıyorum korkarak! 

Siz yaşadınız mı hiç:

Top mermileri arasında bağırarak,

Tankların altında ezilirken,

Korkuyla uykudan uyandığınızı,

Gördünüz mü hiç? 

Gündüz böyle,gece böyle, rüyada böyle,

Hangisi gerçek, hangisi düş,

Bilmiyorum ben de.

Ben böyleyim işte,

Ben, Filistinli  çocuk! …

Sımsıcak yuvalarınızda,

Anneniz, babanız, kardeşleriniz,

Neşeyle yaşıyorsunuz siz.

Ya ben? Ya ben nasılım? ...

Zindanlarda sürünen,

Haylini bile unuttuğum babam! ...

Kim bilir nerede? ...

Yaşıyor mu acaba? 

Belki de hiçbir zaman,

Artık olmayacak babam! ...

Keşke ben de sizler gibi,

Koşup “Baba! ” diyebilseydim…

Kollarına atılıp, sarılsaydım boynuna,

Oyunlar oynasaydım onunla.

Üzülüp ağladığım zaman,

Gelip başımı okşayan,

Göz yaşlarımı silen bir babam olsaydı! ...

Ama yok artık benim babam! 

Çünkü ben, babası zindanlarda çürüyen,

Ona ağıtlar yakıp üzülen,

Filistinli çocuk! ...

Elinize bir diken batsa,

Bir yeriniz kesilse, kanasa,

Hele kolunuz, bacağınız kırılsa,

Canınız nasıl yanar! ...

Nasıl ağlarsınız değil mi acı acı! ...

Ya ben nasılım? 

İsrailli askerler tarafından,

Kolları taşlarla kırılan,

Bacakları tekmeyle, dipcikle ezilen,

Feryadıma hayvanlar bile dayanamazken,

Herkes tarafından seyredilen,

Ben, Filistinli çocuk! ...

İşte ben buyum,

Ben, Filistinli çocuk! 

Benim acılarımı ancak,

Ağaçlar, kuşlar kadar, 

Duyabiliyor musun sen? ...

Nerde buzullar arasında sıkışıp kalan

Balinaları kurtarmaya çalışanlar? ...

Nerede petrole batan kuşlara,

Üzülüp ağıtlar yakanlar? 

Nerede sokak köpeklerine acıyıp,

Onlara yardıma koşanlar? ....

Bir balina, bir kuş, bir köpek kadar,

Benim de değerim var.

Yıllardır dinmedi gözyaşım,

Ben hep ağlıyorum! 

Göz yaşlarım bile kurudu,

Tıpkı çöller gibi! 

Sen benim gözlerimden yaşların,

Aktığını mı sanıyorsun? 

Senin gördüklerin gözyaşı değil,

Onlar, gözyaşı yerine akan,

Damarlarımdan süzülüp gelen kan! ...

Ben kan akıtıyorum gözlerimden! ...

Ben kan ağlıyorum ciğerimden! ...

Yakında o da kuruyacak,

Tıpkı göz yaşlarımın kuruduğu gibi! 

Çünkü ben olmayacağım artık! ..

Sizler gülüp oynayın,

Halay çekip  türkü çağırın! 

Balinalara yardıma koşun,

Petrole batan kuşları kurtarın! 

Onlar için göz yaşı dökün! 

Köpekleri kurtarın siz! ...

Bir kuş, bir köpek, bir balina kadar

Bana yardıma koşmayanlar! 

Ben inlerken zulüm altında,

Ben ezilirken tanklarla,

Kollarım kırılırken taşlarla,

Herkes bana seyirci kalıyorsa,

Utansın bütün insanlık! 

Utansın bütün dünya! ...', 'Ben  Filistinli çocuk… Sizin yuvanız gibi sıcacık, Benim de yuvam vardı ufacık. Siz ne kadar şanslısınız!  Rüyalarınız bile şen, şakrak, Ben...', ARRAY['Türk Edebiyatı','Şiir','Latif Batı']::text[], 8.5, '{"poet":"Latif Batı","poet_slug":"latif-bati","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/filistinli-cocuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Anneyim', 'ben-anneyim-latif-bati-ocx4g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Besledim öz sütümle,

Küçücük beşiğinde,

Mışıl mışıl uyurken bile,

Kalbim hep seninle,

Çarpar birlikte.

Ben anneyim; ben, anneyim.

Gece tatlı uykuda,

Başladın bağırmaya.

“Inga! ... Inga! ...”

Üşenmeden kalkıp sana,

Yaptım bir mama.

Ben anneyim; ben, anneyim.

Bezin olursa ıslak,

İşin gücün bağırmak.

“Cıyak! ... Cıyak! ...”

Sen ağlarken böyle,

Bana haram uyumak.

Ben anneyim; ben, anneyim! 

Dünyaya gelince,

Öğrendiğin ilk kelime.

“Anne! ... Anne! ...”

Her gün, her gece,

Uğraştım seninle.

Ben anneyim; ben, anneyim! 

En kutsal meslek,

Dünyada tek:

Anne olabilmek.

Yüceltir beni tüm çocuklar,

Bana: “Anne! ....” diyerek

Ben anneyim; ben, anneyim!', 'Besledim öz sütümle, Küçücük beşiğinde, Mışıl mışıl uyurken bile, Kalbim hep seninle, Çarpar birlikte. Ben anneyim; ben, anneyim. Gece tatlı...', ARRAY['Türk Edebiyatı','Şiir','Latif Batı']::text[], 8.5, '{"poet":"Latif Batı","poet_slug":"latif-bati","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ben-anneyim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**(K) ehribarım**', 'k-ehribarim-seyhmus-sevilmez-xhfqy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırdılar Kanadımı, Karanlık Kişilerle 

Kahrolup Kaldırımda, Kırıldı Kehribarım

Kopardılar Kolumu, Kıytırık Kaşelerle

Katıksız Kibirlere, Karıldı Kehribarım

Kalkınca Kara Kaşın, Karla Kaplanır Kışım

Kenetlenir Kalbine, Kine Konmayan Kuşum

Korku Konar Kafese, Kifayetlidir Koşum

Kurşunlu Konaklara Kuruldu Kehribarım

Kuranıkerim Kâfi, Kulluğa Konamadım

Kıyamet Kanununda, Kâbile Kanamadım

Kesafetli Kararı, Kibirle Kınamadım

Kavimlere Kıymayan, Kuraldı Kehribarım

Kızıllığın Kamaşır, Kucaklaşan Kollara

Körüklenerek Kızmış, Kinle Kalan Kullara 

Korkmadan Kusursuzca, Kanun Keser Kellere

Köhneliklere Kaldı, Köreldi Kehribarım

Kulluğa Köleliğe, Kızar Karşı Koyarım 

Kusursuz Kâinata, Kızaklarla Kayarım

Kati Kararla Kalıp, Kansızlara Kıyarım

Kurmay’ı, Kadı’sıyla, “Kurul”du kehribarım

10.08.2005', 'Kırdılar Kanadımı, Karanlık Kişilerle  Kahrolup Kaldırımda, Kırıldı Kehribarım Kopardılar Kolumu, Kıytırık Kaşelerle Katıksız Kibirlere, Kar...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/k-ehribarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Kaldın', 'bir-sen-kaldin-bahri-yildirim-pr6xa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sildim ne varsa 

Mazide kalan.

Kötülükler

Sırlar

Ne varsa sevdalara düşman

Aşka düşman

Bir sen kaldın geriye

Bir de unutulmayan...

Bu geceyi sana  bağışladım.

Helâl olsun.', 'Sildim ne varsa  Mazide kalan. Kötülükler Sırlar Ne varsa sevdalara düşman Aşka düşman Bir sen kaldın geriye Bir de unutulmayan... Bu geceyi...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-sen-kaldin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pınar Ailesi', 'pinar-ailesi-latif-bati-nydx5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldız gibi parlak,

Su gibi berrak.

Ak PINAR’ım ak,

Çağlayarak.

Susuz çöllere,

Yanık gönüllere,

Ak PINAR’ım ak,

Şifa niyetine.

Çocuk gül gibi,

Havası sevgi,

Suyu ise bilgi.

PINAR’ın prensibi.

PINAR bir aile,

Çocuklar bizde,

Sevgi ve bilgiyle,

Yetişir güzelce.

Gönlümüzde sevgi,

Kafamızda bilgi.

Aşıyoruz biz,

Bütün engelleri.', 'Yıldız gibi parlak, Su gibi berrak. Ak PINAR’ım ak, Çağlayarak. Susuz çöllere, Yanık gönüllere, Ak PINAR’ım ak, Şifa niyetine. Çocuk gül gib...', ARRAY['Türk Edebiyatı','Şiir','Latif Batı']::text[], 8.5, '{"poet":"Latif Batı","poet_slug":"latif-bati","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pinar-ailesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey!', 'bir-sey-batuhan-batu-605pe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şey var içimde senin gibi bir şey

Anlatmaya çalışıyorum,yapamıyorum

Duygularım tarif edilmiyor,gözlerim doluyor

Sonra sesim titriyor konuşamıyorum...

Bir şey var içimde sana anlatamıyorum.

Sessizliğe bürünüyor birden evren

Bizi dinliyor gibi

Tam söyleyecekken içimdekileri 

Bir şey unutturuyor dilimdeki her şeyi

Böyle bir şey sende de var mı bilemiyorum? 

Belki de sende olmadığından yapamıyorum

Sözcükler dilimdeyken kuruyor boğazım

Ses tellerim kopuyor,söyleyemiyorum

Böyle şeyler sende de oluyorsa eğer

Demek ki sende de bir şeyler var...', 'Bir şey var içimde senin gibi bir şey Anlatmaya çalışıyorum,yapamıyorum Duygularım tarif edilmiyor,gözlerim doluyor Sonra sesim titriyor kon...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Batu']::text[], 8.5, '{"poet":"Batuhan Batu","poet_slug":"batuhan-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-sey-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalına tutunan telaş ve su meşalesi', 'dalina-tutunan-telas-ve-su-mesalesi-adnan-gul-u95ib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dalına tutunan telaş ve su meşalesi

rengime hece denemekten, sıkıntım...

durma sararmış ruhumda; ey hüzün

hortladı inişi, sancıya kaslan sesin,

arala parmaklarımı ıssızlığına

çöz yorgunluğumu içe...

bak, nakşından mı belleğimin

gayrılığa iç çeken gidiş...

anla ki, kamburuna değsin,

dalına tutunan telaş...

tırtılı say ki, aşılsın üç zaman

kelebeğe erken düşen kor...

anılsın inişe, susuz nehir...

başlasın toprağa yürüyen uzunca ses,

ışımadan seherdeki yalınca gökten,

kır ki öykücü dalları yan yana! 

seni konuşalım, seni...

konağını açan savaşa...

durma arkasında bedeli ödenmiş,

ahir zamanın...

gönünden çıkar şey değil; 

insan lekesi...

anam kavminden kovulduğu zaman; 

ışığını sınayan, çiğ ipektim ben...

ama dikiliydi sol göğsüme,

işaret renginin sesi...

dikiliydi ninem, çölünde kaktüse,

elindeydi su meşalesi...

''sıcak vesika'' adlı kitaptan', 'dalına tutunan telaş ve su meşalesi rengime hece denemekten, sıkıntım... durma sararmış ruhumda; ey hüzün hortladı inişi, sancıya kaslan ses...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gül']::text[], 8.5, '{"poet":"Adnan Gül","poet_slug":"adnan-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dalina-tutunan-telas-ve-su-mesalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken Rüya', 'erken-ruya-yunus-yakup-1745e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gözleri pır pır yürüyen çocuk

bir kadın masalı dinlerken ağladı

müziğini kıstı gül bahçelerinde eski bir radyonun

görkemini çizdi kadın masalı dinlerken ağlayanın

ellerinin arasından çıktı kağıt gemiler

ellerinin arasından çıktı renk denizi

şarkılar söyleyen dudaklar arasından sıyrılıp

işte öyle yaptı nasıl yaptıysa

öyle yaptı kadın masalının en güzel yerinde

hayal ürettiği çamur bulaşığı özenişinden

saydam bir belleğe yükleyip heykelini

onu en mahrem yerlerinden öptü

öptü kanatlarını bir kelebeğin

o gün doğdu güneşte eflatun

sıradanlaştı gece uykularının öbür yüzü

kadın masalından sıyrıldı', 'gözleri pır pır yürüyen çocuk bir kadın masalı dinlerken ağladı müziğini kıstı gül bahçelerinde eski bir radyonun görkemini çizdi kadın masa...', ARRAY['Türk Edebiyatı','Şiir','Yunus Yakup']::text[], 8.5, '{"poet":"Yunus Yakup","poet_slug":"yunus-yakup","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erken-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma', 'dokunma-deniz-yavuz-uhx4v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adı hiç konmamış yasak sevdalara gebeydik

Hiç açmamış çiçeğin tomurcuğunda

Hiç koklanmamış  bekaretiyle

Ve hiç doğmayacak bebeğin avuçlarında

İlk aşkların tadımına varmamış yüreğim

Sırılsıklam ıslanmışsa sanane

Açlığından kokuyorsa nefesi buram buram 

Bırak dokunma, ilişme, elleme 

Kardelen çiçekleri açmış yürekte göz göz

Herbiri ayrı yara, geçmez

Kalır sancıları doğuma beş kala

Gelinmezlikleri  biline biline

Uzatma artık ellerini 

Bırak  üşümüşlüğü ile kalsın 

Bakma gözlere maviliklerden 

Yaş olup dökülen sızısına dokunma...', 'Adı hiç konmamış yasak sevdalara gebeydik Hiç açmamış çiçeğin tomurcuğunda Hiç koklanmamış  bekaretiyle Ve hiç doğmayacak bebeğin avuçlarınd...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yavuz']::text[], 8.5, '{"poet":"Deniz Yavuz","poet_slug":"deniz-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dokunma-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gâvurlar...', 'g-vurlar-ulvi-ziya-wuo4l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Medenî zannedilir; 

Canavardan farkı yok...

Hayvanlara acır da

İnsandan nefret eder...

Komşuları aç yatar

Kendisinin karnı tok

Nerde ne zift bulursa

Hepsini sömürür,yer...

Kin güttüğü insanı

Zevk alarak katleder...

Uygar mı ? (!) ...

Özde sadist...

Hakîkatta canavar...

Her birinin içinde

Vahşetin izleri var...

Gün gelir

Bugünkünden daha ilerler ilim; 

Türk olmayan insanda

Nâmertlik geni arar...

Ve bulur...

O kanlarda

Sinsi,kalleş

Rûh yaşar...', 'Medenî zannedilir;  Canavardan farkı yok... Hayvanlara acır da İnsandan nefret eder... Komşuları aç yatar Kendisinin karnı tok Nerde ne zift...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gavurlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrünü ver', 'omrunu-ver-belgin-turan-eeo07', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlünü yakan hasreti, dost kabul et bundan böyle,

O  hicran gözyaşlarını, yardan gizle bundan böyle,

Ömrünü  ada bu  derde,  derman  kalmasada   serde,

İçindeki kör  kuyuya,  sevdanı  at  bundan  böyle.

Belgin Turan

''Güzden Önce Aşktan Sonra'' adlı şiir kitabımdan alınmıştır.

Gündüz Kitabevi Yayınları

Demet 7. Sokak No:7/b

Yenimahalle/Ankara', 'Gönlünü yakan hasreti, dost kabul et bundan böyle, O  hicran gözyaşlarını, yardan gizle bundan böyle, Ömrünü  ada bu  derde,  derman  kalmas...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/omrunu-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-cuneyt-coskun-ui2pr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne varsa şu gurbette

Hasreti zehir gibi acı

Rakıyı bal gibi 

Tatlı yapan

Benden yana..', 'Ne varsa şu gurbette Hasreti zehir gibi acı Rakıyı bal gibi  Tatlı yapan Benden yana.....', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Coşkun']::text[], 8.5, '{"poet":"Cüneyt Coşkun","poet_slug":"cuneyt-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gurbet-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melankoli', 'melankoli-cuneyt-coskun-j2m2v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen beni terkettiğinden beri

Hep bir terkedilmişlik hali saklar ruhum

Sanki birden terkedecekmiş gibi

Kapı,pencere hatta saksıdaki çiçeğim,

Ve geçen İlkbahar gibi birden bire bitiverecekmiş  hayat', 'Sen beni terkettiğinden beri Hep bir terkedilmişlik hali saklar ruhum Sanki birden terkedecekmiş gibi Kapı,pencere hatta saksıdaki çiçeğim, ...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Coşkun']::text[], 8.5, '{"poet":"Cüneyt Coşkun","poet_slug":"cuneyt-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/melankoli-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irkçı Olmadan Irkını Sev...', 'irkci-olmadan-irkini-sev-ulvi-ziya-y1hcg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey Müslüman Türk oğlu; ey âdil er oğlu er ! ...

Dinine ve kanına dâim sonsuz değer ver...

Kahpe düşmana karşı büyü maddî,mânevî; 

Sana diş bileyene güçlü kolunu göster...

Bilirim; kin tutmazsın,kardeşindir her ırk,cins...

Gerçeği sende bulur gerek hayvan,gerek ins...

Elin kalkmaz mâsuma,ihtiyara,kadına; 

Zulüm gâvura mahsus; ten parlaktır,iç necis...', 'Ey Müslüman Türk oğlu; ey âdil er oğlu er ! ... Dinine ve kanına dâim sonsuz değer ver... Kahpe düşmana karşı büyü maddî,mânevî;  Sana diş b...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/irkci-olmadan-irkini-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradığımda aşk bulduğumda ateştin ya...', 'aradigimda-ask-buldugumda-atestin-ya-adnan-gul-08nh4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aradığımda aşk bulduğumda ateştin ya...

acıtır varmışken sona; 

başa dönmem yeniden...

aradığımda aşk,

bulduğumda ateştin ya...

bakarak yıkımına; büyür servetim...

pısma köşeme, sesim seni anlamaz...

çık... çık...

daraltmadan hayatı

değil anlam, değil ötesi yüzün,

sorgusuna durduğum kıble...

hayatım ki o kadına tümüyle verilidir,

adını anmalarla başlar,

emekleyen çocuğun rüyasız

cepheye sürülmesi...

ölüm ki taban fiyatı meçhul,

en ucuz markasıdır ülkemin...

ama suyla yıkılacak, ruhumda heykel,

el at...

el at ki, açılsın nehre giden yol...

belki ilk yalnızlık naklidir; 

yaptığım resim...

doluydum belki yağmurdan, 

hallerime beş baka...

belki kirdir sözüm çıkmaz ruhumdan,

belki ertelenir cesetteki ses...

omzuna düştüğünde başım; 

bil ki karanfil sunuyorum sana...

ağrılıdır gülümsemem...

belki grimser akşamımdayım,

bakınca kara dondan...

belki hayat değil bu renk; 

acısıdır şalgamın içimden geçen...

inandığımda topraktan söze,

gel etti avuçlarıma ateş...

aldığım else de, ocağına kül,

kaldığıydı güneşin, sırrıyla düşeş...

''sıcak vesika'' adlı kitaptan', 'aradığımda aşk bulduğumda ateştin ya... acıtır varmışken sona;  başa dönmem yeniden... aradığımda aşk, bulduğumda ateştin ya... bakarak yıkı...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gül']::text[], 8.5, '{"poet":"Adnan Gül","poet_slug":"adnan-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/aradigimda-ask-buldugumda-atestin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-i-brahim-kilinc-8bmm4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün demiştin, bugün geçti, dün geçti

Hasretinle dolu nice gün geçti

Ay, mevsim, yıl derken, bak ömür geçti

Bu yarınlar bugün olmayacak mı? 

Gönül sevdan ile doldu taşıyor

Bir saatte dört mevsimi yaşıyor

Bakışınla bin ızdırap başlıyor

Gözlerinin içi gülmeyecek mi? 

Belli, bu sevdayı sen biliyorsun

Yanakların al al ve gülüyorsun

Susarak bilmem ki ne söylüyorsun? 

Gönlün şu gönlümü sevmeyecek mi? 

Ben söylerim, sen dinlersin, sözün yok

Dersin gönül işlerinde gözüm yok

Saklamaya, gizlemeye luzum yok

İbrahim de birgün bilmeyecek mi?', 'Dün demiştin, bugün geçti, dün geçti Hasretinle dolu nice gün geçti Ay, mevsim, yıl derken, bak ömür geçti Bu yarınlar bugün olmayacak mı?  ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umit-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su...', 'su-ulvi-ziya-20hc6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yemyeşil vâdide yüzeye çıkan

Şifâ veren suya benzer bu millet

Birikir; göl olur,birhayli zaman; 

Sonra akar,çevresinde bereket...

Düşmanlar bu suya engel olurlar...

Önüne set çeker,kilit vururlar...

Kasırga gibi esip,savururlar...

O ummana doğru eder hareket...

Yüksekten engine akıp gidendir...

Damlayı deryâya fedâ edendir...

Bu suyu yokuşa sürmek nedendir? 

Ters akıp kuruyan nehire hayret ! ...', 'Yemyeşil vâdide yüzeye çıkan Şifâ veren suya benzer bu millet Birikir; göl olur,birhayli zaman;  Sonra akar,çevresinde bereket... Düşmanlar ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim O Kadını', 'severim-o-kadini-ahmet-turan-altunsu-5txqa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'of! .. of! 

kadın ilginç bir filozof...

biraz havalı...

hani olur ya böyle yastıklar, pof pof! 

koyarsın başını,

değer/değmez arası, rahat! 

okşarsın kumaşını,

derin bir oh çekersin; 

yumşak mı yumşak! 

umurunda dahi olmaz

_____kadının vicdanındaki cerahat! 

sen rahatına bak adamım...

önemli olan, yaşamak! 

her şey zamana bağlı:

bir saniye, bir dakika, bir saat...

gör de bak:

kadında ne cerahat kalır, ne takat! 

işlendi ya oylum oylum? ! .

akıllı ol oğlum! 

bak, yine kapın çalacak! 

tak! .. tak! .. tak! 

kim o? ! .

 :)))))  

_______________10.08.2005 / Ankara

_______________Ahmet Turan Altunsu', 'of! .. of!  kadın ilginç bir filozof... biraz havalı... hani olur ya böyle yastıklar, pof pof!  koyarsın başını, değer/değmez arası, rahat! ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/severim-o-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni''ne...', 'seni-ne-gurkan-kuzu-mhbiy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin saçların kıvrım kıvrım,

İçine kır papatyaları yaraşır.

Senin ellerin ince ve küçük,

İçine dağ gülleri yaraşır.

Senin kalbin sevdalı ve narin,

İçine bir dolu ömür  adanır.

Saçların, ellerin ve kalbin...

Bunlarsız burada,

Söyle nasıl yaşanır?', 'Senin saçların kıvrım kıvrım, İçine kır papatyaları yaraşır. Senin ellerin ince ve küçük, İçine dağ gülleri yaraşır. Senin kalbin sevdalı ve...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Kuzu']::text[], 8.5, '{"poet":"Gürkan Kuzu","poet_slug":"gurkan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Beni!', 'anla-beni-batuhan-batu-4qlmo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anla beni sevdiğim yeter ki bir gün,

Anla beni coşan ırmaklardan,koşan ceylandan.

Dağ eteğinde karlar altında yatan çiğdemden 

Bebeğin anneye hasretinden anla beni 

Sor beni ıssız caddelerin köşe başlarından; 

Sana kim kalmış bu güne benden gayrı? 

Tozlu rafında açmadığın bir kitap sayfasından 

Oku beni, her açtığında yeni baştan...

Bul beni romanların eskittiği aşklardan 

Daha en güzeli yazılmamış bir şiirden 

Çıkar beni aydınlığa dudaklarınla 

Doğan şemsten tutulan kamerden', 'Anla beni sevdiğim yeter ki bir gün, Anla beni coşan ırmaklardan,koşan ceylandan. Dağ eteğinde karlar altında yatan çiğdemden  Bebeğin anney...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Batu']::text[], 8.5, '{"poet":"Batuhan Batu","poet_slug":"batuhan-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anla-beni-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekten Hayâle...', 'gercekten-hay-le-ulvi-ziya-1txnx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoksulluk gönlümüzde soldurdu her çiçeği

Vakitsizce sarardı hârelenen binbir renk

Meşakkat unutturdu huzur denen gerçeği

Ne aşkımızda şevk var,ne meşkimizde âhenk...

Ebedî kölesiyiz sırlı bir saltanatın

Tedirgince geçirdik günlerini hayâtın

Gözümüzde cilâsı döküldü kâinatın

Kader irâdemizle aralıksız etti cenk...

Çalıştık türlü işte; eller titrek,yorgun kol...

Sarıldık boş ümîde; ey hayâl,berhüdar ol...

Kaç gece ay denizde açtı da gümüş bir yol

Gittik o ışıltıda,an geçti yıllara denk...', 'Yoksulluk gönlümüzde soldurdu her çiçeği Vakitsizce sarardı hârelenen binbir renk Meşakkat unutturdu huzur denen gerçeği Ne aşkımızda şevk v...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercekten-hayale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla Açmayacağım', 'asla-acmayacagim-abdulkadir-karaca-mxig6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayır açmam kapıyı sen mutluluk değilsin

Hayır bakma yüzüme Sende çekip gidersin

Kollarını uzattığın bu şairin ahından 

Kaç yürek viran gezer olmadan bilirmisin

Hayır kapı kapalı,bekleme,açmıyorum

Zaten aşk kemendini boynumda taşıyorum

Körkütük sahibiyim,bu aşkın günahından

Sanki Nefessiz kaldım,Say ki ben yaşıyorum

Hayır saçlarında ölüm var,ardında acı

Uzak dur buralardan açamam kapıları

Bembeyaz başladığım bu aşkın siyahından

Alev alıyor gökler evrenin tüm sırları

Kapımda bekleme yar,esmem olmaz yol tamam

Bundan sonra aşkına zerre kadar inanmam

Ferman getir istersen yedi cihan şahından

Bunca acından sonra ben artık senle olmam

(10.08.2005)', 'Hayır açmam kapıyı sen mutluluk değilsin Hayır bakma yüzüme Sende çekip gidersin Kollarını uzattığın bu şairin ahından  Kaç yürek viran geze...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asla-acmayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hızırla Kırk Saat', 'hizirla-kirk-saat-sezai-karakoc-8o5bl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '40.

       Konuşacak Mehdi

       Geldi derleniş günü

       Derleniş toparlanış vakti

       Artık her gün her gece

       Bir kadir günü ve gecesi

       Kuran iniyor dağlardan tepelerden

       Yağmue onun yedeğinde

       Horazlar en keskin sesleriyle ötmede    

       Koyunlar ışıldıyor yünlerinde

       Yeni ve keskin bir bilgelik keçilerde

       Doğudan batıya bir şimşek atlardan

       Heyamolalarla inip çıkan

       Bir eleğimsağma develerden

       Kadınlar örtünürler Meryem örtülerini

       Bacalar yeniden tüter 

       Odunların en sertınin yanışından

       Bırakarak gökyüzünde bir ocak sisi

       Dağlarda bir başka çoşkunluk çağlıyor

       Menekşede çiğde kekikte ses var

       Bir vahiy uğultusu arılarda

       Karıncalarda hikmet suskunluğu

       Barışı ve çalışkanlığı sağduyunun

       Derleniş toparlanış diriliş saati 

       Geldi

       Yükseldi bir ağartı müslüman ufuklardan

       Müslüman mevsim ve iklimlerden   

       Kelimeler sıçradı yıllarca beklemişlerdi taşlarda

       Bir başkalaşım oldu yazılarda

       Seslerin durduğu yerde

       Gizlice süren bir ayet sonu yumuşaklığı

       Duruşlar bir süreden inmişcesine ağırbaşlı

       Davranışlar ölçülü tartılı

       Büyük dönüş başlamadan önce

       Kendini bırak evrenin koştuğu o Bütüne

       Bir kanat çırpmasıyla karıştığı Varlığa

       Düzeltip dünyayı yeniden

       Toplumu dirilten insanı erdiren

       Şeytanı bir duvar ucunda sıkıştıran

       Dam saçaklarında koğalayıp

       Eski sınırına iten 

       Kentlere mutluluğu

       Bir ikindi anıtı gibi getiren

       Her eve mermer dağıtan

       Şelale paylaştıran

       Kan kanalı uzatan

       Engebeli bir gebelikte 

       Yatağından korkan kadınlara

      Süt verin süt verin çocuklara

      Alarak nar incir gibi yemişlerden

      Şit evi sığnağı zeytinlerden

      Meryemin dayanağı hurmadan

      Tükenin var olan varlığıyla Varlığın

      Ki göreceksiniz kesin kesin

      Yüzünüzü nereye çevirirseniz çevirin

      O''dur var olan var eden

      Biçim veren değiştiren

      Dağıtan toplayan

      Hiç olmamışa çeviren

      Bir çırpıda gelip 

      Geçmişe döndüren zamanı

      Sesi seslendiren yeri yerlendiren

      Sonra açıp yeli yürüyen bir kabir gibi

      İçine yeri yerleştiren gömen

      Bir kan pıhtısından meniden

      Bir insan türeten

      Sonra onu büyüten

      Sözüne kulak yapan ağız yapan

      İşine onda bir yetenek özü mayalandıran

      İnanış veren sabır veren

      Kur''an''a da şeytana da

      Eş yapan yoldaş yapan sırasında

      Bir örtü gibi birden açan dünyayı

      Sonra birden toplayan ortalığı

      En büyük kolleksiyon sahibi

      Kafataslarından kemiklerden

      Güneşten aydan yıldızlardan

      Cennet ve cehennemlerin

      Kaybolduğu doğduğu girdabından

      Her çağ bir başka ses

      Duyulan mızrabından

      Doğmamış ve ölmeyen

      Gelmemiş ve gitmeyen

                                      sEZAi kARAKOç

       Artık her gün her gece

       Bir kadir günü ve gecesi

       Kur''an iniyor dağlardan tepelerden

