INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Geceler..', 'hazan-geceler-okan-nar-mls9t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana; yüreğimi verdim,

Hazan gecelerde..! 

Kokunu toprağa yükledim, 

Yağmurlu,ıslak gecelerde..! 

Uzandım sensiz gecelerde,

Gecenin ayazlı koynuna..! 

Umudumu,sevdamı...

Yükledim özlemine.', 'Sana; yüreğimi verdim, Hazan gecelerde..!  Kokunu toprağa yükledim,  Yağmurlu,ıslak gecelerde..!  Uzandım sensiz gecelerde, Gecenin ayazlı k...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hazan-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem....', 'ozlem-okan-nar-64fsr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne dokunası yıldızlar keser özlemimi....! 

Nede deli esen rüzgar...! 

Hissetmedikçe kokunu...! 

Hissetmedikçe ıslak dudaklarını...! 

Hissetmedikçe bütünüyle SENİ...!', 'Ne dokunası yıldızlar keser özlemimi....!  Nede deli esen rüzgar...!  Hissetmedikçe kokunu...!  Hissetmedikçe ıslak dudaklarını...!  Hissetm...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ozlem-239-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Aya Bakar', 'ay-aya-bakar-turk-oger-koc-yhz9j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüreğin de 

altın beşik 

sallayıp 

duruyorsun 

uslanmaz 

sevda delisiyim 

bekleyip 

duruyorsun 

ay 

aya 

bakar 

akşamları 

ay sigara 

yakar 

hüzün aya 

akar 

sevda 

beşikte 

durmaz 

uyku gözlerini 

kapamaz 

yarana 

merhem olurum 

uyutma beni 

sokağın 

lambasını 

kırmışlar 

sokaklar 

karanlık, 

karanlığa 

ışık olmak 

ışık olmak 

ister gönlüm, 

uyutma beni... 

