INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldin Gidiyorsun', 'geldin-gidiyorsun-yakup-icik-e4w12', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey sevgili; sen simdi gidiyorsun.

Ben bu gurbette kimi sevecegim? 

Ellerime dokundugun sicakliginla,

Az bir seni yasayacagim.

Inan bir daha ki gelecegin günü,

Iple cekecegim.

Ben burada sensizlige,

Zaten alisamamistim ki.

Bu sabah geldin, bu aksam gidiyorsun.

Öpüslerinden iz biraktin,

Ama sildin gidiyorsun.

Gözlerini bakislarima,

Saldin gidiyorsun.

Safagin pembe renginde uyanmistim.

Sen geleceksin görecegim diye.

Alacakaranlik bastirmadan gidiyorsun.

Aksam günesinin kizilliklarini,

Seyretmedik oysa seninle daha.

Geldin sevgilim,

Cigerimi söküp gidiyorsun.

Sevgilim kalbim sana atarken,

Durdurdun gidiyorsun!', 'Ey sevgili; sen simdi gidiyorsun. Ben bu gurbette kimi sevecegim?  Ellerime dokundugun sicakliginla, Az bir seni yasayacagim. Inan bir daha ...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/geldin-gidiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Cemali kabemizdir! Mani türü edebi', 'dost-cemali-kabemizdir-mani-turu-edebi-ozan-si-ar-agdasan-bdopu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dost cemali kabemizdir

Hac’ca gerek yoktur bizde

Sevgi oduyla yanarız

Sac’a gerek yoktur bizde! 

Sudan tatlı alın teri

Ölmeden öldük biz diri

İnsan dünyanın veziri

Tac’a gerek yoktur bizde

Nakarat:

Gün doğar güller al olur

Yaralı kuşa dal olur…

Dost sevdamızın şavkından

Ay hicap eder lal olur! 

Şiar, zulmü zay ederiz

Karanlığı ay ederiz

Biri kırka pay ederiz

Aç’a gerek yoktur bizde...!  Nakarat:...

Söz: Ozan Şiar Ağdaşan, Aşık Şah Turna  Müzik:Anonim  Yorum ve beste: Ozan Şiar

Vokaller: Aşık Şah Turna, Şirin Şafak Ağdaşan Umut Müzik

‚Klasikler’ ve Yolunda köprü olsam, Can Dost albümleri ve ''İnadına Sevdamız’ kitap

ŞİAR’IMIZ Sanat, Kültür, Edebiyat, Toplumsal Forum

www.siarcan.com', 'Dost cemali kabemizdir Hac’ca gerek yoktur bizde Sevgi oduyla yanarız Sac’a gerek yoktur bizde!  Sudan tatlı alın teri Ölmeden öldük biz dir...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dost-cemali-kabemizdir-mani-turu-edebi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorum Dediğim Gün', 'yasiyorum-dedigim-gun-melih-coskun-39vcx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşıyorum dediğim gün 

Hala şiir yazabiliyorum dediğim gündür

Ve sadece yaşamak için yorulmalıdır insan 

Yaşamaktan asla...

Gün gelecek 

Nadasa bıraktığım bütün acılarım 

Olgun meyveleriyle 

Gelecektir sana

Düşsem de yürüdüğüm yolda 

Yeniden ayağa kalkabiliyorsam 

Ve hala tükürebiliyorsam yüzüne zulmün. 

Yaşıyorum dediğim gün 

Hala direniyorum dediğim gündür benim...

Yaşıyorum dediğim gün 

Seni seviyorum diyebildiğim gündür benim...', 'Yaşıyorum dediğim gün  Hala şiir yazabiliyorum dediğim gündür Ve sadece yaşamak için yorulmalıdır insan  Yaşamaktan asla... Gün gelecek  Nad...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasiyorum-dedigim-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Beni Sevilmediğim Kadar', 'sev-beni-sevilmedigim-kadar-melih-coskun-8bgx8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Al beni 

Sahip çık sahipsizliğime,

Hak ol gel 

Haram edilmiş günlerime,

Sev beni hiç sevilmediğim kadar

Ve hatırla en çok unutulduğum anda...

Hiçbir şeyim eksik kalmadı senin kadar 

Ne yıllar yılı bekledim 

Paslı demirler ardında hürriyeti 

Ne açlık bir kurt gibi kemirdi midemi 

Adını bile hiç duymadığım türküydün sen 

Hiç yazılamamış, 

Saklı bir şiirdin dudaklarımda. 

Silip boşa geçen tüm zamanları

Bir güne sığdırabilmek güzelliğini 

Ve güneş doğmadan fırlayıp yatağımdan 

Seninle başlayan bir günü gözümü kırpmadan izlemek isterdim...

Al beni

Tertemiz  gülüş ol sevincime 

Sımsıcak öpüş ol suskun dudağımda

Annem kadar hiçbir kadın sevmedi beni 

Sevilmediğim kadar çok sev beni...', 'Al beni  Sahip çık sahipsizliğime, Hak ol gel  Haram edilmiş günlerime, Sev beni hiç sevilmediğim kadar Ve hatırla en çok unutulduğum anda.....', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sev-beni-sevilmedigim-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De Ki Hep Âşık', 'de-ki-hep-sik-suna-aras-2n4u3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün bu saatlerde ikimiz

Biraz hüzün biraz tat

Birbirine dokundu ellerimiz.

De ki hep sevdalı

De ki hep âşık

Dokunmadan seviştik

Rengi kaçmış odada, ürkek

Karmakarışık.

Tenim aşk bulaşığı

En güzel bakışın gözlerindeki

Uzanıp dokunuyorsun ürpertili

Kalkıp konuşuyorum ağzınla

Tepeden tırnağa ateş

Dudağının izindeki.

Ve dışarıda bir dünya

Döne kırıla kanaya

Duydu mu dersin bizi? 

Baharın yeşil ezmesi.

Alıp götürsen beni de

Minyatür bir bebek gibi

Gömleğinin iç cebinde.

İçimden geçti ya 

Söyleyemedim.', 'Dün bu saatlerde ikimiz Biraz hüzün biraz tat Birbirine dokundu ellerimiz. De ki hep sevdalı De ki hep âşık Dokunmadan seviştik Rengi kaçmış...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/de-ki-hep-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma Sevgili', 'sorma-sevgili-serhat-karadumanli-40el4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk çağlardan kopup gelen bir fırtınayım

Denizlerin köpüklerinden aldım gözyaşlarımı

O sebebten tadı tuzludur.

Yaralı bir kırlangıç gibi çırpınarak

Anlamını arayan kelimeler asılmış kaşlarıma

Ve gülüşümde çıplak kovan tadı...

Cenk meydanlarında patlamaya hazırlanan hırs

Ve şimşeklerin ürkütücü alazı yüreğimde...

Sorma sevgili

Sorma nereden ve nasıl geldiğimi bana

Hangi çatışmalardan kaldığını

Gözbebeklerimdeki kanlı şafakların

Vücudumdaki yara izlerinin...

Sorma sevgili

Sorma kirpiklerime asılan buz saçaklarını.

Biliyorum mevsim yaz, aylardan temmuz

Güneş tüm cazibesiyle ışıldarken

Tüylerim diken diken olmuş, ürperiyorum tenhalığımdan.

....-biliyorum adım atacak yer yok etrafımdaki kalabalıktan

ama volya atıyor içimde acılar

yıkılmış viraneye dönmüş saraylarımın arasında-

Sorma sevgili

Sorma neden ve nasıl yıkıldığını mihrabımın

Ürkek bir çocuk gibi sessiz bir köşeye sinişimi

Saatlerce volya atışımı kadim bir mahpus gibi.

Anlamışsındır, anlamalısın ruhumdaki abislerden

Bir tek sana izin verdim, bir tek sen görebilirsin

Dibe vurmuş batıklarımın küplerinde saklı olanları...

(2005 Avrupa)', 'İlk çağlardan kopup gelen bir fırtınayım Denizlerin köpüklerinden aldım gözyaşlarımı O sebebten tadı tuzludur. Yaralı bir kırlangıç gibi çır...', ARRAY['Türk Edebiyatı','Şiir','Serhat Karadumanli']::text[], 8.5, '{"poet":"Serhat Karadumanli","poet_slug":"serhat-karadumanli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sorma-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Fatma', 'sevgili-fatma-yakup-icik-gwb0g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cok yillar gecmisti aradan.

Bir duydum ki mahallede

Fatma adi dillerde yankilanir.

Ne yazik ki FATMA(*)   Zamanti,da bogulmustu! 

Icime atildi sanki ates

Eritiyor yüregimi yakiyor.

Görseniz o an duygularimi

Gözlerimden yas olup akiyor.

Ömrümde yasamadim böyle gün.

Hic birsey üzmemisti böyle derinden.

Öyle birgündü ki o gün her yer! 

Agitlar figan, sanki hüzün besteleniyordu!', 'Cok yillar gecmisti aradan. Bir duydum ki mahallede Fatma adi dillerde yankilanir. Ne yazik ki FATMA(*)   Zamanti,da bogulmustu!  Icime atil...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgili-fatma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Recete', 'recete-yurdagul-kurnaz-11cj2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kosmayi, heceyi dün ögrendim 

Ilkbahari ne cabuk özledim 

_______________________Ilk gercek askimdin, sakladigim 

_______________________Basi dumanli daglar, oy yandim 

Sevgi dedin, asktan kactin yare 

Bulunmazmi bu derde bi care 

_______________________Kaf dagi olsan, delerdim daglar 

_______________________Kan kirmizi gül, dereler caglar 

Hava, su, topraksiz kaldim; koma 

Doktor recetemi yaz bana; ASK', 'Kosmayi, heceyi dün ögrendim  Ilkbahari ne cabuk özledim  _______________________Ilk gercek askimdin, sakladigim  _______________________Bas...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/recete-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sairler Delidir', 'sairler-delidir-yurdagul-kurnaz-aibgn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sairler raporsuz bir delidir 

Siirler ki bunun tespitidir 

Kimseler alinmasin ilhamim 

Kapima geldi, dayanamadim!', 'Sairler raporsuz bir delidir  Siirler ki bunun tespitidir  Kimseler alinmasin ilhamim  Kapima geldi, dayanamadim!...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sairler-delidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimde ayridir yerin...Aysun hanim', 'kalbimde-ayridir-yerin-aysun-hanim-yurdagul-kurnaz-bywrn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin icin yildiz topladim gökyüzünde 

Avcumu yakmiyor! 

Senin icin gülleri budadim bahcemde 

Dikeni batmiyor! 

**********Konuktur yüregimize özü 

**********Yildizdir parlayan ay yüzü 

**********Büyülüdür seker tatli sözü 

Cik ortaya kardelen! 

Yik duvarlari 

Meydan oku hayata! 

Kuruyan irmaklar yeserecek 

Aysun hanim bahardir dört mevsim 

Duy sesimizi; yer, gök, su inlesin! 

Men cooohh yorulmusem demeyesin 

Henüz top oynamamisem senin ilem 

Her gece bir cocuk melodisinde 

Cagla berrak derelerde 

Gülücüklerin isledi, 

Yer aldi can evimde 

Ilkbaharda kardelene ulasmak zordur! 

Zordur biliyorum... 

Ulasmak istiyorum! ! ! 

Toplamak 

Koklamak 

Engel olsa dahi yollar! 

''Ne hostur cin vazosundan firlattigi güller'' 

_Yaprak olur yolunda, bu gönüller_ 

Aysun hanima ithafimdir....Sizi Seviyorum', 'Senin icin yildiz topladim gökyüzünde  Avcumu yakmiyor!  Senin icin gülleri budadim bahcemde  Dikeni batmiyor!  **********Konuktur yüregimiz...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kalbimde-ayridir-yerin-aysun-hanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G.y.t.m.o.ş …', 'g-y-t-m-o-s-murat-araz-uzvbk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(.y.t.m.ş…’ye)      (Aşklar sürgünde)

 Pembe kokacağını bilsen de,aşk tütsüsünü hemen görür görmez içinde hayatın bulunduğu kibrit kutusundan hayatı çekip yakmamak lazımmı

Yakarsan hayatında yanarmış ve geriye küllerin kalırmış

Yeni anlıyorum

Şimdi anlıyorum yakarsan o pembeler karaya çalarmış

Güzeli sevsen de delicesine ona göstermeyecekmişsin madalyon’un bu yüzünü göstermeyecekmişsin

 Her şey geçer elinde yaşaman gereken; hayat kalırmış

Sevmek sevilmeyi bilmeyi gerektirir

Aşkım sizin bedeninize dört gömlek büyük geldi

Aşkı tanıdım bakire bir gölgenin altında seninle

Beklide o an kendimi şu güneşli diyarda uçuruma atmamdı; atladığım yerin uçurum olduğunu bilmeden

Sevgiler dölledim cömertçe; ve cömertçe harcandılar

Hayatım yandı

Başkalarıydı,bizim üst üste uzanmış aşkımızı bozan ya da zaman

Kutsal ay ve ebedi yalnızlıklı güneş deydi bizim aşkımız

Oysa Yalnız; yanılmamış dokunulmamış deniz dokunulmaz

İki aynanın arasındayım! ; kendimi kendimden ayırmışım

En güzel aşk,güneş ve ay kokanıymış

Sonra hayata adım atmıştım büyümüşlüğü,hayatı,acımasızlığı,güzelliği tanımıştım

İnsanların sana gülüp sonra da arkandan vurabileceğini de öğrendim

Hayat acımasız bir şeymiş,uzağım ona,bir gemiden gördüm uzaktan bakış attım haline ağladım,zaten ay’da yüzyıllardır ağlamıyor mu? 

Ayrıldığını başkalarından da öğrenebilirmişsin…Senleyken anladım

Tanıştım üç kişilik ilk oyunumla…Ve bıkkınlıkla,nefretle,yalanla,tanıştım; Evet tanıştım da o bana memnun oldum dedi bende ben ondan olmadım dedim…Bin tane mum’un karasını,acımasızını,bitme eğimliyi seçtim

Yaktım söndün külün kaldı; çöpe attım

Ne kaldı geriye yok olan bulunmayan tiksinç küller…ve hayat

Senle tanıdım aşk mavisini,gerçekleri,masmavi ihanetleri,ayrılığı,değişkenlikleri

Demek ki insan bin tane çiçeğin içinden en gerçeğini ve yorucusunu da çekebilirmiş,Ona adaya bilirmiş koca hayatını

Keğıt’ı,kalemi unutmuştum

Göz yaşlarına batırdım kalbimi

Sizin gibilerden az kaldı

Ve daha yüzlercesi

 Mavisi,karası ve yeşili

Kimbilir hangi diyarda unuttum isminizi? 

Gönlümün elçilerini kodese attım,unutulma süreleri,iki yıl beş ay,gün gelirde çıkarlarsa düşümdeki güzeli bulamazlarsa bu sefer onları tek tek öldürürüm

Düşümdeki Rüya

Düşümdeki güzel

Düşümdeki güzel

Nerdesin

Kim bilir nerde nasıl karşıma tüm cüretkarlığınla çıkacak ve içimi alıp öldüreceksin

Yağmurlar altındayım

Islanmışım öleceğim ama seni aramaktan beni hiçbir şey alı koyamıyor

Kutsal ay kutsa onu ve onu batır beyazına; yalnız güneş ışınla mavilerini; derinlerine çeksin,Jüpiter ver yeşilini,Kainat yüzdür karanlıklarında,bahçeler sapsarı çiçeklerini yetiştirsin senin için,Gül kırmızısı her zamankinden kırmızı olsun,Kan kırmızısını oradan sana yollasın,Balıklar türkuazını yüzdürsün sana

Ve sen masmavi  ol

Al beni ılık bir yaz yağmurunda gel ve Öldür beni,çek içine,yak,bırakma…Gökten yağ tüm cüretkarlığınla

Gel Gel Gel

Yazgım ilk kez mavi olsun

Vücuduma konan bir sinek gibi kon; ve akıt aşk kırmızını

Şehvetini de getir

Yay falları ve büyü kanat onu

Sakınma ve bir yunus kadar mavi ve istekli, ol

O ılık yaz yağmurlarıyla gelme Ebedi Bir Yağmurla Gel

Çünkü yalnız sen ve ben bana giden yolu bulur

Ben beni benden alırım ancak o zaman

Aşktan bir süreliğine ayrıldım

Kaçamaaş dan apar topar kaçtım

Gerçeklerle kaldım ben

Gayret et

Geri geleceğim ıhlamurlar çiçek açınca

Sarıla meyvesini verip mavi olunca hayat gözündeki yaşları silecek

Gayret et

Sevmen gerekeni sev yaklaşınca orada durma koş

Ama şimdi orada dur ve beni yorma yakma,beni bana bırakı gayret edeyim

Gayret et

Her şey geçti hayat kaldı; karşı karşıyayız şimdi…

02.02.2005 Çarşamba/00:20/Sivas', '(.y.t.m.ş…’ye)      (Aşklar sürgünde)  Pembe kokacağını bilsen de,aşk tütsüsünü hemen görür görmez içinde hayatın bulunduğu kibrit kutusunda...', ARRAY['Türk Edebiyatı','Şiir','Murat Araz']::text[], 8.5, '{"poet":"Murat Araz","poet_slug":"murat-araz","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/g-y-t-m-o-s-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordular bana', 'sordular-bana-mikdat-bal-3lmo7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sordular bana neden hasreti yazıyorsun

Hem bizi hem kendini, ağlatıp üzüyorsun

Bırak gel Avrupayı, ne diye kızıyorsun

Kızarım çünkü bu dert, çekilir sızı değil

Zulüm eden müslüman bir gavur kızı değil! 

Ayaktan bağlanmışız, kök saldık sökülmüyor

Bir haneydik beş olduk, bırakıp çıkılmıyor

Budur bizi bağlayan, bu hasret çekilmiyor

Süreklidir bu hasret, arada bazı değil

Dört mevsim gelmeliydim, baharı yazı değil

Memleketi terkettik geldik Avrupalara

O zamanlar fakirdik, boğulduk paralara

Bir öküz almak için, gelmiştik buralara

Öküzler çoktan hazır, inekler razı değil

Mikdat’ın yazdıkları, sıradan yazı değil', 'Sordular bana neden hasreti yazıyorsun Hem bizi hem kendini, ağlatıp üzüyorsun Bırak gel Avrupayı, ne diye kızıyorsun Kızarım çünkü bu dert,...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sordular-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hint kumasimisin', 'hint-kumasimisin-husamettin-guven-56vfq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne naz edip durursun

cok havali birisin

sen kendini ne sanirsin

bulunmaz hint kumasimisin

buyuk olan yalniz allah

sen gozumde hic sin vallah

ben cekemem zorsun billah

bulunmaz hint kumasimisin

kasilarak durursun

cok kaprisli birisin

cekilmez ve  sinirsin

bulunmaz hint kumasimisin', 'ne naz edip durursun cok havali birisin sen kendini ne sanirsin bulunmaz hint kumasimisin buyuk olan yalniz allah sen gozumde hic sin vallah...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hint-kumasimisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni çok özlüyorum', 'seni-cok-ozluyorum-umit-isikdag-zsq64', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir ağustos gecesi

geç saatte tanışmıştık ya

şimdi yine öyle

bir ağustos gecesi

aklımıda ismin ve

kulalığımda sesin

ellerimde olmayan elinle

seni çok özlüyorum..

hava yine hafif esintili

izmir yine sıcak her zamanki gibi

bir deprem sonrasında 

geç bir saatte tanışmıştık ya

şimdi seninle eskisi gibi

yeniden tanışmak istiyorum

sensizliğin sesi kulağımda

inan seni çok özlüyorum..

hafif bir müzik sesi geliyor

gece yine sessiz her zamanki gibi..

ritm ağır aksak,sensizliğin şarkısında

varolmanın kuytusunda,ben seni arıyorum

deniz sakin,gökyüzü kara,

yıldızların ardında,

ve ben seni soruyorum

o bizim yıldızımızdı ya..

ona da söyledim

seni çok özlüyorum..', 'bir ağustos gecesi geç saatte tanışmıştık ya şimdi yine öyle bir ağustos gecesi aklımıda ismin ve kulalığımda sesin ellerimde olmayan elinle...', ARRAY['Türk Edebiyatı','Şiir','Ümit Işıkdağ']::text[], 8.5, '{"poet":"Ümit Işıkdağ","poet_slug":"umit-isikdag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-cok-ozluyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum...', 'masum-emine-deniz-eqcgd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sabah

Yağmurlu bir deniz gibisin

Biraz çekingen

Biraz tutkulu

Eğilsem

Öpüvereceksin dudaklarımdan

Ya da

Öylesine

Masum

Günahlarımdan...', 'Bu sabah Yağmurlu bir deniz gibisin Biraz çekingen Biraz tutkulu Eğilsem Öpüvereceksin dudaklarımdan Ya da Öylesine Masum Günahlarımdan......', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/masum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül...', 'gonul-gokten-aydogdu-0fvfx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne yanmayı bilip nede yandırıp,

Böylesi hataya düştün ya gönül! 

Zalimin elinde kendin kandırıp,

Uğruna dağları aştın ya gönül! 

Sevdiğine verdin değmeyen  paye,

Unuttun başından neydi ki gaye,

Sevdalı bir yürek eşsiz hediye,

Serabın peşinden koştun ya gönül! 

Gittiğin yerlerde arama boşa,

Farzı mahal değdin kayaya taşa,

Döndün en sonunda geldiğin başa,

Sığmayıp bendinden taştın ya gönül! 

Söz geçirebilsem coşar çağlarsın, 

Kızgın yaraların aşk ile dağlarsın,

Sevdiğine varıp gönlün eğlersin,

Sevda ateşiyle piştin ya gönül! 

Aydoğsun gecene güneşli günün,

Ağrımasın canın soldaki yanın,

Bilsen ömre bedel gül kokan tenin,

Sevdayla dopdolu teştin ya gönül!', 'Ne yanmayı bilip nede yandırıp, Böylesi hataya düştün ya gönül!  Zalimin elinde kendin kandırıp, Uğruna dağları aştın ya gönül!  Sevdiğine v...', ARRAY['Türk Edebiyatı','Şiir','Gökten Aydoğdu']::text[], 8.5, '{"poet":"Gökten Aydoğdu","poet_slug":"gokten-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonul-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalet', 'hayalet-mehmet-ferhat-bir-t58a0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aşklar hüzünle başlar bende

buluşma ihtimalim olmadığından denizle

güneş dönünce yüzünü doğuya

biten bir gecenin hüznüdür aslında

doğum çığlık çığlığadır 

bir bebenin dilinde

kıçına ilk tokadı yese de 

yemese de

gün batıya kayınca

batınca umutlar

tepelerden aşağı

ardımda ne bıraktıysan

taşıyınca dağların ardına

kalan 

bir umudun

hüzünlü hayaletidir yalnızca

ve aşklar uzakta denize

yalnız biter benle 

(03071998-2005)', 'aşklar hüzünle başlar bende buluşma ihtimalim olmadığından denizle güneş dönünce yüzünü doğuya biten bir gecenin hüznüdür aslında doğum çığl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ferhat Bir']::text[], 8.5, '{"poet":"Mehmet Ferhat Bir","poet_slug":"mehmet-ferhat-bir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayalet-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fuhuş Koridoru', 'fuhus-koridoru-ozgur-kokturk-h4ga8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç böyle hoyratça harcanmamıştı sevda

Aşk hiç bu kadar değersizleşmemişti

Fuhuş koridoru sokaklarda

Hiçbir sevgi sözcüğü bu kadar kolay tüketilmemişti...

	

Yalınayak yürüyorum leş kokan bulvarda

Duvarlarda insan kanı...

Yürek burkan şehvet çığlıkları

Titreyen nefeslerin iğrenç buğusu

Salya sümük sevişkenliğinde caddelerin

Cam kırıklarıyla deşilmiş yürekler...

Çirkef tutuyor eller

Dudaklardan balçık damlıyor 

İrinle yıkanıyor bedenler

Her kelimeden küfür akıyor

Yağlı parmaklar dolanıyor karanlık saçlarda

Göz gördüğüne isyankar 

Dil utancından lâl...

Usanç taşıyor tırnak dipleri

Leş torbası kaldırımlar

İlenç deryasına saplanmış devran

Döngüsünde çamur, girdabında katran...', 'Hiç böyle hoyratça harcanmamıştı sevda Aşk hiç bu kadar değersizleşmemişti Fuhuş koridoru sokaklarda Hiçbir sevgi sözcüğü bu kadar kolay tük...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/fuhus-koridoru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum Ol', 'ruhum-ol-mehmet-ferhat-bir-31dv7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çağırma beni rüyalarımdan

korkulu bir sona 

mahkum etme

bırak içimde yaşatayım

bırak düşlerin süslesin

düşlerimi

ne olur bırak

gördüklerim gerçekti

yüzünde gördüklerim

bir ormandı kirpiklerin

gözlerindeki güneşi süzen

bir biraydın bardağımda duran

sonra kanımda kaybolan

çağırma beni sensizliğimden

gelme bana

görmemeliyim ki seni

hasretim ulu bir çınar

gözbebeklerim yarı çapın olarak

özleyeyim

bırakma beni

gözlerinle baş başa

yaşayamam

sessizliğinle de bırakma

yazamam

her gün gülüşünü görmeliyim

bir yolculuk olmalısın içimde

hiç sahip olmadığım

ama bir çığ gibi büyütebileceğim

bir çocukta olmalı

elleri ellerimin içinde

seslenme bana kutuplardan

iki dudak arası kadar uzağım 

dudağımla dudağından

gözleri ol

bankta oturan yaşlı adamın

gözleri ol 

merdivenleri tırmanan çocukların

gözleri ol babamın

bir de beni öyle gör

gözleri ol annemin

işte beni öyle sev

dalgaları ol bir denizin

dalgaların

çakıl taşlarında sönsün yüreğimin

bir şehrin ışıkları ol

antik bir tiyatronun oyunları

oyuncuları biz olalım

hasretim ol

“Gülhane Parkında”

bir çınarın yaprakları

ruhum ol 

bedenim ol

ama asla benim olma

ki kaybetmeyeyim seni

(28061996-2005)', 'çağırma beni rüyalarımdan korkulu bir sona  mahkum etme bırak içimde yaşatayım bırak düşlerin süslesin düşlerimi ne olur bırak gördüklerim g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ferhat Bir']::text[], 8.5, '{"poet":"Mehmet Ferhat Bir","poet_slug":"mehmet-ferhat-bir","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ruhum-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk’ün Türkten başka bir dostu yoktur! !', 'turk-un-turkten-baska-bir-dostu-yoktur-mikdat-bal-48hdk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Türk’ün Türkten başka bir dostu yoktur! ! 

En büyük düşmanı, yine de Türktür! 

Sözüm ona sahte dostları çoktur

En büyük düşmanı yine de Türktür! 

Azılı düşmanlar bizden çıkıyor

İçimizden çıkıp bizi yıkıyor

Ben de Türk’üm diyor fesat kokuyor

Dostumuz da Türktür, düşman da Türktür! 

Dışardan taarruz olsa korkmayız

Tüm dünya birleşse yine ürkmeyiz

Etten duvar olur düşman sokmayız

Korkulacak düşman, sadece Türktür! 

Vatanını satar, bizden birisi

Ecdadı şehittir, kahpe dirisi

Dışı bize benzer saçı derisi

İçi nifak dolu, ne yazık Türktür!', 'Türk’ün Türkten başka bir dostu yoktur! !  En büyük düşmanı, yine de Türktür!  Sözüm ona sahte dostları çoktur En büyük düşmanı yine de Türk...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turk-un-turkten-baska-bir-dostu-yoktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şuhdamarı', 'suhdamari-tarkan-ragipoglu-05uzd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şuh damarı bakışlarınla şahdamarımı kesiyorsun 

Kanıma karışıyor bakışların

Canımı yakıyor emanet bir yatakta kıvranışın

Gözlerin sarsılırken,boşalırken karnının ateşi

Dağlarken yüreğimi ayıp kadın hallerin

Arı kovanına çomak soktu çocuk ellerin

Şimdi sen lise defterinde üç projen

Çiğ hayatın ortasında yum gözlerini

Biliyorum ki iki koca damla gözyaşı

Ellerin büyük senin yum gözlerini

Boynunda halka kollarım kokum

Gözlerini yum sık dişini açma sakın 

Alı al hallerin moru mor sesin çıkmasın

Yine sık dişlerini sık bir aşk çatlasın

Kasılı bedenin yüzü var artık rüyanın

Ve iki ayrı hali malum sana dünyanın

Aç gözünü aç 

Ve gör

Artık kimle dalarsan dal uykuya

Kiminle oturursan otur Marıa’ da

Her erişte de,her kalamarda

Deniz bedenine sarıp sarmaladığında

Yalnız kalma sakın, sakın şarkılar

Şiirler ve bilimum Ah İstanbul

Gözünü yum sıkıca,aç gözünü

Herkesler uyuyunca

Artık kimle dalarsan dal uykuya

Benimle uyanacaksın', 'Şuh damarı bakışlarınla şahdamarımı kesiyorsun  Kanıma karışıyor bakışların Canımı yakıyor emanet bir yatakta kıvranışın Gözlerin sarsılırke...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Ragıpoğlu']::text[], 8.5, '{"poet":"Tarkan Ragıpoğlu","poet_slug":"tarkan-ragipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/suhdamari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemişim', 'ozlemisim-elazigli-mustafa-kaya-hv2u2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'özlemişim oluklu bir çeşmeyi.

özlemişim kurnası su ile dolu çeşmeleri,

serin gölgesi kavak ağaçlarını,

sıra sıra selvileri bir köy yolunu,

yamaçlarında çiçekler,

renk renk kelebekler,

ve misk kokulu sümbülleri.

özlemişim beton yığınlarından uzak bir köşeyi,

güneşten sıcak yüzleri,

insanımızı özlemişim.....misafirperver

şehrin kirinden uzak.. 

mezarlık çevresinden dualarla geçmeyi 

özlemişim. 

ölümü hatırlamayı 

dünyanın zevklerini söndüren.. 

ve dönüp 

bir selvinin gölgesinde 

konuşmayı özlemişim... 

oluklu çeşme bakıyor konuşmalarımıza 

suyu soğuk çeşmenin tanıklığına bak..! 

kimleri suladı kimbilir…hainler ve yiğitler,

nişanlılar ve evliler,

ordular ve yolcular,

kana kana su içtiler..gelip geçtiler.

ne güzelmiş meğer

yalınayak gezinmek 

yeşil yeşil saran otlarda,

serin serin sularda. 

bir de selvi giriyor dünyama....özlemim var 

özlemim bunlara..

                                                  14.08.2005 / İstanbul

                                                  Mustafa kaya', 'özlemişim oluklu bir çeşmeyi. özlemişim kurnası su ile dolu çeşmeleri, serin gölgesi kavak ağaçlarını, sıra sıra selvileri bir köy yolunu, y...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ozlemisim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi şarkılardasın', 'simdi-sarkilardasin-elazigli-mustafa-kaya-lwxvz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi hiçbir eski avutmuyor

şimdi hiçbir yeni de sevindirmiyor

şimdi hiçbir duruş etkilemiyor 

şimdi ne denizin ne de yosun kokusunun yeri yok.

şimdi kederlerime sarılıp sabahlar ediyorum.

unutamam..unutamam seninle ilk yaşadıklarımı

umutlarıma gölgeler düşse de

uçurtma yapacağım çocuklaşıp sevinçlerimi ve,

ufuklara bakınıp dönersin diye

uykulara dalmayacağım…

leyl gece demekmiş sevdim ben gecemi

lügatte kelimeler aradım senin için

lalezar lale bahçesi demekmiş sevdim ben lale mi

lakin bir kara yılan gibi sokuldu mesafeler,

lümpen bir arenada sahipsiz kalman felaket..

elimde değil kaçıramıyorum senden aklımı

erişememek kırıyor duygularımı ve,

elbet bir gün buluşacağız şarkılarını

ezberledim..ezberleyeceğim...yardım et Allah ım..yardım et..

                                                                                    10.08.2005 / istanbul

                                                                                     mustafa kaya', 'şimdi hiçbir eski avutmuyor şimdi hiçbir yeni de sevindirmiyor şimdi hiçbir duruş etkilemiyor  şimdi ne denizin ne de yosun kokusunun yeri y...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/simdi-sarkilardasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurtma', 'ucurtma-elazigli-mustafa-kaya-jsvqp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'paramız olmadığından dı, 

hiç oyuncaklarım olmadı. 

kağıttan yapardık uçurtmaları, 

çıtalı bir uçurtma alamadık. 

kağıt uçurtma bir o yana

bir bu yana

düştü düşecekti

ip kopardı 

kuyruk uçardı

kağıttan uçurtmam 

kaç kez yırtılır. 

kaç kez ağaçlara takılırdı

tek sevincimdi 

çıtalı bir uçurtma 

alabilseydik eğer

en yukarıda olurdu 

hiç yere inmezdi

renkleri sarı kırmızı

parlak kağıtlı

tüm çocuk günlerimde

hep kıskandım

çıtaları olan uçurtmaları

rengarenk uçarlardı

bulutlarla konuşur,

yere selam verir 

gibi

çıtalı uçurtmalar

ne güzeldi

ipi çekip bırakarak

yükseğe daha yükseğe

birbirleriyle yarışarak

gökyüzünü ele geçirirlerdi

bu yüzden

süslerdi rüyalarımı

ne zaman rüzgar çıksa

çocukluğumu hatırlarım 

gökyüzüne çıkarım 

kah

kağıttan uçurtmamla

kah

çıtalı uçurtmalarla...

11.21.2004 / istanbul 

mustafa kaya 

www.mustafakaya.net', 'paramız olmadığından dı,  hiç oyuncaklarım olmadı.  kağıttan yapardık uçurtmaları,  çıtalı bir uçurtma alamadık.  kağıt uçurtma bir o yana b...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ucurtma-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alış Kadere', 'alis-kadere-yavuz-bayram-caliskan-0693r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçine bir kere çekmeye bak yaşamın soluğunu,

İşte o an borçlusun,

Unutma bir gün ödeyeceksin,

Vereceksin bedenini, kalacak ruhun,

Yüzleşeceksin kaderle,

Yaşam bu ya alış kadere.

Gizli zevklerimizi, utancımızı, duygu damlalarını,

İkliminde yaşayamamışlığımızı,

Kendi halimize bırakılmamışlığımızı,

Düşün ve alış kadere.

Önce ağlarsın, sonra gülersin,

Harran’ın hüznü çökse de semaya,

Uzak değil alın yazın alış kadere.

Arzular, özlemler, tutkular, başarılar, hayaller,

Yıldızlara uzanıyorsa, yol yakın, alış kadere.

Balıklar akvaryumda, insanlar alın yazılarında,

Bireysel zaferler tarihlerde bekleşiyorsa,

Çeker bir gün ruhani güç, savrul ve unutma,

Bu kaçınılmaz yasa alış kadere.

İskender’in kılıcı, bir gün En Küçük İskender’in kalemi oluyorsa,

Günler günlere eklenip yıllara doluyorsa,

Üzüm ezilip şarap oluyorsa,

Yazgı de dostum alış kadere.', 'İçine bir kere çekmeye bak yaşamın soluğunu, İşte o an borçlusun, Unutma bir gün ödeyeceksin, Vereceksin bedenini, kalacak ruhun, Yüzleşecek...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/alis-kadere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağu', 'agu-elazigli-mustafa-kaya-ea3y2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ay parlak

içimi ısıtıyor

gökyüzü açık

yıldızları sayıyorum

göz kırpıp durdular

beni yanlarına çağırdılar

yorgundum

uykusuz ve gece ilerlemiş

ne yıldızlara gittim

ne ay bana düştü

açık bıraktığım kitaplar

altı çizili satırlar

ve buruşuk kağıtlar

günlerdir kapattım kendimi

içime kıvrılıp durmaktan

bir böceğe dönüştüm

arzularım serap oldu

ağu dediler içtiğime

altın tasta verdiler

bu şehirde

beni de ölülerinden yaptılar.

                                                                            mustafa kaya

                                                                            14.08.2005 / beylerbeyi', 'ay parlak içimi ısıtıyor gökyüzü açık yıldızları sayıyorum göz kırpıp durdular beni yanlarına çağırdılar yorgundum uykusuz ve gece ilerlemiş...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yazdım Şiirleri', 'sana-yazdim-siirleri-ahmet-ozyilmaz-o7115', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sana yazdım şiirleri

kelimeler titrerdi

geldi mi mısra başına

isminin bir hecesi

ahmet özyılmaz

nisan 2005 İZMİR', 'sana yazdım şiirleri kelimeler titrerdi geldi mi mısra başına isminin bir hecesi ahmet özyılmaz nisan 2005 İZMİR...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özyılmaz']::text[], 8.5, '{"poet":"Ahmet Özyılmaz","poet_slug":"ahmet-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sana-yazdim-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun', 'gidiyorsun-ahmet-ozyilmaz-h3r5l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gidiyorsun, avuçlarımdan kayıp

