INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-doruk-han-vueei', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün konuştum senle, yine sen yoktun

Öptüm seni saatlerce, ellerini hiç bırakmadım.

Yine gözlerinin güzelliğine hayal gücüm yetmedi

Kör kaldım...

Ama tüm gün hayatımda Sen vardın...

İlk kez burda duy istedim,

Çarpsın kalbim merak et istedim,

Kimbilir belki hiç umursamadın

Belki de heycanla bekledin

Her iki durumda da

Ben seni sevdim', 'Bu gün konuştum senle, yine sen yoktun Öptüm seni saatlerce, ellerini hiç bırakmadım. Yine gözlerinin güzelliğine hayal gücüm yetmedi Kör ka...', ARRAY['Türk Edebiyatı','Şiir','Doruk Han']::text[], 8.5, '{"poet":"Doruk Han","poet_slug":"doruk-han","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-611-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin Ver', 'i-zin-ver-doruk-han-lzjjy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İzin ver mutlu olalım seninle

Şüpheye yer verme yüreğinde

Duru güzelliğine yakısşır şekilde

Hadi al beni gönlüne

Limanlar bize uzak olsun

Mercanlara dalalım seninle

Hani orda denizin rengi

Gözlerin gibidir ya

Tüm renkleri yaşayalım seninle', 'İzin ver mutlu olalım seninle Şüpheye yer verme yüreğinde Duru güzelliğine yakısşır şekilde Hadi al beni gönlüne Limanlar bize uzak olsun Me...', ARRAY['Türk Edebiyatı','Şiir','Doruk Han']::text[], 8.5, '{"poet":"Doruk Han","poet_slug":"doruk-han","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/izin-ver-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmanın adı vurmaktır', 'susmanin-adi-vurmaktir-suna-aras-gcft5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Görmedi çocuk denizi

Üstünden tuzlu nehirler geçti

Anasının iki gözü.

Bütün sevinçler ölmek midir

Bütün aşklar yakılmış köy.

Kır namluları dişinde

Kurşun Ekmekte

Konuş

Susmanın adı vurmaktır

Savaşların dilinde.

Her duruşu tehlikeli bir imza

Asmıştı duvarına

Gitmede usta çocuk, dur

Ölüme beyaz bakma.

Ekmek dersen

Üşür elim çocuğum

Ölüm boynuna kalır

Taşınır akşama baban

Sesine akrep sokması

Korkusuna küheylan.

Sokakta yatar çocuklar

Birbirine sokulu

Çocuklar

Kaşıntılar içinde

Düşlere kül süzer

Yürekleri uykulu.

Bütün sergilerden geçirdim yüreğimi

Alıp götürdü beni bu kanın utancına

Göz suyuna çizilen o çocuk resimleri.', 'Görmedi çocuk denizi Üstünden tuzlu nehirler geçti Anasının iki gözü. Bütün sevinçler ölmek midir Bütün aşklar yakılmış köy. Kır namluları d...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/susmanin-adi-vurmaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Çiçeği', 'umut-cicegi-erdal-sumengen-tvst6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...Ve

Çiçekler açar umut bahçemde 

Ne zaman çizsem seni ufkuma

ozanlığım tutar...

Mısralar dökülür dudaklarımdan, 

Bir biri arkasına; ok gibi her yana.

Bencilleşir tutkum...

Sessizliğe dağılır suskunluğum

Sana sunulur; 

Dalga- dalga, bulut-bulut

Umut bahçemin şiir demet''i...

Sen olursun; 

Hayal dünyamda bulduğum,

Yitik umutlarımın eseri...', '...Ve Çiçekler açar umut bahçemde  Ne zaman çizsem seni ufkuma ozanlığım tutar... Mısralar dökülür dudaklarımdan,  Bir biri arkasına; ok gib...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sümengen']::text[], 8.5, '{"poet":"Erdal Sümengen","poet_slug":"erdal-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umut-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öptüğüm En Güzel Dudaklardı Gözlerin', 'optugum-en-guzel-dudaklardi-gozlerin-doruk-han-a07zx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Liseli çocuklar gibi şiir yazıyorum heycanla

Sen okuyacaksın ya akşam olup eve gidince

Belki gözlerin dolacak belki her dizede güleceksin bu serseriye

Ama bileceksin her seferinde, daha bir inanacaksın seni sevdiğime

Ne yaşadıysak seninle bulacaksın dizelerde

Biraz içip sarhoş olduğunda yüzünün halini görecek,

Güleceksin

Sabahım 3 ünde sahil boyu yürüdüğümüz günü hatırlayıp

Ürpereceksin sessizce

Ellerimi hiç bırakmadan saatlerce sohbet ettiğimiz geceyi anıp mutlu olacaksın

Seni ilk öptüğüm gün gelicek aklına, şaşıracaksın

Sanacaksın daha seni hiç öpmedim

Bir an düşüneceksin, sonra dudaklarında yaşattığın o eşsiz gülümsemeyi takınıp ellerin yosun gözlerine gidecek

O an anlayacaksın

Bu serserinin öptüğü en güzel dudaklar

Senin gözlerinde saklı  prenses', 'Liseli çocuklar gibi şiir yazıyorum heycanla Sen okuyacaksın ya akşam olup eve gidince Belki gözlerin dolacak belki her dizede güleceksin bu...', ARRAY['Türk Edebiyatı','Şiir','Doruk Han']::text[], 8.5, '{"poet":"Doruk Han","poet_slug":"doruk-han","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/optugum-en-guzel-dudaklardi-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceksin Diye Ölmedim', 'geleceksin-diye-olmedim-erdal-sumengen-m5rep', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen geleceksin diye, 

Bir önce görünüşünden Güneş''in

Kör karanlıkta açıldı gözlerim.

Seninle dolu, seninle dopdolu

Bir sokakta yürüdüm, gün boyu...

Sokak lambalarına inat,

Pırıl pırıldı gözlerim,

Ve de aktı parlaktı düşüncelerim...

Ve de; yaşıyorum işte.

Sen yoksun diye, ölmedim

Sen geleceksin diye...', 'Sen geleceksin diye,  Bir önce görünüşünden Güneş''in Kör karanlıkta açıldı gözlerim. Seninle dolu, seninle dopdolu Bir sokakta yürüdüm, gün ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sümengen']::text[], 8.5, '{"poet":"Erdal Sümengen","poet_slug":"erdal-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/geleceksin-diye-olmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın Dağ Başında Öleyim', 'birakin-dag-basinda-oleyim-zeynep-nilgun-gokceoz-35djo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangi kelime beni anlatır size,

Hangi nehir içimdeki coşkudur,

Neden yarınsız sevişmeler peşimde.

Karanfiller döşesem yüreğime

Maviye boyasam yıldızları

Güneşi kucağıma alsam

Dolasam kollarımı rüzgara

Tarifimidir bendeki benin,

Bunun için

Bırakın dağ başında öleyim…

Hangi türkü beni söyler,

Hangi kırık saz beni çalar,

Neden odam penceresiz.

Masum düşlerimi sersem üzerime 

Zincirlesem hayalleri bedenime

Zulümleri döksem kalemimle

Kazısam adımı beyaz mermere

Tarifimidir bendeki benin,

Bunun için

Bırakın dağ başında öleyim…

Hangi bahar benim için düştü toprağa,

Hangi hazan benim için ağladı,

Neden kuru yaprakları seviyorum hala.

Ay dokunana kadar yürüsem

Bıraksam yazgımı arkama bakmadan

Tebessümlere küssem sebepsiz

Sevmeleri ezsem korkmadan

Uğurlasam kuytu sokaklara kederleri

Çalsam zamanı sahte ölümden

Ruhumu açsam azrailin önüne

Tarifimidir bendeki benin,

Bunun için

Bırakın dağ başında öleyim…', 'Hangi kelime beni anlatır size, Hangi nehir içimdeki coşkudur, Neden yarınsız sevişmeler peşimde. Karanfiller döşesem yüreğime Maviye boyasa...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/birakin-dag-basinda-oleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başım Koyup Yatmaya', 'basim-koyup-yatmaya-erdal-sumengen-69thf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dermanım yok, derde deva katmaya 

Malım -mülküm yokki benim, satmaya

Alamadım bir post bile dünyada

Karatoprak, başım koyup yatmaya.', 'Dermanım yok, derde deva katmaya  Malım -mülküm yokki benim, satmaya Alamadım bir post bile dünyada Karatoprak, başım koyup yatmaya....', ARRAY['Türk Edebiyatı','Şiir','Erdal Sümengen']::text[], 8.5, '{"poet":"Erdal Sümengen","poet_slug":"erdal-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/basim-koyup-yatmaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-erdal-sumengen-kw7w2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arayıpta bulamadım

Sustun gönül, sustun gönül.

Yar yolunda olamadım

Küstün gönül, küstün gönül.

Uzak gidip, yakın sandım

Gündüz-gece, seni andım

Alev-alev, sende yandım

Coştun gönül,coştun gönül.

Gönül sana ne eyledim

Yoksa birşeymi söyledim

Yar yolunda çok inledim

Taştın gönül,taştın gönül.

Birileri dese bana

Düş yollara yine ara

Uzakmıyım yoksa sana 

Aştın gönül,aştın gönül.', 'Arayıpta bulamadım Sustun gönül, sustun gönül. Yar yolunda olamadım Küstün gönül, küstün gönül. Uzak gidip, yakın sandım Gündüz-gece, seni a...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sümengen']::text[], 8.5, '{"poet":"Erdal Sümengen","poet_slug":"erdal-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbette', 'elbette-dilba-selen-4pasl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüregimin dikenli sinirindan gectigin gün

Günesi yüregimde dogurdum 

Ay isigiyla yikadim sevgimi

Ve sende eridim 

Ey sevdasi kavgayi gerektiren sen

Saldiriyorum sana yildizlarin isigiyla

Derelerin takintisiz akintisiyla

Yüregimde demliyorum sevgimi

Yasadiklarinin farkli oldugunu düsünür her seven

Oysa binlerce yilin tekrari

Ama yinede fakir gönlüm

kendi sarayinda tek ask olarak yasar seni', 'Yüregimin dikenli sinirindan gectigin gün Günesi yüregimde dogurdum  Ay isigiyla yikadim sevgimi Ve sende eridim  Ey sevdasi kavgayi gerekti...', ARRAY['Türk Edebiyatı','Şiir','Dilba Selen']::text[], 8.5, '{"poet":"Dilba Selen","poet_slug":"dilba-selen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/elbette-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşamak Sanat', 'seni-yasamak-sanat-abdulkadir-karaca-j9ufg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak güneşim sen,ayım sen,yıldızım sen

Bu zindandan çıkarım yüreğime gelirsen

mecnun desinler bırak deli desinler bana

Mutlu olurum inan sevdalıyım ben sana

Hasret bahçesi benim,umut ağacı sensin

Belki tohumlarını üzerime dökersin

Çok oldu bir dost sesi duyulmuyor burada

Aşk hep güzel başlıyor,erilmiyor murada

Bir yerde kopukluk var,ayrılık var bir yerde

Bunu engelleyecek bir yürek lazım sende

Sen ekmeğim suyumsun,acımsın ateşimsin

Sen ayrı düşsek bile yine benim eşimsin

Haydi yar bekledikçe sönüyor  geleceğim

Haydi gel gelmiyorsan çare yok öleceğim

Bir gün buluşuruz yar tüm gidenlere inat

Seni yazmak zaten boş,seni yaşamak sanat

(14,08,2005)', 'Bak güneşim sen,ayım sen,yıldızım sen Bu zindandan çıkarım yüreğime gelirsen mecnun desinler bırak deli desinler bana Mutlu olurum inan sevd...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-yasamak-sanat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-safak-kilinc-xfhqu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk,yeniden doğmaktı,

Yaşarken yok olmak.

Aşk,tek başına çok olmaktı,

Bazen kalabalıklarda tek başına kalmak.

Aşk,bir rüzğardı uçurtmaya yol veren,

Bazen fırtınaydı darmadağın eden.

Aşk,gökyüzünde bir allıturnaydı,

Bazen karanlıkta bir yelan.

Aşk,devler savaşında galip gelmekti,

Olmadık bir gurura yenilmek

Aşk,bir maden ocağının dehlizlerinde cevher bulmaktı,

Bazen,o dehlizlerde kaybolmak.

Aşk,deniz üstünde yürümekti,

Bazen, aynı suda boğulmak.

Aşk,pazar yerinin sakinliğiydi,

Bazen sessizliğin pazar yeri.

Aşk,kutuplarda yanmaktı,

Volkanlarda donmak.

Aşk,düşlerinde görmekti sevdiğini,

Bazen yüzüne bakıp tanımamak.

Aşk,gözlerinde kaybolmaktı sevdiğinin

Kimi zaman yüzüne bakıp tanımamak.

Aşk,gökten yıldızlar toplamaktı,

Bazen yerle yeksan olmak.

Aşk,güneşin aydınlık ve sıcak yüzüydü,

Bazen kör bir kuyunun karanlığı.

Aşk,denizlerin yanmasıydı,

Çöllerin buz tutması çelik mavisi.

Aşk,gözlerde damla damla yaştı,

Dudaklarda tebessümler.

Aşk,kuş tüğünün hafifliğiydi,

Bıçak ağzının keskinliği.

Aşk,var oluştu.....

Aşk,kıyamet.....', 'Aşk,yeniden doğmaktı, Yaşarken yok olmak. Aşk,tek başına çok olmaktı, Bazen kalabalıklarda tek başına kalmak. Aşk,bir rüzğardı uçurtmaya yol...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ask-413-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizim', 'caresizim-orhan-kutlu-46m2u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çaresizim, çaresizim.

Seni sevmemek elimde değil,

Seni özlememek olur şey değil

Seni beklemek

Akıl alır gibi değil.

Çaresizim...

Sen bir ilkbaharsın

Ben ise kışımda,

Bir sevda yeli

Esse de başımda.

Umutsuzluk,

Çaresizlik gözlerimde

Gözyaşımda.

Çaresizim.

Veda etmek için

Kapanırken gözlerim,

Perde kapanırken girdin sahneye.

Ben mi erken oynadım

Sen mi geç kaldın.

Bir yanlışlık olmalı

Bu işte.

Çaresizim..

Daha baştan belli sonu

Bir sevda yaşıyoruz.

Sevgilerin içinde

Bu sevdayı

Ayrılığa taşıyoruz.

Çaresizim,

Çaresiz.

Orhan Kutlu', 'Çaresizim, çaresizim. Seni sevmemek elimde değil, Seni özlememek olur şey değil Seni beklemek Akıl alır gibi değil. Çaresizim... Sen bir ilk...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/caresizim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsenin bilmediği aşksın gönüllerde', 'kimsenin-bilmedigi-asksin-gonullerde-necla-i-lhan-a3392', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreği yanık anaların söylediği

Bir türküsün, ninnisin dillerde

Ozanın bağlamasındaki tellerde

Kimsenin bilmediği aşksın gönüllerde.

Bülbülün duyduğu tutkusun güllerde

Hüzünlü bir bakış gözlerde

Kederli bir anlamsın,dudaktaki sözlerde

Kimsenin bilmediği aşksın gönüllerde.

Karanlıktaki aydınlıksın gecelerde

Cümlesin, dilimlenmiş hecelerde

Sevginin yücesi yüreklerde

Kimsenin bilmediği aşksın gönüllerde.', 'Yüreği yanık anaların söylediği Bir türküsün, ninnisin dillerde Ozanın bağlamasındaki tellerde Kimsenin bilmediği aşksın gönüllerde. Bülbülü...', ARRAY['Türk Edebiyatı','Şiir','Necla İlhan']::text[], 8.5, '{"poet":"Necla İlhan","poet_slug":"necla-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimsenin-bilmedigi-asksin-gonullerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bahçesi', 'sevgi-bahcesi-orhan-kutlu-s7o05', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden seni görünce aklıma sevda geliyor,

Bu sevdada çekilen acılar

Her iki ucunda dünyanın.

Bir hayale sevdalanmak

Hayali acılar yaratmıyor nedense.

Var olduğunu bildiğimdenmidir nedir

Hayalini bile göremeden

Tasavvur ederek kaba çizgilerle

Bir şekli sevebilmek

Ve bu şeklin içindeki yüreği.

Ne zaman sevgi kokan bu

Bahçeye girsem

Gül kokularına karışmış kokunu duyarım

Kalp atışların

Yüreğimde atmaya başlar

Acıların acılarımı katlar

Hasretin hasretimi.

Belki bir başkasına ait yaşattığın sevdan

Belkide olmayan birine hasretsin 

Benim gibi

Olduğunu bildiğin halde

O bilmeden.

Sevmeyi sevmektesin belki

Yalanda olsa acılar çekmeyi

İstemektesin benim gibi

Bilirsin ki acılar

Yaşadığını hissettirir bedene

Olgunlaştırır insanı

Seni yok ettiğini zannetsende

Var edendir seni.

Ne zaman bu 

Sevgi kokan bahçeye girsem

Hep seni ararım

Buluncada işte böyle şairliğim tutar

Ve sana bu sevgi bahçesinden

Bir tutam sevgi gönderirim kelimelerle

Sen oldukça bu bahçede

Ben de olacağım.

Orhan Kutlu', 'Neden seni görünce aklıma sevda geliyor, Bu sevdada çekilen acılar Her iki ucunda dünyanın. Bir hayale sevdalanmak Hayali acılar yaratmıyor ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevgi-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk', 'yokluk-orhan-kutlu-kz9s0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana hangi acılarımdan bahsedeyim

Korktukça acıyan korkularımı

Anlayabilirmisin.

Korktukça büyüyen

Büyüdükçe beni silen acıları

Benle birlikte seni..

Ben neredeyim bilmiyorum

Bildiğin gibi hep aramaktayım kendimi.

Ama senin yerin belli

Acılarımın ucunda sen varsın

İçinde sen

Dışında sen

Beni silen senmisin.

Uzaklara dalıpta gözleri

Düşünür ya insan

Uzaklara dalamıyor gözlerim

Düşünemiyorum

Varlığın öylesine yer etmiş

Dünyamda.

Ya yüreğim

Bir diktatör var içinde

Başkasına yer vermeyen.

Öylesine mahkum, çaresiz..

Bir günün umududur yaşatan

Beyni,

Hala mücadele ediyorsa hücrelerim

Seni yaşattıkları içindir

İçlerinde.

Sen yok olduğunda onlar,

Onlar yok olduğunda sen yok olacaksın

Yokluk bizi bağlayan

Bu yoklukta sevdiğim.

Ne diyeyim.

Orhan Kutlu', 'Sana hangi acılarımdan bahsedeyim Korktukça acıyan korkularımı Anlayabilirmisin. Korktukça büyüyen Büyüdükçe beni silen acıları Benle birlik...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yokluk-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-sair-mavinin-karanligi-3akss', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mavi düşlerim oldu benim

 Oysa hiç ağlamadım düşlere inat

 Sonu gelmeyen yarınlarım oldu

 Oysa yarınların sonu yoktu

Yaralı dünlerim oldu benim

Karanlık bir yanlızlığa gebe yüreğim

Mavi yarınlara,yaralı dünlere hasret

Acı çekerek,gülerek,tembel hayalleriyle

Dolup taşan günlerim oldu benim

Ama hep ben ve günler

Aşksız zevksizzz

Tesellilerim oldu benim

Gelip gecici yaşanmışlarım

Bir şairin boşluğunu yaşıyorum

Bir boşluğun acısını

Ve bin acının yanlızlığını

Kaderimin altını çiziyorum

Ve bütün seslere inat 

Yine yaşıyorum...', 'Mavi düşlerim oldu benim  Oysa hiç ağlamadım düşlere inat  Sonu gelmeyen yarınlarım oldu  Oysa yarınların sonu yoktu Yaralı dünlerim oldu be...', ARRAY['Türk Edebiyatı','Şiir','Şair Mavinin_karanlığı']::text[], 8.5, '{"poet":"Şair Mavinin_karanlığı","poet_slug":"sair-mavinin-karanligi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-192-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldatmaca', 'aldatmaca-kenan-aydin-zd7i6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarda var olmuşluğun sırlarına ermeden, 

Yok oluşta gözlerim aşkın derinliğinde. 

Umut sofrası kurup tatlıları sermeden, 

Bitişinde sözlerim akın serinliğinde. 

Meçhule giden yolda yalnızca yürüyorum, 

Önümde sıra sıra engeller görüyorum, 

Aşmaya kudretim yok, gönlümü sürüyorum, 

Yorgunlukta dizlerim ufkun bitkinliğinde. 

Ya bırak beni artık, ya da kollarına al, 

Bitsin bu yalnızlığım, gitsin gölgeden hayal. 

Bir gelmişsin bir gitmiş, rüya değil de masal, 

Sönüşlerde közlerim, yarin bu hinliğinde. 

14.8.05 19:15', 'Yarda var olmuşluğun sırlarına ermeden,  Yok oluşta gözlerim aşkın derinliğinde.  Umut sofrası kurup tatlıları sermeden,  Bitişinde sözlerim...', ARRAY['Türk Edebiyatı','Şiir','Kenan Aydın']::text[], 8.5, '{"poet":"Kenan Aydın","poet_slug":"kenan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aldatmaca-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-orhan-kutlu-hjbhj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne yaptın bana

Ne yaptın söyle.

Aklımı aldın 

Kalbimi çaldın

Revamı söyle.

Onulmaz dertlere düştüm

Devamı söyle.

Bir acı çeşme ab-ı hayat

İçmemek elimizde değil,

Bana sunduğun saltanat

Esaret özgürlük değil.

Bile bile lades demek var ya

Deyişim senin yüzündendir

Bağlanıyorsam dünya''''ya

Sensiz gidemediğimdendir.

İşte böyle duygularım

Umutsuz biçare.

Sevmekten başka yolum yok.

Mecburum

Vuslatmı, bilmem

Belki bir başka bahara

Ama tek umudum

Sevene hep bahar

Orhan Kutlu', 'Ne yaptın bana Ne yaptın söyle. Aklımı aldın  Kalbimi çaldın Revamı söyle. Onulmaz dertlere düştüm Devamı söyle. Bir acı çeşme ab-ı hayat İç...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duygular-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başkası Olmadı ki..', 'senden-baskasi-olmadi-ki-orhan-kutlu-2zwy2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Suskunluğuma kelepçe vurdum

Gözlerime mil.

Yüreğime söz geçiremedim

Beynimle düşman oldular.

Bir yanda göğsüme inen yumruklar

Bir yanda başımı duvarlara vurmalar

Kimseye söz dinletemedim.

Bir yere gidiyorsam sana gidiyorum

Bir şey söylüyorsam sana söylüyorum

Ağlıyorsam sanadır

Seviyorsam yalnız seni seviyorum.

Senden başkası olmadı ki..

Anlatmaya çalıştım duygularımı

Mecnun gibi,

Mecnun sandılar

Gerçeği

Anlamadılar ki..

Anlamadılar....

Orhan Kutlu', 'Suskunluğuma kelepçe vurdum Gözlerime mil. Yüreğime söz geçiremedim Beynimle düşman oldular. Bir yanda göğsüme inen yumruklar Bir yanda başı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/senden-baskasi-olmadi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeneceksin', 'tukeneceksin-ali-fikri-karadeniz-xe4g2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimde şafak vakti doğduğun an

Güneşi uğurladım.

Katran karası gecelerimde,

Dertlerimle oturdum ağladım...

Teselli arıyorum, tecelli eden ayrılığıma,

Heni kızıl yapraklar düşer ya son baharımda,

Zincirler vurulmuş kara bahtıma,

Özlemin, hasretin gözümde tütmekte,

Bir sabah ki ölüm; sessizce gelmekte...

Zaman; 

Artık güç kalmadığı zaman,

Sen de bilirsin

Yağmurlar güneşi yıkadığı zaman,

Yüreğimde eriyeceksin

Ve volkanlar sönecek damarlarımda

Kara toprağın soğuk anında; 

Sen; tükeneceksin...!', 'Gözlerimde şafak vakti doğduğun an Güneşi uğurladım. Katran karası gecelerimde, Dertlerimle oturdum ağladım... Teselli arıyorum, tecelli ede...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tukeneceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Diyebilsem', 'bir-diyebilsem-orhan-kutlu-vurt3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç gün akşam oldu,

Kaç akşam gece

Ve geceler gün.

Sen mi bendesin

Ben mi sen de

Düşündüm durdum hergün.

Bazen sevgiliye hasret

Şiirlerde dolaştım elemli, üzgün,

Bazen salıverdim

Umarsızlık kuyularına benliğimi

Seni görene kadar.

Belki çok uzaklardaydım

Senden ayrı zamanlarda

Belki de bir o kadar yakın.

Mesafeler kısa olsa da uzak

Duygular anlamsız olsa da yakın.

Neden üstüme alınırım

Güneş gülümsediğinde yeryüzüne

Veya bir tomurcuk çiçeklendiğinde rengarenk.

Kimbilir aradığını ben sandığımdandır.

Farkında değilim gidiyorum demişmiydim

O yüzden geldim diyemiyorum.

Ya da her zaman yanında olduğumu

Ayak izlerine basarak peşinden yürüdüğümü

Sevindiğinde sevindiğimi çocukça

Ağladığında ağladığımı delice

Değil sana kendime bile söyleyemiyorum

Aslında seni ne kadar çok sevdiğimi.

Sensiz yapamadığımı

Sensiz olmadığını

Olmayacağını,

Olamayacağını...

Orhan Kutlu', 'Kaç gün akşam oldu, Kaç akşam gece Ve geceler gün. Sen mi bendesin Ben mi sen de Düşündüm durdum hergün. Bazen sevgiliye hasret Şiirlerde do...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-diyebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-ali-fikri-karadeniz-3z5hg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne ışığın sönsün ne de yıldızın,

Bulutlar mutlulukla üstüne yağsın,

Gül yüzünde gülücükler durmadan açsın,

Yüreğin nasılsa kutup yıldızı,

İçinden geçenler kalbine aksın...', 'Ne ışığın sönsün ne de yıldızın, Bulutlar mutlulukla üstüne yağsın, Gül yüzünde gülücükler durmadan açsın, Yüreğin nasılsa kutup yıldızı, İç...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dua-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissetmek Seni Herşeyde', 'hissetmek-seni-herseyde-orhan-kutlu-0humw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorum aynı şeyleri yaşamaktayız ikimiz

Anlattıkların,

Yazdıkların

Söylemek isteyipte söyleyemediklerin

Ve içinde yaşattığın her neyse

Adını bir sen bil

Bir de ben

İşte onu yaşıyoruz

Bu kalabalık içinde bir sensin aradığım

Yalnız sensin duymak istediğim

Bir sis bulutunun ardında

Sana ait bir yüz çizdiğim

Ve sensin sadece

sevmek istediğim

Nedense vazgeçemediğim.

Biliyormusun sadece sen varsın diye yazıyorum 

Artık bu şiirleri.

Sen olmasan ne mi olurdu

Bilmiyorum sır yüzlüm.

İsterimki hep olasın ve 

Sana yazayım sadece içimden geçenleri

Bir başkasından istemediğim.

Bazen sana kızıyorum sır yüzlüm

Tutsak ediyorsun

Hapsediyorsun özgürlükleri

Belli bir alanda,

Oysa zorlanmakta kelimeler

Bu dar alanlarda

Bir dene bir başka yeri

Çok şey var anlatmak istediğim.

Kulakların çınlarsa belli belirsiz zamanlarda

Adını sesleniyorsa birisi bir yerlerden

Ve bir bakış hissedersen üzerinde

Bilki seni düşünüyorum.

Beni bekletme

Yaşattığımız her neyse

Onun adına

Onu anlamak üzere

Olurmu sır yüzlüm

Yalnız sen varsın beklediğim.

Orhan Kutlu', 'Biliyorum aynı şeyleri yaşamaktayız ikimiz Anlattıkların, Yazdıkların Söylemek isteyipte söyleyemediklerin Ve içinde yaşattığın her neyse Ad...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/hissetmek-seni-herseyde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidemedim, Sensiz Olmuyormuş', 'gidemedim-sensiz-olmuyormus-orhan-kutlu-fta4f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte gör

Ayaklar altına aldım gururumu

Hiç gitmeyen ayaklarım

Sana getirdiler beni

Sen istemediğin halde.

Haykırışlarım sürecek elbette

Duyana kadar sağır sultan

Sevdiğimi seni

Sen duymasan bile.

Haykıracağım

Duymamazlıktan gelsen bile.

Belki bir kez daha denerim gitmeyi

Sen yine bir şeyler yazarsın

Sevgiden ve giden sevgililer hakkında

Ben biraz mutlu olurum

Yazdıklarını üstüme alınıp

Ve seni düşünmekten vazgeçmem

Her zaman olduğu gibi.

İşte gör

Gitmeden olduğum gibi yanındayım işte

Değişen hiç bir şey yok

Bakalım daha ne kadar sürecek

Sana yolculuğum

Ya sen

Mutlumusun gelişimden.

Her gün ismini aradım 

Senden bir haber

Bir söz bugüne kadar.

Seni buldum ve geldiğimi söylemeye geldim

Bil yeter

Başka bir şey varsa kısmetimde

Şükrederim

Ne gelirse Rab''''bimden ve senden

Sır yüzlüm.

Orhan Kutlu', 'İşte gör Ayaklar altına aldım gururumu Hiç gitmeyen ayaklarım Sana getirdiler beni Sen istemediğin halde. Haykırışlarım sürecek elbette Duya...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gidemedim-sensiz-olmuyormus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Bu Kadar', 'benden-bu-kadar-orhan-kutlu-x34mf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim, 

Nerede,

Nasıl,

Ne arar.

Laf bitti,

Ömür bitti,

Ben bittim

Benden bu kadar.

Orhan Kutlu', 'Kim,  Nerede, Nasıl, Ne arar. Laf bitti, Ömür bitti, Ben bittim Benden bu kadar. Orhan Kutlu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benden-bu-kadar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elin Adamı', 'elin-adami-huseyin-alan-r94wt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimde

Parmaklarımın ucunda

Binlerce söz

Döküşlerde hayal denizine

Dilimde çözülen

Kelimeler anlatır

Ötelerden gelen

Umutsu bakışlara

Ilık zamanların soğuk örtüsünü

Bir melek açarken kapıları

Umutlara ışıl ışıl

İşte o güzel söz

Her harfinde ayrı bir heyacan

Raks ediyor

Bütün deruniliğiyle...

Bir mağrurluk 

Gözlerimde seyrederken

Düşen hayallerime

Bir mahçupluk 

Üşengeç tavırlarda

Kızarır yüzümde

Donan yürek elintisi

Çatırdadı birden gök

Kaleme yığılan sözler içinde

Tufanını yaşadı ruh

Düşlerden sıyrılarak

Kurgusuna geldi sevdanın

Közlerine bulanarak

Yürek sevgi arıyordu

Eller ulaşmak istercesine 

Tir tir titriyordu

Hisler duygulara atılmak

Kana kana içmek için

Sevgiyi

Gelen loşluk deryasında

Çırpınırcasına...

İndi hece hece

Izdıraba gidiş

Çizildi kalem kalem 

Benlikte umarsız kalışlar

O an koptu aklımın dibinde

Sevginin urganı

O engin sezişlerden

Kayıplara karıştı

Umuttan örülü yürek

Söküp atmak 

Hücremin her zerresinden 

İsmini

Bir yabancı gibi

Bakmak çaresiz bakışlarla

Gelmemiş sevdayı tutmak

Sabırla bekleyerek...

Bitmeyen bir esinti var

Kucağımda tuttuğum

Bu süsten ibaret yalan dersen

Serilip kalbime iner

Eteş topu yüreğin

Hala ruhum şimşeklerin altında

İnliyor yıkıntılı dilinde

Sen ey! dilber

Nice aylar doğdu

Nice anlar kandillerde aydınlandı

Bir bilsen semalardan inen yağmurların

Yüreğimi ıslatırken çıkardığı feryadı

Bir bilsen sensiz kalan 

Öksüz gecelerimi

Haşyetle donan

Renk renk solan

Hayat dünyamda saklı tuttuğum

Sevdayı anlasan 

Dikersin gözlerini

Göz bebeklerimin 

Derinlerindeki yanan umuda

Pek bunaldım

Sevgi vermeyişine

Cehennem azabı çektirişine

Ufuklarda doğan hicrandayım

Çırpınışdayım 

Hüzünlerdeyim

Bütün ecramıyla sinse

Yüreğime adın

Orda hayat bulacak

Yanacak,kavrulacak

Habersiz kıvranacak

Harab olmuş

Enkazlara dönen yabancı

Kah açılır veda yolculukları

Kah biter gizlerin 

Bulutsu elleri

Değer lanetinin gözleri

Zincire vurulmuş

Yaban yürekte

Sırtımı dayadım 

Geceye...

Düşüncelere dalarak 

Gözlerimi verdim gökyüzüne 

Çaresiz kalışını 

Onun gözünden göreyim diye

Üstüne bindim zamanın

Beni sana ulaştırması için

Kırılan ruhumu

Sevgimi

Tanıman için...

O senin yazgın

Senin yüreğin

Sevgin 

Yaşamın

Aklında hücrelerin

Izdırabında göz yaşların

Her gün güneşin anlında

Gezinirim

Belki bulurum izini

Sıcaklığına sarılarak

Gülen karanlığa...

Bırakıp meydanı

Giderken batan kızıllık

Kalır yapayalnız

Terkedilen güneş

 Dili çözülür gözlerinin

Uzun kirpiklerine dökülür

Hüznün fırtınalı sessizliği

Biter can

Kesilir yamalı pantolonumdan

Adın...

İki dudağının arasından

Acı bir söz çıkar

''ELİN ADAMI! ! ! ''...', 'Elimde Parmaklarımın ucunda Binlerce söz Döküşlerde hayal denizine Dilimde çözülen Kelimeler anlatır Ötelerden gelen Umutsu bakışlara Ilık z...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":127,"source_url":"https://www.antoloji.com/elin-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-orhan-kutlu-1x24r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yanda uykusuzluk bedenimi uyuşturan

Diğer yanda sen 

Böylesine meşgul etmesen zihnimi

Kimbilir kaçıncı rüyasındaydım gecenin

İçimden bir ses gidip yatmamı söylerken

Başka bir ses sakın ha diyor

Gitme 

Ya uyursan

Vazgeçersen uykunda onu düşünmeyi

İhanet olmazmı aşkına

Ya unutmaya başlarsan onu.

Bilsemki her anında seni göreceğim

Uyurum uyanmam bir daha

İçine daldığım rüyadan.

Gece zifiri karanlık

Aklımda sen,

Gönlümde sen,

Ruhumda sen

Aslın yok senin be gülüm

Nedir bu 

Kendim için yazdığım bir oyunmu

Kimi arıyorum

Kime sesleniyorum

Ses vermedikten sonra sesime

Kime koşuyorum böylesine çılgın gibi

Bir adım bile gelecek biri olmadıktan sonra

Kimi bekliyorum böyle.

Ah ihtiyar gönlüm

Kavuşulmaz aşkların

Kabuğu zırh olmuş bedenine

Fuzulinin acılarını çeker olmuşsun

Elifin kağnısı gibi.

Hem gerçek var aşkında

Hem serap

Gerçek olan acıların

Ya gerisi.

Çek bedbaht gönül

olmayan aşkın gamını

Yaşa ve yaşat kalbinde

gamlı hicranını

bilmemki bu gamda

bilmemki bu hicranda

ne buluyorum

Heyhat ey sevilen 

Yüzünü bilmediğim güzel

Nerdesin nerde

Seni arıyorum

Orhan Kutlu', 'Bir yanda uykusuzluk bedenimi uyuşturan Diğer yanda sen  Böylesine meşgul etmesen zihnimi Kimbilir kaçıncı rüyasındaydım gecenin İçimden bir...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/seni-ariyorum-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamayacağım', 'aglamayacagim-ali-fikri-karadeniz-tcne5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlamayacağım; 

Söz ağlamayacağım kara bahtıma.

Birazdan yıldızlar da çekilecek,

Katran karası gecelerimde

Senin hasretinle eriyeceğim...

Bak yine bir ayrılık şarkısı söylüyor rüzgar

Mabedim dua''larımla dolar

Dolar da durduramam kalbimi

Sevgim boğar bırakır beni

Yıkılırım hiç yıkılmadığım gibi...

Yarabbi; 

Yarabbi yüreğim alev alev yanmakta

Olsun, bu beden kül olsa da

Sensizliğimle dertleşeceğim

Belki biraz sitem etse de kalbim

Yine de, güneşin her doğuşunda Seni Seveceğim...', 'Ağlamayacağım;  Söz ağlamayacağım kara bahtıma. Birazdan yıldızlar da çekilecek, Katran karası gecelerimde Senin hasretinle eriyeceğim... Ba...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglamayacagim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usandım Be Gülüm', 'usandim-be-gulum-orhan-kutlu-5y814', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç aklıma gelmez sanırdım

Gün gelirde senden usanacağım.

Bu vurdumduymazlığın

Oyuncak edişin elinde

Sevdaları

Bir pula dönüştürmen

Değer ölçülemez duyguları

Hiç aklıma gelmezdi usanacağım

Sağolasın be gülüm

Sayende

Bir gün seni unutacağım

Orhan Kutlu', 'Hiç aklıma gelmez sanırdım Gün gelirde senden usanacağım. Bu vurdumduymazlığın Oyuncak edişin elinde Sevdaları Bir pula dönüştürmen Değer öl...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/usandim-be-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidiyorsun Diye', 'sen-gidiyorsun-diye-orhan-kutlu-jr7ow', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün bile karardı,

Gökyüzü ağlamakta hala,

Kaldırımlar bitkin, yorgun.

Herkeste, herşeyde

Hasretin telaşı.

Sen gidiyorsun diye.

Ayrılık ayrılıktır

Zaman kısada olsa.

Ayrılık hasret,

Hasret ise özlem.

Tüm özlemler sana

Sen gidiyorsun diye.

Bugün sana sallanacak mendiller,

Sana söylenecek güle güle''''ler,

Senin için kokacak bugün

Karanfiller, güller.

Senin için yaşanacak sevgiler

Sen gidiyorsun diye.

Hoşkal sevdam,

Gönlüm kırık ayrılıktan

Yüreğim buruk, ezik.

Bir sıkıntı

Bir keder.

Candan bir sarılış sana

Orhan Kutlu', 'Gün bile karardı, Gökyüzü ağlamakta hala, Kaldırımlar bitkin, yorgun. Herkeste, herşeyde Hasretin telaşı. Sen gidiyorsun diye. Ayrılık ayrıl...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-gidiyorsun-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Yine', 'sen-yoksun-yine-orhan-kutlu-kzaua', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana baktım

Yine yoksun.

Ayak izlerin var sadece günler öncesinden.

Olmadığın bir yerde olmak

Ne heyecan verir 

Ne de bir umut sevdadan yana.

Eğer gelirsen olmadığım bir anda,

Ya da gitmişsem hiç gelmeyeceksin diye

Geldiğini sal dört bir yana.

Hemen gelirim 

Gerçi ne değiştirir gelişim bilinmez ama

Böyle sürer gider zaman

Sürer gider içimdeki kandırmaca.

Orhan Kutlu', 'Sana baktım Yine yoksun. Ayak izlerin var sadece günler öncesinden. Olmadığın bir yerde olmak Ne heyecan verir  Ne de bir umut sevdadan yana...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-yoksun-yine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilirsin Değil mi Kimin İçin Bu Hüzünler (Son)', 'sen-bilirsin-degil-mi-kimin-i-cin-bu-huzunler-son-orhan-kutlu-xbbph', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aradığımsın,

Kaybolan umutlarımın ardında,

Beklediğimsin,

Bitmeyen düşlerimin arasında

Ve hiç gelmeyensin.

Seni nasıl beklediğimi

Hiç bilmeyensin..

Seni düşündüğüm zaman

Evreni sarar ruhum,

Varlığını hücrelerimde hissederim.

Gözlerimi kaparım

Bir huzur dıoldurur içimi

Açtığımda

Seni dünden fazla severim.

Sen varsın diye yaşıyorum

Katlanışımniye

Yalan dünyanın kahpeliklerine.

Hem hüzün bulurum

Hem ferahlık

Daldığımda gözlerinin

Derinliklerine.

Sen yoksan,

Aşk yok, sevda yok.

Ne hüzün ne mutluluk

Ne de gönlüme yüklenen sabır

Sen yoksan söyle

Seninle bir giderim

Alemde ne kalır.

Sensiz bir dünya yerine

Var olduğun bir dünyada

Sensizliği tercih ederim.

Gitme...

Orhan Kutlu', 'Aradığımsın, Kaybolan umutlarımın ardında, Beklediğimsin, Bitmeyen düşlerimin arasında Ve hiç gelmeyensin. Seni nasıl beklediğimi Hiç bilmey...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-bilirsin-degil-mi-kimin-icin-bu-huzunler-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilirsin Değil mi Kİmin İçin Bu Hüzünler 2', 'sen-bilirsin-degil-mi-ki-min-i-cin-bu-huzunler-2-orhan-kutlu-2oytm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen kaybolur gider usumdan kelimeler,

İki damla yaş düşer gözlerimden

Suskunluğumun ellerine.

Çoktan yangın yerine dönmüştür

Gönlümde çarşı pazar.

Bir yerde ızdırabı sessizliğin

Bir yerde sen.

Kendini hissettirir sensizlik azar azar.

Bir gün selamı duyarsın müezzinin sesinden

Gidişim ya sabah olur ya da öğle vakti.

İstemem ne akşamı ne de yatsıyı.

Güneşli güzel bir günde kılınsın namazım

Hayıflanmasın gücenmesin cemaat.

Senin sevdiğinden olsun kabrimde çiçeklerim.

Gittiğim yerde de beklerim

Seni beklemekse alın yazım.

Yaşadık mı, yaşamadık mı

Tamam mıydı yoksa yarım mı kaldı

Yaşadıklarımız.

Belki anlaşılırdı anlatılsaydı

Anlatamadıklarımız.

Orhan Kutlu', 'Bazen kaybolur gider usumdan kelimeler, İki damla yaş düşer gözlerimden Suskunluğumun ellerine. Çoktan yangın yerine dönmüştür Gönlümde çarş...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-bilirsin-degil-mi-kimin-icin-bu-huzunler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanıdığım Gün', 'seni-tanidigim-gun-ali-fikri-karadeniz-07fkv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni tanıdığım gün,

Yağmurla başladı mutluluklar

Kan kırmızı gül tarlalalarını

Damla damla sulardı göz yaşlarım

Bu şehrin üzerindeki pamuk bulutlar,

Beni getirirdi Sana

Elimde yüreğim

Sen uyumadan geri dönmezdim

Öperdim, koklardım

Yine de doyamazdım

Sen benim Canım...

Seni tanıdığım gün

Gökkuşağının yedi rengi dolardı dünyama

Ebruli hanımeli sarardı bedenimi

Sen dağlardın gözlerimi, kalbimi, yüreğimi

Sen; Sen Canımıniçi...

Seni taıdığım gün; 

Mutluydum; hemde dünyanın en mutlu insanı

Yıkılmaz dağım derdim

Çınardım, dalları yedi cihana bedel

Her gün yaprak yaprak açar

Ve üzerine yazardım

Seni Seviyorum Birtanem...

Seni tanıdığım gün,

Her güneşin doğuşunda,

Sen doğardın dünyama

Çiçekler Sen açar,

Sen kokardı dünyam.

Geceyi Senin hasretinle boyardım

Sen Doyumsuzum, benim Sonsuzum...

Seni tanıdığım gün,

Ve Seni kaybettiğim gün

Ne güneş bir daha doğdu

Ne bulutlar beni getirdi Sana

Gökkuşağını çalmışlar ve gülleri soldurmuşlar

Acılar bedenimi sararken

Tam şuramdan; can evimden vurmuşlar...

Senin olsun; mutluluğum sadece Senin

Hüzünlerim ve Sevdam bırak bende kalsın

Gönlümün avuntusudur aslında

Böyle başı boş,

Böyle virane

Böyle yağmurlu karanlıklar....!', 'Seni tanıdığım gün, Yağmurla başladı mutluluklar Kan kırmızı gül tarlalalarını Damla damla sulardı göz yaşlarım Bu şehrin üzerindeki pamuk b...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/seni-tanidigim-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fakir çapkın', 'fakir-capkin-ahmet-kesici-x5hj5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hay Allah,   yine aşık olduk iyimi.

İşin yoksa sabaha kadar onu düşün şimdi.

O kadar da kendi kendime söz vermiştim,

Kimseye bu kadar bağlanmayacağım diye.

Kabahat bende değil ki,gönlümde.

Kapılıyor her gör düğüne.

Ya bırakıp giderse.? 

Ya bu da diğerleri gibiyse.? 

Hiç düşünmeden seviyor işte.

Zaten bir kere sevdik evlenip gitti.

Diğeri geçen ay sözlendi.

Gerçi benim gönlüm üst katta ki Zeynep deydi de,

Onu da babası vermedi.

Yok canım,  bizde hayır yok.

Ne yapsın kızlar ben gibi fakiri.

Parasızda bir şey olmuyor ki.

Siz bilmezsiniz,

Bu para yüzünden ellere kaptırdım en büyük aşkım Aysel’i.

Zavallı kızın aklını çelmiş zengin birisi.

Hayır,   Aysel yirmi yaşında.

Adam kırk iki.

İstemeye gelmişler geçen akşam. 

Babası da hayır dememiş iyimi.

Görünce kapıdaki Mersedesi,hiç hayır der mi.? 

Bizim neyimiz var.

Murat yüz yirmi dört. 

Mersedesin dört tekeri.

Ah Aysel,

Hiç beklemezdim senden böyle bir şey.

Burnun havada,   gözün yükseklerdeymiş meğer.

Ya sen Ayşe,

Hiç yoktan kıydın gençliğime.

İnandın olmadık şeylere. 

Ben senden başkasına bakarmıydım be.

İşte böyle dostlar.

Bunlar benim hayatımı böyle kararttılar.

Neyse ki bunlar mazide kaldı.

Daha fazla anlatıp da açmayalım kapanmış yaraları...', 'Hay Allah,   yine aşık olduk iyimi. İşin yoksa sabaha kadar onu düşün şimdi. O kadar da kendi kendime söz vermiştim, Kimseye bu kadar bağlan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/fakir-capkin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön', 'don-huseyin-alan-s0pqw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tehammül yok arzulara

Olsun yokların gidişleri

Sevgiye katılsın huzurlar

Ne garip aşkta fakirlik

Cisimleşmiş talihin yortusu

Bir rana tulu adiyor apaçık

Göz hayata yummuş kapaklarını

Hüzün kuruntularına karışıyor

Kalp havuzunda...

Taşlaşmış sözler nefretle

Hançerli acı ciğerimde

Yürek hortluyor ağlayışları

Dikenler batıyor düşlerime

Ateş sahipsiz dipsizlik

Herşey sonda hiçten arız

Yağmalı, bencil ürperti

Darmadağın kalp sevgisi

Yalnız ve yapayalnız akıyor sırlar

Yağmur ıslatıyor

Kör hayalleri

Dürtüyor imgesiz sevdalar

Zaman kırılıyor 

Dumanlanıyor mutluluklar

Yalan gönüldeki sevgisizlik

Temkinli saniyeler

İçinde gezişlerde korkular

Dön yaldızlı gecenin 

Destansı anlarına....', 'Tehammül yok arzulara Olsun yokların gidişleri Sevgiye katılsın huzurlar Ne garip aşkta fakirlik Cisimleşmiş talihin yortusu Bir rana tulu a...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/don-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haftaya Sessizce Şehrine Geleceğim', 'haftaya-sessizce-sehrine-gelecegim-umut-gungor-b5ryk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haftaya sessizce şehrine geleceğim,

Hiç rahatsız olma sen öylece döneceğim,

Hasreti yüreğimde derine gömeceğim,

Duyupta sakın ha davete zahmet eyleme.

Seni arayacağım haberin olmadan,

Uzaklardan bakacağım gözler dolmadan,

Döneceğim şehrime yine akşam olmadan,

Duyupta sakın ha davete zahmet eyleme.

Sen şiirlerine devam et kaldığın yerden,

Duyacak olur isen geldiğimi bir yerden,

Rahatça bir nefes al olurmu derinden,

Duyupta sakın ha davete zahmet eyleme.

Sazında aynı havaları çalma her zaman,

Kuşlar pencerene konmaz her zaman,

Bülbüllerin de aşka çağrı yapmaz her zaman,

Duyupta sakın ha davete zahmet eyleme.', 'Haftaya sessizce şehrine geleceğim, Hiç rahatsız olma sen öylece döneceğim, Hasreti yüreğimde derine gömeceğim, Duyupta sakın ha davete zahm...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haftaya-sessizce-sehrine-gelecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisizliğe', 'sevgisizlige-huseyin-alan-zgmld', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzün yumakları sardı yüreğimi

Paramparça,darmadağın

Fırtınalar koptu

Acımasız

Bütün sözler dikenli yalan

Sevmeler talan

Gerçek içmek

Gerçek solumak

Gerçek istemek

Yasak sana...

Sevgi döner durur

Döner savrulur

Yıkar geçer

Ezer gider

Arkasına bakmadan

Kahpece...

Adın kalır dilimde

Dilimin ucunda

Kalemimde

Kalemimin ucunda

Serzenişlere itilir hayat

Aşk bayat

Sevmek  vasat

Delirmiş aklım seni düşünmekle

Kaçık kalbim

Sevişlerine kapısını açmakla

Bu ne bela ki

Alır kendini kendinden

Ruhunu

Her şeyini...

O da bir gün tadacak

Yalnızlığı

Sevgisizliği

Ölümü

Sonsuza dek...', 'Hüzün yumakları sardı yüreğimi Paramparça,darmadağın Fırtınalar koptu Acımasız Bütün sözler dikenli yalan Sevmeler talan Gerçek içmek Gerçek...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevgisizlige-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-huseyin-alan-uwvj7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevginin haritası çizilsin

İrem ülkesine varmak için

Bütün kainat haykırsın

Elimde kalsın güneş kadar sıcaklığın

Lal olsun gece sevgimin çığırında

Ağlıyor gök

Mavi gözleriyle

Başını çevir

Börtü böceklerinin uçuşuna

Ahengle dans edişine 

Konuşuna çiçeğe

Yüreğine yandım

Yüzünün derin izlerine

Gözlerinin ılık bakışına 

Sana 

Adsızlığına...', 'Sevginin haritası çizilsin İrem ülkesine varmak için Bütün kainat haykırsın Elimde kalsın güneş kadar sıcaklığın Lal olsun gece sevgimin çığ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adsiz-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUSURLUK SUS- UR-LUK ta Kaza! ...', 'susurluk-sus-ur-luk-ta-kaza-asik-sahturna-luir8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susurlukta bir kaza

Oyun düştü cambaza

Kaza güme gitmesin

Aman şoför bas kaza

Kamyon düzene çarptı

Sistemler aids kaptı

Figüranlar oynarken

Baş aktör hile yaptı! 

Belli zulümün başı

Oynatır gözü kaşı

Vampirler karanlıkta

Batırır kanlı dişi.

Kocadağ duman oldu

Kurtlara kervan oldu

Mazluma zehir saçtı

Zalime derman oldu

Nakarat:

Belli zulümün başı

Oynatır gözü kaşı

Vampirler karanlıkta 

Batırır kanlı dişi! ...

Şah Turna sır patladı

Çatlı çatı çatladı...

Bucak kenti de geçti

Ta avrupayı atladı! ...  Nakarat:...

Söz ve Müzik: Aşık Şah Turna  Ozan Şiar 

Düzenleme-aranje: Ozan Şiar

''Dumanlı Ödül'' ''Barış Anası'' albümü..Susurluk klibi

''Şakıyan Turna-Şahturna'' kitap  Bir çok dergi, kitap ve gazeteler.

ŞAHTURNA Kültür Sanat Evi www.sahturna.com

ŞİAR''IMIZ Sanat, Kültür, Toplum Forum

www.siarcan.com', 'Susurlukta bir kaza Oyun düştü cambaza Kaza güme gitmesin Aman şoför bas kaza Kamyon düzene çarptı Sistemler aids kaptı Figüranlar oynarken ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Şahturna']::text[], 8.5, '{"poet":"Aşık Şahturna","poet_slug":"asik-sahturna","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/susurluk-sus-ur-luk-ta-kaza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer ararsan', 'eger-ararsan-suleyman-yavuz-0nfmi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün arasan beni

Maziye bak 

Bulursun belki

Eğer mazide kalanlar

Üzer ağlatırsa seni

Resmime bak 

Dindirir akan yaşlarını belki

Eğer anarsan bir gün adımı

Hatırlarsan sana olan aşkımı

Ve ararsan beni 

Bekleme bulmayı 

Bulsan bile beni

İnan dönemem

Ama görmek istersen

Ben bir tepenin başında 

“Severken ölen ölürcesine 

seven ben bir aşık ben bir 

deli sevdalıyım” 

Yazar mezar taşımda

Öylece seni beklemekteyim 

Belki ziyaret edersin diye

Bir dua edersin diye', 'Bir gün arasan beni Maziye bak  Bulursun belki Eğer mazide kalanlar Üzer ağlatırsa seni Resmime bak  Dindirir akan yaşlarını belki Eğer anar...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eger-ararsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimle Kavgam', 'kendimle-kavgam-halil-kesken-jy0dj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görme benim guru dolu gezmemi

Feleğin gözünde yoktur değerim

Ne ben onu çözdüm, ne de o beni

Bir çimdik atarım, bin yumruk yerim

Yıllar yılı sanki ben bu hayatın

Şamar oğlanı mı bilmem ki neyim

Az mı darbesini yedim bu atın

Bir çelme atarım, bin çifte yerim

İnandım her söze ağızdan çıkan

Kazanır derlerdi ilk şutu atan

Her zaman benimdir zararlı çıkan

Bir fiske atarım, bin sille yerim', 'Görme benim guru dolu gezmemi Feleğin gözünde yoktur değerim Ne ben onu çözdüm, ne de o beni Bir çimdik atarım, bin yumruk yerim Yıllar yılı...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendimle-kavgam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Aşkım', 'benim-askim-nurdan-unsal-3w1if', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen sen diye yazdıklarım sen değilsin

Yanlış anlama...

Ağlamalarım sana değil

Sen üstüne alınma...

Ben seni yazmakla 

Seni yazıyor değilim

Senmişsin gibi algılama...

Sen demelerim lafın gelişi

Sen sen olmaktan çıktın çoktan

Ben''im bu aşk artık anla...', 'Sen sen diye yazdıklarım sen değilsin Yanlış anlama... Ağlamalarım sana değil Sen üstüne alınma... Ben seni yazmakla  Seni yazıyor değilim S...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Ünsal']::text[], 8.5, '{"poet":"Nurdan Ünsal","poet_slug":"nurdan-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/benim-askim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsafsız Yıllar', 'i-nsafsiz-yillar-halil-kesken-8xowc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün diğerinden dahada ezik

Saçımıza dolar bembeyaz kıllar

Her gün yüzümüze yeni bir çizik

Attıkça atıyor insafsız yıllar

Kendisi biniyor tek atımıza

Bittikçe gülüyor takadımıza

Tükenmez dertleri hayatımıza

Kattıkça katıyor insafsız yıllar

Seneler herkesi dertlere salmış

Ne yaşama gücü, ne umut kalmış

Hüsran girdabına bizi de almış

Battıkça batıyor insafsız yıllar

Dönüyor en küçük ızdırap dağa

Acımaz düşecek yeşil yaprağa

Hepimizi tek tek kara toprağa

Sattıkça satıyor insafsız yıllar', 'Bir gün diğerinden dahada ezik Saçımıza dolar bembeyaz kıllar Her gün yüzümüze yeni bir çizik Attıkça atıyor insafsız yıllar Kendisi biniyor...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insafsiz-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoraki Aşk', 'zoraki-ask-halil-kesken-drng5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İyi kötü sevgilim var

Zalim bir kuldan ibaret

Aşkımızın ateşiyse

Sönük bir külden ibaret

Bilmeyen kalmadı bunu

Ümitlerin geldi sonu

Kaderden tek kaçış yolu

Kırık bir saldan ibaret

Mutluluk var bir kaç anlık

Bıktırdı bu perişanlık

Geleceğimiz karanlık

Çıkmaz bir yoldan ibaret

Her an acı, her an çile

Uçurumdan düştük bile

Bak şu sarıldığım ele

Çürük bir daldan ibaret

Moral bozuk, surat asık

Ben manen, o madden aşık

Ümidimiz olan ışık

Yalan bir faldan ibaret

Şarkımızın kısık sesi

Ne söz belli, ne lehçesi

Her şeyimiz aşk bahçesi

Solmuş bir gülden ibaret

Artık kalmamış gücümüz

Bitip tükenmiş ömrümüz

Umman sanılan gönlümüz

Koca bir çölden ibaret

Yıldönümü neyin nesi

Yıkık dökük aşk hanesi

Aşkımızın ilk senesi

Kötü bir yıldan ibaret

Ayrılırız unutulur

Kalplerimiz huzur bulur

Zoraki aşk böyle olur

Tatsız bir baldan ibaret', 'İyi kötü sevgilim var Zalim bir kuldan ibaret Aşkımızın ateşiyse Sönük bir külden ibaret Bilmeyen kalmadı bunu Ümitlerin geldi sonu Kaderden...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/zoraki-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir İçin- 1', 'siir-i-cin-1-mehmet-kiyak-40rl2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sevdadır şiir kalplerde,

Bilinmez hangi zamanda,nerde,

Kimi bir şehirde,kimi bir köyde,

Yaşıyor,şimdi dizelerde...

Kimi ayrılıklarda,kimi kavuşmada,

Kimi özlemde,kimi feryatta...

....

Yaşıyor,şimdi şiirlerde...', 'Bir sevdadır şiir kalplerde, Bilinmez hangi zamanda,nerde, Kimi bir şehirde,kimi bir köyde, Yaşıyor,şimdi dizelerde... Kimi ayrılıklarda,kim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kıyak']::text[], 8.5, '{"poet":"Mehmet Kıyak","poet_slug":"mehmet-kiyak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siir-icin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kanadı Kanatlarım', 'kanadi-kanatlarim-talip-kaplan-5bv7x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben seni sevdim be,

Çok sevdim...

Beyaz kanatları olduğunu gördüm

Yürek dediğimizin

Uçuşunu seyrettim dört kanadın

Kavuşmasındaki ateşi gördüm

Şimşeği gördüm

Yangın yangın alevi

Erimeyi

Kömürdeki katılığa dokundum

Siyah bir yıkılıştı

Tüm birikimim...

Ben seni sevdim,

Çok sevdim...

Asılıp durma kanatlarımı

Kalbim sökülecek

Uçuşumu kıpkırmızı gördüm

Ben o kanda, aşkı öldüm

Ben seni sevdim,

Çok sevdim...

Kırmızı kanatlarla uçulmuyor

Ayaklarında sürünerekte olsa

Ayakkabılarından bile uzakta da olsa

Ben Seni Seviyorum,

Çok Seviyorum,,,

(15 Temmuz 2004)', 'Ben seni sevdim be, Çok sevdim... Beyaz kanatları olduğunu gördüm Yürek dediğimizin Uçuşunu seyrettim dört kanadın Kavuşmasındaki ateşi görd...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kanadi-kanatlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüseyin, Bedreddin, Yunus, PirSultan', 'huseyin-bedreddin-yunus-pirsultan-ozan-sah-turna-agdasan-7056k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her zaman mazlumun yanında olan

Hüseyin, Bedreddin, Yunus, Pir Sultan

İnsan sevgisini canında  bulan...

Hüseyin, Bedreddin, Yunus, Pir Sultan

Irk, din, dil ayrımı yapan değiliz

Boş hurafelere tapan değiliz

Dostluk bahçesinde açan al gülüz

Hüseyin, Bedreddin, Yunus, Pir Sultan

Şah Turna ırmaktan Deniz’e dolan

Güneşin yanında erir, buz- yalan...

Dar kalıptan çıkıp, evrensel olan

Hüseyin, Bedreddin, Yunus, Pir Sultan! ...

Mansur, Yunus, Can Bedreddin, Pir Sultan

Çağlayan Deniz''de, ırmak-hür sultan

Söz ve Müzik: Aşık Şah Turna (Şahturna)

Düzenleme-yönetmen: Ozan ŞİAR Ağdaşan

Almanca çeviri: Şirin Şafak Ağdaşan, Ozan Şiar Doçent Ursula Reinhard Frei Üniversitesi

İngilizce yayın: M. Richter 

‘Canım Pir Sultan’ ve Klasikler albümleri  ‘İnadına Sevdamız’ ‘Şakıyan Turna-Şahturna’ vb. Kitap, dergiler

ŞahTURNA Kültür Sanat Evi  ŞİARımız Sanat, Edebiyat, Toplumsal Forum

www.sahturna.com   www.siarcan.com', 'Her zaman mazlumun yanında olan Hüseyin, Bedreddin, Yunus, Pir Sultan İnsan sevgisini canında  bulan... Hüseyin, Bedreddin, Yunus, Pir Sulta...', ARRAY['Türk Edebiyatı','Şiir','Ozan Şah Turna Ağdaşan']::text[], 8.5, '{"poet":"Ozan Şah Turna Ağdaşan","poet_slug":"ozan-sah-turna-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/huseyin-bedreddin-yunus-pirsultan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Gerillası', 'siir-gerillasi-ozer-genc-9obpm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sürü masal anlatıyorlar ya

İnananı bol

Onlarca yıl geçse de 

Çağın gerçek ayrıntısı nerede

Bir kere ''ol kara sevda'' girmiş gönlüne 

Gözkapaklarına hapsederken gözyaşını

İnancını böğründe sancı gibi saklayıp

Dimdik tutacaksın başını

Yapılasının en az bilindiği zamandayız

Bir sürü yalan dayatıldı insanlara

Kuantumun,

Sınır tanımaz beyinlerden süzülüp 

Tellerde uçuşan

Hızlı bilgilerin 

Ve parmak uçlarından tuşlara 

Tuşlardan gözlere,gönüllere ulaşan

Kehribar sevdaların mevsimindeyiz

Ne kadar yalan vaadler yağdırsalar da

Yine ağlamaklı gözler, hastalıklı bedenler

Yine milyarlarca aç

Sefil ve don gömlek

Kan,ateş, ölüm 

Kirli Dünya kirli beyin kirli yürek

Ve sen beyninle yüreğinin arasında

Yürüyüş yapan sakallı komutanlarla birlikte

Bir de seversen tüm bunların üstüne

Ağır yük, zor meslek

Sevda ateşten değil 

Sevda radyasyon gömlek', 'Bir sürü masal anlatıyorlar ya İnananı bol Onlarca yıl geçse de  Çağın gerçek ayrıntısı nerede Bir kere ''ol kara sevda'' girmiş gönlüne  Gözk...', ARRAY['Türk Edebiyatı','Şiir','Özer Genç']::text[], 8.5, '{"poet":"Özer Genç","poet_slug":"ozer-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/siir-gerillasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir Küçülürdü Durmadan, Biz Büyürdük', 'sehir-kuculurdu-durmadan-biz-buyurduk-melih-coskun-d5sre', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızıl alevler yakılırdı kenar mahallelerinde 

Genç kızlar yasak rüyalar görürlerdi uykularında 

Anneler saçını okşarlardı sakat çocuklarının,

Sokaklar daralırdı, yükselirdi barikatlar

Ve bu kocaman şehir küçülürdü durmadan 

Biz büyürdük,

Merdiven altlarından keskin kokular yayılırdı, 

Dünyayı kurtarırdı 

Kahraman çocukların sokak aralarında, 

Kadınlar güneşi doğururdu tanyerinde

Ve bu şehir küçülürdü durmadan,

Biz büyürdük,

Şairler içeri alınırdı 

Kalemleri tükenmez olduğu için,

Daha güneş doğmadan düşülürdü yollara 

Gece yarıları dönülürdü vardiyalardan, 

Ekmek bölünür, soğan kırılırdı sahipsiz sofralarda 

Ve bu şehir küçülürdü durmadan 

Biz büyürdük...

Hamile kızlar düşük yaparlardı üçüncü aylarında,

Ay başlarında dokuz doğururdu işçi yürekler,

Tütün sarılır, sevdalar yakılırdı rakı sofralarında 

Gidip de dönmemenin adı olurdu ayrılıklar 

Biz büyürdük 

Ve küçülürdü İSTANBUL........', 'Kızıl alevler yakılırdı kenar mahallelerinde  Genç kızlar yasak rüyalar görürlerdi uykularında  Anneler saçını okşarlardı sakat çocuklarının...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sehir-kuculurdu-durmadan-biz-buyurduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Diğer Yarısı', 'sevdamin-diger-yarisi-hatice-bediroglu-68gfc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çabucak bitse gece,

Güneşe bıraksa, 

Yıldızlar yerini.

Apaydınlık bir gün başlasa,

Sıcak mı sıcak.

Mavinin en tatlısı,

Hakimiyet kursa gökyüzünde.

Bir sokağı tam da dönerken,

Sen çıkıversen karşıma,

Bakışların gözlerime kilitlense,

Gözlerinde erisem erisem...

Gördüğümüz...

En büyük ağacın altına sığınsak, 

Kahkahalar atarak.

Dudakların...

Değse dudaklarıma usulca,

İçim hoplasa

Bir titremedir sarsa bedenimi,

Çıldırmışcasına,

Danslara kalksa yüreğim,

Kuşlar topyekün eşlik etse.

Yaprakların hışırdayışları,

Karışsa yüreğimin sesine.

Kaybetmekten korkarcasına,

Sarılsak birbirimize.

Sen...

Sevdamın diğer yarısı,

Gözümün bebeği,

Hayat ağacım benim.

Seviyorum işte seni.

Hep, hep yüreğimdesin.

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Çabucak bitse gece, Güneşe bıraksa,  Yıldızlar yerini. Apaydınlık bir gün başlasa, Sıcak mı sıcak. Mavinin en tatlısı, Hakimiyet kursa gökyü...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevdamin-diger-yarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Şiirsiz', 'sensiz-siirsiz-suleyman-yavuz-n2pyn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dört duvar arasındayım

Zordayım

Demir parmaklıklar arasında

Geçiyor ömür 

Ama inan bitmiyor günler 

Ne güneş vuruyor yüzüme 

Nede bir yağmur düşüyor elime

Kuşlar uzaktan cıvıldar

Yürek yanar ha yanar

Elimde kelepçe 

Ayağımda pranga

Suçum şiir yazmak

Kalemim kırık

Kâğıdım yırtık

Yüreğim buz gibi soğuk

Şiir yasak bana 

Ölüm hak bana

Bir sensizlik 

Birde şiirsiz günler

Uzak bana 

Ölüm bundan gayri inan hak bana', 'Dört duvar arasındayım Zordayım Demir parmaklıklar arasında Geçiyor ömür  Ama inan bitmiyor günler  Ne güneş vuruyor yüzüme  Nede bir yağmur...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sensiz-siirsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-demiss-vangelis-xvz5d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derinden, en derinden

Hiç göremediğin bir yerden

Hiç düşünemediğin, bilmediğinden

Bu ve bunlar gibi 

Binlercesi, onbinlercesi, yüzbinlercesi...

Sır kapısı, perde arkası değil

Gözlerini, kulaklarını, avuçlarını kapadıktan sonrakiler

Bir ÇIĞLIK bu...

İnsanlığın çığlığı

Duyulmayı bekleyen

O kuyunun dibinden, en dibinden...', 'Derinden, en derinden Hiç göremediğin bir yerden Hiç düşünemediğin, bilmediğinden Bu ve bunlar gibi  Binlercesi, onbinlercesi, yüzbinlercesi...', ARRAY['Türk Edebiyatı','Şiir','Demiss Vangelis']::text[], 8.5, '{"poet":"Demiss Vangelis","poet_slug":"demiss-vangelis","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ciglik-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyinler Tehlikede!', 'beyinler-tehlikede-gultekin-mustafa-o52mj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her trende fazlasıyla duyarlı

duyarsız kendi bilincine

ve bilmek fiilinden türeyen her tür eyleme

ibnelikle özcan denizlik arasında kalmış

yeşermeden budanmış

saksı çiçeği bilinçler

bok yanına püsürü de almış yürümüş

elde avuçta

yokta varda

uzakta ve yakında

varsa yoksa yalan

ve talan halde bırakılmış

tecavüz sonrası beyinler

ve bir kapitaldir artık özlem duyulan

gürültü çok duyulmuyor bilirkişi vızıldamaları

ırza geçilme kontürü bir bir artmada

işbu şiire konu beyinlerin

eskidikçe kafa kağıtları', 'her trende fazlasıyla duyarlı duyarsız kendi bilincine ve bilmek fiilinden türeyen her tür eyleme ibnelikle özcan denizlik arasında kalmış y...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beyinler-tehlikede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırma çözüleceğine dairlerimi', 'kirma-cozulecegine-dairlerimi-abdurrahim-kahraman-919bn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çözül! ! ! 

Kördüğüm;  çözül artık

Kırma çözüleceğine dairlerimi

Çipa çamurdan çıkmıyor

Deniz ufukta patladı

Şu şerefsiz urganda kanatma 

Beceriksiz ellerimi

Çözül! ! ! 

Çözemediğim kanrevan ellerimle,

Sağlam olsun

Diye

İlmik ilmik ördüğüm

Ya değilse 

Ufukta, patlayan deniz değil; 

Kendi sonum

Gördüğüm...', 'Çözül! ! !  Kördüğüm;  çözül artık Kırma çözüleceğine dairlerimi Çipa çamurdan çıkmıyor Deniz ufukta patladı Şu şerefsiz urganda kanatma  Be...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Kahraman']::text[], 8.5, '{"poet":"Abdurrahim Kahraman","poet_slug":"abdurrahim-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirma-cozulecegine-dairlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tokat’tan Geldim', 'tokat-tan-geldim-kamber-bal-6gyfv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anam doğurmuş ırgatta

Babam büyütmüş gurbette

Kalamadan doğduğum memlekette

Kalkıp Tokat’tan geldim

Yedi yaşımda sevdim bir yar

Mor menekşeler zülfünde diyar

Kal dediler, geçti kırk bahar

Kalamadan Tokat’tan geldim

Gelirken gözlerim hep ağladı

Kızıl Eniş yollarımı bağladı

Ayrılık acısı yüreğimi dağladı

Dağlayıp Tokat’tan geldim

Yol boyu hep baktım semaya

Dizilmişti bulutlar bir bir duaya

Soramadan bizim bilge kahyaya

Gizlice Tokat’tan geldim

Gezdim diyar diyar gurbeti

Bulamadım kendi memleketimi

Öylesine özledim ki derdi hep kemirdi

Diyemeden Tokat’tan geldim

Sabah olur kuşları cıvıl cıvıl

Dereleri akardı durmadan şırıl şırıl

Anam hazır Tokat kebabı hemen kurul

Yiyemeden Tokat’tan geldim

Bakraçları dolu su,içip kansınlar

İçmeyenler de ah ile avunsunlar

Her damda gezeni Bal sansınlar

Göremeden Tokat’tan geldim

2005', 'Anam doğurmuş ırgatta Babam büyütmüş gurbette Kalamadan doğduğum memlekette Kalkıp Tokat’tan geldim Yedi yaşımda sevdim bir yar Mor menekşel...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tokat-tan-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mantıklı hayatın sona erişi', 'mantikli-hayatin-sona-erisi-hasan-deniz-rujld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden her attığım adımda düşünürdüm

Acaba bu attığım adım mantıklımı diye

Taki sen karşıma çıkıpta beni dalımdan düşürene kadar

Kendimi önceleri bir elma ağacın erişilmez elması sanardım

Amma felakin sen beni bir çırpışınla avuçlarına düşürdün

Artık ne mantığımla düşüne bildim

Nede kalbim acı çekmesin diye, ona söz geçire bildim

Sesini duyana kadar uyku tutmazdı beni

Huzur bulurdum sesini duyduktan sorna

O an kendimi yeni uçmayı öğrenen bir kuş misali sanardım

Hatırlıyormusun o günü, açmıştım ağzımı ve yummuştum gözümü

Tek tek saymıştım sana senin beğenmedigim huylarını

Sende bana bunu demiştin: benimde sende beğenmediğim huyların var

Ama bu huyların olmasaydı ben seni bu kadar sevemezdim

Güneşin o kırmızılığı ve kızarıklığı yüzüme yansıyı verdi

Birdaha anlamiştim o an, senin herkezden farklı olduğunu

Ve seni neden bu kadar sevdiğimi', 'Eskiden her attığım adımda düşünürdüm Acaba bu attığım adım mantıklımı diye Taki sen karşıma çıkıpta beni dalımdan düşürene kadar Kendimi ön...', ARRAY['Türk Edebiyatı','Şiir','Hasan Deniz']::text[], 8.5, '{"poet":"Hasan Deniz","poet_slug":"hasan-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mantikli-hayatin-sona-erisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iki ileri, bir geri', 'iki-ileri-bir-geri-serpil-maglicoglu-t4tn4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Iki adim ileri bir adim geri.

Yürüdükce  geri geri mi gider insan? 

Ilerledikce yokus mu  cikar önüne? 

Birini astikca yenisimi bekler ne? 

Git git bitmek bilmez mi yollar? 

Dur durak tanimazmi sorunlar? 

Aldigim kadar versemde, 

Dengelenmez mi bu teraziler? 

Ne güzel yürümüs gelmisim derken.

Tanrim, bu da ne, onca yol onca yokus.

Yine basa mi gelmisim ben simdi yani? 

Dönmüs dolasmis, ayni yerdemi saymisim? 

Ne etsem diye düsünecek vakit de kalmadi ki.

Yari zamanimi harcamisim, iki ileri bir geri.

Yolu olmayan  duraklar da beklerken.

Kisa hazirlik, bos kavanozlar dolduruken.

Iki adim ileri, bir adim geri.

Ben ögreninceye kadar günes batacak gibi.

Bilseydim ikinci bir sansim olacak.

Otururdum oldugum yere, tüm yollara inat.', 'Iki adim ileri bir adim geri. Yürüdükce  geri geri mi gider insan?  Ilerledikce yokus mu  cikar önüne?  Birini astikca yenisimi bekler ne?  ...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-ileri-bir-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ego', 'ego-mehmet-isikoglu-a1fj6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Halleşip anlaşmak zordur onunla

Hiç ferman dinlemez dargin kanunla

Tek arzusu vardir yare kavuşmak

Istemez avunmak onun bununla

Uçar yükseklerde engine inmez

Akar coşkun coşkun dalgasi dinmez

Ister yalniz kendi dediği olsun

Her zaman haklidir bana yenilmez

Gönül ayri yerde ben ayri yerde

Düşmüşüz ikimiz ayri bir derde

Sözüm kar eylemez bildiğin okur

Onunla dövüşmek varmiş kaderde', 'Halleşip anlaşmak zordur onunla Hiç ferman dinlemez dargin kanunla Tek arzusu vardir yare kavuşmak Istemez avunmak onun bununla Uçar yüksekl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ego-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece''nin Yalnızlığı', 'gece-nin-yalnizligi-murat-araz-kta1v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbimin Külleri Birikir Kalbimde

Ay''ın Gözyaşları Kaybolur Gecede

Yıldızlar Marjinal Dizilir Yalnızlıkta

Melodiler Bulunamaz Karanlıklarda

Yaşlanan Düşler Fırtına Bekler

Kaybolan Gizemler Közlenir

Savrulan Zaman Bulutlarda Söner

Anılardadır Ağlayan Nöbetler

Çözülüşleri Yoktur Yanan Aşkın

Sonu Olmaz Yitirilen Anın

Gerçeği Bilinmez Düşlerdeki Rüyanın

Dönüşü Olmaz Unutulan Geçmişin

U-yanınca Seni Bekleyen Biri Yoksa

Yanan Kalbin Donar

Aşk Tohumu Bırakacak Toprağın Olmazsa

Yeşeren Çiçeklerin Açmaz

(Gece''nin İnsanlığa Yapılan Özet Doktrini)

09.07.2005 Cumartesi/01:50/Sivas', 'Kalbimin Külleri Birikir Kalbimde Ay''ın Gözyaşları Kaybolur Gecede Yıldızlar Marjinal Dizilir Yalnızlıkta Melodiler Bulunamaz Karanlıklarda ...', ARRAY['Türk Edebiyatı','Şiir','Murat Araz']::text[], 8.5, '{"poet":"Murat Araz","poet_slug":"murat-araz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gece-nin-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En İyisi', 'en-i-yisi-mustafa-ceylan-etvex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlaşıldı bitmeyecek bu çile

Nefesimin karşılığı olsa gerek

Başka bir yanıt bulamıyorum

Bıktım yaralı kuş olup çırpınmaktan

Yazdırıp mahalle bakkalına

Kafayı çekmek en iyisi...

Bebeler uyurken televizyon karşısında

Kurulup kırık koltuğa

Pimini çekmek dünyanın

Ve unutmak bütün gün yaşanılan

Kalleşliği, kahpeliği, ihaneti

En iyisi dostum, en iyisi...', 'Anlaşıldı bitmeyecek bu çile Nefesimin karşılığı olsa gerek Başka bir yanıt bulamıyorum Bıktım yaralı kuş olup çırpınmaktan Yazdırıp mahalle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-iyisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşklarım', 'asklarim-murat-araz-tdypa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece Olunca Gelir Yalnızlık Nöbetlerim

Sabah Olunca Biter Uçan Düşlerim

Geceleri Yağan Yağmurlar Sözlerimde

İnsanlığa Haykırıken Gece''nin Yalnızlığını

Benliğim İnsanları Vururken Birer Birer

Geleceğe Giden Düşlerim Ertelenir

Rüzgarın Gözyaşları Örterken Üstümü

Rüyalara Yatar Yinelenen Düşlerim

Cehennemler Aşklara dönüşürken

Ufunetler Gelir Düşlere

Saatlerdeki Çarklar Ayrılık Saatini Bağırırken

Gözyaşları Gelir Gözlere

Artık...

Ay''ın Gözyaşlarını Silsem

Çiçek Olup Açsam; Güneş Olup Doğsamda

Senden Uzaklardayım

Zama''nın Renklendiği Zamana Kadar Tek Söyleyeceğim

Ütopik Kavuşmalar Gerçekleşince

(Tüm Aşklarıma Dair) 

09.07.2005 Cumartesi/01:50/Sivas', 'Gece Olunca Gelir Yalnızlık Nöbetlerim Sabah Olunca Biter Uçan Düşlerim Geceleri Yağan Yağmurlar Sözlerimde İnsanlığa Haykırıken Gece''nin Ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Araz']::text[], 8.5, '{"poet":"Murat Araz","poet_slug":"murat-araz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asklarim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Busekondu', 'busekondu-mustafa-ceylan-2gy60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel artık neredeysen ey şehir yüzlüm...! 

Yüzüne bakmaya doyamıyorum.

Gönül tapusunu ayırdım sana

Halâ bekliyorum busekondunu

Kaç yıl geçti bilmem, sayamıyorum...

Tahtadan evlerle doldu çevrem

Derdimi kimseye diyemiyorum.

Uykusuz gecelerde esiriyim kadehlerin,

Kaldırımlarda sarhoş

Serserinin birisiyim...

Vermiyor kokunu çiçeklerin hiç birisi

Özledim, inan çok özledim

Hoş kokulu busekondunu...

Gel artık neredeysen ey şehir yüzlüm..! 

Gittiğin yolda minübüsler sevdamı taşır

Ölümden beter ayrılığı çığırır türkülerim

Keskin dilli falcılar yüzünden çektiğimiz bu çile

Bitir şu dağlaşan gurbeti

Bitir Allah aşkına..! 

Portakal çiçeği vuslat gecelerine hasretim

Zindan karasını siliver dudağınla...

Özledim, inan çok özledim

Bana ümit, bana ışık, bana heyecan veren kokunu

Ve de canım

Busekondunu...', 'Gel artık neredeysen ey şehir yüzlüm...!  Yüzüne bakmaya doyamıyorum. Gönül tapusunu ayırdım sana Halâ bekliyorum busekondunu Kaç yıl geçti ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/busekondu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Vurdular Gönül', 'gunesi-vurdular-gonul-mustafa-ceylan-xoe0e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllardır göğsünde duran güneşi

Vurdular, farkında değilsin gönül.

Kanayan yarana hasret ateşi

Sardılar, farkında değilsin gönül.

Buna takvim derler atarmış ağı

Ağını örerken susmaz dudağı.

Ferhat''ı olduğun o yüce dağı

Yardılar, farkında değilsin gönül.

Zannetme, sırtına giydiğin samur

Akar eteğinden sulu bir çamur.

Öfke teknesinde yumrukla hamur

Kardılar, farkında değilsin gönül.

Öteler, kalbine takılan çengel

Çıktığın gurbette bekleme dön gel,

Kahpe gecelerde umuda engel

Gerdiler, farkında değilsin gönül.

Çevrene şöyle bak, doğrul da yerden

Atılır güneşe kurşunlar nerden? 

Aşkınla işleyen saatler birden

Durdular, farkında değilsin gönül.

***********

Ve bu şiire ilişkin bir TAHLİL....

Kimden: Asım Yapıcı (Bay, 39)  

 Kime: Grup: Antalya GÜLLÜK Şiir Gül Destesi

 Tarih: 6.9.2005 20:11 (GMT +2:00) 



 Konu: Mustafa Ceylan Hoca''nın ''GÜNEŞİ VURDULAR GÖNÜL'' isimli şiiri üzerine bir değerlendirme 

Modern dönemde şiir eleştirileri, özellikle şiirin dili, sesi, anlamı, tür-kurgu-anlam uygunluğu ve edebi sanatlar çerçevesinde yapılmaktadır. Bir de buna şairin etkilendiği ve etkilediği kişiler ilave edilmektedir. 

Bu şiirde bunların hepsini ele almaya çalışmam uzunca bir vaktimi alacağı için, ben bu kriterleri de desteğime alarak, ama tamamen bunlara bağlı kalmayarak bir analiz yapmak istiyorum. 

Bir kere bu, olumsuz eleştiriye büyük oranda kapalı oldukça güzel açıklama tarzı bir şiir. Teknik anlamda hecesi, durakları, kafiye sistemi ve yapısı yerli yerinde. Bu sebeple bunlar üzerinde durmaya gerek yok. Şiir sesi de oldukça kuvvetli. Lirizm ve duygusal yoğunluk üst düzeyde. 

Şiir dili ve söylem açısından yer yer oldukça bakir ve yaratıcı. Bir iki yer de detone oluş ve şiir dilinde problemler olsa da bu tür bir eleştiri, şairin ustalığı ve özellikle şiir sesinin ve mısra tekniğinin güzelliğiyle geri plana düşüyor. Bu anlamda şiirin bütünlüğü de kendisini eleştiriye büyük oranda kapatıyor. 

Tür ile anlam ve kurgu arasındaki ilişki yerli de yerinde. Bu şu anlamda önemlidir. Bu tür bir temayı bana göre 11''li heceyle ve aşıklama tarzıyla yazmak gerekirdi, şair de bence çok isabetli bir tercihte bulunmuş. 

Şair şiirinin en vurucu, şiir dili açısından en can alıcı, söylemsel yaratıcılık açısından en bakir ifadeyi şiirine başlık olarak seçmiş ve bu isim şiirde çok şık duruyor: ''Güneşi vurdular gönül'' 

Buradaki ''Güneş'' neyin nesi, ''güneşi vurmak da ne'' demeden şiir üzerindeki değerlendirmemi sunmak istiyorum. 

''Yıllardır göğsünde duran güneşi 

Vurdular, farkında değilsin gönül. 

Kanayan yarana hasret ateşi 

Sardılar, farkında değilsin gönül.'' 

Giriş kıtası oldukça güzel. Ses, dil, mısra tekniği açısından. Anlam çok zahir görünse de örtük sembolik anlatım insanı içten bir kavrayışla tutuyor ve bu anlatım ''zihinlerde derinlikli ve açık uçlu bir söyleme'' dönüşüyor. 

''kanayan yaraya hasret ateşi sarmak'' 

diye nesre çevirebileceğim bu imgesel teşbih hakkında sadece sukut ediyorum, çünkü çok güzel. Ve bu ifade, şiir dili açısından yaratıcılığa çok güzel bir örnek teşkil etmekte. 

Tanıyanlar ve şahsen tanımasalar da şiirleri hakkında yorum yaptığım kişiler bilirler ki, hemen her yorumda ''şiir dili'' kavramını ön plana çıkarırım. Çünkü müziğin nasıl kendisine has bir dili varsa, romanın, hikayenin, resmin, hatta rüyaların vs. özel bir takım söylem ve ifade tarzları varsa, şiirinde bir dili ve tarzı vardır. Bu dil tabii ki günlük konuşma dilidir, ancak konuşma dili sadece kelime sağlar şiire. Şair o kelimeleri engin hayal denizinde ve ruhunun en gizli bölümlerinde bazen farkında olarak, bazen de farkında olmayarak öyle yoğurur ki, ''arkası görünür gibi olan, ama yaklaştıkça uzaklaşan seraba benzer dizeler yaratır''. 

Buna takvim derler atarmış ağı 

Ağını örerken susmaz dudağı. 

Ferhat''ı olduğun o yüce dağı 

Yardılar, farkında değilsin gönül.'' 

Şiirin ikinci kıtası. Özellikle ilk iki satır bence bakir bir söyleme sahip. 

''Takvimi ağa'' benzetme, belki de örümcek ya da ipek böceğine, daha doğrusu ağ ören ne varsa onlara. Ancak iş bununla bitmemekte, ağ örülürken dudağın türkü söylemesi gibi, nefes alması gibi, belki de saatin sesi ve tıklaması gibi susmayan bir deveran ve gidiş, hatta kayboluş. 

Türk şiirinin modern dönemlerde de en önemli temasıdır ''zaman''. Şair burada o kadar ustalıkla işliyor ki zamanı, gönlüne hitap ederken aslında zamana da gönderme yapıyor. Bunun şiir dilinde olması şiiri güzelleştiyor.. 

''Ferhat''ı olduğun o yüce dağı 

Yardılar, farkında değilsin gönül'' 

İşte buradaki üçüncü ve dördüncü dizelerde ise Ferhat''a telmihle yine güzel bir söylem var, tabii ki şiir dilinde ve sesinde. Bir de uyuyan gönle sesleniş. Ama hocam zaten gönül bunlarıı görseydi o zaman ''akıl'' olurdu. Gönül görmez, hatta görmemesi bit yana göze de göstermez. Bu sebeple aşk gönülde ve gönülden yaşanır. Belki aşkın gözünün kör olması da onun gönülle ilişkisindendir. Ve gönül et parçası olmayan kalbin belki eş anlanmlısı belki de arkadaşıdır. Yani Doğu-İslam kültüründe tüm duyguların yaşandığı temel merkezlerden birisi, hatta en önemlisi, hattası yok. ''Esası'' demek daha isabetli olur kanaatindeyim. 

''Zannetme, sırtına giydiğin samur 

Akar eteğinden sulu bir çamur. 

Öfke teknesinde yumrukla hamur 

Kardılar, farkında değilsin gönül.'' 

Bu şiirde bu kıtada biraz takıldım. Önce ilk iki dizedeki söylem basit gibi geldi bana. Sonra ''neden'' bu basitlik dedim ve düşündüm. Neticede söylemin pek de basit olmadığı kanaatine vardım, ama fazlaca yaratıcı da bulamadım doğrusu. 

''Öfke teknesinde yumrukla hamur 

Kardılar, farkında değilsin gönül.'' 

dizeleri de oldukça güzel. Ancak ben olsaydım ''hamuru'' ''yumrukla'' değil de başka bir şeyle yoğurmayı tercih ederdim. 

Gerçi burada şiddet ve saldırganlık olgusuna da harika bir gönderme var ve aslında bu gönderme oldukça kınayıcı bir tarzda. Bu sebeple anlam oldukça zahir ve yerli yerinde. 

''Öteler, kalbine takılan çengel 

Çıktığın gurbette bekleme dön gel, 

Kahpe gecelerde umuda engel 

Gerdiler, farkında değilsin gönül.'' 

Burada bir ''öteler'' deyişi var ki, son derece kıvrak. Esasen şiirde bu kıvraklık dili ve sesi tamamlamakla kalmak, mısra tekniği açsından da şiiri şiir yapar. 

''Öteler'' ifadesi biryerlerde yabancı da gelmedi bana. 

Evet, bu ifadeyi bir de Necip Fazıl''dan hatırlıyorum, böyle kıvrak kullanılışıyla 

''Öteler öteler, gayemin malı; 

Mesafe ekinim, zaman madenim. 

Gökte saman yolu benim olmalı; 

Dipsizlik gölünde, inciler benim.'' 

Bu dizelerde dönüşün kıvrımlı, acılı, sancılı yollarında yaşanan yoğun bir arayışın ifadesi var. İçsel bir harbin hatta ruhsal bir ihtilalin travmatik izleri. 

Ama Mustafa Ceylan Hoca ''öteler'' derken ''metafizik'' olanı değil, fiziksel anlamda, hatta coğrafi manada ''öteler''i kastediyor, yanlış anlamadıysam. Ancak o kadar güzel ve yumuşak kullanılıyor ki, bu ifadeyle birlikte birden derin bir Bergsoncu sezgi kalıyor içimizde. 

Gurbet teması bu fikrimi doğruluyor zaten. Ancak ''metafizik olan''da bir yönüyle fiziksel olanın gurbeti deği midir, diye soruyorum kendi kendime. Aslında böyle bir çağrışımı yapmaması gerekirdi diye düşünüyorum şiirin, ama yaptı işte. 

Şiirin dili, sesi ve mısra tekniği açısından en güzel dizelerinden birisi de yine bu dörtlüğün son iki mısrasıdır. 

''Kahpe gecelerde umuda engel 

Gerdiler, farkında değilsin gönül''. 

Ah gönül olanı biteni bir bilseydin, ah bir aklını başına alabilseydin, ah farkında olabilseydin farkındalığının, anlamını anlasaydın anlamsızlığın, görseyin birşeyleri ve yine ahhh ki ümitler kahpe gecelerin karanlığında saklanacak yer ararken ya da gecenin karanlığı umutlara peçe yapılırken, hatta bizzat gece, yani karanlık, yani kötülük, yani yokluk, umudu yokluk trenine bildirirken, ne engeller gelir uzaktan beliren en ufak ziyalara ahh bir bilseyin. 

''Çevrene şöyle bak, doğrul da yerden 

Atılır güneşe kurşunlar nerden? 

Aşkınla işleyen saatler birden 

Durdular, farkında değilsin gönül.'' 

Şiirin finali bence çok güzel. İşte final diyesi geliyor insanın. Sadece ilk dize biraz rutin geldi bana, yani çok düz ve sıradan. Ama diğer üç satır yerli yerinde. 

''Çevrene şöyle bak, doğrul da yerden'' 

Bir şiir de bunun olması da normal, yani doldurma mısraların bulunması. Gerçi anlam açısından alttaki söylemi hazırlayan bir işlevi de var bunun. 

Çünkü; ''çevrene şöyle bak, doğrul da yerden'' dizesiyle şair, biraz da budalaca bir şekilde olanı biteni bir türlü farkedemeyen, üstelik farketmek de istemeyen, bildiğini okuyan, kafasına göre takılan, sadece hisleriyle hareket eden gönle birinci elden hitap ederek onu uyarmak istiyor gibi. Ama yine de daha kıvrak bir ifade bulunabilirdi diye düşünüyorum. 

''Çevrene şöyle bak, doğrul da yerden 

Atılır güneşe kurşunlar nerden? 

Aşkınla işleyen saatler birden 

Durdular, farkında değilsin gönül.'' 

''Güneşe kurşun atmak'', ''aşkla işleyen saatlerin durması'' vb. söylemler şairin şiirsel yaratıcılığının, bakir söylem üretmesindeki ustalığının açık işaretleridir. 

Güneşe kurşunlar neden atılır? 

Güneş neyi temsil ediyor? 

Burada işte sembolik anlatım denen olgu devreye girmekte, düşündürdürkçe de düşündürmekte. 

Güneş; aşk mı, kurtuluş mu, vuslat mı, yarınlar mı, yoksa umudun aydınlığı mı? Şairin yüreğimi yoksa? 

Güneş ne olursa olsun bu çok önemli değil ama onun olumlu birşey olduğunu zaten dizeler sezdiriyor bize. 

Şiirde bunun olması kaliteyi artıran bir husustur. Çünkü şiirin manası kavranırsa, bu durum, tadı hemen alınan ve hemen kaybolan nesneleri yemeğe benzer. Ama ağza aldıkça tadı yavaş yavaş gelen, somurdukça daha fazla tadlanan neyse şiir de onun gibi (anladıkça demiyorum)   sezdikçe ve kavradıkça tadlanan bir söyleyiş şeklidir. 

İşin teknik kısımları da buna ilave edildi mi, işte buradaki gibi okundukça okunası gelen bir şiir ortaya çıkar. 

İslam kültüründe, özellikle de tasavvufta insanın iç dünyasını ifade eden beş kavram vardır: 

1)   Sadr (göğüs) : sadra şifa vermez deyiminde olduğu gibi. 

2)   Fuad: Gönül diye ifade edilen yer. Bu şiirde de ifade edilen gönle oldukça yakın 

3)   Kalp: Bildiğimiz anlamıyla sol yanda bulunan ama acıyı ve mutluluğu duyan yer.''Yere göğe sığmam da sadık kulumun kalbi beni içine alır'' kudsi hadisinde de ifade edilen manevi mekan. 

4)   Lübb: Akılla duygunun birleştiği yer 

5)   Sırr: İşte kişinin en gizli yeri. 

Bu tabakalardan her biri insanın iç içe girmiş iç dünyalarını temsil eder. 

''Gönül'' laf anlamaz ve söz dinlemezdir kültürümüzde. Sadece kültürde mi, aynı zamanda psikolojik olarak da böyledir bu durum. 

Sevgili Hocam ben de laf dinletemedim ona şimdiye kadar. 

Yaratılmışlar içerisinde gönlüne söz geçiren birisi oldu mu onu da bilmiyorum. 

Allah vermiş lutfetmiş bize onu, onsuz da olmaz, onunla başımız beladan da kurtulmaz. 

Özetle şiir gibi şiirdi. 

Tebrikler ve başarılar. 

Asım YAPICI', 'Yıllardır göğsünde duran güneşi Vurdular, farkında değilsin gönül. Kanayan yarana hasret ateşi Sardılar, farkında değilsin gönül. Buna takvi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":112,"source_url":"https://www.antoloji.com/gunesi-vurdular-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Cehennemimizde Soğuk Bir Gün', 'ask-cehennemimizde-soguk-bir-gun-murat-araz-ybm3x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk Cehennemimizde Soğuk Bir Gün

Karşımda Duruyor Güzel İşkencen

Aşklar Doğuyor Bir Tarafı Kırılmış Düşlerimde

Sevgilenmiş Tohumlar Atıyorum Topraklara

Karlar Gibi Yere Serilmişim Üstümden Geçenlere İnat Ölesiye Seviyorum Seni

Gözlerinin O Işıkları Vuruyor Ve Alıp Götürüyor Beni Başka Dünyalara

Öpücükler Topluluğunu Oradan Dünyaya Fırlartıyorum Sana Ulaşsın Dualarıyla

Koskoca Şehirde Yalnız Ben Uyanığım 

Teninin Rengi Olan Ay Gökyüzünü Gözünün Rengine Oda Saçının Rengine Bırakırken

Yapayalnızım! ! ! 

Aynalarım mı Beni Mavileştirdi Yoksa  Kendime Senin Mavi Gözünlerinlemi Baktım Yoksa Yoksa Sözlerimmi Yeşertti Aşk Tohumlarını? 

Bak İşte Aşk Ağacı Meyveler Veriyor...Toplamış Ve Yemişiz Onları

Rengarenk Açmış Sevgi Çiçekleri Hatırlatır Bana Kışın Baharı

Ve O Nahoşlukta Zamanı Unuttum! Yanlış Olması Herhalde 21. Yüzyıldayız

Seni Tanımayan Tek Bir Hücre Bile Yok Kalbimde

Yaşadığımız Mavi Anlar Bir Daha Olmayınca Kalbim Yanıyor Mum Gibi Ah mum Bitti! 

Seni Sonsuzluk Buluşmaları Kadar Çok Sevdim; Attığımız Tohumlar Ağaç Oldu Bak

Güldeki Kırmızılar Kızarmış

Derdim Aşk Denizinin Dibine Batmış Bekalı Aşkı Günyüzüyle Seviştirip Somutlaştırmak

Karlar Gibi Yağıyor Gökten Hoşlanışlar Sevgi Irmaklarına Dökülüyor O Irmaklar ki Görülmemiş Büyüklükteki Aşkımızın Olduğu Denize Dökülüyor 

Kışın O Hüzünlü Ve Kara Yüzünü Bana Masmavi Yaptın

Gönlünün İçindeki Aşk Şehrine,Toprak Olmuş Serilmiş Gök Olmuş Mavileştirmiş,Melek Olmuş Korumuş,Kar Olmuş Yağmış,Güneş Olmuş Isıtmış Ay Olmuş Yansıtmış,Dağ Olmuş Yükseltmiş Ağaç Olmuş Meyve Vermişim...

(Gözleri Işıldayan Mavi Meleğime)

23.12.2004 Perşembe/22:17/Sivas', 'Aşk Cehennemimizde Soğuk Bir Gün Karşımda Duruyor Güzel İşkencen Aşklar Doğuyor Bir Tarafı Kırılmış Düşlerimde Sevgilenmiş Tohumlar Atıyorum...', ARRAY['Türk Edebiyatı','Şiir','Murat Araz']::text[], 8.5, '{"poet":"Murat Araz","poet_slug":"murat-araz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-cehennemimizde-soguk-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya ayrılık yeri,', 'dunya-ayrilik-yeri-mikdat-bal-efr28', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya ayrılık yeri, bir gün vade dolacak 

Vadesi dolan herkes, burdan yolcu olacak 

Renga renk hayalleri, pörsüyecek solacak 

İnansın inanmasın, her insan ölecektir 

Ahiret gerçek midir, ölünce bilecektir 

İnananlar bilir ki bu hayat imtihandır 

Ahiretin tarlası, bu dünya, bu cihandır 

Ekilen biçilecek, herkes bir bahçıvandır 

Her kim ne yapmış ise önüne gelecektir 

Amelini görenler tanıyıp bilecektir 

Aklıselim insanlar, gerçeğe boyun eğer 

Geçici dünyalığa, maddeye vermez değer 

Allah`a teslim olur, alnı secdeye değer 

İman ile göçenler, ebedi gülecektir 

Cennet`e ulaşınca, yerini bilecektir 

Cennet o kadar geniş, orda herkese yer var 

O başka bir alemdir, ne kötülük ne şer var 

Melekler hizmetçidir, orda mutlu beşer var 

Cennet taamlarından, yiyip içilecektir 

Bir mekandan mekana hızlı geçilecektir 

Lailaheillellah diyen cennete girer 

İnanarak söyleyen mutlak sefaya erer 

Ya topluca diyelim, veyahut birer birer 

Tevhit kelimesiyle cennet açılacaktır 

O cennet`e girenler ebedi kalacaktır', 'Dünya ayrılık yeri, bir gün vade dolacak  Vadesi dolan herkes, burdan yolcu olacak  Renga renk hayalleri, pörsüyecek solacak  İnansın inanma...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dunya-ayrilik-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüsuyu Hürmetine Kahrın', 'yuzusuyu-hurmetine-kahrin-aysenur-yazici-ubgwo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Yürekten dilenen herşey'' gerçek olur 

diye öğretmişler ona

yüzüsuyu hürmetine kahrın

inanmış bir duada bin umudun olduğuna

öğrenmiş bir kere kırık yürek

ama bilmez kimse..

...neler çekerek...

her ''hayır''da bir şer

her ''şer''de bir hayır vardır

avuntusuyla sarmışlar yaraları

inanmış  her ayrılıkta bir kavuşan

her kavuşmada bir ''ayrılan'' olduğuna..

belki bilir biri de..

...susar hayrına...

unutulmuş bir çakmak

banyoda kurumuş yarım bir beyaz sabun

çarşafta bir tel kara saç kalınca

''yazgı'' diye ağladıklarının

acının kendiyle abdest almak olduğunu anlayıp

 ''dünyaya bir daha gelmeye'' and içmiş

bir kanadı kırık melek...

aynı aşkla buluşmak dileğiyle

...kimse bulandırmadan..

...bilerek..isteyerek

          

              Kızkulesi

       13.ağustos 2005

             (23:40)  

        Ayşenur Yazıcı

         Andrea and', '''Yürekten dilenen herşey'' gerçek olur  diye öğretmişler ona yüzüsuyu hürmetine kahrın inanmış bir duada bin umudun olduğuna öğrenmiş bir ker...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yuzusuyu-hurmetine-kahrin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küfür, Müfür!', 'kufur-mufur-ekrem-sama-53lko', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çanakkale''de, ilçe Eceabat,

Bir haber var ki, berbat mı çok berbat! 

Şehitçikleri, topluca anmışlar,

Şehitler böyle, anılır sanmışlar...

Başka bir yanı, var ki çok acaip; 

Beraberinde, kutlanmış Regaip.

İyi ya güzel! Hem şehit hem kandil,

Zannetmeyin hiç, biz değiliz safdil.

Öyle anma ki, oynatılmış dansöz,

Haydin beraber, diyelim birkaç söz; 

Akıllarını, hepten sıyırtmışlar,

Şehit uğruna, göbek kıvırtmışlar. 

Bana yakışmaz, edemem ki küfür,

Lakin etmeli, bol okkalı müfür.

Şeytanlar sizle, duyacaktır gurur,

Şehitler silah, bulsa sizi vurur...

Dikkat, hızla, yaklaşıyoruz finişe! 

Hey sizler! Bari, yarayın bir işe; 

İnsanlar için, cazip O kasaba,

Siz gidin teslim, olun bir kasaba...

(İstanbu:13.08.2005)', 'Çanakkale''de, ilçe Eceabat, Bir haber var ki, berbat mı çok berbat!  Şehitçikleri, topluca anmışlar, Şehitler böyle, anılır sanmışlar... Baş...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kufur-mufur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryadın Anlamı Son Dizededir...', 'feryadin-anlami-son-dizededir-ertan-akbayrak-xntk6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Az önce limandaydım,yapayalnız...! 

Rüzgara hasret,durgun denizin,içsel uğultusuyla irkildim...

Derken martılar belirdi gökyüzünde...

İlk kez martıların sesinden bu kadar rahatsızlık duymuştum...

Çığlık çığlığa dolandılar tepemde...

Peki neden? neden dedim kendime...

Neden bu kadar acıdır bu sabah martıların çığlıkları....

Neden bu kadar içten ve yürek dağlayıcı...! 

Birden düşündüm ve dedim ki; 

Ya içlerinden biri,diğerlerine büyük bir acı verdi...

Ya da herhangi bir yerde,herhangi bir sevgili...

Boyun büküp,yarini terketti...!', 'Az önce limandaydım,yapayalnız...!  Rüzgara hasret,durgun denizin,içsel uğultusuyla irkildim... Derken martılar belirdi gökyüzünde... İlk ke...', ARRAY['Türk Edebiyatı','Şiir','Ertan Akbayrak']::text[], 8.5, '{"poet":"Ertan Akbayrak","poet_slug":"ertan-akbayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/feryadin-anlami-son-dizededir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komşu kızı zerrin - 1', 'komsu-kizi-zerrin-1-elazigli-mustafa-kaya-wpspg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'benim hiç olmadı oyuncaklarım

     komşu kızı zerrin inde

     ben kağıttan kuyruk yapardım uçurtmama

     zerrin yırtıp atardı

     ben kuleler yapardım taşlardan

     zerrin dağıtırdı aniden

     beş taş oynamasını öğrettim

     mızıkçılık yapıp taşlarımı kaptı

     pikniğe gittik seyran bağlarına

     aldı topu vermedi bir daha

     en güzel elbiselerimle çıkmıştım bayrama

     çamur atıp kaçtı ağlaya ağlaya

     derdi ne bu kızın

     oyuncaksa benim de yoktu..hem fakirdik

     oysa zerrinin hallice

     okula başladık birlikte

     ben onu beklerdim evin önünde

     beni bırakıp giderdi istediğiyle

     aynı sınıfta oturduk

     önceleri yan yana

     sonra aldı başını gitti arka sıralara

     çantamı atar yere..silgimi alır..defterimi karalar

     sonra şikayeti bana yapar

     tebeşirle çizdi önlüğümü bir gün

     çıkmadı izi o gün bugün

     ben bitirdim okulu..taşındık hem

     kurtuldum  o  komşu kızı zerrinden…

     ortaokul bitti lise de devam etti

     bir gün samanpazarı çevresinde

     adliye ye doğru akan bir cadde de gördüm onu

     tanımadığına sevindim önce

     sonra koşup geçtim önüne

     boyluca olmuş bense kısa kalmışım

     başından belliydi uzayacağı

     benimse dertlerden yarım kalacağım

     bu kez gülümsedi 

     o gün ilk kez böyle gördüm zerrin i..

   

                                                     14.08.2005 / İstanbul

                                                     mustafa kaya', 'benim hiç olmadı oyuncaklarım      komşu kızı zerrin inde      ben kağıttan kuyruk yapardım uçurtmama      zerrin yırtıp atardı      ben kul...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/komsu-kizi-zerrin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyazıd meydanı - 1', 'beyazid-meydani-1-elazigli-mustafa-kaya-e5tn3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir akşam daha aktı içimizden.

bir güvercin bir güvercine karıştı.

güvercinlerle İstanbul a iniyor insan

incecik bir yol yalnızlık,

ve benim hiç sevinçlerim olmadı.

beyazıd meydanı kalabalık

içten içe geçerek parke taşlarının

her damlası İstanbul olan 

beyazıd camii avlusundaki şadırvanın. 

secdelerle teyellenen yalnızlığımı

bırakıyorum meydana,

meydan almıyor. 

gövdeme sığmaz meydan..

hatıra fotoğrafları doluyor pozlardan

ve genç bir kızın tebessümünden

İstanbul düşüyor…

                                                                                 mustafa kaya / istambul

                                                                                 14.08.2005', 'bir akşam daha aktı içimizden. bir güvercin bir güvercine karıştı. güvercinlerle İstanbul a iniyor insan incecik bir yol yalnızlık, ve benim...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beyazid-meydani-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve -1', 've-1-elazigli-mustafa-kaya-3wl27', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 've,

ezanlardı dindiren beni

beni isyanlardan çeken

çeken bilir şehrin korkularını

korkular ölmek kadar acı

acı veren ne varsa sırtlandım.

sırtlandık gidiyoruz meçhule

meçhul gülümsüyor oysa bize

bize ne oldu..? koptuk

koptuk en değerli fikirlerden

fikirler dikilir günde beş defa

beş kez insan eğitilir doğruca

doğrular dinledim bir cami avlusunda

avluda insanlar bir tabut başında

başında genç bir kadın ağlıyor

ağlayan gözler içimden çıkmıyor

çıkmıyor pişmanlıkları kadının

kadın saçları dün karaydı

karası sabaha çıkmadı

çıkmadı dilinden ne bir isyan ne de küfür

küfredenler sıra sıra dizildiler

dizilip aynı oldular..fakir-zengin

zenginlik kurtarmadı onu

onu alıp boyu kadar çukura bıraktılar

bıraktılar yaptıklarıyla baş başa

baş başa yaşadım bir ibreti

ibretten tevbe ye geçtim

geçtim insanlığı seçtim

seçtim sevmeyi…sevgiyi..ölmeden ölmeyi

ölmeyi, güzel görmeyi 

görmeyi öğrendim ben..

                                                                                   15.08.2005 / İSTANBUL

                                                                                    mustafa kaya', 've, ezanlardı dindiren beni beni isyanlardan çeken çeken bilir şehrin korkularını korkular ölmek kadar acı acı veren ne varsa sırtlandım. sı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ve-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yani Biz', 'yani-biz-ozan-ozel-nimzx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir arı

bir çiçekten bal alan

yani ben

bir çiçek

dört mevsim güzel

yani sen

bir bal 

lezzetine doyum olmayan

yani oğlumuz

bir kovan

içinde mutlu bir aile

yani biz...', 'bir arı bir çiçekten bal alan yani ben bir çiçek dört mevsim güzel yani sen bir bal  lezzetine doyum olmayan yani oğlumuz bir kovan içinde m...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yani-biz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Has Dostun Gönül Limanına Demir Atmak', 'bir-has-dostun-gonul-limanina-demir-atmak-caglar-asik-az5es', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl isterim? Anlatabilmeyi. Aaaahh! Yürekten bağlanabilmeyi.

Bir has dostun gönül limanına, sonsuza dek demir atabilmeyi.

Kayalıklarına çarpmadan, daima, güvenle orada kalabilmeyi.

Özden öze, gözden göze, gönülden gönüle konuşabilmeyi.

&

Karşılıklı dalga dalga, köpük köpük, tertemiz sevebilmeyi. 

Sevgiyle, saygıyla, onurla, şerefle, lekesizce yaşayabilmeyi.

Hiç kırmadan, kırılmadan, masumca, sonsuz aşkı seyiredebilmeyi.

Sonsuz aşk ateşiyle, ruhta sonsuz huzuru hissedebilmeyi.

&

İstanbul – 13.08.2005

Çağlar Aşık - Bir Has Dostun Gönül Limanına Demir Atmak', 'Nasıl isterim? Anlatabilmeyi. Aaaahh! Yürekten bağlanabilmeyi. Bir has dostun gönül limanına, sonsuza dek demir atabilmeyi. Kayalıklarına ça...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-has-dostun-gonul-limanina-demir-atmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendimize', 'efendimize-caglar-asik-kak46', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hira dağının her taşını öpsek.

Mekke de Kabe de hep adını ansak.

Aşkının ateşiyle kavrulup, yansak 

Kafi gelir mi sevgine, acziyetten ağlasak.

Ya Resul Allah’ım, aşkım, sultanım.

&

Sonsuza dek kainat, hep Seni anar.

Melekler arşı alaya adını yazar.

Mevlayla salatın yan yana konar.

Sevgilinin Sevgilisine gönlümüz çağlar.

Ya Resul Allah’ım, aşkım, sultanım.

&

Misler diyarından ruhlara, gül kokun gelir.

Zamansız, mekansız, gönüllerde, sevgin yetişir.

Aşkla yanan, kor yüreklerde gül nurun yayılır.

Sevginle, aşkınla  yaşayarak şefaatin umulur.

Ya Resul Allah’ım, aşkım, sultanım.

&

Sen gelmeseydin kainat var olmayacaktı.

Sen şeref vermeseydin nur tamam olmayacaktı.

Sen gelmeseydin insanlık huzur bulmayacaktı.

O güle yanlız çöller değil, gönüller kavuşamayacaktı.

Ya Resul Allah’ım, aşkım, sultanım.

&

İstanbul – 13.08.2005

Çağlar Aşık - Efendimize', 'Hira dağının her taşını öpsek. Mekke de Kabe de hep adını ansak. Aşkının ateşiyle kavrulup, yansak  Kafi gelir mi sevgine, acziyetten ağlasa...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/efendimize-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanım & Cananım', 'sultanim-cananim-caglar-asik-68w6b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönüle şifasın.

Her derde devasın.

Mekansız ilaçsın.

Sultanım, Cananım.

Sultanım, Cananım.

Zamansız akansın.

Benzersiz sehasın.

Nurunla huzursun.

Sultanım, Cananım.

Sultanım, Cananım.

Kötüyü kovansın.

İyiyi yayansın.

Sevgide tamamsın.

Sultanım, Cananım.

Sultanım, Cananım.

Makamı Mahmudsun.

Gönlüme Sultansın.

Evrende canansın.

Sultanım, Cananım.

Sultanım, Cananım.

Rahmete sebepsin.

Felaha nedensin.

Her hali, güzelsin.

Sultanım, Cananım.

Sultanım, Cananım.

Rahman’dan Resulsün.

Yaşayan Kur’ansın.

Emsalsiz insansın.

Sultanım, Cananım.

Sultanım, Cananım.

En güzel ahlaksın.

Zamanı aşansın.

Mekanı geçensin.

Sultanım, Cananım.

Sultanım, Cananım.

Sonsuzu görensin.

Temaşa edensin.

Lütufa erensin.

Sultanım, Cananım.

Sultanım, Cananım.

En yüce kulusun.

Eğrisiz doğrusun.

Aşkıyla dolusun.

Sultanım, Cananım.

Sultanım, Cananım.

Sevginle dolalım.

Aşkınla yanalım.

Sonsuzda görelim.

Sultanım, Cananım.

Sultanım, Cananım.

İstanbul – 13.08.2005

Çağlar Aşık – Sultanım & Cananım', 'Gönüle şifasın. Her derde devasın. Mekansız ilaçsın. Sultanım, Cananım. Sultanım, Cananım. Zamansız akansın. Benzersiz sehasın. Nurunla huzu...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/sultanim-cananim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetin Çağrısı', 'cennetin-cagrisi-caglar-asik-6v77n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nefsini aşıpta gel.

Günahtan kaçıpta gel.

Çağrıya koşupta gel.

Ahdine uyupta gel.

&

Selamı alıpta gel.

Fermanı duyupta gel.

Aşkıyla yanıpta gel.

Cezayı aşıpta gel

&

Resul’e bağlanıp gel.

Rahman’a inanıp gel.

Hayıra harcayıp gel.

Ümide sarılıp gel.

&

Sallanma vaktiyle gel.

Farzları edayla gel.

Sünnete uymayla gel.

Sabırla anmayla gel.

&

Kibiri bırakıp gel.

Sevgiyle susayıp gel.

Sevapla dolupta gel.

Rızayı umupta gel.

&

Sonsuzu seyire gel.

Sonsuza sevgiye gel.

Sonsuzda emine gel.

Sonsuzdur, Hak’kına gel.

&

İstanbul – 13.08.2005

Çağlar Aşık – Cennetin Çağrısı', 'Nefsini aşıpta gel. Günahtan kaçıpta gel. Çağrıya koşupta gel. Ahdine uyupta gel. & Selamı alıpta gel. Fermanı duyupta gel. Aşkıyla yanıpta ...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cennetin-cagrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rızayı Aramak', 'rizayi-aramak-caglar-asik-h6fx9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevilen kıymet bilirse

Sevdiğine değer verirse

Arzusun yerine getirirse.

Rızaya erişmek dilerse.

&

Sabrını kalkan yaparsa.

Kötüye hep savaş açarsa.

İyiyle hep kardeş olursa.

Hak’kın rızasını arasa. 

&

İstanbul – 14.08.2005

Çağlar Aşık – Rızayı Aramak', 'Sevilen kıymet bilirse Sevdiğine değer verirse Arzusun yerine getirirse. Rızaya erişmek dilerse. & Sabrını kalkan yaparsa. Kötüye hep savaş ...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/rizayi-aramak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Dost Diye', 'dost-dost-diye-caglar-asik-zwrst', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dost dost diye ağlarsak.

Har har diye yanarsak.

Hak Hak diye anarsak.

Aşk aşk diye kanarsak.

&

Su su diye inlersek.

Yar yar diye ararsak.

Bul bul diye ahlarsak.

Kalp kalp diye çağlarsak.

&

Ruh ruh diye sorarsak.

Saf saf diye bulursak.

Kat kat diye dizersek.

Can can diye gezersek.

&

Yer yer diye görürsek.

Yurt yurt diye konarsak.

Dur dur diye istersek.

Kal kal diye dilersek. 

&

Yol yol diye alırsak.

Borç borç diye ödersek.

Hak Hak diye gidersek.

Zemzem diye içersek.

&

Dost dost diye gülersek.

Mis mis diye koklarsak.

Son son diye bilirsek.

Gül gül diye inlersek.

&

Söz söz diye dinlersek.

Yön yön diye bilirsek.

Her an diye istersek.

Rab Rab diye kavuşsak.

&

İstanbul – 14.08.2005

Çağlar Aşık – Dost Dost Diye', 'Dost dost diye ağlarsak. Har har diye yanarsak. Hak Hak diye anarsak. Aşk aşk diye kanarsak. & Su su diye inlersek. Yar yar diye ararsak. Bu...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dost-dost-diye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Ruh!', 'ey-ruh-caglar-asik-u4azm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boş musun, yoksa dolu mu? 

Dertli misin, yoksa dertsiz mi? 

Amaçlı mısın, yoksa amaçsız mı? 

Koşan mısın, yoksa duran mı? 

Seven misin, yoksa üzen mi? 

Koruyan mısın, yoksa bozan mi? 

Güçlü müsün, yoksa aciz mi? 

Ağlayan mısın, yoksa gülen mi? 

Arayan mısın, yoksa kaçan mı? 

Yapan mısın, yoksa yıkan mı? 

Yumşak mısın, yoksa sert mi? 

Güzel misin, yoksa çirkin mi? 

Temiz misin, yoksa kirli mi? 

Dengeli misin, yoksa dengesiz mi? 

Burada mısın, yoksa uzakta mı? 

Sevgide misin, yoksa nefrette mi? 

Hak’lıda mısın, yoksa Hak’sızda mı? 

Gidende misin, yoksa gelende mi? 

Sağlıklıda mısın, yoksa hastada mı? 

Görende misin, yoksa bilende mi? 

Dostum musun, yoksa düşmanım mı? 

Sözümde misin, yoksa gönlümde mi? 

&

İstanbul – 14.08.2005

Çağlar Aşık – Ey Ruh!', 'Boş musun, yoksa dolu mu?  Dertli misin, yoksa dertsiz mi?  Amaçlı mısın, yoksa amaçsız mı?  Koşan mısın, yoksa duran mı?  Seven misin, yoks...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ey-ruh-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anıyoruz Mevlam Seni', 'aniyoruz-mevlam-seni-caglar-asik-8jtkk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Suya hasret bir gül gibi.

Yare hasret gönül gibi.

Aşka hasret mecnun gibi.

Anıyoruz Mevlam Seni.

&

Gece gündüz düşümüzde.

Her an zikrin dilimizde.

Korlu aşkın gönlümüzde.

Anıyoruz Mevlam Seni.

&

Neyi versek bilemeden.

Sana layık bulamadan.

Aşkla şükre hiç bıkmadan.

Anıyoruz Mevlam Seni.

&

İyiliğe kucak açıp.

Kötülüğe savaş açıp.

Aşkla kor gönül açıp.

Anıyoruz Mevlam Seni.

&

Gönlümüzden dualarla.

Farzın olan namazlarla.

Tuttuğumuz oruçlarla.

Anıyoruz Mevlam Seni.

&

Salavatla selamlarla.

Yetimlere yardımlarla.

Öksüzleri korumayla.

Anıyoruz Mevlam Seni.

&

Küçükleri severekten.

Büyükleri sayaraktan.

Hak, Muhammed diyerekten.

Anıyoruz Mevlam Seni.

&

Kur’an okur diller ile.

Gözler yaşlı gönül ile.

Ferman duyan kalpler ile.

Anıyoruz Mevlam Seni.

&

İstanbul – 14.08.2005

Çağlar Aşık – Anıyoruz Mevlam Seni', 'Suya hasret bir gül gibi. Yare hasret gönül gibi. Aşka hasret mecnun gibi. Anıyoruz Mevlam Seni. & Gece gündüz düşümüzde. Her an zikrin dili...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/aniyoruz-mevlam-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haktır Mahşer Kavuşalım', 'haktir-mahser-kavusalim-caglar-asik-6tmbl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelin dostlar buluşalım.

Yarın bayram sarışalım.

Öpüşelim koklaşalım.

Haktır mahşer kavuşalım.

&

Hakka hizmet yarışalım.

Sevgisini paylaşalım.

Doğru yolu izleyelim.

Haktır mahşer kavuşalım.

&

Zaman aşıp görüşelim.

Mekan bulup konuşalım.

Herkes bilsin anlatalım.

Haktır mahşer kavuşalım.

&

Tadan alır lezzetini.

Bırakamaz sevgisini.

Aşkın yakar kendisini.

Haktır mahşer kavuşalım.

&

Yolcu olduk biz Dünyaya.

Misafiriz buralarda.

Zegin, fakir, buluşmada.

Haktır mahşer kavuşalım.

&

Kimi ağlar, kimi güler.

Dertli olan dönmek ister.

Cennet cehennem ne bekler? 

Haktır mahşer kavuşalım.

&

İstanbul – 14.08.2005

Çağlar Aşık – Haktır Mahşer Kavuşalım', 'Gelin dostlar buluşalım. Yarın bayram sarışalım. Öpüşelim koklaşalım. Haktır mahşer kavuşalım. & Hakka hizmet yarışalım. Sevgisini paylaşalı...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/haktir-mahser-kavusalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Secde - Senden Sonra Kitabından', 'secde-senden-sonra-kitabindan-omer-ekinci-micingirt-g0so0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uçuşur seccade alnı koyunca

Ezelden ebede yol alır secde

Selamlar melekler salât boyunca

Dergâh-ı İlâhî s/el olur secde

Ağuştan gönüle fecirden göğe

Huşu pınarları akar düzlüğe

Götürür ruhları ölümsüzlüğe

Aşka pervaz eder dil olur secde

Sevda yol vuslata zevk-i ruhani

Miraç mucizesi yârin divani

Dirlik vakitleri ihsanda gani

Tadil-i erkânla g/el olur secde

Secde büklüm büklüm gizli geceden

Dizilir ayetler bin bir heceden

Dilden kalbe akar gelir Yüce’den

Yârin bahçesinde gül olur secde

Kutsi seferleri yeşertir içten

Rahmet burcu burcu eser miraçtan

İnşirah renkleri boyanır hiçten

Kalpler cezbelenir hâl olur secde

Ruhlar huşu giyer secdeye değen

Gösterişsiz salih amel işleyen

Secdeyle yücelir acz öper beden

Cennette kevserle bal olur secde

Hû yağar saflara divanda başlar

Edep sarnıçları esvapta yaşlar

Varmak hoş Mevlâ’ya koşun kardeşler

Yâr ’in seferine kul olur secde

Secde kalp ehline rahmet elidir

Y/anmak iki büklüm kulluk hâlidir

Secde makamların yâr ahvalidir

Aşkın gönderinde al olur secde', 'Uçuşur seccade alnı koyunca Ezelden ebede yol alır secde Selamlar melekler salât boyunca Dergâh-ı İlâhî s/el olur secde Ağuştan gönüle fecir...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/secde-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün', 'bir-gun-gorkem-kaya-yg7ak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özlemeyi unutursam bir gün 

Hatırlatır mısın 

Akşam üzerini İstanbul’un 

Bir gün unutursam sevmeyi 

Yavaşça uyandırır mısın 

Uyurgezer 

Gider 

Gelir 

Ama hep şaşırır duygulardan

Unutursam bir gün ağlamayı 

Yakar mısın 

Tekrar canımı....

..................... 

Yaşamayı unutursam 

Bir gün 

Yeniden başlatır mısın?', 'Özlemeyi unutursam bir gün  Hatırlatır mısın  Akşam üzerini İstanbul’un  Bir gün unutursam sevmeyi  Yavaşça uyandırır mısın  Uyurgezer  Gide...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözündeki Yaşlar', 'gozundeki-yaslar-murat-demir-4hxs1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir derdim bir sıkıntım

Yoktur diyorsun bana

Neden hiç bakmıyorsun 

Gözündeki yaşlara

Damla damla yerlere

Dökülüyorlar işte

Canım çıkıyor benim

Seni böyle gördükçe

Deli olacak gibi

Çıldırıyorum sanki

Seni üzgün gördükçe

Ölüyorum inan ki

Bir sıkıntım, kederim

Yok diyorsun sorunca

Ya neden ağlıyorsun

Azıcık dokununca

Pembe yanaklarından

Süzülüp iniyorlar

Görmez misin halimi

Beni öldürüyorlar

Söyle artık derdini

Öldürmeden şu beni

Ben her türlü acının

Öderim bedelini', 'Bir derdim bir sıkıntım Yoktur diyorsun bana Neden hiç bakmıyorsun  Gözündeki yaşlara Damla damla yerlere Dökülüyorlar işte Canım çıkıyor be...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozundeki-yaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmezmiş', 'degmezmis-murat-demir-300yw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaş dökerek yıllar yılı

Ağlamışım yanmışım

Duyduğum tüm sözlerine

Hep boşuna kanmışım

Günden güne bağlanarak

Seni canım sanmışım

Oysa sevdan iki damla

Gözyaşıma değmezmiş

Ne geceler geçirmişim

Uyumadan düşünüp

Hayatımda ne var ne yok

Hizmetlerine sunup

Neler çektim düşe kalka

Ne dallara tutunup

Oysa sevdan ardın sıra

Sürünmeme değmezmiş

Oflarımı arş eğledim

Yıldızlara baktıkça

Dilek tuttum çoğu zaman

Kayan yıldız aktıkça

Yüreğimde hasretine

Boyun büktüm yaktıkça

Oysa sevdan bir saniye

Düşünmeme değmezmiş', 'Yaş dökerek yıllar yılı Ağlamışım yanmışım Duyduğum tüm sözlerine Hep boşuna kanmışım Günden güne bağlanarak Seni canım sanmışım Oysa sevdan...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/degmezmis-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Yaş Vardı', 'gozlerinde-yas-vardi-murat-demir-vsadt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O gün veda ederken

Gözlerinde yaş vardı

Demek ki kahpe felek

Seni benden kopardı

Huzünlüydü yüreğin

Titriyordu her yerin

Ağır ağır bıraktı

Ellerimi ellerin

Ayrılık geldi işte

Ağla yüreğim ağla

Sanmam ki unuturum

Bu acıyı zamanla

Öldürseydinde beni

Böyle bırakmasaydın

Birden bire canımı

Bu kadar yakmasaydın

Ne önemi vardır ki

Hayatımın sen yoksan

Şu üç günlük dünya da

Benim olmayacaksan', 'O gün veda ederken Gözlerinde yaş vardı Demek ki kahpe felek Seni benden kopardı Huzünlüydü yüreğin Titriyordu her yerin Ağır ağır bıraktı E...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerinde-yas-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şans', 'sans-i-brahim-kilinc-e40b3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir lale soğanı var 

Bu toprağın içinde

İsmi şans

Görürse gerekli ilgi ve sevgiyi

Baharda lale ve yaprak

Görmezse olacak

Çürüyüp toprak', 'Bir lale soğanı var  Bu toprağın içinde İsmi şans Görürse gerekli ilgi ve sevgiyi Baharda lale ve yaprak Görmezse olacak Çürüyüp toprak...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sans-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Final**Aşkım**', 'final-askim-berrin-civgin-3dtw0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alışmış gönlüm

Seni sevmeye

Bırak.! ! 

Dertlerin bedenimi

Sarmaşık gibi sarsın

Sevgini ruhuma 

İlmek ilmek işlemişken

Bırak.! ! 

Yüreğimi damla damla

Kanatsın....

Sensiz geçen 

Senli günlerimde

Bırak.! ! 

Kalbim sen diye

Alev alev yansın 

Sabrım beynime

Sığmıyor artık

Bırak.! ! 

Aşkım aşkınla

Deli divane olsun 

Sen benim 

Yaşantımda

Son bulduğum 

**Final**Aşkım''sın**

***11/08/2005/  02/45/   DiDiM***', 'Alışmış gönlüm Seni sevmeye Bırak.! !  Dertlerin bedenimi Sarmaşık gibi sarsın Sevgini ruhuma  İlmek ilmek işlemişken Bırak.! !  Yüreğimi da...', ARRAY['Türk Edebiyatı','Şiir','Berrin Civgin']::text[], 8.5, '{"poet":"Berrin Civgin","poet_slug":"berrin-civgin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/final-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narinim', 'narinim-i-sa-tekin-gtfse', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Selvi boylum

Güzelim

Şirin huylum

Bak gözlerime

Gözlerim senin

Gönlüm sevdam

Sende güzelim

Narinim

Nazlanma.

Güzelim bak bana

Yaşamak istiyorum seninle

Selvi boylum

Güzelim

Ben seni seviyorum

Gül bana sevdiğini bileyim.

Narinim

Güzel yarim

Gülmek sana yakışıyor

Çatma bana kaşlarını

Güzelliğini bozuyor

Selvi boylum bu gönül

Seni çok seviyor.', 'Selvi boylum Güzelim Şirin huylum Bak gözlerime Gözlerim senin Gönlüm sevdam Sende güzelim Narinim Nazlanma. Güzelim bak bana Yaşamak istiyo...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/narinim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuntu Ve Zaman', 'avuntu-ve-zaman-gulsen-gonenc-xzqhh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Atmak isterken kendini denize

ya da foseptik çukurunun dibine,

Bu nasıl bir aşk acısıdır ki,

Tek avuntusu zaman; 

İleri mi, boşa mı gittiği belli olmayan.

İlginçtir, sonucunu gösterecek tek şey yine zaman.', 'Atmak isterken kendini denize ya da foseptik çukurunun dibine, Bu nasıl bir aşk acısıdır ki, Tek avuntusu zaman;  İleri mi, boşa mı gittiği ...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/avuntu-ve-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düş Gördüm, Meramıma Erdirdin', 'bir-dus-gordum-meramima-erdirdin-mustafa-sami-kd0e2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ferhat ile dağlarını deldirdin 

Aslı ile Keremini yandırdın 

Güzelliğini arar dururken

Yusuf ile Züleyha’yı kandırdın 

Bahar ile tozlarımı savurdun 

Başak ile tanelerim ayırdın 

Sırlarını öğrenmek isterken

Aşkın ile Mevlana’yı yandırdın 

Toprak ile bana bir can verdin

Sevgin ile canı cananda gezdirdin

Bu can senin, vuslatını dilerken

Bir düş gördüm, meramıma erdirdin', 'Ferhat ile dağlarını deldirdin  Aslı ile Keremini yandırdın  Güzelliğini arar dururken Yusuf ile Züleyha’yı kandırdın  Bahar ile tozlarımı s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-dus-gordum-meramima-erdirdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlım', 'nazlim-i-sa-tekin-y3yso', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nazlı bir gül iken

Sevda türküleri yakılırdı güzelliğine

Sevdalıların en güzeli idin

Hep seni konuşurlardı, nazar değdi

Kem gözler çekemediler

Uğursuz bir nazardı.

Kestiler elma yanağındaki kızıl gülleri.

Şimdi ben bu sevdan uğruna 

Vuruldum,

Düştüm,

Süründüm

Yalnız kaldım.

Karanlık yalnız gecelerimde

Hayeller kurdum,

Arar oldum dört yanımda

Arar oldum gülen kara gözlerini

Şayet bir gün karşılaşırsak,

Gözlerime bakıpta sakın aldanma

Gözlerinden okuyorum

Sevda hasretini

Sessiz ve de yalnız yaşıyorum,

Yüzünde gülücükler,

Yanağındaki kızıl güller hiç solmasın

                                            NAZLIM', 'Nazlı bir gül iken Sevda türküleri yakılırdı güzelliğine Sevdalıların en güzeli idin Hep seni konuşurlardı, nazar değdi Kem gözler çekemedil...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nazlim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarına boğ beni.', 'gozyaslarina-bog-beni-sedat-alkan-qqsp4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sıcaklar vurur beni.

Senin özlemin de eklendimi.

Yanarım inan, cayır cayır.

En çok bu öldürür beni.

Kışlarım ayaz durdurur kalbimi.

Senin hasretinde eklendimi

Donarım inan buz tutarım.

Çözemez kimse beni.

Sana endekslendi hayatım.

Sensiz ölür senle yaşarım.

Ayrılık ihtimali eklendimi

Deliririm inan tutamazlar beni.

Of, yanarsam söndür kalbimi.

Üşürsem ısıt bedenimi.

Soldurdun güllerimi ağlamadım.

Gel gözyaşlarına boğ beni.', 'Bu sıcaklar vurur beni. Senin özlemin de eklendimi. Yanarım inan, cayır cayır. En çok bu öldürür beni. Kışlarım ayaz durdurur kalbimi. Senin...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozyaslarina-bog-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkaramam.', 'cikaramam-sedat-alkan-mzfkg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oy sevdiğim kurşunmusun.

Girdin benim kalbime.

Öldür beni ama terk etme.

Hekim istemem bu derdime.

Yıldızımsın gecelerime.

Kadehimsin içkilerime.

Vücudumun her yerine.

Yazdım seni çıkaramam.

Cümle alem yok desede.

Herkes üzerime gelse.

Şu yüreğim ellerinde

Kelepçeli, çıkaramam.', 'Oy sevdiğim kurşunmusun. Girdin benim kalbime. Öldür beni ama terk etme. Hekim istemem bu derdime. Yıldızımsın gecelerime. Kadehimsin içkile...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cikaramam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama.', 'aglama-sedat-alkan-huniv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kördüğüm gözlerin çözülmüyor.

Değil günler, aylar, yıllar yetmiyor.

Hırçın bir rüzgar gördüğüm.

Bazen asi ırmak, Ağlayınca içim eriyor.

Seni vuran kederler beni vursun.

Bırak acıları sal, bana gelsin.

Gülen başka göz ölüm bana.

Bir damla gözyaşın ecelim olsun.

Duman gözlüm, sen ağlama.

Yanmışım ben, yüreğimi dağlama.

Cilve naz sayamam, gözlerine bakamam.

Kurbanım duman gözlüm ağlama.', 'Kördüğüm gözlerin çözülmüyor. Değil günler, aylar, yıllar yetmiyor. Hırçın bir rüzgar gördüğüm. Bazen asi ırmak, Ağlayınca içim eriyor. Seni...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglama-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Bakışı Yurttur Gözlerinin', 'her-bakisi-yurttur-gozlerinin-selahattin-yetgin-g4fd5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben ki, bu koskocaman okyanusta kaybolmuş küçücük bir dal parçasıyım forsasız

Zifiri aydınlıkların muhteşem karanlıklarında dualara açmışım ellerimi yalnız sana 

Gecemi dilimleyen öpüşlerinde parantez sorgularla koşarsın sana açılmış kollarıma 

Şehrinin kıyametlerinde inciler yağsa da saçlarıma, felaketler nefretimi kundaklamaz asla.

Öfkenin çığırtkan çığlıklarında bir pişmanlık ezgisi burkar kimi yüreğimizi. Acı turunçlarımızın esmer gecelerine saklanmalarımız fayda etmez. Gözlerindeki yakamozların hesaplaşmalarında ağlarım boş çıkar aysız denizlerimden. Parmaklarım öksüz, dilim sözsüz, ruhum dünsüzlüğe dönüşür sonsuz. İşte böylesi anlarda yurdumun pazarlarında öfkemin tezgahlarını yerle bir ederek yüreğine değmeye çalışırım. Zifir yalnızlığımın tutsak çağrılarına doludizgin koşumlar yaparak.

Ömrümün tüm fırtınalarından daha yamandır ruhumu sallayan sevdan. Sesinin çığlıklarında, isyanının sığ kayalıklarında uykusuz gecelerde bile seni düşler, bir seni özlerim. Sen içimdeki rotasız gemilerimin ruhu ve nuru, yüreğimdeki isyankar korsanların ganimetlerini sakladığı gizli defineleri ortaya çıkaran doğaüstü bir selsin. Sen benim taptığım abide, sen yüreğime can veren ışık, sen benim her şeyimsin.

Denizlerin ve göklerin mavilikleri sağdığı bu gönül ağılında her sevda bir çiçeği ezer, her çocuk gün gelir umudunu bile satar. Sen bende ruhunu aradıkça, ben yüreğinin değirmenlerinde her karış toprağını yurt edinirim. Ömrümden gelip geçen baharların geri dönülmez türkülerinde beni bir başıma  bırakıp gidersen, oyunlara doymamış çocuklar gibi ağlarım.

Yüzüm yüzüne, gönlüm gönlüne hasret, gölgem gölgene tutsak yaşarken yokluğuma üzülürsün kimi. Perçemlerinin her yansımasına yüzlerce şiir, binlerce yazıdır molası olmamış sözcüklerim. Ben ki, ne gördüysem ellerinden, ne duyduysam dilinden ve ne bildiysem ruhundan almışım. Gecemin yalnızlık sağan tüm koyaklarında başlangıcını ve sonunu hesaplayamadığımız bir sevdaya tutulmuşum.

Bu ruh yansımamızın kırılmış tuvallerinde yeryüzünün bütün renklerini nakşedip sözcüklerime bir menekşe çizeceğim bir gün yüreğine. Zümrüt-ü Anka kuşunu bulup en yükseklerde gönlümüzün penceresini kapatacağız engellere. Saatlerini bana kurdun kuralı hiçbir günahımızın sevgimize borcu kalmamalı. Her yolun sonunda umduğumuz büyük kentlerin kirpik kırpışlarında ben aynada kendimi değil seni görüyorum günlerdir.

Ben ki, bu koskocaman okyanusta kaybolmuş küçücük bir dal parçasıyım forsasız. Zifiri aydınlıkların muhteşem karanlıklarında dualara açmışım ellerimi yalnız sana. Gecemi dilimleyen öpüşlerinde parantez sorgularla koşarsın sana açılmış kollarıma. Şehrinin kıyametlerinde inciler yağsa da saçlarıma, felaketler nefretimi kundaklamaz asla. Sen ki, atan nabzımda, gece gündüz çalan sazımda nur topu umutlar doğurursun her şafakta kutsal sarılışlarınla. Senin için yüklendiğim tüm imgelerle yokuşlarına her tırmanışımda susuzluğum artar, hasretin bir damla su gibi içimi yakar. Her saniye büyüyen bir ızdırabın dayanılmaz kollarında dayarım aşkın sedirine sırtımı ve bulutlara serdiğin döşekte ömür sürerim. 

Sokakların günaydınları unuttuğu ve mavilerin turuncuya düşman kesildiği bu gözyaşı limanlarında günaydınlarla bulduk biz birbirimizi. Şuradan buradan derken gemiler saldık insansız denizlere. Çektiğimiz onlarca hüzün ağlarında yine de başladığımız yerde değil miyiz söyle? .Yaşamın öç alımlarında lüks ve çılgın bir yaşama küfredişimiz de bundan değil midir? .

Bu başkaldırılar dergahında takatim kesilene dek ışığına yürüyüşüm bitmeyecek. Umudunu suyundan alan, kavı gözlerinde çakan ve ruhumu okyanusa çeviren dalgalarda bu sevda mintanını asla çıkarmayacağım. Sensiz kalacaksa, kırılsın kalemim, sensiz olacaksa üzülsün yüreğim ve sensiz duracaksa karanlıklara gömülsün bu izbe duruşlarım.', 'Ben ki, bu koskocaman okyanusta kaybolmuş küçücük bir dal parçasıyım forsasız Zifiri aydınlıkların muhteşem karanlıklarında dualara açmışım ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-bakisi-yurttur-gozlerinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı.', 'sevdali-sedat-alkan-79bt8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlasam gecelerce, haykırsam gökyüzüne.

Dünya güzeli gelse, girer mi şu kalbime.

Koklar mıyım saçlarını, 

Donur muyum sen yerine.

Sarılıp yastığıma uyuyorsam yalnız gecelerce.

Bir an, bir an düşün, sor şu zalim yüreğine.

Görür müyüm başkasını dünyaya gelsem yine.

Geldi mi böyle sevdalı cümle aleme.

Bir bilsen, bir görsen, şu perişan halimi.

Berduş oldum, meyhaneci alma benim kadehimi.

Öldür beni öldür. Ama gözlerime son kez bak.

Felek bile anladı vurmaz artık, görür halimi.', 'Ağlasam gecelerce, haykırsam gökyüzüne. Dünya güzeli gelse, girer mi şu kalbime. Koklar mıyım saçlarını,  Donur muyum sen yerine. Sarılıp ya...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdali-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Soluklanabilirsin**', 'soluklanabilirsin-burcu-alpaslan-guvenli-44b19', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '….

……

…….bitti

………soluklanabilirsin

gece yarısı ağlayışlarında

soluksuzca kalp sesini dinlediğin

acıya yüreğini teslim ettiğin

gidişler ve gelişler 

….

……

…….bitti

………soluklanabilirsin

oh be çekip

güneşi gördüm ya dediğin

hiçbir şeyin 

geceden ayrı olmadığı

güneşinin rengini çalan 

o sefil kanamalı günler

….

……

…….bitti

………soluklanabilirsin

şimdi; 

güneşin senin içinde doğduğu 

dağlarında yeşil gözlerini yıldız diye saldığın

evleri tutku kokan

çocukların meyve niyetine 

dallarda sallandığı köylere geldin….

….

……acı/n

………BİT/ti

…………toprağına geldin

…………….soluklanabilirsin

13-08-2005 - İstanbul', '…. …… …….bitti ………soluklanabilirsin gece yarısı ağlayışlarında soluksuzca kalp sesini dinlediğin acıya yüreğini teslim ettiğin gidişler ve g...', ARRAY['Türk Edebiyatı','Şiir','Burcu Alpaslan Güvenli']::text[], 8.5, '{"poet":"Burcu Alpaslan Güvenli","poet_slug":"burcu-alpaslan-guvenli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/soluklanabilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İle', 'senin-i-le-i-sa-tekin-1qcws', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin ile yaşadım

Hasreti, kederi özlemi

Senin ile anladım

Doğruyu gerçeği

Senin ile buldum

İyiyi güzeli

Senin ile paylaştım

Yalnızlığımı dertlerimi

Senin ile yaşadım

Sevgimizi sevdamızı

Senin ile düşündüm seni

Senin ile özlemimiz bir

Umudumuz tek

Senin ile dikeceğiz elbet

Umut fidelerini

Gerçek mutlu yarınlarımızda

El ele göz göze koşacağız senin ile', 'Senin ile yaşadım Hasreti, kederi özlemi Senin ile anladım Doğruyu gerçeği Senin ile buldum İyiyi güzeli Senin ile paylaştım Yalnızlığımı de...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senin-ile-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzlaşmak', 'sonsuzlasmak-i-sa-tekin-obte5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünmek 

Ta a doruklarda

Bulutlar arasında seni

Gökyüzünün maviliklerinde 

Kaybolmak 

Sevdam ile baş başa

                     Sonsuzlaşmak', 'Düşünmek  Ta a doruklarda Bulutlar arasında seni Gökyüzünün maviliklerinde  Kaybolmak  Sevdam ile baş başa                      Sonsuzlaşmak...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sonsuzlasmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun', 'suskun-i-sa-tekin-wkz4t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve ben yine durgun

Vurgun yedim içimde

Kanıyor yüreğim

Karanlık geceler

Bitmek bilmiyor

Ben suskun ben yalnız', 'Ve ben yine durgun Vurgun yedim içimde Kanıyor yüreğim Karanlık geceler Bitmek bilmiyor Ben suskun ben yalnız...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/suskun-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana İhtiyacım Var', 'sana-i-htiyacim-var-omer-aslan-chjxc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum

Resmine bakıyorum aralıksız

Ve seni yaşıyorum her saniye

Uzaktasın şimdi

İçim sızlıyor

Alevler içinde yanıyor yüreğim

Gel de söndür bir tanem

Sana ihtiyacım var.

Resmin karşımda, sen kalbimdesin

Ama tutamıyorum işte

O zarif ellerini avuçlarıma alıp

Süremiyorum yüzüme,

Ve öpemiyorum parmaklarının ucundan.

Sensizlik yara açtı sinemde

Aralıksız kanıyor

Gel de dindir birtanem

Sana ihtiyacım var.

Dolunay doğmazdı utancından

Güneş ar ederdi Yüzünü görseydi

Sana rağmen ‘güzelim’ demek kimin haddine

Sensin karanlıkları boğan dolunay

Sensin kainatın güneşi.

Ve benim hayat verdiğin kişi

Ama uzaktasın

Gel sevindir birtanem

Sana ihtiyacım var.

Kaşların yay gibi gerilmiş

Ceylan bakışlı gözlerinin üstüne

Yanakların al al, dudakların gül. 

Ak alınlım, dolunay çehrelim

Bu güzellik tarif edilemiyor kelimelerle

Sakın abartıyorsun deme bana

Sana acıkmış, sana susamışım yıllardır

Seni özlemiş, seni beklemişim

Seni sayıklamışım uykularda

Seni sevmişim kalabalıklarda

Ve seni ağlamışım ıssız yerlerde

Gel de güldür bir tanem

Sana ihtiyacım var.', 'Seni düşünüyorum Resmine bakıyorum aralıksız Ve seni yaşıyorum her saniye Uzaktasın şimdi İçim sızlıyor Alevler içinde yanıyor yüreğim Gel d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Aslan']::text[], 8.5, '{"poet":"Ömer Aslan","poet_slug":"omer-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sana-ihtiyacim-var-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-turan-civelek-cmv3o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün, bir ağırlık çöktüğünde üzerine

Yalnızlığa, yalnızlığına doğru yöneleceksin.

Sevemeyeceksin, sevilmeyeceksin

Kahreden sonsuzluk isteğini

Yalnızlığında hissedeceksin

İsteklerinin ötesindesin artık

Sanma ki istediğin yerdesin

Bir büyük yalnızlık içinde

Bilinmeyen bir yerdesin.

Aykırısın artık bu dünyaya sen

Ya da ayrısın küçük dünyandan

Ve gerçekte içinde olan yalnızlığı

Yalnızlığında hissedeceksin.

İstemesen de, yahut istesen de onu

Bulunmaz bir noktadasın artık

Yeterince uzaklaşmışken kendinden

Yalnız kaldığını görecek, üzüleceksin.', 'Bir gün, bir ağırlık çöktüğünde üzerine Yalnızlığa, yalnızlığına doğru yöneleceksin. Sevemeyeceksin, sevilmeyeceksin Kahreden sonsuzluk iste...', ARRAY['Türk Edebiyatı','Şiir','Turan Civelek']::text[], 8.5, '{"poet":"Turan Civelek","poet_slug":"turan-civelek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizlik-268-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sade Bedenler', 'sade-bedenler-turan-civelek-3480n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat geçerken acımasız...

Anlamsızca bakarken insanlar

Ve kimse düşünmezken yarını

Veya sorgulamazken dünü

Sahte yaşamların teslim aldığı

Sade bedenlerdir konuşanlar...', 'Hayat geçerken acımasız... Anlamsızca bakarken insanlar Ve kimse düşünmezken yarını Veya sorgulamazken dünü Sahte yaşamların teslim aldığı S...', ARRAY['Türk Edebiyatı','Şiir','Turan Civelek']::text[], 8.5, '{"poet":"Turan Civelek","poet_slug":"turan-civelek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sade-bedenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altıdan sonraki altı', 'altidan-sonraki-alti-adnan-gul-jb0lo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bitti dediğiniz yerin,

gözesi yıkıyor aklımı...

nasıl da kolaymış, yarına kalan şeyler! 

dalımda tazecik yalan...

kolumda haklı günah...

ve akşama benzeyen sabah...

en çok zaman gizliyor, inci hatalarımı

bakamadım henüz; 

yer almakta mı mavi gözleriniz,

can tufanımda..

kırılmış dalını bilen kökler

toprağa muhalif taş

ve rüzgarlar deminde mi,

uçma özlemine düşen, şu kuşun...

değil miyim ki, okkasız tartılan

değil miyim 

rengi olmalı diyen sevmenin...

anlayarak yoluna çekilen,

ilk adımında...

nasıl olur ters yürümek yarayı

nasıl kalırdı ki lallık,

geceye boşalan ışıkta...

''sıcak vesika'' adlı kitaptan', 'bitti dediğiniz yerin, gözesi yıkıyor aklımı... nasıl da kolaymış, yarına kalan şeyler!  dalımda tazecik yalan... kolumda haklı günah... ve ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gül']::text[], 8.5, '{"poet":"Adnan Gül","poet_slug":"adnan-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/altidan-sonraki-alti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zzzzz / Yar Beni İki', 'zzzzz-yar-beni-i-ki-bir-mim-kemal-ertugrul-ds37q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yar beni yar yar beni 

PEK sever o yar beni 

Gözlerini kapatır 

Rüzgardan koklar beni 

Yar beni yar yar beni 

ÇOK sever o yar beni 

Ellerini uzatır 

Göklerden toplar beni 

Yar beni yar yar beni 

HEP sever aşkla beni 

Düşlerine yasaklar 

S__usunda s_aklar beni.. 

(Düşlerine yasakla 

S_usunda s_akla beni..!)', 'Yar beni yar yar beni  PEK sever o yar beni  Gözlerini kapatır  Rüzgardan koklar beni  Yar beni yar yar beni  ÇOK sever o yar beni  Ellerini...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zzzzz-yar-beni-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül Olan Bendim', 'kul-olan-bendim-mehmet-bulut-qdbox', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bıçak sırtındayım

Ne yana değil

yansız bir yerdeyim

Deşildim...

Tırnaklarımı çektiler

bilmem kaç voltajda tutsak oldum...

Ağlama sen artık

Ne olur! ..

Duyamıyorum.

Ne yaz nede kıştı,

güzdü belkide 

çünkü suskundun.

kül olan bendim oysa

Hani ''''demirin tercihi değildiya 

katil bir bıçak olmak.''''

artık zaruri  ihtiyaç oldu 

Bıçak olmak...', 'Bıçak sırtındayım Ne yana değil yansız bir yerdeyim Deşildim... Tırnaklarımı çektiler bilmem kaç voltajda tutsak oldum... Ağlama sen artık N...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kul-olan-bendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevme Beni', 'sevme-beni-i-lknur-er-mhm4a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevme beni

Seni sevmemin ödülü olma

Sağ elimmi, sol elimmi diye sorma

Biliyorum

İkisindede bensizlik var

Yüreğinde olmadıktan sonra

Yanında olmanın anlamı ne

Sevme beni

Hoyrat bakışlarını çek üzerimden

Yakalanırsam gözlerine bir kez

Bir daha çözemem bağlarını yüreğimden

Sevme beni', 'Sevme beni Seni sevmemin ödülü olma Sağ elimmi, sol elimmi diye sorma Biliyorum İkisindede bensizlik var Yüreğinde olmadıktan sonra Yanında ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevme-beni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Bir Anlık Talan....', 'yasam-bir-anlik-talan-can-ceylan-tl2t1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Basma kurbanın olam

Dala çalı çırpıya

Kalmadı tahammülüm

Ne ses ne çıtırtıya

Gözlerim bağlanmıyor

Mehtap ve pırıltıya

Yüreğim dayanmıyor

Ne şiir ne şarkıya

Dünyada mal mülk yalan

Yar olmaz eşkiyaya

Yaşam bir anlık talan

Değmez pılı pırtıya

Mahkum olmak bir dram

İflah olmaz tutkuya

Dünyada darmış mekan 

Derken girdik kuytuya', 'Basma kurbanın olam Dala çalı çırpıya Kalmadı tahammülüm Ne ses ne çıtırtıya Gözlerim bağlanmıyor Mehtap ve pırıltıya Yüreğim dayanmıyor Ne ...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasam-bir-anlik-talan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimdeki Sen', 'kalbimdeki-sen-i-sa-tekin-ijnpa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimdeki parıltı

İçimdeki coşku

Kalbimdeki sen,

Ve sen canımdan can

Nice aşk depremleri yaşadık

Seninle dört mevsimde 

Dört mevsim güllerini kokluyoruz         

                            Aşkımızın gölgesinde

                            Birde o bakışların

                            O bakışların değişmesin

                            Şu sevgi dolu günlerimizde.', 'Gözlerimdeki parıltı İçimdeki coşku Kalbimdeki sen, Ve sen canımdan can Nice aşk depremleri yaşadık Seninle dört mevsimde  Dört mevsim gülle...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kalbimdeki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-akin-akcan-n4d3v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce sevdiğini söyle

Sensiz yapamam,

Hayatım sensiz anlamsız de

Sonra yüzüstü bırak git

Hayallerimiz vardı,

Yakında mutlu olacaktık

Sen bensiz ben sensiz yapamazdık hani

Öylesine avut gönlümü sonrada bırak git

Çocuklarımız olacaktı hani

Aşkımızı anlatacaktık onlara,

Aşkımız ebedi olacaktı,

Dişi kuş gibi yuva kur sonra terket git

Beni tanıdığın gün hani doğduğun gündü

Mutluydun benimle öyle diyordun,

Hani nerde kaldı mutluluk nerde kaldı aşkımız

Mutluluk mu bıraktın bende hadi gözyaşlarıma acıma git

Hani benimle olduktan sonra,

Kuru bir ekmeği bile paylaşacaktık

Beraber oturup bir birimize aşk şiirleri yazacaktık

Bana mutluluk yerine ayrılık şiirleri yazdır sonra git

Hani ben sabahları geç kalkardım ya

Sende bir o kadar erken kalkardın

Hazırladığın kahvaltı ve mis gibi çay kokusuyla 

Uyandıracaktın beni,söz vermiştin hani

Çayı ateşte bırak sonra da git

Bırakıp gittin ya beni varsın kalayım tek başıma

Uzaktan da olsa,dokunamasam da sana

Yanımda olamayacağını bile bile özleyecek

Ebediyyen de seveceğim seni.', 'Önce sevdiğini söyle Sensiz yapamam, Hayatım sensiz anlamsız de Sonra yüzüstü bırak git Hayallerimiz vardı, Yakında mutlu olacaktık Sen bens...', ARRAY['Türk Edebiyatı','Şiir','Akın Akcan']::text[], 8.5, '{"poet":"Akın Akcan","poet_slug":"akin-akcan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/git-126-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Annem Annemmmm..', 'annem-annem-annemmmm-munevver-duver-do75b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlamıyorsun başına gelmediği zaman

Bilemiyorsun ayrılık olmadığı zaman

Yalnızlığın ne olduğunu annem.

DÜŞÜNÜYORSUN

için yanıyor

Yürdüğün, gittiğin

Her yerde.

DÜŞÜNÜYORSUN

Ayrılığın acısını.

İçine koyuyorsun

Böyle yaşayıp duruyorsun

En güzel yıllarını.

DÜŞÜNÜYORSUN.

Sensizliğin içinde

Seninle yaşıyorum sensizliği annem..

Bazan rüyama geliyorsun

İçimi yakıyorsun

Yinede yalnzlığımda sen oluyorsun

ANNEM ANNNEM ANNNEM.

25/052005 te kaybettiğim annemin

anısına.

www.munevverduver.com

26/06/2005

Güzel yalı/pazar

saat.08.18

ADANA', 'Anlamıyorsun başına gelmediği zaman Bilemiyorsun ayrılık olmadığı zaman Yalnızlığın ne olduğunu annem. DÜŞÜNÜYORSUN için yanıyor Yürdüğün, g...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/annem-annem-annemmmm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Vardı', 'ask-vardi-i-lknur-er-t9ke1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk vardı

Senden öte, benden öte

Bu şehrin üzerine çöktüğünde

Tüm aşıklar birbirine koşardı

Çekildiğinde ise 

Savrulurdu hayatlar

Aşk vardı

Aşıkların gözlerinden doğardı güneş

Mutluluğa gebe olurdu yarınlar

Karanlık çöktüğünde ise

Kaçardı aşk, kararırdı umutlar

Aşk vardı

Alevler yanardı gönüllerde

Buram buram aşk kokardı hava

Sen kokardı

Sen giderdin, O kalırdı

Aşk vardı', 'Aşk vardı Senden öte, benden öte Bu şehrin üzerine çöktüğünde Tüm aşıklar birbirine koşardı Çekildiğinde ise  Savrulurdu hayatlar Aşk vardı ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-vardi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Diye Bakıyorum', 'annem-diye-bakiyorum-munevver-duver-mrpst', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana benzeyen herkese

Bakıyorum....

Seni hatırlatıyor bana

Seni....

Ya yürüyüşü 

Sana benzeyen

Ya da gülüşü

Ya da gidişi

Sanki seni görüyorum.

Seni hatırlatıyor

Bakıyorum..

İçim acyor

seni bulamayıp

Dönüp gidiyorum

Gözüm yaşlı

Yine sensiz kalıyorum..

25/05/2005 te kaybettiğim 

annemin anısına.

www.munevverduver.com

28/05/2005/cumartesi

Güzel yalı.saat 00.59

ADANA', 'Sana benzeyen herkese Bakıyorum.... Seni hatırlatıyor bana Seni.... Ya yürüyüşü  Sana benzeyen Ya da gülüşü Ya da gidişi Sanki seni görüyoru...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/annem-diye-bakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların Raks Etsin Güzel', 'saclarin-raks-etsin-guzel-osman-erdogmus-9c9ac', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SAÇLARIN RAKS ETSİN

Tokalarını çöpe at

Saçların raks etsin güzel.

Böyle daha güzel hayat

Saçların raks etsin güzel.

Hapsetme sakın onları

Rengine kurban sapsarı 

Üzme çıkacak rüzgarı

Saçların raks etsin güzel.

Sallandırsın bir o yana

Vurdursun bir de bu yana

Aşık gibi yana yana

Saçların raks etsin güzel.

Deniz gibi dalgalansın

Şelale gibi çağlasın

Bırak da dağınık kalsın

Saçların raks etsin güzel.

Kapıldım sevda seline

Düşürdün alem diline

Kalbim bağlandı teline

Saçların raks etsin güzel. 

Osman Erdoğmuş

Aşk İklimi

Kitabından alınmıştır', 'SAÇLARIN RAKS ETSİN Tokalarını çöpe at Saçların raks etsin güzel. Böyle daha güzel hayat Saçların raks etsin güzel. Hapsetme sakın onları Re...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/saclarin-raks-etsin-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatandaşın resti', 'vatandasin-resti-durmus-karakus-evg2l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu yalan dolanlarla kendinizi kandırın

Foyanzıı öğrendik hazırlandı şişiniz

Millet kuruşa hasret siz dolara bandırın

Sandıkta görüşürüz bitti sizin işiniz.

Her gün izlettirerek ABD nin bandını

Bize unutturdunuz ATATÜRK ün andını

Hiç boşuna yırtmasın vekilimiz kendini

Sandıkta görüşürüz bitti sizin işiniz.

Birde bize sorsunlar çeklen acıları,

Halimize gülüyor gevurun öcüleri.

Sizi oy dilencisi duygu sömürcüleri,

Sandıkta görüşürüz bitt sizin işiniz.

Tükendi siyasinin sol cusuyla sağ cısı

Bunlar fırsat düşkünü sanki domuz bağcısı

Avrupanın uşağı amerikan yağcısı

Sandıkta görüşürüz bitti sizin işiniz.

KARAKUŞ um aç dolu yurdumun dört bölgesi

Düştü tüm ülkemize işsizliğin gölgesi

Yakında alınacak sizden yetki belgesi 

Sandıkta görüşürüz bitti sizin işiniz.

                                                  17 şubat 2002  GÖZCÜ GAZETESİ', 'Bu yalan dolanlarla kendinizi kandırın Foyanzıı öğrendik hazırlandı şişiniz Millet kuruşa hasret siz dolara bandırın Sandıkta görüşürüz bitt...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vatandasin-resti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-kenan-mim-eryigit-um2gi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güller diyarının ol gülzârında, 

Henüz goncasında, narin bir gülsün! .

Hiç paha etmez bu gam pazarında 

Bahtın açık olsun, yüzün hep gülsün! .', 'Güller diyarının ol gülzârında,  Henüz goncasında, narin bir gülsün! . Hiç paha etmez bu gam pazarında  Bahtın açık olsun, yüzün hep gülsün!...', ARRAY['Türk Edebiyatı','Şiir','Kenan Mim Eryiğit']::text[], 8.5, '{"poet":"Kenan Mim Eryiğit","poet_slug":"kenan-mim-eryigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kizima-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-orhan-kutlu-tdolx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana kendimi anlatayım biraz dinle,

Ölümden başka her acıyı tatmış,

Ölümü yaşamışım ölmeden,

Acılar çekmiş yoğun bir acıyım.

Bir dünya kurmuşum kendime sensiz

35''''i geçmiş

Cahit Sıtkı Tarancı ''yım.

Bazen sevdalar yaşamışım

Sonu hep ayrılıklarla biten,

Hasret ateşinde yanmışım

Hüzünlere boğulmuş bir deliyim

Bir elinde cımbız, 

Bir elinde ayna diyen

Orhan Veli''''yim.

Kader nereye sürüklemiş 

Arar bulamam kendimi.

Ne zaman kayboldum bilemem

Bu halime hep şaşarım.

Beden kayıp, ruh kayıp

Belki senin elinde

Acılar denizindeki

Ümit Yaşar''''ım.

Şimdiyi sorma sakın

Aynı tas aynı hamam

Hazırım gitmeye nereye olursa

Toplanmış tarağım, tasım.

Bir yalnızlık girdabında

Yalnızlık paylaşılmaz diyen

Özdemir Asaf''''ım.

Orhan Kutlu', 'Sana kendimi anlatayım biraz dinle, Ölümden başka her acıyı tatmış, Ölümü yaşamışım ölmeden, Acılar çekmiş yoğun bir acıyım. Bir dünya kurmu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ben-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökte Ay Tutuşur Yerde Ben', 'gokte-ay-tutusur-yerde-ben-guzin-eye-dundar-ypv7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gökte ay düşünür 

yerde ben 

sakin  gece

belli ki fırtına öncesi

ağlamak gelir içimden

bir çocuk gibi

yüzün düşer yüreğime

beş mevsim

ertelenmiş zamana 

isyanın deliliğisin 

ölümsüzlüğe davet 

aşk için 

kabuğunu soy 

-ey ruh yine 

nerdesin? 

gel...bu son fırtınayı seyret.', 'gökte ay düşünür  yerde ben  sakin  gece belli ki fırtına öncesi ağlamak gelir içimden bir çocuk gibi yüzün düşer yüreğime beş mevsim ertele...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gokte-ay-tutusur-yerde-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Şubat sensizde olsa kutlu olsun Sevgilim', '14-subat-sensizde-olsa-kutlu-olsun-sevgilim-orhan-kutlu-wc1ng', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün 14 Şubat

Sevgililer günü

Sevilenler sevenlerden aşk mesajları almakta,

Bir deste gül

Bir mesaj kısada olsa

Bir hatırlanış,

Oysa ben seni hiç unutmadım.

Bugün aşk tazelemede aşıklar

Aşklarına yeni güç katmadalar

Yeni sevilerle yeni ufuklara açılmadalar

Oysa benim sana olan aşkım

Daha dün gibi taptaze, 

Dağ gibi yüreğimde

Seni düşünmekten kendimi alamadım.

Bugün sana seslendiğim günlerden farksız benim için

Her gün diğerinin fotokopisi

Ne günler değişiyor bende

Ne de içimde tüten aşkın

Sadece geleceğin gün değişecek benim için

Tarih değişecek dünya ile birlikte

Hiç bir an seni beklemeden yaşamadım.

Orhan Kutlu', 'Bugün 14 Şubat Sevgililer günü Sevilenler sevenlerden aşk mesajları almakta, Bir deste gül Bir mesaj kısada olsa Bir hatırlanış, Oysa ben se...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/14-subat-sensizde-olsa-kutlu-olsun-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**(Sevda Katiline Çıktı Adımız) **', 'sevda-katiline-cikti-adimiz-seyhmus-sevilmez-c62ye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanıyor bir yerler

Yükseliyor itfaiye sirenleri..

Feryat, figan çığlıklar dürtüklüyor,

Oynadığım uyku rolünden, uyandırıyor beni 

“Kurtarın! ...., Kurtarın beni! ... ” sesleri

Derin bir gayyadan yansıyıp

Deliyor kulak zarımı..

Kavruluyor bir yerler

Ve içerde mahsur kalan birileri

Sökmüşler yangın merdivenlerini

Kaçış yok! ..,

Bir yürek yangınının dumanları yükseldikçe,

Kısık sesli sevdandı, son nefesini veren…

Oysa; 

Yüreğimin yangınları kalkmışken şaha,

Donuyor bir yerler....

Zemheri yüreğinin

Soğuk zindanlarında,

Timsahın gözyaşlarıyla ıslanan sevdamı

Dondurarak öldürmüşsün…

Sevda katiline çıktı adımız...

Unutursan donuyor,

Unutmasan yanıyor sevdalar…

Artık anladım ki,

Sevginin bile, fazlası zarar

15.08.2005', 'Yanıyor bir yerler Yükseliyor itfaiye sirenleri.. Feryat, figan çığlıklar dürtüklüyor, Oynadığım uyku rolünden, uyandırıyor beni  “Kurtarın!...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevda-katiline-cikti-adimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiryakin Oldum', 'tiryakin-oldum-osman-erdogmus-loczw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TİRYAKİN OLDUM

İçkiyi sevmiyorum

İçmesi haram olduğundan

Müptelası da olmadım hiçbir zaman

Hatta nefret bile ederim kokusundan

Bu yüzden o konumuzun dışında.

Fakat güzel bir sigara içicisiydim

Kelimenin tam anlamıyla

Tiryakisiydim.

Kırk yıllık ömrümün

Yirmi dört yılını beraber yaşadık.

Öyle bir beraberlik ki

Akşama kadar kalbimin üstünde

Yatarken de baş ucumda dururdu.

Şayet gece aklıma düşersen

Uykumu kaçırırsa sensizlik

Bana teselli olurdu.

Yıllarca sigara dumanıyla

Seni içime çekmişim

Üflediğim dumanıyla da 

Resmini yaptım havada

Aklıma ne zaman düşsen

Olan sigaraya oluyor

Onunla beraber yanıyor

Onunla beraber bitiyordum.

Sigaradan da kıskandım seni

Sen kalbimin içindeyken

O ağırlık yapıyordu üstünde

Çıkarıp attım onu

Gömleğimin cebinden.

Ne beni tüketecekti artık

Ne de umutlarımı

Bir gün geleceksin düşüncesiyle

Yaşayacağım yarınlarımı

Öksürükle uyandıramayacak beni

Hasretinle başımı yastığa koyduğumda

Daha uzun göreceğim rüyalarımı

Artık senin tiryakin olacağım

Sadece kalbimi değil

Bütün azalarımı

Seninle donatacağım.

Gülleri çöpe atıp

Sana sevdamı sunacağım.

Şu fani dünyada kalan ömrümü

Seni mutlu etmek için harcayacağım.

Seni içeceğim şu alemde

Seni üfleyeceğim

Aldığım her nefeste

Seni soluyacağım.

Osman Erdoğmuş

Aşk İklimi

Kitabından alınmıştır', 'TİRYAKİN OLDUM İçkiyi sevmiyorum İçmesi haram olduğundan Müptelası da olmadım hiçbir zaman Hatta nefret bile ederim kokusundan Bu yüzden o k...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/tiryakin-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleriyle Konuşan Dilsiz', 'gozleriyle-konusan-dilsiz-umit-engin-zg0l8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Parçalanmış bir beden,

Yılların eziyetine dayanamamış,

Benliğini kaybetmiş bir zihin,

Hep ben diyenlere yenilmiş,

Özgürlüğünü yitirmiş bir yürek,

Kendini içine kapamış,

Her gece esaretinde aşkın,

Gözleriyle konuşan bir dilsiz…

15.08.2005 / 11:40 / Ümit Engin', 'Parçalanmış bir beden, Yılların eziyetine dayanamamış, Benliğini kaybetmiş bir zihin, Hep ben diyenlere yenilmiş, Özgürlüğünü yitirmiş bir y...', ARRAY['Türk Edebiyatı','Şiir','Ümit Engin']::text[], 8.5, '{"poet":"Ümit Engin","poet_slug":"umit-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozleriyle-konusan-dilsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tertibim', 'tertibim-durmus-karakus-f61qs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben deli aşklara hiç inanmazdım

Sanki bir köleydi kul du tertibim

Eyvahlar ederek böyle yanmazdım

İçmeden kafayı buldu tertibim.

Aşkını anmasa o gün yatmazdı

Sevda dilenmezdi asla satmazdı

Doğrunun üstüne yalan katmazdı

Anlatacak sözü boldu tertibim.

Hep mutlu bir yuva hayal ederdi

Ne küser darılır ne kin güderdi

Sırtında taşıdı binlerce derdi

Kaderin hamalı oldu tertibim.

Bazen takılırdım ele uyunca

Gülüpte geçerdi öyle huyunca

Dünyası yıkıldı bunu duyunca

Saçını başını yoldu tertibim.

İçini yakarken sevdanın kavı

Kurdun yemi oldu çakalın avı

Gönlüne atmışlar ihanet lavı

Bir tek bacak bir tek koldu tertibim.

Bu nasıl bir sözdü nasıl öğüttü

Derdini hep değirmendi öğüttü

Yemyeşil bir selvi salkım söğüttü

Sonunda sarardı soldu tertibim.

Şahit bu sevdaya köyü obası

Sırtından çıkmadı kara abası

Çilenin kederin derdin babası

Bir akşam ansızın öldü tertibim...', 'Ben deli aşklara hiç inanmazdım Sanki bir köleydi kul du tertibim Eyvahlar ederek böyle yanmazdım İçmeden kafayı buldu tertibim. Aşkını anma...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tertibim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dimi?', 'dimi-dilek-egri-s190w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir esmer gecede düştü yolum gözlerine...

karanlıktı

ıssızdı ama

sıcacık....

sonra bir yıldız 

....tam gözbebeğinde

...............rehberim oldu! 

aldı yüreğine götürdü beni

her köşesi iltifatlarla dolu...

tanıdık değildik.

hiç alışılmadık

sen şikayetçi

ben şikayetçi

haketmedik ayrılıklar yaşadık...

o ilk dokunuş

biraz ürkek

biraz şaşkın

hani Pieere Loti şahit! 

elinin kolumda titremesi

dönmeyecekleri boşa bekleyen beni

kendime getirdi...

...keşke her kabustan sonra 

.........böyle dokunuşlar uyandırsa beni! 

sendede bitmiş inanışlar

ilk görüşte aşkmış

yalan! 

derken

ben inandırmışım ya seni

bir bir anlatıcam

yüreğime seni..

..............yalan değil 

........................dimi? 

(7 Ağustos Pazar 2005)', 'bir esmer gecede düştü yolum gözlerine... karanlıktı ıssızdı ama sıcacık.... sonra bir yıldız  ....tam gözbebeğinde ...............rehberim ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse...', 'gulumse-ozgur-celik-v40zh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen,

