INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh İsyana Köle Ferman Diye!', 'ruh-i-syana-kole-ferman-diye-necmi-unsal-ujw9m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bülbülü nerede bu gülşenin? 

Mesken tutmuş ömrü kof kargalar.

Kaldıranı yok mu bu düşenin? 

Çıkar bölüşmede hep kavgalar.

Kutlu bir nağmeye kalpler muhtaç.

Kor içilir derde derman diye! 

Günah olmuş başlar üstünde taç.

Ruh isyana köle ferman diye! 

30 Haziran 2004 Çarşamba, Danimarka-Køge 20.47

6+4', 'Bülbülü nerede bu gülşenin?  Mesken tutmuş ömrü kof kargalar. Kaldıranı yok mu bu düşenin?  Çıkar bölüşmede hep kavgalar. Kutlu bir nağmeye ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruh-isyana-kole-ferman-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Sen Olmayınca', 'annem-sen-olmayinca-munevver-duver-agnv1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adana''nın ilk baharı oldun gönlümde

Baktıça göle duygulanıyorum 

ANNEM.............

Güzel yalının gülü diyordun bana

Oldun ADANA''nın nisan yağmuru

ANNEM..............

Nisan yağmuru gibi çabucak gittin

Bakınca uğur mumcu''ya

ANNEM.............

Doğmuyor güneş.

seyhana baktığım zaman

ANNEM................

Atmıyor yağmur tanesi

Sen olmayınca 

ANNEM...........

Bir başka oldu

Turgut özal''ın havası

ANNEM............

Sen olmayınca

Sen sen

ANNEM............

Menderes kenarında

Güzel çamlıklar

ANNEM...........

Villayın önündeki

Açan çiçekler

ANNEM..........

Açmıyor artık

