INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskandı', 'kiskandi-serkan-sekban-129gc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsmine bir şarkı yazdım

Söyleyenler kıskandı

Sana bir şiir yazdım

Okuyanlar kıskandı	

Mutluluktan uctum ben

Kuşlar beni kıskandı

Seninle oldugum gün

Gece beni kıskandı

Seni gören her insan

İnan beni kıskandı

Sana olan aşkımı

Mecnun bile kıskandı

12 / 08 / 1996', 'İsmine bir şarkı yazdım Söyleyenler kıskandı Sana bir şiir yazdım Okuyanlar kıskandı	 Mutluluktan uctum ben Kuşlar beni kıskandı Seninle old...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kiskandi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Aşkı Söyler', 'gozlerin-aski-soyler-ali-gulsoy-6tmad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin aşkı söyler

Bana her bakışında

Gönlümü mecnun eyler

Sanki tatlı bir rüya

Dalarım uyanamam

Alışmışım ben sana

Sensiz hiç dayanamam

Beni düşürdün aşka

Çok severim doyamam

Senin yerin bir başka

Hiç kimseyi koyamam

Sevdan öyle bir şeyki

Sevgi çok akışında

Hasretin rüzgar gibi

Sürükler hep peşinde', 'Gözlerin aşkı söyler Bana her bakışında Gönlümü mecnun eyler Sanki tatlı bir rüya Dalarım uyanamam Alışmışım ben sana Sensiz hiç dayanamam B...', ARRAY['Türk Edebiyatı','Şiir','Ali Gülsoy']::text[], 8.5, '{"poet":"Ali Gülsoy","poet_slug":"ali-gulsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerin-aski-soyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhammed''i Görüyorum', 'muhammed-i-goruyorum-abdurrahman-tepe-2sr73', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gül ben sana hep baktıkça

Muhammed''i görüyorum

Aşkı kalbimi yaktıkça

Muhammed''i görüyorum

Gel öyle kalma enginde

Güzel yok senin denginde

Gül ben senin o renginde

Muhammed''i görüyorum

Sabah seher yıldızında

Feleklerin bu hızında

Gül ben senin şu nazında

Muhammed''i görüyorum

Çok güzelsin kal dalında

Aşkı çekenin elinde

Gül ben senin o halinde 

Muhammed''i görüyorum

Kul SAMİHİ geldi geçti

Sırrını bir güle açtı

Özü gülden bir yar seçti

Muhammed''i görüyorum', 'Gül ben sana hep baktıkça Muhammed''i görüyorum Aşkı kalbimi yaktıkça Muhammed''i görüyorum Gel öyle kalma enginde Güzel yok senin denginde Gü...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/muhammed-i-goruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatun', 'hatun-yusuf-kucukosman-3ktk5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'buladık bi hatun

aradık olmadı sorduk olmadı

kısmetimizmi bağlandı ne

          paramız yoktu şimdi oldu

          namımız yoktu şimdi oldu

          olmadı beceremedik yinede

                  

                      kır dereden su getirdik

                      aşılmaz dağları aştık

                      uyy ben nerde hata yaptım

                                yaşı yaşımıza göre

                                 huyu huyumuza göre

                                 bulamadık bi hatun dişimize göre

                                               evet dermisin sen bana

                                               elin gitmez sıcak sudan soğuğa

                                               işle cennetlik b sevap', 'buladık bi hatun aradık olmadı sorduk olmadı kısmetimizmi bağlandı ne           paramız yoktu şimdi oldu           namımız yoktu şimdi oldu ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Küçükosman']::text[], 8.5, '{"poet":"Yusuf Küçükosman","poet_slug":"yusuf-kucukosman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hatun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuş Yüzlerdeki Hatıralar', 'unutulmus-yuzlerdeki-hatiralar-bekir-siddik-demircan-umdg4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutulmuş yüzlerde

Hatırlarım hatıraları

Hatra binaen selamlarım

Küstüğüm hatıraları.

Soğuk dururum kaskatı.

Selamım üşütür bergüzarı

İyice bürünür siyah paltosuna

Saklanır o siyahlığın arkasına

Çünkü bilir,

Sağanak yağacağım.

Katıp önüme geçmişe akacağım

Unutulan yüzlerdeki hatıraları

Yine unutulmuşluğa boğacağım.', 'Unutulmuş yüzlerde Hatırlarım hatıraları Hatra binaen selamlarım Küstüğüm hatıraları. Soğuk dururum kaskatı. Selamım üşütür bergüzarı İyice ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıddık Demircan']::text[], 8.5, '{"poet":"Bekir Sıddık Demircan","poet_slug":"bekir-siddik-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutulmus-yuzlerdeki-hatiralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tehlikeli Kış', 'tehlikeli-kis-ali-kemal-alagoz-suwse', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soğuk bir kış gününde

Yürüyorum ıssız sokaklarda

Sokaklar karanlık

Sokaklar tehlike içinde

Bir berfin düşmede yoluma

Bir berfin de yüreğime,

Korkmak yok yola devam

Kim karşına çıkarsa çıksın

Vazgeçmek yok diyorum kendime

Belki bugün son günüm

Belki bu son yürümek

Yok edecekler beni belki de

Ve bulamayacak bedenimi hiç kimse.', 'Soğuk bir kış gününde Yürüyorum ıssız sokaklarda Sokaklar karanlık Sokaklar tehlike içinde Bir berfin düşmede yoluma Bir berfin de yüreğime,...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal Alagöz']::text[], 8.5, '{"poet":"Ali Kemal Alagöz","poet_slug":"ali-kemal-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tehlikeli-kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-aytekin-kaya-cldtd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zilde olurdu yüreğimiz 

Çantalarımız sırtımızda 

Hani bi çalsada kurtulsak

yerlerimizden 

kirişten boşanan ok gibi

kulaklarımızda arkadaşların 

bilye sesleri

ben mavi bilyeyi severdim

hep uğur getirirdi bana

herkezi üterdim

ve sonra 

anneleri gelirdi 

alırdı ellerimden bilyelerimi

yerlere saçardım

sıkılır

sokak aralarında patlak top

oynardık

benim çocukluğumda 

arsalar boştu

henüz gökyüzünü görebiliyorduk

akşamları sırtüstü yatıp

yıldız tutardık

o zamanlar

boş arsalar vardı

koca koca binalar dikilmemişti

mahalleden arkadaşlarımız olurdu

mahalle maçları yapardık

terli terli su içerdik çeşmelerden

suya para vermezdik

ve mahalle kavgaları çıkarırdık

bizim çocukluğumuzda çocukluk vardı

vaktimizi 

hikayeler anlatarak

artis oynayarak

çember çevirerek yaşardık

bizim çocukluğumuzda büyüklerimiz

''telgırafın tellerine kuşlar mı konar'' türküsü 

dinlerdi

biz telgırafın tellerini bilirdik

bizim çocukluğumuzda herşey gerçekti

oynadığımız oyunlar,

sokak satıcıları,

elma şekerciler,

kağıt helvacılar...

on liraya elma şekeri alırdım

elma gerçekti,şeker gerçek

öğretmenimiz mektup yazmayı öğretirdi

o zamanlar herkez 

mektup yazardı

ve o zamanlar

siyah önlük giyerdik

ama yüreklerimiz

bembeyazdı', 'Zilde olurdu yüreğimiz  Çantalarımız sırtımızda  Hani bi çalsada kurtulsak yerlerimizden  kirişten boşanan ok gibi kulaklarımızda arkadaşlar...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Kaya']::text[], 8.5, '{"poet":"Aytekin Kaya","poet_slug":"aytekin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/cocuklugum-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazin Hazin', 'hazin-hazin-i-rfan-simsek-cn5eg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonbahar da gelmiş, sararmış her yan,

Yaprağı dökülmüş dal hazin hazin.

Güneş vurmuş güller, çiçekler solmuş,

Bülbül figân eder, gül hazin hazin.

        *********        *********

Kanadım kırılmış, olmuşum pare,

Ne yapsam derdime bulunmaz çare.

Uzak düştüm elim erişmez yare,

Avuçlarım bomboş, el hazin hazin.

        *********        *********

Bir yâr sevdasına yanmış İrfanî,

Ayrılığı ölüm sanmış İrfanî,

Nazlı yardan ayrı kalmış İrfanî,

Söyleyemez sözü, dil hazin hazin...

İrfan ŞİMŞEK    -    Ekim-1978', 'Sonbahar da gelmiş, sararmış her yan, Yaprağı dökülmüş dal hazin hazin. Güneş vurmuş güller, çiçekler solmuş, Bülbül figân eder, gül hazin h...', ARRAY['Türk Edebiyatı','Şiir','İrfan Şimşek']::text[], 8.5, '{"poet":"İrfan Şimşek","poet_slug":"i-rfan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hazin-hazin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Ay Doğuşu', 'yeni-bir-ay-dogusu-berrak-su-e4c1q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sancıların cemresi düştü toprağa,

Ateş su oldu,

Alevledi köprüleri,

Yazsonunun aymaz gülüşü, ayın koynunda

Salladı, salladı üşüyen güneşi.

Cemrenin son dansı toprakla,

Gece dolunayla tamamlandı.

Berrak Su', 'Sancıların cemresi düştü toprağa, Ateş su oldu, Alevledi köprüleri, Yazsonunun aymaz gülüşü, ayın koynunda Salladı, salladı üşüyen güneşi. C...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yeni-bir-ay-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-berrak-su-l7tz8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bildiği tüm öğretileri,

Doldurdu valizine.

Evrimin erte vaktineydi yolculuk.

Denizi tarttı, güneşi örttü.

Tüm irilikleri yaşamıştı,

Ve ışığını önüne kattı,

Omuzlarında mavi gagalar, el salladı bazukasına.

Yenildiği zamanları bilirdi,

Benzer yolların yorgunuydu o.

Sırçaları tüketmiş, ununu elemişti.

Karışma zamanları, ayrışma zamanları kalmadı.

İçinden çıktı tüm oyunların,

Evrimin öte vaktineydi yolculuk.

Berrak Su', 'Bildiği tüm öğretileri, Doldurdu valizine. Evrimin erte vaktineydi yolculuk. Denizi tarttı, güneşi örttü. Tüm irilikleri yaşamıştı, Ve ışığı...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yolculuk-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine mi Eylül...!', 'yine-mi-eylul-humeyra-yilmaz-alt2n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu yabancı gidişlere de alışır yalnızlığım

Şimdi bir kez daha Eylül’e hazır kasıklarımdaki sarı sancılar

Son avuntumun zilleri çalarken eteklerimde

Ertesi sevdalar yüreğimin kapısında gece gündüz nöbette

Korkuyorum

Kuytu sevişlerin sahici karanlıklarında parlarken göz yaşlarım 

Hangi tuzu kuru bağıra yaslasam şu eğik başımı bilmiyorum

Ellerimde, kuyruğuna gökkuşağını bağladığım uçurtmam

Dudaklarımda, ölümü bile korkutacak bir ıslıkla

Düne gidiyorum 

Geç kalışların nasırlaşmaya yüz tutmuş izleri değil canımı sıkan 

Belki temiz çarşaflara bulaşan hüznüm 

Belki sonunu  bildiğim masallardan çıkıp gelmiş birkaç yalancı kahraman

Belki de bir daha kutlanmayacağını düşündüğüm on sekizinci yaş günüm

Bilmiyorum 

Midemde yangınlar çoğaldıkça 

Sakin denizlerin, fırtına öncesi yazdığı şiirleri

Rüzgarın kucağında uyuyan hevesime okuyorum

Aklım başım da mı diye soruyorum yüreğime, susuyor

Ağlıyorum yıldızlar düşüyor gözlerimden 

Ve Eylül’e hazır sarı sancılarım bir kez daha canıma saplanıyor...!', 'Bu yabancı gidişlere de alışır yalnızlığım Şimdi bir kez daha Eylül’e hazır kasıklarımdaki sarı sancılar Son avuntumun zilleri çalarken etek...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yine-mi-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencerende Yağmur Var', 'pencerende-yagmur-var-murat-kilic-2-0k22h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', ''' tüm gönül pencerelerine...''

pencerende güneş besle, perdelerini aç.

yepyeni bir heyecana uyandırsın seni.

yeni yüzler tanı, sebepsiz gülücükler saç.

sevinçlerle süsle, bezet gönül ülkeni.

uyan artık.

bak pırıl pırıl bir gök getirdim sana.

yanı başında kar beyazı bulutlar.

uyan hadi bir bakıver pencerene,

pencerende yağmur var.', ''' tüm gönül pencerelerine...'' pencerende güneş besle, perdelerini aç. yepyeni bir heyecana uyandırsın seni. yeni yüzler tanı, sebepsiz gülüc...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/pencerende-yagmur-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört duvar arasında', 'dort-duvar-arasinda-serkan-sekban-hzmhh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçmiyor saatler geçmiyor günler

Bitmiyor burada çileler dertler

Sanki yil gibi burada günler

Dört duvar arasında insan neyler

Yakında değil ama bir gün sana

Kavuşmak tek dilegim ınan bana

Ölmezde yaşarsam eğer burada

Elbet bitecek bu ayrılıkta

Dört duvar var sade birde kapı 

Ufak bir pencere demirle kaplı

Sensizlik yakıyor her an içimi

İşte bunun en kötü yanı burası

	24 / 06 / 1998', 'Geçmiyor saatler geçmiyor günler Bitmiyor burada çileler dertler Sanki yil gibi burada günler Dört duvar arasında insan neyler Yakında değil...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dort-duvar-arasinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende öğrendim', 'sende-ogrendim-serkan-sekban-09vgj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlarken gülmeyi

İncitmeden sevmeyi

Güzel olan herşeyi

Ben sende öğrendim

Güle isim vermeyi

Gülü dikensiz sevmeyi

Güzel olan herşeyi

Ben sende öğrendim

Umut veren sözleri

Hayat dolu gözleri

Güzel olan herşeyi

Ben sende öğrendim

    22 / 08 / 2002', 'Ağlarken gülmeyi İncitmeden sevmeyi Güzel olan herşeyi Ben sende öğrendim Güle isim vermeyi Gülü dikensiz sevmeyi Güzel olan herşeyi Ben sen...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sende-ogrendim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balık olup açılsam', 'balik-olup-acilsam-serkan-sekban-uffb5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Balık  olup açılsam

Engin denizlere

Bulut olup yağsam

Yüksek tepelere

Güneş olup doğsam

Dağlara denizlere

Rüzgar olup savursam

Sevgimizi heryere

12 / 05 / 1999', 'Balık  olup açılsam Engin denizlere Bulut olup yağsam Yüksek tepelere Güneş olup doğsam Dağlara denizlere Rüzgar olup savursam Sevgimizi her...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/balik-olup-acilsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bayram Geldi', 'bir-bayram-geldi-i-sa-tekin-8t3sp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bir bayram daha geldi

İçimde bir burukluk

Geçmişin hüznü

Ve aç çocuklar

Köşe başlarında avuç açan yaşlılar

Ramazan davulu keyif vermiyor.

Radyoda caz sesleri

Tv. lerde idam senaryoları

Ölümler depremler felaketler

Yaşlı ve aç insanlar

Yine bir bayram geldi.

Tadı tuzu yok.

Ramazan davulu keyif vermiyor.

Ne dost kaldı ne akraba

Akraba değil bunlar karga

Leş arıyor, sevgiyi dostluğu katlederek.

Çamurlu sokaklarda elinde somun

Ayakları yarı çıplak çocuklar 

İçimde bir burukluk

Ramazan davulu keyif vermiyor.

Yüreğim yanıyor.

Geçmişin hüznü ve çocukluğumdaki

Bayramlar

Bayramlarda dostluk, bayramlarda sevgi

Ve coşku vardı içimizde 

Yine bir bayram geldi.

Köşe başlarında aç insanlar 

Ramazan davulu keyif vermiyor.

Ben suskun ben sensiz ben hüzünle

Hoş geldin bayram diyorum üzülerek', 'Yine bir bayram daha geldi İçimde bir burukluk Geçmişin hüznü Ve aç çocuklar Köşe başlarında avuç açan yaşlılar Ramazan davulu keyif vermiyo...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-bayram-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak bu ise', 'yasamak-bu-ise-serkan-sekban-0u6c3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çektiğim acıları kim nerden bilecek

Yaşadığım bu hayat elbet bir gün bitecek

Gözlerimi kaparken şu yalan dünyaya

Kim arkamdan ağlar bilmem kim gülecek

Yaşamak bu ise bende yaşıyorum

Ne nefes alıyor nede gülüyorum

Rüzgara kapılmış kuru bir yaprak gibi

Bir sağa bir sola savrulup duruyorum

                    11 / 04 / 2005', 'Çektiğim acıları kim nerden bilecek Yaşadığım bu hayat elbet bir gün bitecek Gözlerimi kaparken şu yalan dünyaya Kim arkamdan ağlar bilmem k...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasamak-bu-ise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklara Sesleniş...', 'uzaklara-seslenis-ulvi-ziya-0nzwq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Serin karanlık gecemde parlayan küskün yıldız...

Ey; ışığı kalbime süzülen kadın,ya da kız...

Bir bağ var aramızda:huzmeden,hayâlden bir bağ..

Seni çok seviyorum,varsın olsun karşılıksız...', 'Serin karanlık gecemde parlayan küskün yıldız... Ey; ışığı kalbime süzülen kadın,ya da kız... Bir bağ var aramızda:huzmeden,hayâlden bir bağ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uzaklara-seslenis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 8', 'guncel-beyitler-8-huseyin-avdic-wi0it', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dertler ve belâlar ancak sabirla a$ilir.

Bütün yapacagin i$: ''Biraz daha sabir''dir.

******

Ilk önce sormalisin: ''Ben kimim, kiminim, nasil ve nicin ya$amaliyim''? 

Bunlari ögrenmez ve gerekeni yapmazsan, yoktur senin hic bir anlamin! 

******

Senin kimlik soruna cevap verir ancak, senin Yaraticin.

O''nun kitap ve elcileridir, senin gercek cevaplayicin.

******

$eytan, bile bile Allah''a isyan eder.

Hakk''i inkâr eden, zalim $eytana benzer! 

******

Her $eyin bir $eyi olan su''dan halketmistir Rab evreni.

Matematigin evrenidir ''dokuz'', ''bir'' de onun temeli.

******

Ben Deccal''i bekler iken hasretle, kar$ima cikti El-Kaide.

Önce onun defterini dürmek, olacaktir en iyi faide! 

Berlin, Temmuz-Agustos 2005.', 'Dertler ve belâlar ancak sabirla a$ilir. Bütün yapacagin i$: ''Biraz daha sabir''dir. ****** Ilk önce sormalisin: ''Ben kimim, kiminim, nasil v...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guncel-beyitler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-serkan-sekban-t0cdd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldığın nefes kadar gerçek

İçtiğin su gibi saf ve temizdir aşkım

Bazen gökyüzündeki güneş

Bazen ılık esen rüzgardır aşkım

                    15 / 05 2005', 'Aldığın nefes kadar gerçek İçtiğin su gibi saf ve temizdir aşkım Bazen gökyüzündeki güneş Bazen ılık esen rüzgardır aşkım                   ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/askim-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir fincan kahve', 'bir-fincan-kahve-serkan-sekban-ev39t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rahatsız ettiysem özür dilerim

Işığı görünce uğrayayım dedim

Vakit biraz geç biliyorum ama

Bir fincan kahveyi çok görme bana

Kapını bir daha çalmıyacağım

Adını bir daha anmayacağım

Yarın bu şehirden ayrılacağım

Bir fincan kahveyi çok görme bana

Ne sitem ederim ne beddua sana

Zaten şansım yok benim aşktan yana

Geçen o güzel günler hatırına

Bir fincan kahveyi çok görme bana

	5 / 03 / 1997', 'Rahatsız ettiysem özür dilerim Işığı görünce uğrayayım dedim Vakit biraz geç biliyorum ama Bir fincan kahveyi çok görme bana Kapını bir daha...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-fincan-kahve-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandımdı...', 'sandimdi-ali-fuat-boga-qz06k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Paylaştıkça güzelleşecekti hayat

Konuşunca akan sular duracaktı

Bitiverecekti,kısa çöp 

uzun çöp kavgası.

Güneş başka doğacak,

Günbatımı cennet-i ala 

olacaktı.

Ve

Yağmurlar ıslatamayacaktı

omuz omuza yürürken,

Sevdikçe büyüyecekti umutlar

Yeşerecekti katmer katmer sevdalar,

Toprak daha bereketli,

çocuklar daha güleç olacaktı,

Ve

''Mutluluğun resmini''yapacaktık

dokununca parmak uçlarımıza,

Rengarenk boyalar şahidimiz olacaktı

ama,

ama Ben

gitmeyeceksin sandımdı.........................', 'Paylaştıkça güzelleşecekti hayat Konuşunca akan sular duracaktı Bitiverecekti,kısa çöp  uzun çöp kavgası. Güneş başka doğacak, Günbatımı cen...', ARRAY['Türk Edebiyatı','Şiir','Ali Fuat Boğa']::text[], 8.5, '{"poet":"Ali Fuat Boğa","poet_slug":"ali-fuat-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sandimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikeli Ödüller...', 'sikeli-oduller-ulvi-ziya-gk5uy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hırsız hırsıza ödül verir; ipsiz ipsize,nâmert nâmerde...

Verilen yüzlerce ödülden pek azı isâbet eder merde...

Darb-ı meseldir ki bu:''''körler sağırlar birbirini ağırlar''''; 

Gerçekten üstün olan; ödülüne kavuşabilir,mahşerde...', 'Hırsız hırsıza ödül verir; ipsiz ipsize,nâmert nâmerde... Verilen yüzlerce ödülden pek azı isâbet eder merde... Darb-ı meseldir ki bu:''''körl...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sikeli-oduller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Sen Koy', 'adini-sen-koy-vecdi-murat-soydan-j349n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şiirdi gözlerin, 

Bazen neşeli, bazen karamsar, 

Bazen bulutlu, bazen güneş yağmurlu...

Bir damla göz yaşın, 

Yüreğimden sel olur akardı,

Yağan yağmura inat. 

Ben kaç geceler ikimize de ağlardım,

Kaç geceler içmeden sarhoş olurdum, 

Yokluğunda meze yapardım hayâlini,

Oysa daha dün mahalle camiinde, 

Yaratana el açıp seni dilenmiştim,

Kıldığım iki rekat namaz, 

Kabul olur mu ki?

Senli geçen günlerimde, 

''Yerin benim yanım.'' derdin, 

Yanılmışım,

Anladım ki yerim cehennem benim,

Bırak desin diyenler, 

Deli olduğumu ben bilmez miyim, 

Ben bilmez miyim sensizliğin derin acısını. 

Yalvarır gözlerle seni aradığımı, 

Bulamayınca yanı başımda, 

Nevrimin döndüğünü, 

Kanın beynime çıktığını, 

Ben bilmez miyim Mecnun olduğumu, 

Havaya bir nara savurup, 

İçmeden sarhoş olduğumu. 

Bırak desin diyenler, 

Bu kadar akıllının arasında, 

Bir deli de olsun, 

Çeşit olsun abiler, ablalar, 

Maksat muhabbetse, 

Ben, senin yaşamadığın dizelerde de yokum. 

Vecdi Murat SOYDAN

18/08/2005 Mihalıççık-Eskişehir', 'Bir şiirdi gözlerin,  Bazen neşeli, bazen karamsar,  Bazen bulutlu, bazen güneş yağmurlu... Bir damla göz yaşın,  Yüreğimden sel olur akardı...', ARRAY['Türk Edebiyatı','Şiir','Vecdi Murat Soydan']::text[], 8.5, '{"poet":"Vecdi Murat Soydan","poet_slug":"vecdi-murat-soydan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/adini-sen-koy-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dans Et Benimle', 'dans-et-benimle-canan-palabiyik-vs72i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dans et benimle gülün dikeni ucunda,

Ağaçların çiğ damlalı yapraklarında,

Yeni doğan güneşin sardığı çimlerin üzerinde,

Irmakta çağlayan köpükler arasında dans et.

Dans et benimle ışıltılı neon lambalarında,

Anason kokulu rakı kadehinin kıvrımlarında,

Eski bir gramafonda çalan taş plak üzerinde,

Çık kozandan kelebek uçuşuyla benimle dans et.

Dans et benimle bulutlarda,

Samanyolunun ışıltıları arasında 

Beyaz bir güvercinin kanatlarında,

Maskeni at suratından benimle dans et.

Dans et benimle acının çıplaklığı üzerinde,

Kızıl saçlarım akarken yüzünde,

Büyünün bozulmamasına dikkat et, 

Haydi elini dola belime benimle dans et...

(18 Ağustos 2005 / İstanbul)', 'Dans et benimle gülün dikeni ucunda, Ağaçların çiğ damlalı yapraklarında, Yeni doğan güneşin sardığı çimlerin üzerinde, Irmakta çağlayan köp...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dans-et-benimle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Dağımda Bir Çiçek', 'buz-dagimda-bir-cicek-hasan-cam-gya3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buz dağımda büyüttüm sevgimi

Kardelen gibi deldin, erittin yüreğimi

Oysa baharsız bir kıştım, doğmayan güneşime

Ne soldurdun ne güldürdün ne de öldürdün 

Yaraladın beni, ciğerimden, sargısız bıraktın

Yıldızlar kadar uzaktasın ve de soğuk

Nadidesin içimde, buzdağımda bir çiçek

Bilemedin içimdeki sevgi ateşimi, sen yaktın

Bana uzaktın, ama gönlümdeki en yakınsın 

Bende kalacaksın hep, buzdağımda bir çiçek

Yapraklarım sallanmayacak esen rüzgarına

Çiçeklerim açmayacak, sen olmayan baharıma

Yine güneşim doğmayacak, sensiz sabahıma

Sevgilim demeyecek hiçbir zaman, dudağım dilim

Günaydınlar yok, öpücükler gelmeyecek yanağıma

Yıldızlar kadar uzaksın ve de soğuk

Nadidesin içimde, buzdağımda bir çiçek

Bilemedin içimdeki sevgi ateşimi, sen yaktın

Bana uzaktın, ama gönlümdeki en yakınsın 

Bende kalacaksın hep, buzdağımda bir çiçek

18 08 2005 

 Ümraniye   İstanbul', 'Buz dağımda büyüttüm sevgimi Kardelen gibi deldin, erittin yüreğimi Oysa baharsız bir kıştım, doğmayan güneşime Ne soldurdun ne güldürdün ne...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/buz-dagimda-bir-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az gelir bana', 'az-gelir-bana-serkan-sekban-z4kj4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel desen koşarım

Deli taylar gibi

Dağ dere tepe

Vız gelir bana

Deli gibi seviyorum 

Bir tanem seni

Yüz bin kere söylesem

Az gelir bana

  12 / 04 / 1998', 'Gel desen koşarım Deli taylar gibi Dağ dere tepe Vız gelir bana Deli gibi seviyorum  Bir tanem seni Yüz bin kere söylesem Az gelir bana   12...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/az-gelir-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki...', 'bil-ki-ulvi-ziya-uheg6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nâmertler ne düşünse fikirleri sakat olur...

Yıktıklarını yapmaya sanmaki tâkat olur...

Yiğitliğin varlığı cinsiyetten anlaşılmaz; 

Bâzen kadının mertliği erden iki kat olur...', 'Nâmertler ne düşünse fikirleri sakat olur... Yıktıklarını yapmaya sanmaki tâkat olur... Yiğitliğin varlığı cinsiyetten anlaşılmaz;  Bâzen ka...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bil-ki-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandırma kendini', 'kandirma-kendini-serkan-sekban-x2pdn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çek ellerini yakamdan artık

Bırakta gideyim kendi yoluma

Bir daha dönmem bu son ayrılık

Kandırma kendini boşu boşuna

Kaç kere yeniden basladık seninle

Ne heves kaldı ne umut bende

Olmuyor bir tanem olmuyor işte

Kandırma kendini boşu boşuna

Belkide gidince ağlıyacağım

Ama yokluğuna alışacağım

Seninle olmuyor anladım artık

Kandırma kendini boşu boşuna

	

            24 / 06 / 2000', 'Çek ellerini yakamdan artık Bırakta gideyim kendi yoluma Bir daha dönmem bu son ayrılık Kandırma kendini boşu boşuna Kaç kere yeniden baslad...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kandirma-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Asi', 'ben-asi-i-sa-tekin-fbkdi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer seni sevmek yaşamsa 

Sonsuza dek seveceğim

Eğer seni sevmek kavgaysa

Sonsuza dek savaşacağım

Eğer seni sevmek sevmek mahpussa

Sonsuza dek prangalar takacağım

Yeter ki sen ol düşüncemde

Çünkü sen umut sen sevda

Sen yeşil selvi deki serçe yüreğim

Mavi denizdeki hırçın dalgalar

Dalgalandırırdı yüreğimi

Ben hırçın ben ASİ

Ben sana sevdalı

Mor dağların tepesindeki

                       yaban çiçeğim kardelenim

Çünkü sen sevdam sen umudum 

Sen kalbimdeki yar 

Mor dağlarındaki barut kokusu 

Yakılan ormanlar baltalanan meşe ağacım

Yuvasız kalan serçe kuşları

Ötüşleri üzüntümüz matemimiz 

Çağlayanların sesi

Bizim sevdamız bizim türkümüz

Biz çok acılar yaşadık çünkü sen umut sen sevda 

Sevdalanmak çok zor biz zorda doğduk

Ben ondan hırçın ben ondan ASİ', 'Eğer seni sevmek yaşamsa  Sonsuza dek seveceğim Eğer seni sevmek kavgaysa Sonsuza dek savaşacağım Eğer seni sevmek sevmek mahpussa Sonsuza d...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-asi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-serkan-sekban-rdrqd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün daha geçti ömrümden

Bir nefes daha alıp verdim

Ağaçlar yapraklarını dökerken

Sen sonbaharı beklemedın

Bir yıl daha geçti ömrümden

Dudağımda acı bir tebessüm

Saçlarıma aklar düşerken

Sana bir türlü yetişemedim

Bir korku sardı içimi

Belki bu son nefesim

Zamanın akışını hayretle

İzledim izledim izledim

    12 / 09 / 2003', 'Bir gün daha geçti ömrümden Bir nefes daha alıp verdim Ağaçlar yapraklarını dökerken Sen sonbaharı beklemedın Bir yıl daha geçti ömrümden Du...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zaman-223-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yolcusun', 'bir-yolcusun-mehmet-nuri-gezmis-ea0ah', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İskeleden ayrılan,

Bir yolcusun sen bugün.

Sen Rabbine kavuştun,

Niçin kalanlar üzgün? 

Üzülme sevinçli ol,

Var mıdır ki başka yol? 

Onu ilâh bilmişsen,

Rahmet bol, merhamet bol.', 'İskeleden ayrılan, Bir yolcusun sen bugün. Sen Rabbine kavuştun, Niçin kalanlar üzgün?  Üzülme sevinçli ol, Var mıdır ki başka yol?  Onu ilâ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Gezmiş']::text[], 8.5, '{"poet":"Mehmet Nuri Gezmiş","poet_slug":"mehmet-nuri-gezmis","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-yolcusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünürken...', 'dusunurken-ulvi-ziya-vkr62', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beynimdeki çılgın ata

Ne gem vurdum ne eyer...

Saldım gitsin tabîata

Hür yaşamak cihan değer...

Âzâd doludizgin koşup

Ovalar dağlardan aşıp

Uçar gider kanatlaşıp...

Küçük gelir semâ ve yer...

Ele geçmez gündüz-gece

Değer vermez zorba güce

Benim cins atım,sâdece

Yüce Rabbine baş eğer...', 'Beynimdeki çılgın ata Ne gem vurdum ne eyer... Saldım gitsin tabîata Hür yaşamak cihan değer... Âzâd doludizgin koşup Ovalar dağlardan aşıp ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dusunurken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dem Dediğin', 'dem-dedigin-dilan-esiroglu-vq0v0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DEM DEDİĞİN

Dem dediğin demdi ya

Akreple yelkovanın tuhaf flörtü

Zaman sırlara gebe

Kimin umrunda

Alt tarafı

Gizem örüyordur seyircilerine

Dem dediğin  buydu ya

Sıcak  ağustos gecelerinde

Öyküye şiire durmak erinmeden

Kirazın yaprağı,

Sevgilinin dar vakitli gözleri

Mısra kovalıyordur  imgelerine

     Dilan Esiroğlu', 'DEM DEDİĞİN Dem dediğin demdi ya Akreple yelkovanın tuhaf flörtü Zaman sırlara gebe Kimin umrunda Alt tarafı Gizem örüyordur seyircilerine D...', ARRAY['Türk Edebiyatı','Şiir','Dilan Esiroğlu']::text[], 8.5, '{"poet":"Dilan Esiroğlu","poet_slug":"dilan-esiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dem-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömre Kara Düştü Saçıma Aklar', 'omre-kara-dustu-sacima-aklar-kamil-soylemez-wl5t8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aktın gönül penceremden içeriye		

Kalırsın sanmıştım bak serseriye

Neyse yanılmışım düş sokağımda		

Harmanım şimdi istanbul diyarında		

Öksüzlük hüznü düştü bağrıma

Bir sen gelip,gidişlerin ardında

Yok olup,gitmeler dağ başşlarına		

Kar olmak volkan olmak düştü şansa

Sevda dedim aşk dedim sana yarim

Tut dedim ellerimden, olsun bahar

Sen olmaz dedin şimdi zemheri var

Ömre kara düştü, saçıma aklar', 'Aktın gönül penceremden içeriye		 Kalırsın sanmıştım bak serseriye Neyse yanılmışım düş sokağımda		 Harmanım şimdi istanbul diyarında		 Öksü...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omre-kara-dustu-sacima-aklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Zor İştir...', 'yasamak-zor-i-stir-ulvi-ziya-x8l2g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tükendikçe yenilenip dolgunluğa eriştir...

Tekrar enerji kazanıp büyük uğraş veriştir...

Ayağa çivi batınca,inlemek normal bence; 

Son düşülen yere kadar,amansız bir yarıştır...

Yol katetmek cesâretle; kâh yürümek,kâh koşmak...

Darbelenince kırılmak,alkışlanınca coşmak...

Bâzen yükseğe tımanıp,bâzen çukura düşmek...

Kan terleyip uğunmak; hayat,belâ arayıştır...

Elinde silâh yokken canavara karşı durmak...

Göğsünü siper ederek ateşleri durdurmak...

Mazlumlardan yana olmak,zâlime şamar vurmak...

Hâk''dan geliş,ilerleyiş,yine Hakka varıştır...', 'Tükendikçe yenilenip dolgunluğa eriştir... Tekrar enerji kazanıp büyük uğraş veriştir... Ayağa çivi batınca,inlemek normal bence;  Son düşül...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasamak-zor-istir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı Hak Etmiyorsun!', 'askimi-hak-etmiyorsun-teoman-bicer-01yro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çek ellerini ellerimden 

Çek gözlerini gözlerimden

Aşkımı hak etmiyorsun.

Kuru yapraklar gibi 

Soldurdun sevdamı

Son bir defa sesleniyorum.

Beni sevdandan yoksul bıraktın,

Gönlümü hicranla doldurdun.

Ben gecelerin efendisi; 

Bu sevdan 

Yabancı geliyor artık bana.

Çek ellerini ellerimden

Çek gözlerini gözlerimden

Sus ve dinle! 

Yudum yudum yaşadığımız

O geceler ardından 

Kuru yapraklar gibi

Soldurdun sevdamı 

Son bir defa sesleniyorum 

Beni sevdandan yoksul bıraktın

Gönlümü hicranla doldurdun.

Ben gecelerin efendisi; 

Bu sevdan 

Yabancı geliyor artık bana.

Çek ellerini ellerimden

Çek gözlerini gözlerimden

Aşkımı hak etmiyorsun.

Bak! Yüreğime bak

Beni sevdandan yoksul bıraktın

Gönlümü hicranla doldurdun.

Gönül bahçemi güz yapraklarıyla doldurdun.

21/04/02  Teoman Biçer', 'Çek ellerini ellerimden  Çek gözlerini gözlerimden Aşkımı hak etmiyorsun. Kuru yapraklar gibi  Soldurdun sevdamı Son bir defa sesleniyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Teoman Bicer']::text[], 8.5, '{"poet":"Teoman Bicer","poet_slug":"teoman-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/askimi-hak-etmiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlan', 'i-lan-osman-karaduman-42bk9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizlik öyle zor ki

Dayanamıyorum

Kusura bakma ama

İlan! 

Yeni bir sevgili arıyorum...

marmaris', 'Sensizlik öyle zor ki Dayanamıyorum Kusura bakma ama İlan!  Yeni bir sevgili arıyorum... marmaris...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaduman']::text[], 8.5, '{"poet":"Osman Karaduman","poet_slug":"osman-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ilan-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Urfa daglarında', 'urfa-daglarinda-hekim-coskun-73r22', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu gün bende Urfa lı yım,

belime acem kuşagı, 

başıma da puşi bagladım,

ve seni çok ama çok seviyorum.

Her ne kadar Siverek te vurulsam da, 

farzet ki sana vuruldum.

Urfa daglarında yaralı Ceylanım bu gün,

sag yanımda yare var sol yana döndürün bu gün.

koy desinler desinler,

sevgili anam NESİBEM oynar desinler.

belki de gelen Hekim dir,

koy desinler.

her ne kadar Siverek te vurulduysam da,

farzet ki sana vuruldum.

Urfa daglarında yaralı bir Ceylandım ben.

Karacadag'' ın tepelerinde; Mardin ''e mi

Adıyaman'' a mı? , Diyarbakr'' amı insem diye düşünüyordum.

seni düşünüyordum,

bir tek insan düşünüyordum,

yaramı saracak.

nerden bilileyim Urfa da düğün oldugunu, 

oy olaydım olaydım,

halay başı ben olaydım.

Urfa daglarında yaralı bir Ceylan dım ben.

her ne kadar Siverek te vurulduysamda,

farzet ki ben sana vuruldum.

o dilleri yesinler, 

oyy demesinler.

.....................

.......................

......................', 'bu gün bende Urfa lı yım, belime acem kuşagı,  başıma da puşi bagladım, ve seni çok ama çok seviyorum. Her ne kadar Siverek te vurulsam da, ...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/urfa-daglarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün Seni De Vurur(Beyit)', 'birgun-seni-de-vurur-beyit-abdulkadir-karaca-qtrx7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedir bunca eziyet,seni sevmek mi günah? 

Birgün seni de vurur,beni vurduğun silah

(18,08,2005)', 'Nedir bunca eziyet,seni sevmek mi günah?  Birgün seni de vurur,beni vurduğun silah (18,08,2005)...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/birgun-seni-de-vurur-beyit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefesten Mezara', 'son-nefesten-mezara-mehmet-nuri-gezmis-n8ui9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çıkacaktır ağzından,

Sünni takma dişlerin.

Geri kalmış bir yığın,

Yüz yıl kadar işlerin.

Çenen de bağlanacak,

Örtülecek gözlerin.

En makbul kelimeler,

Son nefeste sözlerin.

Ayak baş parmakların,

Bir sicimle bağlanır.

Sevilirsen o evde,

Birkaç saat ağlanır.

Teneşire uzanır,

O soğumuş vücudun.

Hemen bir kazan kurar,

Dışarda kaynar suyun.

Yıkar, kefenler, korlar,

Musallanın üstüne.

Oğlun bakar uzaktan,

Kızın girer kürküne.

Kapıda okur sana,

İmam gelir bir Kur-an.

Birkaç gözleri nemli,

Belki başında duran.

Komşulara sorarlar,

Nasıl bilirler seni.

Kimi suratı asık,

Kimi severdi seni.

Kılarlar sana namaz,

Götürürler kuyuya.

Omuzlarda gidersin,

Sonunu duya duya.

Koyarlar mezarına,

Toprağını çekerler.

Artık karşında şimdi,

Bıraktığın eserler.

Bu kısa bir hikâye,

Son nefesten kabire.

Kabirden Arasat''a,

Esas ordadır fire! 

Bir nebze düşünürsen,

Hisse olursa sana.

Duanı esirgeme,

Fatiha oku bana.', 'Çıkacaktır ağzından, Sünni takma dişlerin. Geri kalmış bir yığın, Yüz yıl kadar işlerin. Çenen de bağlanacak, Örtülecek gözlerin. En makbul ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Gezmiş']::text[], 8.5, '{"poet":"Mehmet Nuri Gezmiş","poet_slug":"mehmet-nuri-gezmis","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/son-nefesten-mezara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CANN için', 'cann-icin-esra-aksu-8caa5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hatırlamak değildir unutmamak...', 'hatırlamak değildir unutmamak......', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/cann-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün...', 'bu-gun-ali-baksi-kr5f5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülmek icin güzel bir gün

İlk baharın rengarek rüyası sanki

Boyanmış bütün renkleri sırasınca

Aşkım yorgun yoldan gelmiş uzaklardan

Beni seviyor okşuyor hasretle yanaklarımı

Dışarda bayram var cıvıl cıvıl kokusunda

Cocuklar kendi dünyalarında ne kadar özgür

Çiceklerin renk cümbüşü sarıyor etrafı 

Sanki yeni doğan bir dünya tertemiz

Masmavi bir deniz parlıyor martının cığlıgında

Ellerimde bir sıcaklık sarsıyor bedenimi

Umudum yarınki kadar heyacanlı duragında

Bu gün yaşamak icin güzel bir gün...', 'Gülmek icin güzel bir gün İlk baharın rengarek rüyası sanki Boyanmış bütün renkleri sırasınca Aşkım yorgun yoldan gelmiş uzaklardan Beni sev...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-gun-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayâl Şehir...Issız Sâhil...Ve Mevsim Yaz...', 'hay-l-sehir-issiz-s-hil-ve-mevsim-yaz-ulvi-ziya-owq3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel ey cânan dertleri bir müddet unutalım...

Elem ve acıları zevklerle bir tutalım...

Muhabbet diyârının kumdan şatolarında; 

Kendimizden geçerek uzanalım yatalım...

Aman dikkatli davran,duyan,gören olmasın...

İçip aşk şarabından zevklere zevk katalım...

Yardım et ufkumuzdan silinsin kara renkler; 

Meşakkat denen şeyin,anasını satalım...

Demine devrânına yuh çekip şu dünyânın

Boktan gemilerine hayâlden taş atalım...

Sonu kâbus olacak gördüğümüz rüyânın

Yazarı,rejisörü,rolcüsüne çatalım...

Kızgın kumlar üstünde gevşetici bir rüyâ...

Sabah güneşe değsin yüzün,gece de aya...

Birlikte yol alalım vuslât denen sılaya...

Zaman aralığında çile bekleyedursun; 

Felekten gün çalalım,ibret olsun dünyâya...', 'Gel ey cânan dertleri bir müddet unutalım... Elem ve acıları zevklerle bir tutalım... Muhabbet diyârının kumdan şatolarında;  Kendimizden ge...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayal-sehir-issiz-sahil-ve-mevsim-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum Umut Toprak''a', 'oglum-umut-toprak-a-dilan-esiroglu-jjy3w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'OĞLUM UMUT TOPRAK’A	

Çiçekleri saksımda yeşerttiğim

Mayıs akşamlarından biriydi işte

Büyük işler düşlemiştik babanla

Büyük şehirler

Kocaman hayallerimiz vardı

Aslında küçücük,yürek kadar

Yer bir deniz kasabasıydı

Gökyüzü yeşille mavi arası

                      Kararsız.

Gençtim o yıllarda

Hep genç olmak istedim

Hayatımın duraklarını hiç sevmedim.

Sevdim babanı ölesiye

Sabrı kapılardan avuç avuç

Sırf bu yüzden dilendim

Acılarımı da sevdim

                     Umarsız.

Uzun geçti o yıl kış

Bilmem kaç yıl sonra

Bahar tadındaki bu şehre

Bu kasabaya kar yağmıştı

Ama kardan daha aktı

Ve de sıcaktı

İçimde büyüttüğüm sen

                      Zamansız.

Ben bir toprağı sevmiştim

Yitik baharın sancısını

Çeker durur diye

Bir de

Umutlar ekmiştim yarınlarıma

Yeşerir diye

                        Sorgusuz.

Yeşerdin

Deli öfkem,umut toprağım  benim

Bir  mart sabahı Trabzon’da 

Sonra seninle

Her yıl bu ülkenin farklı coğrafyasında

Yüreğimde,yarınımda,sabahımda

Yanımda

Delikanlı oğlum oldun

Her ananın gururlandığı kadar oğluyla

                             Sınırsız. 

                                     Dilan Esiroğlu', 'OĞLUM UMUT TOPRAK’A	 Çiçekleri saksımda yeşerttiğim Mayıs akşamlarından biriydi işte Büyük işler düşlemiştik babanla Büyük şehirler Kocaman ...', ARRAY['Türk Edebiyatı','Şiir','Dilan Esiroğlu']::text[], 8.5, '{"poet":"Dilan Esiroğlu","poet_slug":"dilan-esiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/oglum-umut-toprak-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamam Böceği', 'hamam-bocegi-yakup-akbulut-tcpas', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir hoşlukla uyanırım... 

Belki biraz da mayhoş. 

Odamda hamam böceği... 

Dolaşır sarhoş sarhoş. 

Hem yiyecek, hem içecek... 

Dibe köşeye girecek. 

"Hadi oradan, adi böcek!" 

Senin baban da sarhoş.

Takke düştü, kel göründü... 

Koyverdim azı dişine. 

Sekiz çize çize gider! 

Nasıl gülmem gidişine? 

Hem sövecek, hem sinecek... 

Türlü naneler yiyecek. 

"Hadi oradan, adi böcek!" 

"Defol git!" dedim işine.', 'Bir hoşlukla uyanırım...  Belki biraz da mayhoş.  Odamda hamam böceği...  Dolaşır sarhoş sarhoş.  Hem yiyecek, hem içecek...  Dibe köşeye gi...', ARRAY['Türk Edebiyatı','Şiir','Yakup Akbulut']::text[], 8.5, '{"poet":"Yakup Akbulut","poet_slug":"yakup-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hamam-bocegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Habercisine Ne Oldu', 'zamanin-habercisine-ne-oldu-abdullah-acar-uimve', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağan yağmur, gürleyen gök

Zamanın Habercisine  ne oldu 

Sen, yerin dibine inen kök 

Zamanın Habercisine ne oldu 

Gitti gelmez, yüzler soldu 

Yürekler buruldu, gözler doldu 

Ey gerçeğin ardindaki gerçek 

Zamanın Habercisine ne oldu 

21/07/2002 (Urbana, Illinois, USA)', 'Yağan yağmur, gürleyen gök Zamanın Habercisine  ne oldu  Sen, yerin dibine inen kök  Zamanın Habercisine ne oldu  Gitti gelmez, yüzler soldu...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zamanin-habercisine-ne-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esiyor yeller yerimden...', 'esiyor-yeller-yerimden-ali-baksi-cw91o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzğarın esintisi vuruyor yüreğime

Bulutlar karşı tepede bakıyorum sessiz

Karanlık cökünce senler ve benler 

Kala kaldım düş sokagımda rüyalarla

Korkuyorum ansısızın sokaklar bom boş

Ürpekliğimden cekiniyorum penceremden

Sıcak cayım ve nemli ciğaram düş sokagında

Ratyomu acıyorum ikimizin şarkısı çalıyor

Senleri ve benleri düşünüyorum

Unutuyorum korkularımı senligimle

Dışarda şırıltı sesleri rahatlatıyor icimi

Sanki aşka davet ediyor benligimi

Dalıp gidiyorum düş sokağımda yanlızca

Sabahın cıvıltılı sevda türküsü mırıldıyor

Valizimi alıp cıkıyorum yollara yılgınlıgımla

Seni arıyorum kaybettiklerimle sevdiğim...', 'Rüzğarın esintisi vuruyor yüreğime Bulutlar karşı tepede bakıyorum sessiz Karanlık cökünce senler ve benler  Kala kaldım düş sokagımda rüyal...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/esiyor-yeller-yerimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yıldızlar Ve Sevdiğim', 'ay-yildizlar-ve-sevdigim-abdulkadir-erdem-eu6b7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AY YILDIZLAR VE SEVDİĞİM

Bir köylü güzeli olmuş 

Bu gece ay

Yıldızlar birer kardelen

Sevdiğimdir

Ceylan edasıyla gelen

Niçin...

Çırılçıplaksınız kaldırımlar

Bayramlıklarınızı giyinsenize

Sevdiğimin ayakları narindir

İncinir beyaz topukları

Ya siz 

Neden loşsunuz sokak lambaları

Güneşten ışık çalsanıza

Aydınlık edin 

Bu gece

Bu sokağı

Ya 

Evimin duvarları

Siz neden susuyorsunuz

Açın

Gözünüzü kulağınızı

Örümcek tutan şu kapıdan

Birazdan sevdiğim girecek

Sesi düşecek üzerinize

Kokusu sinecek üstünüze

Artık

Barışın benimle

Yalnızlığımı tülleyen duvarlar

Barıştım artık tüm evrenle

Ve

Hatta şu çirkin kaktüsle bile

Bakın 

Aya ve yıldızlara

Bir köylü güzeli olmuş 

Bu gece ay

Yıldızlar birer kardelen

Sevdiğimdir

Ceylan edasıyla gelen

Niçin...

Çırılçıplaksınız kaldırımlar

Bayramlıklarınızı giyinsenize

Sevdiğimin ayakları narindir

İncinir beyaz topukları

Bakın 

Aya ve yıldızlara

Bir köylü güzeli olmuş 

Bu gece ay

Yıldızlar birer kardelen

Sevdiğimdir

Ceylan edasıyla gelen

Niçin...

Çırılçıplaksınız kaldırımlar

Bayramlıklarınızı giyinsenize

Sevdiğimin ayakları narindir

İncinir beyaz topukları', 'AY YILDIZLAR VE SEVDİĞİM Bir köylü güzeli olmuş  Bu gece ay Yıldızlar birer kardelen Sevdiğimdir Ceylan edasıyla gelen Niçin... Çırılçıplaks...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Erdem']::text[], 8.5, '{"poet":"Abdulkadir Erdem","poet_slug":"abdulkadir-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/ay-yildizlar-ve-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçmak', 'ucmak-abdullah-acar-5a1vf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uçmak, sihirli kelime

Hürriyet gibi, kardeşlik gibi

Şükranımız sonsuz bilime

Bize bir çift kanat verdi

Çocukken düşlerimde uçardım

Kelebekler gibi kanat açardım

Bu hazza ilk o zaman vardım

Yüreğim bu hazla pır pır ederdi

Uçmak Uçmak*a varmaktır

Kanatsızken kanatlanmaktır

Mavi göklerde salınmaktır

Alıcı şahinler gibi

*Uçmak: eski Türkçe’de cennet 

18/12/2004 (TK 140 sefer sayılı uçağı)', 'Uçmak, sihirli kelime Hürriyet gibi, kardeşlik gibi Şükranımız sonsuz bilime Bize bir çift kanat verdi Çocukken düşlerimde uçardım Kelebekle...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ucmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semek', 'semek-yavuz-unler-dw4kv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suda yaşar sayısız semek;

şuuru yokken vurgun yemeden.

Elbet onları yaratan hâlık;

tasarlamış  suya indirmeden!', 'Suda yaşar sayısız semek; şuuru yokken vurgun yemeden. Elbet onları yaratan hâlık; tasarlamış  suya indirmeden!...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ünler']::text[], 8.5, '{"poet":"Yavuz Ünler","poet_slug":"yavuz-unler","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/balik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve İlham', 'gece-ve-i-lham-abdullah-acar-7whbj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece rüzgar ciğerlerime 

Nefes değil, şiir üflüyor 

Mısralar boy boy diziliyor önümde 

Kendiliğinden goncasını açıyor kelimeler', 'Bu gece rüzgar ciğerlerime  Nefes değil, şiir üflüyor  Mısralar boy boy diziliyor önümde  Kendiliğinden goncasını açıyor kelimeler...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gece-ve-ilham-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Yağmurunda Bir An', 'zaman-yagmurunda-bir-an-abdullah-acar-50sjr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum da 

çıkıp yağmurun altına

sicim gibi inen yagmurun altına 

kimsesiz, yapayalnız ve çırılçıplak ıslansam

ne bir evim olsa ne sığınağım

ne de bir agaç  altı sığınacağım 

acaba ne yaparım! 

Önce korkarım herhalde 

iliklerime kadar ürperir 

hücrelerime kadar titrerim 

yalnızca üşümekten değil, hayır! 

yalnızlıktan,yurtsuzluktan da değil 

fakat An''ın dehşeti ürkütür beni 

düşünüyorum da

böyle bir anda 

hic kalkmamacasına bükersen dizlerini 

ve boynuna inecek giyotini 

bekler gibi beklersen kaderini 

yağmurun fiskelerine kanmadan 

rüzgarın itip kalkmasina aldırmadan 

ve günlerin,ayların 

hatta mevsimlerin 

farketmeden,su gibi 

akıp gittiğini ayaklarının altından 

işte böyle teslim olursan 

boyle verirsen An''a ruhunu 

sanırım  o An omre bedeldir

felek dahi o An’a bendedir. 

Çünkü, zaman yırtılır o an 

ve zamandan kurtulur An 

ve zamanlardan bir zaman 

yakalarsa eğer An''ı

başlar kaderden kadere yolculuk 

ya da yakalanmaz ebede kaçarsan 

çizgin küçülür, noktalaşırsın 

sonra yok olur, sonsuzlaşırsın.. 

Evet! zaman yağmuru bir gun duracaktir 

Peki yağmur durdugunda ne olacaktir..

(23 Ekim 2001''de bir AN)', 'Düşünüyorum da  çıkıp yağmurun altına sicim gibi inen yagmurun altına  kimsesiz, yapayalnız ve çırılçıplak ıslansam ne bir evim olsa ne sığı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/zaman-yagmurunda-bir-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-engin-namli-74ydm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah kalkar kaşlara,kirpikler

İkinci güneş doğar her insana

Uyanır düşten bütün güzellikler

Bedenle doğa gelir heyacana

Yeni bir güne hoş bir seda ile

Dilden merhaba dolaşır her dile

Coşar duygular gönülden gönüle

Akar gider can içinden canana

Durdurak bilmez bir an insanoğlu

Yetmez geçse de günü dolu dolu

Azmin elinde kanadıyla kolu

Uğraşı ile ter döker zamana

Didinir durur can gidene değin

Elden ayaktan çekilene değin

Yaşar uğruna bir dilim ekmeğin

Ne mutlu öpüp başına koyana

Zaman tüneli uzayıp ta gider

Üstünden nice kullar gelir geçer

Nihayetinde son duraksa kader

Çaresiz inmek düşer  yaşayana

Engin Namlı   21:18 14.08.2005', 'Her sabah kalkar kaşlara,kirpikler İkinci güneş doğar her insana Uyanır düşten bütün güzellikler Bedenle doğa gelir heyacana Yeni bir güne h...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/insan-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaye Mutluluk ise;', 'gaye-mutluluk-ise-aysel-cakar-fosqh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gaye mutluluk ise Dünyada; 

Bir parça gülücük  yeter.

Ürkme gülmekten,

Ürkütme kendinden,

Biraz olsun sevdir yeter! 

Lazımdır insana Dünyada; gerçek insan,

Ne fayda sağlar ki; Yalan ve dolan,

Rahat olamazsın,Sevgi akmazsa gönlüne,

Alabilmek için de bil ki; 

Vermek lazım birine.

Aradan bir değil,bin yıl da geçse,

Bil ki, kaybolmaz,unutulmaz; ne dost ne sevgi,

Onlar yok görülse bile,

Her zaman daima yaşar hep gönülde.', 'Gaye mutluluk ise Dünyada;  Bir parça gülücük  yeter. Ürkme gülmekten, Ürkütme kendinden, Biraz olsun sevdir yeter!  Lazımdır insana Dünyada...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çakar']::text[], 8.5, '{"poet":"Aysel Çakar","poet_slug":"aysel-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gaye-mutluluk-ise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbekir', 'diyarbekir-esref-uzulmez-w8r8u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çevirsen başını,yediburç, olacak

Sur,diplerindeki yanık kokulu sevdam

............................

............................

hala,

tedirgindir faili meçhul sokaklar

.............................

.............................

kapılarını,

açmasan,küsmüş olsan bile

Ben-u sen''im

sen bensin diyarbekir', 'Çevirsen başını,yediburç, olacak Sur,diplerindeki yanık kokulu sevdam ............................ ............................ hala, tedirg...', ARRAY['Türk Edebiyatı','Şiir','Eşref Üzülmez']::text[], 8.5, '{"poet":"Eşref Üzülmez","poet_slug":"esref-uzulmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/diyarbekir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Dendimi..', 'ayrilik-dendimi-cihan-kaya-q2lz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılık dendimi, çare yok olur

Gece düşman, aşk perişan sevdiğim.

Geçen zaman, zulüm olur yol olur

Çıkar yare, çıkmaz yoldur sevdiğim...', 'Ayrılık dendimi, çare yok olur Gece düşman, aşk perişan sevdiğim. Geçen zaman, zulüm olur yol olur Çıkar yare, çıkmaz yoldur sevdiğim......', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayrilik-dendimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Çocuk', 'esmer-cocuk-nigar-asik-1sz8u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'evet canımıniçi

bugün uzaklara gidiyorum 

senden çok uzaklara

sadece sesini duyabileceğim

yüzünü göremediğim

elini tutamadığım

başka diyara gidiyorum

bu ayrılık sadece

yollarımızı gözlerimizi ayırıyor bizden

bizi ayıran bu yollar

elbet birleştirecek yine bizi

ama ne zaman? 

belkide bir daha göremeyeceğim esmer yzünü

belkide ölüm girecek aramıza

belkide kader örümcek ağlarını örecek kalplerimize

belki de bu belkiler ayıracak 

yada bunlar oyalayacak bizi

bunların oyalayacağına inandıracağız kendimizi

yaşadığım yaşayacağım hiçbirşeyde alamam 

senden aldığım hazzı

sen uyurken ben hep sana ağladım

hep tanrıya yalvardım ayırmasın bizi

ayırmasın ellerimizi

belkide yanlış bi yerde karşılaştık seninle

yanlış bi yerde bağlandık birbirimize

peki şimdi? 

şimdi ne olacak esmer çocuk

hayat mı bizim biz mi hayatın içinde kaybolup gideceğiz

yoksa bu yanlış şehirde mi kalacak sevgimiz

sadece anılarımı bırakacağız burda

her köşebaşını mesken tutmuş bu anılar mı kalacak sadece bize

yoo sevgimiz bunu haketmiyor

biz bunu haketmiyoruz

anılarımız bunu haketmiyor

nedenler sadece nedenler var bize geride kalan

giderken iki damla gözyaşı armağan edeceğim sana

onlara iyi bak olur mu

çünkü bu ela gözler kolay kolay ağlamaz bir erkeğe

29/07/2005   03:18', 'evet canımıniçi bugün uzaklara gidiyorum  senden çok uzaklara sadece sesini duyabileceğim yüzünü göremediğim elini tutamadığım başka diyara ...', ARRAY['Türk Edebiyatı','Şiir','Nigar Aşık']::text[], 8.5, '{"poet":"Nigar Aşık","poet_slug":"nigar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/esmer-cocuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gebe', 'gebe-sait-kucuk-4bep3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kan revan içinde olsa da dünya

gebedir yeryüzü zeytin dalına', 'kan revan içinde olsa da dünya gebedir yeryüzü zeytin dalına...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gebe-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sen Ve Yine Sen', 'sen-sen-ve-yine-sen-nigar-asik-ugn85', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bazı şarkılar SENle anlam kazanıyor

SENle başladığım gün dünyanın en güzel günü oluyor

SEnle açmak istiyorum dünyanın bütün kapılarını

SENle doğmak 

SENle batmak aynı güneşle

hayat SEN demek

gördüğün herşey SEn demek

aynadaki yüz

gökteki yıldız 

biraz ben bir çok SEN demek

biraz SEN yaşam kaynağım demek

gülümsemen hayatımın geri kalanı demek

daha nediyim

daha nasıl anlatayım içimdeki SENle yanan ateşin 

beni nasıl yaktığını 

nasıl kavurduğunu

SENİ SEVİYORUM', 'bazı şarkılar SENle anlam kazanıyor SENle başladığım gün dünyanın en güzel günü oluyor SEnle açmak istiyorum dünyanın bütün kapılarını SENle...', ARRAY['Türk Edebiyatı','Şiir','Nigar Aşık']::text[], 8.5, '{"poet":"Nigar Aşık","poet_slug":"nigar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-sen-ve-yine-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-mustafa-murat-aydogdu-z9f4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden yazıyorum bilmiyorum

Yazdığım şiirlemi döneceksin bana

Gönderdiğim gülmü anlatacak aşkımı

Sen beni anlamadıktan sonra

Neden yazıyorum bilmiyorum

Sende ağlıyormusun benim gibi

Kalbin sızlıyormu okurken her kelimeyi

Sende özlüyormusun beni,seni özlediğim gibi

Neden ağlıyorum bilmiyorum

Gözyaşlarım yüreğimdeki yangını söndürecekmi yoksa? 

Dökülen yaşların değeri varmı bilmiyorum

Sen beni anlamadıktan sonra

Neden yaşıyorum bilmiyorum

Yaşamın varmı artık değeri

Sahte gülüşlerin varmı kıymeti

Sen sevmedikten sonra beni

Neden hayal kurarım bilmiyorum

Hayaller geri getirirmi seni

Geri getirirmi kaybolan ümitlerimi

Değiştirirmi gerçeği; beni sevmediğini

Artık bilmiyorum hiçbir şeyi

Ve bilmekte istemiyorum

Gün gelip sen unutsanda beni

Asla anlamasanda sevgimi; 

SENİ SEVİYORUM! 

                                         BİRSEN''e...', 'Neden yazıyorum bilmiyorum Yazdığım şiirlemi döneceksin bana Gönderdiğim gülmü anlatacak aşkımı Sen beni anlamadıktan sonra Neden yazıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/neden-175-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlık', 'kadinlik-cihan-kaya-m58z8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızlık ortasında

bir hüzün çöker geceye

deli etse de salmaz 

acısını verir sonra her heceye...

sensizlik ortasında

bir sen varsın şarkılarda

her biri seni anlatır

çiçekler seni kokar saksılarda...

ayrılık ortasında

bir mutluluk yokluğunda

dünyadan ümit kesmeler

dualar sana aşk tokluğunda...

karanlık ortasında 

bir yalancı düş aydınlığı

ne düşlesem, sen

zalimlik yaptın kadınlığı...', 'yalnızlık ortasında bir hüzün çöker geceye deli etse de salmaz  acısını verir sonra her heceye... sensizlik ortasında bir sen varsın şarkıla...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kadinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-tahir-mutlu-efqrb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünmek güzeldi

Sensiz gecelerde

Bir de rüyalarımda

O tatlı gülüşün olmasa

Sanki senden başkası

Yoktu,olamazdı

Kendimi alamıyordum

O mavi gözlerden,sarı saçlardan

Sanki rüyalarımdaki gerçekti

Gerçekler rüya olmuştu

O sensiz gecede

Güller havada uçuştu

Affedilmesi gereken bendim

Suçlu olan ben

Ama nedense seni affediyordum

Suçlu olamadığın gecelerde

Boşuna bile olsa bekliyorum

Çıkıp gelmeni ümit ediyorum

İnsanlar hep ümit eder

Çünkü ümitsiz yaşayamazlar

Belki de bende ümit ediyorum bundan dolayı

Sensiz yaşayamayacağımı bildiğim için', 'Seni düşünmek güzeldi Sensiz gecelerde Bir de rüyalarımda O tatlı gülüşün olmasa Sanki senden başkası Yoktu,olamazdı Kendimi alamıyordum O m...', ARRAY['Türk Edebiyatı','Şiir','Tahir Mutlu']::text[], 8.5, '{"poet":"Tahir Mutlu","poet_slug":"tahir-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-614-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece ve Sadece Seni...', 'sadece-ve-sadece-seni-nigar-asik-jroqs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen bilir misin yazın sıcağında kutuplarda yaşarmışcasına

buz kesmeyi

işte seni özlemek böyle birşey sevgilim

bensiz zaman geçirmen

sensiz yarınlara başlamak

çok koyuyor

ama sen anlamazsın! 

aklımdan hiç çıkmıyor son vedalaşmamız

vapurları hiç sevmiyorum artık

beni senden ayırdıklarından beri

hatta nefret ediyorum

demiştim sana iki gözyaşı bırakacağım sana diye

ben sözümde durdum

nasılda ağlamıştım dimi

hıçkıra hıçkır

bebekler gibi

sen aşağıda ben yukarıda

hayatım boyunca unutamam bu uğurlanmayı

avazım çıktığı kadar bağırmak istedim

ama bağıramadım

annen vardı yanında utandım

şimdi neden sensizim 

neden sol yanım boş

neden acıyor kalbim bilmiyorum

sen benimsin hala

ama neden buacıyla bu korku

iki farklı duygu

ama ikiside bi yerde

kalbimde...

artık hislerimede güvenmiyorum 

bu kadar seviyorum ama yanımda yoksun

oysa yanımda olman lazım

sevgimin, özlemimin seni buraya getirmesi lazım

sol yanımın yanında olman lazım

peki sen hissediyorsun yokluğumda

özlüyor musun? 

ağlıyor musun? 

acı çekiyor musun

seninde uykuların kaçıyor mu zaman zaman aklına ben düşünce

sende az ağlamamıştınarkamdan

ama kendini tutmasını bilmiştin

ya ben çok duygusalım

ya sen çok taşsın

belkide benim gibi olmanı istiyorum 

hakkım yok bunu istemeye

hakkım yok senide ağlatmaya

ilk defa senden birşey istedim

hakkım olmayan birşey istedim

seni istiyorum

sadce ve sadece 

SENİ İSTİYORUM..', 'sen bilir misin yazın sıcağında kutuplarda yaşarmışcasına buz kesmeyi işte seni özlemek böyle birşey sevgilim bensiz zaman geçirmen sensiz y...', ARRAY['Türk Edebiyatı','Şiir','Nigar Aşık']::text[], 8.5, '{"poet":"Nigar Aşık","poet_slug":"nigar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sadece-ve-sadece-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimindir.', 'yuregimindir-suleyman-saylan-rlkzd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YÜREĞİMİNDİR

“Seni seviyorum “ dersem

sakın inanma,

seven ben değilim.

Sevgim

yalan da değil...

Bu haykırışlar

yüreğimindir.

Süleyman SAYLAN

Ankara, 09.08.2001, Saat: 00.30', 'YÜREĞİMİNDİR “Seni seviyorum “ dersem sakın inanma, seven ben değilim. Sevgim yalan da değil... Bu haykırışlar yüreğimindir. Süleyman SAYLAN...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yuregimindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımıniçi', 'caniminici-nigar-asik-f0vl1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zaman geceyarısını vurdu

yine ben seni düşünüyorum

gerçi seni düşünmediğim zaman var mı ki

kaç geceyi kurban ettim seni düşündükçe

ne kadar siyah bu geceler

neden bu kadar karanlık 

neden sokak lambası dışında bir ışık yok odamda

neden ışığım yok yanımda

adı sen olan ışığım

adı sevgilim

adı aşkım

adı canımıniçi olan ışığım

nerdesin seni çok özledim! ! !', 'zaman geceyarısını vurdu yine ben seni düşünüyorum gerçi seni düşünmediğim zaman var mı ki kaç geceyi kurban ettim seni düşündükçe ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','Nigar Aşık']::text[], 8.5, '{"poet":"Nigar Aşık","poet_slug":"nigar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/caniminici-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '....Lori - 2 -', 'lori-2-orhan-demirtas-2x0gn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah lori, 

Sen kelimelerimin bittiği yersin

Sen soruların, sen mısraların 

…………..aklımda buz tuttuğu vakitsin

Ah lori, 

……….derdimin sebebi lori

Varlığımın gölgelerinde varlığından başkası olmayan

………………..aziz konuğum, yeminim lori

Sesinde çırılçıplak utandığım denizim

Nefesimin mateminden kıskandığım ışığım

Adı huzur, kendi törem, helalim lori

İzin ver, hüznüm bakışlarına aşık bu tatlı gecede

Arsız bir aşüfte gibi koynuma girsin

Gözlerin efendim olsun

……………….endamın ulu saltanat

Dirhem dirhem erisin koynunda tenim

………………….mısra mısra çürüsün

………………….mısra mısra yansın

Al lori, canında varsa bana dair gamın

……………götür sualsizce külümü

Yoksa yeniden yanıp kavrulacağım

Külümün kalbiyle yavaş yavaş 

…………………..sana yeniden vurulacağım

Ah lori, mabedim olan avuçlarında meçhule savrulacağım

Ey adil olmayan açlık

……………ey sağır olan sessizlik

İzin verin, kalbimin ölümü uzun sürmesin

Tenimde buz tutan bu kavga benim

Takvim yapraklarından üstüme düşen bu hazan benim

Ya tabut olmalı sözüm, tez vakit

…………uzunca bir mezarlığa gömülmeli

Ya da umut olmalı kederim

……..lirik bir tüy gibi sevdanın ipek saçlarında yıldızlar büyütmeli

Gözlerine dokunmaz oldu gözlerim 

Mahsur bıraktı beni yokluğun, güzel olan her şeyden lori 

Yoksa bana aydınlık, uzayan bu kederli ayrılık-mıdır? 

Bir ah getir bana yaşadığın geceden

Ey yaralı kimse

………………tarafsız ol

Lakin anlamaz bu yaradan, yaralanmayan kimse

Gel bırak bu çaresiz bedeni sevginin gözlerine

…………………..ve gözlerinde sakla kalbinin

Bu benim ve her şeyin sonu olsun lori

Yüreğime gözlerinle o ilk dokunuşun

Zamansız bir keder-miydi? lori 

Yoksa saadeti-miydi? Ebedi aşkın

Gümüş lori

…………..sim lori

Ah bir değiştire bilseydim ahını 

…………………….tüm uzuvlarım-la

İndirerek kinin ve korkunun geceden silahını

Ve uzan-saydım ayın amber kokuna benzeyen sedir toprağına lori

Ben ki boyun eğdim sevdana

……….efendim, arzum, aşkım dedim

Öylesine vurgun

………………...öylesine senden uzakta

Ve benden olmayan bir öyküde 

……..benden olmayan sıkıcı bir gözyaşı ve duada

Kirli bir ceset gibi, boyun eğdim sevdana

Gözyaşı olması gerekense eğer yokluğun için

Yada ölmekse seni sevmek 

Allah''ım beni bağışlasın, bu güzel anı bozmaktan

Gel lori

……….göster yolunu çarenin

Kalbim ihanetine uğradı bu tatlı kederin

Gel lori

……….dinlendirsin beni senden gelen bir haber yada bir söz

Benden başka kim bilir

…..sensiz yaşamdan ölümün daha tatlı olduğunu 

Gel lori

……….gel al canımı

…….ve kurtar beni bu bahtsız yaşamın boyunduruğundan

Ah Tanrım

….ne güzel bir gölgedir bu, kucağımda beslediğim çığlık

………………………çaresiz bekleyiş

…………….dokundukça solan yokluk

….içimde döllenen ateş

Ve daha neler…neler

Ey bana ait olan serin iklim

…………beynimi kemiren inatçı gözlerim

………………………………………..bakışlarım lori

Ve ey bana ait olan verimsiz ve kurak yolculuk

Gösterme artık bu yorgun ve kederli bedene aşkın yüzünü

Sen ki, ey aşk, sıradan olmayan-sın

                                                         

Orhan DEMİRTAŞ', 'Ah lori,  Sen kelimelerimin bittiği yersin Sen soruların, sen mısraların  …………..aklımda buz tuttuğu vakitsin Ah lori,  ……….derdimin sebebi l...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/lori-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Oda Vardı...', 'uc-oda-vardi-suleyman-saylan-h4pl2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÜÇ  ODA  VARDI...

Üç oda vardı bir zamanlar,

Kaçamak seviştiğimiz...

Her sevişmek isteyişimizde gittiğimiz.

Şimdi,

Aşkımızın mezarı oldu oralar,

O yanyana üç odalar.

Ölüm sessizliği içinde

Yeniden dolaşıyorum bir bir...

Sanki her biri insafsız birer kabir.

Yaşamak; 

Çekilmez bir ızdırap,

Bir damla votka, bir bardak şarap...

Yağıyor üzerime,

Öldürücü anılar sağanak sağanak...

Bu mu hayat? ..

Hatırlar mısın,

Üç oda vardı bir zamanlar,

Kaçamak seviştiğimiz...

Her sevişmek istediğimizde gittiğimiz.

Şimdi,

Aşkımızın mezarı oldu oralar,

O yan yana üç odalar.

Orada şimdi,

Zamansız öldürdüğümüz

Aşkımız yatar.

Süleyman SAYLAN

Ankara, 04.12.1970', 'ÜÇ  ODA  VARDI... Üç oda vardı bir zamanlar, Kaçamak seviştiğimiz... Her sevişmek isteyişimizde gittiğimiz. Şimdi, Aşkımızın mezarı oldu ora...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uc-oda-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Çantalım', 'kara-cantalim-suleyman-saylan-jtb8n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KARA  ÇANTALIM

Eskittiğim yılların ötesinden; 

Dalından koparılmış,

Sararıp solmuş,

Yaprakları kurumuş

Güller 

Getiriyorum sana

Kara çantalım! ...

Saçlarımda kar taneleri,

Her birinde

Yitirdiğim yılların izi...

Dudaklarımda; 

Eski aşklarımdan arta kalan,

Suyu çekilmiş denizlerin tuzu, tortusu, 

Belki

Bir kaç damla kan

Var

Kara çantalım! ...

Ferlerini kaybeden gözlerimde; 

Akıtamadığım,

Denizler dolusu gözyaşı...

Uykusuz gecelerin

Solukluğu yüzümde

Sana geliyorum

Kara çantalım! ...

Takatsizim, dermansızım, çaresizim...

Dudaklarımsa; 

Esrik rüzgarların şiddetinden

Kavruk, kavruk,

Çatlak, çatlak...

Ama

Bütün güçlü mısralarım,

Ama

Saatlerce,

Sessiz ve karanlık boşluklara saptanan bakışlarım,

Ama

Ellerimdeki terlerde akıp giden,

Eriyen saniyeler

Hepsi,

Hepsi senin için

Kara çantalım! ...

Sen, kara çantalım; 

Bütün organlarımı felç ettin,

Özgür düşüncelerime,

Sensiz sevilerime

Set çektin

Ve beni

Kendine malettin

Kara çantalım! ...

Süleyman SAYLAN

Denizli, 01.12.1965', 'KARA  ÇANTALIM Eskittiğim yılların ötesinden;  Dalından koparılmış, Sararıp solmuş, Yaprakları kurumuş Güller  Getiriyorum sana Kara çantalı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kara-cantalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akan göz yaşı değildir', 'akan-goz-yasi-degildir-mehmet-ali-suzen-wjprj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözümün önünden hiç gitmez ağlayışım, göz yaşı değil içimin acısı

Her damlası, hayatımın bir kan damlası inan.

Bütün bunları hep kendime söylüyorum ben.

Ciğerim dolup taşana kadar seninle dolsam, 

Kokun üzerime sinse, kendimde senden başka hiçbir şey koklamasam

Nefes almaya korkarım inan, o zaman içimden sen gidersin diye

Kulaklarım senin sesinden başka hiçbir ses duymasın sağır olsam tüm seslere 

Gözlerim her lahza seni görse, sensizlikte kör olsam herkese 

Dilimde sen tat olsan, seninle tadını alsam hayatın 

Parçalansa elim, kolum  acımazdı inan, bedenim canımı sen alsan 

Adımı sen koysan, nasıl istersen öyle seslen yine gelirim işte kölen

Kölen olurum da çek beni götür istediğin yere 

Teslim olurum da, sana  daha nasıl teslim olunur öğret bana 

Öğret bana ben olmadığımı, sensiz ben bir hiç bile olmadığımı

Ne olur öğret artık sensiz canım çok yanıyor

Yangın yeri serin kalır içimden

O küçücük yüreğim uçmak ister kafesinden

Kuş gibi azat edilmeyi bekler, hayat demlenirken  ateşimden

Kor oldum, yak ta kül et beni, savur,savur da yok et beni

Senden ayrı bir damlayım, denizine al beni 

Herkes gülsün isterse bana en gülüncü ben olurum 

Ne istersen iste ben olurum,  olurum 

Haydi teslim al beni, al beni', 'Gözümün önünden hiç gitmez ağlayışım, göz yaşı değil içimin acısı Her damlası, hayatımın bir kan damlası inan. Bütün bunları hep kendime söy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/akan-goz-yasi-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odalar', 'odalar-suleyman-saylan-2blkh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ODALAR

Kalbimde

Kat, kat 

Sıralanmış 

Odalar...

Her birinde 

Hayallerin var.

Süleyman SAYLAN

Denizli, 08 temmuz 1964', 'ODALAR Kalbimde Kat, kat  Sıralanmış  Odalar... Her birinde  Hayallerin var. Süleyman SAYLAN Denizli, 08 temmuz 1964...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/odalar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalet...', 'hayalet-neslihan-i-sler-iksup', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne yüreğim senden öteye gitti

Ne gözlerim başka birini seçti

Dün oturduk hayalinle başbaşa

Konuştuk eskilerden yenilerden öylece

Sende özlemişsin meğer ne çok...

Ama hayat işte bu dönüş yok...

Beni ilk gördüğün anı anlattın uzun uzun

Gözlerin dolu dolu geçmişe baktın...

Hatırlarsan sen çayı severdin ben kahveyi

Kalktım sana çay doldurdum kendi kahvemden de bir yudum aldım

Devam ettik  sabah ışıyana dek...

Sen anlattın ben sustum...

Gözlerimde sende gönlümde,

Sabah kalktın işe gitmek için aldın fotoğrafımı yerine kaldırdın

Meğer hayal olan benmişim yine sana hasret kaldım...', 'Ne yüreğim senden öteye gitti Ne gözlerim başka birini seçti Dün oturduk hayalinle başbaşa Konuştuk eskilerden yenilerden öylece Sende özlem...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayalet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek İstiyorum', 'olmek-i-stiyorum-suleyman-saylan-idk01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖLMEK  İSTİYORUM.

İnsancıklar,

İnsanlara olan saygılarını yitirdi.

Bu anamdır, babamdır,

Bu karımdır, kocamdır,

Büyüğümdür, atamdır demeden

Aşağılayıp, çemkirdi...

Yazık ki, ne yazık! 

Eyvah ki, ne eyvah! 

Beni hep bu küstahlıklar kahretti, 

Bitirdi.

Onurumun sırça sarayı

Pervasızca parçalandı,

Kanını görmediler ama yüreğim yaralandı...

Gündüzümü, gecemi

Heder ettim boş yere,

Harcadım yıllarımı,

Almadan vere vere...

Gücümü tükettim artık yorgunum,

Kaldıramıyorum,

Çekemiyorum bile bile.

Böyle sömürülmeyi,

Sömürgenleri istemiyorum...

Benim bir adım,

Şanım, şerefim var

Onur duyduğum...

Dünün bebeleri,

Edepsizler,

Kendilerini bir bok sanıp

Onurumu çiğnemeyi,

Ayaklar altına almayı denediler.

Bıraktım dünya onların olsun,

Bu utanç verici insancıklardan

Kaçmak gibi olmazsa,

İzninizle 

Ölmek istiyorum.

          Süleyman SAYLAN

          Ankara, 19.07.2000  Saat: 01.55', 'ÖLMEK  İSTİYORUM. İnsancıklar, İnsanlara olan saygılarını yitirdi. Bu anamdır, babamdır, Bu karımdır, kocamdır, Büyüğümdür, atamdır demeden ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/olmek-istiyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahım', 'sabahim-nigar-asik-qeo4r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'suan sabahın beşi

ben sensiz neyapacağımı düşünmeye başladım yine

gözlerim doluyor gideceğim anı düşündükçe

sayılı günleri yaşıyorum seninle

ne kadar uzatabilirim ki daha

ölümü beklenen hastanın ölmemesi için yapılan çabaya benziyorum şimdi.

yedi ayı sığdırmak istiyoruz sanki

üç beş gün içine

sanki bir daha görüşemeyecekmişiz gibi

eskisi kadar acı vermiyor bu düşünce yüreğime

ama gözlerim eskisinden daha çok ağlıyor

bi yanımı burada

yüreğimi sende

anılarımı kayıp şehirde

ve gözlerimi...

yollarını gözleyen o camda bırakıyorum

şimdi sen söyle canımıniçi

kalmak mı zor gitmek mi zor?', 'suan sabahın beşi ben sensiz neyapacağımı düşünmeye başladım yine gözlerim doluyor gideceğim anı düşündükçe sayılı günleri yaşıyorum seninle...', ARRAY['Türk Edebiyatı','Şiir','Nigar Aşık']::text[], 8.5, '{"poet":"Nigar Aşık","poet_slug":"nigar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sabahim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Özlem', 'olume-ozlem-suleyman-saylan-nx3hs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÖLÜME  ÖZLEM

Yanan mum gibi tükenen,

Sönen,

Kötürümleşen bir hayat...

Ölmek istiyorum.

Ölümün arkasında

Rahatlık veren bir toprak,

Asırlarca,

Dünya durdukça

Sakin bir uyku...

Bilmem

Gönlüm huzur bulur mu? 

Ölmek istiyorum.

Yıkılıp kalsam dizlerinin dibinde,

Uzanıversem yol boyu,

Kara bir toprak olsam...

Tanrıdan tek dileğim,

Bütün istediğim bu; 

Buna

Taş kalbin razı olur mu? 

Ölmek istiyorum.

Gözüm yok

Milyonda, milyarda,

Apartmanda, yalılarda, sarayda...

Ah! ... Ölüm! ...

Bir milyoner olmak ister gibi

İstiyorum,

Bütün arzulananları,

Seni ister gibi

Ölmek istiyorum...

Süleyman SAYLAN

Denizli, 09.11.1963', 'ÖLÜME  ÖZLEM Yanan mum gibi tükenen, Sönen, Kötürümleşen bir hayat... Ölmek istiyorum. Ölümün arkasında Rahatlık veren bir toprak, Asırlarca...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olume-ozlem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmak mı Zor Gitmek Mi Zor', 'kalmak-mi-zor-gitmek-mi-zor-nigar-asik-ipb43', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'suan sabahın beşi

ben sensiz neyapacağımı düşünmeye başladım yine

gözlerim doluyor gideceğim anı düşündükçe

sayılı günleri yaşıyorum seninle

ne kadar uzatabilirim ki daha

ölümü beklenen hastanın ölmemesi için yapılan çabaya benziyorum şimdi.

yedi ayı sığdırmak istiyoruz sanki

üç beş gün içine

sanki bir daha görüşemeyecekmişiz gibi

eskisi kadar acı vermiyor bu düşünce yüreğime

ama gözlerim eskisinden daha çok ağlıyor

bi yanımı burada

yüreğimi sende

anılarımı kayıp şehirde

ve gözlerimi...

yollarını gözleyen o camda bırakıyorum

şimdi sen söyle canımıniçi

kalmak mı zor gitmek mi zor?', 'suan sabahın beşi ben sensiz neyapacağımı düşünmeye başladım yine gözlerim doluyor gideceğim anı düşündükçe sayılı günleri yaşıyorum seninle...', ARRAY['Türk Edebiyatı','Şiir','Nigar Aşık']::text[], 8.5, '{"poet":"Nigar Aşık","poet_slug":"nigar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kalmak-mi-zor-gitmek-mi-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örttü', 'orttu-suleyman-saylan-x7dzh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÖRTTÜ

Her yer kirletilmiş,

Her yer pislenmiş,

Çöplük, çöplük parsellenmiş,

Talan edilmiş ülkemden

Pis kokular yükselmiş

Dayanılmaz...

Çöplüklerden beslenen sokak kedileri,

Çaresiz kuşlar,

Köpekler bile

Girememişler çöplüklere

Kokuya dayanamadıklarından.

Yok denecek kadar azaldığı için

İnsanı,

Ayakta kalan ağaçlar

Utanır olmuşlar

Ağaçlıklarından.

Sığınarak demokrasinin ardına

Ve

Kullanarak yine onun adını

Gizli gizli,

Kalleş kalleş,

Acımasızca vurmuşlar hak denen şeyi,

Hukuku

İnsancıklar allah’ından korkmadan.

Pislik yığını olmuş ülkem,

Çöplük çöplük parsellenmiş,

Pis, pis,

Dayanılmaz kokular yükselmiş,

Doğanın bile gücüne gitmiş ki

Bu kadar pisliğe

Çok kar gerekirdi

Geçici bir süre bile olsa

Gizlemek, örtmek için.

... Ve yağdı işte,

Örttü.

Süleyman SAYLAN

Ankara, 05.01.2002, Saat: 01.00', 'ÖRTTÜ Her yer kirletilmiş, Her yer pislenmiş, Çöplük, çöplük parsellenmiş, Talan edilmiş ülkemden Pis kokular yükselmiş Dayanılmaz... Çöplük...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/orttu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irgat Yoksul...', 'irgat-yoksul-suleyman-saylan-cqtsp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'IRGAT YOKSUL...

Ak bir ten düştü düşüme,

başak sarısı saçlarıyla...

“Kimdir? ” diye yordum yüreğimi eskilere; 

aşina bir yüz  çıktı, 

çok bildiğim harman yeri gibi...

Ben harmanda harman döğen bir öküz,

o ise sarı bir buğday başağıydı.

Yıkıldım ilk kez,

üzüldüm ırgat olduğuma...

Zorlayınca yüreğimi

anımsadım ansızın; 

ak bir kentte yaşardı,

denizine inat mavi gözleriyle.

belli ki,

çok zengindi,

gösterirdi her haliyle.

Bense; 

o kentin limanında hamal,

yatlarında çımaydım.

Bir kez daha yıkıldım,

üzüldüm yoksulluğuma...

   Süleyman  SAYLAN (?)

   Ankara, 19.07.2000 Saat: 14.55 (Tamamlanma tarihidir) 

Not: Bu şiirin ilk bölümü tamamlanmamış şiirlerimin arasında yıllar öncesinden bilgisayarımda mevcuttu, ancak küçük bir kuşku bile olsa bana ait olmama olasılığı içerdiğinden; ikinci bölümünü tamamlamış olmama rağmen, bu şiirin tamamının benim olduğundan emin değilim.', 'IRGAT YOKSUL... Ak bir ten düştü düşüme, başak sarısı saçlarıyla... “Kimdir? ” diye yordum yüreğimi eskilere;  aşina bir yüz  çıktı,  çok bi...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/irgat-yoksul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Elleri Dikenli Gülleridir Toprağın', 'a-elleri-dikenli-gulleridir-topragin-nail-yavuz-f86lv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sıcak esintiler arasında 

tozlu tarlaların erleri 

omuzları çökük ama başları dik 

sabahın kör şafağında 

yağmurda toprağın kokusunu soluyarak 

düşüverirler yollara 

kök sarmaşıkları gibi 

el ele yürek yüreğe 

taşırlar emeğin alın terini 

sığıntı pazarlarına kentlerin 

elleri en dikenli gülleridir toprağın 

sağır gecelerini 

sevdalı türküler çağırır 

soğuk ve ıslak gecenin ortasında 

soyunurlar allı uykularından 

gözlerde uykunun belirtilerini aramak boşuna 

cılız dalların gölgesinde uyuturlar çocuklarını 

kırağı usul usul düşer 

bembeyaz gülüşlerine çocukların 

üşüyen bir küçük serçe gibidir elleri 

elleri esintiler getirir 

bire bin veren 

kara sevdalı toprağından 

varsıl beyleri doyurmaktan 

bunca uğraş 

el emeği alın teri 

böyle buruk yürekler 

soysuz soygunlarda çırpınırken 

nasıl ağıta dönüşür 

toprağın birikmiş acıları 

bir kehribar sabrıyla 

solarlar her sonbaharda 

gelecek baharlarda açmak umuduyla 

çiğdem bakışlı ovaların 

kaçıncı açan isimsiz çiçeğidir 

en güzel renklere boyanmış elleri 

susuzluğumu dindiren türküler gibi 

uykusuz gecelerin sonunda 

karanfil hüzünlere dolanmış 

ürkek bakışlı ilkbahar çiçekleri gibi 

gelinlik kızlarımızı salarız tarlalara 

unuturuz işlemeli sevdalarını 

unuturuz kanayan yaralarını 

ince ince sızlar yürekleri 

gözleri uzaklara takılır 

bir çığlık olur zaman 

bir avuç umut için 

açık kamyonlarda taşırız 

gece karanlığı bakışlı 

sırım gibi delikanlılarımızı 

pulluğun ucunda demir 

yardıkça toprağı 

elleriyle büyür 

büyür terin ve emeğin ürünü 

bu sesi tanıyorum 

Sazlıköy civarından 

sırtında göçebe gurbetliklerle 

sallanan kamışların serinliğidir 

ellerimi ve içimi üşütüp giden 

mor bir tay gibidir esinti 

ben üretenleri sevdimse 

ben seni sevdimse gülüm 

geceleri deler 

türkülerden önce gelirim 

ilk yaz kavganın düğün alanı olur 

önce bademler uyanır 

sevdalar yoksulluğun gül yaralarıdır 

al çiçeklerle süsle türkülerini

N A İ L Y A V U Z. İZMİR.

Temmuz 2005 y.düzenleme', 'sıcak esintiler arasında  tozlu tarlaların erleri  omuzları çökük ama başları dik  sabahın kör şafağında  yağmurda toprağın kokusunu soluyar...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/a-elleri-dikenli-gulleridir-topragin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-nail-yavuz-o0wkz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir yalanı sevmiştim../ düşümde gördüğüm

tek bir sonsuz andı zamanın ötesinde

gizemli bir ödeve tutsak kılmış kendini

umut en güzel sokak../ iki ucu açık

zorunlu izine çıkarttım zalim zamanlarımı

seni dikeninden ayrı düşünemem gül

düşlerin çiçekleri solar../ ü m i d i n d e

bir imgenin keskin yüzünde

uçuk mavi bir su damlası hayat

sevişir gibi dövüştüm

_söylemin omurgasında

bahar düşmüş ellerimden

soğudu soluğum / yüzünün çıkmazlarında

__ dur anılarımı silme

çiçekli bir zamandır dürdüğüm/desenlerinde halının

gelseydin serecektim ömrüne

tükendi umutlar../ yaşamın çılgın isteğinde

___s ö z s o ğ u d u

kaç beden eskitti gözlerin

kendime sarıldığım boşluk sensin

____silinir mi yazgı

çileden iğne ipliğe dönmüş ipek

avuç içi kadar yürekte dünya kadar sızı.

Nail Yavuz, İzmir

Ağustos 2005 y.düzenleme', 'bir yalanı sevmiştim../ düşümde gördüğüm tek bir sonsuz andı zamanın ötesinde gizemli bir ödeve tutsak kılmış kendini umut en güzel sokak../...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/umut-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmak istiyor canım', 'susmak-istiyor-canim-kadir-yasan-fnm6d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susmak istiyor canım

İçim geçiyor kelimelerin vurdum duymazlığına

Adıysa her yanım yangın 

Yanıyor ortalık

Cırcır böceğinin çığırtkanlığına inat..

Yıldızlar içinde aşklardan serenat

İnsanları anlamak istiyorum

Ne çaresiz bir insanım ben

Ben diyorum her şeyi bilirim

Sen diyorsun zerresin..

Ben neyim?', 'Susmak istiyor canım İçim geçiyor kelimelerin vurdum duymazlığına Adıysa her yanım yangın  Yanıyor ortalık Cırcır böceğinin çığırtkanlığına ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yasan']::text[], 8.5, '{"poet":"Kadir Yasan","poet_slug":"kadir-yasan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/susmak-istiyor-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diploma', 'diploma-turgay-msamper-vgkiq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne harçlık var ne gündelik

papuç yırtık cep delik 

böyle geçti talebelik 

ö günleri bir sorbana

evde sıcak aş arama

pantolonda koca bir yama

sözde aldık bir diploma 

ne kazandık bir sorbana', 'ne harçlık var ne gündelik papuç yırtık cep delik  böyle geçti talebelik  ö günleri bir sorbana evde sıcak aş arama pantolonda koca bir yama...', ARRAY['Türk Edebiyatı','Şiir','Turgay Msamper']::text[], 8.5, '{"poet":"Turgay Msamper","poet_slug":"turgay-msamper","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/diploma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Yaşamın Orta Yeri', 'a-yasamin-orta-yeri-nail-yavuz-2352z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'değiştirmek için

yeterince çaba harcanmamış hayat

zamanın bağrından kopup parçalandık

dokularım / acılı bağlantılarımda dolaşıyor

sessiz çığlıklar saklı / gözyaşlarımda

yaşam denize karışan bir ırmaktır

ve sayılı günler toplamıdır ömür

dünden mirastı mutsuzluk

yarın kaygılı ve öfkeli

yarım bir şeyler bırakan içimizde / kırık

işlenmemiş suçların acılı imdat çığlıklarında

yalan kahkahaydı kör kuyudan yükselen

_____ giden gitti

________çağla talanı', 'değiştirmek için yeterince çaba harcanmamış hayat zamanın bağrından kopup parçalandık dokularım / acılı bağlantılarımda dolaşıyor sessiz çığ...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/a-yasamin-orta-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkım Olsaydı', 'hakkim-olsaydi-dogan-i-nceman-j48eh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hakkım olsaydı seni özlediğimi söylerdim.

Ben senin neyinim ki? 

Ne dostunum ne  sevgilin,ne eşin? 

Hakkım olsaydı,

Kordon''da  akşamüstü

Sana bir bira ısmarlardım; 

Gözümü kamaştıran ışığın

Güneş ışığı değil,

Deniz rengi gözlerinden 

Geldiğini fısıldardım.

Güzelim,kolay değil ki,

Haklı olmak akıl cesareti,

Sevda,cahil cesareti istiyor belki...', 'Hakkım olsaydı seni özlediğimi söylerdim. Ben senin neyinim ki?  Ne dostunum ne  sevgilin,ne eşin?  Hakkım olsaydı, Kordon''da  akşamüstü San...', ARRAY['Türk Edebiyatı','Şiir','Doğan İnceman']::text[], 8.5, '{"poet":"Doğan İnceman","poet_slug":"dogan-i-nceman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hakkim-olsaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-emine-deniz-ppxiw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben

Her gece

El ayak çekildiğinde

saçlarımı dağıtıp 

gecenin sağır ellerine

seni düşünüyorum

Çiçekler büyüyor yüreğimde

Azgın yalnızlıklara inat

hırsla

sevgiyle

Gözlerin büyüyor

Gözlerimde...', 'Ben Her gece El ayak çekildiğinde saçlarımı dağıtıp  gecenin sağır ellerine seni düşünüyorum Çiçekler büyüyor yüreğimde Azgın yalnızlıklara ...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-dusunuyorum-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Adına', 'dostluk-adina-funda-sengul-w88rb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazmak istersin ya

Yahutta dudakların bir şarkı mırıldanırya

Yada zafer marşı çalar bakışların zamandan

Birşeyler anlatmak istersin ya dostluk adına

Benliğin bir şeylere susamıştır da anlayamazsın

Gözlerin dalar ya maziye çıkar yol bulamazsın

Bazen geçmiş sen olursun geleceğini anlayamazsın

Dersin ya ne olur bana dostluk adına birşeyler anlatın', 'Bir şiir yazmak istersin ya Yahutta dudakların bir şarkı mırıldanırya Yada zafer marşı çalar bakışların zamandan Birşeyler anlatmak istersin...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dostluk-adina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Çanları Çalarken Dünyada!', 'olum-canlari-calarken-dunyada-ozan-si-ar-agdasan-fkabu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm çanları çalarken

Ben nasıl mutlu olurum? 

Kan toprakları sularken

Ben nasıl kutlu olurum? ..

                  Doğan doğduğuna pişman 

                  Pusuda yatıyor düşman

                  Milyonlarca mutsuz insan

                  Ben nasıl mutlu olurum?    

Tel örgüler kanlı pusu 

Kaçtı dünyanın uykusu

Ülkemde ‘açlık ordusu’

Nasıl Umutlu olurum? 

                       Dünyada aç milyon-milyon

                       Atoma rest çekti, ‘nötron’ 

                       Bas düğmeye, dünya’ya son 

                       Ben nasıl mutlu olurum? 

Şah Turna’nın intizarı

Ay geçti, gün oldu yarı

Ortadoğu kan pazarı

Ben nasıl kutlu olurum

Biz  nasıl mutlu oluruz dünya''da! ? ..

Söz ve Müzik: Aşık Şahturna (Ozan ŞAH TURNA Ağdaşan) 

ŞAHTURNA Kültür ve Sanat Evi www.sahturna.com

Düzenleme ve yorum: Ozan ŞİAR Ağdaşan 

ŞİARIMIZ Sanat Kültür Toplumsal Forum www.siarcan.com

Almaca: Şirin&Şafak Ağdaşan Turnalar Müzik

İngilizce çeviri: Prof. Stephen Blum of New York City University

Sevgili Okuyucularımız, Ozanca güzel sözü sizlerle de paylaşayım dedim: İNSAN ÇEŞİT- ÇEŞİT, YER DAMAR-DAMAR... Kimisi ot yer, kimisi et yer, kimisi halt yer...Ama, kimileri de, biri birlerini yerler...

İnsanlık biri birini yemeden, dostluk sevgi ve paylaşım güllerinin katmer açtığı ‘YERYÜZÜ BAĞINDA’ yaşamak adına...Sevgiyle kalın! ...

Aşık Şahturna Ağdaşan', 'Ölüm çanları çalarken Ben nasıl mutlu olurum?  Kan toprakları sularken Ben nasıl kutlu olurum? ..                   Doğan doğduğuna pişman  ...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/olum-canlari-calarken-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Şifresiz', 'a-sifresiz-nail-yavuz-r87rg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kent''te iki kişiydik o gece 

aydınlıktı gökyüzü / aşk da öyleydi 

eş zamanlı yangınlar başlamıştı 

adı belliydi yaşananların 

_p u s u l a s ı z d ı k 

fazla sadeydik giysileri önemsemiyorduk

dudaklar öpülesi duruşlardaydı

şifresiz tetiği çekilmişti duyguların 

etimizin tadını etimizden alıyorduk

_engerekler bürünmüştük 

ay düşmüştü tatlı kayıtsızlığımıza 

iki alev çomağı ile yüzlerimizi dağlıyorduk 

dizginlenemez bir duyumdu yaşamak 

sevmeyi seviyorduk 

_sabahı bitirmiştik



Nail Yavuz, İ z m i r 

Temmuz 2005 düzenleme', 'kent''te iki kişiydik o gece  aydınlıktı gökyüzü / aşk da öyleydi  eş zamanlı yangınlar başlamıştı  adı belliydi yaşananların  _p u s u l a s...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/a-sifresiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağıma Dokunma', 'bayragima-dokunma-sedat-kocabey-qe5mo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senelerdir ülkemde bağımsız yaşıyorsun,

Ayrıcalık var deyip orda burda yakınma.

Aklını başına al haddini aşıyorsun,

Çek o pis ellerini bayrağıma dokunma.

Şehitlerdir bayrağa al rengini verenler,

Bak inliyor toprağa kefensizce girenler,

Kahrolsun bayrağıma bunu layık görenler,

Çek o pis ellerini bayrağıma dokunma.

Bizler Türkoğlu Türküz budur bizim özümüz,

Vatan için ölürüz korku bilmez gözümüz,

Sakın tekrar deneme işte bu son sözümüz,

Çek o pis ellerini bayrağıma dokunma.

Canımız kanımızla bu vatanı savunduk,

Ne mutlu Türküm deyip şanımızla övündük,

Göklerde sancağımız gururlandık sevindik,

Çek o pis ellerini bayrağıma dokunma.

Kimse bizi bölemez çabalama boşuna,

Bozma ağız tadını zehir katma aşına,

Acıttı mı sözlerim gitmedi mi hoşuna,

Çek o pis ellerini bayrağıma dokunma.

Kulağımda çınlıyor ALLAH ALLAH sesleri,

Yine ALLAH diyerek çıktı son nefesleri,

Düşmanın kursağında kaldı tüm hevesleri,

Çek o pis ellerini bayrağıma dokunma.', 'Senelerdir ülkemde bağımsız yaşıyorsun, Ayrıcalık var deyip orda burda yakınma. Aklını başına al haddini aşıyorsun, Çek o pis ellerini bayra...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bayragima-dokunma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muamma', 'muamma-haci-duvan-ltvap', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur tanelerinin düştüğü gibi toprağa

 İri iri düştün içime ateşe düşer gibi

Uykusuz gecelerimin hazan bahçelerinde 

Gül oldun,kül oldum suya düşmüş kor gibi.

Yine çıkmaz bir sokaktayım

Atıverdim kendimi karamsarlığın kollarına 

Laftan anlamaz söz dinlemez kalbin esiriyim

Esiri aşkı bilmezdim düşmeden önce bu yollara

Yarin kokusu gelir çiseledikçe yağmur

Yaralı bir gülün hasreti gibi sarar yüreğimi

Soru içinde soru ızdırap içinde ruhum

Tırmaladıkça seni buldum cananı buldum abı hayat gibi

Biçareyim yollarına vurgun bu gönül

Sual etme halime kifayet etmez dilim

Her şeye inat değil mi çıldırırcasına seveceğim

Şimdi girift bir yolda dikenli bir bahçedeyim

                   

İnce bir sesi  vardır yağmurun 

Kekremsi bir tadı vardır göz yaşlarının

Buruşturup buruşturup attığım kağıtlarda 

Hiç bitiremediğim bir şiir olarak kalacaksın.      -   hazar doğan-', 'Yağmur tanelerinin düştüğü gibi toprağa  İri iri düştün içime ateşe düşer gibi Uykusuz gecelerimin hazan bahçelerinde  Gül oldun,kül oldum s...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/muamma-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Kırlangıçların Saplandığı Yer', 'a-kirlangiclarin-saplandigi-yer-nail-yavuz-qbmqw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SAPLANACAK YER

bir yazgı için dökülmüş çelik

hançerin ölüm borcu yok

bıçağın ucu neyi arar

bir ses ki şaşırmış

benden uzak/endişelerime yakın

ZAMAN

taraf tutan bir tarihin sayfasında

çemberlerden geçtik kaç defa/çark aşınmış olabilir

gelecek/bize doğru akmaktadır

düşlerin kuyusundan çekilmiş

eğirir ömrün ipeğini / zaman

KIRLANGIÇ UÇUŞU

solmayan renkleri tanımla

renksizliğin dışında / özlemlerim dahil

bana şiir yazdırtan neyini sevdim

safkan imge tay / uzun soluklu

avucumda ki yürek kırlangıç uçuşunda 

Nail Yavuz. İzmir, MAYIS 2005', 'SAPLANACAK YER bir yazgı için dökülmüş çelik hançerin ölüm borcu yok bıçağın ucu neyi arar bir ses ki şaşırmış benden uzak/endişelerime yakı...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/a-kirlangiclarin-saplandigi-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemlerim', 'ozlemlerim-haci-duvan-2puq9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilemezdim ki hayatın beni bu kadar  halsiz,bitkin ve sefil düşüreceğini

Nerden bilebilirdim ki güzelim  seni bu kadar çok seveceğimi

Seni görmek için geldiğimde sukutu hayale uğradım

Sordum sual eyledim,gitti ayrıldı ve şimdi nerde? Biz de bilmiyoruz dediler

Nasıl yıkılmıştım; takatsiz,halsiz ve renksiz bir hale düştüm

Kendimi nasıl  hazırlamıştım sana bir bilsen

Biraz daha şık gelmiştim bu sefer

Biraz daha heyecanlıydım bu defa 

Sevdirecektim kendimi,çalacaktım kalbini 

Söyleyecektim duygularımı

Anlatacaktım bu defa, hayatın sensiz olamayacağını

Bir ip ucu, bir umut ışığı, zifiri karanlıkta bir mum, denizde bir fener

Seni tekrar görmek: bana abı hayat, hüzün dolu yüreğime kol kanat

Bahtiyarlık, mutluluk, hülasa hayat ve memat. 

Hiç görmemek mi: bin defa ölmek, bin defa ölmek…Heyat.. heyat..      

                                                                        Mayıs- 2000', 'Bilemezdim ki hayatın beni bu kadar  halsiz,bitkin ve sefil düşüreceğini Nerden bilebilirdim ki güzelim  seni bu kadar çok seveceğimi Seni g...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozlemlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencere', 'pencere-haci-duvan-03r7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya bir penceredir  her gelen baktı geçti

Epey bir zamandır ben de bu pencere önündeydim

Ayrılma vakti gelmişti uykularım kaçtı

Ben; gelenle giden arasında sadece biriydim

Gidenler kalmamış ki bu pencere önünde ebedi

Gelenlere mi kalacak? bekleyenler ise değil  baki

Öyleyse ne duruyoruz?  yol alalım artık

Yolcu yolunda gerek bu pencereden çok baktık

Azı bir çoğu da bir, beklemenin ne alemi var? 

Beklemek güzel olsaydı beklemez miydi peygamber? 

Hiç ayrılmayacakmışız gibi tutunmuşuz pencereden

Ne gelenleri görebiliyoruz,ne de haberimiz var gidenlerden

Diyebiliriz ki henüz benim için erken erken

Ayrılıveririz  bir gün sessizce, belki de elveda bile diyemeden

                                                                                         15-01-2001', 'Dünya bir penceredir  her gelen baktı geçti Epey bir zamandır ben de bu pencere önündeydim Ayrılma vakti gelmişti uykularım kaçtı Ben; gelen...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/pencere-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakut Gözlüm', 'yakut-gozlum-haci-duvan-m7xn7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden utandım konuşamadım

Dönüp de yüzüne bakamadım

Kısmet böyleymiş dedin durdun

Dilime, gönlüme, kaderime bir kelepçe de sen vurdun

Akan bir şelalenin başında

Sevdiğim henüz on yedi yaşında

Çağlayan sular  gibi   pırıl pırıl

Köpük köpük gözlerinle al beni de götür

Çok uzaklara değil kalbinin bir köşesine

Sev beni hayır deme, ne olur sev ölürcesine

Bak zaman geçiyor, hayat işte öylesine

Ben, harap oldum, türap oldum,yıkıldım kaderin böylesine

Yakut gözlüm, kar tanelerine benzeyen yüzün

Billur gibi gözlerinle her gece hayallerimi süsledin

Tut ellerimi şimdi,  ölmek istiyorum

Dizlerine yatıp son defa gözlerini görmek istiyorum

Ruhunu sar bedenenime,ayrılmasın bir  ömür

Beni göz yaşlarınla yıka,doğduğum yere götür

Ayrılık, ölümden daha ağır geliyor bana

Gitme, yanımda kal, ne olur gidersen de beni de götür.

                   01.01.04', 'Senden utandım konuşamadım Dönüp de yüzüne bakamadım Kısmet böyleymiş dedin durdun Dilime, gönlüme, kaderime bir kelepçe de sen vurdun Akan ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yakut-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aleviyiz Biz', 'aleviyiz-biz-guner-kaymak-lcrpj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce tanitalim biz kendimizi 

Ehlibeyt dostu aleviyiz biz 

Bizimle basladi insan sevgisi 

Ehlibeyt dostu aleviyiz biz. 

On iki imamlara bagli özümüz 

Dünya malinda yoktur gözümüz 

Sahimerdan efendimiz, pirimiz 

Ehlibeyt dostu aleviyiz biz. 

Gönlümüzde olmaz fitne, ikilik 

Arzumuz baris, gayemiz birlik 

Bizden hiç kimse etmez hainlik 

Ehlibeyt dostu aleviyiz biz. 

Riyamiz yoktur itikat özde 

Kadini erkegi esittir bizde 

Insani severiz cani gönülde 

Ehlibeyt dostu aleviyiz biz. 

Diktatör zalime karsi dururuz 

Masumun yaninda hazir oluruz 

Bayraga, sancaga selam dururuz 

Ehlibeyt dostu aleviyiz biz. 

Ateistle,dinsizle olmaz isimiz 

Resulü ekreme bagli basimiz 

Kerbela''da akar dinmez yasimiz 

Ehlibeyt dostu aleviyiz biz. 

Yüce Atatürk''e saygimiz sonsuz 

Cahalet bitmezdi katiyen onsuz 

Aleviyim diyen olmaz sorumsuz 

Ehlibeyt dostu aleviyiz biz. 

Güruhu Naciye, çikar aslimiz 

Hiçbir canliya olmaz kastimiz 

Vatanini seven bizim dostumuz 

Ehlibeyt dostu aleviyiz biz. 

Hakkin emrinden asla çikmayiz 

Iftira, yalanla yuva yikmayiz 

Iyilik yapariz, basa kakmayiz 

Ehlibeyt dostu aleviyiz biz. 

Gurur kibir batagina düsmeyiz 

Palavrayla, yalanlarla sismeyiz 

Ser veririz davamizdan geçmeyiz 

Ehlibeyt dosstu aleviyiz biz. 

Ibadet ederiz, cani gönülden 

Bosa geçen zaman zarar ömürden 

Yol düskünü olur dönen sözünden 

Ehlibeyt dostu aleviyiz biz. 

Yetmis iki millete, saygimiz vardir 

Cahille, yobazla yasamak zordur 

Ozan Güner hakkin güzel kuludur 

Ehlibeyt dostu aleviyiz biz. 

Ozan Güner Kaymak/Amsterdam 18.08.2005', 'Önce tanitalim biz kendimizi  Ehlibeyt dostu aleviyiz biz  Bizimle basladi insan sevgisi  Ehlibeyt dostu aleviyiz biz.  On iki imamlara bagl...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/aleviyiz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basra''da Birgün Olur Bağcılar', 'basra-da-birgun-olur-bagcilar-abdulkadir-karaca-nre2o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Basra da akan kana kaygısız bakan insanlara ve buna izin veren Türk hükümetine-

Burada gökyüzü ne kadar da güzel dedim 

Sahi dedi ne renkti bulutlar

Bağcıların bulutları beyaz diyemiyordum

Gerçek ilk defa günahkar edecekti beni

Sustun dedi iyisimi ben buraları anlatayım sana

‘Gökyüzü kapkara ve ölüm kokusu siniyor bedenimize

Gülümsemede neydi ben babamın cesedinde kaybettim

Öldüğü halde askerler tekmelerken

Nasılda gülüyorlardı

Sen hiç insanlığından utandın mı? 

Annem ve ablam utanıyormuş 

Nedenini bana söylemiyorlar

*

Burada kuşların kanatlarında bulursun özgürlüğü dedim

Burada kanatlar bomba yağdırır bize dedi

‘İnsan hakları dedikleri benim ölmemse eğer

Her gün zaten ölüyor yakınlarım 

Bu kadar yeter 

Uçaklarla bildiri atıyorlar özgürlük getiriyoruz diye

Sen bilirmisin özgürlük bizim kanımızla ölçülüyor

O kadar ağır ki bu özgürlük ne kadar kan aksa da 

Hesap bir türlü tutmuyor

*

‘Penceremden bakıyorum yaza hazırlıyor kendini bağcılar’

‘Ne iyi dedi demek ki bir penceren var

Bizim evimizi yaktılar,yakarken de gülüyorlardı

Her nedense buralara hiç uğramıyor insan hakları

Anlat bana

İstanbul’u anlat 

Uçurtma var mı oralarda? 

Ya gülebilen insan? 

Oyunlar oynanıyormu sokaklarda

Ölüleri yakmak için kullanılmıyor mu kaldırımlar’

Bir acı saplandı yüreğime

Halbuki bahsetmek istiyordum ona bağcılardan

burada evler sağlam demek istiyordum

Demek istiyordum ama olmuyordu

Kezzap olmuş bedenimi yakıyordu mutluluk

Bu şen şakrak gülümsemeler devri geçiyordu üzerimden

Çünkü yanıyordu Basra,düşüyordu Bağdat

Ağlıyordu binlerce Ali,ölüyordu yüzlerce Ömer 

*

İstanbul güzel diyebildim sadece

Hayal edemeyeceğin kadar güzel

Her geçen gün biraz daha güzelleşiyor üstelik

Öylemi? dedi

 Neden peki senin çevren bu kadar güzelken

Benim yarınlarım delik deşik

konuşmak,hem de böylesi konuşmak

Kan üzerine ölüm üzerine

Bir kurşun rasgelseydi de bedenime 

Cevabım çıkmasaydı ağzımdan

Göz yaşlarıma karışmış bir kaç sözcük bıraktı dudaklarım

Bilmiyorum kardeşim dedim

Yakılası kitaplarımda sorunun cevabı yok

Ama acın bir ok gibi saplandı yüreğime

Kuş sesleri kulağımı tırmalıyor artık

Basra’da belki olur Bağcılar

Her şey bir duaya bakıyor

Sen bakma seni unutanlara

Bağcılar seni unutmuyor

Bir gün gelecek ağaçların buradakiler gibi meyveye duracak

Basra semalarını kaplayacak uçurtmalar

Sokaklarında olmayacak tank homurtuları

Basra’da bir gün olacak bağcılar

Sen ve ben soluyacağız aynı havayı

Aynı yarınlarımız olacak mutluluğun getirdiği

Savaş uçakları bombalamayacak evini

Özgürlüğüm özgürlüğündür

Yaşamım yaşamın

Basra’da sen,Bağcılarda ben

Çocuk sesleri dolacak beton evine

Hürriyet şarkıları besteleyecek insanlar

İşte o zaman aziz dostum

Aynı mevsim,aynı bahar

Bulutlarımız bembeyaz

İşte o zaman

Basra olacak bağcılar', '-Basra da akan kana kaygısız bakan insanlara ve buna izin veren Türk hükümetine- Burada gökyüzü ne kadar da güzel dedim  Sahi dedi ne renkti...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/basra-da-birgun-olur-bagcilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Nedir', 'dostluk-nedir-funda-sengul-8k3yk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden herkes acımasız oluyor ki

Ya ben çok duygusalım yada onlar gaddar

Neden hep sevdiklerimi kaybetmek zorundayım

Ya onlar çok hain yada götüren yollar

Neden hep beklentisiz sever şu kalbim

Ya sevgiler sahte yada tek ben sevenim 

Neden umutlarımı öldürürler ki

Ya herşey müsvette yada ben sahteyim

Neden dostluğun anlamını bilmezler

Ya onlar gerçekçi yada ben hayalciyim

Neden olumsuzluklar üzerine kurulur hep cümleler

Ya onlar anlamsız yahut dağıtılan roller', 'Neden herkes acımasız oluyor ki Ya ben çok duygusalım yada onlar gaddar Neden hep sevdiklerimi kaybetmek zorundayım Ya onlar çok hain yada g...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostluk-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Çanları Çalıyor Dünya''da! ...', 'olum-canlari-caliyor-dunya-da-asik-sahturna-a5byz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÖLÜM Çanları Çalıyor Dünya''da! 

Ölüm çanları çalarken

Ben nasıl mutlu olurum? 

Kan toprakları sularken

Ben nasıl kutlu olurum? ..

                  Doğan doğduğuna pişman 

                  Pusuda yatıyor düşman

                  Milyonlarca mutsuz insan

                  Ben nasıl mutlu olurum?    

Tel örgüler kanlı pusu 

Kaçtı dünyanın uykusu

Ülkemde ‘açlık ordusu’

Nasıl Umutlu olurum? 

                       Dünyada aç milyon-milyon

                       Atoma rest çekti, ‘nötron’ 

                       Bas düğmeye, dünya’ya son 

                       Ben nasıl mutlu olurum? 

Şah Turna’nın intizarı

Ay geçti, gün oldu yarı

Ortadoğu kan pazarı

Ben nasıl kutlu olurum

Biz  nasıl mutlu oluruz? ..

Söz ve Müzik: Aşık Şahturna (Ozan ŞAH TURNA Ağdaşan) 

ŞAHTURNA Kültür ve Sanat Evi www.sahturna.com

Düzenleme ve yorum: Ozan ŞİAR Ağdaşan 

ŞİARIMIZ Sanat Kültür Toplumsal Forum www.siarcan.com

Almaca: Şirin&Şafak Ağdaşan Turnalar Müzik

İngilizce çeviri: Prof. Stephan Blum of New York City University

Sevgili Okuyucularımız, Ozanca güzel sözü sizlerle de paylaşayım dedim: İNSAN ÇEŞİT- ÇEŞİT, YER DAMAR-DAMAR... Kimisi ot yer, kimisi et yer, kimisi halt yer...Ama, kimileri de, biri birlerini yerler...

İnsanlık biri birini yemeden, dostluk sevgi ve paylaşım güllerinin katmer açtığı ‘YERYÜZÜ BAĞINDA’ yaşamak adına...Sevgiyle kalın! ...

Aşık Şahturna Ağdaşan', 'ÖLÜM Çanları Çalıyor Dünya''da!  Ölüm çanları çalarken Ben nasıl mutlu olurum?  Kan toprakları sularken Ben nasıl kutlu olurum? ..           ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Şahturna']::text[], 8.5, '{"poet":"Aşık Şahturna","poet_slug":"asik-sahturna","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/olum-canlari-caliyor-dunya-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümeseydim', 'buyumeseydim-funda-sengul-uqt2s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömrümün takvimi hep sonbaharı yaşıyor 

Bahar ne diye sorma bilmiyorum

Ya ben yabancıyım bu dünyada 

Yahut bana ait olmayan bir rolü yaşıyorum

Küçükken hep kötüler kaybederdi hani

İyiler her zaman kahramandı para geçersizdi

Hani suçsuz olanları hiç üzmezler hep severlerdi

Ben affettim hepsini ama bilmiyorum içimdeki

çocuk affeder mi.........', 'Ömrümün takvimi hep sonbaharı yaşıyor  Bahar ne diye sorma bilmiyorum Ya ben yabancıyım bu dünyada  Yahut bana ait olmayan bir rolü yaşıyoru...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/keske-hic-buyumeseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim', 'hasretim-burhanettin-akdag-kcbmg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nefes nefese, sevdiğimin beni sarmalamasına

Kalp atışlarımın beynimde zonklamasına

Vücudumdaki kanın damarlarıma vurmasına

Adrenalimin yükselip bedenimi sarsmasına

Yeni heyecan dalgalarının gönlümü savurmasına

O kadar hasretim ki...

Heyecandan dilim tutulup konuşamamaya

Tir tir titreyip saatlerce gözlerinde hapsolmaya

Duygu yamacından aşağıya yuvarlanmaya

Kuşlarla yarışırcasına semalarda uçmaya

Hayallerimle süslediğim diyarlara kavuşmaya

O kadar hasretim ki...

Yüreğimdeki heyecanımın sevgimle dansetmesine

Yarınlardaki umutlarımın filizlenip yeşermesine

Uzun ve yalnız gecelerimin güne ermesine

Sevda şarkılarının beynimde yeniden bestelenmesine

Rüyalarımda prangalanan sevgilinin gelmesine

O kadar hasretim ki...

Hasretim! ..

(18.08.2005)', 'Nefes nefese, sevdiğimin beni sarmalamasına Kalp atışlarımın beynimde zonklamasına Vücudumdaki kanın damarlarıma vurmasına Adrenalimin yükse...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasretim-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet ellerde ağlarım', 'gurbet-ellerde-aglarim-tuncay-akdeniz-fml2k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret kaldım vatanıma sılama

Yaban gülü gibi soldum ağlarım

Gelmiyor demeyin sakın balama

Yüzülmez ummana daldım ağlarım

Gurbetin çilesi dertleri çoktur

Bakarım yollara gelenim yoktur

Ayrılık derdine bakmıyor doktor

Başımı dertlere saldım ağlarım

Garip diye kimse bakmaz yüzüme

Anam yok ki ortak olsun sızıma

Geceleri uyku girmez gözüme

Gurbet elde yalnız kaldım ağlarım

Hasretin acısı gurbetten beter 

Sılada yavrular burnumda tüter

Yarim haber salmış durma gel yeter

Acı dertleriyle doldum ağlarım

Kul Tuncay gurbette bu ömrüm geçer

Ayrılık  şerbeti hangi can içer

Vatanı görmeden belki de göçer

Kader sana küser oldum ağlarım 

							10.01.1997', 'Hasret kaldım vatanıma sılama Yaban gülü gibi soldum ağlarım Gelmiyor demeyin sakın balama Yüzülmez ummana daldım ağlarım Gurbetin çilesi de...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gurbet-ellerde-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlığım ve Ben', 'yanlizligim-ve-ben-funda-sengul-yaukt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzandım yatağıma yine seni yazıyorum

Kalem bıktı yazmaktan ben usanmıyorum

Sabahlarda tükeniyor gecelerde doğuyorum

Usanmıyorum yanlızlığım yine seni yaşıyorum

Gecelerle kadeh tokuşturuyorum yine 

Sarhoş olup belkide nispet yaparız güneşe

Ayılmak istemiyorum ben mutluyum seninle

Yanlızlığım koynumda yatıyoruz saatlerce

Senden kopmak belkide korkutuyor beni

Bana sadık olan bir sen kaldın

Sen ayrılmaz parçam karanlıklardaki eşim

Aynaya her baktığımda bendeki aksim', 'Uzandım yatağıma yine seni yazıyorum Kalem bıktı yazmaktan ben usanmıyorum Sabahlarda tükeniyor gecelerde doğuyorum Usanmıyorum yanlızlığım ...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanlizligim-ve-ben-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Mefta mı?', 'sevda-mefta-mi-halil-kesken-ux0vz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adı Sevda demişlerdi

Yıllardır arıyorum onu

Bakmadığım yer kalmadı

Sonunda o artık sevda değil,

Mefta dediler...

Neden bulamadığımı anladım

Çaresiz bir demet gül alıp; 

Mezarına gideyim dedim...

Önüme gelene sordum:

Eski sevda, yeni mefta nerede yatıyor diye.

O mefta oldu ama daha ölmedi dediler,

Ben de sevda''nın ağzından,

Meftayı anlattım...

Buyrun...! 

YAŞIYORUM

Anıt mezar koca dünya

Yaşıyorum hayat buysa

Sen ölmüşsün diyordun ya

Yaşıyorum hayat buysa

Kanım henüz çekilmedi

Belim henüz bükülmedi

Mezar taşım dikilmedi

Yaşıyorum hayat buysa

Bazen her şey karışıyor

Dert kederle yarışıyor

Kalbim hala çalışıyor

Yaşıyorum hayat buysa

Unutuldum, yalan oldum

Gonca güldüm artık soldum

Sanmayın ki çoktan öldüm

Yaşıyorum hayat buysa', 'Adı Sevda demişlerdi Yıllardır arıyorum onu Bakmadığım yer kalmadı Sonunda o artık sevda değil, Mefta dediler... Neden bulamadığımı anladım ...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevda-mefta-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Masumiyet', 'sevgili-masumiyet-guzin-eye-dundar-u96c2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni savaşlarda yitirdi insanlık

bebelerin gülücüklerinde kaldın 

kazandı  öfkenin dostu vahşet

kuruldu  şeytani krallık

artık ölümünü seyret

sevgili masumiyet

seni esir pazarlarında

silah tüccarlarına sattılar

bumeranga dönüştü nefret

genç yüzlerde postallı ayaklar

cehenneme döndü topraklar

ölüm makineleri  çocuklar

seni beş kuruşa  sattılar

ve uyuduk biz  insanlar

AFFET', 'Seni savaşlarda yitirdi insanlık bebelerin gülücüklerinde kaldın  kazandı  öfkenin dostu vahşet kuruldu  şeytani krallık artık ölümünü seyre...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgili-masumiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vesselam', 'vesselam-mustafa-ocaktan-ccufw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine dardayım, yine yorgun.

Yakına yakına oldum kendime dargın.

Yüreğim çok yoruldu,gözlerim de baygın.

Hasret bana göre değil vesselam...

Gözlerim yaşlanıyor,kalbim paslanıyor.

Gençliğim gidiyor,deli gönlüm uslanıyor.

Dünyanın bütün derdi omzuma yaslanıyor,

Özlem bana göre değil vesselam...', 'Yine dardayım, yine yorgun. Yakına yakına oldum kendime dargın. Yüreğim çok yoruldu,gözlerim de baygın. Hasret bana göre değil vesselam... G...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ocaktan']::text[], 8.5, '{"poet":"Mustafa Ocaktan","poet_slug":"mustafa-ocaktan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vesselam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-hasan-sanli-y44ua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece boyu hıçkırarak ağladım

Her göz yaşını bir şiirle bağladım

Bazen durgun fırtına yeri geldi çağladım

Şimdi sabrım koynumda,gelmeni bekliyorum

Yolumda ağaç idin, başımın üstünde taç

Bu kanı deli bilesin sana muhtaç

Kaç zaman gözüm yaşlı, gönlümse sevgine aç

Şimdi sabrım koynumda gelmeni bekliyorum

Baktığın yerlerde hep seni görö oldum

Evvelde çok boş idim şimdiyse senle doldum

Ruh, beden kayıplarda sorarım ben n''oldum

şimdi sabrım koynumda gelmeni bekliyorum', 'Gece boyu hıçkırarak ağladım Her göz yaşını bir şiirle bağladım Bazen durgun fırtına yeri geldi çağladım Şimdi sabrım koynumda,gelmeni bekli...', ARRAY['Türk Edebiyatı','Şiir','Hasan Şanlı']::text[], 8.5, '{"poet":"Hasan Şanlı","poet_slug":"hasan-sanli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekliyorum-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al senin olsun', 'al-senin-olsun-mehmet-ali-kepez-n6z7p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zalim felek sen davayı  kazandın

	Dünya''da doyası gül senin olsun

	Nere''ye kaçtıysam orda gezindin

	Şimdilik pes ettim yol senin olsun

	Dostlarım gönlümü kırıp yıktıysa

                Boynum kıldan ince eğer haklıysa

	Ömrùmde bir anlık huzur saklıysa

	Ara didik, didik bul senin olsun

	Yediğim,içtiğim zehir zembelek

	Bayramda giydiyim yarım yamalak

	Dünyanin sisyemi sen kahpe felek

	Bir kelepçem kaldı al senin olsun

	Kan,irin bulaşmış yediğin kirli

	Ben göçebe oldum sen artık yerli

	Yakamda dùsmedin zalim bir tùrlù

	Kötürüm canımı al senin olsun', 'Zalim felek sen davayı  kazandın 	Dünya''da doyası gül senin olsun 	Nere''ye kaçtıysam orda gezindin 	Şimdilik pes ettim yol senin olsun 	Dost...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/al-senin-olsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ciğerimsin', 'cigerimsin-mehmet-ali-kepez-1x7s8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senede bir defa olsa

	Dost dost''unu aramazmı

	Ciğerimsin nede olsa

	 Atsan yere kanamazmı

	Kùsùlùrmù durduk yerde

	Aşkin dönùşùyor derde

	Gelip burda gidenlerde

	Hal,hatırım soramazmı

	Gel artik inadi birak

	Yağan gözler oldu kurak

	Diyelimki yolu yırak

	Bir tek selam salamazmı

	Öğrendim akı karayı

	Virandır gönùl sarayı

	Açtikca açtı arayı

	Can kötùrùm soramazmı', 'Senede bir defa olsa 	Dost dost''unu aramazmı 	Ciğerimsin nede olsa 	 Atsan yere kanamazmı 	Kùsùlùrmù durduk yerde 	Aşkin dönùşùyor derde 	Ge...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cigerimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş geyilmi?', 'bos-geyilmi-mehmet-ali-kepez-amtny', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seyrettim toplumu bir hayret ile

	Yaşıyor toz,duman çok gayret ile

	Kime dur dediysem işi acele''(acele acele gider ecele)   

	Şu Dùnyanin sonu boş deyilmidir

	Ne götùrùn ambar,ambar malında

	Öbùr Dùnya bir korkulu yalanda

	Bùlbùller baki''mi gùlùn dalında? 

	Şu nefes dediğin kuş deyilmidir

	Zamanin içinde bir anlık gezdik

	Para, pul uğruna kafalar kestik

	Dizeni kutsadık kadere kızdık

	Daha''da keyfiniz hoş deyilmidir? 

	Günbe gün bırakti insan özünu		

	Kaçırdık yaşamın tadı,tuzunu

	Kapalı söyleme Kepez sözünü

	Verceğin gamlı baş deyilmidir?', 'Seyrettim toplumu bir hayret ile 	Yaşıyor toz,duman çok gayret ile 	Kime dur dediysem işi acele''(acele acele gider ecele)    	Şu Dùnyanin so...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bos-geyilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhbarcı gözler', 'i-hbarci-gozler-sedat-akguden-q0wzb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sırlarını gizlemiyorlar

yalan söylemiyorlar

ihanet ediyorlar

o güzel o deniz gözlerin sana

geri tepen kal gitme diyen

sevgi şefkat dileyen

gururunu dinlemeyen

o şeffaf o manalı gözlerin sana

buğulanıyor ıslanıyorlar

ihbar ediyorlar

kıpkırmızı dudaklarında boğuluyorlar

o nadide o masmavi gözlerin seni', 'sırlarını gizlemiyorlar yalan söylemiyorlar ihanet ediyorlar o güzel o deniz gözlerin sana geri tepen kal gitme diyen sevgi şefkat dileyen g...', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ihbarci-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana bir şiir yazıyorum', 'sana-bir-siir-yaziyorum-sedat-akguden-5tfzi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazıyorum

seni severek ikimize diyerek

bir şiir yazıyorum

zehir zemberek

şiirle ezgi gibi

sözle müzik gibi

ağzındaki sakız gibi

bir şiir yazıyorum

kelimelerle dans eder gibi

bir kocaman yürek gibi

amin diyen dilek gibi

muradına erer gibi

kaderimiz aynı gibi

bir şiir yazıyorum

bir şiir yazıyorum

sana tapıyor gibi

ağıt yakıyor gibi

sevgiler serpiyorum

Ali Dilki''nin şiir bahçesi gibi

bir şiir yazıyorum

sana büyü yapar gibi

bir şiir yazıyorum

sana dua eder gibi

ve bombayı patlatır gibi

parmağına yüzüğü takar gibi

yıldırım nikahı kıyar gibi 

şairce haykırır gibi

sana bir şiir yazıyorum', 'Bir şiir yazıyorum seni severek ikimize diyerek bir şiir yazıyorum zehir zemberek şiirle ezgi gibi sözle müzik gibi ağzındaki sakız gibi bir...', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sana-bir-siir-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyom işte', 'gidiyom-iste-mehmet-ali-kepez-u6g8y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koca Dünya dertli Dünya

	Geldim de giderim işte

	Bin türlü kaba koydunya

	Bildimde giderim işte

	Can vermişsin ölüm ile

	Bak dönmüyor dilim bile

	Acı, keder zülüm ile

	Doldum da giderim işte

	Yol yürüttün yalın karda

	Nasibim olmadı yarda

	Yaprak döktùm ilkbaharda

	Soldumda giderimiste

	Bir gün görmedim inanki

	Fors atıp niye dönenki

	Ne acelen vardı sanki

	Öldümde giderim iste', 'Koca Dünya dertli Dünya 	Geldim de giderim işte 	Bin türlü kaba koydunya 	Bildimde giderim işte 	Can vermişsin ölüm ile 	Bak dönmüyor dilim ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidiyom-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül kışta', 'gonul-kista-mehmet-ali-kepez-8t4rp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılmışım nazlı yarda

	Yùrùyorum sulu karda

	Ne kadar uzaklaşmışım

	Ben nerede sıla nerde

	Dağlar, tepeler bembeyez

	Yùzùm yakar kuru ayaz

	Dönùp donup dolaşmışım

	Bu gidişle gelirmi yaz

	Dondurdu gözùm yaşını

	çok çektim gönùl'' kışını

	Bir zalime bulaşmışım

	Bırakmaz  artık peşimi

	Gittişim cılga yoludur

	Durumum ferhat halidir

	Sıkıntiya alışmısım

	Bu deli Mehmet Ali''dir', 'Ayrılmışım nazlı yarda 	Yùrùyorum sulu karda 	Ne kadar uzaklaşmışım 	Ben nerede sıla nerde 	Dağlar, tepeler bembeyez 	Yùzùm yakar kuru ayaz ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-kista-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Geldin Aklıma', 'sen-geldin-aklima-mustafa-ocaktan-tep4k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bahrla birlikte sen geldin aklıma...

Uzak diyarlardan sessiz köşelerden.

Yüreğimin gitmek isteyipte gidemediği yerlerden,

Şöyle bir dere kenarından,yeşil çimenlerden,

Kurşun gibi oturdun kalbime, sen geldi aklıma.

Sen geldin aklıma,güzel gözlüm,

En yoğun ruh halimde kafam karmakarışıkken,

Şarkı söylemek isteyipte,şarkı söyleyemezken,

Şiir yazmak isteyipte,hiç bir şey yazamazken,

Çıban gibi vurdun gönlüme,sen geldin aklıma.

Artık tadı kalmadı hiç bir şeyin,

Şarkıların,şiirlerin,hayatın,hayallerimin,

Anlamı yok artık yüreğimdeki eşsiz nağmelerin,

Tadını alamazken yaşamanın,çalışmanın,

Tavşan kanı çayım gibi, sen geldin aklıma.

Gayrı başka dünyalardayım ben,

Kartalların yuvasını yaptığı ulaşılmaz yerlerdeyim,

Şahinlerin keskin bakışlarla süzülüşündeyim,

Arayan olursa, leyleklerin kanatlarındayım.

Zevkindeyken doğanın, sen geldin aklıma.

Ilık bir yaz günündeki yağmurun ardından,

Papatyanın yapraklarını art arda açışından,

Bir gül dalından gonca yaprağından,

Dünyayı aydınlatan,güzelleştiren güneşten,

Karanlıkları yırtarak, sen geldin aklıma...!', 'Bahrla birlikte sen geldin aklıma... Uzak diyarlardan sessiz köşelerden. Yüreğimin gitmek isteyipte gidemediği yerlerden, Şöyle bir dere ken...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ocaktan']::text[], 8.5, '{"poet":"Mustafa Ocaktan","poet_slug":"mustafa-ocaktan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-geldin-aklima-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimo', 'eskimo-ozan-ozel-2nprp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kutuplardan gelip

ikliminize sığındım 

siz, cömert insanlar

beni dilenci bildiniz

en değerlinizi

şiirlerinizi bağışladınız

herhal hiç eskimo tanımamıştınız...

www.erolayyildiz.tr.gs', 'kutuplardan gelip ikliminize sığındım  siz, cömert insanlar beni dilenci bildiniz en değerlinizi şiirlerinizi bağışladınız herhal hiç eskimo...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eskimo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halbuki', 'halbuki-mehmet-ali-kepez-xd190', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derdine ağıitlar yaktığım dostlar

	Gelipte göz yaşım silmez halbuki

	Sokakta geçerken tesadùf rastlar

	Hastayken kapımı  çalmaz halbuki

	Hasretim dumanli böyle yanaıim

	Ben herkesi kendim gibi sanarım

	Her firsat buldukca dalar anarım

	O sevinip mutu olmaz halbuki

	Kavağin  gölgesi serin gel otur

	Kırallar dùşùyor bak patır,patır

	Kalirsa kalacak tek gönùl,hatır

	Şu Dùnya kimseye kalmaz halbuki

	Ayrilik,nankorlùk yoktu hesaptan	

	Genç yasta yorulup dùsmùsùm çaptan

	Bir karton gemiye ettiler kaptan

	Kepez yùzmesini bilmez halbuki', 'Derdine ağıitlar yaktığım dostlar 	Gelipte göz yaşım silmez halbuki 	Sokakta geçerken tesadùf rastlar 	Hastayken kapımı  çalmaz halbuki 	Has...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/halbuki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-mehmet-ali-kepez-2qect', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömrùmùn tùmùnù boşver

	Ah gençlik çağlari gùzel

	Nemrut,Ağrı beni hoş gör

	Nurgak''in dağları gùzel

	Baharda nevruz açınca

	Kar ile raki içince

	Pinar başını  geçince

	Ah gavur bağlari gùzel

	Kuyucak dediğin bir dere

	Bak Kepez''i attı nere

	Ölmùşùm gelsen ne çare

	Canların sağları gùzel', 'Ömrùmùn tùmùnù boşver 	Ah gençlik çağlari gùzel 	Nemrut,Ağrı beni hoş gör 	Nurgak''in dağları gùzel 	Baharda nevruz açınca 	Kar ile raki için...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tebessümü', 'askin-tebessumu-ahmet-kesici-bxfh1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim ilk kokladığım gülümsün.

Nasıl olsunda sensiz bu yüzüm gülsün.

Gülmez gülüm gülmez.

Sensiz tebessüm bile etmez.

Nedir gözlerimden alıp veremediğin,? 

Ben ağladıkça sen nefes mi alıyorsun.? 

Senin gülüşündür kalbimin atışı,

Neden suratını asıyorsun.

Bilmez misin ki gözlerindeyim,

Ağlarsan boğulurum.! 

Kirpiklerindeyim,

Bir boyun büksen düşer kaybolurum.! 

Sen gözlerimin feri,

Kalbimin atışısın.

Söyle sensiz bu can nasıl yaşasın...', 'Sen benim ilk kokladığım gülümsün. Nasıl olsunda sensiz bu yüzüm gülsün. Gülmez gülüm gülmez. Sensiz tebessüm bile etmez. Nedir gözlerimden ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/askin-tebessumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan Kalır...!', 'sevdan-kalir-mustafa-ocaktan-z5vci', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül düşer bir meydana...

Meydan ki kor,meydan ki ateş,

Yan gönlüm, bu ateş senin için,bu ateş sana,

Yanacağım bu meydanda,dokunmayın bana...

Meydandan çıkamaz, düştüyse yürek,

Unutma ki namerde mert gerek,

Sönmez ateş,kum döksen kürek kürek...

Yanar her yanım sonunda külüm kalır,

Ateşi sönse de meraklanma korum kalır,

Sen tasalanma gülüm! her yanım yansa da,

Yanmaz yüreğim,içinde sevdan kalır.', 'Gönül düşer bir meydana... Meydan ki kor,meydan ki ateş, Yan gönlüm, bu ateş senin için,bu ateş sana, Yanacağım bu meydanda,dokunmayın bana....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ocaktan']::text[], 8.5, '{"poet":"Mustafa Ocaktan","poet_slug":"mustafa-ocaktan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdan-kalir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-mehmet-ali-kepez-ss4et', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuruyan mil gibi çatlayan kalbim

	Seni susuz koyan kör bulutlardir

	çirkin pozlarnla dolu bir albùm

	Seni tez çökerten nankör dostlardır

	Derlerdiya dost yarasi derinde

	Nasilda ayrildin sevdiklerinde

	Umudunu kesme böyle yarinda

	insani yaşatan bil umutlardır

	Doğruna gùvanip zorluğa dayan

	çok cengaver gördük fiskede cayan

	Kim kimin nazını çekmişki uyan

	Tapılmış tanrılar ağaç putlardir

	Alevi çok olur her yanar dağıin

	Yakmasın ısıtsın dostu sıcağın

	Ölùmsùz olurmu canlı dediğin

	Kepez''i mahf eden boş yanıtlardır', 'Kuruyan mil gibi çatlayan kalbim 	Seni susuz koyan kör bulutlardir 	çirkin pozlarnla dolu bir albùm 	Seni tez çökerten nankör dostlardır 	De...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbim-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışık', 'karisik-mehmet-ali-kepez-sutph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mahkum oldu savcılarıI

	Suçlu kalem kırar oldu

	Bizim köyùn avcıları

	Dağda balık avlar oldu

	Sarayda gezer katırlar

	Tıp''ı solladı  yatırlar

	Yatağa dùştù doktorlar

	Hasta yara sarar oldu

	Er oldu paşa erine

	El yanar maşa yerine

	isçiler alın terine

	Şimdi çelme atar oldu

	Sarhoş gezer mü''min hoca

	Ateist gidiyor haca

	Bu asırda karı, koca

                Birbirini  satar oldu

	

	Okur kaçtı yazarında

                Sazlar küstù ozanında

	Yeni dùnya dùzeninde

	Ters yaşamak kural oldu

	Cana dùştù korucular

	Sinek besler arıcılar

	Yali tùkenen bocular

	Kanlı çete kurar oldu

	Dedeler çılgın torununda

	Musavir hakim yerinde

	Mapushane diyaında

	Gardiyanlarr yatar oldu

	Yolcular yolunda sapmış

	Kasaplar cerrahlık yapmış

	Dùnyanın çivisi kopmuş

	Kar dediğin zarar olmuş

	Gùzel suratlar buruşuk

	Emek sermaye barışık

	Vel hasıl karma karışık

	Kurt kuzuya yarar oldu

	Dùnyami tes benmi tersim

	Benmi yanlış aldım dersim

	Kendimde çikarsam hırsım

	Gùn doğuda batar oldu

	Kepezden selam herkese

	Kimseler birsey demese

	Tavuklar girmez kümese

	Tilkilere çatar oldu', 'Mahkum oldu savcılarıI 	Suçlu kalem kırar oldu 	Bizim köyùn avcıları 	Dağda balık avlar oldu 	Sarayda gezer katırlar 	Tıp''ı solladı  yatırla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/karisik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keder', 'keder-mehmet-ali-kepez-hauhj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KEDER

    

	Zor be kardeşim zor keder

	Sabah yıldızını  gösterir hergùn

	Insanı canında yaşamda eder

	Gùneşi görmeden öldùrùr bir gùn', 'KEDER      	Zor be kardeşim zor keder 	Sabah yıldızını  gösterir hergùn 	Insanı canında yaşamda eder 	Gùneşi görmeden öldùrùr bir gùn...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/keder-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine yan', 'kendine-yan-mehmet-ali-kepez-hrbd2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin kime faydan olur

	Sen kendine yanadursen

	Haydan alan huydan olur

	Sen kendine kanadursen

	Dostu kendinde soğutma

	ùsendiğin yolu tutma

	Kendi kendi''ni avutma

	Sen kendini bana sorsen

	Tikende çiçekmi olur

	Adamlık birazmı olur

	Bizleri kurtarma nolur

	Sen aklını sana yor sen', 'Senin kime faydan olur 	Sen kendine yanadursen 	Haydan alan huydan olur 	Sen kendine kanadursen 	Dostu kendinde soğutma 	ùsendiğin yolu tutm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendine-yan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilit vurdun', 'kilit-vurdun-mehmet-ali-kepez-dvwse', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kanadımı kırdın  yar

	Bak işte uçamıyom

	Kalbe kilit vurdun yar

	Yıllardır açamıyom 

	Burada kaçarımda

	Kamp kurdun içerimde

	Canımda geçerim de

	Yar sende geçemoyom

	Hani sevdiğin nerde

	Ansızın durduk yerde

	Gözùme indi perde

	Gecemi? seçemoyom

	Mesken tuttum gurbeti       

	Kepez almaz ibreti               

	Acı sevda serbeti

	Doyurdun içemiyom', 'Kanadımı kırdın  yar 	Bak işte uçamıyom 	Kalbe kilit vurdun yar 	Yıllardır açamıyom  	Burada kaçarımda 	Kamp kurdun içerimde 	Canımda geçeri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kilit-vurdun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-mehmet-ali-kepez-yalm2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'inceden bir korku girdi gönlùme

	beni buralarda koyarsın diye

	sabaha dek ben adını  çağırdım

	Bağırdım feryadım duyarsın diye

	sen gùnesim, suyum kaçabilmiyom

	melekmi, huri mi, seçebilmiyom

	içmi bir tùrlù açabilmiyom

	sevda dilencisi sayarsın diye

	Yüreğimi açip çok yoklamışım

	Elinde renga renk gùl koklamışım

	kendime sevdayı yasaklamışım

	korkarım sonunda cayarsın diye

	Uzatsan uzansam elini tutmam

	Seni yùreğime kazdım unutmam

	Yıldizdan yùcesin ama benzetmem

	Aniden boşluğa kayarsın diye', 'inceden bir korku girdi gönlùme 	beni buralarda koyarsın diye 	sabaha dek ben adını  çağırdım 	Bağırdım feryadım duyarsın diye 	sen gùnesim,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korku-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Kal', 'gitme-kal-tolga-hamamci-5a0cv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir can, bir hayat, bir bitiş

son perde, veda sahnesi

gidiyorsun demek 

bir mucize olsa ve...

gitmesen...

olur ya gidersen bir duvara gitme

bir ağaca kal yazarım tebeşirle…

olur da tebeşir bulamazsam anlık heyecandan

damarlarım var onlar yeter son damlasıylan...

…ve olur ya mektup yazarım gitme kal diye

bakarsın kalem bulamam; titrerken ellerim

o zaman gözyaşımı döker kağıda; sana öyle veda ederim...

                            Tolga Hamamcı ...', 'bir can, bir hayat, bir bitiş son perde, veda sahnesi gidiyorsun demek  bir mucize olsa ve... gitmesen... olur ya gidersen bir duvara gitme ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Hamamci']::text[], 8.5, '{"poet":"Tolga Hamamci","poet_slug":"tolga-hamamci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gitme-kal-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurt', 'kurt-mehmet-ali-kepez-9b29v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun sùrmez zehmeri,nin ayazı

	Azılı kurt yaptiğını  kar sanma

	Gùneşte tutukluk vermezmi bazen

	Geceye gùvenip kışı  yar sanma

	Ağanın, paşanın  elin yaladın

	Emlik kuzuları, kırdınn,daladın

	Ağılı,sùrùyu dile doladın

	mazlumu ezmeyi sakın  kar sanma

	İpligin pazarda herkes biliyor

	Tasmanin ipleri kimde kalıyor

	Yaz geldi eteğin bak zil çaliyor

                Kepezi bu kadar bakar kör  sanma', 'Uzun sùrmez zehmeri,nin ayazı 	Azılı kurt yaptiğını  kar sanma 	Gùneşte tutukluk vermezmi bazen 	Geceye gùvenip kışı  yar sanma 	Ağanın, paş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kurt-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne dersin', 'ne-dersin-mehmet-ali-kepez-e4hta', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çok suvalim var cevabi  sende

	Dùnya''nin aldigi hiza ne dersin? 

	Tarih kendi yolundadIr desende

	İnsan oğlu çok ucuza ne dersin

	Hakkım yokmu çogalttıgım ùrùnde

	Kızgın lavlar fışkıryor derinde

	Demekki hiç bir şey durmaz yerinde

	Kıştan sonra gelen yaza ne dersin

	Yarına kötùyù biz taşıyoruz

	Yıldızda canlivar ne şaşiyoruz

	Soğuyan bir gùneşte yaşıyoruz

	Dar kafamda çikan teze ne dersin? 

	Korkmasa yobazlar tanrıya tapmaz

	Kulakver sözùme kiyamat kopmaz

	Hiç bir yerde kendi yerini yapmaz

	Böyle şaşkin şu Kepez''e ne dersin?', 'Bir çok suvalim var cevabi  sende 	Dùnya''nin aldigi hiza ne dersin?  	Tarih kendi yolundadIr desende 	İnsan oğlu çok ucuza ne dersin 	Hakkım...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-dersin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne güzel', 'ne-guzel-mehmet-ali-kepez-3xhv2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kış gelmış yazı  kovalar

	Ke gùzel bak kar ne gùzel

	Canlanır dağlar,ovalar

	Yemyeşil bahar ne gùzel

	Bùlbùl gùle boşa ötmez

	Yobazlarin aklı yetmez

	Doğa''nin nimeti bitmez

	Ne ararsan var ne gùzel

	Yıldirım çakip duruyor

	Yüreğim çarpip vuruyor

	Kepez bir dùzen kuruyor

	Gel de bir bak gör ne gùzel', 'Kış gelmış yazı  kovalar 	Ke gùzel bak kar ne gùzel 	Canlanır dağlar,ovalar 	Yemyeşil bahar ne gùzel 	Bùlbùl gùle boşa ötmez 	Yobazlarin akl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-guzel-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parlatılmış Gümüşlükler', 'parlatilmis-gumuslukler-tolga-hamamci-insrl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ya ben seni sevemedim

ya da sen sevmelerim olamadın

kimse anlamadı derdimden 

kimse ilaç olmadı masum gönlüme

ya eski bir kahve fincanı 

ya da parlatılmış gümüşlükler

hangi yüz bakar bilemem; benim yerime aynaya

benim bakamadığım ela gözlere

hangi beden can olur 

benim giremediğim ruhun içine; sarar sımsıkı

ya ben erken doğmuşum

ya da zaman çok geç kalmış 

haziran akşamları bana seni anlatır

bakışların dalgınlaşmış 

gözlerin yaşarmış...

ey! ! ! sen ki gözlerine kurban olduğum yarim

ben senin gülen gözlerini sevmiştim

ağlayan yüzünü hayatın sonu bilmiştim...', 'ya ben seni sevemedim ya da sen sevmelerim olamadın kimse anlamadı derdimden  kimse ilaç olmadı masum gönlüme ya eski bir kahve fincanı  ya ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Hamamci']::text[], 8.5, '{"poet":"Tolga Hamamci","poet_slug":"tolga-hamamci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/parlatilmis-gumuslukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne suçum var', 'ne-sucum-var-mehmet-ali-kepez-g2bzj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'r

	Beni anam senden önce doğurmuş

	Bunda benim ne suçum var nazlıcan

	Saçlarima benek benek ak düşmüş

	Bunda benim ne suçum var nazlıcan

	Bir sey desem hemen hüzün kapıyor

	Seni sevmiş sana yanmış tapıyor

	Gönùl kendi dediğini yapıyor

	Bunda benim ne suçum var nazlıcan', 'r 	Beni anam senden önce doğurmuş 	Bunda benim ne suçum var nazlıcan 	Saçlarima benek benek ak düşmüş 	Bunda benim ne suçum var nazlıcan 	Bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-sucum-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye yarar', 'neye-yarar-mehmet-ali-kepez-8q1e7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönùl sevdigin almazsa

       Benim sevdami bilmezse

       Gözù gözùmde gùlmezse

       Neye yarar  neye yarar

       Acı çekmek benim isim

       Yaz gùnùnde ùsùmùsùm

       Binyil sensiz yasamisim

       Neye yarar  neye yarar

       İlaç derde yaramazsa

       Dar gùnde dost aramazsa

       Can cananı saramazsa

       Neye yarar  neye yarar

   

       Zamansiz açilmis gùlùm

       Savrulmus yellere kùlùm

       Sen olmazsan tatli dilim

       Neye yarar neye yarar

       Dolu yùrek patlayinca

       Sabir tasi çatlayinca

       Hasretlik omùr boyunca

       Neye yarar neye yarar

       Ben sevmisim neye yarar

      Dertler bende harar,harar

      Saçini ellermi tarar

      Kendime vermisim zarar

      Neye yarar neye yarar

     Daha sana ne diyeyim

     Sensiz yaşami nideyim

     Başimi alip gideyim

     Neye yarar neye yarar

     Mehmet olsam, Ali olsam

     Kıraç dağda çali olsam

     Mecnun gibi deli olsam

     Neye yarar  neye yarar

     benim sevdam neye yarar', 'Gönùl sevdigin almazsa        Benim sevdami bilmezse        Gözù gözùmde gùlmezse        Neye yarar  neye yarar        Acı çekmek benim isim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/neye-yarar-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noksanım şimdi', 'noksanim-simdi-mehmet-ali-kepez-cxcq1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Muradını  aldınmı yar

	Yer ile yeksenim şimdi

	Huzurunu buldunmu yar

	Baykuşa meskenim şimdi

	Gidip èl ile oturdun

	Evin yolunu yitirdin

	Başımı alıp gttùrdùn

	Akılda noksanım şimdi

	Yùreğimde sökemedim

	Benden yana çekemedim

	Birtarafa çıkamadim

	Sen oldun eksenim simdi

	Dùşermi insan insana

	Sen ögrettin derdi bana

	Tuful iken taptım sana

	Yaşdiyor seksenim şimdi', 'Muradını  aldınmı yar 	Yer ile yeksenim şimdi 	Huzurunu buldunmu yar 	Baykuşa meskenim şimdi 	Gidip èl ile oturdun 	Evin yolunu yitirdin 	Ba...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/noksanim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noldu gönül', 'noldu-gonul-mehmet-ali-kepez-kgbx3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boz bulanik akaridin

	Noldu da duruldun gönùl

	Dost peşinde koşaridin

	Noldu da darıldın gönùl

	Bir cani elinde şaştin

	Kar gibi ataşa dùştùn

	Mecnun gibi çolmù aştın

	Noldu da yoruldun gönùl

	Her tarafin olmùş yara

	Bir adımın kalmış yara

	Bu zalim vefesız yara

	Noldu da vuruldun gönùl

	Zaten ömrùn kaç seneki

	Kepez varımış geneki

	Yaşın neki başın neki

	Hayata kırıldın  gönùl', 'Boz bulanik akaridin 	Noldu da duruldun gönùl 	Dost peşinde koşaridin 	Noldu da darıldın gönùl 	Bir cani elinde şaştin 	Kar gibi ataşa dùştù...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/noldu-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz sana ağlamak', 'sensiz-sana-aglamak-mehmet-ali-kepez-adakc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kar yùklù bulutlar dağı aşarken

     Ben çollerde eli kolu bağlıyım

     Can ile cananlar birlik yaşarken

     Ben yùrekte kizgin lav la dağlıyım

     Sùmbùl''e rengini veren senmisin

     Ben kavrulam senin canın yanmasın

     İsterse nazlıyar beni anmasın

     Ben gurbette sensiz sana ağlayam

     Of çeksem alevim seni yakacak

     Gözùnùn içne kimler bakacak', 'Kar yùklù bulutlar dağı aşarken      Ben çollerde eli kolu bağlıyım      Can ile cananlar birlik yaşarken      Ben yùrekte kizgin lav la dağ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensiz-sana-aglamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdasina doymak', 'sevdasina-doymak-mehmet-ali-kepez-xhsxs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siyahlar giymişim kara  yastayım

	Yùreğim kanıyor ağir hastayım

	Su alemde bir şey beceremedim

	Ben başıma dert açmakta ustayım

	ùç degil,beş, deyil sayılmaz derdim

	Aşılmaz dağları aşar giderdim

	Ne suçum varidi; nede gùnahım

	Ben kendimi cehennem''e gönderdim

	ilkbahar''ı sonbahar''a dönderdim

	Yillar delir birbirini kovalar

	Yemyeşil ovalar sıcak yuvalar

	Bir tùrlù gurbet''e alışamadım

	Sulusepken yaz gùnùnde havalar

	Gùn doldurmak yaşamdamı sayılır

	Sanma kepez bu feryadın duyulur

	Akılda,fikirde rùyada yoksun

	Çınar  yanmaz poyraz ıle eyilir', 'Siyahlar giymişim kara  yastayım 	Yùreğim kanıyor ağir hastayım 	Su alemde bir şey beceremedim 	Ben başıma dert açmakta ustayım 	ùç degil,be...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdasina-doymak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslu Gecelerin Hayalperesti', 'uslu-gecelerin-hayalperesti-volkan-yoruc-vs75k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uslu gecenin koynundayım

Yüzümde bir telaşsız tebessüm

Nedendir bu, niyedir bu halim? 

Oysa akar heryerimden hüznüm

Uslu gecenin uslanmaz düşündeyim

Odam sessiz, odam sensiz

Sahi niye bu halim? 

Gören sanar ki kedersiz

Uslu gecenin puslu hayallerindeyim

Bir yanım sensiz

Öte yanımda seninleyim

Duyan sanar ki dengesiz

Uslu gecenin uslanmaz çocuğu gibiyim

Biraz aşksız biraz da sevgisiz

Ama yüreğinde ki kibriti sönmez hallerdeyim

İşte o sebeple hem deli hem serseriyim

Ve bir o kadarcık ta seni ömrümce sevmekteyim

Söyle, ben neyim? 

Yoksa uslu gecelerde kalmış bir hayalperestmiyim?', 'Uslu gecenin koynundayım Yüzümde bir telaşsız tebessüm Nedendir bu, niyedir bu halim?  Oysa akar heryerimden hüznüm Uslu gecenin uslanmaz dü...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uslu-gecelerin-hayalperesti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli', 'gizli-haci-duvan-nwv6o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi gönüllerde gizli

   Makbulü Allah’a gidendir

   Kin kötülükte gizli

   Makbulü eriyip gidendir', 'Sevgi gönüllerde gizli    Makbulü Allah’a gidendir    Kin kötülükte gizli    Makbulü eriyip gidendir...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gizli-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lakin', 'lakin-haci-duvan-0kiou', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vermek isterdim sana serveti samanımı 

Bütün her şeyi ile beraber

Lakin veremezdim ki hiçbir şeyimi

Sana gönlümü verdiğim kadar', 'Vermek isterdim sana serveti samanımı  Bütün her şeyi ile beraber Lakin veremezdim ki hiçbir şeyimi Sana gönlümü verdiğim kadar...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/lakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selulit', 'selulit-i-brahim-elciboga-r63ls', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatimizin bu denli 

Teget gectigini anladigimda

Hissettigim tarifsizlikti 

Ortaya karisik

Seni yere goge sigdiramazken simdilerde

Farkli cografyalarda.....

Ya iste bu acigi

Kapamak icindir besbelli

Dengesiz heveslenmeden

Gelen asiri sismanlik

Kepenklerini cekmis erkenci ruyalarda

Sikayet etmiyorsa sayet selulitli kalbim

Bilki

Senzele olup kayip gitmeyesin

Diyedir uykumdan

                                                                  

		                                                                       

                                                                    31 /07 2005,Cezayir', 'Hayatimizin bu denli  Teget gectigini anladigimda Hissettigim tarifsizlikti  Ortaya karisik Seni yere goge sigdiramazken simdilerde Farkli c...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Elçiboğa']::text[], 8.5, '{"poet":"İbrahim Elçiboğa","poet_slug":"i-brahim-elciboga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/selulit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Şiir', 'i-lk-siir-haci-duvan-v5c7b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ayaktasın ben yerdeyim 

Gözlerinde kayboldum bilmem neredeyim? 

Yüreğim paramparça  senin derdindeyim

Sen benim gönlümdesin acep ben nerdeyim?', 'Sen ayaktasın ben yerdeyim  Gözlerinde kayboldum bilmem neredeyim?  Yüreğim paramparça  senin derdindeyim Sen benim gönlümdesin acep ben ner...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilk-siir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İthaf', 'i-thaf-haci-duvan-nc04l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cefa çektim senden ötürü sefa süremedim

Yar dedim karşına çıktım vefa göremedim

Çile hane denilen şu yalan dünyaya geldim geleli

Yaralı kalbimin bizarına merhem ol diyemedim

Sen benden uzak ben senden uzak

Hayat bize kurmuş acımasız bir tuzak

Sevmek ve sevilmek bize ezelden yasak

Ağlamak kar eylemez feryat etme bari gönül

Kalem böyle çalmış yazıma

Yazım kışa uymaz kışım yazıma

Kader seni çıkartmıştı karşıma

Sen de diğerleri gibi vefasız çıktın Kınalım vefasız çıktın…', 'Cefa çektim senden ötürü sefa süremedim Yar dedim karşına çıktım vefa göremedim Çile hane denilen şu yalan dünyaya geldim geleli Yaralı kalb...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ithaf-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak dur yeter', 'uzak-dur-yeter-mehmet-ali-kepez-b4m1m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç isime karışmasın

	Benim ile yarışmasın

	Ömùr boyu barışmasın

	Benden uzak dursun yeter

                Beni sorsun arasın

	Ne bir işime yarsın

	Kara kömùrde karasın

	Bizden uzak dursun yeter

 	Düşmanıma dùşman olsa

	Yaptığına pişman olsa

	Bundan sonra melek olsa

	Benden uzak dursun yeter

	Bu yezitte çıktı   hain

	Yaklaşma alırsın payin

 	Bu adam kim diya sormayın

	Sizden uzak dursun yeter', 'Hiç isime karışmasın 	Benim ile yarışmasın 	Ömùr boyu barışmasın 	Benden uzak dursun yeter                 Beni sorsun arasın 	Ne bir işime ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzak-dur-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-haci-duvan-p8j6a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat dediğin ne ki; deniz üstünde bir köpük

Uçan kırlangıçların dahi boynu bükük

Elli altmış yıllık bir yol: bir gece bir gündüz bir soluk

Hayata küsenler uyanın! Ölüm bize bu yolda pusu kuruk

                                                                         01-03-2000', 'Hayat dediğin ne ki; deniz üstünde bir köpük Uçan kırlangıçların dahi boynu bükük Elli altmış yıllık bir yol: bir gece bir gündüz bir soluk ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayat-233-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakıyor artık', 'yakiyor-artik-mehmet-ali-kepez-e4vn5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendimi kafeste kuşa benzettim

	Gurbetlik ruhumu sıkıyor  artık

	Baharken ömrùmù sattım gùz ettim

	Mevsimler seyrinde çıkiyor artık

	Bir barakam olsun kara meşeden

	Tavani laylonlu cami şişeden

	Dört köşe olurum inan neşeden

	Şu Dünya gittikçe kokuyor artık					

	Hasret kaldım vadi deki nehire

	Aldiğım her nefes benzer zehirre

	Ne Paris,ne londra ne de kahire

	Bozkırlar içimi yakıyor artık

	Yùreğini koru kepez sımsıcak

	Tezzkle ısınsın ùç taşlı  ocak

	Sıla hasretiyle sonun nolacak

	Memleket toprağı çekiyor artık', 'Kendimi kafeste kuşa benzettim 	Gurbetlik ruhumu sıkıyor  artık 	Baharken ömrùmù sattım gùz ettim 	Mevsimler seyrinde çıkiyor artık 	Bir bar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yakiyor-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhammes', 'muhammes-haci-duvan-76mfm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Konmadı gönül dalıma bir peri-i gönül şimdi hezeyandadır

Harap olan cümle hayatım, akıbetim ise perişandır

Bu veçhile müsabir olmaklıyım mütemadiyen imandandır

Bi bedi gidişatın esbabı: ne senden ne bendendir

Takdiri Hüdadandır, tecelliğahı levhü kalem taki ezeldendir 

                                                                            13.08.2005', 'Konmadı gönül dalıma bir peri-i gönül şimdi hezeyandadır Harap olan cümle hayatım, akıbetim ise perişandır Bu veçhile müsabir olmaklıyım müt...', ARRAY['Türk Edebiyatı','Şiir','Hacı Duvan']::text[], 8.5, '{"poet":"Hacı Duvan","poet_slug":"haci-duvan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/muhammes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De hele Kepezin yanımdamısın?', 'de-hele-kepezin-yanimdamisin-mehmet-ali-kepez-6evos', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarp kayada çekirgeye benzerdin

	Poyraz gibi kırat ile tozardın

	Nerde çağırınca orda hazırdın

	Şimdi yolsuzların yanındamısın? 

	Yerrdiğin şeyleri alıp satmışsın

	Döşek beğenmezdin yerde yatmışsın

	Ne diye vatana dönmem demişsin

	Yoksa firavunun inindemisin? 

	Balıklar balığa yem olur yerler

	Gurbette kediyle aslan ezerler

	Günbe gùn çamura batıyor derler

	Aklın gitmiş şimdi canındamısın? 

	Bıraktışın yerde baykuş ötùyor

	Zorbalar köyùnù yakıp,yıkıyor

	Gel artık kavgamız seni bekliyor

	De  hele kepezin yanındamısın?', 'Sarp kayada çekirgeye benzerdin 	Poyraz gibi kırat ile tozardın 	Nerde çağırınca orda hazırdın 	Şimdi yolsuzların yanındamısın?  	Yerrdiğin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/de-hele-kepezin-yanimdamisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaramaz oldum', 'yaramaz-oldum-mehmet-ali-kepez-45lqh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yel esti beni aldı savurdu

	Bir daha dalımda duramaz oldum

	Kızgın saç ùstùne koyup kavurdu

	Amàya dönderdi göremez oldum

	Rüzgarın sesini susturamadım

	Gönlùmùn lav''ini bastıramadım

	Ne yana esiyor kestiremedim

	Hayalmi,ruyamı soramaz oldum

	Yürùdùm dolandim gezdim olmadı

	İçip bir kenarda sızdım olmadı

	Bin kere kendime kızdım olmadı

	Şekerdim serbete yaramaz oldum

	Kendi kendisini görmez ışığım

	İşte böyle iflah olmaz aşığım

	Geceler sadıktır  hep barışığım

	Aliştım gùndùzù aramaz oldum', 'Bir yel esti beni aldı savurdu 	Bir daha dalımda duramaz oldum 	Kızgın saç ùstùne koyup kavurdu 	Amàya dönderdi göremez oldum 	Rüzgarın sesi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaramaz-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Tutması', 'kan-tutmasi-emine-deniz-8wi53', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Damlama kirpiklerimden,düşersen ölürsün

Avucumda bir kuş gibi

Atmazsa yüreğin neye yarar 

                                                  Neye yarar

Solarsa gözlerin göz bebeklerime değmeden…

 buruşur  resimler

vermediğimiz pozların gölgesinde

Elin omzumda

Başım çınarlara yaslanmış kadar huzurlu

Dingin…

Yağmurlu bir eylül rüzgarı esiyor beklediğim

Ürpertisi içimde.

Nefesin ensemde.

Bağırmak,  türküler söylemek denize

Koşmak 

Deliler gibi koşmak

seni düşürmeden yere

Hiçbir şiirsizlik acıtmadı canımı 

Yandım işte

‘’sesin beni terkedince’’

Kan tutması bu dilimi

Solgun gecenin teninden düşen ürperti

... hazin çığlıkları eşliğinde acılı bir kadının

Dansöz oynatmak kadar ezici 

Kumral sancılar dolaşıyor göğsümde

Gözlerinin mavisi  bedenimden gitmede…

Parmaklarımın arası 

Ah parmaklarımın arası

Unutulmuş tütün sarısı…

1.08.2005', 'Damlama kirpiklerimden,düşersen ölürsün Avucumda bir kuş gibi Atmazsa yüreğin neye yarar                                                    ...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kan-tutmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni bir şey', 'yeni-bir-sey-mehmet-ali-kepez-hwgah', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tùrkù desen tùrkù deyil

	Şarkıya hiç benzemiyor

	Çaldı söyledi iştahlı

	Bir başı var birde sonu

	içinde yok bir konu', 'Tùrkù desen tùrkù deyil 	Şarkıya hiç benzemiyor 	Çaldı söyledi iştahlı 	Bir başı var birde sonu 	içinde yok bir konu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yeni-bir-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-mehmet-ali-kepez-7td4d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevda iki kitada

	Olmadın oralı yollar

	Yüreği taşta katıda

	Olmuşsun paralı yollar

	Sılayı aratan sensin

	Gurbetı yaratan sensin

	Bahtımı  karartan sensin

	Dertlerim sıralı yollar

        Bırak sılama gideyim

	Gurbeti dostsuz nideyim

	Hangi derdine he deyim

	Bozulmaz kuralı yollar

	Kimi gökte uçup gider

	Yolcu yolun açıp gider

	Yàd ellere göçüp gider

	Ah yüzü karalı yollar

        Nice dağları döndürdün

        Nice  ocaklar söndürdün

        Beni gurbete gönderdin

        Kepez bak yaralı yollar', 'Bir sevda iki kitada 	Olmadın oralı yollar 	Yüreği taşta katıda 	Olmuşsun paralı yollar 	Sılayı aratan sensin 	Gurbetı yaratan sensin 	Bahtı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yollar-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanıma Girdiğin Andan Beri..(düz yazı)', 'kanima-girdigin-andan-beri-duz-yazi-hulya-arisan-06w0q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şeyde sen varsın,

Sokakta, evde hayallerimde her yerde....

Kanıma girdiğinden beri hiç çıkmıyorsun aklımdan.

Bensiz nefes almanı bile kıskanırken, şimdi kimlesin ne yapıyorsun? 

Yaşamın içinde onca ayrıntıyı kiminle yaşıyor kiminle paylaşıyorsun? 

Dağlar sert görünsede,

okyanuslar korkutsada

Senin varlığınla yumuşuyor dağlar,

korkutmaz oldu okyanuslar....

Bir nehir gibi taşmanı

ve bir göl gibi durgunluğunu seviyorum senin....

Sahip olduğum en güzel şeysin, 

kalsan benimle gitmesen....

Heyecanın doruk noktasında buluşalım sevgiyle, bir gece geçirelim isteklice.

 ....sevişelim delice.........

Yüreğim suskun, karma karışık...

.vucudum seni özlüyor...

Kollarım sarılmayı,

gözlerim ışıltını,

kulaklarım sesinin tınısını,

dudaklarım dudaklarını istiyor.....

Sana ulaşmak tek umudum....

Sana kanmak, seni bitirmek değil ki amacım....öyle olsa ne yaparım....

Sonsuza ulaşmak maksadım.

Ürettim sevdamı,

artık benimle sonsuzluğu bulacak sana olan AŞKIM.....

Istanbul, Ağustos 2005', 'Her şeyde sen varsın, Sokakta, evde hayallerimde her yerde.... Kanıma girdiğinden beri hiç çıkmıyorsun aklımdan. Bensiz nefes almanı bile kı...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kanima-girdigin-andan-beri-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurduma', 'yurduma-mehmet-ali-kepez-vytkr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YURDUM A                                                                       

	Yıllar oldu bir can seni sordumu?

	Akıllanır cahil gubet gördùmù

	Dùnyalara deyistirmem yurdumu

	Varsın sokakları çamurlu olsun

	Leylek bile döner yuva yerine

	irkcılar horbakar esmer derine

	Girem çekinmeden vagonlarına

	ister tirenlerim kömùrlù olsun

	Bizi satan beyler duyup bilsinler

	Gurbet yolcuları cayıp dönsùnler

	Vatansız olamam varsın desinler

	ister dört tarafım demirli olsun

	Düzeni kötùyse elbet yıkarım

	Kıraç borlarına fidan dikerim

	Gurbette boynumu niye bùkerim

	Vatana bu sevdan ömùrlù olsun', 'YURDUM A                                                                        	Yıllar oldu bir can seni sordumu? 	Akıllanır cahil gubet gö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yurduma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Böyledir', 'a-boyledir-mikdat-bal-12vjt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir topu ortaya at, gör ne olur o anda

Tekme vuranlar çıkar, meraklı var her yanda

Gülüp geçmeyin sakın, gerçek var bu beyanda

Hem sizde hem de bizde, hem onlarda böyledir! 

Artık bilen, bilmeyen, harekete geçmiştir

Ne kendi taraf olmuş, ne de taraf seçmiştir

Ani bir dalış olmuş, düşünmekten kaçmıştır

İşkembeden atılan yorumlarda böyledir! 

Bir toplumda alkış yap, alkış edenler çıkar

Bir yerde yuh çek de gör, biri etrafı yıkar

Ne meseleyi bilir, ne sebebine bakar

Bu sadece taklittir, maymunlarda böyledir

Bir karaltı belirse olsa bile zararsız

Ortak içgüdü ile kaçışırlar kararsız

Ne desen kar eylemez,  ikazın da yararsız

Ansızın gerçekleşen durumlarda böyledir! 

Mikdadi gerçek söyler bakarlar apış, apış

Güzel bir şey yazınca alırlar kapış, kapış

Birinin arkasından giderler tıpış, tıpış

Koyunlarda böyledir, insanlarda böyledir! 

Ozan Mikdadi', 'Bir topu ortaya at, gör ne olur o anda Tekme vuranlar çıkar, meraklı var her yanda Gülüp geçmeyin sakın, gerçek var bu beyanda Hem sizde hem...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/a-boyledir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşka Veda', 'bir-aska-veda-abdil-yasaroglu-s8xgw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O gün; 

O gün, kar yağıyordu bu şehre,

Denizli ağlıyordu sessizce,

“Gitmelerin zamanıdır artık” diyordu o gece

Bitsin bu işkence …

19.12.2004 23.18', 'O gün;  O gün, kar yağıyordu bu şehre, Denizli ağlıyordu sessizce, “Gitmelerin zamanıdır artık” diyordu o gece Bitsin bu işkence … 19.12.200...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yaşaroğlu']::text[], 8.5, '{"poet":"Abdil Yaşaroğlu","poet_slug":"abdil-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-aska-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Git Gideceksen', 'oyle-git-gideceksen-abdil-yasaroglu-zhejg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğindeki son isyanı söyle de; 

Öyle git gideceksen.

Bir tokat gibi vurup,

Çekip gitme hayatımdan sessizce…

Hatamı söyle,

Konuş,

Öyle git gideceksen.

Konuş ki hayatıma yön vereyim,

Vur ki yüzüme, hatamı, sebebini bileyim.

Susup gideceksen; 

Yaşananları bir anda silebileceksen; 

Seninle hiç bir şey yaşamamış olayım.

Tutmamış olayım ellerini,

Geceleri sarılmamış olayım sıcak tenine,

Kokunu içime çekmemiş olayım,

Hele birde öpmemiş olayım dudaklarını.

Şimdi tekrar düşün,

Öyle git gideceksen,

Dostluğunu, arkadaşlığını,

Bana olan aşkını, sevgini sil,

Öyle git gideceksen.

Öyle git gideceksen.

08.08.2004 23:55', 'Yüreğindeki son isyanı söyle de;  Öyle git gideceksen. Bir tokat gibi vurup, Çekip gitme hayatımdan sessizce… Hatamı söyle, Konuş, Öyle git ...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yaşaroğlu']::text[], 8.5, '{"poet":"Abdil Yaşaroğlu","poet_slug":"abdil-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oyle-git-gideceksen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gezi böyle başladı', 'bir-gezi-boyle-basladi-umut-gungor-7c1or', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir Gezi Böyle Başladı (Bursa-Domaniç)

  



Tarih: 06.08.2005-08-09 

Yer: Kocatepe Camii Yanı / Ankara 

Saat: 07.45 

Bir otobüs öylesine park etmiş etrafında birkaç insan geziniyor, hafif telaşlı, biraz heyecanlı ama uyku mahmurluğu yok gözlerinde, her geleni ayrı bir sevinç ile, neşe ile karşılayıp kucaklaşıyorlar, her gelen ayrı bir heyecanlı, bazıları birbirini önceden tanıyor belli fakat tanışmayanlar aynı samimiyet ve dostlukla kucaklaşıp sarılışıyorlar. 

Vakit geliyor herkes otobüse biniyor, hafif hafif hareket ediyor otobüs, nazlı bir gelin gibi süzülüyor gidecekleri istikamete doğru ve tatlı bir sohbet başlıyor o şirin otobüste. Kaptan yolların kurdu belli, direksiyona hakimiyetiyle hissettiriyor kendini, manevralar ustaca, 

- “Emin ellerdeyiz” diye geçiriyorum içimden. Herkes tanışma ve kaynaşma faslını 

hallediyor kısa sürede ve gezinin gerçek anlamda amacına uygun bir fasıl başlıyor şiir ve şarkılar ile açılıyor perde. 

Gezi ile ilgili ilk konuşmayı kırlaşmış saçları, mert yüreği, yüzünün gülümsemesinde bile bir vakur hava bulunan, hem kafile, hem de gurup kurucusu olan Başkan Hünkar DAĞLI alıyor eline mikrofonu, açılış konuşmasını yaptıktan sonra sırası ile herkes bir şeyler söylemeye başlıyor ve ben bu tatlı telaş içinde ne kadar isabetli bir karar verdiğimi, böylesi Nadide insanlar içinde bulunmanın her kula nasip olmayacağını düşünerek, Allaha Şükrediyorum ve bu havanın asla bozulmaması için dua ediyorum kendi kendime. 

Otobüsün en ön koltuğundan başlayarak sizlere tanıtmama izin verin lütfen bu Nadide ve Seçkin insanları... 

Koltuk No 1: 

Bekir GEDİKOĞLU: Harika bir kişilik olarak tanıdım kendisini, sanal alemde şiirlerini okuduğum ama Reel olarak tanıma fırsatı bulamamıştım bahse konu tarihe ve geziye kadar, katılacağını öğrendiğim zaman çok mutlu olmuştum ve bu mutluluğum Yalancı bir mutluluk değilmiş; Engin tarih bilgisi, Kültürü, Vizyonu ve tatlı dili ile gönlümde şiirleri kadar yer etti. Sevgili Hocam; Sizi tanıma onuru ve gururu bana yetti, Teşekkürler... 

Koltuk No 2: 

Turhan TOY: İşte size Antoloji. Com sitesinin sevgili Turhan Emmisi, Malatya dan aramıza katıldı, tatlı dili, şiirleri, hoş görüsü, insancıl yapısı ve karakterli duruşu gülen yüzü hiç solmasın. Emmi iyi ki geldin ve aramızdaydın. Mutluyum seni tanıdığım için, onurluyum. Teşekkürler... 

Koltuk No 3: 

Ahmet Faruk TÜRKYILMAZ: Zaten yapısını, duruşunu, çizgisini, insanlığını bilmeyen yoktur eğer varsa da öğrenmek için biraz kendisi ile iletişim kurmayı denesinler diye öneririm ve ben kendisini uzun zamandan beri tanırdım, iyi ki tanımışım ve iyi ki bu gezide beraber olmuşsuz. Katılımın ve desteğin için teşekkürler... 

Koltuk No 4: 

İsmet Bora BİNATLI: Şiir dünyasının İsmet abisi, gerek kişiliği, gerek duruşu, gerek babacan tavırları ile gezimizde renkli bir yapı ve, fikir ve görüşleri ile yol gösterici ve aydınlatıcı oldu. Biz Edebiyatın ilk basamaklarında olanlara çok güzel dersler verdi ve ben kendi adıma kendisinden feyz aldım, iyi ki geldiniz ve derin bilgilerinizden bizlere birer yudum tattırdınız. Katılımınız için Teşekkürler Hocam... 

Koltuk No 5: 

Nuray ALPER: Edirne gezisinde beraberdik zaten, onu anlatmaya gerek yok, hanımefendiliği, sakin duruşu, mütevazi yapısı, dikkatimi çeken bir özelliği de (Edirne gezisinde de aynı gözlemi yapmıştım)  tarihi ve kültürü eşsiz yerlerde kendini kaptırıp gözleri buğulanıyor ağlamak üzere oluyor, maneviyatının ne kadar yoğun olduğunu buradan anladım. İyi ki yine katıldın kardeşim, sonsuz Teşekkürler... 

Koltuk No 6: 

Emre ALPER: Nuray ALPER kardeşimizin eşi ve gerçektende çok asil bir beyefendi yapısı, çizgisi, yapısı, karakteri ile tam bir akademisyen olduğunu belli ediyor, Edirne gezisinde tanıştık ve bu gezi ile kaynaştık. Şiire zaman ayıramasa bile aramızda olup, Kültürel bir gezide bizleri desteklemesi ayrı bir güzellikti. Katılımız için sonsuz teşekkürler... 

Koltuk No 7: 

Ahmet KURT: Ahmet abimiz her zaman sessiz, sakin ve gözlemci tarafıyla yanımızdaydı, her mekanı, her ortamı en ince detaylarına kadar gözlemlediğine şahit oldum, onu anlatmaya zaten kelime dağarcığım müsait değil, çünkü o kelimelere sığmayacak kadar geniş bir yapıya sahip her ne kadar suskun ve sessiz olsa da birikimi ve bilgisi ile bana bir çok şey öğretti. Teşekkürler Ahmet hocam... 

Koltuk No 8: 

Asım YAPICI: Kendisi ile bu gezi vesilesi ile tanıştık ve yapısını daha iyi öğrendik, iyi ki katılıp bizlerin arasında olmuş. Hele okuduğu şiirler bir harikaydı en çok Antalya Türküsü olarak okuduğu şiir belleğimde yer etti, ne kadar güzel di, dili tatlı, gönlü geniş, kendi Akademisyen, e daha ne olsun değil mi ama. Katılımınız için Teşekkürler Asım Hocam... 

Koltuk No 9: 

Ulviye SAVTUR: Siz ne güzel insansınız Ulviye Hanım, sizi tanımak beni ne kadar mesut ve bahtiyar etti bilemezsiniz, aramızda olmanız ayrı bir gurur ve onurdu benim için, Sizi hiç unutmayacağım hele okuduğunuz şiirler ve şiire hakim oluşunuz çok güzeldi, tıpkı yüreğiniz gibi. Katılımınız için sonsuz Teşekkürler. 

Koltuk No 10: 

Ramazan KARİMİŞ: Sevgili Kardeşim, genç kalem, dürüst kişilik, mert duruş, şiirin geleceğinde söz sahibi olacak gençlerden biri. Sakin yapısı, duruşu, sessizliği ama gözlemciliği, fotoğraf makinası ile ilginç enstanteneler araması dikkatimi çekti. Gelecekte bu ismi çok duyacağız arkadaşlar, not alın. Seni tanımak çok güzeldi Katılımın için Teşekkürler Kardeşim... 

Koltuk No 11: 

Fatih TAŞKIN: Siyah bereli kardeşim, TRT teklif yaparsa kabul etme sakın çünkü senin çekimlerin bir belgesel olacak nitelikte, özel kanalları düşün. Gezinin Bursa ayağına kadar ekürim olarak görev yaptı, Sivrihisar da kahvaltı hazırlıklarında bana yardım etti, neşe kaynağıydı, söylediği şarkılar hala kulaklarımda hele hele en çok Kazancı Bedi ye ait olan Zalımın Kızı türküsünde birlikte düet yapmamız hiç unutulmaz. Sen ve kameran iyi ki aramızdaydınız, sonsuz Teşekkürler Kardeşim... 

Koltuk No 12: 

Fatih Taşkının Yeğeni: Varlığı ile yokluğu belli değildi ki kardeşimizin, ismini bu yüzden yazamıyorum kusuruma bakmasın, bir görünüyordu, bir kayboluyordu, karabatak misali ama daima gezi içerisinde gerek Fatih kardeşime, gerek diğer arkadaşlara yardım etmek için koşturduğunu gördüm, saygılı ve efendi yapısı ile takdirimi kazandı. Teşekkürler Kardeşim... 

Koltuk No 13: 

Miyase ÇAVUŞOĞLU: Bu gezi için Almanya da ev taşımasını alel acele gerçekleştirip, yaklaşık olarak 40 saatlik bir yolculuk sonrası aramıza katıldı ve bu fedakarlığı ile gönlümde ayrı bir yer kazandı. Sevgili Ablacığım seni tanımak güzeldi, senden biraz Almanca öğrenecektim ama zaman yetmedi, ne yapalım kısmet başka sefere, unuttuğum bilgileri tazeleteceksin sözün var bak J Sevgili Ablam İyi ki geldin, fedakarlığınla beni bir kez daha mutlu ettin. Teşekkürler Ablacığım... Achtung! ! ! 

Koltuk No 14: 

Sabiha RANA: Ablaların en güzeli, melekleri daima bizlere gönderip koruma altında olmamızı sağlayan ablamız, ne güzle seninle aynı otobüste seyahat etmek ve ortamı solumak, Esprilerin, neşen, gülen yüzün, tatlı dilin ile bizleri ne kadar mutlu ettin bilemezsin. Ablacığım Sonsuz teşekkürler. Meleklerin Öpüşleri Yüreğinden Eksik Olmasın Daima... 

Koltuk No 15: 

Ali Rıza NAVRUZ: Sevgili Hocam, Her ne kadar fazla sohbet imkanı bulamasak ta sizi daha önceden tanıdığım için kişiliğinizi ve yapınızı biliyorum, şiirleriniz ile seyahat esnasında bizlere çok güzel duygular yaşattınız, duygularınız içimize aktı, fazla konuşmadınız belki ama bakışlarınızla anlattınız her şeyi. Katılımınız için sonsuz Teşekkürler... 

Koltuk No 16: 

Ümüt GÜNGÖR: Dünyanın en hızlı şairi ünvanı olsa sanırım kendisinden başkası alamaz, her yaşanan olaya, her yapılan konuşmaya anında şiir yazıp kaleme alan ve o dakikada okuyan biri, Ümüt Abi, Sensiz hiçbir gezi düşünemiyorum ben, lütfen asla aramızdan ayrılma ve daima bizlerle birlikte seyahat et olur mu? Sonsuz Teşekkürler Abi... 

Koltuk No 17: 

Hünkar DAĞLI: Kendisi gurup kurucumuz ve Başkanımız, çok kişi için yapısı Guruba uygun yani Sivri gelebilir ama Anlayana Sivri biri, yaptığı güzel organizasyonlar ile bizleri şehir şehir dolaştırarak, unuttuğumuz değerlere yolculuk yaptırdığı için sonsuz teşekkürlerimi baştan sunayım sonra gezi esnasında bir Lider sıfatı taşıması nedeniyle gerçek bir Liderlik örneği göstermiştir. Böyle bir gezi düzenlediğin ve bizleri bir araya bir kez daha getirdiğin için bir kez daha Teşekkürler başkanım... 

Koltuk No 18: 

Uğur ALAYBEY: Sessiz sakin, gezi içerisinde gözlemci gibi durdu Elinde Fotoğraf makinesi ile tüm güzellikleri çekti, sonrada öğrendim ki Uğur bey aslında Fotoğraf Sanatçısı imiş, bu yüzden çok mutlu oldum, usta bir sanatçı tarafından gittiğimiz, gezdiğimiz ve gördüğümüz mekanlar ölümsüz karelerde yaşayacak diye düşündüm. Sevgili Uğur Bey, katılımınız için Sonsuz Teşekkürler... 

Koltuk No 19: 

Leyla AKGÜL: Ankara dan Otobüse bindi, şiirleri ve türküleri ile aramızda oldu. Teşekkürler... 

Koltuk No 20: 

Mehmet TEKECİ: Ankara dan Otobüse bindi, Şiirleri ile aramızda oldu. Teşekkürler... 

Otobüsümüz Sivrihisar da Mola verdi, 

Belediye başkanı Sayın Yaşar YURTDAŞ tarafından karşılandık ve kahvaltı için belirlenen mekana vardık, Yumurtalar ve Sucuklar ortaya çıktı, tabaklar hazırlandı, Avcılar Derneği Lokalinde demlenen taze Tavşan kanı çaylar servis olarak sunuldu. Ben ve Fatih Tavayı hazırlayıp başladık YUMURTALI SUCUKLARI hazırlamaya ve servislere, bu arada bayanlar Peynirleri, zeytinleri ve domatesleri servis yaptılar, güzel bir kahvaltı sonrası Sayın Başkanın konuşması ve karşılık olarak Kafile ve Gurup Başkanımız Hünkar DAĞLI nın konuşmasının ardından, Belediye Başkanına Anlayana Sivri Gurubu adına Plaket takdim edildi ve Sayın Belediye Başkanı Yaşar YURTDAŞ bey Sivrihisar ile ilgili bir kitap hediye edip imzaladı, sohbetler edildi, ardından Sivrihisar da bulunan Tamamen Ahşap direkler ile yapılmış olan Camii ziyaret edildi. Vakit geçiyordu ve gideceğimiz yolumuz uzundu Eskişehir den aramıza katılacak olan arkadaşlarımız vardı, Sayın başkandan müsaade isteyip yola çıktık. 

Eskişehir de Otobüsümüze iki kişi bindi biri Neslihan YAZICILAR diğeri saygıdeğer ve sevimli Annesi. 

Koltuk No 21: 

Neslihan YAZICILAR: Antolojiden şiirlerden tanıdığım ve seyahat esnasına kadar hiçbir şekilde diyalog kurmadığım biriydi, otobüse binerken “ Ne kadar havalı bir hanım, burnu büyüktür şimdi bunun” diye düşündüm açıkçası ama asla öyle olmadığını daha sonra anladım ve bu düşüncemden ötürü kendimden utandım (bu bir itiraftır)  Sevgili Neslihan, o kadar şirin, sempatik, dost canlısı ve samimi ki şaşmamak mümkün değil, yüreğinin güzelliği yüzüne yansımış, tatlı dili ile sohbeti ve okuduğu şiirler ve şarkılar çok güzeldi. Teşekkürler Neslihan İyi ki katıldın ve seni tanıdık... 

Koltuk No 22: 

Neslihan Yazıcıların Annesi: Gülmeyi bir bıraksa ismini soracaktım ama o kadar şirin ve güler yüzlü ki (sonradan başımız ilginç bir olay geldi daha sonra anlatacağım)  nasıl bu kadar neşeli olduğuna şaşmamak imkansız, ben onu çok sevdim, inşallah o da bizi sevmiştir. Teşekkürler Katıldığınız için, Ellerinizden Öpüyorum... 

Otobüs yine hareket etti, hayallah zaman ne çabuk geçiyor yahu diye düşünüyorum kendi kendime bu arada ben en arkada Ele başılık yaparak sigara içmeye başladığım ve bana içenler katıldığı için şoför arkadaş ikide birde aynadan bana bakıyor bir şey söyleyecek ama vazgeçiyor :-)  Fatih elinde kamera ile bir öne bir arkaya gidip geliyor, bir eksiklik hissediyor belli ama oda bunu dile getiremiyor ama ben anlıyorum onun eksikliğini onun için en büyük eksiklik seyahat esnasında sevgili Fahrettin KÖSEOĞLU nun yokluğu. Birlikte bir şeyler yapmaya çalışıyoruz ama ben aynı tadı ve havayı veremiyorum belli, onun için illede Fahrettin gerekli, neyse birkaç saat sonra inşallah Fahrettin aramıza katılacak Fatihin de bu huysuz atlar gibi bir ileri bir geri olan tavırları bitecek diyorum kendi kendime gülerek. 

İstikamet Ertuğrul Gazi Gazi Türbesi: 

Ertuğrul Gazi Türbesinin olduğu mekana varıyoruz ki harika bir ortam ve büyük bir otağ çadırı ile karşılaşıyoruz, hepimizin gözleri bir heyecan ile parlıyor, kolay mı Yüz yıllar boyu Tarihe nam Salmış bir Devletin ilk kurucusunun türbesini göreceğiz biraz sonra, bu ne kadar güzel bir duygu Allahım diye içimden geçiriyorum. Türbenin kapısı açılıyor ve içeriye giriyoruz ki ne muhteşem bir görüntü bizi karşılıyor, içeriye attığım ilk adım sonrası gözlerim dolu dolu oldu, bir kenara çöktüm ve dua etmeye başladım içime ayrı bir huzur ve serinlik çöktü sanki bir müddet orada öylece kaldım, türbeyi seyrettim, bütün Türk-i Cumhuriyetlerin bayrakları ve günümüze kadar kurulmuş olan tüm beyliklerin bayrakları türbe üzerindeydi hayranlıkla seyrettim ve bir ses beni kendime getirdi, bu Başkanın sesiydi: 

-Haydi arkadaşlar, Gözleme ve Ayranlar hazır, bizleri bekliyorlar... 

Hemen çadır içerisinde yer sofrasında yerlerimizi aldık ve o harika gözleme ve ayran ile karnımızı doyurduk (ben herkesten bir tane fazla yedim buda bir itiraftır)  tekrar yola çıktık, bu defa istikamet Bilecik... 

O kadar güzel geçiyor ki yolculuğumuz, neşe, eğlence, şiirler, şarkılar eşliğinde Otobüsümüz Bilecik kentine vardı. Şeyh EDEBALİ Türbesine uğramadan geçmek olmaz. 

Oraya da uğrayıp Dua edip, türbesini ziyaret ettik ve müthiş bir duygu da orada yaşadık, aklıma bu toprakların Osmanlı İmparatorluğunun kurulduğu topraklar üzerinde olduğumuz ve bu Devletin Yüzyıllar boyu ne kadar adil bir yönetim gösterip te tüm himayesindeki devletlerin memnun ve mesut oldukları ve o Devletin temellerinin atıldığı bu topraklarda olmanın ne güzel bir duygu olduğu geldi, hüzünlendim, duygulandım, gururlandım... 

Yola Çıkıyoruz İstikamet BURSA..... 

Devam edecek...! ! !', 'Bir Gezi Böyle Başladı (Bursa-Domaniç)    Tarih: 06.08.2005-08-09  Yer: Kocatepe Camii Yanı / Ankara  Saat: 07.45  Bir otobüs öylesine park ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/bir-gezi-boyle-basladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Güzeller Güzeli...', 'gitme-guzeller-guzeli-guner-kaymak-s0k5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhamet eyle halime 

Gitme güzeller güzeli 

Düseriz ellerin diline 

Gitme güzeller güzeli 

Bahçemde güller sararir 

Ay söner günes kararir 

Yillar ömrümü yipratir 

Gitme güzeller güzeli 

Söner gözlerimin feri 

Yasamin olmaz degeri 

Sensin gönlümün cevheri 

Gitme güzeller güzeli 

Dünya basima yikilir 

Maziye aklim takilir 

Düsmanlar kina yakinir 

Gitme güzeller güzeli 

Ruhumu sikinti sarar 

Hükmeder kalbimi yorar 

Dostlar benden seni sorar 

Gitme güzeller güzeli 

Dünyada mutlu olamam 

Yokluguna ben alisamam 

Hiç kimseyle konusamam 

Gitme güzeller güzeli 

Tutmaz dizlerimin bagi 

Erir yüregimin yagi 

Söner Güner''in ocagi 

Gitme güzeller güzeli 

Ozan Güner Kaymak/Amsterdam 18.08.2005', 'Merhamet eyle halime  Gitme güzeller güzeli  Düseriz ellerin diline  Gitme güzeller güzeli  Bahçemde güller sararir  Ay söner günes kararir ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gitme-guzeller-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedemden', 'dedemden-seref-akar-samut', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dedem “itibar” derdi: ömrün en kutsal malı

Haya, söz, iş ve fikir şanını korur olsun

Sende hırsın, hasetin hiç yeri olmamalı 

Varma şer dergahına, nişanın onur olsun

“Oğul” dedi: hüsn-ü zan, ne asil bir sermaye

Oysaki zamanede, su-i zan paşa olmuş

Komşunun iffetine iftiralar sürmeye

Bey gönüllü pezevenk, hanım fahişe olmuş', 'Dedem “itibar” derdi: ömrün en kutsal malı Haya, söz, iş ve fikir şanını korur olsun Sende hırsın, hasetin hiç yeri olmamalı  Varma şer derg...', ARRAY['Türk Edebiyatı','Şiir','Şeref Akar']::text[], 8.5, '{"poet":"Şeref Akar","poet_slug":"seref-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dedemden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Söylenmiş Sözler Gibiydik', 'zamansiz-soylenmis-sozler-gibiydik-melih-coskun-7boyh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamansız söylenmiş sözler gibiydik

Bir imla hatası gibi yaşadığımız ömrümüzde

Aykırı cümleler gibiydik 

Aykırı zamanlarda kurulmuş

Bir kez olsun tutuşmadan ellerimiz

Bir kez olsun bakamadan gözlerimizin içine doyasıya

Vardık bitimsiz sandığımız yolun sonuna

Uzak dağları yarıp geçerken bu haykırış 

Yetmemişti menzili yanı başımızdakine 

Kurumuş nehir yataklarında 

Taşmaya hazır beklerken kelimelerim,

Ne garip şey 

Çığlar taşırken yüreğinde 

Karları erimiş dağ başlarının yalnızlığında kalmak, 

Ne garip şey 

Bağıramamak yırtar gibi sessizlikleri 

Seviyorum seni diyememek yüreğinin olanca sesiyle.

Artık ne söz kalır geriye 

Ne sararmış bir resim. 

Unutmak; 

En nankör hastalığı insanoğlunun 

Azcık efkar, 

Birkaç damla gözyaşı 

Gerisi yalan 

Gerisi,

Hiç kurulamamış bir cümle...

2003', 'Zamansız söylenmiş sözler gibiydik Bir imla hatası gibi yaşadığımız ömrümüzde Aykırı cümleler gibiydik  Aykırı zamanlarda kurulmuş Bir kez o...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/zamansiz-soylenmis-sozler-gibiydik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Karanlık', 'karanlikta-karanlik-suna-aras-rtl3o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlık saçlarından 

Tutarak aydınlığı

Karanlıkta karanlık

Bir kuyuya hapsetti

Karanlık aydınlığın

Çıkarıp yüreğini

Karanlık kişilere

Karanlıkta yedirdi.

Karanlık karanlığın

Diz çökerek yanına

Karanlık düşler kurup

Yayıldılar dört yana

Karanlık yol üstünde

Kuruldu her köşeye

Karanlık evler oldu

Karanlık kentler oldu

Yüreklere karanlık

Kara kara oturdu

Karanlık kişilere

Karanlık amaç oldu.

Sonra her kara kişi

Bir “kara köpek” olup 

Karanlıkta karanlık

Kişilere satıldı.

Büyüdükçe büyüdü

Karanlık karanlıkta

Karanlık karanlıktan

Kara günler getirdi

İnsanın insanlığı

Böylece elden gitti.', 'Karanlık saçlarından  Tutarak aydınlığı Karanlıkta karanlık Bir kuyuya hapsetti Karanlık aydınlığın Çıkarıp yüreğini Karanlık kişilere Karan...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/karanlikta-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Bir', 'o-bir-mehmet-isikoglu-shwrg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O bir sırmalı taç

Kasar kendini

Beğenmez her önüne geleni

Uzak durur ürkektir

Bakar soluna sağına

Bilir kurnaz 

Ünü her yerde

Gelecektir herkes ayağına 

Başta baştır

Her derde ilaçtır

Sesi kokusu güzel herşeyden

Daha değerlidir gelin güveyden

Uçar yükseklerden

Gözetir geleni 

Yakın dost olur

Bulursa işi bileni

Alır kanatlarına

Yükseltir birden

Severse yerini

Gönenir semirir

Güldürür bir müddet

Üzersen

Terkeder serini

Eder ekmeğe muhtaç', 'O bir sırmalı taç Kasar kendini Beğenmez her önüne geleni Uzak durur ürkektir Bakar soluna sağına Bilir kurnaz  Ünü her yerde Gelecektir her...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın ve Elveda', 'gunaydin-ve-elveda-suleyman-yavuz-chhah', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günaydın sana günaydın

Elveda hoşça kal

Kaybedilmişliğin 

Ve kaybetmiş olmanın acısına da elveda

Senle yaşanmış ne varsa 

Geçirilmiş güne geceye

Mehtaba çıktığımız o kumsala 

Elveda

Sen istedin ayrılığı 

Sen bitirdin bu güzellileri

Sadece sen

Şimdi git dedin 

Çek git dedin 

Elveda sana 

Görmezden geldiğin 

Benim yerine hiçbir şey 

Koyamadığım

Asla da hiçbir aşkla ölçüştüremeyeceğim 

O büyük aşka sevgiye elveda

Ve sana da günaydın bensiz uyandığın 

Yeni günün aydınlık olsun 

Ve bensiz hayatın

Hep mutlu olsun

Günaydın ve elveda', 'Günaydın sana günaydın Elveda hoşça kal Kaybedilmişliğin  Ve kaybetmiş olmanın acısına da elveda Senle yaşanmış ne varsa  Geçirilmiş güne ge...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gunaydin-ve-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-suleyman-yavuz-rlzvt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep beklersin hayattan bir ışık

Umarsın umarsızca beklersin

Kader bir gün gülsün diye yüzüne

Beklersin bir gün büyük işlerin olsun diye

Söyle bu açlık niye

Yedin bitirdin kendini

Hep bekledin bir ışık 

Bir umut Hak’tan

Ama hiçbir iş yapmadın 

Oturdun boş ve gönül hayalde

Düşte eller kaldı boş

Başlamadan işe 

Kalktın sen boş bir tevekküle

Söyle bu yoğurdun bolluğunu nerde

Sen besle gönlünü umutla

Bir gün Hak senide görür bekle

Umut senin ekmeğin belli

Çalışmak neyine

Oyna lotonu totonu

Vurur sana da belki 

O büyük ikramiye

Umut sana yar olmuş

Hayatın bomboşmuş

Ömür belli geçecek

Hayal ile düş ile

Hülyalı günler ile

Sen son nefeste varacaksın farkına

Ah ben ne yaptım diye', 'Hep beklersin hayattan bir ışık Umarsın umarsızca beklersin Kader bir gün gülsün diye yüzüne Beklersin bir gün büyük işlerin olsun diye Söyl...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/umut-200-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryad-ı Figan', 'feryad-i-figan-kemal-tahir-ozcan-io7s0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhum feryad ediyor, firkat-i hazan ile,

Yanıyor tul-i emel, ateş-i hicran ile.

Titriyor bir nazarda, sine-i perişanım,

Tarumar oluyorum, sevday-ı tufan ile.

Rahmını talebim yok, mani olur hicabım,

Ahkamına muntazır, vücudum bir can ile.

Münasip değil amma, bi-haberim raddeden,

Yüreğim mestanedir, hüsnünü seyran ile.

Ukbaya mütenasip, belki sana vuslatım,

Cihana ram olamam, ümid-i viran ile,

Müptelayım ismine, cürmüm idrakimdedir,

Lakin akl-ı divane, düşünmez irfan ile.

Haddime düşmez elbet, zat-ı na hayran olmak,

Affet bırak TAHİR'' i, feryad-ı figan ile.', 'Ruhum feryad ediyor, firkat-i hazan ile, Yanıyor tul-i emel, ateş-i hicran ile. Titriyor bir nazarda, sine-i perişanım, Tarumar oluyorum, se...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/feryad-i-figan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'H a r m a n...', 'h-a-r-m-a-n-zafer-zengin-etnika-w34om', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

Koyup ellerimi dizime

Gülü seyrettim beş saat

Sonra sarıldım

Gülden yana acılıydım

| kırmızıyı çalar içimden hasret..ateş alır rengi |

Çocuktum

Saçları sarıydım

Sarıyı saçlarım yaptım

Bozkır düşer ömrüme

Yaslayıp sırtımı gölgeye

Ekin tararım yüreğimle

Harman ki

Ömrümün orta yerinde

Çocuk büyür gölgede.gece..gece...

01 12 2004

.', '. Koyup ellerimi dizime Gülü seyrettim beş saat Sonra sarıldım Gülden yana acılıydım | kırmızıyı çalar içimden hasret..ateş alır rengi | Çoc...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/h-a-r-m-a-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvarın öte yanından b a ğ ı r d ı m...', 'duvarin-ote-yanindan-b-a-g-i-r-d-i-m-zafer-zengin-etnika-awov1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.



duvarın öte yanından bağırdım

haber var mı

- şiir var dediler -

sıkıntı bitmez dedi

söyledi

dinledi

yüceltti bir vakit sözü

ses''e iliştirdi

güzelledi



.

yaz’dı

elleri yaktı güneş

öyle ölümlüydüm ki

dokunmadım kendime

ilk defa durdum

mavi deniz üstünde

ellerimle...

27 07 2005

.', '. duvarın öte yanından bağırdım haber var mı - şiir var dediler - sıkıntı bitmez dedi söyledi dinledi yüceltti bir vakit sözü ses''e iliştird...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duvarin-ote-yanindan-b-a-g-i-r-d-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenk', 'cenk-kemal-tahir-ozcan-9brh6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Miğferler giyildi, atlar binildi,

Gözler düşmanları, arıyor şimdi.

Kılıç kından çıktı, yaylar gerildi,

Topuzlar kalkana, vuruyor şimdi.

Her mızrak darbesi, kanlar saçıyor,

Atlar şaha kalkmış, oklar uçuyor,

Bu ordu yeni bir, devir açıyor,

Zulüm zincirini, kırıyor şimdi.', 'Miğferler giyildi, atlar binildi, Gözler düşmanları, arıyor şimdi. Kılıç kından çıktı, yaylar gerildi, Topuzlar kalkana, vuruyor şimdi. Her ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cenk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutamamaktan Korkuyorum', 'seni-unutamamaktan-korkuyorum-abdulkadir-karaca-hp8gj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni unutamamaktan korkuyorum

Çektiğim her iki nefesin ikisinde de kaybolmamandan

Bunca yara inadına her gece

Bir daha,bir daha kanamaktan

Korkuyorum

Sensizliği yaşayamamaktan

Her üçüncü sayfa haberine

Ölen sensin korkusuyla bakmaktan korkuyorum

Bir felaket ardından resminin ekranda belirmesinden

Alt yazıda isminin geçmesinden

Zamanın gelince sensiz ölememekten 

Sensizlikten utanmaktan

Seni unutamamaktan korkuyorum

Sensizliğe doğrulttum silahımı

Fakat tek kurşunda vuramamaktan korkuyorum

Silahın ateş almamasından

Ellerimin titremesinden

Namlunun ucunda hayalinin belirmesinden

Sensizliğin hızlı davranıp beni devirmesinden korkuyorum

Soruların üstüme gelmesinden

Bu ayrılığa bir gerekçe bulamamaktan

Sensiz kalmaktan değil inan

Seni unutamamaktan korkuyorum

Öpmekten hiç korkmadım seni

Bağlanmaktan korktum hep

Bağlandım

Düştü gardım

Korkmuyorum bir düzine vicdansız insanın

Ayağı altında çiğnenmesinden aşkımın

Yerine birşey koyamamaktan

Seni unutamamaktan korkuyorum

Ya birgün göz göze getirirse kader

Benim elimde ümitlerim

Senin kolunda yeni sevgilin varsa eğer

Birgün sana böyle raslamaktan

Gözlerine bakamamaktan değil

Baktığım an seni unutamadığımı anlamandan

Koyup gidişinden sonra başka bir aşka

Mecal bulamamaktan

Sana tutkun kalmaktan belki de

Seni unutamamaktan korkuyorum

Korkmazdım

Kalbimi bir ömür gözlerinde hapsetmenden

Gidişin ürkütmedi geceyi

Bir mühürlü aydınlığa kapatmalı sensizliği

Utanamam arkandan yakınamamaktan

Anlatamam seni özlediğimi

Seni unutamamaktan korkuyorum

(19.08.2005)', 'Seni unutamamaktan korkuyorum Çektiğim her iki nefesin ikisinde de kaybolmamandan Bunca yara inadına her gece Bir daha,bir daha kanamaktan K...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/seni-unutamamaktan-korkuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Suçum mu?', 'benim-sucum-mu-serhat-karadumanli-ep8u2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oturdum yapayalnız sahilde

Dalgalar hırsla kalbimi dövüyordu

Gözlerim ürkekçe aradı seni 

..............................................-ama yoktun-

Kalbimin kapısı örümcek tuttu,

Sen yoksan giremez kimse...

Gecenin bir vaktinde düşündüm insanları

Mutluydular

Kahkahaları gökyüzünde yankılanıyordu

Bazılarıysa

Tenha yerlerde

Hüznün kollarında titriyordu

Kimsesizdiler, açtılar...

Benim de onlardan pek farkım yok

Ruhum sevgine acıkmıştı

Hüznün koynunda zangır zangır titrerken 

Gözlerimde acının ayak izleri derinleşiyordu...

Yosun tutmuş uçurumlarda yüreğimi dişlerken

Gece boyu sözcüklerde hep ismini fısıldadım...

Şimdi söyle bana...

Gözlerimi hüzün işgal etmişse benim suçum mu? 

Sana sarılamıyorsam,

Sensizliğin koynunda Aiakos''un şarabını yudumluyorsam

Yokluğunla savruluyorsam kuytuluklara

Ve ruhumun abislerinde boğuluyorsam benim suçum mu? 

Yüreğim ağlıyorsa 

Ve bu yüreğimin pencerelerine yansıyorsa 

............ benim suçum mu? ...

(2002-2005)', 'Oturdum yapayalnız sahilde Dalgalar hırsla kalbimi dövüyordu Gözlerim ürkekçe aradı seni  ..............................................-ama...', ARRAY['Türk Edebiyatı','Şiir','Serhat Karadumanli']::text[], 8.5, '{"poet":"Serhat Karadumanli","poet_slug":"serhat-karadumanli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/benim-sucum-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahalle kavgası', 'mahalle-kavgasi-mikdat-bal-3lvku', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorgundum uzandım dinleniyordum

Gözlerim daldıydı uyuyordum ben

Dışarı çık diye ünleniyordum

Zannetsem ismimi duyuyordum ben

Yabancı düşmanı bir kaç soytarı

Tehditkar tavırla vermiş uyarı

Saçları kazınmış hem iri yarı

Yeni uyanmıştım ayıyordum ben

Derken bir taş gelmiş camlar döküldü

Ne oluyor dedim canım sıkıldı

Bir baktım üç kişi yere yıkıldı

Düşeni kalkanı sayıyordum ben

Düşenler onlardı dayak yediler

Çocuklar onları haşat ettiler

Gelmeyiz bir daha tövbe dediler

Gençleri içeri koyuyordum ben

Her şey sakinleşti polis gelince

Bize ses etmedi haklı bilince

Türkler çok güçlüdür birlik olunca

BAL der heyecandan bayıyordum ben', 'Yorgundum uzandım dinleniyordum Gözlerim daldıydı uyuyordum ben Dışarı çık diye ünleniyordum Zannetsem ismimi duyuyordum ben Yabancı düşmanı...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mahalle-kavgasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şarkısın sen', 'bir-sarkisin-sen-elazigli-mustafa-kaya-7unz8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'daha girmemiştim hayatına

yazmıyor...hissetmiyor..konuşmuyordum kimseyle

gezinip durduğum sahillerde.

şehir güzel…her şey harika..hayat mükemmel

kalbim sancılı…ve kimsesiz

benimle aynı bir kalbi nasıl

bulup çıkartabilirdim 

diplerindeyken uçurumun. 

yıllarca didinip durduğum yalnızlığıma nasıl girdin.? 

bırakıp gideceğin,

ve bin defa döneceğin sevgiyle

birlikte büyüttüğümüz.

nar ağaçları nasıl çiçek açar bilir misin..? 

sakarya  nasıl akar gördün mü.? 

hayatıma seni beklerken çektiğim. 

bir bakışın vardı ateşlere düşürdüğün

kıskanırdım yüzüne düşen gölgeyi.

kapılıp rüzgarına kaderin

güzelim saçlarına ve gözlerine giderim

ve sana yenik düşen yüreğimle.

bağrımda bir yara uzaklığın.

daracık sokaklardayım.

ve ne zaman seni düşünsem

bir şarkı dökülür dilime

sen uzaklarda değil…/..damarımda kanımsın

ben sensiz yaşayamam…/hayatımsın canımsın…/

ve gün ay a yıldızlara dönüşürken sevgilim,

saklandığımız yerleri kimselere söylemedim..

                                                                             

                                              19.08.2005 / Üsküdar

                                               Mustafa kaya', 'daha girmemiştim hayatına yazmıyor...hissetmiyor..konuşmuyordum kimseyle gezinip durduğum sahillerde. şehir güzel…her şey harika..hayat müke...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-sarkisin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul ve martılar', 'i-stanbul-ve-martilar-elazigli-mustafa-kaya-jodi6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'simitleri almıştım.

üsküdar iskelesinden bir vapura binecek,

koparıp koparıp simitleri

martılara atacaktık.

Eminönü nde inecek bukez kadıköy vapuruna binecektik ve 

martılar bize alışacak.

saçların  savrulacak  rüzgarda 

tel  tel  martılar  konacak

ve köpükler arasında bir martı

şarkı  söyleyecek 

istanbul un tüm martıları bize uçacakl 

çığlıklar çığlıklara karışacak 

gökyüzü beyaz kuşların dansına bakacak 

ve sen 

ve ben 

gün inerken suya 

kızıllığında akşamın 

ismini daha bilmeyeceğim 

ve bir bulut gibi akıp gideceksin 

yaşanan bir düş kalacak 

istanbul ve martılar hep bizi konuşacak..

                                                                                     11.07.2005 / istanbul

                                                                                      mustafa kaya', 'simitleri almıştım. üsküdar iskelesinden bir vapura binecek, koparıp koparıp simitleri martılara atacaktık. Eminönü nde inecek bukez kadıköy...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/istanbul-ve-martilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Konuşma', 'karanlikta-konusma-nurdan-unsal-uqy1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlıkta konuşma 

Duyamıyorum...

Gün ışıyınca gel 

Görmem gerek

Yüzün, ellerin

İlle de gözlerin olmalı

Konuşmasan  da olur

Göreyim gözlerini

Karanlıkta konuşma 

Anlamıyorum...

Nurdan Ünsal

Ankara

18.08.2005

-Dikili Ekin,2006 Temmuz-Ağustos, Sayı:41

-Antalya Güllük Şiir Güldestesi, 2005,Özel sayı:2', 'Karanlıkta konuşma  Duyamıyorum... Gün ışıyınca gel  Görmem gerek Yüzün, ellerin İlle de gözlerin olmalı Konuşmasan  da olur Göreyim gözleri...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Ünsal']::text[], 8.5, '{"poet":"Nurdan Ünsal","poet_slug":"nurdan-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karanlikta-konusma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Ver Mevlam Yanıyoruz', 'su-ver-mevlam-yaniyoruz-caglar-asik-dqxaa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alev alev aşkın yakar.

Aşıklar aşkını çağlar.

Aşıklar ateşle parlar.

&

Su ver Mevlam yanıyoruz.

Su ver Mevlam yanıyoruz.

&

Doldur aşkını gönlüme.

Sardır aşkını ruhuma.

Yandır aşkına, söndürme.

&

Su ver Mevlam yanıyoruz.

Su ver Mevlam yanıyoruz.

&

Cezamız var, yüzümüz nar.

Aşkımız var, gönlümüz har.

Derdimiz var, yaşımız yar.

&

Su ver Mevlam yanıyoruz.

Su ver Mevlam yanıyoruz.

&

Geldik aşkınla karşına.

Döndürme bizi şaşkına.

Daldırma derin uykuya.

&

Su ver Mevlam yanıyoruz.

Su ver Mevlam yanıyoruz.

&

Ecel yakın görür olduk.

Azraili bekler olduk.

Zikrin ile ağlar olduk.

&

Su ver Mevlam yanıyoruz.

Su ver Mevlam yanıyoruz.

&

Azrail ruhlar alandır.

Sorgu sual yakındadır.

Mahşer Hakkın günündedir.

&

Su ver Mevlam yanıyoruz.

Su ver Mevlam yanıyoruz.

&

İstanbul -  15.08.2005

Çağlar Aşık – Su Ver Mevlam Yanıyoruz', 'Alev alev aşkın yakar. Aşıklar aşkını çağlar. Aşıklar ateşle parlar. & Su ver Mevlam yanıyoruz. Su ver Mevlam yanıyoruz. & Doldur aşkını gön...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/su-ver-mevlam-yaniyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Sana', 'asigim-sana-caglar-asik-3snnv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geldim kapına.

Girdim yoluna.

Çıkmam bir daha.

Ahdim var Sana.

&

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

&

Ne bir deliyim.

Ne divaneyim

Aşkınla yanan.

Bir viraneyim.

&

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

&

Aşığım Sana.

Doymam aşkına.

Sormam hiç Sana.

Döndür mecnuna.

&

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

&

İsteğim verdin.

Yoluma serdin.

Borcum nedeyim.

Şükrüne geldim.

&

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

&

Buldum sabırı.

Gördüm fikiri.

Söylet zikiri. 

Düzelt fakiri. 

&

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

&

Canıma cansın.

Hayat sunansın.

Kabre sokansın.

Hesap soransın.

&

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

&

Kavuşsak Sana.

Ne sunsak Sana? 

Rızan olursa.

Nurun temaşa.

&

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

Allah Hu Allah

&

İstanbul – 15.08.2005

Çağlar Aşık – Aşığım Sana', 'Geldim kapına. Girdim yoluna. Çıkmam bir daha. Ahdim var Sana. & Allah Hu Allah Allah Hu Allah Allah Hu Allah Allah Hu Allah & Ne bir deliyi...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/asigim-sana-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak Aşıkları', 'hak-asiklari-caglar-asik-eteep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hak’kı görebilmeyi,

Hak’kı duyabilmeyi,

Hak’kı bulabilmeyi,

Hak’la olabilmeyi,

&

İster Hak aşıkları.

Umar Hak aşıkları.

&

Gönülle yanmayı,

Koruyla uyanmayı,

Rızayla kavuşmayı,

Nuruyla buluşmayı,

&

İster Hak aşıkları.

Umar Hak aşıkları.

&

Cennetinde durmayı,

Huzurunda olmayı,

Güveninde kalmayı,

Nurunu temaşayı, 

&

İster Hak aşıkları.

Umar Hak aşıkları.

&

İstanbul – 16.08.2005

Çağlar Aşık – Hak Aşıkları', 'Hak’kı görebilmeyi, Hak’kı duyabilmeyi, Hak’kı bulabilmeyi, Hak’la olabilmeyi, & İster Hak aşıkları. Umar Hak aşıkları. & Gönülle yanmayı, K...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hak-asiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Canım Sen Nerdesin?', 'soyle-canim-sen-nerdesin-caglar-asik-7ei9m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Coşup coşup, çağlar mısın? 

Gülüp gülüp, ağlar mısın? 

Hak yolunda, koşar mısın? 

&

Söyle canım, sen nerdesin? 

Söyle canım, sen nerdesin? 

&

Duyan alır, lezzetini.

Kabul eder, her emrini.

Ahdi olur, hem yemini.

&

Söyle canım, sen nerdesin? 

Söyle canım, sen nerdesin? 

&

Ağlayanlar, bir gün güler.

Hak rızasın, kimler erer? 

Temaşayı, kimler eder? 

&

Söyle canım, sen nerdesin? 

Söyle canım, sen nerdesin? 

&

İstanbul – 16.08.2005

Çağlar Aşık – Söyle Canım Sen Nerdesin?', 'Coşup coşup, çağlar mısın?  Gülüp gülüp, ağlar mısın?  Hak yolunda, koşar mısın?  & Söyle canım, sen nerdesin?  Söyle canım, sen nerdesin?  ...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/soyle-canim-sen-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Canım Gelir Misin?', 'soyle-canim-gelir-misin-caglar-asik-v6ixq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün dost bağına girsek.

Resul, Nebi orda görsek.

Şehit, dostlar hep dinlesek.

Hak yolların hep izlesek.

&

Söyle canım, gelir misin? 

Söyle canım, gelir misin? 

&

Resul sünnetine uysak.

Farzları hep, eda etsek.

Hak’kın rızasını umsak.

Temaşaya talip olsak.

&

Söyle canım, gelir misin? 

Söyle canım, gelir misin? 

&

İstanbul – 16.08.2005

Çağlar Aşık – Söyle Canım Gelir Misin?', 'Bir gün dost bağına girsek. Resul, Nebi orda görsek. Şehit, dostlar hep dinlesek. Hak yolların hep izlesek. & Söyle canım, gelir misin?  Söy...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soyle-canim-gelir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Depremimiz (Nişanlımın babasına-babamıza ithafen)', 'bizim-depremimiz-nisanlimin-babasina-babamiza-ithafen-i-lknur-er-kjig2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '16 Ağustos 2005

Saat 15:20

Bizim depremimiz

Kalp hastanesinde

Kalbimizi bıraktık

Nasıl bir yürek sancısıdır bu

Yokmuş tarifi

Gözlerde ne çok yaş varmış

Bilmiyordum

Bakmaya kıyamadığımız

Nur yüzlü babamız

Allah sevgisi o kadar çoktuki

Bizi bırakıp ona gitti

Kavuştu sevdiğine

Çokta çekti ya tam beş ay

Hastanelerde

Tam ameliyat oldu kurtuldu derken

İlaçların dozu düşünce

Tansiyonda düştü

Yada şöyle demeliyim

Azrail 

Tansiyon kılığında geldi

Son olarak melekleri görmüş olmalı ki

Gülüyormuş yüzü

Çocukları çok severdi

Çocuk parkı yanında

Küçücük bir evi var şimdi

Mezar diyorlar ya 

Yakıştıramıyorum o ismi

Evinde bekliyor kadınını

Sevdiğini

Bir odada ona aldık yanında

Dileriz uzun süre dolmaz içi.

16 Ağustos

Bizim depremimiz', '16 Ağustos 2005 Saat 15:20 Bizim depremimiz Kalp hastanesinde Kalbimizi bıraktık Nasıl bir yürek sancısıdır bu Yokmuş tarifi Gözlerde ne çok...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bizim-depremimiz-nisanlimin-babasina-babamiza-ithafen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum aşkım', 'gidiyorum-askim-yasemin-kurt-nzrt6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dışarıda yağmur yağıyor,

Nerdesin aşkım beklemekteyim.

İçimdeki acı nehri çağıldıyor,

Ayrılığını hergün çekmekteyim.

Sonsuzluk denen zaman yok bu şehirde

Acılar üstüste gelir,beni ezmekte.

Yokluğun oluk oluk kan olmuş akar bedenimde,

Nerdesin hasretinle ölmekteyim.

KIşın soğuk olur derler anlamam,

Benim için her mevsim dondurucu.

Seni unutmak istemesemde,

Unutmam için imza atar herbirgün.

Sevgini içime attım ve gidiyorum,

Artık beklemeye tahammül edemiyorum.

Yok olan ümitler sen ve ben değil anlıyor musun? 

Dönmemek üzere ben gidiyorum.

Tarihte adım yokki namım kalsın,

Belki hatıralarında azda olsa kalacağım.

Ama sen benim ömrümden aldın,

En büyük ve acı hatıra benim için sen kaldın.

Gidiyorum buralardan,sen den uzaklara,

Ateş oldu sevgin içimde bağrım yanmakta.

Ne zaman aşkın söner içimde kalbim anlamamakta.

Gidiyorum aşkım sen sağ kal buralarda.', 'Dışarıda yağmur yağıyor, Nerdesin aşkım beklemekteyim. İçimdeki acı nehri çağıldıyor, Ayrılığını hergün çekmekteyim. Sonsuzluk denen zaman y...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Kurt']::text[], 8.5, '{"poet":"Yasemin Kurt","poet_slug":"yasemin-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidiyorum-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramazsın Yar', 'aramazsin-yar-huseyin-sigirtmac-3p5jg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boşuna arayıp sorma sebebi.

Bu aşkın sırrına eremezsin yar.

Gönül deryasında derin bir debi.

Balinalar yüzer göremezsin yar.

Bu aşkın hikmeti bir efsânedir.

Zahiri görünen can divanedir.

Batıni olanlar hep viranedir.

Şekle bakıp gönül veremezsin yar.

Can gözü görmeyen uzak menzile.

Rahata erilmez çekmeden çile.

Bülbülün nağmesi zevk verir güle.

Ateş olur dalı deremezsin yar.

Bakma Sığırtmaç’ın garip aşkına.

Her güzel mihmandır gönül köşküne.

Geçer gençlik gider döner düşküne.

Belki de unutur aramazsın yar.

Bursa 19/08/2005', 'Boşuna arayıp sorma sebebi. Bu aşkın sırrına eremezsin yar. Gönül deryasında derin bir debi. Balinalar yüzer göremezsin yar. Bu aşkın hikmet...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aramazsin-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay Haline', 'vay-haline-murat-demir-5b70e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dert çekmekle biter derler

Yol yürümekle

Ne dertlerim bitti benim

Ne de yürümem

Katmerlendi gün geçtikçe

İçimde sevda

Ne hasretim bitti benim

Ne de sürünmem

Vay haline deli gönlüm

Çileli başım

Vay haline can yoldaşım

Canım dadaşım

Vay haline iki gözüm

Sırrım, sırdaşım

Ben kimlere ne yaptım ki

Durmaz gözyaşım

Gel olursa hiç boşuna

Yanıp kavrulma

Bu gidişle yolun uzun

Ömürse kısa

Bir gün gibi gelir geçer

Kalan günler de

Unutma ki işin çok zor

Şansa kalmışsa

Vay haline deli gönlüm

Çileli başım

Vay haline can yoldaşım

Yol arkadaşım

Vay haline iki gözüm

Sırrım, sırdaşım

Ben kimlere ne yaptım ki

Durmaz gözyaşım', 'Dert çekmekle biter derler Yol yürümekle Ne dertlerim bitti benim Ne de yürümem Katmerlendi gün geçtikçe İçimde sevda Ne hasretim bitti beni...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/vay-haline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Yaşımı Gözden Ayırdın', 'sen-benim-yasimi-gozden-ayirdin-murat-demir-ulbds', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin sevgin, sevdan yalanmış yalan

bana yaptığını yapmaz mış yılan

Göl varmı ki sularından ayrılan

Sen benim yaşımı gözden ayırdın

Bana sensin derken beni hoş kılan

Bir zaman ben iken vatanın sılan

Dal varmı ki gövdesinden ayrılan

Sen benim canımı candan ayırdın

Garip yüreğime acıyı salan

İçimde çekilmez hasreti kalan

Çöl varmı ki kumlarından ayrılan

Sen benim terimi tenden ayırdın

Varımı yoğumu aldıkça alan

Bağımı bahçemi ettiren talan

Kök varmı ki toprağından ayrılan

Sen benim gönlümü senden ayırdın', 'Senin sevgin, sevdan yalanmış yalan bana yaptığını yapmaz mış yılan Göl varmı ki sularından ayrılan Sen benim yaşımı gözden ayırdın Bana sen...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-benim-yasimi-gozden-ayirdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gıdıklama Ağlarım', 'gidiklama-aglarim-sahin-yilmaz-beu39', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unuttum mutluluk, saadet neydi,

Gıdıklama, dayanamam ağlarım.

Kahkahayla gülmek nasıl bir şeydi? 

Gıdıklama, dayanamam ağlarım.

Irak’ta başıma çuval taktılar,

Kerkük’te kalbime kurşun sıktılar,

Karabağ’da diri diri yaktılar,

Gıdıklama, dayanamam ağlarım.

Filistin’de eziliyor Müslüman,

Vatanında üzülüyor Müslüman,

Küfre karşı büzülüyor Müslüman, 

Gıdıklama, dayanamam ağlarım. 

Gümrük Birliğinde attılar kazık,

Doğuda kan döktü bir kanı bozuk,

Yanına kâr kaldı, yazık çok yazık! 

Gıdıklama, dayanamam ağlarım.

Aşkabat’ta şeyin kurbanı olduk,

Bakü’de, Taşkent’te sınıfta kaldık,

Kıbrıs’ta çok kötü oyuna geldik,

Gıdıklama, dayanamam ağlarım.

Kara günler geçer diye bekledik,

Kol kırıldı, yen içinde sakladık,

Sermayeyi patronlara yükledik,

Gıdıklama, dayanamam ağlarım.', 'Unuttum mutluluk, saadet neydi, Gıdıklama, dayanamam ağlarım. Kahkahayla gülmek nasıl bir şeydi?  Gıdıklama, dayanamam ağlarım. Irak’ta başı...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidiklama-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat! ! !', 'dikkat-mehmet-demir-atmali-myo80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Girerken kavşaklara,

Dikkat et yavşaklara...

Güvenme gevşeklere,

Razı ol şimşeklere...

Bozuk insan çoğaldı,

Yeryüzüne dağıldı...

İnsanım bu değildi; 

Dikkat et köçeklere...

23.8.1994', 'Girerken kavşaklara, Dikkat et yavşaklara... Güvenme gevşeklere, Razı ol şimşeklere... Bozuk insan çoğaldı, Yeryüzüne dağıldı... İnsanım bu ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dikkat-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mirac', 'mirac-makbule-baydaroglu-uc13a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Miracında can bulup arzdan arşa çıkan nur; 

Yalnız sana mahsustur, yalnız sende bulunur.', 'Miracında can bulup arzdan arşa çıkan nur;  Yalnız sana mahsustur, yalnız sende bulunur....', ARRAY['Türk Edebiyatı','Şiir','Makbule Baydaroğlu']::text[], 8.5, '{"poet":"Makbule Baydaroğlu","poet_slug":"makbule-baydaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/mirac-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklar meyhanesi', 'asiklar-meyhanesi-erol-buker-1pym9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşıklar meyhanesinde üç kişi

sen ben ve aşkımız

şarap kokan kadehlerde birleşti dudaklarımız

aşıklar meyhanesinde üç kişi

sen ben ve bitmeyen arzularımız.', 'Aşıklar meyhanesinde üç kişi sen ben ve aşkımız şarap kokan kadehlerde birleşti dudaklarımız aşıklar meyhanesinde üç kişi sen ben ve bitmeye...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asiklar-meyhanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz...', 'caresiz-mehmet-demir-atmali-h10mr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-İlahi

Bir gün gelir vade yeter,

Zaman durur, süre biter...

Bütün dostlar, birlik olsa; 

Kefin sarar, toprak örter...

Bu mezarlık güzel dolu,

Kırılmış kanadı kolu...

Ölüm kurtuluşun yolu; 

Ölüm var, ölümden beter...

Nefis ölümü tadacak,

Aslına rücu edecek...

Bir marifetin var ise; 

Durma kaç, kendini kurtar! ! ! 

6.10.1996', '-İlahi Bir gün gelir vade yeter, Zaman durur, süre biter... Bütün dostlar, birlik olsa;  Kefin sarar, toprak örter... Bu mezarlık güzel dolu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/caresiz-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deliboran', 'bir-deliboran-erol-buker-ma1r5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bugün şiir yazmak istemiyor canım

deniz kenarındada   dolaşmayacağım 

rüzgarda saçlarının savruluşunu

düşünmek bile istemiyorum

gözlerin denizin dibinde şimdi

biten ümitlerim gibi.

Bir gemi olmak istiyorum bugün ben 

demir alıp gitmek buralardan

küsmek tüm limanlara.

Bir balık olsam diyorum şimdi

okyanusun en ıssız köşesinde

yalnız bir balık.

Bir yıldız olsam gökyüzünde 

kaysam gitsem birgün

kimseler  farketmese

bir daha göz kırpmasam sana ayışığında.

Bir nehir olsam şimdi

kabına sığmayan bir nehir

sel olsam göz pınarlarında

yıksam geçtiğim yerleri bir bir.

Bir rüzgar olsam 

bir deliboran..

o benim işte

deliboran

bir çılgın adam! ! 

Deniz olsam taşşam

ateş olsam yaksam 

gözyaşı olsam aksam

vede aşık olsam sana 

uzaktanda olsa 

doya doya  baksam.

Ahh can ahh

ben bugün hiç ben  olmak istemiyorum

ben bugün 

sen olmak istiyorum şeker

anlıyormusun! !', 'bugün şiir yazmak istemiyor canım deniz kenarındada   dolaşmayacağım  rüzgarda saçlarının savruluşunu düşünmek bile istemiyorum gözlerin den...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-deliboran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız gemi', 'vefasiz-gemi-erol-buker-a4yo7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gemi vefasız 

vefasız bu gemi

doğrusu ayıp etti limana

söz vermiş randevusuna gitmemiş

söylentiye göre

okyanusda dalgalarla kırıştırıyormuş

yemin ediyorlar 

martılar görmüş.', 'Bu gemi vefasız  vefasız bu gemi doğrusu ayıp etti limana söz vermiş randevusuna gitmemiş söylentiye göre okyanusda dalgalarla kırıştırıyorm...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vefasiz-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz sevgisi', 'deniz-sevgisi-erol-buker-kl314', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben denizi severim

sariyerde  balıkçıda kafayı çekerken boğaza karşı

dudaklarımda sevda türküleri 

aşığımdır denize.

Ben denizi severim

bodrumda masmavi suların koynunda

yada cok uzak bir ülkede denizci barında 

dans ederken  latin güzelle 

aşığımdır denize. 

Ama ben denizi hiç sevmem 

okyanusun ortasına atılmış bir fındık kabuğu gibi sallanırken

köşe kapmaca oynarken fırtınalarla

hele birde aylarca uzaksam sevdiklerimden

birde özlemişsem deliler gibi

kusura bakmayın ama işte o an bana

hiç sevdiremezsiniz denizi.', 'Ben denizi severim sariyerde  balıkçıda kafayı çekerken boğaza karşı dudaklarımda sevda türküleri  aşığımdır denize. Ben denizi severim bodr...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/deniz-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliveravi', 'deliveravi-akin-akca-yqobs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanıyorum olanca sessiz, bir mavi; 

Ama buna kanmak için fazla lüksü yok.

Bir gömlek daha aşağısına 

oturtup uğraşıyı bereketin; 

üstünde bırakmalı böyle, mavi’yi..

ateşsi kırmızının, bir gömlek. Çünkü,

yine de hayal gücünden alır temelini; 

anlık, şiddetli patlayış dönenceleri:

Hayaldir, onun için mavi bir adım yukarda.

Azameti ise ateşin, yaratıcılığa duacı.

*

Pembede barışmaya 

alışmış bu ikisi; biri su’dan, 

erkek cinsi kaya’dan; volkan dağları’nın biri sürter mağmadan,

Diğeri çalar, 

Buzlu* oluşumlardan.

(Buz’un dağda yüzey* oluşturması aldatmasın; 

Su olunca, o da içe çökerek

ergiyecek ama ateş gibi patlamayacak:

Olanca saf) 

Buzul dağda kuzey ışığı, arşa çıkan; 

Volkanik olanda alev kadarsı, tüten.

Şaşılacak şey, su’dan yapılma kadın’ın

Sırtında yer 

buluyor sönmüş, faalliği arayan –onun 

artık olmuşcasına- Etna.

Ve tescillemekte kendisini

Kürek kemiklerine yapışık -

o da- o buz dağı.

İnce bir vernik:

Doğru tahmin edilmiş,

O kırmızı ve o mavi; 

Renk karışımı,

Bir pembe.

Hepsi de, dalgaların koynunda

barındırılan köpüklerin kanatlarında! 

Bir gömlek daha aşağıda olsa da; 

Deliveravi! çıkması an meselesidir 

an be an, yukarıya, hayallere! 

-

''Deli Mavi Sevdalar'' grubundaki giriş resmi üzerine bir doğaçlama

İkinci bölüm resim üzerineyken, ilk bölüm bir giriş niteliğinde.', 'Sanıyorum olanca sessiz, bir mavi;  Ama buna kanmak için fazla lüksü yok. Bir gömlek daha aşağısına  oturtup uğraşıyı bereketin;  üstünde bı...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/deliveravi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Son', 'gercek-son-erdogan-cam-e7isp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aklım başımda değilki; 

Nedenini bilmiyorum

Ya hiç kimse beni duymuyor,

Yada ben sesimi duyuramıyorum

Ölüm artık amansız bir yol

Alıp başımı gidiyorum

Gidiyorum, bir yanım hüsran bir yanım hicran 

Nereye gittiğimi bilmeden gidiyorum

Yolumun üzerindeki sislerin arasında kayboluyorum

Bir yanımda günahlarım bir yanımda sevaplarım

Yürüyorum, yürüyorum,yürüdüğüm yol bitmiyor

Yolumun üzerindeki yabancı gel biraz uyu diyor

Uykuya yattım uyku karanlık

Uyku değil Tanrım bu bir mezarlık

Şiddetle irkildim gözümü kamaştıran bir aydınlık

Gidiyorum dostlar bana Allah''a ısmarladık

İşte gerçek son işte sinema

Anılar vizyonda yanıyorum geçen zamana

Hatıralar gözlerimde dalıp dalıp izliyorum

Daracık teknemde ben inim inim inliyorum

İşte kaynar kazan işte kızgın ateş

Yanacağım günü bekliyorum

Şimdi değil belki ama bir gün mutlaka

Bende o kazanda yanacağım, 

Yaa! ruhum hazırmısın? Hazırmısın?

sesli dinlemek icin linke tıklayınız 👇👇👇

Hüzün temalı

/

Gerilim temalı

/

Korku temalı

/', 'Aklım başımda değilki;  Nedenini bilmiyorum Ya hiç kimse beni duymuyor, Yada ben sesimi duyuramıyorum Ölüm artık amansız bir yol Alıp başımı...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çam']::text[], 8.5, '{"poet":"Erdoğan Çam","poet_slug":"erdogan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gercek-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin', 'i-zin-umit-demir-yjid5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir çocuk bile

daha az ağlar

benim yanımda

sebebim

yâr orada 

can orada

ben; darda...

                                        

kış mı geçer 

karanlık gecelerde! 

yağmur bile

gösterirken damla damla

âleme korkusunu

yârim orada

canım orada

ben burda; darda...

korkum

anlamsız hecelerde!', 'bir çocuk bile daha az ağlar benim yanımda sebebim yâr orada  can orada ben; darda...                                          kış mı geçer ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/izin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olsan', 'sen-olsan-umit-demir-xpshx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sevdanı gönlüme mühürledim

senden başkası açamasın diye

sen ol istedim rüyalarıma giren

sen ol istedim derdimi dinleyen

kızsa da sesin sen ol istedim

gözlerinle nazlayan

bir evi paylaşsam dedim seninle

otursam, dizlerine koysam başımı

saçlarımı okşayan sen olsan

değiştirsek dünyayı seninle

göstersek sevmeyi bilmeyenlere

sen olsan ağladığımda yanımda

derdime dermanım sen olsan 

unutsam gözlerine bakınca kendimi

deliren ben, delirten sen olsan

hasret kalmasam bir ân bile sana 

yanımda yokken bile içimde sen olsan

bir lokma ekmeği seninle paylaşsam

aynı bardaktan yudumlasak suyu

seninle gülsem, seninle yaşasam

sev desem gönlüme; delicesine sev

seven ben sevilen sen olsan

Elif Demir', 'sevdanı gönlüme mühürledim senden başkası açamasın diye sen ol istedim rüyalarıma giren sen ol istedim derdimi dinleyen kızsa da sesin sen o...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-olsan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Ateşi', 'sevda-atesi-umit-demir-ct8lg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben seni sevdim güzel

sevebilmenin sınırında

sevmenin doruğunda

ve sevginin sonsuzluğunda dolaşırken

seninleydim

seninleydim çünkü sen benim her şeyimdin

seninleydim çünkü ben senindim

gittiğim yolda

sensiz bir ânı ölüme 

eş bilip de sevdim

sevdim çünkü sen benim diğer yarımdın

sevdim çünkü sen benim canımdın

sol yarımı ''çıkar at'' deseler atardım

ama beni dipsiz kuyulara salsalar

seni bırakamazdım

bırakmadım da güzel

bir yavru kuşun 

yuvadan uçmaya çalışırken ki

heyecanı, sevinci ve acemiliğindeydim 

seni severken

ama yine de seni

kendimden de çok sevdim

yuvadan düşme korkum olmadan

kanadımın kırılmasını bile umursamadan

kendimi senin kollarına bıraktım

ben seni, sana güvenerek sevdim

ne de zordur severken güvenmek bilirsin

ama ben seni, gözü kapalı sevdim

ben seni her şeyimle sevdim güzel

ne varsa verebileceğim

ayaklarının altına serdim

kıskanmadan saçımın bir telini bile

sana kendimi feda ettim

senden de beklemedim

yüreğinden gayrı bir karşılık

ve seni yürek coğrafyanda bir karışlık

yere razı olarak sevdim

ben seni nedensiz sevdim güzel

çağlar boyu efsaneleşen 

soylu sevdalar, asil aşklar nasılsa

öyle sevdim

''ol'' dedin, olasıya sevdim

''öl'' dedin, ölesiye sevdim

olmayı ve ölmeyi ben

sende öğrendim

senleyken ''tam'' oldum

sensizken ''bin'' öldüm

sende oldum, sende öldüm

ben, beni sende kaybettim güzel

ben seni şekilsiz sevdim

sığdırmaya çalışırken bir kalıba

birileri sevgisini

ben yıktım da sevdim

sevdamın bentlerini

bıraktım sevgimi azgın bir sel gibi 

sığmadan yatağıma

kendimde nice evleri 

harap ederek sevdim

ben seni, sensizken de sevdim güzel

senle olmanın tadını

yokluğunda dahi alarak sevdim

varlığın ve yokluğun aynıydı benim için

aynıydı seven yüreğim için

sakinliğe bürünmüş engin okyanuslar

aşılmazlıklarıyla mağrur 

sıradağlar bile olsa arada

sen hep yanımdaydın

benim canımdaydın', 'ben seni sevdim güzel sevebilmenin sınırında sevmenin doruğunda ve sevginin sonsuzluğunda dolaşırken seninleydim seninleydim çünkü sen benim...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/sevda-atesi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaktüs Çiçeği', 'kaktus-cicegi-umit-demir-izdc5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'serap, sen de biliyorsun

n'' olursa olsun, sonuna kadar

''seni çok seviyorum''

ama seni görünce de, diyorum ya

aklıma hep çöller geliyor

serap, sen de biliyorsun

seni afrika’da bir çöl kadar 

korkutucu ve sınırsız buluyorum

yüzüne de söyleyemiyorum ya

sensiz bu dünya inan dar geliyor

serap, sen de biliyorsun

yalvarırım naz yapma bu kadar

yoksa ben azar azar ölüyorum

beni sende kaybediyorum ya

yalan değil biraz gönle zor geliyor

serap, sen de biliyorsun

güzelliğin bir kaktüs çiçeği kadar

ama gizle dikenlerini dokunamıyorum

sana sarılmak istiyorum ya

utanıyorum, bu da bana ar geliyor', 'serap, sen de biliyorsun n'' olursa olsun, sonuna kadar ''seni çok seviyorum'' ama seni görünce de, diyorum ya aklıma hep çöller geliyor serap,...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaktus-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbise Giydirme Sevgiye', 'elbise-giydirme-sevgiye-ertugrul-sakar-hpc8x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dert çıplak olmalı

Aşk çıplak

Elbise giydirme sevgiye

Makyaj yapma

Kokun senin kokun kalmalı

Kokmamalı bir marka

Seviyorum dememeliyim

Senin dışında ki hiç bir şeye', 'Dert çıplak olmalı Aşk çıplak Elbise giydirme sevgiye Makyaj yapma Kokun senin kokun kalmalı Kokmamalı bir marka Seviyorum dememeliyim Senin...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/elbise-giydirme-sevgiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim Aşk', 'dort-mevsim-ask-erdogan-cam-leab0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen 

Güneşli bir bahar günü çıkıverdin karşıma

Deli fırtınalar gibi azgın seller gibi geldin

Gelişinle 

Bambaşka baharlar getirdin hayatıma

Çiçekler açtı yüreğimin en derin kuytu köşelerinde

Hoş geldin gülüm, hoş geldin yüreğime...

Ve sıcak bir yaz akşamıydı en ateşli sevdamız

Aşkın büyüsü,kör etmişti bizi,toz pembeydi herşey

Hiç birşey görmüyordu gözümüz

Bir sen vardın birde ben...

Sanki bize kalmıştı koskoca dünya

Tüm şarkılar susmuştu bizim için

Hiç birşey duymuyorduk

Biri yarın kıyamet kopacak dese 

Boş ver bize ne, dünya umrumuzdamı sanki

Sen varsın ya birde ben hikaye gerisi...

Ve hüzünlü bir sonbahar akşamı gidişin

Penceremden,

Kurumuş yaprakların üstüne çiselen,

Yağmuru seyrederken,aldım acı haberi

Attım kendimi sokağa

Koştum deli fırtına, sırılsıklam yağmurlarda

Sen gidiyordun,

Ben gitme kal diyemiyordum

Desem ne çare,

Canımı yakıyordu,dönüşü olmayan gidişin...

Ve soğuk karlı bir kış günü...

Mezarındayım bugün

Sana güller getirdim,en sevdiğin kırmızısından

Karla kaplı mezarına bırakıyorum

Sevgililer günün kutlu olsun,bu güller senin için

Aldırma akan gözyaşlarıma,ağlıyorum için için,

Ağlıyorum sevgilim, ağlıyorum ikimiz için...', 'Sen  Güneşli bir bahar günü çıkıverdin karşıma Deli fırtınalar gibi azgın seller gibi geldin Gelişinle  Bambaşka baharlar getirdin hayatıma ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çam']::text[], 8.5, '{"poet":"Erdoğan Çam","poet_slug":"erdogan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dort-mevsim-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün İstanbul Da Ağlayacak', 'bir-gun-i-stanbul-da-aglayacak-ahmet-nural-ozturk-ti5c7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün de böyle geçsin bakalım

Birgün istanbul da ağlayacak

Tutunamayacaksın onun gözyaşlarında

Ve ummadığın bir anda ben çıkıp geleceğim

Kız kulesinden istanbul''un kucağına

Öpülmemiş dudaklarda

Kahrolacaksın...', 'Bugün de böyle geçsin bakalım Birgün istanbul da ağlayacak Tutunamayacaksın onun gözyaşlarında Ve ummadığın bir anda ben çıkıp geleceğim Kız...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-gun-istanbul-da-aglayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biyografi', 'biyografi-memed-ayaz-r5v2o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''  Ocak ayı imiş. Soğuğu severim

   Tan atıyormuş. Ayaza vurgunlugum o zamandan

   Anadoluda bir yermiş. Memed''likte malumunuz,,

ikimde ak bir bebek gördüm

üçümde kuyruksuz bir kedi

dörtte harfleri söktüm

beşimde mektebe düştüm.

ilki ortası kenarı köşesi

öğrettiler de öğrettiler

otu çöpü

taşı kayayı

dokuyu organı

su havayı

ama ne yazık, bir damlacık eğitmeyi düşünemediler.

kendini eğebilen ağaç görülmüş mü..

okumaya pek küçükken başladım da

yazmaya ne zaman hiç hatırlayamadım.

karaladığım herşeyi yakmak huyumdu. 

mahreme ateşten örülmeliydi duvarlar. 

sonra bir gün ahretliğim zuhur etti kızıllığımın ortasına. 

bölüşme vaktidir ateşi dedi....    böldük.

ben topraktım. o su.

ben kor oldum. o hala su..

anladım ki bildiğim bildirdiğim sadece yalan.

kapadım gözlerimi dünya bitti

açtım gözlerimi bulduğum bıraktığımdan diil di.

saygılarımla efendim.', '''  Ocak ayı imiş. Soğuğu severim    Tan atıyormuş. Ayaza vurgunlugum o zamandan    Anadoluda bir yermiş. Memed''likte malumunuz,, ikimde ak b...', ARRAY['Türk Edebiyatı','Şiir','Memed Ayaz']::text[], 8.5, '{"poet":"Memed Ayaz","poet_slug":"memed-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/biyografi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyalog Masalı!', 'diyalog-masali-saim-bastik-4ycjq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arkadaşlar anlatıyor bir DİYALOG masalı

Diyalog Müslüman''a Vatikan''ın tuzağı.

Bak iftara çağırmışlar PAPAZ eli âsâlı

Diyalog Müslüman''a Vatikan''ın tuzağı.                                                          

Hak din Allah katında bize göre İSLAM''dır

Kâfirle dost olanlar bilmem nasıl insandır

Tanrım hidayet ver de sen bunları uslandır

Diyalog Müslüman''a Vatikan''ın tuzağı.

Adam kabul etmiyor kitabımı dînîmi

Herhalde papaz bana gösterecek yönümü

Fethullah''la Papa mı yıkayacak ölümü

Diyalog Müslüman''a Vatikan''ın tuzağı.

Mektup yazmış PAPA''ya  aciz kulunum diye

Gidince de herhalde şarap verdi hediye

Dînî sulandırınca ne kalacak geriye

Diyalog Müslüman''a Vatikan''ın tuzağı.

Kâfirlere en sınırsız tolerans ve hoşgörü

HİZMET''e  para gelse desteklerler terörü

Dikkat edin bunlara TÜRK''üm demez hiçbiri

Diyalog Müslüman''a Vatikan''ın tuzağı.', 'Arkadaşlar anlatıyor bir DİYALOG masalı Diyalog Müslüman''a Vatikan''ın tuzağı. Bak iftara çağırmışlar PAPAZ eli âsâlı Diyalog Müslüman''a Vati...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/diyalog-masali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümde(Beyit)', 'dusumde-beyit-abdulkadir-karaca-cv9y4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşümde yar gözlerin kovuldu gözlerimden

Bütün dünya tutuştu bu pervasız düşümden

(19.08.2005)', 'Düşümde yar gözlerin kovuldu gözlerimden Bütün dünya tutuştu bu pervasız düşümden (19.08.2005)...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/dusumde-beyit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anafor', 'anafor-cumhur-boratav-n8nxy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1.

(aklından uçmadan çıkarıver o bir çok sesi)

dudağın dudaklara değmeden hissetsin, kokuları almadan

çocukluk zamanından geri gelen elinle bardağı  şerefe kaldırmadan 

saçların, üstünde durdukları kemiği öfkeyle duvara fırlatmadan 

hissetsin

toprak, çıplak ayaklarında hissettiğin

o zamanki ten değil

2.

(duvara karşı kendimi bağırırken buldum)



önce en arka duvar çöktü

arka duvardan bir öndeki önce

en önce daha öndeki önce



(sonrası olmayan bir çığlık ağzımı kapadı)

3.

sana böyle ol diyemem, belki de çaresizimdir ben öyle olduğum için…belki de hissedilmek için senden bu isteğim, belki de olup biteni anladığım için…

sana anlamıyorsun da demeyeceğim huzursuzlanırsın sonra, kendimi tanıyorum

huzursuzluğunu daha da artırmayı denerim sonra…hayır bunu isterim…

(sadece uykunda yanına kıvrılabilmek

sadece bu,

senin üstüne yağan pus

kardeş yapacak bizi

belki de sevgili

terlemiş bir sevişme

dudağına gömdüğüm

pustan öğrendiğim bir gülümseme

oysa dokunamayacağım bile tenine)

4.

yine de sana böyle ol diyemem…belki sen uğuldayansın sadece, ağaçların yaprak uçlarına 

değmekten hoşlanansın, boşluğa açılan kayalıklardan karşılara seslenen, yüksekteki bir kanat çırpışında aşağıya doğru hızla yükselmekten hazlanansın…

(işte elin, yarattığına değdi

gözleri heyecanla açılmış

bir çocuğun

bir serçe kuşuna koşarak uzanan 

elini çizdi)

tavana baktın, beyazdı, çekti seni…gürültünün sesi beyazlaşarak sana kollarımdaki bu et beyaz dedi -evet o beyazdı, puslu bir beyaz-ve anlaşılmayan imgelere boğdun kendini, ve gittin…

5.

oysa bilmiyorsun, ben de bilmiyorum…sadece bir hissedenim…sevdiğim gün ışığı bir anda

kırmızılaşıveriyor yüzünde, artık senden sızan damlaları içemiyorum.. çeperlerinin içinde saklı olan beni sonsuza kadar değiştirecek bir gölge…

bilmiyorum, sadece hissedenim; sana yine de oysa bilmiyorsun diyeceğim…

(oysa bilmiyorsun

kırılgan olan gökyüzü

seninle beraber

döküldü parça parça 

o sana  gömülüyor, 

ben mağaramdaki çiziklerime)

bilmiyorsun, tükenen insanların da farkına varamayacaksın öyleyse, cam kırıkları gibi yere saçılmış olanların…aslında kırık bile değiller, küçük cam parçaları sadece, bunu hissedemeyeceksin öyleyse...düğmeye bastığında ışık gözlerini yine inildiyerek kamaştıracak, perdeler örtünecek seni saklamak için…dışardan yeni ismin seslendiğinde duyamayacaksın öyleyse…

6.

hissediyorum, bir yer bulabilmek için

kaçıyorsun, yüreğin çarpıntının kendisi

her yer senin gölgen, karanlık, 

karanlıksın

kendi içinde neye dönüştüysen

bir yapışkanlık

7.

(bu bir ağıttır sana kaybolduğun için, oysa sadece değişim içindeydi  çizgilerin)

bir eski ya da  bir yeni değilsin', '1. (aklından uçmadan çıkarıver o bir çok sesi) dudağın dudaklara değmeden hissetsin, kokuları almadan çocukluk zamanından geri gelen elinle ...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/anafor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pay Etsek(Beyit)', 'pay-etsek-beyit-abdulkadir-karaca-shjcw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaybetmeyi pay etsek en büyük hisse benim

Kazanmayı paylaşsak pay düşmez cüsse benim

(19.08.2005)', 'Kaybetmeyi pay etsek en büyük hisse benim Kazanmayı paylaşsak pay düşmez cüsse benim (19.08.2005)...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/pay-etsek-beyit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirler Bize Tuzak', 'bu-sehirler-bize-tuzak-kamil-soylemez-0oook', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalk gidelim sevdiğim

Kalk......

Bu kentler bize uzak

Kavuşmamıza bir çok engel

Bir çok tuzak

Kalk........

Sevdamıza pranga,kasap

Yaşamımıza inadına yasak

Kalk gidelim sevdiğim

Kalk.....

Yaylamız olsun,dağlar

Bağrımızda şarkılar

Sevdamız olsun

Kalk....

Bel bağlasın umut çiçekleri

Arılar bal yapsın

Oğul atsın

Koyunlarımız otlasın

Kuzularımız seslensin

Kalk..

Yoğurtlar kaymak tutsun

Yayıkta ayran vursun 

Çocuklarımız toprak

Kalk...

Yürekler serçe 

Cıvıl,cıvıl ötsün

Pınarlar bizim için aksın

Şarkılar bizim için

Kalk gidelim sevdiğim

Kalk...

Bu şehirler bize tuzak

Ömürse bedende yaprak

Bir rüzgar ile yakındır dalından kopacak

Kalk gidelim sevdiğim

Kalk...', 'Kalk gidelim sevdiğim Kalk...... Bu kentler bize uzak Kavuşmamıza bir çok engel Bir çok tuzak Kalk........ Sevdamıza pranga,kasap Yaşamımıza...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bu-sehirler-bize-tuzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsin', 'bilemezsin-akin-dursun-kmpmw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kaç memleket sakladım yüreğimde 

kaç sevdalara yataklık ettim 

bilemezsin sen, 

avuçlarımdan akan ırmakların 

nereye, 

hangi denize döküldüğünü

bilemezsin...

saklımda kaç yalnızlık büyüttüm 

kaç şiiri sensiz ama virgülle bitirdim 

bilemezsin sen, 

elim gitmedi bir türlü 

nokta koymaya 

noktanın ne acı olduğunu 

tahmin bile edemezsin sen...

biliyorum...

şimdi uzaktasın, 

şımarık bir gecenin sabahında

yitip gittin,

haritalardan silinmiş isimsiz bir kente 

bilseydin sevdiğim,

ağladığımda denizlerin nasıl kabardığını 

bilseydin,

noktanın yorulmadan peşimde iz sürdüğünü

koyduğum her virgülden sonra 

gelirdin, yanı başıma 

                                          (20-24.12.2003 / 03:02-00:47)  İzmir', 'kaç memleket sakladım yüreğimde  kaç sevdalara yataklık ettim  bilemezsin sen,  avuçlarımdan akan ırmakların  nereye,  hangi denize döküldüğ...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bilemezsin-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel kız', 'guzel-kiz-murat-erol-mxjej', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Leylası''nı arayan Mecnun degil mi? 

Karanlık içinde bir deli degil mi? 

Bana kara diyen güzel 

Söylesene saçların kara değil mi?', 'Leylası''nı arayan Mecnun degil mi?  Karanlık içinde bir deli degil mi?  Bana kara diyen güzel  Söylesene saçların kara değil mi?...', ARRAY['Türk Edebiyatı','Şiir','Murat Erol']::text[], 8.5, '{"poet":"Murat Erol","poet_slug":"murat-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guzel-kiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tavan Arası Tıkırtıları', 'tavan-arasi-tikirtilari-akin-dursun-ex7m4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1.

çağırıyordu 

gecekondu bacalarından 

yükselen dumanlar 

sokak kedilerini 

tavan arasına 

2.

daha çok ısınıyordu 

yüreğim 

sıcacık odamın 

tavan arasında, 

soğuktan sığınan kedilerin 

tıkırtılarını duyunca 

3.

yakar yakmaz sobayı 

dinmiyordu 

üst kattaki 

gürültücü komşuların 

sesleri

                                                             (31.12.2003 / 05:10)  izmir', '1. çağırıyordu  gecekondu bacalarından  yükselen dumanlar  sokak kedilerini  tavan arasına  2. daha çok ısınıyordu  yüreğim  sıcacık odamın ...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tavan-arasi-tikirtilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlara Sordum Seni Sevdam', 'bulutlara-sordum-seni-sevdam-kamil-soylemez-j0dmu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bulutlara sordum seni

Pencerem önünden geçen bulutlara

Gördünüzmü bitanemi? 

Yok dedi..

Yok..

Sorma

Yolum düşmedi sivas''a

İki damla yaş bıraktı yanağıma

Yolun düşerse unutma

Bitanem var orada

Bir iki damla düşür saçlarına

Bir de öpücük kondur 

Benim yerime

Yanağına

Selam söyle istanbul dan

Kucak dolusu selam

Kızkulesi,Kuzguncuk tan 

Bilirim buna çok sevinecek

Sakın yaş kondurma yanağına

Başını okşa

O beni hissedecek

Ellerimi saçlarında', 'Bulutlara sordum seni Pencerem önünden geçen bulutlara Gördünüzmü bitanemi?  Yok dedi.. Yok.. Sorma Yolum düşmedi sivas''a İki damla yaş bıra...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bulutlara-sordum-seni-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sualim Sana Değil', 'sualim-sana-degil-serap-demirturk-grsx4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi mi, dostluk mu nedir bilemem,

Bazı bazı  bir eksiklik sarar yüreğimi...

Uzakları yakın eden yüreğini ararım,

Ararım da çaresiz bükerim boynumu..

Her ne hal ise yoksun gönül kervanında

Kırılmış kolum kanadım nicedir sensiz

Bir yudum sevgine hasretken böyle

Beni sensiz, beni kimsesiz bırakıverdin.

Sualim sana değil hayatadır bilesin.

Gönlüm arar seni, gözlerim değil.

Adın her geçtiğinde nasılım bilemezsin

Şu karşıki dağlara selamımı diyesin.', 'Sevgi mi, dostluk mu nedir bilemem, Bazı bazı  bir eksiklik sarar yüreğimi... Uzakları yakın eden yüreğini ararım, Ararım da çaresiz bükerim...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sualim-sana-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Öyle İçim Kavrulur', 'bakma-oyle-i-cim-kavrulur-kamil-soylemez-m8kqw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakma öyle ne olur

Bakma aşkım karası

Sevdamın ince uçlu 

Uzun saplı sazı..

Bakma öyle...

Bakma …

İçim kavrulur

Üç günlük ömrümün

Hepsi savrulur

Depremler,tusinamiler

Kıyılarıma vurur

Vururda aklım 

Başım dağılır...

Bakma öyle...

Bakma...

Aklım kaybolur

Ellerim titrer

Dizlerim kıvrılır

Derin mavilerde

Ömrüm 

Ömrüm inan son bulur', 'Bakma öyle ne olur Bakma aşkım karası Sevdamın ince uçlu  Uzun saplı sazı.. Bakma öyle... Bakma … İçim kavrulur Üç günlük ömrümün Hepsi savr...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bakma-oyle-icim-kavrulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-ozgur-celik-ugj29', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gel otur yanıma çocuk

bir uçurtma yapalım seninle

kocaman kuyruklu,

masmavi olsun

yükleyelim sevgiyi sırtına,

salalım gökyüzüne

her yan sevgiyle dolsun

sonra çocuk

bir ağaç dikelim seninle

kökü bilgi,

yaprakları kitap osun

cahilliği silelim yeryüzünden

herkes kendini bilsin

ne dersin?', 'gel otur yanıma çocuk bir uçurtma yapalım seninle kocaman kuyruklu, masmavi olsun yükleyelim sevgiyi sırtına, salalım gökyüzüne her yan sevg...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cagri-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Fısıldasaydın Kulağıma', 'askim-fisildasaydin-kulagima-kamil-soylemez-54e47', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep çocuk kalsaydım

Çocuk kalsaydım sen de

Bilyelerim,uçurtmalarım

Takılsaydı tellere

Ağlasaydım 

Sende bana kıyamayıp,

Sarılsaydın

Bitanem sarılsaydın

Okşasaydın başımı

Gözlerime bakıp, anlasaydın

Dağlar,ormanlar kadar gür

Sana olan aşkımı

Tutup,ellerimden bir köşede

Anlatsaydın aşkımı

Sen Çocuksun,deseseydin

Önce büyüyecek

Sonra küçüleceksin

Deseydin bana

İşte o zaman aşık olurdum sana

Fısıldasaydın kulağıma', 'Hep çocuk kalsaydım Çocuk kalsaydım sen de Bilyelerim,uçurtmalarım Takılsaydı tellere Ağlasaydım  Sende bana kıyamayıp, Sarılsaydın Bitanem ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askim-fisildasaydin-kulagima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadın sınır tanımaz iki farklı yakası', 'i-nadin-sinir-tanimaz-iki-farkli-yakasi-akin-akca-0u04g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle şeyler vardır ki gittiğini demekle gitmez 

Çünkü o istediği ölçütte yaşamı; 

Tam da yaşam verilir ona, o haykır-çağırış’ken tersini: 

Ve düzler açıklanır ama böyle bir inat 

olmayanın inatsı havasına daha bir inatla 

Gördüklerin hayal mi? Hayır, bence hayalgücü. 

Yaratıcı ve bütünleştirmeye başkaldırıcı. 

Denebilir ki, bu anlamda, inat değildir yıkıcı; 

Sırf vatan savunmaya girişken askerler de 

Suçlanamaz ama, ama süngüler suçlanır; 

Akılları vicdan sahibi yüreklerinde olan: 

Yürekle buluşmaya başkaldırabilen,

Elbet olabilir bir vaşak ya da denesi hayvan.

O süngüler ki, yeryüzü gibi bir bilye 

tanesindeki küçük yüzeyleri, koca evrende, 

Askerlerin güdümsüz ellerinden e kendilerinde 

gözü gören at gözlüklü inatlar - 

iki boyutu algılasan ne çıkar özünü 

kaybetmeye- parçalara bölerler.', 'Öyle şeyler vardır ki gittiğini demekle gitmez  Çünkü o istediği ölçütte yaşamı;  Tam da yaşam verilir ona, o haykır-çağırış’ken tersini:  V...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/inadin-sinir-tanimaz-iki-farkli-yakasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Sarhoşluğu', 'hazan-sarhoslugu-feride-ozmat-byjxn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 've destana dönüşür 

terk edişe adanan dizeler 

sözcükler anlamını yitirir yürekte

koklayınca solan manolya misali aşk 

ömrün son demlerinde

özlemlerdir şimdi yüzün iki yanından düşen 

hasretin buruk tadı acıtır son yazda 

heyhat

bir başına kalmaktır yalnızlık 

şafaklar aydınlık olsa da 

bir şiir vurur anılara 

kırgın

yalar geçer kalemi kömür karası poyraz

bense sırılsıklam olmuşum 

kupkuru ırmaklarda

Eksildi Artık Söz 

Sis Yayınları - Nisan 2006

108 sayfa - 5 YTL', 've destana dönüşür  terk edişe adanan dizeler  sözcükler anlamını yitirir yürekte koklayınca solan manolya misali aşk  ömrün son demlerinde ...', ARRAY['Türk Edebiyatı','Şiir','Feride Özmat']::text[], 8.5, '{"poet":"Feride Özmat","poet_slug":"feride-ozmat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hazan-sarhoslugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün,Kendime Bir Gül Verdim...', 'bugun-kendime-bir-gul-verdim-muharrem-cetinkaya-0d6dq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '________-Bugün doğum günüm_kendime ithaf_ımdır…(19 Ağustos) 

Bugün kendime bir gül verdim.

Geçip aynanın karşısına,

Yüzümdeki çizgilere,

Gülümsedim…

Ve

Tüm hayâllerime birer karanfil,

Kendime bir gül verdim…

Yaşadıklarımı düşündüm; 

Dostları,arkadaşları,…..

Gönül bahçemden uçup giden,

Göçmen kuşları.

Dostları,arkadaşları…

Hepsine birer karanfil,

Kendime bir gül verdim.

Anıları gördüm,

Yüzümdeki çizgilerde,

Gurbet yollarını,

Bekleyişleri,

Arayışları,

Vedaları gördüm…

Hasretlerime birer karanfil,

Kendime bir gül verdim…

Kırık dalları,

Solan yaprakları gördüm…

Umut doldu gönlüm,

Körpe fidanları,

Gonca gülleri görünce.

Vefasızlara birer karanfil,

Kendime bir gül verdim…

Her doğan gün,

Bana hediyedir.

Bilirim sevmek yaşamak,

Yaşamak sevmektir.

Bilirim daha çok yolcular uğurlayacağım

Ayrılık limanından,

Ve bilirim daha çok yolcular gelecek…

Tüm gidenlere birer karanfil,

Kendime bir gül verdim…

Utansam da bıyığımdaki aktan,

Gönlüm yorulmaz,

Bıkmaz yaşamaktan.

Gönül bahçemden,

İçimdeki tabiattan,

Bütün insanlara birer karanfil,

Kendime bir gül verdim…

19 Ağustos 2005-Mihalıççık', '________-Bugün doğum günüm_kendime ithaf_ımdır…(19 Ağustos)  Bugün kendime bir gül verdim. Geçip aynanın karşısına, Yüzümdeki çizgilere, Gül...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bugun-kendime-bir-gul-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkürler Yalnızlık..!', 'tesekkurler-yalnizlik-dilek-egri-owbr5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlıkla can ciğer kuzu sarmayız şimdi...

çok olmadı tanışalı

senden sonraydı..

birileri bir yerlere gidiyor benden de

birtek o hep bıraktığım yerde...

.......................................................

külkedisi ocak başında

bense balkon kenarında

ağaçların yalnızlığımla bana çaldığı

rüzgarın kemanıyla eşlik ettiği müziği dinliyorum..

yıldızlar gökyüzüne yaktığım mumlar

her birinde aynı dilek...

***kavuşturun beni***

ay gecenin ispiyoncusu

uzaktan anlamaya çalışıyor ne olup bittiğini,

anlar anlamaz güneşe anlatmak için 

bir çırpıda kaçıyor geceden

ve güneş devralıyor akşamdan kalma mutsuzları..

............merhametli bir rüzgar fısıldıyor güneşin kulağına

....................................yeterince yanmışlar yakma onları!', 'Yalnızlıkla can ciğer kuzu sarmayız şimdi... çok olmadı tanışalı senden sonraydı.. birileri bir yerlere gidiyor benden de birtek o hep bırak...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tesekkurler-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-osman-erdogmus-e7bls', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖZLEDİM

Yine gönlüm dalgalı

Karadeniz’den de beter

Tak etti canıma sensizlik

Gel artık yeter

Etme hayatımı derbeder.

Gel sokayım seni canıma

Canım kurban yoluma

Heves değil ki bu

Bir tutku,kara sevda

Özledim be güzelim

Seni çok özledim.

Dün,kırlara çıktım tek başıma

Dolaştım sorumsuzca

Kuzularla konuştum

Böceklerle dertleştim

Çiçeklerle söyleştim

Seni koklar gibi kokladım 

Kır çiçeklerini.

Özledim be güzelim

Kokunu da özledim.

Sahile indim sensiz

Sıkıntımı dağıtsın diye rüzgarlar

Alsın götürsün diye dalgalar

Ahh be güzelim

Şimdi olman vardı yanımda

Rüzgarda dalgalanan saçların

Dev dalgaların

Kayalara çarpması gibi

Çarpmalıydı omzuma

Vurmalıydı yanağıma

Ellerinde avucumda

Bana en güzel

Aşk teraneleri söylemeliydin

Özledin be güzelim

Sesini de özledim. 

Gece yürüdüm sokaklarda

Biliyor musun? 

Sensiz gecenin de tadı yok

Yıldızlar bana dargın

Ay,bulutların arkasına saklanıyor

Sanki kırgın.

Gündüzümü de ettin gece

Sensiz hayat işkence

Sen yanımda olunca

Hatırımı sorunca

Muhabbetle gülünce

Gülüşünü özledim

Bekliyorum seni

Yüreğimle,sevdamla

Her şeyimle

Gel artık

Özledim be güzelim

Seni çok özledim

Hem de çoook.

Osman Erdoğmuş

Aşk İklimi

Kitabından alınmıştır', 'ÖZLEDİM Yine gönlüm dalgalı Karadeniz’den de beter Tak etti canıma sensizlik Gel artık yeter Etme hayatımı derbeder. Gel sokayım seni canıma...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ozledim-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-i-brahim-kilinc-crj78', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç durulmaz sen dört mevsim çağlarsın

Derdi tutar dertlerine bağlarsın

Gözünde hiç yaş yok, daim ağlarsın

Senin işin her dem âh-u zâr mıdır?', 'Hiç durulmaz sen dört mevsim çağlarsın Derdi tutar dertlerine bağlarsın Gözünde hiç yaş yok, daim ağlarsın Senin işin her dem âh-u zâr mıdır...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sair-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırağan aksamcıları', 'ciragan-aksamcilari-erol-buker-2f5j8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şarap  tütün ve deniz

ne güzel şey seni sevmek! ! 

ismini haykırmak denize karşı

tüm çırağan akşamcılarına

kadeh kaldırtmak şerefine.

eller akşamcı ve yorgun 

eller hasta.

bir sefer bu şarap renkli denizde meçhule

akşamcı kürekler alesta.', 'Şarap  tütün ve deniz ne güzel şey seni sevmek! !  ismini haykırmak denize karşı tüm çırağan akşamcılarına kadeh kaldırtmak şerefine. eller ...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ciragan-aksamcilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Düşlerle Büyüsün Yüreğin', 'ayni-duslerle-buyusun-yuregin-selahattin-yetgin-dl22w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göz pınarlarının coğrafyasında gökler hep mavidir

Seni sevmenin dirençleri ise tutkulu bir özleyiştir 

Resimlerde kalan bir mutluluktur kimi zaman aşk,

Kimi de yaşanılan, yasak mavilerin olduğu bir kenttir..

	Ruhumu okşadığın yerdeyim yine. İçtiğim her yudumda binlerce sözcük okşuyor saçlarımı. Dinlediğim her şarkı dağlıyor yüreğimi. Yıldızlar, ay ve evrenin tüm ışıkları işbirliği yapmış sanki küçüğüm ve söyletiyor bir türlü söyleyemediklerimi. Dışarıda yalan, burada gerçek bir yaşam büyüsü var ve ben galiba yıldızlarla bitmeyecek bir aşk ayinine katılıyorum.

		Sarhoş kelimelerim dile gelmeden gözlerimdeki hayalini çağırdım aşk soframa. Uzaklardan sesini, ellerini ve gözlerini çağırdım, duyarsın diye. Saatler yokluğuna vuracaktı ama ben aldırmıyordum. Şerefine kadeh kaldırırken ben aşka, sen belki de ağlıyordun. Umudum, acım ve öfkem yine yalnızdı anlayacağın. Saatleri kırdım, umudumu orada bıraktım, acımı yarına erteledim, sensizliği de o garip meyhanede bir kadeh içkiye sattım.

	İsterim ki, gecelerin hasret kervanları ipeksi sevgiler taşısın yüreğine. Ruhunun müzikleri duyulsun uzak ormanlarımda. Bir yangın mavisi kaplasın vefalı gönlünün en ulaşılmaz yerlerini. Gözlerin dokunsun şiirlerime, dolaşsın en bilinmez labirentlerini. Gece saçlarının kokusu bölsün düşlerimi. Ansızın içimi sevince boğan çağrılarına tutunarak geleyim  yanıbaşına. Özlemime gem vurayım ve seni yıldız tepesine çağırmak için tanrıdan yeni bir şafak dileyeyim.

	Kendime sarılıp yattığım gecelerde gözlerin düşsün kıyılarıma. Bakışlarının izdüşümlerinde  bakir kuytular arayayım kendime. Soluğun nemlendirsin ormanlarımı, ellerin ısıtsın üşümüş yüreğimi ve aşkın sarsın öksüz kalmış bedenimi. Evet mağrur kelebek, göz pınarlarının coğrafyasında gökler hep mavidir. Seni sevmenin dirençleri ise tutkulu bir özleyiştir. Resimlerde kalan bir mutluluktur kimi zaman aşk, kimi de yaşanılan, yasak mavilerin olduğu bir kenttir..

	Bugün yağmur diledim tanrıdan yüreğime. Ruhumun yangınlarına rüzgar diledim savrulsun sözcüklerim diye. Bugün seni diledim aşk soframa gelip ruhuma lezzet katarsın diye. Bugün bir başka yangınlarda içim, kanıyor ellerim, tutuşuyor sözlerim ve sözlerini özlüyor yalnız yüreğim.

 	Bir gün gelecek kaçıp gidecektin buralardan. Kara talihinin karabasanlarını atlatarak özgür umutlara uçacaktın kelebek. Yüzünün çizgileri gönlümün derinliklerine otak kurmuş kutsal bir yazgı olarak duracak sen bilmesen de. Kilometrelerce öteden ellerine değecek, yüreğine girecek, bu can bu bedende kaldıkça seni seveceğim. Yıllar kahırlı bir şarkı gibi besteledikçe sözlerimi, senin sevginin türkülerini söyleyeceğim.

	Direncinin kapsüllerinin bir gün dağılacağını biliyordum. Günler sonra, sensiz günlerin izini sürerek sana ulaşmak  ve yüreğine yeniden merhaba demek ne güzel bilemezsin. Kendimi, gururumu, direncimi yenemeden yaşamayı da bilemezsin. Mağrur sözlerinle öldürme beni. Ben ten kokunla yaşamaya alışırım. Sen gözümden ırak olabilirsin ama gönlümden asla. Çünkü, seni seni özlemek bile ibadetlerin en güzeli.

	Hayat yolunu yürürken yıldızlı bir gecede ben çıktım karşına. O güne lanet edebilirsin, o günü hiç yaşanmamış sayabilirsin, hatta hatta beni de unutabilirsin. Ama bil ki yolun doğru. Biraz gürültülü olsa da, rotan umudun adresine götürecek seni. Ardına bakma ve mutlu adımlar at. Bir gün, bir yerde, belki de yıldız tepesinde seni  halâ bekliyor olacağım.

 	Resimlerindeki benlerine dokundum bugün parmaklarımla. An gibi, can gibi, nan gibi aklımdasın diyen o şarkıda senin için ağladım. Her lokmada boğazıma düğümlenen hasretini yutmaya çalıştım. Sıcacık nefesini ve ten kokunu aradım gözlerini özleyerek. Seni unutmamak için ettiğim yeminleri tekrarladım yüreğime. Küskün yüreğine diz çöktüm, kırılan gönlünün parça parça kristalleriyle bedenimi doğramak istedim.

	Sınır tanımaz sözcüklerimin girdapları derindir benim. Dağlarım yalçın, denizlerim azgın, yüreğim inadına kırılgandır. Gönlümün ülkeleri uzak, aşklarımı anlamak, o aşklara dalmak tatlı bir tuzaktır. Sen benim yüzyıllara kafa tutacak sözlerime katlanamazdın. Benim sevdalarım yücedir ve cüce sevgileri bilmez. Kaybolan baharlarımı da benden başka hiç kimse anlayamaz. Anlayacağın, insan doğar, büyür ve ölene kadar sever. İstisnalar ise korkunun ayak izleridir.', 'Göz pınarlarının coğrafyasında gökler hep mavidir Seni sevmenin dirençleri ise tutkulu bir özleyiştir  Resimlerde kalan bir mutluluktur kimi...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayni-duslerle-buyusun-yuregin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Panzehir Gülüşlüm', 'panzehir-guluslum-selahattin-yetgin-c5w2b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zülfünü düşürüp benlerine, sevda durağıma gelirsin

Bir yıldız kümesi serpip yüreğime, sevgini verirsin

Dağlar gibi yücedir sevdan, içimde halaya durursun

Panzehir gülüşlüm, sevdikçe ruhumu işgal edersin...

	Gidişinin üzerinden yıldızlar geçti, ay dolunay''a döndü ve ben halâ o rüzgâr tepesinde aşkın parmaklarını okşuyorum. Çığlıkların denizlere düştüğü gecelerde sancılı itiraflarının  üzerinden çok geçmedi sevdalım. Çok olmadı yüreğimden izin isteyip ayrılalı. Kalmanı istediğim, yanımda gözlerime sokulmanı beklediğim o akrep kıskacındaki günlerden geriye, sadece ve sadece yüreğin kaldı.

	Bedenimin delişmen arzularını bir kenara fırlatıp, aynı köşede seni soluduğum günlerden geriye kalan, yüreğimi kor alevlerde bırakan gecelerden arta kalan, sigara izmaritlerine kazıdığımız isimlerimiz, aynı dairede sıkışmışlığımız değil mi? . Biz bu yerküredeki anlamsız kavgalardan uzak, aynı küredeki sevdaya yakın durarak bulduk birbirimizi. Sevinçlerimize sevinç katıp, acılarımızı uçsuz bucaksız evrene bir balona bağlayıp salmadık mı? .

	Gönlüme sürdüğün büyülerden, ruhuma nakşettiğin resimlerden nasıl kaçarım, nasıl ellerinin kutsal ovalarında verimsiz dururum diye sorarım arada bir kendime. Yokluğunun sevda duraklarında gönlümün yara berelerine ben senin panzehir gülüşlerini sürmüşsem, içimin enlem boylarında seni, yalnız seni bulmuşsam bu yüce ovalarda sensiz ne ederim? .

		Birazdan düşüp yollara bana geleceksin hasretim ülkene ulaştığında. Ruhumun buzlarını eritecek gül nefesin. Yüreğimi ısıtacak sözlerin ve avutacak gönlümü ellerin. Birazdan kor karanlığıma ışık olacak kutsal yüreğin. Birazdan sana ibadete duracak, bu yorgun yüreğimin ayinine katılacağım. Yıldız ülkesinden üzerine yıldızlar yağacak, göklerin gözyaşları saçlarına bu yüce evrenin büyüsünü sürecek ve biz oracıkta hiç bitmeyecek bir ayine duracağız.

	Bedenini bağlayan, yüreğini dağlayan intizarlar yolunu da kesmekte bilirim. Seçmekte zorlandığın karmaşık yollara zülfünü düşürüp, tereddütlere sıvarsın minicik yüreğini. Sevgi pusulan gözyaşlarıyla boğulmuş, aklının firari duraklarında isyan çığlıkları atarak geriye dönmüşsün. Seni korkutan, seni binlere bölen bıçkın duruşlarda bile tarayıp çıkmışsın saçını sokaklara. Dinlemezsen yüreğini, bu diyarlar hayın olur, bu şehir yer bitirir seni, yaşlar dolar gözlerine.

	Serçe yüreğin kafes arar telaşlı gün batımlarında. Akşamlara banarak yediğin lokman kuru, anılar sevdana hükümlü, gönlün sabrın tunç kapısı gibi dikilir karşında. Ufuklara saldığın mutluluk uçurtman rüzgârla birlikte şarkı söylemeyi hiç bitirmez ve sen göklere kaldırıp başını tanrıdan mutluluk dilersin. Bazen yaşamını, ilişkilerini bir masaya yatırıp yüreğinin bıçaklarıyla didik didik edersin. Nereden tutarsan tut, ne yaparsan yap asla bitiremeyeceğin bir garip öyküyü sen öylesine yaşarsın.

	Yüreğinin kutsal mahzenlerinde kimsecikler yoktur senden başka. Özgürlüğünü bekler, gözlerini gün ışığına beleyecek günleri özlersin. Kapını sürekli çalan sevdayı içeri hiç almaz, mırıldandığın aşk sözcükleriyle onları kovarsın. Tutkulu bir salıncakta durmadan sallanır, kelime oyunlarıyla dama oynayan dostluklara yanarsın. Söversin kimsesizliğine, bazen de ağlarsın.

	Günler dönecek, belki yıllar geçecek, ama bu aşk ölmeyecek. Mecnun Leyla''sını, Kerem Aslı''sını, Ferhat Şirin''ini yıldızların birinde bulacak elbet. İşte o gün korkularını silerek kollarıma koşacaksın. Çürümüş yüreğimle sana ''Hoş geldin'' diyecek, taptığım yüreğine değecek, ellerini öpecek, gözlerinde eriyecek ve son nefesimde bile seni seviyorum diyerek öleceğim.

	Anlayacağın, yüreğinin bir köşesinde olabilmek için çok şey verirdim. Ne garip şimdi aynı yürekte bir bütün, bir olgun elma olmak için birbirimizi arıyoruz. Ne yazacağını bilememek gibi. Ben sevginin sözcüsüyüm kelebek. Mağrur yüreğinde yerim ne kadarsa o kadar büyürüm, sevgini verdiğin kadar aşkla yoğrulurum, sen olurum.', 'Zülfünü düşürüp benlerine, sevda durağıma gelirsin Bir yıldız kümesi serpip yüreğime, sevgini verirsin Dağlar gibi yücedir sevdan, içimde ha...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/panzehir-guluslum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşım..', 'asim-nurdane-diken-3foat', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ekmeğimsin, aşımsın. 

Aşımdaki, tuzumsun. 

Soframdaki, nimetsin. 

Gönlümün, ilâcısın... 

Aşkımın, nağmesisin. 

Bestemdeki, notamsın. 

Çalarım, mızrabımsın. 

Hüzün dolu, güftemsin... 

Baharım, hazanımsın. 

Yağmurum, rüzgarımsın. 

Bendeki, güzelimsin. 

Sen benim, birtanemsin. 

Gönlümün, sultanısın. 

Bir tanecik, olansın. 

Kaderimsin, yazgımsın. 

Beyaz bir, orkidemsin.....', 'Ekmeğimsin, aşımsın.  Aşımdaki, tuzumsun.  Soframdaki, nimetsin.  Gönlümün, ilâcısın...  Aşkımın, nağmesisin.  Bestemdeki, notamsın.  Çaları...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgârın Tutukludur Yüreğimde..', 'ruzg-rin-tutukludur-yuregimde-selahattin-yetgin-ez9go', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kutsal yüreğine vurgun kelimeler biriktiriyorum günlerdir

Mühürlü bir sevdanın rengârenk gül desteleri var içerimde.

Sen, gecelerin siperlerinde aşkla titreyen mağrur kelebek,

Rüzgâr türkümüzü susturmadan ülkenden çekilmeyeceğim...

	 Bunca yıl seni yazsaydım eğer, ülkemin bütün toprakları yemyeşil olurdu. Sana yıldızlı bir günde rastlamasaydım eğer, bu beden bende olmaz, acıların yoldaşı olurdum. Sevmek acı, seni sevmek acıların atlası şimdi. Ben o atlasta seni buldum ve söylüyorum işte yeryüzünün en güzel ''Seni seviyorum'' sözcüğünü. 

	Şimdi uzan yatağına ve dağıt bedenini sarmalayan tüm acıları. Gözlerini gözlerime dik, ellerini ellerime uzat ve bedenini yıldızlarıma ser. Ruhundaki fırtınalara meydan okuyarak gir düşlerime. Gözlerin açık, ihtirasların bıçkın ve özlemin bir deli kısrak olsun. Ellerin konuşsun, zaman dursun, bedenimiz birbirini bulsun, sonra, isterse kıyamet kopsun.

	Aşkın parmak aralarında terli geceler yaşıyoruz biz. Dudaklarımız ıslaklığı unutsa da yüreğimize yağmur bekliyoruz tanrıdan. İki göktaşı, bir yıldız kayıyor biz birbirimizi beklerken. Yarına göz ucuyla bakarken, dün kaldırım taşları gibi kayıyor ayaklarımızın altından. Geceleri ne sen, ne de ben seviyoruz şimdi mağrur kelebek. Çünkü geceler masum oyunları unutarak bir perdenin arkasından gözyaşı döküyorlar aşkımıza.

	Bazen aklının labirentlerinde kaybolarak seni yıldızlara anlatırım. Aşkının ne kadar süreceğini sorarım  aya. Bakışlarındaki sevgiye kapılınca benim de mağrur çarpar yüreğim, alev alev olur bedenim. Anlamsız tüm sözcüklerime kızar, seni defalarca haketmenin şerefine alkış tutarım. Gecelerin kahır duraklarında bir seni bekler, yalnız senin sesini özlerim.

 	Bütün söylediklerim hayal olsaydı seni sevmekten vazgeçerdim. Senin yüreğinde böyle deli divane kalmaz, kabuğumda ölümü beklerdim. Beni yaşama bağladın kelebek. Alev gözlerinde piştim, geniş yüreğinin ovalarında yetiştim. Ben, seni severek aştım tüm tuzakları. Gün gelecek bu bedende ne kadar kutsal olduğunu anlayacaksın.

	Ay büyümeden uyut beni dizlerinde bebek. Gamzendeki benlerinden olsun ölümüm. Gece gibi sür gözlerini uykularıma. İsterse yüreğimi parçalasın çakal sürüleri. Ben sana dağlardan karamık toplayıp, pırıl pırıl sevgiler sürdüm yüreğine. Kendimden millerce uzakta, sana bir nefes kadar yakındım. Üzünçlü bir bulut dolanıyordu başımda, rüzgâr türkümüzü söylerken.

	Oysa sen, karanlığa alışmış gözlerinle korku resimleri işliyordun gönül tuvaline. Gecenin siperlerinde gözlerin beni ararken binlerce kurşun geçiyordu üzerinden. Direncin emsali olmayan sevgilere sarılı, bakışların sıcak bir temmuz''du. Zaman, suskun bir sözcüktü yüreğimde ve kollarında tüm batık düşlerim yeryüzüne çıkıyordu. Firari oyunlar büyüdükçe aklının zirvelerinde uzakları, çok uzakları düşlüyordun.

	Irmaklar karışınca denizlere, ruhum bir karınca kanadınca küçülünce, yarınımdan umut kesilince, acılarım gönlümden çekilince, bahçende yalnız senin için açmış menekşelere ulaşınca, seni özlemekten vaz geçeceğim. Ne zaman yollarıma bakmayı unutup, özgür düşüncelerinle başbaşa kalıp perdeni sonuna kadar açınca, yüreğindeki güvercinlerle ülkeme mesajlar gönderince, ovalarımdaki tüm asmalar kuruyunca, ateş karanlığına geçince, rüzgâr şarkımızı susturunca ben senin gökyüzünden çekileceğim

	Sensiz suyum yok, aşım, ekmeğim yok. Sensiz şiirim tatsız, kalemim çatlamış binbir yerinden. Sensiz denizlerimden çıkan ağlarım boş, limanlarım uzak gül dudaklım. Yüreğim firari, aklım tutuklu, gönlüm darmadağınık ve acım yıkık kentlerin dayanılmaz ağıtı sanki. Sana özlemim durmadan büyüyor her geçen gün ve sarılıp, tırmanıyor yüreğine arsız sarmaşıklarım.', 'Kutsal yüreğine vurgun kelimeler biriktiriyorum günlerdir Mühürlü bir sevdanın rengârenk gül desteleri var içerimde. Sen, gecelerin siperler...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruzgarin-tutukludur-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Türk Anasıyım...', 'ben-turk-anasiyim-nurdane-diken-wspns', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben sırtında bomba taşıyan, 

Nene Hatun''um. 

Ben sırtında çocuğuyla mermi yapan, 

Emine nineyim. 

Ben yalınayak yollarda, 

Çocuğu sırtında, 

Cepheye mermi taşıyan, 

Kara Fatma''yım. 

Ben cephede yaraları saran, 

Seher''im. 

İsmim ne fark eder, 

Ben Türk anasıyım. 

Türk genlerim. 

Asîl genlerim. 

Modern olduğuma bakmayın. 

Yine mermi taşırım. 

Yine civanların yanında 

Yer alırım. 

Ey! Avrupalıyım diyen, 

Ey! Avrupalı oldum, diyen. 

Bu genlerden korkun. 

''Garb''ın âfâkını sarmışsa çelik zırhlı duvar, 

Benim îman dolu gögsüm gibi, serhad''dim var'' 

Ulusum korkma! 

Böyle iman dolu, serhad''lar 

Dünyayı boğar.... 

Gelsede en modern silahlarla, 

Bizim meşrûk''tan gelen, 

Bir ordumuz var. 

Vatan''ım Türk. 

Benliğim Türk. 

İmanım Türk. 

Türk doğdum. 

Türk öleceğim...... 

''Ne mutlu Türk''üm Diyene....', 'Ben sırtında bomba taşıyan,  Nene Hatun''um.  Ben sırtında çocuğuyla mermi yapan,  Emine nineyim.  Ben yalınayak yollarda,  Çocuğu sırtında, ...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ben-turk-anasiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küskün Giden', 'kuskun-giden-mehmet-bulut-lmq8i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herkesçe hemen anlaşılabilir 

bir politika değildi

hemen anlayamadım...

Önce yokluğuna alıştırdın

sonra aramaz oldun.

Uzun bir aradan sonra

''''uzaklık aşkı öldürüyor'''' dedin

Ve tümden aramaz oldun...

Ancak ben 

yani hep bekleyen 

hala ilk günkü gibi özlüyorum seni

Ama neylersin ki

bir kar topu gibi

avuçlarımda eriyorsun küskün giden....', 'Herkesçe hemen anlaşılabilir  bir politika değildi hemen anlayamadım... Önce yokluğuna alıştırdın sonra aramaz oldun. Uzun bir aradan sonra ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kuskun-giden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Uyarı(!)', 'uyari-erdem-nur-cengiz-dmzgp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimi tutsak etti

Usumun ordusu

Karşı gelemedim (!) 

Bilirsin; 

Komutansız

Savruktur

Sevi erleri...

Mayıs 2005', 'Yüreğimi tutsak etti Usumun ordusu Karşı gelemedim (!)  Bilirsin;  Komutansız Savruktur Sevi erleri... Mayıs 2005...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uyari-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Dünyam....', 'benim-dunyam-nurdane-diken-aqpf7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluluk ülkesidir. 

Bir renk armonisidir. 

Gökkuşağı rengidir. 

Mutluluğun resmidir... 

Özgürlük sınırsızdır. 

Sevgiler sonsuzluktur. 

Huzur iç dünyasıdır. 

Aşk''ların adresidir... 

Dostluğun merkezidir. 

Arkadaş rehberidir. 

Güvenin tam yeridir. 

Huzurun merkezidir... 

Bir çiçek bahçesidir. 

Gül, menekşe, laledir. 

Yıldızlı gökyüzüdür. 

İlâhi bir güftedir... 

Kini, hırsı atmıştır. 

Nefretten azadedir. 

Kıskançlık onda yoktur. 

Dünyam sevgi doludur...', 'Mutluluk ülkesidir.  Bir renk armonisidir.  Gökkuşağı rengidir.  Mutluluğun resmidir...  Özgürlük sınırsızdır.  Sevgiler sonsuzluktur.  Huzu...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benim-dunyam-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-cem-han-jjlis', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gülüşün her tavrın sahteydi,yalandı

Senin bu haline herkes inandı,herkes kandı.

Utanmadın insanların duygularıyla oynamaya,

Daima kararlıydın onlardan faydalanmaya.

Sanma ki bu hayat hep böyle gidecek,

Göreceksin bak bu hayat senin için nasıl bitecek.

Sen acıyla kıvranırken son anında,

İnşallah hiç kimse olmaz o an yanında.

Bütün vücudun kararsın,morarsın,acıyla kıvransın

Yaptığın kötülükler için yüreğin pişmanlıkla sızlasın.

Son pişmanlıkla yalvarsanda Allah''a

Allah büyüktür ama acımaz senin gibi insan''a', 'Her gülüşün her tavrın sahteydi,yalandı Senin bu haline herkes inandı,herkes kandı. Utanmadın insanların duygularıyla oynamaya, Daima kararl...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beddua-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçim Sizin..', 'secim-sizin-omer-golge-r7wjk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıcak gülüşlere hasret

Zifir gecelerin ışıttığı yüz...

Uzak mutluluklar ülkesinin

İşitilmez olmuş senfonileri

Hep yanlışımızı aramaktayız

Kutsal ışık Olimpos''tan çalınalı beri

Biz bu toprağın ırgatları

Ne sahte tanrılar gömmüşüz

Tarihin dipsiz mezarlığına

Ama hep sunulan kendi kanımız...

Çok uluslu silah tüccarlarına...

Bizler aynı güneşin kavurduğu

Yanık tenlerimizle.....

Fıratın,Sakaryanın,Gedizin çocukları

Nasıl yabancılaştık birbirimize...

Ekmeğe ''nan'',suya ''ab'' demiş kimimiz

Bu nasıl zarar verir ki kardeşliğimize

Sabrı serin şerbetlercesine  içirmişiz

Anadolum gibi geniş yüreğimize....

O kocaman kara gölgelerinizle

Alıcı kuşlar gibi dönüp dururken tepemizde..

Bir parça umut,bir dem özgürlük solumak için

Sarılmışız kendi kaderimize

Toprağa can katan,hiç kaybetmemiş....

İri ve nasırlı ellerimizle...

Şimdi iki seçenek var önlerinizde..

Ya alıp gidin! 

Doymak bilmeyen iştahınızı...

Yada kendi leşlerinizi dolduralım..

Helal lokma girmemiş midelerinize.....', 'Sıcak gülüşlere hasret Zifir gecelerin ışıttığı yüz... Uzak mutluluklar ülkesinin İşitilmez olmuş senfonileri Hep yanlışımızı aramaktayız Ku...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/secim-sizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk 2', 'mutluluk-2-mehmet-halil-qwsgp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah güneşinin altında

Krağı gibi hafızam.

beni hedefime götürecek

izler var üzerinde… 

üzerinde izler,

Hızlı davranamazsam

Kaybolup gidecekler.

Yazarken, 

hep sonraya bırakıyorum

yazım kurallarını.

Yazımı 

araç olarak kullanıyorum.

Ben mutluluğun peşindeyim.

Mutluluk,

Ardında gemileri yakarak gidiyor.

yetişmek istiyorum

Silinmeden önümde izler

Yetişmek için koşuyorum.

Sırt sırta, kederle mutluluk

İkisi arasında sıkışıp kalmışım

kederlerim yakamı bırakmadı

mutluluğu ben yakalayamadım.

Dönüp 

bakıyor bana mutluluk 

ben silerken gözlerimi.

Gülüyor,

Ve söylüyor son sözlerini; 

‘’sen yazımı 

nasıl araç olarak kullanıyorsan

ben de kullanıyorum seni

ben kaçmazsam

kim bilir kıymetimi? ’’', 'Sabah güneşinin altında Krağı gibi hafızam. beni hedefime götürecek izler var üzerinde…  üzerinde izler, Hızlı davranamazsam Kaybolup gidece...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/mutluluk-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk kez Böyle Aşık Oldum', 'i-lk-kez-boyle-asik-oldum-ahmet-nural-ozturk-c243s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'usul usul yürüyordu bayazit''ten aksaray''a 

göğsünde istanbul kız lisesi arması 

beyaz kaşkol boynunda 

telaşlıydı

adımları aksaktı 

ama o güne kadar  bana

onun kadar anlamlı 

hiç kimse bakmamıştı

karşıda ben 

yeni başladığım sığarayı ateşlerken

kirpiklerimiz kırpıştı birden

yüreğimi bir yangın kaptı

ama o güne kadar bana

onun kadar anlamlı

hiç kimse bakmamıştı 

kırk yıllık tanıdık gibi

ona uzattım elimi

aksaray''dan döndük yenikapı''ya 

dillerimiz tutuldu konuşmadık küs gibi

ama o güne kadar

onun kadar tutkulu dilli

hiç kimse tutmamıştı elimi

yenikapı sahili boştu

oturduk bir banka

boynundan düştü kaşkolu

heyacanlıydık

dalgalar çıkıyordu omuzlarımıza

değildik ıslandığımızın farkında 

ama o güne kadar

onun kadar seviyle

hiç kimse sarılmamıştı bana

işte böyle aşık oldum ben onaltı yaşında

o kış İstanbul çok soğuktu kimin umurunda 

hiç kimse o kadar büyük tutkuyla

bır daha bakmadı bana..', 'usul usul yürüyordu bayazit''ten aksaray''a  göğsünde istanbul kız lisesi arması  beyaz kaşkol boynunda  telaşlıydı adımları aksaktı  ama o gü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ilk-kez-boyle-asik-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşeklik', 'eseklik-latif-bati-19mz3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen eşekliği kabul edersen eğer,

Elbette birçok kişi üstüne biner.', 'Sen eşekliği kabul edersen eğer, Elbette birçok kişi üstüne biner....', ARRAY['Türk Edebiyatı','Şiir','Latif Batı']::text[], 8.5, '{"poet":"Latif Batı","poet_slug":"latif-bati","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/eseklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım-1', 'anladim-1-mehmet-kiyak-56bff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün bu çaba,

Bütün bu telaş,

Niyeymiş meğer? 

Niyeymiş bu ısrar? 

Ne kadar aceleci,

Ne kadar sabırsızmışım meğer! 

Anladım,

En büyük hatam,

Acele etmekmiş meğer! 

Ne kadar zorlasan da,

İş olacağına varırmış meğer! 

Anladım,

Zaman ilaç,

Sabır insanın,

Sermayesiymiş meğer! 

Anladım,

Her şey para,

Her şey mal mülk değilmiş,

İnsanın gözü değil,

Gönlü doymalıymış meğer! 

Anladım,

En büyük servet,

Şükürmüş meğer! 

Anladım,

İnsan,

Küçük şeylerle de,

Mutlu olurmuş..! 

Anladım,

Hayat sevince,

Güzelmiş meğer! 

(04.03.1992) 

Mehmet KIYAK', 'Bütün bu çaba, Bütün bu telaş, Niyeymiş meğer?  Niyeymiş bu ısrar?  Ne kadar aceleci, Ne kadar sabırsızmışım meğer!  Anladım, En büyük hatam...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kıyak']::text[], 8.5, '{"poet":"Mehmet Kıyak","poet_slug":"mehmet-kiyak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/anladim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baki Kalan Sessizlik', 'baki-kalan-sessizlik-isik-aktas-3r18m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömer ALTAN''a sevgiyle

Tükenmek...

bir taş plağın

çizgilerinde eriyip, biten

iğne gibi...

Bekledim...

Neye yaradı? 

''Bekledim de gelmedin''.

Ağladım...

Bana yaramadı.

''Gözyaşımı silmedim''.

Ve hicran...

''Yine hicran bu aşkın sonu''.

Sense...

''Şimdi uzaklardasın''.

Bense...

''Kimseye etmem şikayet''.

Zaten artık ne fark eder; 

''Dönülmez akşamın ufkundayız''

''Vakit çok geç''.

Beklemek, beklemek,beklemek,

beklemek, beklemek,

beklemek...

Şimdi boşa dönüyor plak...

Ortada baki kaln sessizlik, sensizlik...

Ha, bir de bensizlik...

Tükendim...

Tü

    ken

          dim...

                      02.01.2002 (Gramafon sergisinden esinti)', 'Ömer ALTAN''a sevgiyle Tükenmek... bir taş plağın çizgilerinde eriyip, biten iğne gibi... Bekledim... Neye yaradı?  ''Bekledim de gelmedin''. A...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/baki-kalan-sessizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün üretmek', 'dusun-uretmek-akin-akca-59wx0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanların düşünmeye ihtiyacı var.

Etraf ışıl ışıl, göz görmez kar.

Çok aydınlık, alışık değil herkes.

Düzeltmek lazımsa bunu es geçme:

Herkes sevgi besler, bir aşkı vardır; 

Sever nikbin kırları, sever tek başın tepeleri

Özütlemezsen bunları,

Gerisini ekmezsen sonu talandır.

Yar bir başaktır,

Çoklarınca benimsenilen

ümmetim hadislerinden ama daha çokça

ve hatta sevgi ebedidir.

Çünkü sürükleyen kuvvet,

Kavgalarda bile barışık olmaktır.

İnsan, kılıfa sığmaz; 

Giyinilen entari kendini gösterir en ön.

Bak o şişko, bak şu sıska; 

Ya neden şunun suratı buruşuk? 

Halbuki o kıvrılmalar ve biçimsizlikler

Daha başka şeyleri de gösterir.

Daha derine inildikçe,

Kıyafetin bile muğlak olduğu öğrenilir.

Bu yüzden aşıkken de sevgi önemlidir,

Yine de patlamalar olmadan 

sevgi bir şey değildir sürdürmek için,

ama var ise, sevgi en edimlidir! 

Tıpkı kavganın anatomisi gibidir; 

Var ise vardır, ama

yoksa koca bir hayat bahşeder; 

önceden öngöremediğin yerlere ulaştırır.

İşte bu mevkide, bilmek vardır! 

İnanç, sızmaz kör burada.

Bir anlık gibisindencesine cee’leyerek

Gıdak tutan tavuk-rüzgar gülü horozmuş

Seversen seversin yanında bulduklarını

Uzakta bulduklarından ötedekileri! 

Daha çok öğrenen bilmez çok özümseyen,

Okuluna gitmek lazım gene ancak

Çıkan o bir sancak anca onun ellerince 

Çıkarılacak, sebatla varılacak! 

Tüm bunların ötesinde, işte! 

Kaç üç yüzüncü sefer kalışın bu sessiz? 

İnanmanın tarifi değişmiş ama gene oymuş

Ve/ fakat kalmış sabır denen sabit! ! 

Gnomlarca oynanan Elf kaçıncı Hobbit? 

İnatla, gene de müjde gaipten verecek

İnadın kendin olsun ey başak :)

Ancak dediğim olmasın bu vakurlu tiradın.

Tiyatroda uzun solukludur konuşma 

Ki halk oyunudur o dediğin uzun hava …', 'İnsanların düşünmeye ihtiyacı var. Etraf ışıl ışıl, göz görmez kar. Çok aydınlık, alışık değil herkes. Düzeltmek lazımsa bunu es geçme: Herk...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/dusun-uretmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Bir Yanım Ölüm**', 'bir-yanim-olum-seyhmus-sevilmez-3li9x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Havar! 

Beni anlayan yok mu? 

Çok mu görüldü, içten gelen bir tebessüm, 

Yok mu? şefkatten birkaç sözcük payıma düşen, 

Oysa hiç acımadılar bu cana, 

Ne iştahla içtiler iliklerimi 

Bir bilseniz kana kana.. 

Beni anlayan yokmuş, 

Yokmuş elimi tutacak, 

Bir uçurum kenarından kurtaracak… 

Hep omuzlarıma bindiler 

Beni zayıf düşüren keder bulutları 

Umut olup yağmadılar üstüme… 

Bir yanımda beni iten zulüm, 

Diğer yanımda beni çağıran ölüm.. 

Ensemde hissettiğim Azraillin kanat yelleri 

Anlayamadım ki, bana ”Seni seviyorum(!)   ” diyen dilleri 

Ben mi ateşe attım, sevgiyle suladığım gülleri 

Birde; 

Damarlarımda dolaşan 

Hiddetli bir firari düşünce, 

Cam gibi saydam umutları yumruklayarak yıkan, 

Ben miydim? bileklerimi kanatan… 

Derime saplanan cam parçacıklarından 

Çocuklarımın ağlayışları yansır göz bebeklerime, 

Yarınları görüyorum ağıtlar eşliğinde... 

Bir kararsızlık çizgisinde bekleyip ağlarken emeklerime, 

İp yarışına tutuşmuş ölüm ve kalım, 

Kim kimi çekerse diğer tarafa… 

Cebimdeki bebeğimin resmi son anda çeliyor aklımı 

Geciktim mi? Bilmem…. 

Bir yanımda beni çekiştiren ölüm, 

Diğer yanımda ağlaşan, oğlum ve iki gülüm….. 

Anlamını çözemediğim hayat! 

Kendim için değil, 

Yavrularım için 

Seninle bir kez daha savaşacağım… 

(19.08.2005/Batman)', 'Havar!  Beni anlayan yok mu?  Çok mu görüldü, içten gelen bir tebessüm,  Yok mu? şefkatten birkaç sözcük payıma düşen,  Oysa hiç acımadılar ...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bir-yanim-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enkaz', 'enkaz-isik-aktas-0rs5n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerim,

yetim ellerim,

aşkın dansına hasret,

senin sıcaklığına.

yüreğim,

nasırlaşmış bir soluk.

donmuş kalp atışları...

yaşamak,

miş''li geçmiş bir zaman,

ve belirsiz bir gelecek.

geçmişi eksik,

belirsizliği kelepçeli gerçeğe.

azat olacak mı bilinmez...

gözlerim,

yosun yeşili hüzün,

gözyaşı demek...

...

kimsesiz,

görmeyen gözlerim.

bütün aydınlığa kör

yeşil bir boşluk.

yüreğimden akıyor yaşlarım; 

yeşil,

kırmızı

ve sıcak...

bir varmış-bir yokmuş.

işte hayat! 

                                        19.02.2005/22.15-Şişli', 'Ellerim, yetim ellerim, aşkın dansına hasret, senin sıcaklığına. yüreğim, nasırlaşmış bir soluk. donmuş kalp atışları... yaşamak, miş''li geç...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/enkaz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız Alabora', 'askimiz-alabora-isik-aktas-iz53a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sarhoş bir gemiyim sensiz,

süresiz bir gelgitte

bir o yana, bir bu yana

sallanıp durmaktayım şimdi.

yüzüme vuran her rüzgar sen.

tan yeri ağardığında

ta ki güneş batıp

şafak atana dek oturduğum 

iskelede beklediğim; sevdamız

ve ben,

kara sevdalı avare.

sarhoş bir gemi olarak

ya yelkenlerim delik deşikti,

ya yelken açacak yüreğim yoktu.

her iki halde de sensiz,

yani rüzgarsız kaldım, kalacağım.

yelkenlerin delik deşik olsa da,

yelken açacak yüreğin olmasa da

değilmi ki o denizdesin,

rüzgarsız kalamazsın...

                                          25.08.2000', 'Sarhoş bir gemiyim sensiz, süresiz bir gelgitte bir o yana, bir bu yana sallanıp durmaktayım şimdi. yüzüme vuran her rüzgar sen. tan yeri ağ...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askimiz-alabora-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk/Gizli Bir Aşkın Kısa Ama Açık Tarihi', 'sonsuzluk-gizli-bir-askin-kisa-ama-acik-tarihi-isik-aktas-6azgq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidenlere...

Suların, selleriyle ayrıldığı yerden,

                                          sana senelerce kavuşuyorum.

kavuşmam sen,

ayrılmam sen.

buluştuğumda ayrıldığım yine sen.

sen,

ya süresiz bir yağmursun,

ve ben,

o yağmurun altında ıslak bir ben.

ya taşkın bir selsin,

ki taştığın kıyı benim,

ama ben sen''im...

                                10.03.2002/01.00-Şişli', 'Gidenlere... Suların, selleriyle ayrıldığı yerden,                                           sana senelerce kavuşuyorum. kavuşmam sen, ayrıl...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sonsuzluk-gizli-bir-askin-kisa-ama-acik-tarihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğin kadar', 'sevdigin-kadar-erol-buker-j2etz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiçekler güzeldir

kuşlar özgür

tiramisu tatlı 

sen de tatlı oldugun için sevimlisin.

ama sunu bilki şeker

ne kadar seversen 

işte o kadar sevilirsin

ne bir eksik ne bir fazla

anlıyormusun! !', 'Çiçekler güzeldir kuşlar özgür tiramisu tatlı  sen de tatlı oldugun için sevimlisin. ama sunu bilki şeker ne kadar seversen  işte o kadar se...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdigin-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahmur bağlantı...', 'mahmur-baglanti-omer-faruk-girgin-mlrjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Henüz tanrıyı keşfedememiştim

Oruca niyetli gönül yatağımda

Önce sesinle yürüdün sen

Aslı bilinmeyen bir sözle dudağında

Sonra tek işaretiyle inandım ben ona 

İçine alevli damgasını vurduğu kadınlığında

Nasıl da zevk aldım her şeyinden

Kekeleyen gülüşlerin kıskacında

Belki de sevişme sonrası mahmur bir bağlantıda

Şimdi, morötesi bir günbatımı

Elimde titreyen bir bakır güneş

Dalga dalga yayılan bir sis

Ve neredeyse her şey silinirken

Şimdi nasıl sevmem tanrıyı ben

Denizlere karşı, seni severken ben…', 'Henüz tanrıyı keşfedememiştim Oruca niyetli gönül yatağımda Önce sesinle yürüdün sen Aslı bilinmeyen bir sözle dudağında Sonra tek işaretiyl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mahmur-baglanti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzu', 'arzu-orhan-kutlu-gdye7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gönlüm ara sıra iki laf ister,

İstediğinde size geleyim mi yar.

Yar görünce kollarım sarılmak ister,

Gördüğümde seni sarılayım mı yar.

Derim; 

Geldiğimde size ne güzel zülfün var,

Kız o zülüflerin hep tellenmek ister.

Bakarım ki ne güzel ak gerdanın var,

O güzel gerdanın hep ellenmek ister.

Derim; 

Kara kara güzel sırma saçların var,

Kara sırma saçlar koklanmak ister,

Ateş gib yakan bal dudakların var,

Ateşten dudaklar hep ballanmak ister.

Derim; 

Al al olmuş al yanakların var,

A kız o al yanaklar allanmak ister,

Göğsünde saklı minik goncaların var,

O goncaların çıkıp açılmak ister.

Kutlu Ozanım güzel arzuların var,

Bu arzuya boyun eğecek yar ister,

Güzel çoktur içlerinde arzu da var,

Lakin önce yüzükle bir nikah ister.', 'Bu gönlüm ara sıra iki laf ister, İstediğinde size geleyim mi yar. Yar görünce kollarım sarılmak ister, Gördüğümde seni sarılayım mı yar. De...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/arzu-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendim İçin..!', 'kendim-i-cin-mehmet-kiyak-ci0qi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne şairim,ne yazarım,

Kendimce,bir şeyler yazarım! 

Şair olmak  değil amacım,

Şiir dostlarıyla olmak için buradayım! 

Gezdikçe Antoloji''nin sayfalarını,

Yeni yeni dünyalar keşfederim! 

Gördükçe güzel şiirleri,

Şiir yazmaktan geçerim! 

Hem ne kalmış bana yazacak,

Hepsi yazılmış bir bir,

Ne varsa yazılacak,

Bir bu kalmış bana yazacak,

Ah, ne çok şey var okunacak! 

Ben yazmasam ne çıkar,

Yazan ne güzel yazmış,

Yazana saygı duyarım! 

Girince büyülü etkisine şiirin,

En büyük hazzı duyarım! 

Beni öyle acımasızca eleştirmeyin,

Daha başındayken işin! 

Şiir nasıl yazılır bilirim amma,

İşte bu kadar oluyor anca..! 

Bütün ustalardan af ola! 

Öyle kolay değil şiir yazmak,

Al eline kalemi,

Yaz aklına geleni...? 

Kaç kağıt yırttım,

Kaç kalem kırdım,

Olmadı diye! 

Sonra sordum kendime,

''Bardak dolmadan taşar mı? '' diye! 

...

Yine de olsun,

Yazıyorum işte! 

Yazıyorum,

Bir şeyler,kendimce! 

Yazıyorum; 

Bakarsın bir gün,

Birisi okur diye! 

Bilirim,

Söz uçar,yazı kalır! 

Her şey ölür,

Yalnız anılar kalır! 

Malım mülküm yok benim,

Demesinler ''bir şey bırakmadı''diye,

Hiç değilse benden de,

Birkaç satır kalsın geriye! 

Mehmet Kıyak 

(15,04,05)', 'Ne şairim,ne yazarım, Kendimce,bir şeyler yazarım!  Şair olmak  değil amacım, Şiir dostlarıyla olmak için buradayım!  Gezdikçe Antoloji''nin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kıyak']::text[], 8.5, '{"poet":"Mehmet Kıyak","poet_slug":"mehmet-kiyak","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kendim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslata Özlemdir benim derdim…', 'vuslata-ozlemdir-benim-derdim-muammer-celik-6zc2e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özgür bırakın beni doğamla

çiçekli dallarına konayım

susayınca aşk gölüne

acıkınca gözlerine ineyim...

Özgür bırakın beni kuşlar gibi

ağlayınca omuzuna konayım

söyleyince diline dolanayım

gülünce dudaklarına oturayım...

Kendimi yüreğine gömeyim

özgür bırakın beni, son nefesimde

sevdiğimin kanatlarında öleyim...

BirDeli

19.08.2005', 'Özgür bırakın beni doğamla çiçekli dallarına konayım susayınca aşk gölüne acıkınca gözlerine ineyim... Özgür bırakın beni kuşlar gibi ağlayı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vuslata-ozlemdir-benim-derdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıksız Ölümüm', 'taniksiz-olumum-abdullah-acar-masu2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanıksız bir ölümün ipuçlarındayım

Yakalarım alabildiğine kirli

Biri asılıyor sanki alt dudağımdan

Ağlamamak o kadar zor ki! 

Aman Allahım! Bu bir cinayet! 

Kanıtları bir bir inceliyorum,

Ölen benim yüreğim, evet! 

Öldüren kanlı ellerim...', 'Tanıksız bir ölümün ipuçlarındayım Yakalarım alabildiğine kirli Biri asılıyor sanki alt dudağımdan Ağlamamak o kadar zor ki!  Aman Allahım! ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/taniksiz-olumum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kalır?', 'ne-kalir-mehmet-kiyak-7vw5h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaldır, sevgiyi aradan kaldır,

Söyle o zaman arada ne kalır?', 'Kaldır, sevgiyi aradan kaldır, Söyle o zaman arada ne kalır?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kıyak']::text[], 8.5, '{"poet":"Mehmet Kıyak","poet_slug":"mehmet-kiyak","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ne-kalir-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime deyim ben', 'kime-deyim-ben-i-brahim-kilinc-3ku5o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mızrap dokunmazsa teller inlemez

Seven söyler, sevilenler dinlemez 

Aşk ile yanmayan halden anlamaz

Şimdi âh-u zârım kime deyim ben

Bazen anlatırsam, bazen dinlersem 

Âşıkların aşkı ile inlersem

Ahir-i ömrümde bir gün gülmezsem 

Şimdi âh-u zârım kime deyim ben

Anladım ki bu iş  uzayıp gider 

Her kim ne ederse kendine eder

Her âşığın derdi benden az beter 

Şİmdi âh-u zârım kime deyim ben', 'Mızrap dokunmazsa teller inlemez Seven söyler, sevilenler dinlemez  Aşk ile yanmayan halden anlamaz Şimdi âh-u zârım kime deyim ben Bazen an...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kime-deyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Çam Yaprağında (Destan)', 'cam-yapraginda-destan-cihan-kaya-oqcdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '____________________________Şehitlerinize

Bir destan yazılır, yurdun bağrında

Dalgalanır durur hemen sağrında

Bir bayrak süzülür yürek ağrında

Hüznün parelenir çam yaprağında...

İşlenir hücrene, son bulur ezber

Nefesle haykırır, canlanır makber

Duyarsın kubbede, Allah-u ekber

Yüreğin harelenir çam yaprağında...

Ana kucağında, ekilir fidan

Asker ocağında, verilir ferman

Kırkına gelince edilmez, aman! 

Düşmanın asılır, çam yaprağında...

Bir kudret gürünür, bayrak alında

Yaralar bağlanır, yarin şalında

Hayat var bir kase tatlı balında

Fermanın basılır, çam yaprağında...

Ölümsüzlük başlar, vatan yolunda

İman gücü gelir, kellen kolunda

Gülümser Azrail, durur solunda

Kılıcın bilenir, çam yaprağında...

Boşuna desen de, “Ağlama ana”

Ağlar tüm analar, dualar sana

Vatanım uğrunda tek damla kana

Bir ülke dilenir, çam yaprağında...

Git düşünme bizi, bekler Peygamber

Ölümü tatmak var, nerde Nekir-Münker

Şehitsin olmaz ki ruha seferber

Vatanım şanlanır, çam yaprağında...

Cihan demez işte, “Ölür şehitler...”

Kan damlar kalemden, ağlar beyitler

Kuyruğuna bastım uluyor itler

Kalemim canlanır, çam yaprağında...', '____________________________Şehitlerinize Bir destan yazılır, yurdun bağrında Dalgalanır durur hemen sağrında Bir bayrak süzülür yürek ağrın...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cam-yapraginda-destan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deruni Hasbıhal -4-', 'deruni-hasbihal-4-zulfikar-yapar-kaleli-gwprx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' 

Hasret göze, hüzün gönle, sis dağa 

Ay gölgemin gölgesine sığınır...

Akşam tana, sır sendeki şafağa 

Ya bu aymaz gün nesine sığınır...

Gönül perim, şahım, perişan halım

Artık ne sürgünüm, ne de var dalım

Gayri hem sevgilim, hem de  sevdalım 

Şiir senin nefesine sığınır...

Bulutları dilim dilim dilerim

Gökyüzünden yıldızları elerim

Aklım, fikrim, zikrim, ifadelerim

Alemin en bilgesine sığınır...

Sırdaşın dileği, erinin sırrı

Sözün gizlendiği yerinin sırrı

Birinin kederi, birinin sırrı

Gönlün mahrem bölgesine sığınır...

Sözcükte tamamlar hece ömrünü

Şarlatanca yaşar cüce ömrünü

Yarıladığında gece ömrünü

Hasret hüznün tok sesine sığınır...

* Kaleli''yle Hasbıhâl - 4 *

Gönül yangın yemiş, tulumbacı yok! 

Hekim desen, hekim benden de hasta! 

Bir beyaz kaftandır kefen, tacı yok, 

Gezerim sırtımda, umudum yasta! .. 

Düşünüp düşünüp kendimi yerim, 

Bir devâ ararım, Yaradan Kerim... 

Lâkin şimdi bunu burada derim; 

Bir sabah Şehriye''m kalacak tasta! .. 

Böyleyken ahvâlim, sitem edersin, 

İnkâr yok, pek fayda veriyor dersin... 

Yalnız bir fikrim var, bilmem, ne dersin? 

Kısa bir teneffüs verelim usta... 

Kaleli Usta''nın bu şiire yazdığı cevap 

Özel Sayfam 

Abdulkadir Öğdüm', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''  Hasret göze, hüzün gönle, sis dağa  Ay gölgemin gölgesine sığınır... Akşam tana, sır sen...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/deruni-hasbihal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkınızı Helal Edin', 'hakkinizi-helal-edin-abdullah-acar-3wsf0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uçan kuşlar, kelebekler 

Hakkınizı helal edin 

Kundaktaki bebekler 

Hakkınizı helal edin 

Yerde yürüyen karınca, 

Sokakta görduğüm amca 

Hakkınız var kanımca 

Hakkınızı helal edin 

Kopardigim çiçekler 

Siz kovdugum böcekler 

Boyu benden küçükler 

Hakkınızı helal edin 

Dostlarim, gardaşlarım 

Ben kendimi taşlarım 

Dursun şu gözyaşlarim 

Hakkınizı helal edin 

Ahmet, Mehmet, Ali beyler 

Bu can kalkti göç eyler 

Hakkınız varsa neyler 

Hakkınızı  helal edin 

Annem, babam, yarenim

Bacılarım Kardeşlerim

Hakkınızı nasıl öderim

Hakkınızı  helal edin 

Bosyere gonullendim 

Gurur ettim, bilendim 

Kendime sinirlendim 

Hakkınızı helal edin 

Sözünüz özünüz bal olsun 

Kaseniz hikmetle dolsun 

Benden yana helal olsun 

Hakkınızı helal edin 

31 Haziran 2002 (Urbana, IL,USA)', 'Uçan kuşlar, kelebekler  Hakkınizı helal edin  Kundaktaki bebekler  Hakkınizı helal edin  Yerde yürüyen karınca,  Sokakta görduğüm amca  Hak...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hakkinizi-helal-edin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-oguz-duzgun-arepi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi...

Şimdi sev beni seveceksen

Şimdi...

Şimdi gül bana güleceksen

Ne bir saniye,

Ne de bir gün sonra

Şimdi...

Şimdi gel bana geleceksen', 'Şimdi... Şimdi sev beni seveceksen Şimdi... Şimdi gül bana güleceksen Ne bir saniye, Ne de bir gün sonra Şimdi... Şimdi gel bana geleceksen...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/simdi-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün Son Anahtarı', 'omrumun-son-anahtari-kamil-soylemez-pvbn4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ömrümün son anahtarı..

Tüm kapılar sana açılırken

Bana kapalı..! 

Kaldırım taşları kucaklar beni

Bir de istanbul sokakları

Sen yoksun ya..

Fotoğrafın da yasaklı..! 

Ben yandım bu gidişle

Yokluğun eşliğinde

Her yanımı kışlar sardı

Ve yüreğim beklemelerde

Dantel işlemeli ahşap evlerden

Çıkıverecekmiş gibisin sokak ucuma

Ne çare gözlerim ihanetler peşinde

Dökerken arpacıkları içime

Göremem seni

Vermez ankara sokakları

Ahşap evler seyrederken beni

Suratlar asık

Nice aşıklar geldi geçti

Kanatma eski yaralarımı der gibi

Kuzguncukta kavlağan ağaçları

Hatıralarımı sakladığım

Bir de eskici dükkanı

İnce ruhlu meleğim

Avuçlarımda bir kalp

Tutmasam uçacak sana

Tutarmısın salsam

Ankara sokaklarından

Haydi şimdi söyle bana', 'Ömrümün son anahtarı.. Tüm kapılar sana açılırken Bana kapalı..!  Kaldırım taşları kucaklar beni Bir de istanbul sokakları Sen yoksun ya.. F...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/omrumun-son-anahtari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Yaprak', 'sari-yaprak-oguz-duzgun-r8em4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi düştü bir yaprak sapsarı

Hazan da değil mevsim, bahar da değil

Yarın kalabalık gelecek endişelerle

Sense sapsarı bir yaprağa tırmanmadasın

Bir evren sanmadasın kıvrımlarını

Tırtıldan ne farkın kalır sürünürsen

Kurumuş bir yaprakta

Ne farkın kalır eşk-i hun dökersen

Yas tutan matemcilerden

Varsın hazan olsun, 

Varsın ''cogito ergo sum'' dememişsin

Varsın o yar hiç olmamış

Varsın kainat da sönüversin gözlerinde

Hazan da değil mevsim bahar da

Tırtıldan ne farkın kalır sürünürsen

Kurumuş bir yaprakta', 'Şimdi düştü bir yaprak sapsarı Hazan da değil mevsim, bahar da değil Yarın kalabalık gelecek endişelerle Sense sapsarı bir yaprağa tırmanmad...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sari-yaprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takvimlerde Acımasız', 'takvimlerde-acimasiz-kamil-soylemez-ftpyd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak geldim bitanem 

Geldim, kovsan da geldim kapına

Aşkımız için dilenip,yalvarmaya

Ne olursun ver elini

Geçmeden zaman ver

Takvimler de acımasız

Saatler, yılbaşılar da

Sessizce geçiyor içimizi acıta acıta

Dönüp bir bak istersen

Giden yılların ardı sıra

Kırarmış saçlar ve bir yığın özlem 

Bakmıyormu sana bana

Haydi ver elini bitanem ver

Özlemler bizi tüketmeden

Biz tüketelim zamanı', 'Bak geldim bitanem  Geldim, kovsan da geldim kapına Aşkımız için dilenip,yalvarmaya Ne olursun ver elini Geçmeden zaman ver Takvimler de acı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/takvimlerde-acimasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin Yaşam Yoldaşım!', 'hosgeldin-yasam-yoldasim-erdem-nur-cengiz-lp9df', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Köhne inançlarla

Aldanışım 

Riya kokan başlangıçlara,

Arkası; 

Döne döne isyanlar 

Ve dinginliğe susamış

Tükenmez sandığım

Yürek çarpıntılarımı saklayan,

Yapay gülümseyişlerim aşka

Sona erdiniz...-



''O'' geldi,

Üç harfe sığan adını

Duraksamaksızın

Yazdı gönlüme.



Tutkunun ardından

Göz kırptı gençliğim

Ki ondandır atımlarındaki hızı

Yüreğimin

-Sunduğu baharla nergisler açtı ruhumda-



Güvençtir gizil adı, 

Sırtımı döndüğümde sarılanım

Yalansızlığına kurban olayım...

İncitmeyenim,

Paylaşanım,

Evimin eri

Üç meleğimin dayanağı

Kucağında avutanım.

Hoşgeldin sevgi,

Hoşgeldin umut,

Hoşgeldin yaşam yoldaşım...

Seninle birlikte

Bir ömür

Her tür savaşıma varım...', '-Köhne inançlarla Aldanışım  Riya kokan başlangıçlara, Arkası;  Döne döne isyanlar  Ve dinginliğe susamış Tükenmez sandığım Yürek çarpıntıla...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hosgeldin-yasam-yoldasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle oynarmısın?', 'benimle-oynarmisin-neslihan-i-sler-anpaz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün canım kuralları olan bir oyun oynamak istedi...

Sen geldin aklıma sevgili...

Bir önceki oyunu da  yarım bırakmıştık aslında,

Sonkez oynamaya ne dersin....

Bakarsın bizimde sonu olan bir oynumuz olur bu dünyada,,,

Bir çember çizecegiz etrafı gülbahçesi,

Sen gözlerini bağlayacaksın ve çemberi aşmadan

Sana diktiğim o dikeni olmayan tek gülü bulacaksın,,,

Oyunbozanlık yok ama,,, lütfen kuralına göre oyna

Birkez yapmıştın bunu aslında gözlerin açık,,,

Ama yüreğin kapalı sevdaya...

O yüzden kuralları değiştirdim bu defa

Tersden oynayacağız oyunu son defa...

Sen sadece gözlerini kapatacak yüreğini açacaksın,,,

Ve sana ait tek gülünü bulacaksın 

Ruhun güle bağlı, gülün ömrü sana,,,', 'Bugün canım kuralları olan bir oyun oynamak istedi... Sen geldin aklıma sevgili... Bir önceki oyunu da  yarım bırakmıştık aslında, Sonkez oy...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benimle-oynarmisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Kuş Ölmeli Aşk İçin', 'kac-kus-olmeli-ask-i-cin-kamil-soylemez-rfgc0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç kış geçmeli,yüreğimin üstünden

Kaç kış.? 

Isınmak için yeniden 

Kaç bahar geçmeli

Özlemin üstünden

Kavuşmak için sana

Kaç serçe ölmeli,yuvada

Daha açmamış iken gözlerini hayata

Kaç kuş yavru kalmalı 

Kaç takla atmalı yürek

Vuslatın üstünden

Kavuşmak için sana

Kaç papatya açmalı 

Sevda ormanların da

Sararıp,solmadan 

Kaç bahar beklemeli ömür

Tutuşmuşken  sana

Kaç gül dökmeli yüreğim gözlerinden

Başın üstüne

Haydi söyle bitanem

Bu adam ne yapmalı 

Yanar ken kızgın fırınlarda sana', 'Kaç kış geçmeli,yüreğimin üstünden Kaç kış.?  Isınmak için yeniden  Kaç bahar geçmeli Özlemin üstünden Kavuşmak için sana Kaç serçe ölmeli,y...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kac-kus-olmeli-ask-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Olurdu', 'ne-guzel-olurdu-oguz-duzgun-7dxya', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Serin serin esen nefesin yok şimdi

Şu sıcakta ne de güzel olurdu

Nefesini hissetmek

Ellerimi tutan ellerin yok şimdi

Ne de yumuşak olurdu

Hayatın balyoz saniyeleri

Ellerin olsaydı

O gülen gözlerin yok şimdi

Bahar da yok, sabah da, sevinç de

Ne düğün yapardı kainat

Bir gülücük atıverseydin

O siyah saçların yok şimdi

Çiçeklerle avunmaktayım

Ne güzel olurdu cennetim

Şimdi yanında olsaydım', 'Serin serin esen nefesin yok şimdi Şu sıcakta ne de güzel olurdu Nefesini hissetmek Ellerimi tutan ellerin yok şimdi Ne de yumuşak olurdu Ha...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-guzel-olurdu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecmis Zamanin Gecmemis $iirleri 1', 'gecmis-zamanin-gecmemis-iirleri-1-huseyin-avdic-udx9n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geometrik inanc

Ey BiRBiRiM oy BiRBiRiM

Sen DOGRUSUN ben egriyim

Hersey sIfIr Sen BiRBiRSiN

Sen DOGRUSUN ben egriyim

Ey BiRGENiM oy BiRGENiM

Sen VARGENSiN ben yokgenim

Hersey sIfIr Sen BiRBiRSiN

Sen HEPGENSiN ben hicgenim 

Bati Berlin, 1980-85.', 'Geometrik inanc Ey BiRBiRiM oy BiRBiRiM Sen DOGRUSUN ben egriyim Hersey sIfIr Sen BiRBiRSiN Sen DOGRUSUN ben egriyim Ey BiRGENiM oy BiRGENiM...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gecmis-zamanin-gecmemis-iirleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kaldı', 'yarim-kaldi-adem-tetik-rizue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aslında senin gidişin ölümüydü yar

Yüreğimde ki tüm güzelliklerin  söylemiştim ya sana

Ben senin gidişine hiç ağlamadım desem inan

Benim haykırışlarım yakarışlarım yüreğimde ki delikalıya

Hani bir kaza sonuçu feda etti ya umutlarını senin uğruna

İster ağla yavrum istersen hep gül

O delikanlı uğrunda öldü gittiğin o gün

Şimdi en kazı var hala yüreğimde

Acılar sarmış yüreği şimdi dertlerin deryalarında

Acıtmıyor canımı artık sevdiğimin gidişi 

Mahsum yüreğimle son defa ağladım ya dün

Hani gömerken senden ayrıldıktan sonra mezara

O yüreğine hasta olduğum delikanlıyla ağladım son defa', 'Aslında senin gidişin ölümüydü yar Yüreğimde ki tüm güzelliklerin  söylemiştim ya sana Ben senin gidişine hiç ağlamadım desem inan Benim hay...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yarim-kaldi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Gözüm Vardı Birini Sağ Birini Sol Omzuna Taktım', 'i-ki-gozum-vardi-birini-sag-birini-sol-omzuna-taktim-kamil-soylemez-9ulll', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen giderken

Ardın sıra bir çift göz bıraktım

Birini sağ birini sol omzuna taktım

Kalbimi yaktım bir şamdanda

Yollarına taktım

Geri dönüp,dönüp baktığında

Çöllerde kaktüslere taktın

Canım yaktın bitanem

Hem de çok yaktın

Şimdi çok uzaksın

Bir o kadarda yakın

Sen giderken iki gözüm vadı

Birini sağ,birini sol omuzuna taktım

Şimdi kör  bir adam

Ardın sıra bıraktığın', 'Sen giderken Ardın sıra bir çift göz bıraktım Birini sağ birini sol omzuna taktım Kalbimi yaktım bir şamdanda Yollarına taktım Geri dönüp,dö...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/iki-gozum-vardi-birini-sag-birini-sol-omzuna-taktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SORMA BANA HHANGİ ''aşk''', 'sorma-bana-hhangi-ask-cennet-sengul-m5po2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sorma Bana ''Hangi Aşk'' Diye 

Aşk…

Namlusu kalbime doğrulmuş…

Tetikte bekler…

Barut değil, gül kokusudur sızan…

Ya Rabbim! …

Senin sevdiğindir sevgilim…

Düşmanın; düşmanım! 

Bu, benim inancım…

Ve aşkım…

“Yaratılanı sevmek; Yaratandan ötürü…”

Sevebilmek…

Sevgiyi Yaratandan ötürü…

Derviş; aşk adamı…

Dergah; aşkhane…

İbadet; sevgiliye muhabbet…

Su nasıl kaynar gönül ateşiyle? …

Çiçeklerin zikri nasıldır ve kimler duyar? 

Ve Ferhat’ın dağları erittiği ateş, Şirin’in aşkından ibaret midir? 

Sorma bana “Hangi aşk? ” diye…

Ve aşktan korkma! 

Bir göz açıp kapayıncaya kadarsa ömür…

Aşk sonsuz olmalı…

“Aşk nasıl sonsuz olur? ”

Bunu sormalı…

Aşk…', 'Sorma Bana ''Hangi Aşk'' Diye  Aşk… Namlusu kalbime doğrulmuş… Tetikte bekler… Barut değil, gül kokusudur sızan… Ya Rabbim! … Senin sevdiğindi...', ARRAY['Türk Edebiyatı','Şiir','Cennet Şengül']::text[], 8.5, '{"poet":"Cennet Şengül","poet_slug":"cennet-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sorma-bana-hhangi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Böyle Sevdim', 'ben-seni-boyle-sevdim-sair-mertcan-4eic9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani olurda bi gün iki adımının arasında kalırsa ayakların

Kalbine yakın olanına at adımını 

Bil ki aşktır dolayan ayağına ayağını

Ağlama ve dönme bir daha ardıma ardını 

Unutma; kalan, bırakır aslında gitmeyen yanını

Sen aşka dair adımlar at

Ben sensiz de avuturum içimin ağlayan yanını', 'Hani olurda bi gün iki adımının arasında kalırsa ayakların Kalbine yakın olanına at adımını  Bil ki aşktır dolayan ayağına ayağını Ağlama ve...', ARRAY['Türk Edebiyatı','Şiir','Şair Mertcan']::text[], 8.5, '{"poet":"Şair Mertcan","poet_slug":"sair-mertcan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-seni-boyle-sevdim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-sair-mertcan-c75v3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana göz yaşları bırakıyorum ardımda avuçlar dolusu; 

Yüzümde sahte gülümsemeler...

Ve bağlıyorum ellerimi giderken ellerine! 

Söyleyemediğim her sözü sana vasiyet ediyorum,

Yitik bi aşktan bolca hoşçakallar umuyorum senin için.

Hayat neyi esirgediyse bizden hepsini alıp götürüyorum,

Geride sana bir ömre sığdıracağın garip bir çift söz bırakıyorum...

'' Ya her şeyim ol;  ya da hiç bi şeyim''', 'Sana göz yaşları bırakıyorum ardımda avuçlar dolusu;  Yüzümde sahte gülümsemeler... Ve bağlıyorum ellerimi giderken ellerine!  Söyleyemediği...', ARRAY['Türk Edebiyatı','Şiir','Şair Mertcan']::text[], 8.5, '{"poet":"Şair Mertcan","poet_slug":"sair-mertcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumartesi', 'cumartesi-bilal-bavli-s55k2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün cumartesi

Ödünç aldığım bütün aşkları iade ettim

Hepsini kullanmadım üstelik

Bir çoğu bir beden büyük geliyordu

Sonraya bıkraktıklarım hep sonrada kaldı

Eskileri unuttum

Kim bilir? 

Nerde? 

Nasıl? 

Kiminle yaşandı? 

Bu gün cumartesi

Ve bu şehir eskisinden daha yalancı...', 'Bu gün cumartesi Ödünç aldığım bütün aşkları iade ettim Hepsini kullanmadım üstelik Bir çoğu bir beden büyük geliyordu Sonraya bıkraktıkları...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bavli']::text[], 8.5, '{"poet":"Bilal Bavli","poet_slug":"bilal-bavli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cumartesi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gir Gönül Sarayıma', 'gel-gir-gonul-sarayima-abdurrahman-tepe-mahd7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel gir gönül sarayıma

Ne hoş tatlı civanlar var

Cehalet zıttır kanıma

Ülküm de ne cananlar var

Sermayem bilgiyle vakar

Bir ahım cihanı yakar

Sevgim fırat olmuş akar

Daha nice ummanlar var

Yüküm muhabbet dostluktur

Çektiğimiz hasretliktir

Meşrebimiz dürüstlüktür

Bizi cahil sananlar var

Gel ahtına çok sadak ol

Dost bağında dal budak ol

Vefan varsa gel adak ol

Gör ki nice kurbanlar var

İyi düşün sonra konuş

İlim erbabıyla tanış

Dilersen irfana karış

Aşk oduna yananlar var

Can canan''çün olsa turap

Ram olur o yüce çalap

Zail olur gam ızdırap

SAMİHİ ne inamlar var', 'Gel gir gönül sarayıma Ne hoş tatlı civanlar var Cehalet zıttır kanıma Ülküm de ne cananlar var Sermayem bilgiyle vakar Bir ahım cihanı yaka...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gel-gir-gonul-sarayima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur.?', 'ne-olur-adem-tetik-evszn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi ulan çek silahını sıkıver kafama

Ölüm korkutmaz bayramdır kan ağlayan sol yanıma

Tövbe etipte gelme istemem uzakta kal ne olur

Ben razıyım senden uzaklarda hergün ağlamaya 

Elimden kadehim düşmese ne olur..? 

Gözümde  yaşlar hep aksada olur..? 

Sen gelmede canım bu beden bir avuç toprak olsada olur

Gelme artık yeter yeter ne olur 

Ne duam olursun artık bu zamandan sonra nede beduam 

Bilirmisin şimdi gönlümde  hep hicran hep hicran

Mevsimler yalan olmuş  gönlümde her zaman hazan

Gelme ne olur vicdansız sevdaların hep yalan 

                                                             Hep yalan......', 'Hadi ulan çek silahını sıkıver kafama Ölüm korkutmaz bayramdır kan ağlayan sol yanıma Tövbe etipte gelme istemem uzakta kal ne olur Ben razı...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-olur-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anka', 'anka-nalan-kazazoglu-zwrjo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçtik kuş uçuşu nice menzilden

Çoktan ayrıldık gönüllerden...

Çok sonra görüşmüşken

Gülümser hikayeler aradım geçmişten..

İşbu kaçık yüreği kırık buldum her yerinden

Anka kuşu masalına inanmam zaten ben...', 'Geçtik kuş uçuşu nice menzilden Çoktan ayrıldık gönüllerden... Çok sonra görüşmüşken Gülümser hikayeler aradım geçmişten.. İşbu kaçık yüreği...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anka-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebedi Menzile Doğru', 'ebedi-menzile-dogru-abdurrahman-tepe-pxpkv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldik işte gidiyoruz

Ebedi menzile doğru

Gece gündüz yürüyoruz

Ebedi menzile doğru

Yükledik biz yükümüzü

Hakka döndük yönümüzü

Çevirelim yüzümüzü

Ebedi menzile doğru

Yazılınca fermanımız

Haktan ola dermanımız

Kalktı gider kervanımız

Ebedi menzile doğru

Kuran SAMİHİ''ye yoldaş

Amelleri ona sırdaş

Varıyoruz yavaş yavaş

Ebedi menzile doğru', 'Geldik işte gidiyoruz Ebedi menzile doğru Gece gündüz yürüyoruz Ebedi menzile doğru Yükledik biz yükümüzü Hakka döndük yönümüzü Çevirelim yü...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ebedi-menzile-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem Yağmuru', 'ozlem-yagmuru-i-lknur-cekici-7c6dn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitmelerin var kararsız ürkek

Gelmelerin sevdayı yüklenerek

Engin denizleri yüce dağları aşıp

Gelmelerin var sevinerek

Gelmelerin hoş eda gecelere

Gitmelerin olmasa gelecekte

Özlem yağmurunda bırakmasan yüreğimi

Tutsam gecelerce o minnacık ellerini 

Gözlerinde kaybetsem kendimi

Ellerine versem yüreğimi

Ateşinle ısıtsam, yıllarca hasretlenen

Aleve gebe bu sevgimi', 'Gitmelerin var kararsız ürkek Gelmelerin sevdayı yüklenerek Engin denizleri yüce dağları aşıp Gelmelerin var sevinerek Gelmelerin hoş eda ge...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlem-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-aysel-cakar-1h5bl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne görmek isterim gözlerini,

Ne duymak isterim,sesini,

Unutmak istiyor kalbim,artık seni,

Izdırap içinde yakıyor hala,

Yaktığın bu ateş kalbimi.

Bitsin artık diye bekliyorum,

Herşeyin bir sonu var diye ümit ediyorum,

Ama bitmek tükenmek bilmiyor,

Sevgin hala içimde,

Dilim başka söylüyor,

Kalbim seni söylüyor.

Nasıl isterdim yine de Seni görebilmek,

Unutmaya çalışırken,bir anda olsa habersizce,

Uzaktan seyredebilmek.

Çünkü Sen,Benim ilk Aşkımsın,

Hayatımın.varlığımın,

Tek MANASISIN!', 'Ne görmek isterim gözlerini, Ne duymak isterim,sesini, Unutmak istiyor kalbim,artık seni, Izdırap içinde yakıyor hala, Yaktığın bu ateş kalb...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çakar']::text[], 8.5, '{"poet":"Aysel Çakar","poet_slug":"aysel-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istemem-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenler Buraya Gelsin', 'sevenler-buraya-gelsin-abdurrahman-tepe-4jmiz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoluna can vermek vaciptir bize

Bayrağı sevenler buraya gelsin

Şehitlik gelmişken can evimize

Toprağı sevenler buraya gelsin

Her karış toprakta var şehit kanı

Uğruna verelim canla cananı

Evliya doludur her bir dört yanı

Sancağı sevenler buraya gelsin

Ekmeği burçağı suyu havası

Dünyayı inletti ecdatın sesi

Ormanın koronun serin gölgesi

Yaprağı sevenler buraya gelsin

Tarihler yazdırır şehit ve gazi

Dedesi ninesi gelini kızı

Me diye meleşir koyunla kuzu

Kaymağı sevenler buraya gelsin

SAMİHİ der yeter bağla sözünü 

Vatana millete ada özünü

Kelam-ı Kadim''le kapa gözünü

Aşığı sevenler buraya gelsin', 'Yoluna can vermek vaciptir bize Bayrağı sevenler buraya gelsin Şehitlik gelmişken can evimize Toprağı sevenler buraya gelsin Her karış topra...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevenler-buraya-gelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela Gözler', 'ela-gozler-i-rfan-simsek-8cl5z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ela gözler süzüm süzüm süzülür.

Baktıkça yar, ciğerlerim ezilir.

Bakma yarim eller görür söz olur.

Yaktı beni bir ela gözlü dilber.

*********************************

Benim sevdiğimin gözleri elâ.

Açtı başıma bin türlü bela.

Bir göreyim o gözleri, çık yola,

Yaktı beni bir ela gözlü dilber.

*********************************

Kiprikleri ela gözü bürümüş,

Ak gerdanda çifte benler var imiş.

Bu hasretlik gayri bana zor imiş.

Yaktı beni bir ela gözlü dilber.

**********************************

Kara kaşlar ela göze yakışmış.

Yanaklara kırmızı gül takışmış.

Gül sineler buluzuna sıkışmış.

Yaktı beni bir ela gözlü dilber.,

*********************************

İrfan yandı ela gözün fendine,

Ondan başka çare olmaz derdine,

Ela gözü değişemem dördüne,

Yaktı beni bir ela gözlü dilber.

                    Aralık  -  1982', 'Ela gözler süzüm süzüm süzülür. Baktıkça yar, ciğerlerim ezilir. Bakma yarim eller görür söz olur. Yaktı beni bir ela gözlü dilber. ********...', ARRAY['Türk Edebiyatı','Şiir','İrfan Şimşek']::text[], 8.5, '{"poet":"İrfan Şimşek","poet_slug":"i-rfan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ela-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-erol-buker-6n11m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilirmisiniz bu kelimeyi

beş harflidir

özlem.

her harfi bir başka acı verir insana

bir ok gibi saplanır yüreğinize

isyan  edemezsiniz.

Bilirmisiniz bu kelimeyi

beş harfilidir

özlem.

evi kalpdir

vatanı gurbet

dudaklar hep aynı türküyle avunur

sabret deli gönül sabret

belki bir gün biter bu hasret.', 'Bilirmisiniz bu kelimeyi beş harflidir özlem. her harfi bir başka acı verir insana bir ok gibi saplanır yüreğinize isyan  edemezsiniz. Bilir...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozlem-242-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekler', 'cicekler-abdurrahman-tepe-nq6ci', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben kalamam burda işim acele

Selam dua niyaz edin çiçekler

Beklerim yolunu cananım gele

Yurdunuz güzeldir kalın çiçekler

İlkbahar gelince hemen açarlar

Misk-i amber gibi koku saçarlar

Aşılmaz dağları meskan seçerler

Sararıp solmadan gülün çiçekler

Bir daha gelmezsem özlerim sizi

Her seher de çıkıp gözlerim sizi

Gönül aleminde izlerim siz i

Siz de birgün bize gelin çiçekler

Kiminiz kırmızı kiminiz beyaz

Lisan-ı hal ile ederler niyaz

Ben de sizin gibi dertliyim en az

Sevdiceğim oldu elin çiçekler

SAMİHİ''yim geldim size dert yandım

Bir vefasız yara bağlandım kaldım

Dert içinde derdi ben ondan aldım

Bu alem fanidir bilin çiçekler', 'Ben kalamam burda işim acele Selam dua niyaz edin çiçekler Beklerim yolunu cananım gele Yurdunuz güzeldir kalın çiçekler İlkbahar gelince he...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cicekler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarlıklar', 'mezarliklar-sait-muharrem-say-do6nt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mezarlıklar hep yaşamı özetler bana,

Bir köy mezarlığı gibi

Hayatın içinde olmak

Yakın olmak isterken aşka

Şehirlilerin

Şehirlileşenlerin

Tenhalara savurduğu,

Mezarlıklar kadar 

Uzağım aslında,

Oysa, aşkta ölümde var

Hem de

	Belki de

		Hemen....

(Temmuz 2005)', 'Mezarlıklar hep yaşamı özetler bana, Bir köy mezarlığı gibi Hayatın içinde olmak Yakın olmak isterken aşka Şehirlilerin Şehirlileşenlerin Te...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mezarliklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Çek Çıkar', 'kendini-cek-cikar-sait-muharrem-say-cnjiz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi zaman esas oğlan 

Kimi zaman figüran

Bir bakıyorsun içindesin 

Ama yoksun aslında

Bazen yokmuşsun gibi

Ama tam ortasında

Ne zaman

Nerede durur,

Kendinden yükselip

Kendine bakmak gibidir

Yaşamak biraz

Seni seven sana düşman

Yazanı yöneteni belli,

Çözemediğin bir senaryodur

Oynadığın..

Tut çıkar kendini yaşamından 

Bak kendine sonra

Senden başka bir sen gördüğünde

Dön git arkana bakma

Başka bir dekor

Başka oyuncular

aradığın

Rolün nerede aslında

Kendini çekip çıkardığında

Gördüklerin kadar varsın 

Yaşamda.....

(Temmuz 2005)', 'Kimi zaman esas oğlan  Kimi zaman figüran Bir bakıyorsun içindesin  Ama yoksun aslında Bazen yokmuşsun gibi Ama tam ortasında Ne zaman Nered...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kendini-cek-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarıma', 'dostlarima-sait-muharrem-say-7i7tz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostum demek zordur,

Her yürek yetişmez

Onca paylaşmaya,

Daralır çoğu,

Kıvranır bencilliğin

Kirli paslı bulvarında,

Dostun avucunun içi gibidir,

Gözlerin önüne düştümü bilir,

Nerdesin yaran derin midir? 

Onsuz yapamayacağını bilirsinde

Tek o mutlu olsun diye

Giderken gülebildiğin,

Ağlayamadığın,

Gözlerini önüne düşüremediğin,

En koyu kanamasını yüreğinin

İçine dirhem dirhem akıttığın,

(Mayıs 2005)', 'Dostum demek zordur, Her yürek yetişmez Onca paylaşmaya, Daralır çoğu, Kıvranır bencilliğin Kirli paslı bulvarında, Dostun avucunun içi gibi...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dostlarima-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Buradan Şiir Perisi', 'git-buradan-siir-perisi-sait-muharrem-say-6s3go', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir perisi çık git odamdan

Görmüyor musun çalışıyorum.

Nerden çıktı? 

Beynimin en gri hücrelerinin arasına bağdaş kurup oturmak,

Masama dağıttığın grek şarkıları al ve terket burayı,

Ben sadece balık avlarken dinlerim onları

Yılın her mevsimi ayırdetmeden

Yanlızca ben ve deniz varken

Yanlızlıklarla birbirimize salıncaklar kurmuşken

Aşkımızı ince ince birbirimize akıtırken,

Yağmurda başladı bak,

Işığını açmadan odamın

doğanın griliğine gizlenmeye hazırken

git buradan,

Yağmuru dolama boynuma,

O güzel grek şarkıları ve yağmur

Eski bir kayık ben ve deniz

Bilmiyor musun beni ne kadar uzaklara savuracaklar,

Ve düştüğümde ne kadar canım yanacak.

Git buradan....

(Şubat 2005)', 'Şiir perisi çık git odamdan Görmüyor musun çalışıyorum. Nerden çıktı?  Beynimin en gri hücrelerinin arasına bağdaş kurup oturmak, Masama dağ...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/git-buradan-siir-perisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapalım?', 'ne-yapalim-saim-bastik-zhirl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dursun ELMAS hocama ve tüm  Gönüldaşlara

 

Devlet Bey''e bu hiddet,bu düşmanlıklar niye? 

Ne yapalım,gidipte bir kurşun mu sıkalım? 

Hoşumuza gitmeyen birşey söyledi diye

Ne yapalım, gidipte bir kurşun mu sıkalım.? 

Başörtüsü diyerek gösteri yaptıranlar

İktidar oldular bak, takıldı mı türbanlar? 

Şimdi tarafımızdan,doğru mu yapılanlar

Ne yapalım, gidipte bir kurşun mu sıkalım? 

İmama kızdık diye camiden mi kaçalım

Cami yıkılsın diye hep bayrak mı açalım

Yoksa hepimiz birden HAVRA''yamı! geçelim

Ne yapalım,gidipte bir kurşun mu sıkalım? 

Memleket satılıyor bizim derdimiz bu mu? 

Bütün bu fitne fesat sizin için doğru mu? 

Kime yarar bu fitne düşünelim sonunu

Ne yapalım, gidipte bir kurşun mu sıkalım? 

Ayrılıkta azap var demiş Peygamberimiz

Şu anda yumruk gibi olmalıyız hepimiz

Ora bizim herzaman gönüldeki evimiz

Ne yapalım, gidipte bir kurşun mu sıkalım? 

Liderim diyen beyler nerelerde gezdiler

Bu misyon bitti diye ne yazılar yazdılar

Yıllarca bu  davanın düzenini bozdular

Ne yapalım,gidipte bir kurşun mu sıkalım? 

Ozan Arif''le Ramiz kanlı bıçaklı idi

No oldu şimdi bunlar hep bir araya geldi? 

Şimdi bütün kabahat Devlet beyin mi oldu? 

Ne yapalım,gidipte bir kurşun mu sıkalım? 

Kan kusup biz şu anda bu şerbet diyeceğiz

Davanın hayrı için hep bir yürüyeceğiz

Yarın bir seçim olsa kime oy vereceğiz? 

Ne yapalım,gidipte bir kurşun mu sıkalım?', 'Dursun ELMAS hocama ve tüm  Gönüldaşlara   Devlet Bey''e bu hiddet,bu düşmanlıklar niye?  Ne yapalım,gidipte bir kurşun mu sıkalım?  Hoşumuza...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ne-yapalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Slogan Yazalım', 'bir-slogan-yazalim-yusuf-ziya-yilmaz-1oml6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kardeşlerim gelin

   Bir  slogan yazalım

   İnsanları ve insanlığı

   Küme küme parçalayan

   Dikenli tellerin 

   Hudutlara   bölemediği

   Beyaz  güvercinlerin 

   Barış  ve kardeşlik için kanat çırptığı

   Masmavi  gökyüzüne

   Soldurmadan umutları

   Kurşunlatmadan  barışı

   Dünyadaki  bütün  çocuklarla 

   Gelin bir slogan yazalım

   ''Kim  olursan ol

    Yine gel......! Yine gel....! ''

    Barışıp  kardeş olalım

   Atalım  silahları

   Tarihin  kanlı  çöplüğüne', 'Kardeşlerim gelin    Bir  slogan yazalım    İnsanları ve insanlığı    Küme küme parçalayan    Dikenli tellerin     Hudutlara   bölemediği   ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Yılmaz']::text[], 8.5, '{"poet":"Yusuf Ziya Yılmaz","poet_slug":"yusuf-ziya-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-slogan-yazalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ömrümsün', 'sen-omrumsun-isik-aktas-mb6rx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidenlere...

Nedensiz yere ölmek istiyorum.

ölmek istediğim yeri bilmeksizin hem de.

ölümün adını anmak istemiyorum

ama

ölüm benim adımı andığında; 

sana sığınmak istiyorum.

çünkü sana sığındığımda

ölüm, benim için

bütün ömrümün kısa bir özeti oluyor,oldu,olacak...

                                                                       17.05.2003/c.tesi-Şişli', 'Gidenlere... Nedensiz yere ölmek istiyorum. ölmek istediğim yeri bilmeksizin hem de. ölümün adını anmak istemiyorum ama ölüm benim adımı and...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-omrumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.*Umut*', 'a-umut-nail-yavuz-qdno6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir yalanı sevmiştim../ düşümde gördüğüm

tek bir sonsuz andı zamanın ötesinde

gizemli bir ödeve tutsak kılmış kendini

umut en güzel sokak../ iki ucu açık

zorunlu izine çıkarttım zalim zamanlarımı

seni dikeninden ayrı düşünemem gül

düşlerin çiçekleri solar../ ü m i d i n d e

bir imgenin keskin yüzünde

uçuk mavi bir su damlası hayat

sevişir gibi dövüştüm

_söylemin omurgasında

bahar düşmüş ellerimden

soğudu soluğum / yüzünün çıkmazlarında

__ dur anılarımı silme

çiçekli bir zamandır dürdüğüm/desenlerinde halının

gelseydin serecektim ömrüne

tükendi umutlar../ yaşamın çılgın isteğinde

___s ö z s o ğ u d u

kaç beden eskitti gözlerin

kendime sarıldığım boşluk sensin

____silinir mi yazgı

çileden iğne ipliğe dönmüş ipek

avuç içi kadar yürekte dünya kadar sızı.

Nail Yavuz, İzmir

Ağustos 2005 y.düzenleme', 'bir yalanı sevmiştim../ düşümde gördüğüm tek bir sonsuz andı zamanın ötesinde gizemli bir ödeve tutsak kılmış kendini umut en güzel sokak../...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/a-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ama-neden-g6guo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden aşk şiiri yazıyorsun diyorlar bana,

izin verdiği için belkide,

belkide az yaraladığımdan onu ve getirdiklerini

belki benden götürdüklerini

sıkça yüzüne vurmadığım için

Para gibi şeytanın oyuncağı görmediğim için belki de

sakladığım için sırlarını

ya da pek saf buluyor beni

hani bundan zarar gelmez hesabı

biliyor kirletmediğimi

girdiğim her kalbi

nasıl bulmak istiyorsam öyle bıraktığımı...

(Ağustos 2005)

 Sait Muharrem Say', 'Neden aşk şiiri yazıyorsun diyorlar bana, izin verdiği için belkide, belkide az yaraladığımdan onu ve getirdiklerini belki benden götürdükle...', ARRAY['Türk Edebiyatı','Şiir','ama neden?']::text[], 8.5, '{"poet":"ama neden?","poet_slug":"ama-neden","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-siiri-ama-neden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-isik-aktas-8zh9m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidenlere...

Beni uyutamadınız; 

uyutmadınız çünkü.

ayıkken bitmemişti ki sizi sayıklamalarım

sarhoşken nasıl bitsin...

        bir, (sen) ''iniz kaldı sana,

                                         (sen) ''siz,

        bir de (sevgi) ''niz,

                               (ben) ''siz=bensiz

                               belli belirsiz...

                                                       18.05.2003/04.30', 'Gidenlere... Beni uyutamadınız;  uyutmadınız çünkü. ayıkken bitmemişti ki sizi sayıklamalarım sarhoşken nasıl bitsin...         bir, (sen) ''...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizlik-270-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben anladım M.İ.Yakar''ın anlayana veda şiirine..', 'ben-anladim-m-i-yakar-in-anlayana-veda-siirine-mikdat-bal-uafiu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben anladım herkes böyle olmalı 

Çok açıktır, çok sarihtir söz senin 

Bilmeyenler, belleyip anlamalı 

Giderken bayrağın beyaz bez senin 

Deme gencim, deme yaş elli değil 

Yolculuk var, ne zaman belli değil 

Geçiciyiz hayat temelli değil 

Ne güzeldir idrak etmen, tez senin 

İyi anla hayat denen mektebi 

“Ölmeden önce ölünüz” der Nebi! 

Bunun vardır hikmetleri, sebebi 

Sende kinayeler çok, bitmez senin', 'Ben anladım herkes böyle olmalı  Çok açıktır, çok sarihtir söz senin  Bilmeyenler, belleyip anlamalı  Giderken bayrağın beyaz bez senin  Dem...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-anladim-m-i-yakar-in-anlayana-veda-siirine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sersemin Biriyim (!)', 'ben-sersemin-biriyim-muharrem-cetinkaya-lqwe2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '___________Tüm metaryalist düşünenlere

ben sersemin biriyim

oturmuş senin için şiirler yazıyorum

gönülden nağmeler

oysa senin

okuman-yazman yok ki

ben sersemin biriyim

oturmuş sana

en güzel renklerle bezediğim

gönül bohçamı gösteriyorum

oysa senin

senin gören gözün yok ki

ben sersemin biriyim

oturmuş sana

en yanık şarkılarımı söylüyorum

içli

oysa senin

senin duyan kulağın yok ki

ben sersemin biriyim

oturmuş sana

delikanlı duygularına

güzeller dolusu haremler sunuyorum

oysa senin

senin erkekliğin yok ki

ben sersemin biriyim

oturmuş sana

genç_kızlık duygularına

yiğit delikanlı sunuyorum

babayiğit

oysa senin

senin kadınlığın yok ki

ben sersemin biriyim

oturmuş sana

gönül bahçemin en güzel

güllerini deriyorum

kokla diye

oysa senin

senin koku alma duyun yok ki

ben sersemin biriyim

oturmuş sana

dil döküyorum

sevgiden

muhabbetten

aşktan

yürekten bahsediyorum

oysa senin

senin vicdanın yok ki....', '___________Tüm metaryalist düşünenlere ben sersemin biriyim oturmuş senin için şiirler yazıyorum gönülden nağmeler oysa senin okuman-yazman ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ben-sersemin-biriyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pervasız Konuşmalara Karşıt', 'pervasiz-konusmalara-karsit-isik-aktas-rigo3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidenlere...

                     (hasretle) 

Uzun uzun ırmakların, kısa kısa öyküleri vardır.

Hani susmak, konuştuğun kadarını unutmak gibidir.

ve konuştuğun kadarını anımsamak,

sustuğunu konuşmamak gibidir.

Ve bir gün gelir,

sustuğun, seni değil konuşmadıklarını kusar.

ve sen kustuğun kadar sensin.

Ve yine bir gün gelir,

bir gül bahçesinde içine çektiğin nefes,

ses oluncaya kadar hıçkırırsın.

hıçkırığında diken,

içinde tek bir kırmızı gül.

ve asla dokunamazsın o güle.

çünkü o gül sana yasak,

sen o gülden saklı.

ne sen o gülün yasağını kırmak için çabalarsın,

ne de o gül seni bulmak için çabalar...

yiter zaman,

buluşursunuz,

bir de bakarsın ki; 

mezar taşın güllerle kaplı.

ya üstündeki çiseler? 

                               kimin gözyaşları? ...

                                           22.05.2003/24.00/Şişli', 'Gidenlere...                      (hasretle)  Uzun uzun ırmakların, kısa kısa öyküleri vardır. Hani susmak, konuştuğun kadarını unutmak gibi...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/pervasiz-konusmalara-karsit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yare Sitem', 'yare-sitem-fatih-suretli-vi8hw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne oldu yar

Hüznüm mü yaraladı

Yoksa; 

Yaram mı hüzünlendirdi

Seni? .....', 'Ne oldu yar Hüznüm mü yaraladı Yoksa;  Yaram mı hüzünlendirdi Seni? ........', ARRAY['Türk Edebiyatı','Şiir','Fatih Suretli']::text[], 8.5, '{"poet":"Fatih Suretli","poet_slug":"fatih-suretli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yare-sitem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hâr Olur', 'h-r-olur-murat-sahin-7a4dy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dost diyerek sığındığın gönüller

Bir gün gelir yâr iken agyâr olur

Derdin söyletip de öğüt verenler

Çeker gider, bize düşen zâr olur

Geceyi alıp da derdin örtersin

Uyku girmez açık kalır gözlerin

Yatacak bir ufak hasır istersin 

Verdikleri kefen olur nâr olur

Güle kıymet biçip kahrın çekersin

Dalında gün gece figan edersin

Açılsa diyerek şafak beklersin

Gonca sandığın diken olur hâr olur

Türlü çiçeklerden kurduğun köşkler

Çıkıp ardınsıra koştuğun düşler

Yıkılmaz bildiğin bunca ümitler

Yel eser de viran olur târ olur

Bahar geldi diye yola düşersin

Gezer dolanırsın ömür gidersin

Hasbahçada bir zaman gönül eylersin

Kış iner de boran olur kar olur

Baranîyem sözlerimde hâre var

Dilde sitem,yüreğimde yare var

Şu dünyada derde çare bulanlar

Yoldaşımdır yılan olur mâr olur', 'Dost diyerek sığındığın gönüller Bir gün gelir yâr iken agyâr olur Derdin söyletip de öğüt verenler Çeker gider, bize düşen zâr olur Geceyi ...', ARRAY['Türk Edebiyatı','Şiir','Murat Şahin']::text[], 8.5, '{"poet":"Murat Şahin","poet_slug":"murat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/har-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilmezsin', 'sen-bilmezsin-murat-sahin-2iksr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsyankar mevzileri kolluyor gece,

Ahengi sönüyor sımsıcak kelimelerin

Biraz olsun ısınmak için

Titrek bir muma sarılıyor karanlık

Sarı bir hüzün damlıyor sessizce

Eğreti çığlıklar tırmalıyor heceleri,

Peşi sıra diziliyor aç köpekler

Dört bir yanı kuşatılmış mısraların

Katline ferman eylemişler,

Sayfa sayfa vuruyorlar şiirleri

Sen bilmezsin bu kördüğümü

Bu rezil savaş,bu yaprak dökümü

Bölük bölük hayaller,tabur tabur sevgiler

Bu zindan gecede bekliyorlar ölümü

Çağırsan da bütün şairlerini dünyanın

Güneşi, ayı, yağmuru ve yıldızları

Hiçbir şey eskisi gibi değil artık! 

Eşkâli bilinmeyen kediler tutmuş yolları

Art arda yankılanıyor bu sarı sayfalarda

Yüreklere düzenlenen intihar saldırıları', 'İsyankar mevzileri kolluyor gece, Ahengi sönüyor sımsıcak kelimelerin Biraz olsun ısınmak için Titrek bir muma sarılıyor karanlık Sarı bir h...', ARRAY['Türk Edebiyatı','Şiir','Murat Şahin']::text[], 8.5, '{"poet":"Murat Şahin","poet_slug":"murat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-bilmezsin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla ve Mecnun', 'leyla-ve-mecnun-murat-sahin-7xgjo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu çöller beni avutmaz Leyla 

Ben ki susamışım ateşler içmeye

Yanmak ille de yanmak derim

İçimde sadece aşk olsun isterim', 'Bu çöller beni avutmaz Leyla  Ben ki susamışım ateşler içmeye Yanmak ille de yanmak derim İçimde sadece aşk olsun isterim...', ARRAY['Türk Edebiyatı','Şiir','Murat Şahin']::text[], 8.5, '{"poet":"Murat Şahin","poet_slug":"murat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/leyla-ve-mecnun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derman Diye', 'derman-diye-murat-sahin-e3tpy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçilmez bu bade yakar sinemi

Kaç zamandır gönüllerde kor oldu

Kime bildireyim bunca derdimi

Arz eylemek tellere de zor oldu

Nice döktüm gurbet elde kanımı

Ya aklım al,ya bu tende canımı

Bulamadım gidilecek yönümü

Dağa taşa vara gele yol oldu

Yaban oldum sıla yurdu illere

Hasret kaldım o tomurcuk güllere

Çok ağladım,dökemedim dillere

Yağmur yağdı kirpiğime göl oldu

Bârânîyem güneş doğmaz şehrime

İlaç,merhem çare olmaz zehrime

Derman diye gül koklattım ömrüme

Bir od düştü yüreğime kül oldu', 'İçilmez bu bade yakar sinemi Kaç zamandır gönüllerde kor oldu Kime bildireyim bunca derdimi Arz eylemek tellere de zor oldu Nice döktüm gurb...', ARRAY['Türk Edebiyatı','Şiir','Murat Şahin']::text[], 8.5, '{"poet":"Murat Şahin","poet_slug":"murat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derman-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-herdem-ankara-hp3zi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımla beni

Derin bir bakışınla kalbimi çaldın

Yalan sözlerle umutlarımı yıktın

Göz yaşlarıma sen sebep oldun

Bırakıp giderken yalnızlığımla beni

Hani söz vermiştin farklı olacaktın

Sevgini hep bana adayacaktın

Kaderime yine beni küstürdün

Bırakıp giderken yalnızlığımla beni

Hasretinden yanmıyorum artık

Sevgi ile bakmıyorum resimlerine

Sevginin ölümsüzlüğüne inanmıyorum artık

Bırakıp giderken yalnızlığımla beni

Herdem

01/08/2003

13:13', 'Yalnızlığımla beni Derin bir bakışınla kalbimi çaldın Yalan sözlerle umutlarımı yıktın Göz yaşlarıma sen sebep oldun Bırakıp giderken yalnız...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizlik-271-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-volkan-yoruc-pr177', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dostluk

Bir kahve değildir ki içesin

Yahut bir çiçek değildir ki koklayaveresin

Dostluk

Bir gülümseyişle ısıtır yüreğini

Bir sözüyle tebessümlere salar cemalini

Dostluk

Bir merhabayla yeniden yaşarsın yaz mevsimini

Dostluk

Ne de güzel şeysin sen

Ömre ömür katarsın hissettirmeden

Dostluk

Can dır Canan dır

Yani yüreğe serpilen kan dır hayat tır

Dostluk

Şiirleri bile aşan mısralardır

Yahut herkesin çalamadığı saz dır

Dostluk

Can dır Canan dır

130. peronda bana gülümseyen bir tatlı simadır', 'Dostluk Bir kahve değildir ki içesin Yahut bir çiçek değildir ki koklayaveresin Dostluk Bir gülümseyişle ısıtır yüreğini Bir sözüyle tebessü...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dostluk-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak Vakti...', 'safak-vakti-ali-baksi-7xzrf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürürken yanlızlığımın yolunda sensiz

Kaldırımdaki güllere takıldı gözlerim

İcimde buruk bir sevda ateşi yaksada

Mırıldatıyor sevda türkümü dudaklarımda

Şafak vaktini bekliyorum korkularımda

Satin beşinde ğüneşimin doguşunu

Ürkütüyor yanlız gecen gecelerimi

Hafif esen rüzğar vuruyor böğrüme

Bahcemdeki güllerin boynu bükük

Su istiyor sevgi istiyor benligimden

Lalelerin renği soluk yanlızlığında

Şafagımı bekliyorum vakitsizce

Şarabım köpürmüş taze kafesinde

Bekliyorum sabahımın kan kırmızı cayını

Sevda yüklü düşlerim yanlızlığında

Yeni dogan bir güneş yeni bir ben...

Yeni bir şafak yarına umutlar ve arzularla dogacak bir daha...', 'Yürürken yanlızlığımın yolunda sensiz Kaldırımdaki güllere takıldı gözlerim İcimde buruk bir sevda ateşi yaksada Mırıldatıyor sevda türkümü ...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/safak-vakti-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlice', 'gizlice-herdem-ankara-wr9u9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gizlice

Saat yine gece yarısını gösteriyor

Şarkılarda seni arıyorum sessizce

Seni soruyorum her gece yalnızlığıma

Yıldızlar kadar uzak

Güneş kadar sıcak diyor gizlice

Sonra susuyorum saatlerce 

Derinlere dalıyorum düşündükçe

Seni soruyorum yüreğime sessizce

Ruhun kadar yakın

Dağlar kadar yüce diyor gizlice

Derin bir uykuya dalıyorum

Rüyamda belki sen olursun diye

Sevgiyi soruyorum kaderime sessizce

Hasret kadar derin

Özlemek kadar acı verir diyor sessizce

Hayatımı geçiriyorum gözümün önünden

Çaresiz kalıyorum bir an acı içinde

Şefkati soruyorum kendime sessizce

Deniz kadar büyük

Yaşamak gibi güzeli yok diyorum gizlice

Herdem

15/07/2003

10:30', 'Gizlice Saat yine gece yarısını gösteriyor Şarkılarda seni arıyorum sessizce Seni soruyorum her gece yalnızlığıma Yıldızlar kadar uzak Güneş...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gizlice-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An''ı Daim', 'an-i-daim-isik-aktas-pizvs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki ara-bir dere,

yaşamak,

kurallı şartlı; 

papyonlu salon beyefendisi,

ya hanımefendi.

kuralsız şartsız

çizgi ötesi.

ama sadece o an.

an''lar ve özlemler,

an''lar ve bedenler.

aynı bedenler, farklı an''lar ve yaşamlar.

an''lar ve yaşamlar,

biteviye...

ömür ne kadar ki; 

bir sigara içimi,

bir türkü söylemi,

bir kuşun kanat çırpışı,

dermansız dert,

bilinmez...

bir bilinmezi yaşamak hesapsız,

iki ara-bir dere,

hıh...

bir mum alevi belki,

aynı haz alınır mı ikinci parlamasından,

an''ı daim derdi hocam,

an''ı daim''dir güzel olan yaşam.

hazlar, bir defa alınmak içindir,

o an ve o an''ı yaşamak.

bulutsuzluk özlemi,

bulutsuz bir gökyüzü olur mu ki,

bazen bulut yoktur gökyüzünde

bazen gökyüzünü göremezsin.

an''ı daim işte...

doğru söyledi hocam; 

mutluluk, an''ı daim''de gizli...

keşke an''ı daim''ler hep sonsuz olsa,

o zaman işte,

ne iki ara

ne dere...

                        Mart 2003', 'İki ara-bir dere, yaşamak, kurallı şartlı;  papyonlu salon beyefendisi, ya hanımefendi. kuralsız şartsız çizgi ötesi. ama sadece o an. an''la...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/an-i-daim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-herdem-ankara-lanps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEVDA 

Tüylerin ürperdirmi için titredimi

Gözlerinin yerine kalbin ağladımı

Kalbin söyleyebildimi sevdanı

Bu ne aşk ne de bir başka duygu

Bunun adına sevda diyorlar bu bir tutku

Gecikmiş bir duygu yumağı

Yaşanılmamışı yaşama hevesi sanki

Kalbin söylebildimi sevdanı

Bu ne aşk ne de bir başka duygu

Bunun adına sevda diyorlar bu bir tutku

Çocuklar gibi sebepsiz şımartınmı

Kalbinin esiri oldunmu hiç

Gözlerinin yerine kalbin ağladımı

Bu ne aşk ne de başka bir duygu

Bunun adına sevda diyorlar bu bir tutku

04/07/2003 

saat:01:10', 'SEVDA  Tüylerin ürperdirmi için titredimi Gözlerinin yerine kalbin ağladımı Kalbin söyleyebildimi sevdanı Bu ne aşk ne de bir başka duygu Bu...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevda-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanaat', 'kanaat-sait-kucuk-bepj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dağ başındaymışım

azığım yokmuş

umrumda değil

sevdan var ya

yeter bana', 'dağ başındaymışım azığım yokmuş umrumda değil sevdan var ya yeter bana...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kanaat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-isik-aktas-nzrgg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Hasretle...) 

Gitme...

gidersen, kurur dallarım.

göklerin hepsi karanlık,

kanatlarım kırılır.

susuz kalır köklerim.

geceler bitmez,

hiç sabah olmaz ki.

Gitme...

gidersen, yetim kalır ellerim.

gözlerim boşluk rengi,

hayallerim kötürüm.

kurak geçer yazlarım.

dillerim bir deli çığlık,

gönlüm konuşmaz ki.

Gitme...

gidersen,hayat sonsuz bir labirent,

çıkış yok.

alabora düşlerim,

deniz yok, 

hava yok.

Gitme be çocuk,

ölüm sana yakışmaz ki,

gidersen,

ben yok

gitme...

Gitme...

hayattan alacaklısın,

yaşanacak çok şey var daha,

kalemine sözün vardı,

buluşmanı yapmadın ki.

gitme be çocuk,

bizi yetim bırakma.

sevdamız yarım kaldı,

ölüm sana yakışaz ki.

gidersen,

sen de yarım kaldın,

gitme,

gitme...

                             11.05.2003/03.30', '(Hasretle...)  Gitme... gidersen, kurur dallarım. göklerin hepsi karanlık, kanatlarım kırılır. susuz kalır köklerim. geceler bitmez, hiç sab...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gitme-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güya Bizde Yaşıyoruz', 'guya-bizde-yasiyoruz-ali-dilki-zyk4a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizler çile hamalıyız

Her gün bir dert taşıyoruz

Kırk taraftan yamalıyız

Güya biz de yaşıyoruz

Asgaridir maaşımız

Çıkmaza girmiş başımız

Ne yaz belli ne kışımız

Güya bizde yaşıyoruz

Yüro başı almış gider

Dolar onla yarış eder

İşçi memur her gün heder

Güya biz de yaşıyoruz

Kaderine küskün dargın

Çilelerden yemiş vurgun

Düşünceden yorgun argın

Güya biz de yaşıyoruz

ALİ der; bu nasıl yasa

Dertlerimiz kime tasa

Nefes almak yaşamaksa

Güya biz de yaşıyoruz.

Ahenk 02. 08.1999', 'Bizler çile hamalıyız Her gün bir dert taşıyoruz Kırk taraftan yamalıyız Güya biz de yaşıyoruz Asgaridir maaşımız Çıkmaza girmiş başımız Ne ...', ARRAY['Türk Edebiyatı','Şiir','Ali Dilki']::text[], 8.5, '{"poet":"Ali Dilki","poet_slug":"ali-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guya-bizde-yasiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzuhal', 'arzuhal-sadik-altinkaynak-kuxo0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cumhurbaşkanlığı yüce katına

Sayın Ahmet Necdet SEZER’ in âli zatına

Mağduriyetimi bildirir arzuhalimdir

Haksızlığa uğramak yargısız ölümdür

Bendeniz Van Erciş’ ten bir garibanım

Ne evim var ne arabam ne de hânım

Otuz yıl çalıştım devlete sadakatle

Korudum devlet malını pür dikkatle

Bunca yıl kaymakamlık müfettişlik yaptım

Kula kul olmadım sadece Hakka taptım

Kimse kötü demedi ne yüzüme ne arkamdan

Şoke oldum kararnamem dönünce makamdan

Nihayet Genel Müdür olacaktım Arsa Ofisine

Ömrümce karışmadım kimsenin etlisine sütlüsüne

O yüzden beklemiyordum “Uygun Görülmemeyi”

O yüzden sindiremiyorum içime bu muameleyi

Sonunda dayanamayıp sordum sebebini Makam-ı Âliden

Gelen cevapla bir kere daha şaşırdım sahiden

Buyurmuşlar “Ofisin yaptığınız görevlerle ilgisi yok”

O halde Vali olabilirim zira görevimle ilgisi çok

Sonra talip oldum Denizcilik Müsteşar Yardımcılığına

Maalesef yine uğradım “adeta” ırk ayrımcılığına

Bir kere daha atanmam uygun görülmedi

Vekâletten asalete geçmeme izin verilmedi

Yoksa bunca atananlar “Beyaz Türk” ben zenci miyim

Onlar efendi de ben Çankaya kapısında dilenci miyim

İstirham ediyorum dosyama bir daha bakınız

Hangi görevlere uygunsam bir yeşil ışık yakınız

Bir bülbülü nâlanım çektiğim hep dilimdendir

Sürçü lisan eylediysem uğradığım zulümdendir

Hatalıysam bağışlayın lütfen bakmayın kusuruma

Bir cevap bahşedin şu kısacık basit soruma

Arşı âlaya dayandı feryadım figanım ahım

Lütfedip söyleyin nedir hatam noksanım günahım', 'Cumhurbaşkanlığı yüce katına Sayın Ahmet Necdet SEZER’ in âli zatına Mağduriyetimi bildirir arzuhalimdir Haksızlığa uğramak yargısız ölümdür...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/arzuhal-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde kanayan gizli bir Yara', 'i-cimde-kanayan-gizli-bir-yara-asii-gonul-zjhkk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', ':::GEL ÖZLEMİM::: 

dizlerinin dibinde oturup 

dinlenmek isterdim bitene dek 

gel şiirlerimi dinle özlemim bitene dek 

boynuna sarılıp uyumak isterdim sabahlara dek 

gel kollarıma özlemim gidene dek 

gözlerinin içene bakıp erimek isterdim 

bu dünyadan göçene dek 

gel gözlerime bak......özlemim bitene dek... 

_______________________________________________________________________________ 

kalbimde üç çiçek yetişdim 

SEVMEK,,,SEVİLMEK,,,VE 

BEKLEMEK 

SEN BUNLARIN İKİSİNİ ANLAYAMADIN 

BANA YALNIZCA BİRİ KALDI... 

BEKLEMEK 

KARANLIK AKŞAMLARDA VE MUTSUZ YARINLARDA 

GÜLMEYİ UNUTMA ARKADAŞ 

SEVDİĞİN SENİNLE OLMASA DA 

SEVİLDİĞİNİ SAKIN 

UNUTMA.... 

________________________________________________________________________________ 

KUYRUKLU YILDIZLAR VARDIR DÜNYAYA 

YETMİŞ YILDA BİR KEZ GELİRLER 

İNSANLAR ONU BELKİ BİR KEZ GÖRÜRLER 

BEN O YILDIZI GÖRDÜM O DA SENSİN 

ARKADAŞ SEN ÇÜNKÜ 

KUYRUKLU YILDIZ BEN İSEEE 

Çoban YIldızı... 

_____________________________________________________________________________ 

SENİ YILDIZLARA BENZETİYORUM 

ONLAR KADAR ETKİLEYİCİ,ÇEKİCİ VE GÜZELSİN 

AMA ARANIZDA TEK BİR FARK VAR... 

ONLAR MİLYONLARCA,,, 

SEN BİR TANESİN', ':::GEL ÖZLEMİM:::  dizlerinin dibinde oturup  dinlenmek isterdim bitene dek  gel şiirlerimi dinle özlemim bitene dek  boynuna sarılıp uyumak...', ARRAY['Türk Edebiyatı','Şiir','Asii Gönül']::text[], 8.5, '{"poet":"Asii Gönül","poet_slug":"asii-gonul","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/icimde-kanayan-gizli-bir-yara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemileri Yakmadan', 'gemileri-yakmadan-sadik-altinkaynak-r4s8i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dönüş yok artık demiştim bir şiirde

Çünkü yakmıştım tüm gemileri

Sanki buna cevap buldum başka bir şairde

Diyor ki; “Endülüs’e varılmadan gemiler yakılmaz.”

Şair duygularla konuşur kusuruna bakılmaz

Hale göre söz sadır olur şairden yazardan

Biz başka gözle bakmışız, O bakmış başka nazardan

O’ da haklı gemiler yakılmaz hedefe varmadan

Aksine şişirip yelkenleri kürek çekmeli durmadan

Deniz azgın  yol uzak tekne küçük olsa da

Azmetmeli varmak için menzili maksuda

Zira düşman uyumaz su uyusa da

Her an alesta bekler bir pusuda

Gevşemek yok kardeşler dayılar emmiler

Henüz Endülüs görünmedi ufukta

Yakmayalım daha bize lazım bu gemiler

Varacağız hedefe belki akşama belki kuşlukta', 'Dönüş yok artık demiştim bir şiirde Çünkü yakmıştım tüm gemileri Sanki buna cevap buldum başka bir şairde Diyor ki; “Endülüs’e varılmadan ge...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gemileri-yakmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-aliye-onur-j4a2t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kader benimle oynuyor…

Hayallerle zaman geçiyor 

Sevinç dolu günler hiç gelmiyor

Sensiz olunca yaşam yaşanmıyor

Kader bana bakıp eğleniyor

Beden yaşlanıyor, ruh tükeniyor

Hayat sensiz akip gidiyor

Bu şair de kadere

Kadeh kaldırıyor

Ve gülüyor...', 'Kader benimle oynuyor… Hayallerle zaman geçiyor  Sevinç dolu günler hiç gelmiyor Sensiz olunca yaşam yaşanmıyor Kader bana bakıp eğleniyor B...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kader-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık çok derinde', 'isik-cok-derinde-hakan-e-mmv93', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben belki senin gibi değilim

Belki ben dönebilirim her an

Geldiğim yeri hiç görmedin, konuşma

Aynalardan gelen ses ve bir tek tuttuğun nefes var

Kör adamın gördüğü bütün kalpler kördüğüm

Gümüşten caddelerde hep kuklalar gördüğün

Sahiplerdi kalanlar

Kiracılar terketti

Büyük karton binalar

Bomboş birer sepetti

Ben ufakken derlerdi 

‘Altı çıktı kaç kaldı? ’

Altı değil boku çıktı

Yüzlerdeki nefretti

Kalan herşey senin oldu ‘yaşasın! ’ diye bağır artık

Bu şehirde bir tek sensin, diğerleri birer artık

O çok korktuğun polisler evet senin peşinde

Kaçacak yer kalmadı, ışık çok çok derinde', 'Ben belki senin gibi değilim Belki ben dönebilirim her an Geldiğim yeri hiç görmedin, konuşma Aynalardan gelen ses ve bir tek tuttuğun nefes...', ARRAY['Türk Edebiyatı','Şiir','Hakan E']::text[], 8.5, '{"poet":"Hakan E","poet_slug":"hakan-e","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isik-cok-derinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalenin dibi', 'kalenin-dibi-hakan-e-iasbp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O kalenin dibiydi 

 ben iyi hatırlıyorum

“Burdan geçmez” dediğin vapur

“Burda açmaz” dediğin menekşe 

“Burda uçmaz” dediğin muhabbet

“Burda çıkmaz” dediğin balık

“Burda olmaz” dediğin. öpücük

“Burda görmez” dediğin abin......', 'O kalenin dibiydi   ben iyi hatırlıyorum “Burdan geçmez” dediğin vapur “Burda açmaz” dediğin menekşe  “Burda uçmaz” dediğin muhabbet “Burda ...', ARRAY['Türk Edebiyatı','Şiir','Hakan E']::text[], 8.5, '{"poet":"Hakan E","poet_slug":"hakan-e","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalenin-dibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akil', 'akil-sadik-altinkaynak-er7y5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akıl altın bir taçtır

Herkes akla muhtaçtır

Akılsız dosttan akıllı düşman evladır

Akılsız dost her zaman başa beladır

Akıllı her söylediğini düşünür

Amma her düşündüğünü söylemez

Akılsız konuşmuş olmak için konuşur

Nerede susup nerede konuşacağını bilemez

Akıllı güzel bakar güzel düşünür hoş görür

Akılsız dolu bardağı bile boş görür

Akıllı affedicidir her kusuru görmez

Köprü kurar etrafına duvar örmez

Güneş gibi ışığını istenmeden verir

Sevgi havuzunda sudaki buz gibi erir

Akılsız inatçıdır pireyi deve yapar

Güzelliği görmemek için gözünü kapar

Gece gibi güzellikleri örter gizler

Paylaşmayı bilmez hep nefsini izler

Akıllı güzelliği dışta değil içte arar

Her işinde mutedildir orta karar

Akılsız mazrufa değil zarfa bakar

Fevridir hırsla herkese verir zarar

Şöyle derdi bizim rahmetli nine:

“Akıl tace zerine, sere herkesi nine”

Yani; “Akıl altın taçtır” onsuz olmaz

Allah vergisidir “Her kafada bulunmaz”', 'Akıl altın bir taçtır Herkes akla muhtaçtır Akılsız dosttan akıllı düşman evladır Akılsız dost her zaman başa beladır Akıllı her söylediğini...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/akil-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cazibe', 'cazibe-aliye-onur-s7h8d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç bir eşi yoktur hani, 

Çemenin ahenkli dansı yumurtayla

Sarmaş dolaş cilveli…

Tadı damağımda, kokusu burnumda

Elimi uzatsamda bi bandırsam ekmeği

Bak elim yine boşlukta…

Serap gibi birşey bu benimkisi…

Hep gözümün önünde, dumanı üstünde…

Yok arkadaş aç değilim, rejimdeyim rejimde…', 'Hiç bir eşi yoktur hani,  Çemenin ahenkli dansı yumurtayla Sarmaş dolaş cilveli… Tadı damağımda, kokusu burnumda Elimi uzatsamda bi bandırsa...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cazibe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Tutkusu', 'deniz-tutkusu-sadik-altinkaynak-swxx9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman zaman soruyorlar bendenize

Şiir yazdın mı denizcilik üstüne denize

Yazayım yazmasına da deniz sığmaz dizelere

Ancak konu olur hikâyelere filimlere dizilere

Deniz sere serpe uzanmaktır altın sarısı kumlara

Deniz “rastgele” demektir sefere çıkan balıkçılara

Dalıp uzaklara gitmektir bir martının kanadında

Gelecek yolcuyu beklemektir bir iskelenin ucunda

Bazen yunustur ya da deniz kızı gemilerle yarışan

Bazen duygudur dalgalarla alabora olup karışan

Bazen hasret bazen gurbet bazen vuslat demektir

Deniz özgürlüktür maceradır uzaklara gitmektir

Kimi zaman dönüşü belirsiz hüzünlü bir vedadır

Kimi zaman  ayrılık sonrası tatlı bir merhabadır

Göz alıcı yakamozdur mehtaplı gecelerde

Sonsuzluk duygusudur şiirlerde hecelerde

Denizciler için “Dönülmez akşamın ufkudur”

Tüm zorluğuna rağmen vazgeçilmez bir tutkudur

Evet deniz bir tutkudur anlatılmaz yaşanır

Denizci zamanla değil hasretlikten yaşlanır', 'Zaman zaman soruyorlar bendenize Şiir yazdın mı denizcilik üstüne denize Yazayım yazmasına da deniz sığmaz dizelere Ancak konu olur hikâyele...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deniz-tutkusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıkla Sarmaş Dolaş', 'yalnizlikla-sarmas-dolas-aliye-onur-4mh7k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlığın ortasında; 

Yalnızlıkla derin sohbetlere dalıyorsan

Dinledikçe hislerini için titriyorsa

Kelimeler dudağının ucunda takılıp kalıyorsa

Boğazında bir sizi yanakların ıslanıyorsa

Derken tatlı anılar süzülüyorsa aklına

Ve bir tebessüm yayılıyorsa simana

Ne mutlu sana! 

Demek ki barışmışsın yalnızlıkla…', 'Karanlığın ortasında;  Yalnızlıkla derin sohbetlere dalıyorsan Dinledikçe hislerini için titriyorsa Kelimeler dudağının ucunda takılıp kalıy...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizlikla-sarmas-dolas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yel Götürür', 'yel-goturur-mahmut-ulusoy-5v1gf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hile düzme el kastine

Kırılmasın bak testine 

Bina kurma su üstüne

Birgün gelir sel götürür

Düşme muhannet toruna

Ne yapsan gelir yoluna

Sırrın söyleme karına

Kendir değil tel götürür

Sağlam temel yap yapını

Akşamdan kitle kapını

Harmanda koyma sapını

Tufan çıkar yel götürür

Sakın kimseyi horlama

Kendi suçunu korlama

Silahla boşa oynama

Karın kalır el götürür

Gülme MESULİ atana

Sabreyle sana çatana

Can feda eyle vatana

Her bir yana mal götürür', 'Hile düzme el kastine Kırılmasın bak testine  Bina kurma su üstüne Birgün gelir sel götürür Düşme muhannet toruna Ne yapsan gelir yoluna Sır...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yel-goturur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarım Leyla', 'yanarim-leyla-sedat-kocabey-65i45', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benden başkasına bakarsa gözün,

Çıldırır deliye dönerim Leyla.

Bu aşkın sonunda olursa hüzün,

Kahrımdan ölürüm yanarım Leyla.

Gurbetin kahrını bana yükledin,

Her mektubuna bin sitem ekledin,

Madem gidecektin niye bekledin,

Oluk oluk akar kanarım Leyla.

Umutlar yeşerttim vuslata dönük,

Perdeler çekili ışıklar sönük,

Döktüğüm yaşlara duvarlar tanık,

Yokluğun üşütür donarım Leyla.

Sonbahar kış dedin yaz da geçecek,

Bak yine çiçekler sensiz açacak,

Gönlüm kafesinden uçtu uçacak,

Günlerdir sevdamı sınarım Leyla.

Ahımı alanın yüzü güler mi,

Bu gönül arkandan hayır diler mi,

Sana son halimi söylediler mi,

Zannetme yıkılmaz çınarım Leyla.

Mecnunum aşkına düştüm düşeli,

Ben hep ağlamaklı sense neşeli,

Gönlüm bu gidişten çok endişeli,

Yine de adını anarım Leyla...', 'Benden başkasına bakarsa gözün, Çıldırır deliye dönerim Leyla. Bu aşkın sonunda olursa hüzün, Kahrımdan ölürüm yanarım Leyla. Gurbetin kahrı...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yanarim-leyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut...', 'umut-ali-baksi-5lexz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah pencerendeyim 

Yorğun bedenim düşlerimle

Bekliyorum yarım aşklarımı

Aydınlık bir gün gelirsin belki

Kusursuzu aramıyorum ben

Ama bekliyorum gelmelerini

Son durağında mahsumum

Kopsun fırtınaların dön artık

Gitmelerim yok artık benim

Ağlayamam artık binler daha

Seviyorsan sessiz gel bana

Dayanamaz yoksa yüregim

Penceremdeyim umudumla

Konuşmuyorum kimselerle

Dokunmuyorum yoklugunda

Seviyorum seni her ğün daha

Yılğınlığında sensizim

Sevğisizim sokağında

Gelmelerini bekliyorum

Umutla durağında...

Benim adım umut...', 'Bu sabah pencerendeyim  Yorğun bedenim düşlerimle Bekliyorum yarım aşklarımı Aydınlık bir gün gelirsin belki Kusursuzu aramıyorum ben Ama be...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umut-201-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vicdanına Danış', 'vicdanina-danis-mahmut-ulusoy-r3j5b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biraz dert yanmak konumuz

Köylerde yok okulumuz

Çıplak gezer çocuğumuz

Biraz vicdanına danış

Beraber ederiz savaş

Öyle değil mi arkadaş

İçte kıtlık dışta ataş

Biraz vicdanına danış

MESUL''sahip ol diline

Yalanı almış eline

Bakmaz köylerin haline

Biraz vicdanına danış', 'Biraz dert yanmak konumuz Köylerde yok okulumuz Çıplak gezer çocuğumuz Biraz vicdanına danış Beraber ederiz savaş Öyle değil mi arkadaş İçte...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vicdanina-danis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarem Yarenim Feryadım', 'yarem-yarenim-feryadim-aliye-onur-47s3g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büründüm yarelere,

Sürüklendim ötelere,

Ararken sevinçlerde, 

Yokluğa sarındım hüzünlerle...

Sevdayı buldum,

Yarenimle ahenkli söyleşlerde…

Yüreğim yangınlarla bekleyişte

Hele yar bana bir ses vere…

Son sözüm feryadımı dinleyenlere,

Yitiklerdeyim hükümlerle, 

Aman bu cana bi çare…', 'Büründüm yarelere, Sürüklendim ötelere, Ararken sevinçlerde,  Yokluğa sarındım hüzünlerle... Sevdayı buldum, Yarenimle ahenkli söyleşlerde… ...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yarem-yarenim-feryadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ele Bakma', 'ele-bakma-mahmut-ulusoy-vthwg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O gözlere kurban olam

Sakın dönüp ele bakma

Güneşten sakın kendini

Yazık olur yele bakma

İpekler giymiş üstüne

Sürmeler çekmiş gözüne

Kurbanlar kesim özüne

Akıp giden sele bakma

MESULİ ağlarsın diye

Korkarım ki nazar deye

Melekler onu beyene

Kurban olam güle bakma', 'O gözlere kurban olam Sakın dönüp ele bakma Güneşten sakın kendini Yazık olur yele bakma İpekler giymiş üstüne Sürmeler çekmiş gözüne Kurban...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ele-bakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Davet', 'buyuk-davet-sadik-altinkaynak-h2rgb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüce Mevlam sen çağırdın ben geldim

Bütün varlığımla dergâhına yöneldim

Bağışla günahım lütfu kereminle affet

Esirge nâr-ı cehimden Cennetini lutfet

Dünyanın dört yanından kopup geldi hacılar

Ak sakallı dedeler genç kardeşler bacılar

Her biri ayrı renk ayrı ırk ayrı dilden

Hepsi bir Allah’a niyazda aynı gönülden

Üstlerinde kefen misal ihramlar

Geride kalmış masiva günahlar haramlar

Terk edip gelmişler işi gücü evi barkı

Eşitlenmiş mevki makam zengin fakir farkı

Sanki kabirden döküldüler Meydan-ı Mahşere

Böyle eşitlik ancak orda nasip beşere

Kâbe güneş milyonlarca insan etrafında peyk

Tüm dillerde söz tek “Lebbeyk Allahümme Lebbeyk”

Tekbirler tehliller tesbihler dualar aminler

Kâinat efendisinin nurlu izinde mü’minler

Dönüyorlar etrafında tecessüm etmiş nurun

O Nur ki Arz’a izdişümüdür Beyt-ül Mamur’un

Misafir olmuşuz evinde Yüce Allah’ın

Bu duyguyla pervanesi olduk Beytullah’ın

Doyulmaz tavafa döndükçe dönmek istersin

Unutursun yaşamayı orda ölmek istersin

İlahi bu ne saadet ne lütuf ne kerem

İzin ver nasip kıl beytinde canım verem

Böyle ölüm bulursam yaşamayı istemem

Önümde Beytullah başucumda Havz-ı Zemzem

Çok şükür çıktık Arafat’a Vakfe’ye durduk

Kararmış kalbimizi gözyaşlarıyla yunduk

Arınmamız sürdü Müzdelife Vakfesiyle

Yer gök inledi hacıların “Lebbeyk” sesiyle

Sonra geçip Mina’ya şeytanları taşladık

Kurbanları kestik saç sakalı tıraşladık

İhramdan çıkıp yaptık Ziyaret Tavafını

Yedi defa dolandık Kâbe’nin etrafını

Yedi Şavt gidip geldik Safa-Merve arası

Nasıl ki gitmiş idi (Hz.)  İsmail’in anası

Malumdur ki Say denilir bu gidiş gelişe

Yaradan bir sebep bir hikmet halk etmiş her işe

Hacer Ana su aramış bu yolda (Hz)  İsmail’e

Rabbimiz Zemzemi buldurmuş Cebrail ile

Tahattur et bunu iç zemzemi kana kana

Ne niyetle içersen onu verir Allah sana

Bu minval üzere tamam olur hac farizası

Dökülür günahlar kazanılır Hak Rızası

Önce gitmeyen Medine’ye döner yüzünü

Ziyaret etmek için ol Resul-ü Güzini

Şimdi davet aldık kutlu belde Medine’den

Öylesine hafifledim kanatsız kuş gibiyim

Adeta gelmiş gibiyim dünyaya yeniden

Günah pasından kirinden kurtulmuş gibiyim

Göründü tüm ihtişamıyla kubbe-i Hadra

Şifadır hasret ateşiyle yanan her sadra

Sermest eder Mü’minleri bu nurlu abide

Tarifsiz sürur verir ehl-i iman her abde

“Sakın terki edepten” anıp Şair Nabi’yi

Kemal-i edeple kıl ziyaret Yüce Nebi’yi

Titrer insan görünce Ravza-i Mutahhara’yı

Çünkü sinesinde saklar Muhammed Mustafa’yı

Ayaklar tutmaz nabızlar durur heyecandan

Selat-u selamlar edilir yürekten candan

“Esselat-u vesselam-u aleyke ya Resulallah

Esselat-u vesselam-u aleyke ya Habiballah “

Ya Rabbi önündeyim şimdi Kabr-i Şerifin

Tarifi mümkün değil bu emsalsiz şerefin

Karşımda dostlarıyla Kâinatın Efendisi

İşte Ebubekir işte Ömer işte Kendisi

Geçsin tüm ömrüm bir lahza gibi huzurunda

Yıkansın günah yüklü kalbim havzı nurunda

Huzurundan hiç ayrılmam mümkün olsa tahakkuku

Mani buna sıradaki aşıkların hukuku

Ayrıldım hüznü keder içinde Efendimden

Ateş-i firakla geçmiş gibiyim kendimden

Elveda elveda Ey Resul-ü Kibriya

Şefaat et mahvetmesin bizi kibir ve riya

		

Gidiyorum ne yazık ki geldi vakti veda

Ruhum canım her şeyim olsun yoluna feda

Sen Fahr-ı Kâinat ben kapında aciz geda

Mahrum etma şefaatinden Dar-ı  Ukbada   a', 'Yüce Mevlam sen çağırdın ben geldim Bütün varlığımla dergâhına yöneldim Bağışla günahım lütfu kereminle affet Esirge nâr-ı cehimden Cennetin...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/buyuk-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün ve Gece', 'gun-ve-gece-aliye-onur-0rr5a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yitik saatler gündüzlere, sabrın özü gecelerde

Düşlerimiz ve hayalin güneşle sohbetlerde…

Yıldızlarla sarmaş dolaş, 

Gecenin sükutu ruhuma beste…

Ay sırdaş bu hicranda, 

Işığı ise yoldaş bekleyişte, 

Veba gibi birşey oldu bu ateş bedenimde…

Sitemim geciktiğin akşam saatlerine,

Kavuşmamız karanlığın sarılması evrene,

Buluşmamız parmak uçlarımızda yine…

Azar azar tükenişimiz doğan güneşin eşsizliğinde,

Eriyor zaman an be an kainatta sevgimizle,

Ant içtim sevence, canlar solmadan geleceğime…', 'Yitik saatler gündüzlere, sabrın özü gecelerde Düşlerimiz ve hayalin güneşle sohbetlerde… Yıldızlarla sarmaş dolaş,  Gecenin sükutu ruhuma b...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gun-ve-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanda irade var', 'i-nsanda-irade-var-mikdat-bal-1k1n0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsanda irade var, aklı var ilim de var

Görüyor gözetliyor, hayat var ölüm de var

Çok faydalı işler var, nefsine zulüm de var

Kurtulmamız gerekir nefsin esâretinden 

Bizler yoktuk var olduk, hayat veren biri var

Önümüze nimetler, yayıp seren biri var

Biz göremezsek bile, bizi gören biri var

Gafil olmamak lazım, Rabbin nezaretinden

Şeytan nefis el ele, bize tuzak kurmuşlar

Bu iki azgın düşman yolumuza durmuşlar

Ölüm var, ama bunu bize unutturmuşlar

Gunde yüz kez  dönsek te, kabir ziyaretinden! 

Bunca nimeti bize, acaba kim sağladı

Kim şöyle düşünerek, Allah için ağladı? 

Terkedildi ibadet, kalpler beton bağladı

Şeytan bile şaşıyor kulun cesaretinden

Bal der bizden aranan, ibadettir, imandır

Allah’a en makbul kul tövbe eden insandır

Dönelim kendimize tövbe anı bu andır

Kıymetli birşey yoktur, nefsin taharetinden', 'İnsanda irade var, aklı var ilim de var Görüyor gözetliyor, hayat var ölüm de var Çok faydalı işler var, nefsine zulüm de var Kurtulmamız ge...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/insanda-irade-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşim', 'kardesim-sedat-kocabey-r5aip', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretinle gönlümüzü kavurdun,

Et tırnaktan ayrılır mı kardeşim,

Kurumuş bir yaprak gibi savurdun,

Et tırnaktan ayrılır mı kardeşim.

Her mektubun bin bir özlem taşıyor,

Anam hasta son günleri yaşıyor,

Sanma adın dilimizden düşüyor,

Et tırnaktan ayrılır mı kardeşim.

İlkbahar mı yoksa bilmem kışa mı,

Bitir artık gurbet elde yaşamı,

Ettiğimiz onca dua boşa mı,

Et tırnaktan ayrılır mı kardeşim.', 'Hasretinle gönlümüzü kavurdun, Et tırnaktan ayrılır mı kardeşim, Kurumuş bir yaprak gibi savurdun, Et tırnaktan ayrılır mı kardeşim. Her mek...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kardesim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Demeden Yaşamayı Becerebilsek..(düz yazı)', 'keske-demeden-yasamayi-becerebilsek-duz-yazi-hulya-arisan-ffah7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluktan çıkıp, tam kendimizi bulmaya çalıştığımız andan beri,

bu koca sahnede oynamaya başladık seninle.

Sana da bana da roller verilmişti. yaşamlar sunulmuştu ama biz çok uzaktık.

Ne sen, ne de ben beyenerek oynıyamadık bize verilen bu rolları...

Belki yaşlarımızım küçük olması da etkendi. Herşey netlik kazanmamıştı,

hayatın ciddiyetine henüz vakıf değildik.

Yanlış olan neydi? 

Tabiikii belli....

Ayrı ayrı iyi insanlar olsakda farklı dünyaların insanı olmamız, çabuk verilen

kararlar....yıkılmak üzere olan beraberlikte kendimizin bile inanamadığı iki güzel çocuk.....oysa daha kendimiz büyümemiş kendimiz bir çok şeyi anlamamışken....

Şimdi seneler geçti ve artık sahneden inme vakti geldi....

Perde kapanacak, zaman doldu....

Birbirini anlamadan zevk vermeden tat almadan yaşanmış onca kıymetli süreç....bunların hepsi geçmişde anı olarak kalacak artık....

Eğer  bir şeyler kalmışsa yüreklerimizde bitmemiş,

gizli köşelerde tat alabilecek birşeyler varsa hala,

belkide yeniden filizlenerek yeniden başka biriyle can bulacak duygular....

Birde keşke demeden yaşamayı bilebilsek...

bilebilsek SEVGİYE sarılıp tat alabilsek.....

Istanbul  19 Ağustos 2005', 'Çocukluktan çıkıp, tam kendimizi bulmaya çalıştığımız andan beri, bu koca sahnede oynamaya başladık seninle. Sana da bana da roller verilmiş...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/keske-demeden-yasamayi-becerebilsek-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüşlerde', 'oluslerde-aliye-onur-p262c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakıyorum da dağarcığımdaki kelimelere,

Hislerimi anlatacak manalar nerede? 

Direniyorum dönmemek için başlangıca...

Son damla gücümde tükenmek üzere, 

Kaybettiklerime karşılık yine kaybedişte…

Sevginin yerini dolduracak olan ne? 

Hüzünlerde boğuluyorum hazince

Yakarışlarda…yalnızlıkta…ölüşlerde 

Geçen zaman yaşam mı sence? ...', 'Bakıyorum da dağarcığımdaki kelimelere, Hislerimi anlatacak manalar nerede?  Direniyorum dönmemek için başlangıca... Son damla gücümde tüken...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oluslerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-aliye-onur-eyiki', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damarlarımdasın

Beynimdesin 

Düşlerimdesin

Dudaklarımda ismin

En önemlisi yüreğimdesin

Yüzümde tebessümsün 

Hayat pınarım yaşama gücümsün

Şu fani dünyada yalnızlığımsın

Ulaşılmazım hasretliğimsin

Canımsin sen herşeyimsin', 'Damarlarımdasın Beynimdesin  Düşlerimdesin Dudaklarımda ismin En önemlisi yüreğimdesin Yüzümde tebessümsün  Hayat pınarım yaşama gücümsün Şu...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-615-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğa', 'dostluga-aliye-onur-5nbgl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Selamlara selam ola! 

Selam vermek yürektir, 

Bu can o yüreğe sahiptir…

‘Selam’ verenlere ve ithaflara 

Teşekkür saygıdandır…

Gözün ve dilin sadakatine inananlara, 

Ruh ve beden bütünlügü olanlara,

Çağrım var dostluğa…', 'Selamlara selam ola!  Selam vermek yürektir,  Bu can o yüreğe sahiptir… ‘Selam’ verenlere ve ithaflara  Teşekkür saygıdandır… Gözün ve dilin...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dostluga-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-aliye-onur-hiunz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın içinde kalabalığım

Sakinliğin ortasında karmakarışığım

Düşüncesizliğin içinde fikirlere boğulmuşum

Duyguların içinde hissizim

Bedenim ruhsuz ruhum bendensiz

Aşkım yüreksiz yüreğim sevgisiz

Hayat acımasız sen hayatsız

Kaderim sensiz ben bensiz…', 'Yalnızlığın içinde kalabalığım Sakinliğin ortasında karmakarışığım Düşüncesizliğin içinde fikirlere boğulmuşum Duyguların içinde hissizim Be...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olum-197-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Es ey bad-ı saba gönlümde pürgür dinsin', 'es-ey-bad-i-saba-gonlumde-purgur-dinsin-ali-riza-unal-nkf7c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Es ey bad-ı saba gönlümde pürgür dinsin

Can ile canân seyran oldu kevn-i mekâna

Şimdi açıldı hicâp sinemde inkâr sinsin

Sultan oldu zelili rüsva nefs,cümle cihana

-----     Şiirin tamamı değildir  -----', 'Es ey bad-ı saba gönlümde pürgür dinsin Can ile canân seyran oldu kevn-i mekâna Şimdi açıldı hicâp sinemde inkâr sinsin Sultan oldu zelili r...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/es-ey-bad-i-saba-gonlumde-purgur-dinsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla Beni', 'bagisla-beni-aliye-onur-5rsr4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın ve sessizliğin ortasındayım yine, 

Kaybolmak istiyorum, havaya karışmak 

Yağmurda damla olup Marmara`da dalgalarla buluşmak

Ne olursa olsun seninle olmak istiyorum İstanbul…

Üsküdar`da sahilde yürümek,

Yerebatan`da bir dilek daha tutmak

Sultanahmet`te turistlere yol tarif etmek,

Onlara Asya ile Avrupanın gerdanını 

Seni anlatmak istiyorum İstanbul…

İçim üşüyor be İstanbul…

Kadıköy`de sahilde demleme çayımı yudumlamak,

Eve dönerken vapurda martılarla simidimi paylaşmak,

Marmara`yla sohbet etmek istiyorum…

Tükeniyorum İstanbul…

Gerçekleri kabullenmeyi denemek,

Son buluşmamız üç günü hatırlamak,

Boğaza karşı yemek yiyip 

Kızkulesinin hikayesini anlattığımızı hayal etmek…

Topkapı Sarayı`nda tarihinin kanıtları,

Kapalı Çarsı, Ayasofya, Yerebatan Sarnıcı,

Beşiktaş, Dolmabahçe Sarayı derken,

Çemberlitaş`ta nargile ile

Hasret giderdiğimiz günü düşünmek…

O günlerin hayallerde ve resimlerde kalmadığına

İnanmak istiyorum İstanbul…

Kırgınmısın bana İstanbul…

Biliyorum iki yıl dolunca sana dönecek,

Kavuşmamızı Kız kulesi`nde kutlayacaktık

Ne yaptım ne ettiysem olmadı o günü yaşayamadık

Bağışla beni İstanbul…

Ancak anladım ki sensiz hayat hayat olmayacak

İçim daha cok acıyacak, yüreğim daha cok kanayacak…

Zaman hiç geçmeyecek, geceler uzadıkça uzayacak, 

Gözlerim kanla dolu, yakında kan damlaları akacak…

Biliyorum ki İstanbul! 

Senin koynunda uyumadan,

Ölmek bile huzur vermeyecek…', 'Yalnızlığın ve sessizliğin ortasındayım yine,  Kaybolmak istiyorum, havaya karışmak  Yağmurda damla olup Marmara`da dalgalarla buluşmak Ne o...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bagisla-beni-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişebilseydim…', 'degisebilseydim-aliye-onur-29rbm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, ben olupta bir defa anlatılanları dinleseydim

Yaşayıpta öğrenmeye yeltenmeseydim

İçimdeki o hırs damarını bir bulsaydım,

Ve bu çektiklerimin sebebini sorabilseydim…

Sakin limanlarda yasamaya bir alışabilseydim…

Söylenenleri anlasaydım ve yollara düşmeseydim. 

Bambaşka bir dünyaya rotamı çevirmeseydim.

Kader gemimi kabus ötesi fırtınalara sürüklemeseydim…

Sorun kaderim mi, yoksa ben miyim bilebilseydim…

Ah! Arkadaş bir değişebilseydim…', 'Ben, ben olupta bir defa anlatılanları dinleseydim Yaşayıpta öğrenmeye yeltenmeseydim İçimdeki o hırs damarını bir bulsaydım, Ve bu çektikle...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/degisebilseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırış', 'haykiris-aliye-onur-o7tt3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey kalbimin attığı, ruhumu besleyen şehir,

Son damla gücümle sana koşuyorum…

Duy sesimi İstanbul! Sana haykırıyorum… 

Son nefesimi koynunda vermek için geliyorum…', 'Ey kalbimin attığı, ruhumu besleyen şehir, Son damla gücümle sana koşuyorum… Duy sesimi İstanbul! Sana haykırıyorum…  Son nefesimi koynunda ...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/haykiris-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni çok özledim', 'seni-cok-ozledim-gulsum-cakir-ozumok-lx9z5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yokluğunu bilerek varlığını yaşamak ne zor şey

Seni çok özledim

Varlığında yaşatamadım, seni bana,

Bağışla,

Biliyor musun? 

 IIhhhh 

Nerden bileceksin ki! 

O gün hava alanında, 

Bana resmi kimliğini gösterdiğinde

Biliyordum, utancımın ardında saklanacağımı

Ama sen, 

Ah sen

Neden, alışmadığım kadar insandın? 

 İstanbul/Bostancı/1994/11/2235', 'Yokluğunu bilerek varlığını yaşamak ne zor şey Seni çok özledim Varlığında yaşatamadım, seni bana, Bağışla, Biliyor musun?   IIhhhh  Nerden ...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-cok-ozledim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dans', 'dans-gulsum-cakir-ozumok-11i5g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hey, dikkat

Ama ediyorum

Öyleyse daha çok etmelisin

Olur

Benim atalarım

Senin ataların

Esaret yıllarında

Evet 

İçlerini boşaltmak için

Nee! 

Vücutlarını kullanırlarmış

Nasıl yani

Dans ederlermiş

Kendilerini anlatmak için mi dans etmişler, tarih boyunca

Her halk gibi

Yaa

Örneğin sizinkiler

Ailem mi

Yapma

Tamam

Anadolu insanlarının dansları da ne çok şey anlatır

Atalarım Anadolu''dan 

Anadolu da benim ailem, ne haber

Haklısın 

Her zaman

Sen çok geniş bir aileye sahipsin 

Sen de öyle

Bak şu desene

Baktım

O da dansın büyüsüne kapılmış. 

Sizin büyük rakkase...

Kim

Birlikte izledik

Aaa evet

Hani sizin surlar var  ya, onun ikinci adı

Nesrin Topkapı 

Ohh evett o büyük dansçı

Bende de

Benim büyükannem gibi

Bizim gibi

Biz ve tüm aşıklar gibi...

Yanında özgürüm

Ben de özgürüm

Daha önce hiç özgür olamadım

Ben hep özgürdüm, atalarımın aksine, dans özgürlüktür

Dans özgürlüktür...

''Şekercik'', diyiverdi

''Tenim seninle yitti''

İstanbul/Suadiye/1989/09/04/1230', 'Hey, dikkat Ama ediyorum Öyleyse daha çok etmelisin Olur Benim atalarım Senin ataların Esaret yıllarında Evet  İçlerini boşaltmak için Nee! ...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/dans-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapma', 'yapma-ufuk-coban-776hz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda vurur gider gözlerine bir yaş damlasıyla,

Ayrılıkları koyar aksatmadan hergün hayatına,

Bir rüzgarla alır dökülen yaprakları uzaklara,

Beyazlıkların arasından sürükler seni bir kışa.

Bir başlangıç bulamazsın kendine kördüğümler arasında,

Ellerin kenetlenir kendine, uzanmaz hasat rüzgarlarında,

Düşler uyanır kimsesiz sabahların yastıklarına,

Güneş bile dokunmaz kimsenin dokunmadığı gözlerine.

Yasakları alsan kendinden bıraksan uzaklara,

Yerine umuttan bir bebek yapıp büyütsen korkusuzca? 

Dost olsan hayatla, gülsen, oynasan kaderinle,

Bir çocuk bıraksan içinde ve hiç çıkartmasan? 

Rastlarsın bir gün birine yıllardır beklediğin,

Korkularını hatırlarsın kaybetmeler üzerine,

''Doğru mu değil mi''ler üzerine gider aklın,

Kimseye soramazsın, diyemezsin içindekileri.

Gördüğün gülüşünü bakmıyorsa çek kendini gözlerinden,

Sevdiğini duymuyorsa boşuna dökme dilleri,

Saçlarında rüzgar olma dokunamıyorsan hayallerine,

Kalp atışını hissetmiyorsan dokunma kimsenin tenine.

18/08/2005 11:15', 'Sevda vurur gider gözlerine bir yaş damlasıyla, Ayrılıkları koyar aksatmadan hergün hayatına, Bir rüzgarla alır dökülen yaprakları uzaklara,...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yapma-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektup', 'sevgiliye-mektup-aliye-onur-rczy6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba hayatımın ışığı

Öyle zor oldu ki uyanmak bugün,

Aslında yine yataktan çıkmak istemedim… 

Yanımda olmayacaksın düşüncesi ile

Sensiz bir güne daha başlamak varya,

İçten içe tüketiyor beni.

İnanırmısın sabah sabah dakikalarca,

Hergün taktığım gözlüğümü aradım…

Baktım olmuyo vazgeçtim…

Bir günde göremesem 

Senin olmadığın dünyayı, ne kaybederdim…

Bir tatil sabahı kendini bilmezce,

Yataktan fırlayıp düştün mü yollara? 

Işte bu sabah; 

Yollarda aradım seni, kokunu, 

Sıcacık gülüşünü, bana sevgiyle dokunuşunu

Fırtınada rotasını şaşırmış gemi misali

Savruldum oradan oraya……

Yoktun hiç bir yerde, yoktun…

Yine yalnızlıktı bulduğum….. 

Ayağıma kramp girince saati merak ettim,

Telefonu aradım ceplerimde 

Onuda unutmuştum bir yerlerde…

Eve gelirken Nero`daki görevli seslendi

Meğersem dün orada bırakmışım telefonu 

İşte böyle canımın içi…

Sensiz günler böyle geçiyor…….

Aslında geçmek bilmiyor….', 'Merhaba hayatımın ışığı Öyle zor oldu ki uyanmak bugün, Aslında yine yataktan çıkmak istemedim…  Yanımda olmayacaksın düşüncesi ile Sensiz b...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgiliye-mektup-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzün Olur mu?', 'yuzun-olur-mu-halil-kesken-qn6tc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küstürdükten sonra sevenlerini

Son defa diyecek sözün olur mu? 

Terkettiğin için pişman olsanda

Özür dileyecek yüzün olur mu? 

Döneceğim diyorsun bir gün oraya

Tuz basma kapanan eski yaraya

Yıllar sonra tekrar gelip buraya

Merhaba diyecek yüzün olur mu? 

Geç kaldın diyemem, ne de çok erken

Hiç düşünmemiştin çekip giderken

Bu sonsuz öfkenin suçlusu senken

Sevgi dileyecek yüzün olur mu? 

21.02.1998', 'Küstürdükten sonra sevenlerini Son defa diyecek sözün olur mu?  Terkettiğin için pişman olsanda Özür dileyecek yüzün olur mu?  Döneceğim diy...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yuzun-olur-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sorumluyum', 'ben-sorumluyum-halil-kesken-rvymg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık vazgeç deyip bana hiç uyma

Yanlış bile olsa bu benim yolum

Kendini suçlayıp pişmanlık duyma

Zavallı halimden ben sorumluyum

Sen de hata yaptın beni severek

Yaşayan ölüye sevgi ne gerek

Kendimi mahvettim hemde bilerek

Zavallı halimden ben sorumluyum

Üç paralık gurur bitirdi aşkı

Her halim olumsuz her halim kuşku

Aşkına dar geldi gönlümün köşkü

Zavallı halimden ben sorumluyum', 'Artık vazgeç deyip bana hiç uyma Yanlış bile olsa bu benim yolum Kendini suçlayıp pişmanlık duyma Zavallı halimden ben sorumluyum Sen de hat...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-sorumluyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarıma', 'dostlarima-aliye-onur-wvl8l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey! Dostlarım sağolun… 

Gerçekten dost oldunuz. 

Aradaki mesafelere rağmen, 

Boşvermediniz benden,

Aradınız, sordunuz…

Bazen acı gerçekleri söylediniz,

Siz dosttunuz paylaştınız

Acı günümde yanımda olamadınız 

Ama aradınız,

Sevinçlerimde benimle değildiniz 

Ama hemen kutladınız…

Ne olursa olsun bu dostu unutmadınız…', 'Ey! Dostlarım sağolun…  Gerçekten dost oldunuz.  Aradaki mesafelere rağmen,  Boşvermediniz benden, Aradınız, sordunuz… Bazen acı gerçekleri ...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostlarima-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgün Değilim', 'uzgun-degilim-halil-kesken-364z3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum artık sen gidiyorsun

Hiç arkana bakma kızgın değilim

Sevdiğin biriyle evleniyorsun

İnan ki mutluyum, üzgün değilim

Boş ver bu anlamsız sitemlerime

Ne olur aldırma matemlerime

Sen bakma benim bu bitkin halime

İnan ki mutkuyum, üzgün değilim

Ağıt yakmıyorum gözyaşlarımla

Sevinçten akmıştır o birkaç damla

Sana da en içten duygularımla

Mutluluk dilerim, dargın değilim.', 'Biliyorum artık sen gidiyorsun Hiç arkana bakma kızgın değilim Sevdiğin biriyle evleniyorsun İnan ki mutluyum, üzgün değilim Boş ver bu anla...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzgun-degilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-deniz-onderoglu-7b1q2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamaksa, yaşayacağım

Sevmekse, seveceğim

Ölmekse, ölmeyeceğim

Seninle gözümü tekrar açtığım bu hayatı

Sevginle sürdüreceğim

Daha önce neredeydin, neredeydim? 

Gel 

Mutluluk bahçesindeki çiçekleri

Sevgimizle büyütelim

Arzularımızı birlikte gerçekleştirelim

Gel, gel ki; 

Asıl sevda nedir

Şu dünyaya gösterelim', 'Yaşamaksa, yaşayacağım Sevmekse, seveceğim Ölmekse, ölmeyeceğim Seninle gözümü tekrar açtığım bu hayatı Sevginle sürdüreceğim Daha önce nere...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevda-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Olsam', 'seninle-olsam-aliye-onur-qifvg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah! Bir seninle olsam…

Şöyle bir kanatlanı versem… 

Semaya doğru yükselip; 

Bulutların peşine takılsam…

Rüzgara yaren, kuşlara dost,

Yağmurla kardeş olsam… 

İçimdeki hüzünle damlayıp; 

Toprağı, ekinleri canlandırsam…

Çağlayanlarda coşup; 

Denizlerde akarak sana ulaşsam…

Güneşle selamlaşıp buharlaşsam…

Havaya karışıp, sabah meltemiyle; 

Kendimi yanında bulsam…

Yanağına öpücükler kondurup; 

Sana sıcacık sarılsam 

Ve hiç bırakmasam…', 'Ah! Bir seninle olsam… Şöyle bir kanatlanı versem…  Semaya doğru yükselip;  Bulutların peşine takılsam… Rüzgara yaren, kuşlara dost, Yağmurl...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seninle-olsam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yıllar', 'o-yillar-mehmet-emin-altun-sq766', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasıl başlamıştık biz o yıllar

Ucu bucağı olmayan kumsallar

Rüya gibiydi o güzelim anlar

Ard arda gelen şansızlıklar

Yaşanmadı sanki bütün o yıllar

Hani o güzellim koylar

Ağaçlarla kaplı yollar ve dağlar

Nerede kaldı o güzellim mekanlar

Işık gibi geldi geçti o zamanlar

Mazide kaldı bütün o yıllar', 'Nasıl başlamıştık biz o yıllar Ucu bucağı olmayan kumsallar Rüya gibiydi o güzelim anlar Ard arda gelen şansızlıklar Yaşanmadı sanki bütün o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Altun']::text[], 8.5, '{"poet":"Mehmet Emin Altun","poet_slug":"mehmet-emin-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/o-yillar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-gulsum-cakir-ozumok-5439k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkardım gelecekten, 

Saramazdım, 

Bildiğimden

Bildiğinden öte duygularımla seni

Kelebeklerimi 

Kozalarına 

Kilitleyip

Sadece 

Senin sevgini

İkimiz içinde

Tüketmeyi 

Öğretmiştim 

Sanırım, sen bilmeden, 

Sana

Ve

Bana

Belki

Bu sefer

Hayır

Belki 

Diyemeyecek kadar

Öğrendim artık.

Bu sefer

Cesurum

Umarım sen de

Bankosundur...

Kara adamı sevmenin bedeli

Bu olmamalı

Beyaz kadını sevmenin bedeli de

Pınarlarından gelen 

Kristallerin 

Olmamalı artık

Gülsüm Çakır Ozumok/İstanbul/ Sarayburnu/1988/Temmuz03/0215', 'Korkardım gelecekten,  Saramazdım,  Bildiğimden Bildiğinden öte duygularımla seni Kelebeklerimi  Kozalarına  Kilitleyip Sadece  Senin sevgin...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bedel-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreciğim', 'yurecigim-aliye-onur-a3wro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey! Yüreciğim küçücüğüm

Zor biliyorum dayanmak 

Güç hasretliği özümsemek

Yıprattı elemlere katlanmak 

Üzülme yüreciğim küçücüğüm

Dayanabildiğin kadar dayan

Duru ver gücünün yetmediği zaman

Duruver ki bitsin bu hicran

Anla ki yüreciğim küçücüğüm

Kaderimiz bu bizim

Ondan gayrıs düşlerim

Kalmadı bir damla takadim

Yorulma yüreciğim küçücüğüm

Sevince susamış umutlarım

Devasız bütün yaralarım

Sonu yok bu girdabın…', 'Ey! Yüreciğim küçücüğüm Zor biliyorum dayanmak  Güç hasretliği özümsemek Yıprattı elemlere katlanmak  Üzülme yüreciğim küçücüğüm Dayanabildi...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yurecigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Agustos Aksamı', 'bir-agustos-aksami-ali-aydogan-mok4x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine Sensiz Ve Sessiz Bir Agustos Aksamı 

Penceremden Süzüldü İceriye Umutlarım Usulca

CanLandı Hayalin YaşLı Gözlerimde Ansızın

Ellerim Yoklugunda Sıcacık Ellerini Aradı Umutsuzca

HüzünLü Bir Agustos Aksamı YanlızlıgımLa basbasa

Dolasırım Gözlerimde Sen İcimde Bir Umut Seni Bulurum Diye

Yoklugun AnLatıLmaz SanKi SensizLik YazıLmıs Anlıma Kaderime

İnan Sevdigim Doyamıyorum Sana Güzel GözLerine

Kosmak İstiyor Ayaklarım Sana Ucarcasına

Sanki DizLerimin Bagı Cözülüyor  Bitanem

Kahretsin Yine Sensiz Bir Agustos Aksamı

Aglamak Care Deyil CareLerim Sensiz 

Sanma Askım Güzel GünLer Yakın Bize 

Günes Bizim İcin Dogacak  Üzülme Bitanem

Yuvamızda YeşereCek Ask TanecikLeri

MutLuluk Kapımızda KöLemiz Olucak

Unutma Askım Bir Agustos Aksamı', 'Yine Sensiz Ve Sessiz Bir Agustos Aksamı  Penceremden Süzüldü İceriye Umutlarım Usulca CanLandı Hayalin YaşLı Gözlerimde Ansızın Ellerim Yok...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-agustos-aksami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevi', 'sevi-gulsum-cakir-ozumok-mbzm3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Can ötede

Sevi bende

Sevgi sende

Ten, terlerimizde

Alazlar içindeki 

Rakkase gibi,

Sevinin kollarından

Düşüverdi

Sevginin sonsuzluğuna

Ben sende

Sen bende

Ter…

Tende kaldı

İstanbul/Suadiye/1996/02/22/0430', 'Can ötede Sevi bende Sevgi sende Ten, terlerimizde Alazlar içindeki  Rakkase gibi, Sevinin kollarından Düşüverdi Sevginin sonsuzluğuna Ben s...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevi-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar ki!', 'onlar-ki-aliye-onur-595ji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan var güleç yüzlü içten mi içten; 

Ela gözlü, tatlı sözlü, bir damlacık sıcaklığa hasret…

İnsan var konuşmayı seven, özü dürüstlüğün; 

Solgun yüzlü, yorgun ruhlu, içtenliğe susamış…

İnsanlar var kader çizgisi buluşmuş,

Akılları ve yürekleri bir, hayat yolları ayrı mı ayrı...

Onlar konuştular yarınları, paylaştılar düşleri, saygıyı…

İnandılar birlikte yaşamaya bu hisleri… 

Zaman akıp geçti, an be an ruhlar kenetlendi…

Onlar ki! Sevgiye aç dünyada mutluluktu tek istekleri.

Unuttular gerçekleri, hatırlamak istemediler kaderi.

Kader unuturmu onları? Zaman doldu diyen gardiyan misali…

Bir bahar akşamı söndürdü gözlerdeki sevinç ateşini, 

Kader katıydı kurallara sadık, ayırdı yolları… 

Denediler birbirinden uzak hayatlara alışmayı

Öğrendiler gülmeye, içtenliğe hasret yaşamayı…', 'İnsan var güleç yüzlü içten mi içten;  Ela gözlü, tatlı sözlü, bir damlacık sıcaklığa hasret… İnsan var konuşmayı seven, özü dürüstlüğün;  S...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/onlar-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kozalar', 'kozalar-gulsum-cakir-ozumok-g1e8y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kozalarına

Kendi kendini kilitleyen

Kelebeklerin 

Primadonnası oluşuna

Ağladı,

Aklı

Kurtulan sadece

Sevgili rakkasesi değildi artık

Özgür bıraktığı kelebekleri, 

Dans ederken, leylaklarla; dalların ucunda, 

Kendini 

Geleceğini 

Özgürce yaşama kararı 

Anladı ki: 

Kelebekler 

Kozalarda kalmamalı, 

Gelecekteki yaşamın 

Zıplatıcısı oldurulmalı kozalar

Yeni

Kelebeklerin uçmakları  için...

Ankara/Çankaya/Esat/ bahar/1998/04/0645', 'Kozalarına Kendi kendini kilitleyen Kelebeklerin  Primadonnası oluşuna Ağladı, Aklı Kurtulan sadece Sevgili rakkasesi değildi artık Özgür bı...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kozalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla beni', 'bagisla-beni-gulsum-cakir-ozumok-39su8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dans ederiz birlikte

Atalarımız gibi

Altımızda yeşil

Üstümüzde mavi

Hep sevdim seni

Korkularım için

Bağışla beni

Gülsüm Çakır Ozumok/Ank./Çankaya/Esat/ 2001/Nisan30/0510', 'Dans ederiz birlikte Atalarımız gibi Altımızda yeşil Üstümüzde mavi Hep sevdim seni Korkularım için Bağışla beni Gülsüm Çakır Ozumok/Ank./Ça...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bagisla-beni-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalıktaki-YALNIZLIK', 'kalabaliktaki-yalnizlik-kemal-guzel-q4zxg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürüyor yorgun olsada dinç görünür.

Uçsuz,bucaksız hayal ederek,

yüreğine kazarak,acısını çekerek

mutlu görünür.

Ruhunda bir müzik dinler.

Dinlerki içi dert yanar.

Yüzünde tebesüm, 

iki eksik dişle gülerek.

Uzak düşünür,yakın konuşur.

Hayal kurar,gerçek diler.

Konuştukça gözleri susar...

Anlatan gözleri susar.

(aşkı...)', 'Yürüyor yorgun olsada dinç görünür. Uçsuz,bucaksız hayal ederek, yüreğine kazarak,acısını çekerek mutlu görünür. Ruhunda bir müzik dinler. D...', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalabaliktaki-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş Dediğin', 'arkadas-dedigin-halil-kesken-u2uzc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir eyvallah demeden çekip gittin işte...

Ben arkadaşlarıma böyle yapmam.

Tamam, ilahlaştırıp tapmam ama

Böyle de yapmam...

Üzülmesin isterim, kırılmasın...

Aman bir yanlışım olmasın,

Olmasın da bana darılmasın...

Arkadaş dediğine vefasız denmemeli

İsmi hayırsızla kirlenmemeli

Ben arkadaşlarımı ölesiye severim ama...

ama...

Benim için ölmelerini istemem...

Onun güldüğü zaman gülmeyebilirim ama...

ama...

Ağladığı zaman mutlaka ben de ağlarım.

Öpmem gerekirse öperim,

Tokat atmam gerekirse atarım

amaaa...

Benim de canım yanar...

O kadar ki, can çekişirim...

Zaten arkadaş dediğin candan olmalı

Aynı anda candan gülmeli,

Aynı anda candan sevmeli,

Aynı anda yaşamalı

Aynı anda ölmeli...

Arkadaş dediğin candan olmalı...', 'Bir eyvallah demeden çekip gittin işte... Ben arkadaşlarıma böyle yapmam. Tamam, ilahlaştırıp tapmam ama Böyle de yapmam... Üzülmesin isteri...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/arkadas-dedigin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan', 'unutulan-aliye-onur-azdod', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her beklentin için verdiğin son karar

Son değil, yeni bir başlangıç aslında! 

Baslangıçların ceremeside,

Kalın bir ip boyunda…

İpin ebatı bağlı kararın doğruluğuna. 

Elbette ki tüm amaç; 

Umutların filizini yeşertip,

Köklü bir agaç yapmakta…

İsin unutulan bir yönü, 

İpin ucu düğümlü ağacın dalında…', 'Her beklentin için verdiğin son karar Son değil, yeni bir başlangıç aslında!  Baslangıçların ceremeside, Kalın bir ip boyunda… İpin ebatı ba...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unutulan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-gulsum-cakir-ozumok-ksops', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi sadece sunulan

Ve

Sunulana geri gönderilenmiş

Anlayacağımız

Sevgi denilen şey

Şimdilerde bize sevgi diye verilene benzemeyenmiş.

Aşk gizilmiş 

Bir çiçeğin taç yapraklarının altındaki mikroorganizmalarda

Sevgi ise

Aşktan da  gizilmiş makroorganizmalarımızda

Bu yüzden zormuş

Bu yıllarda

Sevgiye ulaşmak

''Boş bir hayelmiş''

Elbette 

Sevgiyi 

Nerde 

Nasıl 

Gördüğümüz 

Önemliymiş 

Aslında

Sevgi bulmak adına

Sevgiye yüklüğümüz

Sevgi üretmek adına üretilemezmiş

Bunu anladığımız an 

Sevgiliyi sevgide bulduğumuz anmış

Amma

Bu sevgili sevgi hali

Anlam genliğinde

“Her şey bir lokma sevgi içindir”

Denildiğinde

Bulduğumuz sevgili sevgi bizi asla terk etmez miş.

Sen seni ve yüreğindeki sevgiyi terk etmedikçe

Ben 

Ve 

Sevgi 

Adına 

Varsılların 

Laaaaa

Orda kalırız sonsuza dek

Ürettiklerini aklın ile besler

Yüreğin ile sularsan

Duygu dünyan çoraklamazmış

Ankara/Çankaya/Or-an/08/12/0550', 'Sevgi sadece sunulan Ve Sunulana geri gönderilenmiş Anlayacağımız Sevgi denilen şey Şimdilerde bize sevgi diye verilene benzemeyenmiş. Aşk g...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sevgi-194-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ablacığım/Komedi Serisi', 'ablacigim-komedi-serisi-mehmet-akif-gulhan-85mik', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine haberin geldi hastahane köşesinden

Dedim, kaybetmez o hiçbir şey neşesinden

Alışkındır bir gün yatar,menüsküsten,

Bir gün yatar safra kesesinden

Hastahaneden çık ta salın gel ablacığım

Sensiz evin neşesi hiç olmuyor,

Annen hasta oldu evde yatıyor

Ne desek kanmıyor,inanmıyor

Sensiz, bayramlar bile,hiç çekilmiyor

Baklava hamurunu açta gel, ablacığım

Hanımlar toplanmış yine  altın gününe 

Hamur işi,mantı, koca tabak hepsinin önüne

İş dönmüş  oyuna,pokere,konkene

Haber saldılar dördüncü olur mu diye 

As döperi, jokeri, kapta gel ablacığım,

Cevap veremedik, seni sordu,torunlar kızlar

Vallahi özledik,burnumuzun direği sızlar

Düğün dernek kurduk,seni bekler defler,sazlar

Sen başımız tacısın,gel artık sevinelim bizler

Sar beline şalı,eline zilleri tak da gel ablacığım

Mehmet Akif Gülhan 10/11/2004', 'Yine haberin geldi hastahane köşesinden Dedim, kaybetmez o hiçbir şey neşesinden Alışkındır bir gün yatar,menüsküsten, Bir gün yatar safra k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ablacigim-komedi-serisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninleyim', 'seninleyim-timucin-ayaz-gthkf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana yazmak isterdim

Yalnızca sana.

Sen bul kendini bensizlikte.

Ben nasıl olsa 

Seninleyim.', 'Sana yazmak isterdim Yalnızca sana. Sen bul kendini bensizlikte. Ben nasıl olsa  Seninleyim....', ARRAY['Türk Edebiyatı','Şiir','Timuçin Ayaz']::text[], 8.5, '{"poet":"Timuçin Ayaz","poet_slug":"timucin-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seninleyim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşikler Boş', 'besikler-bos-ali-kilic-kakiz-klxdg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ürpertiyor insanı korkular, her gece.

Rastlarsın çığlıklar atan yaşlı gence.

Kalbim buruk gurbetteyim senelerce.

Gördüğüm hep yaşlı nesil beşikler boş.

Ay bile doğmuyor ışık yok, geceler loş.

İtilen sensin, koridorlarda koşta koş.

Akıl almaz, doğmatik düşünceler.

Arsız, hırsız, pirsiz  hora tepiyor beyler.

Gözümün yaşı kurumuyor, dilim söyler.

Brüksel / 1985', 'Ürpertiyor insanı korkular, her gece. Rastlarsın çığlıklar atan yaşlı gence. Kalbim buruk gurbetteyim senelerce. Gördüğüm hep yaşlı nesil be...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/besikler-bos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından Gelirmiş', 'ardindan-gelirmis-aliye-onur-vdrwv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk yüreğinin kıpırtısı,

İçini dolduran bir ışık, enerjiymiş…

Bacakların titremesi engellenemezmiş…

Ruhundaki fırtına, delilik, divanelik,

Kaybolmak, kahrolmakmış.

En güzeli dokunmadan yaşanırmış.

Gözgöze bakıpta eriyip gitmek,

Sonsuzlukta yok olmakmış…

Evrende tek varlık olma hissini tatmakmış…

Aşk kalpte başlayan

Ve tüm vücuda yayılan bir virüsmüş.

Öyle ki kanattıkça kanar,

Seni yaktıkça yakarmış.

Güneş gibi yalnızlıkta haz bulurmuş.

Aşkını yüceltip, yaşatmak için,

Mesafelere aldırmazmış.

Kendi cayır cayır içten içe yanarken,

Aşkını ısıtırmış ama yakmazmış…

Elbet bu yangının birde sönüşü varmış,

Kül olmak demek ölmekmiş.

Sonrada aşkım dediği ardından gelirmiş...

Ve aşk asla bitmezmiş…

Ya biterse diye düşünüyorsanız, 

Biterse aşk aşk olmazmış…', 'Aşk yüreğinin kıpırtısı, İçini dolduran bir ışık, enerjiymiş… Bacakların titremesi engellenemezmiş… Ruhundaki fırtına, delilik, divanelik, K...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ardindan-gelirmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanında', 'yaninda-volkan-yoruc-2blta', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimden düşsende dilimden düşmezsin

Usulca gözlerim seni

Sen bilmesende

Belki yağmura yakalanırsın

Yanında ben olmam, ıslanırsın

Elimden düşsende fikrimden düşmezsin

Usuldan da öte gözlerimdesin

Gün olur beyazlar içinde üşürsün 

Yanında ben olmam, üşüdükçe beni düşünürsün

Burnun kızarır elin morarır

Ben olmam, hayalim seni belki ısıtır

Elimden düşsende zikrimden düşmezsin

Usule aykırı düşlerim seni

Belki güneşin alnında yanarsın

Yanında ben olmam, o anın tadını çıkaramazsın

Kimse bakmaz yüzüşüne

Yahut o masum gülüşüne

Derinden bir ah çekerde duyuramazsın

Çünkü seni bir ben anlardım

Ama sen anlayamazsın

Çünkü yanında ben olmam

Sevdanın adını gayrı anımsayamazsın', 'Elimden düşsende dilimden düşmezsin Usulca gözlerim seni Sen bilmesende Belki yağmura yakalanırsın Yanında ben olmam, ıslanırsın Elimden düş...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yaninda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Girdabı', 'siir-girdabi-kamber-bal-b9jmp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir girdabına girdim bu gece

Sürüklüyor beni alabildiğine

Acımasız yokluklar içinde

Mısraların derinliğinde

Yok olup gidiyorum ağır ağır

Kendi benliğimde

Yok anlatmaya dili derdini yakamozların

Zıpkın yemiş akvaryum balıklarının

Şiir girdabına girdim bu gece

Anıların elinden

Hurilerin belinden

Ozanların dilinden

Kopup geliyorum ağır ağır gizlice

Yok anlatmaya dili derdini yakamozların

Zıpkın yemiş akvaryum  balıklarının

Şiir girdabına girdim bu gece

Alev alev yanan mısralar içinde

Doğmak işkence

Yaşamak işkence 

Sevmek işkence

Aslında yürüyoruz yine de ümitsizce

Bence

Yok anlatmaya dili derdini yakamozların

Zıpkın yemiş akvaryum balıklarının

Şiir girdabına girdim bir kere

Çıkamam artık binlerce sene

Nazım’lardan Arif’lerden bulaştı

Bu onulmaz Bal yüklü leke

Anladım aslında kendimni

Kendi benliğimle', 'Şiir girdabına girdim bu gece Sürüklüyor beni alabildiğine Acımasız yokluklar içinde Mısraların derinliğinde Yok olup gidiyorum ağır ağır Ke...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/siir-girdabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Güzel', 'hayat-guzel-volkan-yoruc-w801j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şehir karaldı yine

Işıklar söndü renklerin üstüne

Bende yine sonsuz yakamoz düşleri

Yine esti daralmaz soluk dolu hayaller gönlüme

Bu ne bir veda nede başka bir eda

Sevdam defterimde, kalemimde

Ne gözlerine ne sözlerine

Ben hala yaşıyorum kadim şehrimde

Ve mutluluk var dilimde

Sen olmasan neye yarar diye düşünmem kendimce

Şehir karaldı yine üstüme

Gülümsüyorum 

Hayat güzel

Özlüyorum

Ne de güzel

Hüzünleniyorum

Renkler hala bende

Gökmavimde asılı durur oynaya oynaya

Özlemekte güzel, sen bilemesende

Hala coşkun deli denizler 

Hoyrat tepeler, rüzgar kırmaz ovalar benle

İnsanın doğası geliyor yine inan be 

Ey kavgalaştığım bakkal

Ey unutan sen

Siz bilemesenizde hayat benle

Renkler yine sabahları açıyor gözümde

Ey everestteki kızlar, boya küpüne düşmüş yüzler

Siz umursamasanızda dipte hayat benle

Elimde anılardan kalma sarı sayfalar

Dilim aşınmaz okurum tekrar tekrar

Gönlüm yorulmaz doyasıya doğarım yine hasbelkader

Hayat renklerde yaşar 

Yüreğim renklerde yaşar

Ben hayatla coşar

Şehir karalmış çokmu

Adımlarım hala yürüyorsa 

Hala nefesimi veriyorsam hayata

Gönlüm durulmaz doyasıya doğarım hasbelkader hayatın her anında', 'Şehir karaldı yine Işıklar söndü renklerin üstüne Bende yine sonsuz yakamoz düşleri Yine esti daralmaz soluk dolu hayaller gönlüme Bu ne bir...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hayat-guzel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişin peşine düşüp...', 'gecmisin-pesine-dusup-yusuf-ziya-leblebici-j51r1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün geçmişin peşine düşüp

kendini sorgulayacaksın.

Daha dün gibi kaybettiğin uzun yıllarını

saymaya başladığında,

inan çok şaşıracaksın.

İlk adımın,

gençlik çağın,

ilk sevdan

gözlerinde canlanınca

yılların hızına kızacaksın.

Kızacaksın, 

pişmanlık duyduğun zamanlar

gelince aklına...

Eski fotoğrafları karıştırdıkça

ölenleri, yaşayanları ayıracaksın

sen de kendini bir yere koyacaksın.

Bazen, bir eziklik saracak seni

ezilmişliğin acısıyla ezişini anacaksın

işte o zaman kendinden kaçacaksın.

Terazinin kefesine doğrularınla

yalanlarını koyduğunda

ağır basan yalanlarına şaşacaksın.

Bir gün geçmişin peşine düşüp

kavgalara dalacaksın.

Yaşam kavgasının ideolojinle kardeşliğini

anti''lerin düşmanlığını tekrar yaşayacaksın.

Yüreğindeki dağlarda eşkiyalaştığını

damarlarında haramileştiğini andığında

bir mavzer kurşunu saplanacak göğsüne,

göğsündeki dünlerine! ..

Artık basmayacağım diyeceksin mayınlara

kaymayacağın diyeceksin raylarda.

Ama; yıllanmış bir çınar olmuşken

dönemeyeceksin toy bir fidana

dönemeyeceksin andığın o geçen yıllara...', 'Bir gün geçmişin peşine düşüp kendini sorgulayacaksın. Daha dün gibi kaybettiğin uzun yıllarını saymaya başladığında, inan çok şaşıracaksın....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gecmisin-pesine-dusup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N''olur...', 'n-olur-yusuf-ziya-leblebici-mm3ky', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan gibi insan olduktan sonra 

Kırkına merdiven dayasan n''olur 

Umudu önüne koyduktan sonra 

Yolunda tuzaklar bulursan n''olur 

Kula kulluk etmek günahtır günah 

Padişahtan büyük Allah var Allah 

Kendini bilirsen yolların mübah 

Zalimlere karşı koyarsan n''olur 

Yoksula bir omuz verdikten sonra 

Zevk ile sefalar dolar ruhuna 

Dostları dost gibi sevdikten sonra 

Karşına düşmanı doldursan n''olur 

Ekmeği bölüşmek bize keyf verir 

İnsanları sevmek bize denk gelir 

Haklının hakkını verdikten sonra 

Haksızın şeytanı olursan n''olur 

Yusuf Ziya der ki, yaşından korkma 

Yıllar geçer ama sen bak yarına 

Allah durur iken tapma kuluna 

Kullara kulluğu bozarsan n''olur', 'İnsan gibi insan olduktan sonra  Kırkına merdiven dayasan n''olur  Umudu önüne koyduktan sonra  Yolunda tuzaklar bulursan n''olur  Kula kulluk...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/n-olur-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serenat VII', 'serenat-vii-yusuf-varol-0bf0b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mavi kokuyor bütün kentler,ıslaklık çoktan sinmiş her yere

Dolaşıyorum bir başıma ihtimal, sınıra kadar.sıçrayışlar bozuyor suyun dinginliğini morca bir duman çöküyor kendi renginde ellerime ellerim yalnız, yalnızlığın ihtimali sınıra kadar. Tozlanmış imgeleri serpiyor karanlık, çiseleniyorum.Çiseliyorum ağır ağır küllere, morca bir duman çıkıyor içimden yanaklarının siyahlığında kayboluyor. Kül birikintilerine çise düşüyor resmini çiziyorum,son sınıra kadar yalnızım, duyumsuyorum.

                Bu kent ölü bir kentse  kaybettiğindendir, kazanan da yoksa buğusu kurumuştur ıslaklığın...', 'Mavi kokuyor bütün kentler,ıslaklık çoktan sinmiş her yere Dolaşıyorum bir başıma ihtimal, sınıra kadar.sıçrayışlar bozuyor suyun dinginliği...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/serenat-vii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhabbet Ilsa', 'muhabbet-ilsa-mustafa-gokcek-hhf9f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'MUHABBET ILSA

Yaklaşınca insan, gözlerinde ışıldıyor

Hani insanın bir içimlik, 

Su tasında bal şerbeti içercesine

Nemli ve bulutların üzerinde

Çok aradım, çok bekledim

Sahilde, poyraz esen bir rüzgâr

Ve bu sıcakta buluşan kavruk tenler

Bir şarkının coşkun nağmeleri gibi

Gözlerimi ıraklara düşürdüğümde

Yüreğimin çırpıntısıyla buluştu gözlerin

Uzunca bir bekleyiş ve manevra

Faydasız değilmiş, rotam artık muhabbet ılsa! ...



12.08.05                                      M.Gökçek', 'MUHABBET ILSA Yaklaşınca insan, gözlerinde ışıldıyor Hani insanın bir içimlik,  Su tasında bal şerbeti içercesine Nemli ve bulutların üzerin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/muhabbet-ilsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A b y s s', 'a-b-y-s-s-yusuf-varol-ld0wh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öl beni hüzün yanım

olmayan bir esmerliğin serabını yaratıyorum

olmayan bir nehrin akışında boğulmak üzre 

duy! .. 

siyahın tanrısallığı,

cehennemi bir kahkaha bu

Ben beni sende öldürmeliyim

sen beni,kendinde öldüremeyecek kadar güzelsin

öl beni,ölüm ürkünç olmasın 

Ben,sende öldürmeliyim kendimi

Kahkaham ağlayışa dönüşmesin.', 'Öl beni hüzün yanım olmayan bir esmerliğin serabını yaratıyorum olmayan bir nehrin akışında boğulmak üzre  duy! ..  siyahın tanrısallığı, ce...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/a-b-y-s-s-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leş Kokar, Üzgünüm Nietzsche', 'les-kokar-uzgunum-nietzsche-yusuf-varol-tyedz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çürüyenin salgıladığıyla yaşamak,

Ne üzücü ne ağlayış 

ne bilmektir bu deşen bir farkına varış

ne kahır koku’yu sevenlerle aynı çağda olmak

değil yaşamak… 

Reddin katılığı saydamlaştı.

Renge bakıp neşelenmenin sevinci kalbimize doğsa bile, 

rengin altında gezinenler yok görünenler kadar

Görünenler çürümeyi yücelttiler…

Defni gecikti kierkegaard.

Üzgünüm,leş kokar

Ağlayarak söylüyorum bunu 

Sonsuza dek kalıcı bu buğu.', 'Çürüyenin salgıladığıyla yaşamak, Ne üzücü ne ağlayış  ne bilmektir bu deşen bir farkına varış ne kahır koku’yu sevenlerle aynı çağda olmak ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/les-kokar-uzgunum-nietzsche-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir buluta uydum', 'bir-buluta-uydum-ulas-guleviz-klou4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir  buluta  uydum  sırtüstü  uzanıp  uyudum...

Sonra  bir  kuş  olup  dağlara  kondum.

Kış  geldi  göç  etim, 

deniz  üzeri  süzüldüm, dağları  geçtim.

Sonra, sakin  bir  koyda  güzel  bir  kulübe  buldum,

düşe  saldım  kendimi  ve  bir  sürü  düş  buldum...

Düşlerimi  kucağıma  aldım, uyudum.

Sabah  oldu, gün, güneşle  doldu,

Güneş `in  parıltılı  kolları, suya  vurdu, 

gözlerim  daldı, içim  yandı, ağladım.

“ Gitme  vakti  geldi,”  rüzgar  doldu  kanadıma,

 rüzgarın  kanatlarına  takılıp  süpürdüm  caddeleri.

Sonra  yağmur  çaldım  bulutlardan,

 toprağa  verdim, yoruldum.

Sonra, bulut  bulut  oldu  gözlerim

ve  hüzün  doldu  içim, ağladım.

Rüya  gibi  bir  ömür  geçti  gözlerimin  önünden, 

ama  gördüklerimi

yaşamadım.', 'Bir  buluta  uydum  sırtüstü  uzanıp  uyudum... Sonra  bir  kuş  olup  dağlara  kondum. Kış  geldi  göç  etim,  deniz  üzeri  süzüldüm, dağl...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-buluta-uydum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B e y a z b a y r a k', 'b-e-y-a-z-b-a-y-r-a-k-ulas-guleviz-aqxo7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğim

Çekti  beyaz  bayrağını

Açtı  perdesini 

Ve  artık  sana  teslim

dahası  bir  boşluktayım

Şimdi  geceyi  izliyorum

Ve  güneşin  öteki  yüzü  ay

Ve  gözlerimin  arkası  sen 

Şimdi  yağdı  bulut

Kırıldı  ay

Dondu  gün

Ve  beklemek  şimdi 

bir  baston', 'Yüreğim Çekti  beyaz  bayrağını Açtı  perdesini  Ve  artık  sana  teslim dahası  bir  boşluktayım Şimdi  geceyi  izliyorum Ve  güneşin  ötek...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/b-e-y-a-z-b-a-y-r-a-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm’dü Ertelenen', 'olum-du-ertelenen-yusuf-varol-bj2q1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur,

Yine aynı masumluğunda kalmalı

O 

Nefesleşemeyen sözcüklerin damlasıdır

Düşerken saçlarından tenine,

gözlerinin yerde kalışını neye yorabilirim ki

Ahh Ulaşmak! …

ulaşamamanın korkunç çiziği çekildi düşlere

bir ölümdü sanki sensizliğim,

birdi ölüm ve sensizliğim…

Deniz öylesine durgun ki 

o azgın dalgaları sanrılaşırken ben,

sana uzanan yüreğimin ağlayışını dizginliyorum

Dur diyorum, 

kanamanın sırasıdır; 

esmerliğine düşen donuk  yüzünden üç damla gözyaşı koparıyorum 

dudağımın çatlağında nefes oluyor

ve üç damla acı emiyorum 

dilimi eritiyor.

Ey karanlığım! ...

O durgun bekleyişin dudağının eksilişini doğuruyor bilesin

Kopardığın her parça et, 

uzaklığın sancısını çoğaltıyor

sancılarsa özlemi büyütüyor.

Kanamalı bir bakıştı geçen şu zaman

Yürekte cam parçalarının gezintileri

geçtiği her yol bir sürtünüş.

Her ilerleyişinde yarık bir iz bırakıp

koyu damlasını elime düşürüyor…

Yine resmini çiziyorum aklımın suyuna bulaştırdığım

Ve diline, 

bir damlasını konduruyorum elimde parlayan ışığın', 'Yağmur, Yine aynı masumluğunda kalmalı O  Nefesleşemeyen sözcüklerin damlasıdır Düşerken saçlarından tenine, gözlerinin yerde kalışını neye ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olum-du-ertelenen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şakağımda...', 'sakagimda-ayse-i-smetoglu-ldgiu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şakağımda 

serin bir dokunuş 

gözlerin akıyor

...

hissediyorum 

...

hani ıssız koylarda biten 

yosun yeşili gözlerin 

es geçiyor kirpiklerin tenimi 

sarıyor beni bir titreyiş 

öylece sebepsiz

mevsimsiz öylece 

üşüyorum...

şakağımda 

ince bir inilti 

o sahipsiz beste için ağlıyor notalar

...

duyuyorum

...

sana söylediğim türkü 

can çekişiyor mazide 

hani '''' gaybana gecelere oy ''  derdi ya ozan 

tebessümlü biraz 

biraz acıtan 

melodiler kapıyor ağızlarını 

öylece kimsesiz

nefessiz öylece 

ölüyorum...

şakağımda 

yorgun bir nem

bir zamanlar avucuma gömdüğün gül

şimdi döküyor yapraklarını damla damla 

...

ıslanıyorum

...

bu yağmur 

'' kal '' diyen soysuz naralar 

çiseliyor hatrıma 

siliyorum gül kurusu renkleri 

soluk öylece 

öylece gri

gömülüyorum...

şakağımda 

ayak sesleri 

kabusça bir dönüşün 

gölgesiz adımları yaklaşıyor 

...

görüyorum 

...

yaklaştıkça kararsızlık,

yaklaştıkça nefret,

yaklaştıkça aşk..

taş kesilmiş parmakların 

ucuna varıyorum! 

sıyırıp intiharları tetikten 

karanlık namlularda 

öylece takatsiz

sahipsiz öylece 

kayboluyorum...', 'şakağımda  serin bir dokunuş  gözlerin akıyor ... hissediyorum  ... hani ıssız koylarda biten  yosun yeşili gözlerin  es geçiyor kirpiklerin...', ARRAY['Türk Edebiyatı','Şiir','Ayşe İsmetoğlu']::text[], 8.5, '{"poet":"Ayşe İsmetoğlu","poet_slug":"ayse-i-smetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/sakagimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindanda Yenildi Ölüm', 'zindanda-yenildi-olum-ercan-cengiz-wep60', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zindanda Yenildi Ölüm 

Gezginliğimin patikasına girmiş

Bir ucundan diğerine ülkemin

Her karış toprağında çizilmiş güzergahları 

Olunmazdan geçilmiş yolu 

Patikalarla

Vietnam tunellerinden gelen

Ho Chin Minh''nin öğretisi.

Güneşi kucaklamaya ustaca, hepsinden önce

Güneşe kaldırırlardı kollarını 

Ezilmiş yürekleriyle bin yılların 

Beşer-onar 

Gruplar halindeydiler...

Ustaca kalkılırken güneşi selamlamaya

Günüydü bir başka mevsimin günü

Sıkılırken yumruk, haykırılırken

Sabırlı adımlarla katılırken diğerine,

Tereddütsüzce...

Ve karanlıktan koparıp almak için geleceğini

Şafak boyu sürecekti, hücre hücre

Söküp alıncaya 

Uzayacaktı da patika,

Parça parça olmuş ülkemde.

Patikadan sesler yükselir toprağın yüzüne

Çağın yaratımı kaplarken ince bir esintiyle

Ölümün üstünü 

Diyarbakır zindanında yenildi 

Ölümün kendi,

Ölümün donuk yüzüne de diz çökülmezdi

Aman dilenmezdi asırların kirine, 

Pasına da

Dosta-düşmana öğreti 

O yüce dirençle

Okşanırken Zeynel''in kahkahasında

Vadileri Dersim''in, 

Akarsuları ve toprağın ezgisi.

Ve patikadan sesler yükselirdi suyun sesine

Dirençli yüreklerle taşınıp

Tarihe damgasını vuran, 

Yaşatan bir ezgi

En amansız zamanlarda,

Yaşanılmazlığı 

Çarkın ihanetinden çıkarıp

Yaşanılır kılandı.

Çarkın dişlerindeki ezili yürekleri 

Ve ateş içinde kavrulmuş

Yitik kalbin ezgisiyle 

Sıkılı yumruk.

Yaşamın kendiydi ezgilerde, 

Sevdanın kendi 

Direnciydi 

Meşenin inadındaki damarın 

Yüreğiydi-ruhuydu

İradesi... 

Suya doymuş toprakların 

İnsana ait ne varsa, 

Yaşanılır kılan

Yaşanmazlıkları,

Çağdaş Kawa''nın öfkesiydi, 

Zindandan yükselip

Karanlığın üzerine düşen 

Bu toprağın ezgisi

Üç kibrit,

Patikalardan coğrafyalara taşırken

Ayak izlerini

Suyun sesi, 

Dağın sesi gelirdi kulaklara

Ve inançlı yüreklerde dokunurken 

Yarınlar kalırdı 

Yarınlar ezgili yüreklerde...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'Zindanda Yenildi Ölüm  Gezginliğimin patikasına girmiş Bir ucundan diğerine ülkemin Her karış toprağında çizilmiş güzergahları  Olunmazdan g...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/zindanda-yenildi-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlikten Bir Anı...', 'genclikten-bir-ani-mehmet-osman-erol-unal-5fbud', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar zâlim - miş meğer

Şu zaman denen ''şey''

Eriyor, yok oluyor avucunda 

Güvendiğimiz her şey...

İnsan,

Farkedemiyor gençlikte 

                                  - olup biteni -

Deli oluyor yürekler, ruhlarsa serseri...

Kafa tutardık gölgemize 

                                  - olur / olmaza - 

Heyecan sınırsız 

Arzularsa dur-durak bilmezdi...

Günler uzun olur gençlikte

Gecelerse güvenilmez ve kararsız

Kış bitmek bilmezdi

Erken varmak isterdik o yüzden hep yaza

Yaz...

Sevgili demekti...

Aşk demekti, sıcaktı...

Yeni yeni şarkılar çıkardı hiç duymadığımız

Bütün şarkılar ezberlenirdi 

Ne varsa aşk üstüne

                                   - anlamlı / anlamsız -

Boş verirdik gerisine

                                   - önemliye / önemsize -

Sonra? .. sı yoktur gençliğin...

Gençlik,  ah o gençlik...

Sevenlerimiz ve sevdiklerimiz vardı

                                   - gizli, saklı, uzak, yakın -

Ve canlarımız

Anne, baba, kardeş

Onlar,

Hep yanımızda olacaklar diye umduklarımız

Onlar, 

Şimdi pek çoğunu sevgiyle, hasretle andıklarımız... 

Her şey bizim içindi ve öyle kalacaktı

Bizim için dönüyordu sanki dünya

Bizim için doğuyordu her sabah güneş...

Genç olmak güzeldir evlât...

Ancak kıymetini bilmezsen 

                                    - vay, aman -

Öylece akıp giderken zaman

Ah, vah demeye kalmadan

Bir de bakarsın ki...

Bir gün...

                                   - vakit tamam -

Ve...düşünürken 

Yol uzun, zaman çok, vakit daha çok erken 

                                  - her şey bitivermiş - 

Sen,

Yine her zaman ki yerinden 

Doğacak güneşi beklerken...

...........

Böyle anlatmıştı bana bir gün

                                    - bir yaşlı adam -

''Ömür nedir? '' diye sorduğumda...

Kim di o yaşlı adam

Neden sormuştum...

Hiç hatırlamıyorum neydi konu

Zaten... bir daha hiç görmedim onu...

(İstanbul, Ocak 1972)', 'Ne kadar zâlim - miş meğer Şu zaman denen ''şey'' Eriyor, yok oluyor avucunda  Güvendiğimiz her şey... İnsan, Farkedemiyor gençlikte          ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/genclikten-bir-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum değil....', 'dostum-degil-i-brahim-tolga-ozsoy-bq1gm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sahte bir azizi müjdeliyordu şenlik ateşleri,

ve çılgınca içip dansediyordu günahkarlar.

Aralarından geçerken gözlerimdeydi onun sözleri,

sözlerimde onun kara gözleri yanar

bu yalnızlıkta her soluğum onun yolunu izlerdi.

Adı Özgürdü  ve gözleri alev gibi süzgündü.

Dostum derdim ona ama artık dostum değildi.

Yoldan çıkaranın soyu saz çalıp yasak söylerken,

anımsardım çilingir süslü maphus kokulu geceleri.

Biz kadeh kaldırırdık günahkarlar dansederken.

Depremler,kavgalar,ölümler sarardı bu şehri,

dimdik durup anıları izlerdik geceler sinsice firardayken.

Urfalıydı aslen ve inatçıydı evsiz sözleri,

Dostum derdim ama artık dostum değildi

Umutlarını ''her zaman'' a yatıranlar ''bazen'' leri umamazlar.

Bazenlerle toplar, kimi zamanlara yayardık dostluğu.

İki elin zincirlerini tatmışlar, sevgiyi zamanda aramazlar.

Zamanı tek testiden içer, uzun yolda kırardık suskunlugumuzu.

Ayrılıklar espiriydi hayatta, güçlenirdi halkaları ayrıyken yaşamlar.

Severdi kimisini benden dolayı, severdi beni ondan dolayı.

Dostum derdim her kelamımda ona, belki artık dostum değildi.

Kanım aksa mazgaldan akar, lağıma aksada ona akar.

Yüzleri gözükmeyenleri bulursam gönlüme katar,

Onun yanlış dediğini doğru sayar,

Elinden öldüğüm her gün, ona yasalanarak yeniden doğar,

Ama bir gün olsun ona dönmeden ne tok kalır ne göçerdim.

Bir zamanlar yanılıp, ona dostum derdim

Dostum değildi artık, şüphesiz kardeşimdi o benim.', 'Sahte bir azizi müjdeliyordu şenlik ateşleri, ve çılgınca içip dansediyordu günahkarlar. Aralarından geçerken gözlerimdeydi onun sözleri, sö...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tolga Özsoy']::text[], 8.5, '{"poet":"İbrahim Tolga Özsoy","poet_slug":"i-brahim-tolga-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dostum-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-elazigli-mustafa-kaya-zj7yk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'derin bir acı ile okudum.. 

sesimin titrediğini yüreğimle.

yazabildiğin titrek notlarına düşen göz yaşlarını...

kimse yoktu,

bir kez daha sesli okudum...ve seninleydim...yanımdaydın.. 

sımsıkı sarılıp bedenime...kollarını çözmek bilmedin.. 

yüzüne inen nur beni de aydınlattı... 

senden çok ben ağlıyordum... 

sana hava gibi...su gibi..gelmiş olmak... 

benimle hayata bağının devamı demek oluşum..

dışarıdaki tek soluduğun olmak...ve seni ayakta tutanın ben... 

evet ben senin biriciğin kalmak... 

tek güzel şey dediğine ağlayışım...

bir mahkum gibi baktığında dışarı

orada sadece beni bulmuş olmana dayanamam.. 

ve seni şimdi daha çok seviyorum...

seni neden sevmekten kurtulamadığımı görüyorum

ben sana...sen bana akarken.. 

beni artık defterinden sildiğini...

ve kalabalıklara karışıp bir çöp tenekesi aradığını...

buruşturup atacağını bekliyordum...

öyle de yapmış olsaydın...sevgim geçmeyecekti..

ve tek güzelin...nefesin..havan ve suyun olmak için 

her şiirim sensin...

ve senin için olacak sevgilim...

                                                                                             20.08.2005 / üsküdar

                                                                                              mustafa kaya', 'derin bir acı ile okudum..  sesimin titrediğini yüreğimle. yazabildiğin titrek notlarına düşen göz yaşlarını... kimse yoktu, bir kez daha se...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mektup-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soldan Sağa - Yukarıdan Aşağı', 'soldan-saga-yukaridan-asagi-mehmet-osman-erol-unal-qv6fk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canımsın................... Cânan mısın

Kanımsın.................. Sevdâ mısın

Ecelimsin.................. Alır mısın

Duamsın.................... Tutar mısın

Kânunsun.................. Nerde olsan

Hükümsün................. Canım alsan

Cihânsın.................... Derdim olsan

Sözümsün................. Benim olsan

Gül yüzüne................  Doyamadım

Perçemine................ Kıyamadım

Âşık oldum................ Saramadım

Gözlerine..................  Bakamadım

Târifi yok................... Anlatamam

Bu bir çile.................. Katlanamam

Tâkatim yok.............. Dayanamam

Düştüm dile..............  Kurtulamam

Seni sevdim............  Sevdim seni

Günah olsan.............  Vermem seni

Terk edemem............Asla seni

Seni ölsem................ Ölsem seni

(İstanbul, Haziran 1990)', 'Canımsın................... Cânan mısın Kanımsın.................. Sevdâ mısın Ecelimsin.................. Alır mısın Duamsın..................', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/soldan-saga-yukaridan-asagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sen', 'sadece-sen-salih-ozalasan-hkr0r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya’da iki kadın tanırım

Biri annem diğeri sen

Annem daima haklıdır

Senin içinse ölürüm öl desen

Kim tutar dünyada sizin yerinizi

Doğma sebebim sevgili annem

Damarlarımda dolanan kanın sahibi

Beni hayata bağlayan bağsa sadece sen

Şımarır mıydın? Sevinir miydin? 

Sana yüreğimde verdiğim yeri görsen

Sevgili bulunur ANNE bulunmaz” derler

Doğrudur; Ama senden asla vazgeçmem ben

Y Tarihi 19-08-05

Salih ÖZALAŞAN', 'Dünya’da iki kadın tanırım Biri annem diğeri sen Annem daima haklıdır Senin içinse ölürüm öl desen Kim tutar dünyada sizin yerinizi Doğma se...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sadece-sen-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Omuzumda Bin Yılların Ezgisi', 'omuzumda-bin-yillarin-ezgisi-ercan-cengiz-b6x69', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Irmaktan okyanusa açılan suyum ben,

Toprağın katmanından çıktım

Kaya diplerinden toprağın ezgisini bin yılların 

Olanca gücümle yüklendim omuzlarıma

Güneş inerdi berraklığıma

Karanlığı söken kızılca güneş,

Ak ederken yüzümü yıldızlar toplanırdı

Karanlığı yırtarcasına.

Dağların oyuğundan, vadilerden

Akardım kendi kanımda ezgilerle

Balık olurdum suya nehirlere açılırdım

Toprağın yüzüne çıktıktan sonra,

Akacağım yönü bilirdim... 

Ayı da severdi balığı ve balık için

Suya inerdi, bir düşün ki

Ayı ki meşeye sürtünür gücü yetmezdi

Arıya... 

Geçtiğim yerlerde uçurumlar vardı,

Derin vadilere gömülmüş ezgiler

Gözeneklerim vardı şarıl şarıl akan,

Ülkemin altın saçlı ak yüzü

Uygarlık beşiği, Mezopotamya...

Yoksundu günümüzden.

Kayayı damarlarıyla parçalayan meşe ağacı,

Yeşile boyanan vadi,

Birbirini kollayan dere yatakları... 

Özgürlüğe yürüyenlerin patikasını bulurdu

Dört parçada ezgilerin kesişmeleri.

(Kaynak: Ezgilerde Kaldı Yüreğim 2. Kitap)       

Zindanda Yenildi Ölüm 

Gezginliğimin patikasına girmiş

Bir ucundan diğerine ülkemin

Her karış toprağında çizilmiş güzergahları 

Olunmazdan geçilmiş yolu 

Patikalarla

Vietnam tunellerinden gelen

Ho Chin Minh''nin öğretisi.

Güneşi kucaklamaya ustaca, hepsinden önce

Güneşe kaldırırlardı kollarını 

Ezilmiş yürekleriyle bin yılların 

Beşer-onar 

Gruplar halindeydiler...

Ustaca kalkılırken güneşi selamlamaya

Günüydü bir başka mevsimin günü

Sıkılırken yumruk, haykırılırken

Sabırlı adımlarla katılırken diğerine,

Tereddütsüzce...

Ve karanlıktan koparıp almak için geleceğini

Şafak boyu sürecekti, hücre hücre

Söküp alıncaya 

Uzayacaktı da patika,

Parça parça olmuş ülkemde.

Patikadan sesler yükselir toprağın yüzüne

Çağın yaratımı kaplarken ince bir esintiyle

Ölümün üstünü 

Diyarbakır zindanında yenildi 

Ölümün kendi,

Ölümün donuk yüzüne de diz çökülmezdi

Aman dilenmezdi asırların kirine, 

Pasına da

Dosta-düşmana öğreti 

O yüce dirençle

Okşanırken Zeynel''in kahkahasında

Vadileri Dersim''in, 

Akarsuları ve toprağın ezgisi.

Ve patikadan sesler yükselirdi suyun sesine

Dirençli yüreklerle taşınıp

Tarihe damgasını vuran, 

Yaşatan bir ezgi

En amansız zamanlarda,

Yaşanılmazlığı 

Çarkın ihanetinden çıkarıp

Yaşanılır kılandı.

Çarkın dişlerindeki ezili yürekleri 

Ve ateş içinde kavrulmuş

Yitik kalbin ezgisiyle 

Sıkılı yumruk.

Yaşamın kendiydi ezgilerde, 

Sevdanın kendi 

Direnciydi 

Meşenin inadındaki damarın 

Yüreğiydi-ruhuydu

İradesi... 

Suya doymuş toprakların 

İnsana ait ne varsa, 

Yaşanılır kılan

Yaşanmazlıkları,

Çağdaş Kawa''nın öfkesiydi, 

Zindandan yükselip

Karanlığın üzerine düşen 

Bu toprağın ezgisi

Üç kibrit,

Patikalardan coğrafyalara taşırken

Ayak izlerini

Suyun sesi, 

Dağın sesi gelirdi kulaklara

Ve inançlı yüreklerde dokunurken 

Yarınlar kalırdı 

Yarınlar ezgili yüreklerde...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)      

Gidişini Belirleyen Ahlardır

Gecenin sırdaşları dağların sesini aldılar

Dağlar birleşti kendi sesleriyle, haberin var mı? ..

Gelişini bilirler, gecenin sırrını alanlar

Sokağa çıkma yasağı delindi

Haberin var mı? ..

Gölgen sarmalamışken her yeri 

Rap rap ayak seslerine tutulmuşken gün

El-ayak bağlanırken panzerine,

Dağların sesini aldı gecenin sırdaşları

Geldiler, haberin var mı? .. 

Delip karanlığı geçtiler üstünden kendi ezgileriyle

Ve uzaktılar, tanrının selamından

Haberin var mı? .. 

Bilir misin gecenin sırdaşını,

Dağın sesini, ezginin gücünü bilir misin? ..

Kır çiçeğini, kardeleni bilir misin, isyanı sana

Ahları var bu çarkın karanlığına

Sessizliğe boğulmaz dağın sesi,

Gecenin sırdaşı ezgiler toplamış geliyor

Yıldız yıldız

Ki belirleyecektir bu yüzden bu çarkın dişlileri adına

Senin gidişini, O yıldızlar...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)     

Yolundan Etmemiş, Umut Bellemiş

İşgal edilmiş bir ülkenin toprağında

Kaplamış duman gökyüzünü,

Henüz baykuş ötmüyorsa eğer

Bil ki manga manga gecenin melekleri.

Dağlarına ezgileriyle sırdaş olmuşlar...

Bir ülke paramparça edilmiş ezgileri ile

Soyguncu, talancı, zindancılarla çevrili

Boydan boya kana bürünmüş

Boydan boya kül içinde kalmış toprağında

Yakılmış, yıkılmış evlere gömülü gözyaşları,

Viraneye dönmüş köylerde kurumuş ağaçları

Ve sürgünlerde

Açlığa terk edili bir ülkenin ezgileri...

Gecenin melekleri, dağların birleşmiş sesinde

Ağıtlar arasında şehitlerine söz verenler

İntikam ve özgürlük yeminlerinde,

Karanlığa-talancıya-soyguncuya karşı ayağa kalkanlar

Zindanlarla birleşmiş yüreğini saran ezgilerle

Dağ dağ, oyuk oyuk tüfek çatmışken...

Çoktan sevdalanmış gençleri toprağın ezgilerine

Gecenin meleklerine,

Yaşlıları asırlardır ağıtlar yakmış ardında

Çıkınlar hazırlamış yol yorgununa,

Ama, yolundan etmemiş ezgili yürekleri

Sırrına alıp rüyasına katmış umut bellemiş.

Yeşermiş vadileri, dağlar seslenmiş

Sararmış başakları ekinlerin bu topraklarda

Bolluk bereket görmüş hep,

Ekmeğini kazanmış bin beladan sonra

Şehit düşmüş, tutsak edilmiş, ve sürgünlerde onyıllarca

Ve arkasından toprağın ezgisiyle gelenler

Zincirleri koparıp vurmuş celladının suratına

Özgürlük ve insanca yaşam yeminlerinde,

Güzelliklere, toprağın sesine koymuş kalan ömrünü...

Analar, şehit Anaları

İntifadada büyütmeye çalışırken ezgileri

Çocukları eğitirken okullarında

Gelinleri dağın sesini almışken bir kez

Melek soyunu bilmişken ezgili yürekleri 

Gece sırdaşını görmüş, konuşmuşken

Yüreğini katmışken büyüsün diye çocuğu

Yitik ülkenin ezgilerinde çoğalmış...

Gecenin melekleri, dağların birleşmiş sesi 

Yeni insana vermişken elini ezgili yürekleriyle

Kendi kurtuluşuna yolunu bilemişken

Çilesini anlatmışlar ceviz ağaçlarına.

(Kaynak: Ezgilerde Kaldı Yüreğim 2. Kitap)    

Gece Akardı Üstüne

Çakmak çakmaktı gözlerin

Gecenin karasına gömüldüğünde,

Çoban yıldızı kaymıştı

Ay kaçmıştı havai fişeklerden. 

Açlığını karanlığa bırakmıştın

Geceye gömüldüğünde mavi yoktu.

Duman çökerdi üstüne

Doğaya yanık tenin kokusu sinerdi

Ve çetebaşları ulumaklıydı. 

Tan vaktiydi,

Kan akardı kuşun kanadından

Tepede bir meşe ağacı,

Vurgunuydu ora acılarının

Düşünürdü acısını kuşun

Yaprağı rüzgarın sürtmesindeydi.

Dudaklarında doğardı yarının ezgisi

Birleşirdi ezgili yüreklerle

Kanadında gece kuşunun. 

Çeteler gelirdi üzerine,

Gece karanlığa gömüt, gece cılıktı

Yaprak sallanırdı esen rüzgarda,

Yarına bir dinleti çıkardı

Ve gece, akardı üstüne, hoyratca...

(Ezgilerde Kaldı Yüreğim 1.Kitap)   

Artık Çok Geçti

Hoplata hoplata çekilip alınmıştı sudan

Bir balık 

Solucan takmışlardı oltaya

Keyiflendiler

Bir daha, bir daha

Kanmasına gelirdi kimi balık bu lokmaya

Zıplaya zıplaya

Çırpınıp dururdu oltada

Kumsala vurduğunda

Bağlanmıştı midesinden, çırpındı durdu

Midesizliğinden bir lokmaya

Sallanıyordu oltada

Son çırpınışında.

Gözlerinde sefil bir duruş

Suyun son damlaları düşüyordu üzerinden

Yutkunuyordu da

Bu kez hazımsızlığından

Anlamıştı belki,

Artık çok geçti...

...

(Ezgilerde Kaldı Yüreğim 1.Kitap)  

Devran Ellerimde Kaldı 

Göremiyorum

Kulağımı tırmalayan çığlığı,

Yitiğime gezdiriyorum ellerimi

Boşlukta 

Boşuna dönüp dururlar.

Dokunmak istiyorum

Gözlerim bağlı, yüreğim yaralı 

Dişlerimi sıkıyorum,

Yumruğumu...

Karanlık beslemesi bir el,

Kavrıyor ellerimi,

Elleriyle

Bir araya getirip

Vuruyor birbirine

Ve ardından kelepçeleyip

Bağlıyor ranzaya.

Ellerimde kalıyor

Devranın ağırlığı...

(Ezgilerde Kaldı Yüreğim 1.Kitap) 

Nuro''ya 

Ayrı zamanlardı, iki karanfil buluştuğunda

Sıcak, çıplak tepe başında

Boylu boyunca düştüler, yan yana

Beyaz Dağ''ına Dersim''in,

Bir karanfil kendi renginde

Bedenine saplanmış kör bir kurşun...

Uzak diyarlardan adres sorulurdu

Ve saplanırdı bedenine, bir kurşun daha. 

Son mermisiydi Beyaz Dağ''da 

Çarpışmadan arta kalan 

İndirmeden kirpiğini, onu da Hüseyin aşkına

Sıkıyordu karanlığın bekçisine.

Dizleri dermansız, doğrulamazdı yerinden

Son nefesine yakın, hayat bir film şeridi gibi 

Ama bitmemişti haykırmalar

Ve mavzerini kırıyordu kayalara vura vura

Sonra, fırlatıyordu uzaklara

Parça parça,

Ki geçerse de ellerine kör kurşunun 

Kullanılamaz halde geçsindi gaye...

Ayrı zamanlardı dağlarda iki karanfil buluştuğunda

Karanfillerle

Kör kurşundu yıkılası Eleziz sokaklarında 

Saplanmıştı bedenine,

Kan anonsu geçilirken mahalle sakinlerinden

Sokaklara pusu atılmıştı

Korkaklardı, doymamışlardı kana

Karanlığın ortasındaydılar kana doymayanlar.

İlk kurşundu sırtından giren

Kalbinden vurup geçerdi

Ve nabzın son atışlarında çevirirdi gözlerini yoldaşça,

Yarasını kaparken bir eliyle

Sıcak gülümsemesine diğer eliyle 

Pusuya yatanları gösterirdi.

Korkaklardı, doymamışlardı

Salya akıtır, kanla beslenirlerdi

Kabarırdı ulumaklı sesler

Eleziz sokaklarında... 

Şimdilerde portreleri ellerindedir ora insanının

Duvarlara renk verirken gülümsemesi

Dağlar aşılırdı O iki karanfille,

Toprağa - güneşe - ateşe

Yağmurun çiselemesinde

Ayrı ayrı zamanlarda gülümsediler

Rüzgarın okşayışında inlerken çınar

Gülün rengine...

İki karanfil düştü ateşe

Bahara ton verdiler, daha da verecekler

Dersim''in dağlarında...

(Ezgilerde Kaldı Yüreğim 1.Kitap)

Senin Eğlencene 

Senin eğlencene denirdi

Balık da olsa

Yani 

Nehirdeki balık, Okyanustaki... 

Meşe diplerinden, kayalardan fışkırıp 

Toprağın yüzüne çıkan

Su içindeki balık...

İçtiğin sudaydı balık 

Boğazına duracak.

Sofrandaydı,

Tabağındaki yemekte...

Sudaki balık,

İsmi diline geldiğinde

Kendisiydi tepende duran

Ecdadının aklı almadı,

Bilirim ki senin de almaz...

(Ezgilerde Kaldı Yüreğim 1.Kitap) 

Sesine Vurulduğum Keklik 

Sesine vurulduğum keklik,

Gelen ben 

Kandığım keklik ölen ben,

Öldüren ben 

Birlikte ağıtlar yaktık arkalarından

Yine geldik. 

Türümüz yayıldıkça denendik

Keko, peko dedik guguk kuşuna

Dağ-taş düştük yollara

Ağaçlara yaslandık, ağladık yapraklara

Gizledik ağlamaklı yüzümüzü

Sesimizi verdik rüzgarlara

Efsanelerle geldik her bahar

Öldük, öldürdük.

Nasılını bilmem,

Geldik yan yana

Sesine vurulduğum keklik,

Ötmemeyi deneseydin bir kerecik

Kanmamayı bir kerecik

Kandırmamayı...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'Irmaktan okyanusa açılan suyum ben, Toprağın katmanından çıktım Kaya diplerinden toprağın ezgisini bin yılların  Olanca gücümle yüklendim om...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":330,"source_url":"https://www.antoloji.com/omuzumda-bin-yillarin-ezgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsküdar - 1', 'uskudar-1-elazigli-mustafa-kaya-vhn6x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 've 

içimdeki yalnızlığa koştu 

iskeleye yanaşan bir vapur.

ruhuma acı veren sessizliğe geldi martılar.

kaç vapur yanaştı,

ve yüzlerce insan buluştu.

görmeliydin bir kalabalık Üsküdar.

gül kokusu sinmiş gözlerine şehrin.

bir turuncu akşamdı,

ve bir martı çığlığında atar

yalnızlığıma kanayan veda.

kızıl-mor-gri renklerden bir akşam

ve sana yazdığım şiir,

ve güneşin sarı yüzü

baş başa boğazda cilveleşir…

ve ezanlar ezanlara karışır

bir akşam ezanı kucaklar sizi

basamakları mermer iskele camii.

biraz ilerde cadde de selman ağa.

daha az ileride  devati camii.

bir mana iklimi yatar 

sırrını çözemediği dünyanın

mahmut hüdai hazretleri camiinde

ve burası Üsküdar..

                                                                      20.08.2005 / üsküdar

                                                                       mustafa kaya', 've  içimdeki yalnızlığa koştu  iskeleye yanaşan bir vapur. ruhuma acı veren sessizliğe geldi martılar. kaç vapur yanaştı, ve yüzlerce insan ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/uskudar-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şâheser', 's-heser-mehmet-osman-erol-unal-mxmsa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şâheserim uyanmış...

Esmiş aklına, erken kalkmış

Şâheserim çayı koymuş

Başında uyuya kalmış...

Şâheserim, pek hoşsun

Bu ne zahmet, aşk olsun

Hadi, dön sen uykuna

Aç koynunu kuş konsun...

Şâheserim çok tatlı

Uykuları beyaz atlı

Çayımı bana bırak

Rüyâların senin olsun...

(İstanbul, Şubat 1994)', 'Şâheserim uyanmış... Esmiş aklına, erken kalkmış Şâheserim çayı koymuş Başında uyuya kalmış... Şâheserim, pek hoşsun Bu ne zahmet, aşk olsun...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/saheser-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçarı Gönlüm', 'ucari-gonlum-nevzat-erkol-mmeit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah yanımdan

Çok renkli bir kuş geçer

Öyle sevimli, ürkek,

Bakar kalırım ardından

Konmadan uçar gider.

Her sabah mutlanır gözlerim

İçime sevinç düşer,

Bir çiğ damlası gibi

Dalgalanır yüreğim,

Kuşlar kadar hafifler.

Sonra, bildiğin şeyler...

Süreğen bir döngüde

Gün biter, gönül diner

Yorgun akşamlar iner

Küllenen düşlerime...

Gece,

_______yine derbeder

Yürek, 

_______beterden beter.

2002', 'Her sabah yanımdan Çok renkli bir kuş geçer Öyle sevimli, ürkek, Bakar kalırım ardından Konmadan uçar gider. Her sabah mutlanır gözlerim İçi...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Erkol']::text[], 8.5, '{"poet":"Nevzat Erkol","poet_slug":"nevzat-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ucari-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tepeme Çıkan Şiir', 'tepeme-cikan-siir-meral-vurgun-w39ya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“bak cin gibi çarparım bütün cinlerini

bütün uykularını kara delikler gibi deşerim

tir tir titrersen yapayalnızlğınn okyanusunda

getirmez beni adımların sahiline - bilesin-

yak gitsin postumu bu ıssız dağlara” Yaşar Doğan



TEPEME ÇIKAN ŞİİR

başımın ağrısı ki

üzerime karabasan gibi çöken zaman

bütün sınırları aşmış –yasaklar ihlal-

kanatlarını düşlerimde okşadığım şahin

türküsüdür zirvelerin

yaslandığım dağ olsun omuzbaşın

kanata kanata karanlığın omurgasını

yedi iklim dört kıta’ya 

şan veren sözcükler biriktirdim sana

işte başımın ağrısı, tepeme çıkan şiirin öyküsü

bizden önce de buradaydı bu gökyüzü

toprağımıza düşürüp salkımlarını

gülerken güneşin yüzü, misafirdim...

koynuma gelmişti kirpiklerin –pır pır uçarak-

yıldızlardan süzülüp alnından öpmüştük ay’ı

derimizi etimizden soyarak...', '“bak cin gibi çarparım bütün cinlerini bütün uykularını kara delikler gibi deşerim tir tir titrersen yapayalnızlğınn okyanusunda getirmez be...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tepeme-cikan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onu kaybetim', 'onu-kaybetim-elazigli-mustafa-kaya-7uzoq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onu kaybettim,

İpek haykırışlarını duyamıyorum artık

Suya dokunuşu gibi ay ın..

Onu kaybettim,

Geceyle barışmak isteyen  gölgelerde

Yakamozlara dönüşen gülüşlerini..

Sararmış yapraklara döndüm

Paslı çiviler gibi

Kopuyorum  bir bir..

Dağılan bulutları 

toplamak istiyorum

rüzgarın sesiyle.

günler geçiyor

onu  kaybettim.

birazı  sen

birazı yine sen

seni kaybettim.

renklerin raksı bir mevsimde.

Onu-seni kaybettim

Hanginizi sevmiştim..hanginizi

Her şey burada kilitleniyor.

Çehreme yayılan uzun bir kış şimdi.

                                                                      

                                                                       11.08.2005 / istanbul

                                                                        mustafa kaya', 'Onu kaybettim, İpek haykırışlarını duyamıyorum artık Suya dokunuşu gibi ay ın.. Onu kaybettim, Geceyle barışmak isteyen  gölgelerde Yakamozl...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/onu-kaybetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişini Belirleyen Ahlardır', 'gidisini-belirleyen-ahlardir-ercan-cengiz-kkcon', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin sırdaşları dağların sesini aldılar

Dağlar birleşti kendi sesleriyle, haberin var mı? ..

Gelişini bilirler, gecenin sırrını alanlar

Sokağa çıkma yasağı delindi

Haberin var mı? ..

Gölgen sarmalamışken her yeri 

Rap rap ayak seslerine tutulmuşken gün

El-ayak bağlanırken panzerine,

Dağların sesini aldı gecenin sırdaşları

Geldiler, haberin var mı? .. 

Delip karanlığı geçtiler üstünden kendi ezgileriyle

Ve uzaktılar, tanrının selamından

Haberin var mı? .. 

Bilir misin gecenin sırdaşını,

Dağın sesini, ezginin gücünü bilir misin? ..

Kır çiçeğini, kardeleni bilir misin, isyanı sana

Ahları var bu çarkın karanlığına

Sessizliğe boğulmaz dağın sesi,

Gecenin sırdaşı ezgiler toplamış geliyor

Yıldız yıldız

Ki belirleyecektir bu yüzden bu çarkın dişlileri adına

Senin gidişini, O yıldızlar...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'Gecenin sırdaşları dağların sesini aldılar Dağlar birleşti kendi sesleriyle, haberin var mı? .. Gelişini bilirler, gecenin sırrını alanlar S...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gidisini-belirleyen-ahlardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca Uyanıncaya Kadar', 'yalnizca-uyanincaya-kadar-melih-coskun-3ui5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suyu çekilmiş bir nehir gibi 

Hissettim yokluğunu yine bu sabah

Aradım yüzünü zihnimde gecelerce

Bulamadım ama gördüğüm hiçbir rüyada.

Seni sensizliğinde sevmenin 

Destanını kazıdım beyaz kağıtlara 

Sıkılı yumruk, kenetlenmiş diş gibi hınçlandım 

Sensizlikle yitirdiğim 

Belki bininci geceye.

Şimdi küçük kederler ekiyorum yüreğime 

Çağırıyorum çok uzaklardan 

Hiçbir zaman duymadığım sesini

Onca dağ

Onca denizler gördüm 

En sıcak kavgaların koynunda,

Can çekişen binlerce balık gördüm 

Kurumuş dere yataklarında. 

Hep görebildiğim güzelliklere vuruldum yıllar yılı 

Burkuldu yüreğimin sol yanı

Dinlediğim bütün acıklı hayat hikayelerinde. 

Daha önce hiç aşık olmadım 

Rüyalarımda yarattığım bir imkansızlığa.

Bir adın olsaydı 

Kazırdım yüreğimin ortasına 

Bir yüzün olsa 

Bakardım usanmadan 

Yavru ceylan bakışlarına

Ve bir yüreğin olsaydı 

Sevmeni dilerdim beni rüyalarımda

Yalnızca uyanıncaya kadar da olsa... 

2005', 'Suyu çekilmiş bir nehir gibi  Hissettim yokluğunu yine bu sabah Aradım yüzünü zihnimde gecelerce Bulamadım ama gördüğüm hiçbir rüyada. Seni ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yalnizca-uyanincaya-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tütmez mi', 'tutmez-mi-yusuf-ter-fcqmj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aslı''sını arar kerem

Yana yana ağlamaz mı

Ferhat dağı deler iken

Coşup coşup çağlamaz mı

Gök kubbeye söyler diller

Dua eder  bütün canlar

Kerbelada akan kanlar

Hüseyin’i  bağlamaz mı

Kesilir mi hakkın yolu

Kabe dedir  asıl kolu

Veysel Karani''nin eli

Yusuf’umun eğlemez mi

Yusuf Ter 19.08.05

Saat 02:17 İsviçre', 'Aslı''sını arar kerem Yana yana ağlamaz mı Ferhat dağı deler iken Coşup coşup çağlamaz mı Gök kubbeye söyler diller Dua eder  bütün canlar Ke...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tutmez-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurtmalarım Telgrafın Tellerinde', 'ucurtmalarim-telgrafin-tellerinde-tunahan-ermihan-if4u4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözler tükendi dillerde

Yaşlar dondu kaldı gözlerde

Umutlar asılı kaldı bir hayal ağacında 

İpini salarken sevindiğim hatıralardan yaptığım 

Tüm uçurtmalarım telgrafın tellerine takılı kaldı

Affetsin beni tüm hayat

İyi niyetim kırıldı yüreğim ellerimde kaldı', 'Sözler tükendi dillerde Yaşlar dondu kaldı gözlerde Umutlar asılı kaldı bir hayal ağacında  İpini salarken sevindiğim hatıralardan yaptığım ...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ucurtmalarim-telgrafin-tellerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Olsun', 'ask-olsun-tunahan-ermihan-i0it1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kanma onların dediklerine 

Daha toysun sen yüreğim,

Zamanla göreceksin sende, 

Anlayacaksın 

Aşk dediğin, 

Yüreğinin orta yerini yarmadan, 

Gözlerindeki son neşe pırıltısını söndürmeden,

Aşk olmuyor', 'Kanma onların dediklerine  Daha toysun sen yüreğim, Zamanla göreceksin sende,  Anlayacaksın  Aşk dediğin,  Yüreğinin orta yerini yarmadan,  ...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-olsun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm vatan hasretinden yaralı', 'gonlum-vatan-hasretinden-yarali-mikdat-bal-lq17f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlüm vatan hasretinden yaralı

Bu hasret yakıyor, yakıyor beni

Hasret mi sadece, dertler sıralı

Mahvedip yıkıyor yıkıyor beni

Gündüz hayalimde, gece düşümde

Yatarken, kalkarken, her bir işimde

Sağımda, solumda, önüm peşimde

Kendine çekiyor, çekiyor beni

Mamurdan çöplüğe, her bir köşeyi

İğneden ipliğe, yurdun her şeyi

Özledim huzuru, zevkı, neşeyi

Bu gurbet sıkıyor, sıkıyor beni

Her vakit gür sesle. ezan okunur

Onları duymamak. bana dokunur

Mikdati ne etsin ancak yakınır

Dostlarım okuyor okuyor beni', 'Gönlüm vatan hasretinden yaralı Bu hasret yakıyor, yakıyor beni Hasret mi sadece, dertler sıralı Mahvedip yıkıyor yıkıyor beni Gündüz hayali...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonlum-vatan-hasretinden-yarali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-arif-emre-ui0aj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'elbet sessiz sedasız 

dur durak bilmeyen çingene bir kızın çığlığı gibi senden benden orospu.

hatırlayın kimsesiz kadınlar kadar aç.

eskimiş bir dostumun kalbinde bir kanser yarası olmuşum adım ihanet

sevmediğim o kadar çok delikanlı bir abdest boyu seviştiğim.

dur ve durak bilmem beni tanımadığım şehrin duraklarında becerdiler.

olduğum vakit senin dudaklarında gördüğüm elma 

sanki pembe bulutların gözümü dağladığı cennettir.', 'elbet sessiz sedasız  dur durak bilmeyen çingene bir kızın çığlığı gibi senden benden orospu. hatırlayın kimsesiz kadınlar kadar aç. eskimiş...', ARRAY['Türk Edebiyatı','Şiir','Arif Emre']::text[], 8.5, '{"poet":"Arif Emre","poet_slug":"arif-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ihanet-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K a l e m l e y a l n ı z...', 'k-a-l-e-m-l-e-y-a-l-n-i-z-zafer-zengin-etnika-5nx05', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

sıcak kendine kavurgan

toz havanın yoldaşı ‘zamanda

sen çıktın karşıma

sessiz ‘yalın

saldırdın aynandan

içimi tanımadan

ellerim açıldı

hapis oldun bana

yağma yok

canlar alıp

ateş saçan ayrılık

huzura bilenmiş hayat

ikimiz bir toprağa sığamadık

yaş''ım sana

ömrümden 

gözümden

kapla

tırnak uçlarına

unutma

ten düştü

elin kılıç saplamış

ahh affet

yüreğim sana duracakmış

an''ım sana

canımdan

kanımdan

kapla 

yüzün şavkından

unutma

| kendine iyi bak

hep görmeyeceğim ‘o geceyi anlat|

soğuk yerimde bile

hiç dokunmadığım

gözyaşını anlat

düşür bir kaçını ‘kirpiklerime

ağlamayı hatırlat

ağır yoldayım ‘şimdi 

ıssız

sen

ben

kalemle yalnız

sarılmışız

sarma(a)  şığız*

12.01.2005

* Birine aitse mesaj atarsa sevinirim.

Sahiplenemedim bir türlü.Googeldende taradım.', '. sıcak kendine kavurgan toz havanın yoldaşı ‘zamanda sen çıktın karşıma sessiz ‘yalın saldırdın aynandan içimi tanımadan ellerim açıldı hap...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/k-a-l-e-m-l-e-y-a-l-n-i-z-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'H a z ı r l a d ı m y e r i m i...', 'h-a-z-i-r-l-a-d-i-m-y-e-r-i-m-i-zafer-zengin-etnika-45bb1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

yerimi

hazırladım

küçük 

olsa da

ellerim sığar 

en azından

bel ki

gülümsemem

dudağımdan

..

yerimi

hazırladım

ayrı

bulut

ayrı

mavi

yerde

