INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suya Yazıyorum...', 'suya-yaziyorum-gurkan-kuzu-3mtug', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Suya yazarım kendimi, 

Herkes bilsin istemem beni. 

Her anlayan beni,

Suya yazıyordur kendini...', 'Suya yazarım kendimi,  Herkes bilsin istemem beni.  Her anlayan beni, Suya yazıyordur kendini......', ARRAY['Türk Edebiyatı','Şiir','Gürkan Kuzu']::text[], 8.5, '{"poet":"Gürkan Kuzu","poet_slug":"gurkan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/suya-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur sultan', 'nur-sultan-i-brahim-kilinc-bi2c7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nur sultandır adı, bir beyin kızı

Kırkında dillere düşürdü bizi

Tatlıdır dilleri, çekilir nazı

Saldı da sevdaya bıraktı bizi

Onu tarif etsem, lugatım yetmez

Çekerim çekerim çilesi bitmez

Ben pınarım, o suyumdur hiç akmaz

Bu ıssız çöllerde bıraktı bizi

Nazlı nazlı yolda gidişi vardır

İçimi güldüren gülüşü vardır

Çağırırım gelmez hep işi vardır

Dünyada nasipsiz bıraktı bizi', 'Nur sultandır adı, bir beyin kızı Kırkında dillere düşürdü bizi Tatlıdır dilleri, çekilir nazı Saldı da sevdaya bıraktı bizi Onu tarif etsem...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nur-sultan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arı', 'ari-oguzkan-bolukbasi-apqbf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk sandığın bir bulut

Somut bir delili var mıdır sonsuzun

Çiçeklerin ödülü baldır arıya

Hiçbir çiçek üzülmez

Arı konduğunda

Sarıya

Kırmızıya

Beyaza

Onlar yalnızca ayaza 

Dayanamazlar

Arı olmak kolay mı

Ya çiçek olmak

Ben senin ödülün olmak istiyorum

Ödüllerinden biri olmak

/İşte sonsuzluk sunuluyor şimdi

 Aşkın durmayan pervanesinde/', 'Aşk sandığın bir bulut Somut bir delili var mıdır sonsuzun Çiçeklerin ödülü baldır arıya Hiçbir çiçek üzülmez Arı konduğunda Sarıya Kırmızıy...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ari-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Birikintileri', 'su-birikintileri-sinan-karakas-s8iet', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Su birikintileri yanyana durarak

Birisi diğerine diyordu seslenerek

Ey birikinti kardeş hazırlanda gidelim

Gök yüzüne çıkıpta bir buluta girelim

Sen yüksel su kardeşim ben arkandan gelirim

Canlılara yardıma nekadar sevinirim

Biraz daha güneşten ısıyı alacağım

Sen yükselirken göğe peşinden geleceğim

Böyle konuşurlarken o iki birikinti

Güneş gülümseyerek o suları ısıttı

Buharlaşıp girdiler her biri gaz haline

Bakakaldım kupkuru çukurluğun dibine

Yetişti birincisi bir buluta girerek

Ardından ikincisi yükseldi sevinerek

Bak kardeşim gökyüzü ne güzel ne de sakin

Sanki bir şeye gebe sanki hareket yakın

Adımız su birikintisiydi biraz evel

Şimdi bize bulut diyorlar nede güzel

Bir süre yükseldiler gökyüzüne çıkarak

Bir havayla çarpışıp bir yldırım çakarak

Sonra soğuk bir hava geldi çattı bunlara

Pamuk gibi bulutlar indiler topraklara

Ölü gibi topraklar nasılda canlandılar

Gökten inen rahmetti onu yağmur sandılar

Gökyüzünü görmeye doyamazdı insanlar

Bir düğün yeri gibi oynuyorlardı canlar

Bir tek amaç uğruna iniyorlardı onlar

Elbette bu misali hizmeti bilen anlar

Bir birikinti iken buharlaşıp yükselen

Sonra bir bulut olup mavi gökleri delen

Bir süre gökte durdu Allahın himmetiylen

Gökten rahmet olarak bir damla sudur inen', 'Su birikintileri yanyana durarak Birisi diğerine diyordu seslenerek Ey birikinti kardeş hazırlanda gidelim Gök yüzüne çıkıpta bir buluta gir...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/su-birikintileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Rengi', 'siirin-rengi-figen-aydogmus-vuyd0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elime bir kağıt alsam birde kalem

Huzuru çizsem şu dizelere

Renk cümbüşleriyle geçiş yapsam

Bir mısradan diğerlerine

Sonra suluboyayla boyasam üzerini

Renkler karışsa sözcüklerime

Kim anlar ki şiir tadını

Rengin sarhoşluğuna kapılmadıkça

Kapılandan bir şey anlamadıkça', 'Elime bir kağıt alsam birde kalem Huzuru çizsem şu dizelere Renk cümbüşleriyle geçiş yapsam Bir mısradan diğerlerine Sonra suluboyayla boyas...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/siirin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biten Gün', 'biten-gun-sibel-maral-53afx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün daha bitti...

Doğan güneşi görmeden,

Gecenin yıldızlarına bakamadan

Başımı yastığa koydum tekrar...

Ve...

Sabah kalkacağım

Yine,

Rüya görmeden uyanmış olacağım.

Hep aynı şeyleri yazdığım günlüğümde

Akşama değişen bir şey olmayacak

Ama,

Ben,

Vazgeçmeyeceğim aynı şeyleri yazmaktan

Takii 

Hayatım aynı olmaktan çıkana kadar

Mucize değil beklediğim

Bitmişliğin melil mahzun yüzünü kazımak 

Sadece hayatımdan...

Beklemeden bişeyleri,

Başlangıcı yapmak

Bitsin artık, dünyayı süslemekten vazgeç

Dalsız, yapraksız, renksiz kalmış içindeki bana iyi bak

Merhamet her uğradığında kapıma,

Açlığımı sende gör  istiyorum

Bil istiyorum,

Dünyada en çok  benim; 

Yıldızları saymak için uğraşan,

Ve 

Sadece benim,

Bunu gökyüzüne bakmadan yapmaya çalışan...', 'Bir gün daha bitti... Doğan güneşi görmeden, Gecenin yıldızlarına bakamadan Başımı yastığa koydum tekrar... Ve... Sabah kalkacağım Yine, Rüy...', ARRAY['Türk Edebiyatı','Şiir','Sibel Maral']::text[], 8.5, '{"poet":"Sibel Maral","poet_slug":"sibel-maral","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/biten-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buralarda Aşk''sız Geçer Zaman...', 'buralarda-ask-siz-gecer-zaman-ugur-deniz-ulkegul-qe01c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önemi yok nerde olduğunun

Saçlarına dokunan benim rüzgarım

Güncesine not düştüm yokluğunun

Kovgun sabahlara yenilir korkularım..

Bir adam efkar çeker dumanından

Bakir düşlerinde sancılanır kadın

Büyümeye geç kaldığını anlar çocuk

Buralarda aşksız geçer zaman...

Yazılası mektuplar susar dilim

Kalem kırıldıkça, kanar ellerim

Bir gülüşe gözyaşımı satarım

Alan olmaz, duyulmaz söylediklerim...

Asarım maviyi ağaçlara

Kırgın bakışlar sunar Deniz,

Eşkiyalar Kurşun sıkar bulutlara

Kan rengi bırakır toprağa, bastığım iz...

Düşlerini yakarlar Ozan''ın

Otel odasında soluksuz kalır hece

Gün ki, -zafer tarih yazanın-

Ah! çeker insan, Sırlarından utanır gece..

Buralarda Aşksız geçer zaman

Zulasında öfke taşır yelkovan

Vurulur saat başlarında tarih

Düşer gölgeler, ayakta kalır insan...

Önemi yok nerde olduğunun

Saçlarını ıslatan benim gözyaşım

Yanılma yağmur diye, o bulut ki

Benim en yakın sırdaşım...

Şimdi hükümsüz kaldı sevişmeler

Sorguya prangalı bakışlar

Müebbete mahkum bütün dokunuşlar

Kalan biz, yanan içimiz, giden arkadaşlar...

Buralarda

Aşksız geçer zaman

Önemi yok nerde olduğunun

Yanıbaşımda durur, sesin, soluğun

Sonra bütün yalnızlıklar, seninle başlar......', 'Önemi yok nerde olduğunun Saçlarına dokunan benim rüzgarım Güncesine not düştüm yokluğunun Kovgun sabahlara yenilir korkularım.. Bir adam ef...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/buralarda-ask-siz-gecer-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rızayı Rahman', 'rizayi-rahman-selim-basar-aqw9p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O her kim ki,rızayı Rahmana mazhar olur.

Ol dem cümle kainat ona musahhar olur.', 'O her kim ki,rızayı Rahmana mazhar olur. Ol dem cümle kainat ona musahhar olur....', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/rizayi-rahman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemim', 'kalemim-huseyin-sigirtmac-pvvof', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürekte ufkumdur gamım efkarım.

Aşikar eyleyip yazma kalemim.

Sermaye bilirim bu ahu zarım.

Varlığıma değip ezme kalemim.

Bırak hayalimi yorsun hasretim.

Dünya malı değer gönül servetim.

Deryada bir damla yutmaz gayretim.

Devri alem edip gezme kalemim.

Can içinde canan bulur erenler.

Şekil ile sevmez gönül verenler.

Mala meftun ise ahbap yarenler.

Yorulup sen seni üzme kalemim.

Gönül umanında aşkın gemisi.

Seyrüsefer eder artar sevgisi.

Motife bezenir gönül duygusu.

İlhamına erip çözme kalemim.

Akıl ile süzüp bozma ahengi.

Sayfalara döküp soldurma rengi.

Madde olur sanma mananın dengi.

Sır kalsın gizemi sezme kalemim.

Kılıçtan keskindir bilirim gücün.

Zehirden beterdir şüphesiz acın.

Dünyayı yıkmaya yeter ya ucun.

Sevgi yaz, nefreti çizme kalemim.

İnsanlığa yön ver, bitsin melanet.

İlim, irfan, tarih sende nihayet.

Her can ameliyle, haktan hidayet.

Doğru yanlış deyip süzme kalemim.

Kul kusursuz olmaz şaşar, paylama.

Öfke kalesine çıkıp haylama.

Kendini bilmezle yükün taylama.

Alem mizanını bozma kalemim.

Kendini beğenen hakka muhalif.

Bir aklın sırrına ermez bin kaşif.

Düşünce ininde boş kafa hafif.

Ham söz cevherse de dizme kalemim.

Doğru ile yaren Sığırtmaç özün.

Yanlışa uyarsan hükümsüz sözün.

Taraf olma zalim olsa da gözün.

Mazlumdan yana ol, bezme kalemim.', 'Yürekte ufkumdur gamım efkarım. Aşikar eyleyip yazma kalemim. Sermaye bilirim bu ahu zarım. Varlığıma değip ezme kalemim. Bırak hayalimi yor...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kalemim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-abdullah-acar-gh1jy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşlerin en izbesinde 

Sensizliğin süzmesinde 

Bir dervis cezbesinde 

Seni arıyorum

Gündüzün nefesinde 

Gecelerin sesinde 

Bir rüya tepesinde 

Seni arıyorum... 

Bir muamma kutusunda 

Bir ölüm uykusunda 

Sırların en kuytusunda 

Seni arıyorum... 

Rüyaların izinde 

Hulyaların yüzünde 

Gerçeklerin özünde 

Seni arıyorum... 

Bir burukluk sesimde 

ve hıçkırık genzimde 

Gözyaşı denizimde 

Seni arıyorum... 

Yazımda baharımda 

Atan sah damarımda 

Aha tam buramda 

Seni arıyorum...', 'Düşlerin en izbesinde  Sensizliğin süzmesinde  Bir dervis cezbesinde  Seni arıyorum Gündüzün nefesinde  Gecelerin sesinde  Bir rüya tepesind...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-ariyorum-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünde Yaşamak', 'bugunde-yasamak-ali-i-nal-1tqf8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'usulca açılan bir kapının ardından

ve de ilk anda korkutucu karanlıktan

bir taze ışık gibi dolmalı yüreklere

hayatın ta kendisi olmalı yaşanan

sonu gelmez dertler bir yalan

ne dert var ne de sefa uyan

gözümüzle gördüğümüz bir sanrıdır

kim bilir nasıldır gerçek dünyan

han misali gezen gönül avare

her durakta düşme biçare

çareler uçuşurken gözünün önünde

bakan gözler görsün artık bir kere

geçen günler gelmez geri bir daha

gelecekse yaklaştıkça kaçar uzağa

hayalleri taşımak dünden yarına

yaşamamak bu günü en büyük hata

bir son var mutlaka hayatta

ölüm bile değildir uzakta

dün ölmedin, yarın da ölmeyeceksin

öldüğün gün de bugündür aslında', 'usulca açılan bir kapının ardından ve de ilk anda korkutucu karanlıktan bir taze ışık gibi dolmalı yüreklere hayatın ta kendisi olmalı yaşan...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bugunde-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mustafa-alpaydin-mifhl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün yine gözlerim kamaştı birden

Bir kartpostal gelmiş Metropol''imden

Üsküdar tarafı kuzey yönünden

Güzel İstanbul''u karşımda gördüm

Güneşmi karardı Aymı tutuldu

Şöyle bir of çektim içim burkuldu

Bu şehir gönlümde derin tutkuydu

Güzel İstanbul''u karşımda gördüm.

Alınteri ile sefa sürdüğüm

Hoşgörüyü usul sayıp bildiğim

Bahçelerde gonca güller derdiğim

Güzel İstanbul''u karşımda gördüm.

Hayallere daldım maziye döndüm

Sıla yollarında sanki yürüdüm

Kaderimmiş gurbet elde çürüdüm

Güzel İstanbul''u karşımda gördüm.', 'Dün yine gözlerim kamaştı birden Bir kartpostal gelmiş Metropol''imden Üsküdar tarafı kuzey yönünden Güzel İstanbul''u karşımda gördüm Güneşmi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-328-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstadlar', 'ustadlar-selim-basar-qc3do', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizim yazdığımıza şiir demek abestir.

Zira cümle amelimiz iştigal-i abestir.

Bütün şair üstadlarım, yazarken büzülmüştür 

Lakin diyebilirim ruhumdan süzülmüştür.', 'Bizim yazdığımıza şiir demek abestir. Zira cümle amelimiz iştigal-i abestir. Bütün şair üstadlarım, yazarken büzülmüştür  Lakin diyebilirim ...', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ustadlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Geldim', 'i-ste-geldim-ali-i-nal-bxnpp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'işte geldim

mum gibi erirken

biten bir bekleyiş

ne ben sana geldim 

ne de bir başkasına

sanki gitmemiş gibi

sanki hiç bitmemiş gibi

daha dün uzaklarda değilmiş gibi

aldanma olmayacak arzularına

doğru değil bu, bekleme boşuna 

işte geldim

giden bir hataysa

gitmek bir yalansa

bitmek bir kaderse

dönmek ayrı bir bela

görmek bir kez daha

dağlamak gözleri kor ile

duymak unutulan sesini 

saplanan zehirli ok misali

yeter artık orda dur

giden dönenle bir değil

gördüğün sandığın ben değil', 'işte geldim mum gibi erirken biten bir bekleyiş ne ben sana geldim  ne de bir başkasına sanki gitmemiş gibi sanki hiç bitmemiş gibi daha dün...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/iste-geldim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Ateşim Közde Kalsın...', 'birak-atesim-kozde-kalsin-tulay-sustam-0wwxw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aşkın gölgesi kadar uzak dur benden

düşmesin yüreğime

yosun gözlerinden bir yaprak

tenin tenime değmesin

kendimi tutamam...

aşkın gölgesi kadar uzak dur benden

kara dudağımı güneş yaktı...

yağmurum olupta ateşimi söndürme

aşkın gölgesi kadar uzak dur benden

değerse yüreğime kirpiklerin

ansızın kopar kızılca kıyamet

ay tutulur, yıldız kayar, yağmur boşalır....

aşkın gölgesi kadar uzak dur benden

alıştım! ... yıllar yılı yalnızlığıma sarılıp uyumaya

hadi git! ... birazdan güneş açacak gözlerini

kimse duymasın beni aşka çağırdığını 

beni bana bırak... ben aşka tövbeliyim

aşkın gölgesi kadar uzak dur benden

- bırak ateşim közde kalsın -

küçükkuyu/çanakkale', 'aşkın gölgesi kadar uzak dur benden düşmesin yüreğime yosun gözlerinden bir yaprak tenin tenime değmesin kendimi tutamam... aşkın gölgesi ka...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birak-atesim-kozde-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Kandiller', 'i-yi-kandiller-ali-soyyigit-3qhc8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kandillere can verir

Kandili yakan eller

Kıyameti durdurur

Semaya bakan eller

Kandil teşekkür sana 

Sana iyi kandiller', 'Kandillere can verir Kandili yakan eller Kıyameti durdurur Semaya bakan eller Kandil teşekkür sana  Sana iyi kandiller...', ARRAY['Türk Edebiyatı','Şiir','Ali Soyyiğit']::text[], 8.5, '{"poet":"Ali Soyyiğit","poet_slug":"ali-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iyi-kandiller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arada bir uğra...', 'arada-bir-ugra-dilek-egri-goalr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'saçlarımda öpüşlerin takılı

düşmesinler

tutuyorum...! 

yatarken çıkarıp baş ucuma koyuyorum

yıldızların gözünü alıyor............

............biri sağıma biri soluma

................yokluğunla oyunlar oynuyorum.

ellerimde ellerinin izi

hayat çizgin bana yakın.........

...........................yolunun üstü

..............................uğramadan geçme sakın...! 

bir demet papatya ısmarla boynuma senden hatıra

bırak tenimde bıraktığın sıcaklıkla sulayım 

arada bir uğra tenime,soğutma

paptyalarıda soldurma..

...........................................

...desem

.......aslında 

...............beni!', 'saçlarımda öpüşlerin takılı düşmesinler tutuyorum...!  yatarken çıkarıp baş ucuma koyuyorum yıldızların gözünü alıyor............ .............', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/arada-bir-ugra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmezsin(Beyit)', 'gelmezsin-beyit-abdulkadir-karaca-r99bv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hiç sensiz kalmadın,sensizliği bilmezsin

Bu ne eziyettir yar,beklenir de gelmezsin 

(23.08.2005)', 'Sen hiç sensiz kalmadın,sensizliği bilmezsin Bu ne eziyettir yar,beklenir de gelmezsin  (23.08.2005)...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gelmezsin-beyit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey sen', 'hey-sen-yunus-isikoglu-5f4lc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özgürlüge set çeken 

Hey sen...

Özgürlüğe set çekemezsin

Beyinde canalanan filizleri kıran 

Hey sen...

O filizleri kıramazsın

Özgürlük ateşi yanmayı görsün

Söndürmeye gücün yetmez

Duvarlar örsen, zincirler gersen

Güneş tepeden de aydınlatır

Aydınlığı engelleyemezsin

Yıkarız duvarları kırarız zincirleri

Nasırlı eller ve yalın ayakla 

Yürürüz aydınlığa 

Çünkü özgürlük bizim hakkımız.', 'Özgürlüge set çeken  Hey sen... Özgürlüğe set çekemezsin Beyinde canalanan filizleri kıran  Hey sen... O filizleri kıramazsın Özgürlük ateşi...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hey-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Sofrası', 'dost-sofrasi-selahattin-yetgin-r6xqk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgilerin kucağında büyürken aşkımız,

Umulmadık nice düşlere hasret kaldık

Ufuklarda ışık gözledik yorgun, umutsuz,

Oturup dertleşemedik sevgili gibi seninle.

Bedenimizdeki ihtirasların deli tufanlarında,

Arzu bulvarlarında el salladık birbirimize

İçimizdeki yangınlara kovalarla su döktük,

Sevdalı yüreklerimizi asla söndüremedik.

Yıldızlar ektim saçlarına göklerden,

Bulutları kızdırdım, yağmur diledim

Seni çektim ciğerime nefes diye,

Yetmedi, yetmedi aç yüreğimize.

Şimdi, bir kaçışın öyküsü yüreğimde,

Ninnilerin kucağında masala dönüyor,

Biçare düşlerle avunmuş ömrüm, yazık,

Bir dost sofrasında kalmış yalnız yüreğim.', 'Sevgilerin kucağında büyürken aşkımız, Umulmadık nice düşlere hasret kaldık Ufuklarda ışık gözledik yorgun, umutsuz, Oturup dertleşemedik se...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-sofrasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun Bitti', 'oyun-bitti-selahattin-yetgin-t504x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaçamak bakışlar fırlatırken yüreğine,

Sessiz halatlar attın yüreğime

Kokun, sesin ve nefesin yol alırken bende,

Benim gibi titredin, biliyorum sen de.

Uçarı, haylaz, yaramaz çocuklar gibi,

Bildiğim en karmaşık oyunları oynamak,

Cezalandırıldığım günlere dönmek,

En saf gülüşlerinle  bilmekti seni sevmek.

Büyük bir ormanda kayboldum seninle,

Buncadır geceyi hançerledim dizelerde,

Kanımla besledim buncadır dizeleri,

İsyan ettim, ağladım, güldüm gelişinle.

Tapınaklar oydum sana, küçücük dünyamda,

Yalancı öpüşlere kandım gün ortası,

Aşkın paslandı, un ufak oldu, öldü,

Seven hep ben oldum, sevilen başkası.

Bir çağı daha uğurladım, bilge şairler gibi,

Varlığının sonsuzluğunda unutuldum,

Geçerken uğranılan bir çoban çeşmesi oldum,

Ey aşk, söyle bana, yine beni mi buldun? ..', 'Kaçamak bakışlar fırlatırken yüreğine, Sessiz halatlar attın yüreğime Kokun, sesin ve nefesin yol alırken bende, Benim gibi titredin, biliyo...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyun-bitti-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost''luk...', 'dost-luk-nurdane-diken-y40qn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanın gerisinden, geliyorum.

Dost''luk adına. 

Dost bulurum diye, her kapıyı çalıyorum 

Her kapının arkasında, dost bulurum diye bekliyorum. 

Ne bir Sevgi, ne bir Dost buluyorum. 

Dost meclislerine gidiyorum, 

Dost''luk nafile. 

Kırlarda ağaçlara, çiçeklere, böceklere, soruyorum. 

Bizi yokedenlere mi dost diyorsun? 

Gönül gözü ile görenlere gidiyorum. 

Sen nereden geldin! 

Bunca acı, gözyaşı boşuna mı çekiliyor, diyorlar. 

Gökyüzündeki kuşlara, yerdeki canlılara soruyorum. 

Bilmem ki nerede, diyorlar. 

Biçare, yardıma muhtaç olanlar, çaresizler, 

Sen biliyorsan, bizi ona götür, 

İnsanlara soruyorum, bizim dost''umuz paradır, diyorlar. 

Çocuklara soruyorum onlar, annem babamdır, 

Bizi dünyaya getirenlerdir. 

Sevgilime gidiyorum, senden başkası da var, diyor. 

Gökte ki yıldızlara, aya, güneşe soruyorum. 

Can dost''umu nerede bulurum? 

Sen onu yanlış yerlerde arıyorsun, 

O sende, diyorlar.........', 'Zamanın gerisinden, geliyorum. Dost''luk adına.  Dost bulurum diye, her kapıyı çalıyorum  Her kapının arkasında, dost bulurum diye bekliyorum...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dost-luk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Şimdi Avuçlarımızda', 'ask-simdi-avuclarimizda-selahattin-yetgin-pcbfg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizliğin çıldırtan saatlerinde sevi ışıklarının pırıltısından çok uzağım şimdi

Ne havanın kokusu, ekmeğin buğusu, ne de yağmurun sessizliği avutamaz beni. 

Dudağımda nice yıldızlar birikir, saçlarımda küskün kırıklıklar oluşur yokluğunda

Dön desem duymaz, özledim desem bilmez, aşkınla eridiğimi sezmezsin eyy sevgili…

Öfkelere vurulduğu zaman yürek, bir gamsız duruş olurum yüreğinde. Eğerim başımı önüme ve yaralarıma (tuz)  basarım. Ateş olur, volkan olur ülkene gelirim. Öfkelere vurulduğum zaman bebek, bir mızrap olur, türkü gönlüne dokunurum. Aşk olur, sevda olur, mutlak seni bulurum. Bilmezsin yalnız, öfkeli duruşlarımı, sorarsın kimi, sensizken garip susuşlarımı. Bir deniz, bir çığlık, belki martıyım ben, vurup devirdikçe seni bulmak isterim.

Seninle çevirdikçe gönül harmanımı, bir gökyüzü ışır başımızın üstünde. Ekin tanelerini ezen, başaklardan taneleri eleyen bir düvenin üzerinde bitmek bilmeyen bir gecenin sürgünlerini toplamak istiyorum seninle. Bir sevda ki, bize acıları çektirmeye yemin etse de yüzyıllara kafa tutacak bir öykünün kollarında büyüyeceğiz biz. Cebimizdeki umutlar hiç eksilmeyecek, bir yanımız yarım kalsa da bu sevdanın ovalarında yüreğimiz bir testiden dökülen sular gibi berrak kalacak biliyorum.

Her sevdanın sözü yarım kalır(mış)  sevgili. Yarım kalan aşklar(ın)  derin yüzlerinde bir matem sevişmesidir belki de geriye kalan. Hiçbir yüzde yüreğimize umduğumuz aşklar, beklediğimiz hiçbir şeyi fısıldayamayan nice yüreklerde, nice sevda yaralarıyla avunmadık (mı)  sevgili. Üşüyen ruhumuz, karlar içinde buz tutan ellerimiz ve sözcüklerimizin hayali ocaklarında tutuşan kütüklerimiz olmasa, nasıl severdim seni (ey)  sevgili? .

Tüm olmazlara, olmayacaklara karşın uğranılan bir liman meyhanesidir bu yaşam sevgili. Her sevenin, her acı çekenin sözcükler damıttığı bu liman meyhanesinde acılarımızı sevinçlerimize meze yapıp içmiyor muyuz. Yağmur damlasına karışmış, ışıltılara kavuşmuş bir gece değil midir avuçlarımızda tuttuğumuz. Gözlerinde bulduğum tüm bakir adacıklarda aşkın defne yapraklarıyla benzersiz bir ev yapıp birlikte, güneşi sulara serip kahkahalara durmuyor muyuz? . Sen ki, tüm sessizliklerin en uç yapraklarında, yağmur ormanlarının en bilinmez sığınaklarında ölümsüzlüğü sunmuyor musun aşk sofranda şu sevdalına? ..

Oysa sessiz vedaların vurur can evimi. Soluksuz, nefessiz kalırım buralarda ve hasretinin acı meyini içerim. Sensizliğin çıldırtan saatlerinde ışıkların pırıltısından uzak, denizlerin yakamozlarına muhtaç yaşarım. Ne havanın kokusu, ne ekmeğin buğusu, ne de yağmurun sessiz yağışı avutamaz beni. Dudağımda yıldızlar birikir, saçlarımda küskün kırıklıklar oluşur. Kırmızı güllerime kar düşer, uzak ülkelerinden haber gelmez. Dön desem duymazsın, özledim desem bilmezsin, seni sevdiğimi, aşkınla eridiğimi sezmezsin sevgili.

Sana yürüyen bir yüz, senin için ülkeler keşfeden bir kaşifim şimdi. Duaya dönen tüm şarkılarımda ismin, olup olmadık yerde aşkını söylediğimsin. Ay çizer yolumu, yıldızlar avutur gönlümü ve ben Yunus gibi, Mevlana gibi bir sana, sana yürürüm. Sırtımda biriktirdiğim yorgun aşklar bohçasıyla sessizliğe sarılır yatarım karanlık gecelerde. Bilme istersen tenimin yanıp kavruluşunu, bilme çıldırtıcı yalnızlığımı, bilme sevgili, aşkına tutsaklığımı.

Bilirim ki, her şafakta gözlerini içindeki varlığıma açıyorsun sen de. Gözlerine, yüreğine ve ömrüne sığmayan bir dolunayım ben de. Bu hayat denizinde son deniz fenerinin yandığı bir ülke var ve biz onu arıyoruz birlikte. Kilitleri mavi denizlere atılmış tüm hücrelerde yitik, cezası kesilmemiş aşklar aramıyor muyuz seninle. Zirveye ulaşamayan, sonsuzluğu bulamayan yorgun kalmış kuşların denizlere çivilendiği bu hayat sahnesinde, vurgun yemedik mi ikimiz de? . Sevdaya dair söylenen tüm şarkılarda, rotasız, pusulasız yola çıkan tüm gemilerde yolculuk yapmıyor muyuz söyle? .

Bir bekleyişin, bir özleyişin şarkısını yazdık, birbirimizi severek seninle. Gidersek küseriz biliyorsun birbirimize. Nasıl anlatılacaksa bir sevginin büyüklüğü, nasıl yaşanılacaksa bir aşkın hiç yaşanmamışlığı, öyle yaşıyoruz işte. Çırılçıplak, ama utançsız yaşıyoruz tüm aykırılıklara inat bu hayat sahnesinde. Örümcek yalnızlıklarımızla, yaşlı balıkçıların ağlarına takılacağız birgün seninle. Yüreğimizdeki martılarla, sözcüklerimizdeki yaşam pekmeziyle yitik düşlerimiz gün ışığına çıkacak elbet. Yüreğimizde biriktirdiğimiz dualarla bu küçücük dünyada bulacağız  birbirimizi elbet günün birinde.', 'Sensizliğin çıldırtan saatlerinde sevi ışıklarının pırıltısından çok uzağım şimdi Ne havanın kokusu, ekmeğin buğusu, ne de yağmurun sessizli...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-simdi-avuclarimizda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinçten Ağlıyorum...', 'sevincten-agliyorum-nurdane-diken-6usqf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu ne fedakârlık, 

Bu ne özveri, 

Bu ne baş koyuş 

Ülküye... 

Gözlerim yaşarıyor.. 

Vatanı severlerin karşısında 

Gaflet ve hıyanet 

İçinde olanlara 

Hala uyuyanlara 

Yazıklar olsun... 

Yer yerinden oynuyor. 

Vatan toprağı mutlu oluyor. 

Ey! Şehitlerim 

Kalk bir bak 

Fidanlara, civanlara bak 

Bırakır mı sizi bu insanlar, 

Kanınızı yerde kor mu, bu leventler 

Nice canlar hebâ oldu 

Vatan ve Bayrak için. 

Yine bir ordu sizinle buluşmayı bekliyor. 

Değil mi damarlarında Türk kanı dolaşıyor. 

Değil mi, Türk''lükten taviz vermiyorlar. 

Vatanım, Bayrağım, Şehitlerim 

Siz rahat olun. 

Bir avuç Vatan haini karşısında 

Çığ gibi bir inançlı ordu geliyor... 

Siz rahat uyuyun... 

Siz rahat uyuyun.... 

NE MUTLU TÜRK''ÜM..... 

NE MUTLU TÜRK KALDIM.... 

NE MUTLU TÜRK KALACAĞIM....', 'Bu ne fedakârlık,  Bu ne özveri,  Bu ne baş koyuş  Ülküye...  Gözlerim yaşarıyor..  Vatanı severlerin karşısında  Gaflet ve hıyanet  İçinde ...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevincten-agliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam, coşkuların hazin tortusu', 'yasam-coskularin-hazin-tortusu-selahattin-yetgin-1yvd3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıldızlardan çaldığım bir gülüşle seni beklerim şimdi

Tüm kapılar kapanınca, tüm perdeler çekilince karanlığa, 

Bir mum alevinde, kimi de bir ay ışığında dilsizliğin bağları çözülmez mi? .

Düşünce cemreler havaya, suya ve toprağa suskun türkümüz söylenecek nasılsa.

Sesinin, nefesinin ve yüreğinin atışlarına yetişecek çok sesli sözcükler yetiştiriyorum sana. Seni düşündükçe çocukluğumun oyun alanlarına dalıyor, bitip tükenmez şarkılarımla ve tüyden bacaklarımla gülüşlerine tutunuyorum. Bir sevincin çingene danslarında bu şiir seni anlatır yüreğimde taşıdığım sözlüklerde. Sözümü esirgemeden söyledikçe, Venüs güzelliğinin kalıntılarında sen yaşlı bir çınar ağacının gölgesinde beni beklersin inadına.

Ufuklarda yansıyan bir gemici fenerinin altında bir kadın suskun ihtiraslarını sorgulamaktadır. Kaçınılmaz bir gravürde geceleri erkekliğe soyunan bedenimiz ve kıvrılan her sigara dumanlarında aradığımız geçmişimiz yargılar bizi de. Seninle denizlerin tüm tuzlarına ismimizi yazsak, ya da bir sevdanın tüm yaşanmamışlıklarını yaşasak, soyunsak gönül avlumuzda ne çıkar. Sesini dinlemeden, nefesini koklamadan zirvelerden düşmen neye yarar.

Yaşam, coşkuların hazin tortusudur bir bakıma. Yıkıntılarda, her mevsim yeni baharlar açar, ırmaklar denizlerle buluşsun diye. Düşlerin tüm zincirlerini bırakıp bu yerkürede, ölümsüzlüğü aramak değil midir aşkı aramamız? . Tüm kapılar kapanınca, tüm perdeler çekilince karanlığa, bir mum alevinde, kimi de bir ay ışığında dilsizliğin bağları çözülmez mi? . Yara bedenimizi sarınca, büyüyünce çığlıklarımız ve de düşünce cemreler havaya, suya ve toprağa suskun türkümüz söylenecek nasılsa. 

Beni özledikçe uzayan saçlarının dalgalı denizlerinde ince sızına sızımı, bekleyişlerine özlemimi ve sevinçlerine şiirlerimi sürüp, parlak bir gökyüzünün altında yıldızlardan çaldığım bir gülüşle seni beklerim şimdi. Küskün biten binlerce gecenin ihtiras dövmelerini  ağaçlara biz yapmadık mı, yüreğimiz yeşil dursun diye? . Bir yel gibi sokulup birbirimizin içine aramızdan geçen nice ırmaklarda birbirimizi şiirlerimizle ıslatmadık mı? ..

Ve bu umut döşeğinde bal mayalarken arılar, kan emiciler ve kara kargalar dolaştıkça başımızda niye sevmez aşkı sevgisizler? . Ben seninle sağrısını okşarım beyaz yeleli bir atın. Ben seninle yaramı sargısız sererim güneşlere ve ben seni bir başkaldırının öfkesi gibi içimde taşırım. Seni düşündükçe, seni sevdikçe turuncu memelerin, mavi denizler gibi coşan dudakların ve kekik kovuğu yüreğin böler uykularımı. Sensiz, yüreğimin tüm fırtına tepelerinde bir hasret türküsü söylerim.

Yosun gözlerinin tiryaki güzelliğinde, her gece binlerce şehirler uyanır uykularından ben seni özledikçe. Hasret yüreğimizi her vurduğunda güller fışkırır topraktan, biz birbirimizi bekledikçe. Gözlerin ki, kıpırtılı bir bekleyiş oluyor ve ak kağıtlara, bobinlere sarıyorum seni sevdiğimi. Dizelerde yüreğime saplanmış bir bıçak oluyor, ışıklı şafaklarına coşkuyla bakıyorum. 

Yüreğini ağrıtan tüm bıçak sırtlarında özündeki vefa, sözündeki gizemle bölüşürsün ekmeğini benimle. Acılarının yüreğini tırmalayan ince sızılarında aydınlık bir gökyüzünün altında sana yürümek istiyorum ben. Suskunluğumuzun bıçağı kınından çıkacak ve yıldız sevişmelerine duracağız birlikte. Yurdumuz filizlenecek, ovalarımız tanelere duracak ve uykusuzluğumuzun kapılarını açacağız pembe rüyalara. Cemreler düşmekte bak yemyeşil bahçelerimizin topraklarına. Sularımız ılık ılık yüreğimize akacak sonra. Son cemre de yüreğimize düşünce, bu yeryüzü atlasında sevişecek bir yer bulacağız elbet kendimize.', 'Yıldızlardan çaldığım bir gülüşle seni beklerim şimdi Tüm kapılar kapanınca, tüm perdeler çekilince karanlığa,  Bir mum alevinde, kimi de bi...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasam-coskularin-hazin-tortusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-hulya-karaca-43ygh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar, uçsuz bucuksız, zamansız yollar

Gurbeti bana tatdıran. 

Hasreti sol yanıma işleyen 

Gözlere çiğ gözyaşını eken yollar

Dağa bağıran, haykıran dertli yollar

Sağa sola dağılan gamlı

Özlemlere gem vuran

Dertli,  dermanı arar de get yollar

Güneşle doğup bir olan yollar

Ayla birlikte geceye dalan 

Yıldızların ışıltılı mabetinde

Al git artık bu hasreti al da git yollar

Denizler dalga sen yamaçsın yollar

Rüzgar eser geçer elbet gider

Karanlık çöksede aydınlık gelir

Bırak yakamı sende git yollar

Bülbül hüsrandadır gidemez yollar

Sevgimi bağrımda sökemem ki

Derya deniz gözümde neki

Vazgeçip gelemem sen git yollar', 'Yollar, uçsuz bucuksız, zamansız yollar Gurbeti bana tatdıran.  Hasreti sol yanıma işleyen  Gözlere çiğ gözyaşını eken yollar Dağa bağıran, ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yollar-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ergen Ve Aile', 'ergen-ve-aile-halay-sadi-qehnw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oğlan babaya,

Reddedilince trip yapıyorsun dedi

Vay anam vayyy

Bak şu yeniyetmenin yaptığına

Bakar mısın saygısızlığa

Anne de müdahale etmedi

Babaya trip denmez demedi

Eee saygısızlığın müsebbibi annedir

Bunu da tüm babalar bilir(!) 

Oğlanda yaş onbeşse

Babalar artık kahraman değildir

Onbeşlik oğlan,

Beni de adamdan sayın tavrında

Kırklık baba,

Sen çocuksun ben de baba savında

Anneye göre,

Gencin tavrı geçici,sabır gerek

Babaya göre,

Anlatılmazsa bu tavrı doğru bilecek

Anneye göre,

Kendini ifade etmesine izin vermeli

Babaya göre,

Hayata,büyüğe asi duruşunu yermeli

Anneye göre,

O yaşlarda hepimiz asi olduk

Babaya göre,

Her daim büyüklerin büyüklüğünü bildik

Neticede görünen o ki,

Hepimize kendi görüp yaşadıklarımız doğru

Farkındayız, elbet geçecek bu günler

Başka günler başlayacak

Ve başka sorunlar

O yüzden, sorunu ne gözümde büyütmeliyim

Ne de yok saymalıyım

Sorunu kendi ölçeğinde görüp

Yara almadan ve yaralamadan

Yol almalıyım…

05.8.2005/Antalya', 'Oğlan babaya, Reddedilince trip yapıyorsun dedi Vay anam vayyy Bak şu yeniyetmenin yaptığına Bakar mısın saygısızlığa Anne de müdahale etmed...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ergen-ve-aile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*[Kadim Dostlar]*', 'kadim-dostlar-seyhmus-sevilmez-otqjm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zifiri karanlıkta, ilk onlardır görünen

Yıldızları takınca, gördüm kadim dostları

Paylaşılan sevgiydi, ilmik ilmik örünen

Gönüllere akınca, gördüm kadim dostları.

Bir zamanlar varlıkta, çevremde cirit atan

El uzattım darlıkta,  yüzü çevirip yatan

Gerçekleri zorlukta, görüp desteği katan

Sahte yüzden bıkınca, gördüm kadim dostları

Moralim bozulunca, hemen desteği coşar

Dertlere üzülünce, neşeyle bana koşar

Çaresiz süzülünce, yardımı cana taşar

Gafil yürek yakınca, gördüm kadim dostları 

Bir kalburla eledim, üstte ikisi kaldı,

Gerçek yoldaşım olan, benle maziye daldı

Çocukken beraberdi, büyüdü sevgi saldı

O sevgiyi ekince, gördüm kadim dostları

Gücüme güç katarlar, hem sağım hem de solum

Karanlığa çatarlar, aydınlatırlar yolum

Hep sevgiye batarlar, tutup kucaklar kolum

Çullanınca sakınca, gördüm kadim dostları

Bu can kefeni giyip bir gün toprak olsa da

Dostlarım ağıt ile saç başını yolsa da

Mezara çiçek ekip, gözleri yaş dolsa da

Başucuma bakınca, gördüm kadim dostları

(23.08.2005/Batman)', 'Zifiri karanlıkta, ilk onlardır görünen Yıldızları takınca, gördüm kadim dostları Paylaşılan sevgiydi, ilmik ilmik örünen Gönüllere akınca, ...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kadim-dostlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (88) ''Yosun Gözlü Dilberim...''', 'maniler-88-yosun-gozlu-dilberim-abdullah-atay-t1xzf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gurbet elde kimsesiz

Ağlarım sessiz sessiz

Cenneti de verseler

Ne yapayım ki  sensiz...

Ah benim arsız gönlüm

Kalp çalan hırsız gönlüm

Dünya onun olsa da 

Duramaz yarsız gönlüm...

Yosun gözlü dilberim

Gönlümdür senin yerin

Kor ateşte değil de

Bakışınla eririm..

Su akar serin serin

Yürekte yaram derin

Dünyalar sizin olsun

Bana sevdiğim verin...

Gonca gülüm açıyor

Mis kokular saçıyor

Ak gerdanı açınca

Yar kendinden geçiyor...

Hüzünlerden kal uzak

Sevgi büyüt dal budak

Şekerden bilem datlı

O yardaki bal dudak...

O yarin adı Neşe

Benzer doğan güneşe

O’nu bir gün görmesem

Gönül düşer ateşe...

Gençlik elden giderken

Yanarız için için

Para pul malk mülk derken

Unutulur dost niçin...', 'Gurbet elde kimsesiz Ağlarım sessiz sessiz Cenneti de verseler Ne yapayım ki  sensiz... Ah benim arsız gönlüm Kalp çalan hırsız gönlüm Dünya...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maniler-88-yosun-gozlu-dilberim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Necip Fazıl misali', 'necip-fazil-misali-olumun-adi-5zp4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sokak ortasındayım ve yalnızım.

Hani eş dost,hani çeken nazım.

Ben de Necip Fazıl misali yalnızım,

Kaldırımlar da canciğer kuzu sarmam...', 'Bir sokak ortasındayım ve yalnızım. Hani eş dost,hani çeken nazım. Ben de Necip Fazıl misali yalnızım, Kaldırımlar da canciğer kuzu sarmam.....', ARRAY['Türk Edebiyatı','Şiir','Ölümün Adı']::text[], 8.5, '{"poet":"Ölümün Adı","poet_slug":"olumun-adi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/necip-fazil-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cin Ali  ile Başlar Aşk...', 'cin-ali-ile-baslar-ask-ayse-i-smetoglu-qh27d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A - Lİ   BAK   BU  AŞK! 

....

Bak! 

hayatın basit dönencelerinden,

gözlerimin içindeki senli hecelere..

apansız bir başlangıç 

bekliyor şimdi bizi,

sarı sayfalı alın defterinde 

yaş yedinin pembe mantığından

süzülüyor aşk,

ve  dökülüyor ipe dizili sevgi terimleri

hayat tahtasının önüne! ! 

a-li  bak  bu  aşk! 

görmezden gelme 

görmezden geldiklerin

saklı sende....

A-Lİ   KAL-Bİ-Mİ   TUT 

....

Tut 

tüm kopuşlara inat 

uzat  elini düşüşlerime 

şehrin tiksinti dolu hücrelerinden, 

sana kaçarken

ayaz doluştu  geçmişime! ! 

yaş yedinin minik ellerinde,

seninle yaşamaya, 

yazmaya seninle başlamak.. 

yanlızlığımı  tek hecelere 

eğri çizgilere, korkularımı saklamak! ! 

a-li   kal-bi-mi   tut! 

düşmelerin sınırı çizildi,

kalp atışlarıma! 

tut avuçlarımı 

kalmadı uçuruma ramak...



not: Burdaki ''Ali '' ismi   ilköğretimde kullanılan kitaplarda geçtiğinden dolayı kullanılmıştır..Kimseye ithafen değildir...', 'A - Lİ   BAK   BU  AŞK!  .... Bak!  hayatın basit dönencelerinden, gözlerimin içindeki senli hecelere.. apansız bir başlangıç  bekliyor şimd...', ARRAY['Türk Edebiyatı','Şiir','Ayşe İsmetoğlu']::text[], 8.5, '{"poet":"Ayşe İsmetoğlu","poet_slug":"ayse-i-smetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/cin-ali-ile-baslar-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden kaçıyorum', 'senden-kaciyorum-burhan-kucuk-90fje', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden kaçıyorum

Topladım 

Gidiyorum..... 

Kendi yalnızlığıma

Kırık dökük bavulum

Senden kaçıyorum

Yalın ayak 

Üşüyorum 

Sensizliğe koşarak

Ardımdan şarkı söyle

Kurtuldum diye 

İstersen bağır 

Serseri diye

Burhan KÜÇÜK

Kdz.Ereğli-23.08.2005-13:30', 'Senden kaçıyorum Topladım  Gidiyorum.....  Kendi yalnızlığıma Kırık dökük bavulum Senden kaçıyorum Yalın ayak  Üşüyorum  Sensizliğe koşarak ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senden-kaciyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonumuz ''Vah Vah''a Kaldı...', 'sonumuz-vah-vah-a-kaldi-dursun-elmas-8wcv0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '____Gönüldaşım Zülfikar Yapar Kaleli''ye

Yüreğimiz yaralandı 

Ciğerimiz paralandı 

Geçmişimiz karalandı 

Hâlimiz ''berzah''a kaldı. 

Gem vuruldu sözümüze 

Gurbet olduk özümüze. 

Çok vururuz dizimize 

İşimiz ''Allah''a kaldı. 

Angel oldu Halimeler 

Güme gitti Salimeler 

İmgelendi kelimeler 

Dilimiz küstaha kaldı 

Şu sorunu, bu sorunu 

Yıktık millet onurunu. 

Dede anlamaz torunu 

Sözümüz ''eyvah''a kaldı. 

Azınlıklar yasasında 

Ülke bitişin yasında

Beyler parsa tasasında 

Ülkemiz penâha kaldı

İnkârdayız ceddimizi 

Bilemedik haddimizi 

Karartınca bahtımızı 

Günümüz ''bedhah''a kaldı. 

Elmas der,dost Kaleli'' ye; 

Bu gidiş acep nereye

Bindik bir meçhul gemiye 

Sonumuz “vah vah”a kaldı.

Dursun ELMAS', '____Gönüldaşım Zülfikar Yapar Kaleli''ye Yüreğimiz yaralandı  Ciğerimiz paralandı  Geçmişimiz karalandı  Hâlimiz ''berzah''a kaldı.  Gem vuruld...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sonumuz-vah-vah-a-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelde Ver Elini Dönüşsüz Çıkalım Bahara', 'gelde-ver-elini-donussuz-cikalim-bahara-kamil-soylemez-ir63i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabancı olgunlaşmada

Bir derin mavi var, derya

Aklım da sen 

Başımda sevdan

Bir de bir kaç tel saçın

Avuçlarım da

Araba da istemeden bıraktığın

O bir kaç teli öpüyor,kokluyorum

Özleminle ağlıyorum 

Göz yaşım karışıyor saçlarına

Özlemin oluyorda acı bana

Bir yanıyor bir donuyorum

Gözlerin geliyor aklıma 

O dalıp giden gözlerin

Gülüyordun bana usulca

Bense seni sayıklıyordum

İki kelimelik adınla

Haydi gel diyordum sana

 Gel de ver elini aşkım ver

Geri dönüşssüz çıkalım bahara', 'Sabancı olgunlaşmada Bir derin mavi var, derya Aklım da sen  Başımda sevdan Bir de bir kaç tel saçın Avuçlarım da Araba da istemeden bıraktı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelde-ver-elini-donussuz-cikalim-bahara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Beşyüzler/1500''ler', 'bin-besyuzler-1500-ler-sezai-sengonul-x9e6j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kulaklar gözler

Duydunuz gördünüz

Endülüsü Gırnatayı

Acı/ Ne acı

Acı ne

Yazdığı Bleda''nın

Ya yazamadığı sözler

Yokmuydu ilacı

Ki denizler iç çekermiş

İçin için hala

Kırmızıymış gözler

Neden niçin hala

Ki günde batarmış

Kurtuba da işbiliye de yine

Işıtmazmış ama kandiller

Oraları artık

Yerine yıldızların

Aydınlatırmış yeri göğü

Ayışığı gibi masum

Ö gözler o yüzler

Birde yakarmış içini

Dile gelmez

O yaralı sözler

Ki kovulurmuş şimdi

Tüm acılı kapılardan

Acı doğururmuş

Ağlarmış için için

Günahı için

Binbeşyüzler...', 'Kulaklar gözler Duydunuz gördünüz Endülüsü Gırnatayı Acı/ Ne acı Acı ne Yazdığı Bleda''nın Ya yazamadığı sözler Yokmuydu ilacı Ki denizler iç...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bin-besyuzler-1500-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-abdurrahman-tepe-izi7o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ekmeğini yedik suyunu içtik

Bizleri bağrına bastın sen dünya

Hoyratça biz sana libaslar biçtik

Sağ olasın var olasın şen dünya

Biz senin üstüne konaklar kurduk

Epey hırpaladık epeyce yorduk

Yine de biz senden ihsanlar gördük

Hayat kaynağısın cana can dünya

İmkanlar fırsatlar kaynağı oldun

Çok kere boşaldın çok kere doldun

Biz sana zulm''ettik sen bize güldün

Zalimler elinde ağla-yan dünya

Hak seni evrenle yarattı yoktan

Haddini bilmeyen mahvoldu çoktan

Lütuf ikram gördük cenab-ı haktan

Sen de SAMİHİ''yle hakka dön dünya', 'Ekmeğini yedik suyunu içtik Bizleri bağrına bastın sen dünya Hoyratça biz sana libaslar biçtik Sağ olasın var olasın şen dünya Biz senin üst...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi birbirine bağlayan gücün', 'bizi-birbirine-baglayan-gucun-mikdat-bal-wsncw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizi birbirine bağlayan gücün 

Elektrik olduğu biliniyor mu? 

Gidip gelmiyoruz acaba niçin? 

Komşuluğa gidip geliniyor mu? 

Biri hasta mıdır, bir telefon aç! 

En yakın komşunu ziyaretten kaç! 

İnsan birbirine değil mi muhtaç? 

Hiç komşunun zili çalınıyor mu? 

Yabancı yayınlar bozuldu diller 

Aileden öne geçiyor eller 

Uyuştu beyinler, öldü gönüller 

Bunlar hiç dikkate alınıyor mu? 

Bazen tüm işlere ara vererek

Arabaya binip yola girerek! 

Anneyi babayı gidip görerek

Arada yatıya kalınıyor mu? 

Bu ikaz geçerli sana bana da 

Yediden yetmişe baba ana da

Gafletten ayıp da gerçek manada

Hakiki efkâra dalınıyor mu? 

Mikdadi der sitem değil, uyarı! 

Bozuldu sıhhatle, gözün ayarı 

Bir kere kapatıp bilgisayarı 

Beraber eğlenip gülünüyor mu? 

Ozan Mikdadi', 'Bizi birbirine bağlayan gücün  Elektrik olduğu biliniyor mu?  Gidip gelmiyoruz acaba niçin?  Komşuluğa gidip geliniyor mu?  Biri hasta mıdır...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bizi-birbirine-baglayan-gucun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelip Geçti', 'gelip-gecti-mahmut-ulusoy-jc6f0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir durakta bekliyordum

Yaşım beni gelip geçti

Akıttı dert ummanına

Başım beni gelip geçti

Dürüst yazdım heceleri

Gelip geçti niceleri

Sayıkladım geceleri

Düşüm beni gelip geçti

Anlamadım nasıl dünya

Ömrüm geçti sanki rüya

MESULİ''de öldü güya

Naşım beni gelip geçti', 'Bir durakta bekliyordum Yaşım beni gelip geçti Akıttı dert ummanına Başım beni gelip geçti Dürüst yazdım heceleri Gelip geçti niceleri Sayık...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelip-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G.Z''nin Gecmemis $iirleri 4', 'g-z-nin-gecmemis-iirleri-4-huseyin-avdic-kejjo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oku! 

Oku! Oku! Oku! 

Neyi istersen onu.

Ister evreni, ister kendini

Yeter ki, oku! 

Ama, ''Yaratan''in adi''yla.

******

 Okumak

 Nedir okumak? 

-Beyin doldurmak,

 Gönül doldurmak! 

 Yoksa doldurmak,

 Bo$tur okumak...

******

''Oku''yu Okumak

Okumak, ene''yi yirtmak, Hüve''yi bulmak.

Okumak, ben yumak yumak, ben''i dokumak.

Okumak, O''nu bulmak, ''Oku! ''yu okumak.

Bati Berlin, 1980-85.', 'Oku!  Oku! Oku! Oku!  Neyi istersen onu. Ister evreni, ister kendini Yeter ki, oku!  Ama, ''Yaratan''in adi''yla. ******  Okumak  Nedir okumak?...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/g-z-nin-gecmemis-iirleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmıyorum', 'sanmiyorum-sahin-erturk-z0yer', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutlarım başka bahara

İşte yine HAZAN MEVSİMİ

Yine gelmedin

Yine sorunlar girdi araya

Yine

İSTANBULU bırakamadın

Hep birşeyler oluyor

Birşeyler giriyor araya

Sorun bende mi? 

Yoksa sende mi? 

Şaştım kaldım doğrusu

Yüreğime KRAMPLAR var

Zaman,zaman tekliyor

Güven vermiyor bana

Hasretin zirve yaptı

Yokluğun bitirdi beni

Şarkılar,Şiirler,Mesajlar

Avutmuyor artık beni

Cesurluğum da kalmadı? 

İnatcılığım da...? 

Korkağın biri oldum çıktım

Yalnızlıktan korkuyorum

Gecelerden korkuyorum

Yarınımdan korkuyorum

Tıpkı senin gibi

Hiç kimse anlamıyor beni

Yine mazeretler yığmışsın

Yine aşamadın dağları

Yine gelmedin,gelemedin

Yine KRAMP girdi yüreğime

Yine hazan mevsimindeyim

Yine umutlarım başka bahara

Yine ler bitmek bilmiyor

Herşey böyle giderse

Sanmıyorum güzelim

İkibin altı baharını göreceğimi

Sanmıyorum,sanmıyorum

(23.08.2005-Yeni)', 'Umutlarım başka bahara İşte yine HAZAN MEVSİMİ Yine gelmedin Yine sorunlar girdi araya Yine İSTANBULU bırakamadın Hep birşeyler oluyor Birşe...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sanmiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bana Sor', 'gel-bana-sor-mahmut-ulusoy-afy2y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç aram yok feleğinen

Gizli vurur keleğinen

Su taşıtır eleğinen

Gel sen onu gel bana sor

Bilirsin çok yalancıdır

Rüzgar ona aracıdır

Çalar çırpar talancıdır

Gel sen onu gel bana sor

MESULİ köşkler yaptırır

Toza toprağa kattırır

Bak köle gibi sattırır

Gel sen onu gel bana sor', 'Hiç aram yok feleğinen Gizli vurur keleğinen Su taşıtır eleğinen Gel sen onu gel bana sor Bilirsin çok yalancıdır Rüzgar ona aracıdır Çalar ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-bana-sor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Mekânı...', 'askin-mek-ni-i-brahim-ethem-bingul-khgxe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara gözlü mutluluğum

Bakışlarında geceyi saklayanım

Tebessümünde rengarenk açanım

Neredesin? Kiminlesin? 

Demeyeceğim..

Biliyorum

Bendesin, benimsin...

Gitti,bitti

Unuttu...

Zaman geçiyor

Hayat neler getiriyor

Diyorlar,diyorlar,diyorlar

Bilmiyorlar seni

Bilmiyorlar aşkı...

Aşk

Zamanın durduğu bir anda kaybolmak

Ve buluşmak seninle

Mekânın olmadığı bir yerde

Yine söylüyorum

Neredesin demeyeceğim

Biliyorum...

www.iebingül.com', 'Kara gözlü mutluluğum Bakışlarında geceyi saklayanım Tebessümünde rengarenk açanım Neredesin? Kiminlesin?  Demeyeceğim.. Biliyorum Bendesin,...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/askin-mekani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Kızı', 'turk-kizi-saim-bastik-aob2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir güzel sevmişim saçları uzun

Bana zemheriyi yaşattı yazın

Vallahi karıştı gecem gündüzüm

Düşürdü gönlüme ince bir sızı

Sevdiğime değer tam bir TÜRK kızı.

Bir güzel sevmişim hilaldir kaşı

Yeni onsekize değmiştir yaşı

Unutturdu bana bacı gardaşı

Dilerim Allah''tan ayırmaz bizi

Sevdiğime değer tam bir TÜRK kızı.

Bir güzel sevmişim gözleri kömür

O gözler bakınca eritir demir

Ayrılmam ben artık ondan bir ömür

Sevdaya düşmüşüm çalarım sazı

Sevdiğime değer tam bir TÜRK kızı.

Bir güzel sevmişim incedir beli

Sürüklüyor beni aşkının seli

Gördüğümden beri olmuşum deli

Deli divaneye döndürdü bizi

Sevdiğime değer tam bir TÜRK kızı.

23/08/2005', 'Bir güzel sevmişim saçları uzun Bana zemheriyi yaşattı yazın Vallahi karıştı gecem gündüzüm Düşürdü gönlüme ince bir sızı Sevdiğime değer ta...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/turk-kizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Mermi.', 'tek-mermi-i-shak-ozlu-8y6pj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Çınar fidanı dikti sabah ile,

Bir evlat düştü hasbahçeye akşam ile.

Çınara su,bebeğe süt verdi aşk ile,

Sevinç geldi,güzellik geldi bu hal ile.

Kışta fidanlar üşümesin diye sardı,

Onun dünyaya ilk kez gülüşünde vardı.

Çınarın suyuna,bebeğin ak sütüne,

Sevğinin kırkbir çeşidini katıp kardı.

Büyüdü çınar dalına kuşlar konuyor,

Evlat dersen hukuk son sınıfı okuyor,

Bahçe hoşnut,dal hoşnut serpilmiş fidanlar,

Emekle umutta yirmiüç yıl doluyor.

Bir maganda takımı için seviniyor,

Bir tek mermi bir geleceği bitiriyor,

Yıllarca emek verilip umut bağlanan,

Bir yiğit çınar dibinde can yitiriyor.

Not:Tabanca taşıyan ve sevincini mermi atarak belirten korkak insanların mermilerine maruz kalan masum canlara ithaf edilmiştir.', 'Bir Çınar fidanı dikti sabah ile, Bir evlat düştü hasbahçeye akşam ile. Çınara su,bebeğe süt verdi aşk ile, Sevinç geldi,güzellik geldi bu h...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tek-mermi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Değmemiş Fırça Darbeleri', 'el-degmemis-firca-darbeleri-asli-evrensel-ed2kf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'el değmemiş fırça darbeleri 

asılmış merdiven üzerinde 

karşılanıyor konuklar

sessiz bekliyor 

hala sıcak 

artık takvimlere duyarsız

yosun bahçeler 

yanlış asıldığı yer 

bakışlar

karanlık gölgelere boyanmış

yürekler değmiş

yüreğine değilmemiş odanın

baş köşesinde süzülmüş halı

sessiz dilekler dilenmiş dokuyan 

yeni dileklerle gelmiş dokunan

perde açılmış

cam seyre karışmış

yıldızlarla motifler

uyuyan dileğe rüyayla dolanmış

ay sabrı yıldızlara emanet

pencereden içeri dalmış

ilişmiş yatağın ayak ucuna

seyretmiş huzursuz uykuların

yükler altındaki dileğini

tutmuş uyanan ellerini

şarkısı gecenin omzuna dayanmış

söylemiş ki

göğe bıraktım dileğini

uyansın ki gözlerin

kucaklaşabilsin yüreğin

ay şarkıya boyanıyor denizle

öğütlüyor dinle

toprağa varacaksak tek tek

koynunda mı gidecek beklediklerin

silebilir ışığım acısını hataların 

başaramamışlıkların

ay fırça, deniz resim

her gittiğin göğe

seninle gelecek denemediklerin

tek şansın içinde saklanan dileğin', 'el değmemiş fırça darbeleri  asılmış merdiven üzerinde  karşılanıyor konuklar sessiz bekliyor  hala sıcak  artık takvimlere duyarsız yosun b...', ARRAY['Türk Edebiyatı','Şiir','Aslı Evrensel']::text[], 8.5, '{"poet":"Aslı Evrensel","poet_slug":"asli-evrensel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/el-degmemis-firca-darbeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gemiyim Yolculuğum Sana', 'son-gemiyim-yolculugum-sana-kamil-soylemez-q9b4k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son gemiydim...

Sana doğru...

Son seferinde ilerleyen

Son gemi..

Çılgın dalgalarda bata,çıka

Geliyorum sen kucağına

Hasretin aldıda beni

Düştüm yollarına

Kara sevda yüklü

Son gemiyim

Başka yolcu arama

Bilki ölsemde dönüşüm yok geri

Olmayacakta

Bekle beni birtanem

Rotam sana

Olur da batarsam

Sen göklerde beni ara

Yıldız olup,göz kırpacağım sana

Güneş olup,ısıtacağım

Ve hep sana bakacağım

Yatağın baş ucunda her gece 

Bir gül bırakacağım

Bir de buse dudaklarına

Kokun alacağım derinden

O ipek gibi teninden

Sen anlayacaksın geldiğimi

Bir tek sen

Sakın üzülüpte ağlama

Kıyamam da sonra kayarım

Bir yıldız gibi uzaklara', 'Son gemiydim... Sana doğru... Son seferinde ilerleyen Son gemi.. Çılgın dalgalarda bata,çıka Geliyorum sen kucağına Hasretin aldıda beni Düş...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/son-gemiyim-yolculugum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'I wish I were', 'i-wish-i-were-abdullah-acar-q5nei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I wish I were the one who is loved

and read poetries in his face

under a scattering moonlight

in the drunk darkness in which

only the sparks of eyes glisten

In the far distances, in the skies

I wish I leant againist a plain tree

with roots hidden in clouds

and closed my eyes

far from everyone

far from everything

Or, I wish I were a phoenix

that dived into the blue deepness

landed on the acme of the Kafs

and found valley of Emeralds', 'I wish I were the one who is loved and read poetries in his face under a scattering moonlight in the drunk darkness in which only the sparks...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/i-wish-i-were-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanacak güzel bir gün', 'yasanacak-guzel-bir-gun-erol-buker-5ffgp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tüm televizyon kanalları  beni haber yapmış

tüm aksam gazetelerinde resmim varmiş

yarın  asacaklarmış beni

boşverrr

hiç önemi yok bunların ! ! 

Şimdi önümde

seni sevmek için 

seninle kavga etmek için

senden ayrılmak icin

dahası seni özlemek için 

yaşanacak güzel  bir gün daha var ya.', 'Tüm televizyon kanalları  beni haber yapmış tüm aksam gazetelerinde resmim varmiş yarın  asacaklarmış beni boşverrr hiç önemi yok bunların !...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasanacak-guzel-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matem yüzlü güzel', 'matem-yuzlu-guzel-erol-buker-1lmac', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin gözlerin siyah

kaşların, saçların

umutlarında siyah öyle mi

anan seni matem gününde doğurmuş güzelim

karagözlüm.

matem yüzlüm.', 'Senin gözlerin siyah kaşların, saçların umutlarında siyah öyle mi anan seni matem gününde doğurmuş güzelim karagözlüm. matem yüzlüm....', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/matem-yuzlu-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Aklımı Başımdan Alan Güzel', 'sen-aklimi-basimdan-alan-guzel-kamil-soylemez-t50pc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O kadar etkiledinki beni

Bir alımlı,yürüyüşün

Bir busen var ya

O kalkıpta giderken

Göz kırpman

Aldın aklımı başımdan

Dağıldım kumlar gibi

Deniz kıyılarındayım şimdi

Titriyorum doğrusu

Şu an tir tir titriyorum

O gözlerin derin mavisi

Benim sonum oluyor

Çıkıyorum mavilere

Yüreğimde bahar

Sarıp sarmalıyor sen sevdanla

Kuş oluyor yüreğim sana çırpınan

üf yaaaaaaaaaaa

Bana neler oluyor böyle

Söylermisin kara sevdam

Seninle olamasamda

Bilki ben seninleyim her zaman', 'O kadar etkiledinki beni Bir alımlı,yürüyüşün Bir busen var ya O kalkıpta giderken Göz kırpman Aldın aklımı başımdan Dağıldım kumlar gibi De...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-aklimi-basimdan-alan-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelin Peşindeyim', 'guzelin-pesindeyim-burhanettin-akdag-ct5tf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun yıllardır

Güzelin peşindeyim arkadaş.

Gözleri ahu

Dudakları kızıl

Gülüşü gonca gül

Bakışları fırtına

Sevdası okyanus

Sevgisi gökyüzü

Umutları papatya

Dokunuşı ipeksi

Endamı alımlı

Gözyaşları hüzün kokulu

Ruhu derin

Yüreği engin

Saçları lepiska

Etekleri fırfır

Gönlü zengin.

Var mıdır acaba? 

Dünyada böyle güzel 

Tasviri bile insanı yorar

Ben yıllardır arıyorum

Bulan, gören varsa eğer

Bir koşu haber etsin.

Son nefesime kadar da

Peşindeyim güzelin arkadaş

O güzel ki

Güzelliğin ta kendisi...

(23.08.2005)', 'Uzun yıllardır Güzelin peşindeyim arkadaş. Gözleri ahu Dudakları kızıl Gülüşü gonca gül Bakışları fırtına Sevdası okyanus Sevgisi gökyüzü Um...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/guzelin-pesindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmek İsterim', 'gormek-i-sterim-mustafa-alpaydin-3efzo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim ilk aşkım ilk gözağrımsın

Bana benden yakın şahdamarımsın

Mevsimler içinde ilkbaharımsın

Ben seni yanımda görmek isterim

Yuvamız üstünde baca tütünce

Sıcak yaz günleri kışa dönünce

Gönül penceremde kuşlar ötünce

Senin nefesini duymak isterim.

İsmimi andığın dualarında

Tebessüm eksilmez dudaklarında

Gamzeli alpembe yanaklarında

Sevinç gözyaşları görmek isterim.

Sensiz geçen günün yorgunluğunda

Gecenin gizemli karanlığında

Derin uykulara daldığım anda

Rüyamda hep seni görmek isterim.', 'Sen benim ilk aşkım ilk gözağrımsın Bana benden yakın şahdamarımsın Mevsimler içinde ilkbaharımsın Ben seni yanımda görmek isterim Yuvamız ü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gormek-isterim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Öyle Bakma', 'bana-oyle-bakma-ozan-ozel-x9iuz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yersiz bir kuşkuyla 

bana öyle bakma 

inan sözüme 

seni sevmiyorum 

deyişime inan 

gerçeği gözlerimde arama 

ne olur 

bana öyle bakma... 

www.erolayyildiz.tr.gs', 'yersiz bir kuşkuyla  bana öyle bakma  inan sözüme  seni sevmiyorum  deyişime inan  gerçeği gözlerimde arama  ne olur  bana öyle bakma...  ww...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bana-oyle-bakma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh Halleri', 'ruh-halleri-bekir-mutlu-gokcesu-iuyxk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uslandırmak istediğim bir çocuğu okşar gibi

Dokunmak yüzüne denizin avuçlarımla

Acıtmadan canını uçar gibi yürümek dalgalarında

Ve dindirip öfkesini sırt vermek kayalara...

Ay kayıp düşerken mesela karşı damdan

Koşup, uçup hatta, kucaklamak

Ve beraberce yuvarlanmak bayır aşağıya...

Yazmaktan öte, yaşamak daha çok hani

Her zaman resmedemediğim bu ruh halleri...', 'Uslandırmak istediğim bir çocuğu okşar gibi Dokunmak yüzüne denizin avuçlarımla Acıtmadan canını uçar gibi yürümek dalgalarında Ve dindirip ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruh-halleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorduk...', 'seviyorduk-ali-baksi-x7tq2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İsimsiz kahramanlar oldu

Yitip giden yıllarda

Seviyorduk aşktı ötesi

Gercek arıyorduk icimizden

Hatıraları andık

Sunduk gelecek düşlere

Gitmelerimiz gelmelerimiz oldu

Yollar bitmedi ömür bitti yamacında

Seviyorduk! ! ! 

Hemde cok şeyi seviyorduk

Aşktan bahsederken

Mazeretlerimiz vardı

Yalandı? ? ? 

Arayışlar vardı

Yaşandı ötesinde cizğinin

Gercekleri hobi yaptık fobilerle

Bu bizim istediğimiz değildi yamacında

Seviyorduk 

Herkez dürüst tü aslında

Cıkarları bıraktık arada...', 'İsimsiz kahramanlar oldu Yitip giden yıllarda Seviyorduk aşktı ötesi Gercek arıyorduk icimizden Hatıraları andık Sunduk gelecek düşlere Gitm...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seviyorduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-birsen-i-brahimhakkioglu-6ys21', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçim yanıyor

Sanki alevler saçıyor

Ayrılıklar yüreğimi dağlıyor

Gözlerimi yumuyorum

Seni bulmak istiyorum

Bulamıyorum

Uyumak istiyorum

Düşlerimde sana kavuşmak

Sıcaklığını

Sesini

Bakışlarını

Düşlerde yaşamak

Yaşayamıyorum

Sen olmuşum diye

Aynaya bakıyorum

Seni göremiyorum

Bir gün nefesler tükenecek

Ömürler bitecek

Acılar dinecek

Özlem hiç bitmeyecek

Biliyorum

Seni hissetmek istiyorum

Dört bir yanımı acılar kuşatmış

Hislerim çıkmaz bir sokakta kalmış

Dokunmak, dokunmak istiyorum

Dokunamıyorum

Nefesini, kokunu

İçime çekmek 

Kendimde seni duymak istiyorum

Derin bir nefes alıyorum

Nefesin nefesime karışıyor

Kokun içime yayılıyor

Nefesine 

Kokuna 

Sinen acılar

Kanıma Karışıyor

Canıma can katan varlığın

İçimi acıtıyor

Duyamıyorum

Çıkmaz sokakta kayboluyorum

Görünmez oldun

Bilinmez oldun

Hüzün

Ayrılık 

Birbirine kavuştu

Bir ben sana kavuşamadım.

Bir ben sevdiğim', 'İçim yanıyor Sanki alevler saçıyor Ayrılıklar yüreğimi dağlıyor Gözlerimi yumuyorum Seni bulmak istiyorum Bulamıyorum Uyumak istiyorum Düşle...', ARRAY['Türk Edebiyatı','Şiir','Birsen İbrahimhakkıoğlu']::text[], 8.5, '{"poet":"Birsen İbrahimhakkıoğlu","poet_slug":"birsen-i-brahimhakkioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/cikmaz-sokak-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf ve Temiz', 'saf-ve-temiz-nihal-yasar-oiyl5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırakın kalsın mısralarım da,

süssüz ve gösterişsiz.

Bırakın sade olsun,

onun gibi

saf ve temiz.', 'Bırakın kalsın mısralarım da, süssüz ve gösterişsiz. Bırakın sade olsun, onun gibi saf ve temiz....', ARRAY['Türk Edebiyatı','Şiir','Nihal Yaşar']::text[], 8.5, '{"poet":"Nihal Yaşar","poet_slug":"nihal-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/saf-ve-temiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vestiyer', 'vestiyer-cigdem-bir-genc-94zo9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yıldızlar asılı duruyor vestiyerinde gecenin

unutulmuş süsü verilmiş bir aşktan kalma kelimeler etrafta

akıp giden bir kemanın sesine bırakıyorum kendimi

vakit kedere yatkın bir şiirin arefesi

maskeli balo kıvamında suretleriyle kalabalıklar

 gece kelebekleri gibi şehrin ışıklarında kayboluyor

esrik kanatlarında bir parça sen...

soyunup giriyorum kelimelerin koynuna

imge sel oluyor...', 'yıldızlar asılı duruyor vestiyerinde gecenin unutulmuş süsü verilmiş bir aşktan kalma kelimeler etrafta akıp giden bir kemanın sesine bırakı...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vestiyer-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-nihal-yasar-ajk55', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dayanmak çok zor inan özlemine.

Bir karabasan misali,

yokluğun çöreklendi üzerime.

Sensiz geçmek bilmeyen

o uzun günlere,

senin dinmeyen

büyük hasretine,

nasıl dayanacak benim

bu küçük kalbim söyle...', 'Dayanmak çok zor inan özlemine. Bir karabasan misali, yokluğun çöreklendi üzerime. Sensiz geçmek bilmeyen o uzun günlere, senin dinmeyen büy...', ARRAY['Türk Edebiyatı','Şiir','Nihal Yaşar']::text[], 8.5, '{"poet":"Nihal Yaşar","poet_slug":"nihal-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozlem-244-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-sahin-kars-wixtz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk bir muamma gibidir çözebilene aşk olsun

Aşk bulutunun üstünde gezebilene aşk olsun

Aşk gönülün hitabıdır divanenin hesabıdır

Aşk şiirin kitabıdır yazabilene aşk olsun

Aşk incelik aşk azamet aşk özveri aşk nezaket

Aşk imandır aşk ibadet hazzı bilene aşk olsun

Aşk ilahların sathıdır aşk benliğin ruhsatıdır

Aşk kayalardan katıdır ezebilene aşk olsun

Aşk Ali''ye Kamber gibi aşk mis gibi amber gibi

Aşk sihirli çember gibi bozabilene aşk olsun

Aşk deli aşk akil eder aşk uzağı yakın eder

Aşk ateştir aşk kül eder tozabilene aşk olsun

Aşk irfan alimin huyu aşk Kevser Zemzemin suyu  

Aşk bir sonsuz derin kuyu kazabilene aşk olsun 

Aşk  özgürlük  aşk  hürriyet  aşk  özgüven  aşk  emniyet

Aşk  tarihsel  medeniyyet    baz ı  alana  aşk  olsun.

Aşk ilimdir aşk keramet aşk asalet aşk nedamet

Aşk güvendir aşk saadet erebilene aşk olsun 

Aşk mekanı arı yerdir ziyareti gönüllerdir

Aşk benlikten ileridir özge bilene aşk olsun 

Aşk uğraştır aşk emektir aşk sevmektir sevilmektir

Aşk Şahin''e  can  demektir sezebilene aşk olsun', 'Aşk bir muamma gibidir çözebilene aşk olsun Aşk bulutunun üstünde gezebilene aşk olsun Aşk gönülün hitabıdır divanenin hesabıdır Aşk şiirin ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aska-dair-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-aysel-cakar-0avj8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle özlüyorum ki Canım Seni,

Kızgın çöllerde bir damla yağmur tanesi gibi,

Hasretin öyle yakıyor ki,içimi,

Sanki çöllerde  kavrulmuş gibi.

Bekliyorum.yolunu,

Belki bugün gelirsin diye,

Yollarına yaşlı gözlerle bakarken,

Ümit ediyorum belki ararsın diye.

Bak! yine Güneş, batıyor.

Karanlıklar çöküyor üzerime.

Ve ben yine başladım ağlamaya,

Tutamadım gözyaşlarımı,

Çünkü Bak! yine sensiz bir gün daha bitiyor diye…

Ne kadar zormuş ayrılık.

Tarif edilmez bir dertmiş,

İnsanı hayata küstüren,

Yaşamı zehir edenmiş.

                                 23.08.2005', 'Öyle özlüyorum ki Canım Seni, Kızgın çöllerde bir damla yağmur tanesi gibi, Hasretin öyle yakıyor ki,içimi, Sanki çöllerde  kavrulmuş gibi. ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çakar']::text[], 8.5, '{"poet":"Aysel Çakar","poet_slug":"aysel-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozluyorum-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Çizgi', 'i-nce-cizgi-sait-muharrem-say-mr3hr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O kadar kötü ki dünya

o kadar kirlendi ki

İncecik bir çizgi var 

kendi mutluluğumuza ulaşmak 

ya da 

kalabalıklar içerisinde 

hoşnutsuz kalmak ve

 gün gün erimek arasında

(Ocak 2005)', 'O kadar kötü ki dünya o kadar kirlendi ki İncecik bir çizgi var  kendi mutluluğumuza ulaşmak  ya da  kalabalıklar içerisinde  hoşnutsuz kalm...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ince-cizgi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşasın Sonbahar-İlkbahar yalan', 'yasasin-sonbahar-i-lkbahar-yalan-sait-muharrem-say-hj1ds', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılık mevsimi

kimliksiz dramların üşüştüğü

yeşerdiği

yüzsüzce sarıp sarmaladığı doğayı

kırgınlıklar savruluyor heryerde

ve birikmiş limanlarda 

aşklardan geriye kalan

tortular

kıyıya vurmuş

bir çocuk elindeki sopayla karıştırdığında

ağlamaklı bir yüz beliriyor

yosunların arasında

kirli yanlızlıklar akla gelen

derin yanlızlıklar zamanı şimdi

umut yok

güçlendirir mi seni

ne dersin? 

neden var sanıyorsun

sonbahar...

aslında yalan İlkbahar 

o kadar kolay değil herşey

her şey yeşil her şey pembe

inanmam sahtekar ilkbahara

bir şeye inanırım

birden fazla aşık olduysam bunu

ona borçluyum...

Beni güçlendiren

acıtırken öğreten

Sonbahara....', 'Ayrılık mevsimi kimliksiz dramların üşüştüğü yeşerdiği yüzsüzce sarıp sarmaladığı doğayı kırgınlıklar savruluyor heryerde ve birikmiş limanl...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yasasin-sonbahar-ilkbahar-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günler,Hiç Kolay Geçmiyor.', 'gunler-hic-kolay-gecmiyor-ali-osman-yilmaz-p95rf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cananım,

Günler hiç kolay geçmiyor,

Gecelerimse,karabasan,

Bir türlü,

Bitmek bilmiyor,

Üzerime,

Akşamın karası değil,

Sensizliğin ağırlığı çöküyor.

Cam kenarından,

Soğuk karanlığa bakarken,

Titrememek için,

Sensizliği çekiyorum üstüme,

Biraz olsun,

Belki ısınırım diye,

Ama nafile,

Daha da donuyorum,

Sensizliği düşünmeyince,

Odam,daha bir sıcak oluyor,

O kadar üşümüyorum,

Zaman da geçiveriyor,

Usul,usul da olsa,

Ama sen,

Düşlerime girdiğinde,

Beynim çıldırıyor,

Yüreğimdeki yangın,

Daha bir yanıyor,

Buz gibi denize girsem,

Yüreğimdeki yangının,

Söner mi bilmem? 

Sen olmasan da yanımda,

Buz gibi donmaktansa,

Varsın yüreğimdeki ateş,

Daha gür yansın,

Senin ateşin yüreğimde yoksa,

Yaşamak neye yarar.', 'Cananım, Günler hiç kolay geçmiyor, Gecelerimse,karabasan, Bir türlü, Bitmek bilmiyor, Üzerime, Akşamın karası değil, Sensizliğin ağırlığı ç...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gunler-hic-kolay-gecmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökler,Çıldırmasın Artık.', 'gokler-cildirmasin-artik-ali-osman-yilmaz-55p48', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani,

Gökler çıldırınca,

Şimşekler çakar,

Yıldırımlar düşerdi? 

Sen o zaman,

Koşardın koynuma,

Ta içime kadar girip,

Korktuğunu söylerdin,

Sarılırdım sıkıca sana,

Korkma sevdiğim,

Saklan bana derdim,

Öyle güzel an’lardı ki,

Şimdi gökler,

Her çıldırdığında,

Şimşekler çakıp,

Gök gürlediğinde,

Senin içimde saklandığın,

O günler gelir aklıma,

O yüzden,

Göklerin çıldırmasını,

Çok severim,

Seni hatırlattığı için,

Hemde nefret ederim,

İçimde sensizliğin ateşini,

Yeniden yaktığı için.', 'Hani, Gökler çıldırınca, Şimşekler çakar, Yıldırımlar düşerdi?  Sen o zaman, Koşardın koynuma, Ta içime kadar girip, Korktuğunu söylerdin, S...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gokler-cildirmasin-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalansı Gerçeklerin.', 'yalansi-gerceklerin-ali-osman-yilmaz-hjv2e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gerçekmiş gibi,

Anlattığın yalanların,

Yalansı ama,

Gerçek gibi söylediklerin,

Seviyor gibi görünüp,

Ardımdan vurman,

Tatlı sözler söylerken,

Yılan gibi sokan dilin,

Nasıl bir kısır döngü bu? 

Gerçek mi? Yalan mı? 

Geçek gibi yalanın ne? 

Yalansı gerçeğin nedir? 

Gülerken neşeyle yüzüme,

Gizlice zehirleyen,

Yılansı kıskançlığın,

Hani sevdan nerde? 

Hep ihanetine mi? uğrayacak,

Seni adam gibi seven,

Gönlüm?', 'Gerçekmiş gibi, Anlattığın yalanların, Yalansı ama, Gerçek gibi söylediklerin, Seviyor gibi görünüp, Ardımdan vurman, Tatlı sözler söylerken...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yalansi-gerceklerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yığın', 'yigin-berrak-su-751r7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Milyonlarca el, ayak,

Telaşlı rapsodilerde.

Algılamamaların anlık uzanışlarında,

Akıyorlar ve kısalıyorlar.

Yanmanın ölümcül sızısı,

Ve bir bereket ki,

Leylimler, zeytindalları,

Çoğalıp azalırken tüm kısırlıklarda,

Bin gürültü, milyon suskun.

Herdemden, ne varsa dökülmüş,

Saçılmış,

Anlatılmamış,

Anlaşılmamış..

Berrak Su', 'Milyonlarca el, ayak, Telaşlı rapsodilerde. Algılamamaların anlık uzanışlarında, Akıyorlar ve kısalıyorlar. Yanmanın ölümcül sızısı, Ve bir ...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeti', 'yeti-berrak-su-ee4fd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yetisi eksik,

Tamamlanmamış buğday tanesi,

Büyür baharın erken sirenlerinde.

Bilmezden gelişi,

Gözlerin bağlı oluşundan.

Yaratısı,

Varlığın bataklığı.

Korkusu,

Boşça,

Leşçe, uçuşan sinekler..

Berrak Su', 'Yetisi eksik, Tamamlanmamış buğday tanesi, Büyür baharın erken sirenlerinde. Bilmezden gelişi, Gözlerin bağlı oluşundan. Yaratısı, Varlığın ...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yeti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda...', 'veda-neslihan-i-sler-9q0g1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aslında tamda vazgeçişlerin ortasındaydım 

Cama vuran aksimi seyrediyordum gecenin karanlığında,,,

Ah  şu duvarların dili olsada konuşsa paylaşsa yanlızlığımı...

Gece gibi siyah bir  ağırlık çökmüştü yüreğime,,,

Tek avuntum sigaram ve geceye ses veren ağustos böceklerinde...

Bende oturdum köşedeki kanepeye karşımada kendimi aldım 

Başladım sorguladım,yargıladım, kızdım aşağıladım....

Kimi neyi suçluyordum böyle, hata kimde veya nerde

Aslında ne kaderimde ne de başka birinde

Biliyorum sadece yüreğimde....

Hep yanlış yerde yanlış düşüncelerde,,,

Oturdum kaldım bir süre öylece....

Ve yüreğime veda ettim düngece....', 'Aslında tamda vazgeçişlerin ortasındaydım  Cama vuran aksimi seyrediyordum gecenin karanlığında,,, Ah  şu duvarların dili olsada konuşsa pay...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/veda-166-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-serkan-sekban-7zxcw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk,cevabını bulamadığım bir soru

Yaşamadan anlatılmayan bir duygu

Bazen hayattır bazen sonu

Bazende minik bir bebek gibidir

Aşk,koparmaya kıyamadığım bir çiçek

Kimine yalan kimine gerçek

Bazen şeytan bazen melek

Bazende yanan bir volkan gibidir

14 / 04 / 2004', 'Aşk,cevabını bulamadığım bir soru Yaşamadan anlatılmayan bir duygu Bazen hayattır bazen sonu Bazende minik bir bebek gibidir Aşk,koparmaya k...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-418-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanoğlu İnsan', 'i-nsanoglu-i-nsan-mehmet-dag-j5mlu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ha kar eriyor doğadan,

Ha insan.

Biri cansız,

Biri can.

Karın eridiğini 

Herkes fark ediyor da,

İnsanı fark etmiyor hiç kimse neden? 

Bu kadar mı kör, sağır, dilsiz

Bu kadar mı işit siz ve işlevsiz oldu

İnsanoğlu insan

2005', 'Ha kar eriyor doğadan, Ha insan. Biri cansız, Biri can. Karın eridiğini  Herkes fark ediyor da, İnsanı fark etmiyor hiç kimse neden?  Bu kad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/insanoglu-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağırma Beni', 'cagirma-beni-omer-arslan-5yb1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessizce de  olsa  çağırma beni

                 Kulağım keskindir duyabilirim

                 Şakadan da olsa gel deme emi

	 Deliyim, şeytana uyabilirim

 	Benim gönlümü hapsetme kafese

 	Kulak kabarttım en küçük bir sese

                Yaralı bir  kuşum dinlemem ökse

                Elimle, canıma kıyabilirim

                Selam olsun dağda gezen efeye

                Hastayım Şiire şarkıya neye

                Mecnunla kendimi aynı kefeye

                Koymadım amma koyabilirim', 'Sessizce de  olsa  çağırma beni                  Kulağım keskindir duyabilirim                  Şakadan da olsa gel deme emi 	 Deliyim, şeyt...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cagirma-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı tokalı kız', 'kirmizi-tokali-kiz-ahmet-kesici-bho6n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ufak bir çocukken ne kadar rahattım.

Hiç bir sıkıntım yoktu.

Arkadaşlarla bilye oynardık.

Gazozuna iddalaşıp maç yapardık.

Devre aralarında,

evimizin karşısındaki duvarın üstünde oturup soluklanırdık.

İp atlayan kızları izlerdik.

Ne kadar hoşuma gitse de

o kırmızı tokalı sarı saçlı güzel kız,hiç belli etmezdim.

Onun için hiç üzülmezdim.

Ne vardı yine çocuk olsaydım.

O zaman senin için yanmazdım.

Belki ne tatlı çocuk diye,eğilip yanağımdan öpmek isterdin.

Ama aşkı sevmezdim, sana boyun eğmezdim.

Oysa şimdi, askere gidecek yaşa erdim.

Ali askerden geldi.

Gözde ile evlendiler.

Hani biz tanıştırmıştık.

Bi ara ayrılmışlardı, hatırlıyormusun? biz barıştırmıştık

Ali’nin her şeyi tamamdı. 

Bir de kızları oldu, görsen dünya tatlısı.

Benimde her şeyim tamam.

Bir sen eksiksin.

Birazdan arayacaksın biliyorum.

Yine telefonda ''''biraz daha sabret döneceğim, seni seviyorum''''diyeceksin

Ama artık sesini duymak hasretimi gidermiyor.

Seni görmek istiyorum.

Sarılıp koklamak istiyorum.

Kırmızı tokalı, sarı saçlı güzel kız, seni seviyorum.

Yokluğunda nefes yerine çektim dumanı.

Su yerine içtim Şarabı.

Hasret yerine çektim kafayı.

Sarhoşum.

Boşum.

Başımda zonklayıp duran bir ağrı.

Elimde sigara,

bekliyorum döneceğin anı.

Dönmüyorsun dindirmiyorsun acımı.

Yoksa sende mi saymaz oldun güzel geçen yılların hatırını.? 

Yoksa unuttun mu,giderken o bitmeyen vedamızı.

''''seni seviyorum unutma beni''''değip gitmiştin.

Unutmadım.

Her yaşanan güzel günümüzün

her saatinden,her dakikasına kadar,aklımdadır her anı.

Ve de,unutmadım asla seni.

Bir papatya belki teselli olur diye yoldum yapraklarını.

Seni seviyor deyince sevindim.

Bir anlık olsa da gamlı yüzümün hüzün perdesini indirdim.

Artık dönmen gerek.

Dönmezsen ölmem gerek.

Şu bitip Küle dönen sigara halime en basit örnek.

Bana bir tanem bana,her halin İle sen gerek.

Bana bir tanem bana,her halin İle

Kırmızı tokalı,

.............sarı saçlı,

.........................güzel kız,

.....................................sen gerek...', 'Ufak bir çocukken ne kadar rahattım. Hiç bir sıkıntım yoktu. Arkadaşlarla bilye oynardık. Gazozuna iddalaşıp maç yapardık. Devre aralarında,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kirmizi-tokali-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytana Uymak', 'seytana-uymak-mustafa-topcu-f7yek', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adem''den beridir

Şeytana uymak

Bir elma uğruna

Cennet''ten olmak', 'Adem''den beridir Şeytana uymak Bir elma uğruna Cennet''ten olmak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Topçu']::text[], 8.5, '{"poet":"Mustafa Topçu","poet_slug":"mustafa-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seytana-uymak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fani Dünya', 'fani-dunya-funda-sengul-hggq3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya kimsin nesin parçamısın hayattan

Belkide sen yaşandıkça anlaşılansın

Kimi barınır kimi konar göçer üstünden

Dünya sen gerçekte sahte olansın

Dünya senmisin mezar olan sevaplara

Nesin ki sen bir toprak parçasından başka

Sana yüz çevirende var ilah diye tapanda

Adın gibi yalansın sen yalan dünya

Dünya kendine oyuncak edinmişsin ben piyon olmam

Bir avuç toprağın için umutlarımı sana bağlamam

Seni vareden ve beni YARADAN''ı asla unutmam

Sen üç günlük dünya sen mi beni yıldırıcan', 'Dünya kimsin nesin parçamısın hayattan Belkide sen yaşandıkça anlaşılansın Kimi barınır kimi konar göçer üstünden Dünya sen gerçekte sahte o...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fani-dunya-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yaşlanmış Olamam', 'ben-yaslanmis-olamam-funda-sengul-tgj75', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aynalara dargınım artık gençliğimi göstermiyor

Silik silik anılar çoğu artık hatırlanmıyor

Yaşlandığını nefs bir türlü kabullenmiyor

Sanki hayat beni yavaş yavaş unutuyor

Asla unutmamları unuttum bitmezler bitti

Keşkelerle ne yaptımlarla bir ömür tükendi

Niye nerede nasılda harcamışım kendimi

Merhaba derken elvedamı olucaktı bu son gösteri', 'Aynalara dargınım artık gençliğimi göstermiyor Silik silik anılar çoğu artık hatırlanmıyor Yaşlandığını nefs bir türlü kabullenmiyor Sanki h...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-yaslanmis-olamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvallah', 'eyvallah-kadir-kaya-40fj9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgiye, özleme umut besleyen,

Sıralı derdime çare sesleyen,

Duygumu coşturup aşkı süsleyen,

Özdeki ateşe, köze eyvallah.

Sabırla, hoşgörü yanlışı  eler,

Mutluluk kederi,tasayı siler,

Bizlere sağlıklı gelecek diler,

Tebessümde saklı haza eyvallah.

Gönüllere şifa bakışın olsun,

Düşlerin sevgide sevdayı bulsun,

Hasretin, vuslatla sefaya dalsın,

Kadirim , tadında naza eyvallah.', 'Sevgiye, özleme umut besleyen, Sıralı derdime çare sesleyen, Duygumu coşturup aşkı süsleyen, Özdeki ateşe, köze eyvallah. Sabırla, hoşgörü y...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eyvallah-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kainat', 'kainat-sinan-karakas-t6k38', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yok iken hiç bir zerre,ancak var idi Allah

O zamanda yok idi ne akşam nede sabah

Ne zaman vardı anda nede mevcut bir mekan

Ol demeden olmazdı dünya dediğimiz han

Yarattı melekleri görünmez bir nur ile

Dolaştı kainatı melekler onur ile

Bir duman yarattı ki buluta benziyordu

O duman da durmadan hareket ediyordu

Döne döne o duman parçalandı ikiye

Biri arz biri sema diyerek bölünmeye

Yaratıldı beraber altı günde arz sema

Arz bile parçalandı dağıldı her bir yana.', 'Yok iken hiç bir zerre,ancak var idi Allah O zamanda yok idi ne akşam nede sabah Ne zaman vardı anda nede mevcut bir mekan Ol demeden olmazd...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kainat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilımlı İslam', 'ilimli-i-slam-funda-sengul-5miqf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dinin islamın cenazesini çoktan kaldırdılar

ILIMLI İSLAMİYET diye yeni bir isim buldular

Bilmem hangi dille duada bulunurlar

Ne verdik ki ne istiyoruz diye hiç sormazlar', 'Dinin islamın cenazesini çoktan kaldırdılar ILIMLI İSLAMİYET diye yeni bir isim buldular Bilmem hangi dille duada bulunurlar Ne verdik ki ne...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilimli-islam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nisan Yağmuruydu Aşk', 'bir-nisan-yagmuruydu-ask-i-lknur-cekici-cvee4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir nisan yağmuruydu aşk 

Kıştan kalan ama sıcak 

Yeni hayallerle kucak kucak 

Yüreğimi yaşatacak 

Bir nisan yağmuruydu aşk 

Umut filizleri yeşertti köşe bucak 

Yağdı ürpertti bedenimi 

Düştü,yüreğimde hala nemi 

Bir nisan yağmuruydu aşk 

Yağdı yıllarca yaşatarak 

Geçmedi baharları, çoğalarak 

Derinlere aktı iz bırakarak', 'Bir nisan yağmuruydu aşk  Kıştan kalan ama sıcak  Yeni hayallerle kucak kucak  Yüreğimi yaşatacak  Bir nisan yağmuruydu aşk  Umut filizleri ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-nisan-yagmuruydu-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kadar Şeytana Kaç Cehennem Var', 'bu-kadar-seytana-kac-cehennem-var-funda-sengul-0mxom', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Para diye takmışlar boynumuza bir yular

Sen kurtulayım derken firar ediyor yıllar

Tövbe etmeyi hep bitmez yarınlara bırakırlar

Sen uyurken yastığının altında nefesini sayan ölüm var

Bananelerle neme gereklerle yaşanır mı

İbadetsiz taatsız dualar ulaşır mı

Yaradanın istediği sadece kulluk anlamazlar mı

Fitneyi duyanlar birgün ezanları duymicaklar mı

Ne sana ne bana olucak bu dünya yar

Günahların ve nefsinden başka neyin var

Allah''a kulluk bu kadar ağarmı ki hep sızlanırlar

Soruyorum acaba bu kadar şeytana kaç cehennem var', 'Para diye takmışlar boynumuza bir yular Sen kurtulayım derken firar ediyor yıllar Tövbe etmeyi hep bitmez yarınlara bırakırlar Sen uyurken y...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-kadar-seytana-kac-cehennem-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nurlu konuk', 'nurlu-konuk-selim-basar-sadlp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Abad olduk konukluğunla muhsin (sav) .

Hane-i sinemizi ihya eyledi cismin.

Ala dır şüphesiz cemalin gibi ismin 

Ne geldi nede gelir,asla aleme mislin.', 'Abad olduk konukluğunla muhsin (sav) . Hane-i sinemizi ihya eyledi cismin. Ala dır şüphesiz cemalin gibi ismin  Ne geldi nede gelir,asla ale...', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nurlu-konuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-selim-basar-98vpo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulut gibi doluyum,''yağ'' emr''i bekliyorum.

Sağnak sağnak aşk''ımı Allaha saklıyorum', 'Bulut gibi doluyum,''yağ'' emr''i bekliyorum. Sağnak sağnak aşk''ımı Allaha saklıyorum...', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/emanet-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat Ecele Kaç Var', 'saat-ecele-kac-var-funda-sengul-agirx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saat ecele kaldı biliyormusun

Ölümün soğuk yüzünü duymuyormusun

Gelecekte birgün gelecek anlamıyormusun

Kıyamet denilen o saati düşünmüyormusun

Dünya dümdüz olduğunda mahşer yerinde

Unutma kimse olmicak o an seninle

Bir ömür dediğin bitmiş olucak o saatlerde

Kendini bulucaksın o yüce mahkemede

Sorucak ALLAH kulum ne yaptın benim için

Namaz kıldım oruç tuttum ALLAH''ım diyeceksin

Onlar senin kulluk borcundu benim için ne yaptın

İşte o an başlar öne eğilecek ''''eyvah ben ne yaptım''''', 'Saat ecele kaldı biliyormusun Ölümün soğuk yüzünü duymuyormusun Gelecekte birgün gelecek anlamıyormusun Kıyamet denilen o saati düşünmüyormu...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saat-ecele-kac-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak..Şu Bebelerin Güzelliğine', 'bak-su-bebelerin-guzelligine-guzin-eye-dundar-omlv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bak..şu bebelerin 

güzelliğine

biririn elleri kan içinde

biri elbebe gül bebe

birinin içinde bir orman

diğeri ormanda bir tane 

biri sıcak göğüslerde mutlu

diğeri cami bahçesinde üryan

geçmemiş günlerin gölgesinde

bir ermiş bir bilge gibi 

tutmuş nefesini

kaderi beklemekte

biri çıkmadığı tepelerin eteğinde

diğeri zirvede....', 'Bak..şu bebelerin  güzelliğine biririn elleri kan içinde biri elbebe gül bebe birinin içinde bir orman diğeri ormanda bir tane  biri sıcak g...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bak-su-bebelerin-guzelligine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis Çanları', 'sis-canlari-mucahit-gulbas-bz0dv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün çanlar çaldı

eyy serseri kız, küçük kız

bütün çanları çaldım

küçük serseri kız

bütün yolları denedim

yine de yoksun

sis çanları da başladı vurmaya

anlayamadığım

ve anlatamadıklarıma vuruyor demir topuz

öyle vuruyor ki zangoç

cehennemii

ve ben öyle bekliyorum ki

 gelmenii

göz gözü görmez oldu ortalık

tozdan dumandan

son bir şiir daha yazıyorum sana

acılardan,acılardan,acılardan.......

19.01.95 İzmir', 'Bütün çanlar çaldı eyy serseri kız, küçük kız bütün çanları çaldım küçük serseri kız bütün yolları denedim yine de yoksun sis çanları da baş...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Gülbaş']::text[], 8.5, '{"poet":"Mücahit Gülbaş","poet_slug":"mucahit-gulbas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sis-canlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiy Düşer', 'ciy-duser-sezai-sengonul-9qg2l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çiy gece düşer

Düşerken geceyi öper

Gece çiyi içine çeker

Gündüz içini çeker

Pusudadır

Şafağı bekler

Atarken şafak

Boğar geceyi gündüz

Uyur çiy biraz

Çimenlerin üstünde

Üstü açık

Dökülür gündüz

Tül gibi aşağılara

Dağlardan tepelerden

İner ovaya

Çiyi görür

Üstünde topragın

Gögsünde çimenin

Sarılmak ister

Dikilir güneş karşısına

Bakar gündüze

Kızgın kızgın

Yanar içi uyanmıştır

Dayanamaz kızgınlığa

Erir gider çiy arada.', 'Çiy gece düşer Düşerken geceyi öper Gece çiyi içine çeker Gündüz içini çeker Pusudadır Şafağı bekler Atarken şafak Boğar geceyi gündüz Uyur ...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ciy-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koltuk değneğim', 'koltuk-degnegim-yunus-isikoglu-ebcq7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir koltukdeğneğim vardı

Hep ona sarılır.hep ona dayanır,

Öyle yürürdüm.

Hep onunla gezerdim.

Benim bir parçamdı

Koltukdeğneğim 

Benim kaderimdi.

Benim sevincim,

Neşem,

Mutluluğumdu,

Yaşama umudumdu.

Çaldılar...

Yokartık koltuk değneğim.

Yokartık benim parçam.

Ne istediniz? 

Neden çaldınız yaşambağımı? 

Sevincimi,mutluluğumu

Ben koltukdeğneğimi istiyorum

Verin benim parçamı

Ben onsuz yaşayamam.', 'Bir koltukdeğneğim vardı Hep ona sarılır.hep ona dayanır, Öyle yürürdüm. Hep onunla gezerdim. Benim bir parçamdı Koltukdeğneğim  Benim kader...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/koltuk-degnegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancılar', 'yabancilar-mehmet-dag-5bmp4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilim değil,

Film satıyor ABD şirketleri.

Süslü yuvarlak sözcüklerle

Renkli fırçalı desenler çiziyorlar

Görselimize 

Kıl, kalemli yazarlar.

Yıllarca kanla ve rantla beslendiler.

Sınıfların çelişkilerini görmezden gelip,

Emeğe düşman oldular.

‘’Önce insan’’ diye yola çıkanlar,

İnsanı insan eden değeri unuttular.

Ağızlarına bir parmak bal çalanın,

Ardına düşüp gittiler karanlıklara…

DAĞ', 'Bilim değil, Film satıyor ABD şirketleri. Süslü yuvarlak sözcüklerle Renkli fırçalı desenler çiziyorlar Görselimize  Kıl, kalemli yazarlar. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yabancilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarık', 'carik-yunus-isikoglu-lfokk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gene yandan yandan 

Açtın ağzını çarık

Gene başladın sırıtmağa

Gel be çarık kapat ağzını

Bak biz yoldaşız

Ben sana muhtacım

Sırıtma bu kar da boran da

Koma beni kış ortasında Yarı yolda                                                      

Bak bir kış çıksın

Hele bir yaz gelsin

Seni dinlendireceğim

Giymeyeceğim yaz boyunca

Tüm bir yaz rahat edeceksin

Yalvarıyorum sana

Koma beni yarı yolda şu kış ortasında

Sırıtma

Kapa biraz ağzını

İdare et beni

Bari şu kış geçene kadar.', 'Gene yandan yandan  Açtın ağzını çarık Gene başladın sırıtmağa Gel be çarık kapat ağzını Bak biz yoldaşız Ben sana muhtacım Sırıtma bu kar d...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/carik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Gemisi', 'hayal-gemisi-mehmet-aslan-96ofk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En sıkıntılı zamanımda,

bir gülüşünle yetiyordun bana.

Her başım ağırdığında,

koşup yetişiyordun bana.

Seninde başın sıkıştığında,

bir çağrı yapıyordun bana.

Şimdi sen sıkıntıdasın,

Dert deryasının en derin yerinde.

Üzüntülerinin yasındasın,

Çaresizsin bir şey yok elinde.

Anlat ki derdini bilelim,

Belki merhem oluruz,

Bilelim ki gözyaşını silelim

O zaman rahat bir nefes soluruz.

Bilirsin benim huyumu,

Yapıştım mı bırakmam.

Kessen bile hayat suyumu,

Korkma gülüm

seni dalından kopartmam.

Dostunum senin,

Ortağı olurum dertlerinin.

Her şeyinim senin,

Dermanı olurum dertlerinin.

Arkadaşınım senin,

Terkedilmişken yalnızlığında.

Işığınım senin,

Yalnız gecelerinin karanlığında.

Boşalt, dök içinde ne varsa,

Yaslanıp ta omzuma ağlayarak

Bırakma hiçbir şeyi şansa,

Boş pembe hayaller kurarak.

İn artık o hayal gemisinden,

Yaklaştığında ilk limana,

Kurtul artık sahte aşkın pençesinden,

Üzülme ben yetişirim imdadına.', 'En sıkıntılı zamanımda, bir gülüşünle yetiyordun bana. Her başım ağırdığında, koşup yetişiyordun bana. Seninde başın sıkıştığında, bir çağrı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hayal-gemisi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Kaydı', 'yildiz-kaydi-sezai-sengonul-0x4i7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazdı

Ruhumu toprak çimen

Kokusu sardı

Asumanda

Yıldızlar birde ay vardı

Gam keder

Boşa çıkan hamleler

Düşünürken

O da ne! 

Bir yıldız kaydı

O yıldızın hayatı kaydı

Attım gamı kederi

Gülümsedim ince ince

Kaymayan daha

Ne çok yıldız vardı

Tomurcuklandı tekrar

Ümitlerim o an

Ne hoş hazdı.', 'Yazdı Ruhumu toprak çimen Kokusu sardı Asumanda Yıldızlar birde ay vardı Gam keder Boşa çıkan hamleler Düşünürken O da ne!  Bir yıldız kaydı...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yildiz-kaydi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibritçöpü', 'kibritcopu-yunus-isikoglu-4x36c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak kibritçöpü

Sana

Şu an oyle ihtiyacım var ki

Sen olmazsan

Sigaram yanmıyor

Sigaram yanmazsa 

Efkarım dağılmıyor

Bir kibritçöpü

Bir kibritçöpü...', 'Bak kibritçöpü Sana Şu an oyle ihtiyacım var ki Sen olmazsan Sigaram yanmıyor Sigaram yanmazsa  Efkarım dağılmıyor Bir kibritçöpü Bir kibrit...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kibritcopu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Güzeli', 'gul-guzeli-mehmet-aslan-jomtd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kopartmam seni dalından

Belki solarsın diye

Öpmem seni dudağından 

Belki kanarsın diye

En güzelisin güllerin

Koklamaya doyamam

Aşkısın bütün bülbüllerin

Ben o kadar şakıyamam

Kopartmasam da soluyorsun

Haberin olsun gül güzelim

Çatlayacaksın içine kapanıyorsun

Açıl ki sıkıntını çözelim.

Sır küpüyümdür dostlarımın

Sana da boş yerim var

Değişti rengi saçlarımın

Anlat sana da yağmadan kar.

Kalmadı ne menekşelerim nede sümbülüm

Gitmek üzereydim bu ülkeden

Bir tek sen kaldın dertli gülüm

Gitmeyeceğim senide gülerken görmeden.', 'Kopartmam seni dalından Belki solarsın diye Öpmem seni dudağından  Belki kanarsın diye En güzelisin güllerin Koklamaya doyamam Aşkısın bütün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gul-guzeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana ne', 'bana-ne-yunus-isikoglu-ikmzs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökte güneş varmış

Dünya yı aydınlatırmış

Alemi ısıtırmış

Bana ne

Gece semada

Yıldızlar kıpırdar gözkırparmış

Bazen de şans dağıtırmış fallarda

Bana ne

Ay mehtap olurmuş

Güneşin doğusunu beklermiş

uykuya yatmak için

Bunlar benim için birbilinmeyenli denklem

eş değeri de sensin

Sonuçta sen çıkmazsan

O denklemden

Bana ne', 'Gökte güneş varmış Dünya yı aydınlatırmış Alemi ısıtırmış Bana ne Gece semada Yıldızlar kıpırdar gözkırparmış Bazen de şans dağıtırmış falla...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-ne-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirdir Bu Sağı Solu Belli Olmaz', 'siirdir-bu-sagi-solu-belli-olmaz-veli-dalbudak-9lnri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönul emeğidir, yazılır okunsun diye,

Bazan düşmanı bırakır, catar sevgiliye,

Karıştırır sevgiyi hüzüne, hüzünü sevgiye,

Şiirdir bu, sağı solu belli olmaz.

Bazan çölde su olur, ferahlatır serinletir,

Bazan üzer,bazan neşelendirir sevindirir,

Bazanda anlaşılmaz, okuyanı delirtir,

Şiirdir bu, sağı solu belli olmaz.

Bakarsın kara-kışda bahar olur, ateş olur,

Bakarsın, zifiri karanlıkta sonsuz guneş olur,

Kimi zaman, yalnızlara bulunmaz bir eş olur,

Şiirdir bu, sağı solu belli olmaz.

Ne olursa olsun, öğüt verir, yol gösterir,

Vurdum duymazlara karşı  ses verir,

Kaktüsede yazılsa, çiçek olur, gül verir,

Şiirdir bu, sağı solu belli olmaz.

...............yazan yazmaya,

...............okuyan okumaya doyamaz.

...............şiirdir bu, sağı solu....

....................belli olmaz........

(Stockholm 2005)', 'Gönul emeğidir, yazılır okunsun diye, Bazan düşmanı bırakır, catar sevgiliye, Karıştırır sevgiyi hüzüne, hüzünü sevgiye, Şiirdir bu, sağı so...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siirdir-bu-sagi-solu-belli-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Yarın Temizdir', 'belki-yarin-temizdir-i-smail-haki-simsek-0az2z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalabalıklar,şehir ve zaman kuleleri

Eyvah! Yine unutmuşum kendimi...

Alemi küstürmeden,

Dünyaya yeniden gelmeyi...

Unutmuşum lakin; 

İhtiyar da değilim.

Çerçevelere sığdıramadığım çocuklukları,

Bıraktım bu sabah kimsesiz bebelere.

Başımın dönmesine aldırış etmeden.

Çıkardım onları gökyüzüne...

Çıkardım lakin; 

Yetim de değilim.

Çiçekler kopardım rengarenk bir kuşaktan,

Rengarenk çiçekler...

Yağmur, kar,dolu...

Ne varsa bekledim beyaz topraktan.

Bekledim lakin; 

Aşık da değilim.

''Belki yarın temizdir''

Bu kadar gülümsüyorum sana miniğim.

Ama garanti edemem sana gülümsemeleri

Edemem lakin; 

Kirli de değilim.', 'Kalabalıklar,şehir ve zaman kuleleri Eyvah! Yine unutmuşum kendimi... Alemi küstürmeden, Dünyaya yeniden gelmeyi... Unutmuşum lakin;  İhtiya...', ARRAY['Türk Edebiyatı','Şiir','İsmail Haki Şimşek']::text[], 8.5, '{"poet":"İsmail Haki Şimşek","poet_slug":"i-smail-haki-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/belki-yarin-temizdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşananların Sadeliğinde', 'yasananlarin-sadeliginde-sule-giray-5zkxt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şey ilk günki kadar berrak

Gözümün önünde bir hayat

Gelecekten bir feryat

Kulak vermeli mi? 

Ey Hak...', 'Her şey ilk günki kadar berrak Gözümün önünde bir hayat Gelecekten bir feryat Kulak vermeli mi?  Ey Hak......', ARRAY['Türk Edebiyatı','Şiir','Şule Giray']::text[], 8.5, '{"poet":"Şule Giray","poet_slug":"sule-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yasananlarin-sadeliginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayan Anlar', 'anlayan-anlar-veli-dalbudak-9qt5o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç yaşında olursan ol,

..........anan için çocuksun,

Nerde olursan ol,

..........çocuğun için mutluluksun.

Sana düşen değerlerini bilmektir,

değerlerini bilmiyorsan,

zaten sen e.....

...neyse gerisini söylemeyim.

Elim öpülür sanma, el öpmez isen,

Yüzüm güler sanma, yüz güldürmez isen,

Mutluluğu tadamazsın, çocuk sevindirmez isen,

bunları bilmiyorsan.....

zaten sen e......

....neyse gerisini söylemeyim.

Anayı babayı takmaz isen,

Aman dileyene bakmaz isen,

İmdat elinden tutmaz isen,

ne deyim....

o zaman sen e......

....neyse gerisini söylemeyim,

......ANLAYAN  ANLAR.

(Stockholm 2005)', 'Kaç yaşında olursan ol, ..........anan için çocuksun, Nerde olursan ol, ..........çocuğun için mutluluksun. Sana düşen değerlerini bilmektir...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anlayan-anlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz İsyan', 'sessiz-i-syan-sule-giray-0a9hv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Kadınım''a ithaf olunur) 

Gözlerinden akan iki damla yaş

Derin izlerden yalnızca ona kalan

Nefes almak yavaşça bırakmak kadar kısa

Ardından dalınan uyku

Sanki uykusunda yeni bir umut varmış gibi

Aldığı soluk çok içten

Yeniye uyanış umuduyla alınmış gibi

Oysa gece; yine aynı sabahlardan birine gebe.

İsyan... Sessiz, derinden, çaresiz, yorgun,

Gözlerinden akanda gizli...

(Altınoluk, 17.08.2005)', '(Kadınım''a ithaf olunur)  Gözlerinden akan iki damla yaş Derin izlerden yalnızca ona kalan Nefes almak yavaşça bırakmak kadar kısa Ardından ...', ARRAY['Türk Edebiyatı','Şiir','Şule Giray']::text[], 8.5, '{"poet":"Şule Giray","poet_slug":"sule-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sessiz-isyan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anlık Aşk....', 'bir-anlik-ask-avni-aydin-fwb5s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk bir anda mı gelir? 

ya da bir anda gelen ilk duygu aşk mıdır? 

neden şu hayatta devamı gelmiyor bişeylerin? 

anlamı kalmadıysa bişeyler için çabalamanın...

sonu gelmiyorsa bu yalnızlığın...

gelecek diye beklenen mektuplardan mıdır aşk? 

son trenin de hüzünle gelmesini bekleyen ağlamaklı bir çift göz? 

yoksa bir kısa mesajla biten ilişkiler mi aşk? 

bilemedim ama mektupla veya bir çift kelimeyle biten aşklar gibi değil...

artık tanıyamaz oldum insanları...

ne kadar da basitleşmiş herşey

ne kadar da yozlaşmış...

ilişkiler bile artık hamburger tadındayken,

aşkı sormak hata belki de...

bu topraklarda bir daha aşk yaşanırmı bilmem...

ümidim de yok keza.

neye yanayım bilmiyorum...

ben buldum mu aşkı? 

ya da farketmeden yaşadım mı? 

yoksa ben de farketmeden mi yaşadım yıllarca? 

bu sorulardan nasıl kurtulurum bilinmez...

yeter diyeceğim

kelimeler boğazıma diziliyor...

konuşamıyorum.', 'aşk bir anda mı gelir?  ya da bir anda gelen ilk duygu aşk mıdır?  neden şu hayatta devamı gelmiyor bişeylerin?  anlamı kalmadıysa bişeyler ...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-anlik-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Atını', 'ask-atini-taner-nisanci-097vy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AŞK ATINI………..

Dertler insan için katlanmak gerek

Ah etmeden menzile yürümeli

Sabır; muştu olur canda diyerek

Aşk atını menzile sürümeli

Kar boran fırtına gelse üstüne

Yar dediğin etse canın kastına

Alca kanın dolsa gönül destine

Aşk atını menzile sürümeli

Paralansa adın dilde dolaşsa

Yolların kesilip itler dalaşsa

Mihnetin türlüsü tende buluşsa

Aşk atını menzile sürümeli

Mansur’leyin bende beni atarak

Boynun bükük göze yaşı katarak

Makam, mevki, malı, mülkü satarak 

Aşk atını menzile sürümeli

Mecnun’ca yanarak Leyla yolunda

Öl ve ol; taşınma mevta salında

Bir Garip benim de; işin aslında

Aşk atını menzile sürümeli

                       07/05/2005', 'AŞK ATINI……….. Dertler insan için katlanmak gerek Ah etmeden menzile yürümeli Sabır; muştu olur canda diyerek Aşk atını menzile sürümeli Kar...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-atini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm ve Ölüm', 'olum-ve-olum-mehmet-sakir-karatas-suzp9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalmadı tutunacak yanı hayatın

Paslandı bütün zincirler

Islat ve kurut beni

Ey yağmur ve rüzgar

Hep sen peşimdeydin

Şimdi ben kapındayım

Açıl ve unut beni

Ey bahçe ve duvar

                   2005', 'Kalmadı tutunacak yanı hayatın Paslandı bütün zincirler Islat ve kurut beni Ey yağmur ve rüzgar Hep sen peşimdeydin Şimdi ben kapındayım Açı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakir Karataş']::text[], 8.5, '{"poet":"Mehmet Şakir Karataş","poet_slug":"mehmet-sakir-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olum-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-halil-kesken-58wfi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimbilir arkadaş sen de yanmışsın

Tatlı söze, bir bakışa kanmışsın

Bu hayat oyununda belli ki aldanmışsın

Kadehleri bir bir deviriyorsun

Aşkını söyleyip açamadın mı? 

Bu acı kaderden kaçamadın mı? 

Sevgine karşılık bulamadın mı? 

Kadehleri bir bir deviriyorsun

Hayat olmadı mı senin gönlünce? 

Seven olmadı mı sen hep sevdikçe

Haline güldüler sen yar dedikçe

Kadehleri bir bir deviriyorsun

(bu arada ben içmem :))', 'Kimbilir arkadaş sen de yanmışsın Tatlı söze, bir bakışa kanmışsın Bu hayat oyununda belli ki aldanmışsın Kadehleri bir bir deviriyorsun Aşk...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sarhos-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-halil-colak-xwjlq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gülsün çevren diken olsa da

Hepsini birden avuçlarım inan sevdiğim

Ellerim senin için kanlar içinde kalsa da

Yine seni özlemle kucaklarım  sevdiğim

Geceler senin hasretliğinle  dolsa da

Rüyalarım seninle süsleniyor sevdiğim

Özlemin kor olup içimi için için yaksa da

Bir ömür boyu seni seveceğim sevdiğim

Halil Çolak  23.8.2005 Ankara', 'Sen gülsün çevren diken olsa da Hepsini birden avuçlarım inan sevdiğim Ellerim senin için kanlar içinde kalsa da Yine seni özlemle kucakları...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdigim-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstadlar 2', 'ustadlar-2-selim-basar-9bobs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mana vardır üstadların sözünde.

Dava vardır,efkarında özünde.

Onlarınki fikirdi, bizimkisi lakırdı

Onlarınki kasırga, bizimkisi takırtı.

.', 'Mana vardır üstadların sözünde. Dava vardır,efkarında özünde. Onlarınki fikirdi, bizimkisi lakırdı Onlarınki kasırga, bizimkisi takırtı. ....', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ustadlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayraklı Baba', 'bayrakli-baba-halil-colak-r2ufn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ufuklar dar geliyor şehitlerle kaldığım bu gecede

Manevi bir haz var Gelibolu denilen bilmecede

Her taraf manevi surlarla örülmüş bu kutsal beldede

Şehitler yatıyor bu yörede tekbir sesleri yükseliyor göklere de

Bayraklı baba kurulmuş bir tepede binlerce bayrakla

Ona gelen insanlar onu vasıta kılarak yalvarıyor Allah’a

Samimi yalvararak ayyıldızlı bayrağı asıyor iplere de

Şehitler yatıyor bu yörede tekbir sesleri yükseliyor göklere de

Kendisi horasan ereniymiş gelmiş iklimi Rum’a

Savaşta eşsiz bir cengâvermiş aman vermezmiş düşmana

Elinde bayrağı tekbir getirirken korku düşermiş düşmana

Şehitler yatıyor bu yörede tekbir sesleri yükseliyor göklere de

Bayraklı babanın rivayete göre atı’da Allah yolunda savaşır

Bayrak elinde cephe cephe dolaşır askerin imdadına yetişir

Savaş meydanlarında efsaneleşir unu yedi iklime yetişir

Şehitler yatıyor bu yörede tekbir sesleri yükseliyor göklere de

Halil Çolak  16.8.2005 Bayraklı Baba Gelibolu', 'Ufuklar dar geliyor şehitlerle kaldığım bu gecede Manevi bir haz var Gelibolu denilen bilmecede Her taraf manevi surlarla örülmüş bu kutsal ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bayrakli-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''ı Hüda', 'ask-i-huda-selim-basar-rsbv9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeter! ! açılsın perde ve duman.

Artık eylersede eylesin viran,

Zaten harab olmuş, cihaz-ı zaman 

Aşk''ı Hüda dan gayr''ı ya varmı gönülde derman?', 'Yeter! ! açılsın perde ve duman. Artık eylersede eylesin viran, Zaten harab olmuş, cihaz-ı zaman  Aşk''ı Hüda dan gayr''ı ya varmı gönülde der...', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-i-huda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakiki maşuk', 'hakiki-masuk-selim-basar-2uwz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç birşey aklına gelmez onun geldiği kadar 

Hiç birşeyi göremezsin hayalen ondan başka, 

Gözlerin cemaliyle ruhun aşk''la temaşa

Allahım senden başka, layık değildir aşk''a.', 'Hiç birşey aklına gelmez onun geldiği kadar  Hiç birşeyi göremezsin hayalen ondan başka,  Gözlerin cemaliyle ruhun aşk''la temaşa Allahım sen...', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hakiki-masuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi kendime', 'kendi-kendime-tuncay-akdeniz-k10re', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem nasıl anlatayım derdimi

Sağ gözün sol göze faydası yoktur

Hak katında insan bildim kendimi

Bencilliğin öze faydası yoktur

Akıl ile geldim insan olmaya

Gönülleri gezdim sevgi bulmaya

İrfan çeşmesine gittim dolmaya

Riyakarın söze faydası yoktur

Güzellik verilmiş haktan insana

Kul hakkıyla demiş gelmeyin bana

Kuranla peygamber rehber imana

İnançsızın köze faydası yoktur

Gönlümü bağladım seven birine

Kalpleri donatmış iman nuruna

Sevenleri sesler kendi turuna

Yanlış yolun ize faydası yoktur

Gündüz güneş gece ayla yerindim

Yer yüzünde alem ile süründüm

İnsanlara insan gibi göründüm

Eğrisinin düze faydası yoktur

Alemlere tek bir dille konuşan

Senin yokluğunda halim perişan

Kul Tuncay’a gülüp haddini aşan

Çok gülenin yüze faydası yoktur', 'Bilmem nasıl anlatayım derdimi Sağ gözün sol göze faydası yoktur Hak katında insan bildim kendimi Bencilliğin öze faydası yoktur Akıl ile ge...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kendi-kendime-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum Sevgili', 'bekliyorum-sevgili-kerem-kayar-e52zq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllardır bekledim, gelen her yaz ile

Yoluna gerilen bir ağ var sanırım

Gelecek her yarın bugünden fazla

Gönlümü sevgine bağlar sanırım

Hasretin nabzında attığı zaman

Bekledim, her güneş battığı zaman

Hayalin, göğsümde yattığı zaman

Kalbimde bir pınar çağlar sanırım

Bülbüller ağladı, inledikçe ben

Dağ, dere ses verdi, hiç duymadın sen

Gönlümün sesini dinledikçe ben

Yaralı bir ahu ağlar sanırım

Baharlar, dallara çiçek takınca

Her gurup, ömrümden bir gün yakınca

Kaybolan yıllara, dönüp bakınca

Bir ateş ki; bağrımı dağlar sanırım…', 'Yıllardır bekledim, gelen her yaz ile Yoluna gerilen bir ağ var sanırım Gelecek her yarın bugünden fazla Gönlümü sevgine bağlar sanırım Hasr...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekliyorum-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğruna Yüreğimi Sürgünlere Yolladığım Yar', 'ugruna-yuregimi-surgunlere-yolladigim-yar-kerem-kayar-swby4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Penceremi aralamışım

içeri sızan bahar değil, senden kalan bir eksik

Tabakamdan sigaramı sarmışım

dumanı bile senden yana savruluyor

Ah…

uğruna yüreğimi sürgünlere gönderdiğim yar

ben hâlâ aynı sokaklarda kayboluyorum

Kaldırımlar değil artık sırdaşım

ayak izlerim bile yabancı bana

Geceler omzuma çökmüş

bir yalnızlık var

adı konulmamış, ağırlığı tarif edilmez

Taşıyamıyorum

her adımda biraz daha içime gömülüyorum

Yaban eller değil aslında

insan en çok kendine gurbet

Şimdi sen sıcacık yatağında

üşüme…

Ben burada

soğuğu senin yerine seviyorum

Avuçlarıma düşse de kanlı yaşlar

ben yine senin yerine ağlarım

Sen…

hiç eğme başını', 'Penceremi aralamışım içeri sızan bahar değil, senden kalan bir eksik Tabakamdan sigaramı sarmışım dumanı bile senden yana savruluyor Ah… uğr...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ugruna-yuregimi-surgunlere-yolladigim-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaş 30', 'yas-30-selim-basar-ajmpp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şah çekti zaman bize, yolun sonumudurki? 

Yoksa şakaklardaki, karmı? dolumudurki?', 'Şah çekti zaman bize, yolun sonumudurki?  Yoksa şakaklardaki, karmı? dolumudurki?...', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yas-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı sen benim kanadımsın', 'marti-sen-benim-kanadimsin-yasemin-sungur-nn6vg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Martı

martı, en sevdiğim şehrin simge kuşu,

martı, çöplüklerin süsü,

martı, soframın konuğu,

martı, simitimin yarısı senin,

martı, en yüksekteki en parlak ışığın uçuşan kurdelası,

martı, hüzünlerimin komşusu,

martı, dalgaların ritmisin,

martı, gitmek istediğim yerlerin yolcusu,

martı, sen benim kanadımsın...

(istanbul, haziran 05)', 'Martı martı, en sevdiğim şehrin simge kuşu, martı, çöplüklerin süsü, martı, soframın konuğu, martı, simitimin yarısı senin, martı, en yüksek...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sungur']::text[], 8.5, '{"poet":"Yasemin Sungur","poet_slug":"yasemin-sungur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/marti-sen-benim-kanadimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca', 'yalnizca-metin-yalti-9ll0a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevmek insanlık 

çünkü sen 

insanlığa uzanan tüm çizgilerdesin 

hava gibi 

su gibisin 

sen 

mübarek ekmek gibisin 

oysa ben 

seni severim 

yalnızca.......... 

Metin yaltı 23/08/05 

Sevgili Gülseren Onay''a ve tüm öğretmenlere', 'Seni sevmek insanlık  çünkü sen  insanlığa uzanan tüm çizgilerdesin  hava gibi  su gibisin  sen  mübarek ekmek gibisin  oysa ben  seni sever...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizca-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-yunus-isikoglu-7zgiy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Babam Akdenizl i

Annem Karadeniz

Ben

Kuzeyrenvestfalya lı

Ben Hasret im

Söyle Avrupa lı

Ben nereliyim

Söyle Asya lı

Ben nereliyim

Ve

Ben kimim

Ben

Asyalıyım

Ben

Avrupalyım

Ben

İnsanlığın hasreti

Adım Hasret

Avrupa da benim

Asya da ben

Ben insanım

Adım Hasret', 'Babam Akdenizl i Annem Karadeniz Ben Kuzeyrenvestfalya lı Ben Hasret im Söyle Avrupa lı Ben nereliyim Söyle Asya lı Ben nereliyim Ve Ben kim...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hasret-264-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakikatimdir.', 'hakikatimdir-gulnare-leman-eu20n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedendir bilmirem şeref de,şan da,

Ayda,yıldızlar da,sanki mekan da   

Harekete keçir..kaynayır,taşır,           

Aklım da,beynim de sırla oynaşır.. 

Sevdamı arayır,hicranmı gezir? 

Amansız bir sual kalbimi ezir.

Nedir hayalımı  karışık salan,

Benim ilhamımı elimden alan

En uzak  aleme çekib götüren? 

Nedir ciğerimi didip koparan

Sırlarmı,hayalmı,bilmirem nedir? 

Ecelmi,ömürmü,bir mucizedir...

..Nedir? ...cansızmıdır,canlıdır ya da,

Sıcakmı,soğukmu bilmirem o da

Sırrını açmayır,demir ki nedir? 

Aşkmı ya uydurma  efsanemidir? 

 Sevdamı,sevgimi,adi hevesmi...

Ruhi,düşüncesi,sıdkı,varlığı,

Emeli,paklığı,vefakarlığı,

Benmiyim? ..,bilmem ki,bu da bir sual

Ben ise başka şey edirem hayal.

Efsane diyil bu,hakikatimdir

İnce muhabbetim,sadakatımdır.', 'Nedendir bilmirem şeref de,şan da, Ayda,yıldızlar da,sanki mekan da    Harekete keçir..kaynayır,taşır,            Aklım da,beynim de sırla o...', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hakikatimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Artık Sustuğun Konuş Biraz Güzelim', 'yeter-artik-sustugun-konus-biraz-guzelim-umut-gungor-07bd5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne yapmaya çalışıp, ne diye yazmıyorsun,

Sevgimi tartıyamı koyupta tartıyorsun,

Öfken varsa vur hadi ne diye duruyorsun,

Yeter artık sustuğun konuş biraz güzelim.

Senin kadar sabırlı olamam biliyorsun,

Seven nasıl eriyor bakıpta görüyorsun,

Mezara gireceğim günümü bekliyorsun,

Yeter artık sustuğun konuş biraz güzelim.

Yeşertip bahçemizde yine sevgi çiçeği,

Büyütelim seninle neşe adlı bebeği,

Çatlasın bırakta kıskananın göbeği,

Yeter artık sustuğun konuş biraz güzelim.

Bırakıp kalemi ellerimle yazacağım,

Sitemleri gizleyip şiirimle kızacağım,

Desemde inanma sen gezip tozacağım,

Yeter artık sustuğun konuş biraz güzelim.', 'Ne yapmaya çalışıp, ne diye yazmıyorsun, Sevgimi tartıyamı koyupta tartıyorsun, Öfken varsa vur hadi ne diye duruyorsun, Yeter artık sustuğu...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeter-artik-sustugun-konus-biraz-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedi Diyerek Çınar Ağladı', 'gelmedi-diyerek-cinar-agladi-umut-gungor-6coli', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bülbüller hep seni çağırdı durdu,

Güllerin feryadı yüreği vurdu,

Turna isyan ile kanadı vurdu,

Gelmedi diyerek çınar ağladı.

Çiçekler açmayı unutur oldu,

Güller goncasını kurutur oldu,

Acılar yüreği burutur oldu,

Gelmedi diyerek çınar ağladı.

Ay doğunca mehtap gelmek bilmedi,

Samanyolu gözyaşımı silmedi,

Gökkuşağı renklerini dilmedi,

Gelmedi diyerek çınar ağladı.', 'Bülbüller hep seni çağırdı durdu, Güllerin feryadı yüreği vurdu, Turna isyan ile kanadı vurdu, Gelmedi diyerek çınar ağladı. Çiçekler açmayı...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelmedi-diyerek-cinar-agladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Çok Var Daha', 'bize-cok-var-daha-bekir-mutlu-gokcesu-mgjvt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok bakacağı var gözlerimin

Söyleyeceği çok sana dillerimin

Çok var, çok daha vuslata...

Gözümde şiirsin damla damla

Dilimde nehirsin bitmezsin 

Bitmez içimin sesi sana akmakla...

Sığmaz sevgin yüreğime taşıyamaz

Yüreğim yorgun, çığlık çığlığa...

Mesela diyorum mesela

Daha karşılaşmadık 

Çok var vuslata...', 'Çok bakacağı var gözlerimin Söyleyeceği çok sana dillerimin Çok var, çok daha vuslata... Gözümde şiirsin damla damla Dilimde nehirsin bitmez...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bize-cok-var-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayta Çocuk', 'hayta-cocuk-omer-arslan-34q53', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haytanın biriyim ben 

		Ama sevgilere ihanet etmem

	                Zamansız açan tomurcuğum

	                Ve hayta yaramaz bir çocuğum

		Belki zamansız doğdum

		Zamansız sevdim belki

		Ah o zamanlar bir bilseydim

		Neyse …..

		Ben hayta çocuğum

		Her şeyde ilk bendim

		Ama babamın ilk çocuğu değildim

		İlk sigarayı ben içtim

		Tabi ilk sopayı da ben yedim

		İlk ben kaçtım evde şehre

		İlk takımı mahallede ben kurdum

		Sapanla ilk ben kuş  vurdum

		Babam ilk bana kızardı

		İlk kırık karneyi de ben aldım

		Sınıf ta ilk ben kaldım

		Okuldan ilk ben kaçtım

		Kavgalara ilk ben girdim

		Her şeyde ilk bendim 

		İlk askere ben gittim

		İlk ben geldim nasıl geldimse

		İlk ben sevdim ilk ben evlendim

		İlk çocuk sahibi bendim

		Bilmiyorum ilk ölecekte benmiyim? 

		

                                http://sairarslan.sitemynet.com', 'Haytanın biriyim ben  		Ama sevgilere ihanet etmem 	                Zamansız açan tomurcuğum 	                Ve hayta yaramaz bir çocuğum 	...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hayta-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Sende Git *', 'sende-git-serdar-celebi-tyyfe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'git! 

sende git

herkes gibi 

sende...

rengini açıkça belli etmenin, 

dürüstlüğün, 

ve yaşadığının ahlakını savunmanın

yalnızlıklarla,

dışlanmalarla,

en temiz duyguların suistimaliyle ödüllendirildiği 

bir dünyada

sende git! .

yalnızlık bir ütopya olmaktan çoktan çıktı

sosyalliğimi kaybetmemek için verdiğim savaşı kaybettim. 

kıyılardayım artık

yalnız odalardayım

bir kıyıda, 

kentin tüm yalnızlığını içimde tutuyorum.

sen git! 

deniz kenarından kumlara iz bıraka bıraka

onlarda silinir bir dalga gördümü nasılsa...

evet silinir bir şeydir gidişin.

bir yara gibi kabuk bağlayıp hiç olmamışçasına silinir

ve ben kıyımda hiç olmamışsın gibi devam ederim yaşamaya.

ama bir de silinmezlikler vardır ki

yaradan çok bir iz gibidir.

hiç silinmez,

sürekli üstündedir,

nereye gidersen git

ne yaparsan yap

hep aklındadır

bir karabasandır

uykuların haram olduğu gecelerin baş mimarıdır

hayattan soyutlar seni

kıyıya çeker.

karşı konulamaz bir korkudur

karamsarlıkların en önde geleni

amaçsızlıkların tek nedenidir.

öyle bir izdir ki silinmez 

aldatılmışlık...

bu damgayı vuranlardan biri de sen oldun alt tarafı.

alt tarafı kıyıdan kopamayacağımı anlattın bana

savaşı tüm benliğimle kaybettirdin 

içimde kalan, bölük pörçük son umudumu yitirttin 

bir yaşamı canlandırıp, budaklandırabilecekken

küçücük bir sevgiyi çok görüp sende gittin alt tarafı.

git

sende 

herkes gibi...

14/04/2005

kıyı', 'git!  sende git herkes gibi  sende... rengini açıkça belli etmenin,  dürüstlüğün,  ve yaşadığının ahlakını savunmanın yalnızlıklarla, dışlan...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sende-git-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve ben', 'sen-ve-ben-erol-buker-4jbn4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen beyaz olsan

ben siyah olurum

gündüzle gece gibi

yani BEŞİKTAŞ gibi

sevinç olsan hüzün 

gül olsan diken 

sen şeker olsan 

ben tuz olurum

sıkı tut ellerimi şeker 

bırakma beni 

düşersem tuzbuz olurum.', 'Sen beyaz olsan ben siyah olurum gündüzle gece gibi yani BEŞİKTAŞ gibi sevinç olsan hüzün  gül olsan diken  sen şeker olsan  ben tuz olurum ...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-ve-ben-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmez Ölü', 'olmez-olu-necip-fazil-kisakurek-lm0t5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mezardadır timsali

Millete babalığın.

Ölmez ölü misali,

Ruhu, kalabalığın...', 'Mezardadır timsali Millete babalığın. Ölmez ölü misali, Ruhu, kalabalığın......', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olmez-olu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Yağış Bitti *', 'yagis-bitti-serdar-celebi-lai72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak! 

işte yine başladı gönlüme kar tanecikleri düşmeye.

Oysa güneş göstermişti yüzünü

Isıtmıştı bedenimi bir zaman

Bahar gelmiş çiçekler açmıştı

Serçe ötüşür

Deniz parıldar olmuştu.

İyiye doğru gidiyordu sanki yaşam 

O aşksızlık kokan gözlerini tekrar görmezden evvel

unutmuştum oysa seni

Olmayacaktın bir daha 

Adını anmayacak

Senin için ağlamayacaktım.

Düştüğümde hemen doğrulacak

Kendimi kıyılara sürmeyecektim

Ama olmuyor

Verdiğim sözleri tutamıyorum işte

Sana benzediğim tek nokta bu olsa gerek…

Denizin kıvrımlarına bakıp 

Da Vinci’den bir tablo hayal ediyorum; 

“Son akşam yemeği…”

Biz seninle son akşam yemeğinde neler konuşmuştuk hatırlar mısın? 

Elimde değil; ben hatırlıyorum; 

Başka bir şehrin, başka bir lokantasında, başka bir zamandaydım 

Başka insanların, başka dünyalarında…

Bana yabancı olan her şey senin hayatına çoktan girmişti bile

Kaybetmiştik geçmişimizi

Geleceğimizi kaybetmiştik… 

Her şey için çok geçti ama

Yinede umutla savaştım,

Savaştım sonuna dek; ölü bir insanı diriltmeye…

Ama olmadı işe; 

Ben seninle en büyük aldanışları yaşadım.

Martılara simit atıyorum Sirkeci’den Kadıköy’e gelirken

Ne kadar vefasız hayvanlar yiyip kaçıyorlar simitleri

Biraz olsun minnet edip omzuma konmuyorlar

Sevdirmiyorlar kendilerini

Yada beni sevmiyorlar…

Oysa o simidi onları sevmek 

ve onlar tarafından sevilmek için atıyorum 

Havada kapıp kaçmaları ve yutup tekrar geri gelmeleri için değil.

Ama hayvanlar sonuçta öyle değil mi? 

Bir hayvandan ne beklenebilir ki? 

Belki de ben kendi kendimi aldattım kim bilir; 

Bir hayvandan çok şey bekleyerek…

Kar yağışı bitti...

18/04/2005

kıyı', 'Bak!  işte yine başladı gönlüme kar tanecikleri düşmeye. Oysa güneş göstermişti yüzünü Isıtmıştı bedenimi bir zaman Bahar gelmiş çiçekler aç...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yagis-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretliğimin Hasreti', 'hasretligimin-hasreti-sahin-karakulunc-ridw1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzümü Döndüm İstanbul’a

Açtım kollarımı gökyüzüne

Deniz gönderdi,

Rüzgar getirdi seni bana

Tuttum,

İçtim gözlerinden.

Kokundan,

Tadından anladım

Hasretliğimin hasretisin

19 Ağustos 2005, Devrek', 'Yüzümü Döndüm İstanbul’a Açtım kollarımı gökyüzüne Deniz gönderdi, Rüzgar getirdi seni bana Tuttum, İçtim gözlerinden. Kokundan, Tadından an...', ARRAY['Türk Edebiyatı','Şiir','Şahin Karakulunç']::text[], 8.5, '{"poet":"Şahin Karakulunç","poet_slug":"sahin-karakulunc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hasretligimin-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Sen **', 'sen-serdar-celebi-pcy4g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen bir pragmatistsin... 

tüm hücrelerinin çekirdeklerine işlenmiş olan 

bencillik duygunu da  buna eklersek 

ortaya çıkan cismin 

bir insan olma olasılığı kadar insansın.

sen habislerin en önde gelenisin...

hiçbir korku senaristinin yazamayacağı kadar kötüsün

ve bir o kadarda acımasızsın.

“”“yeni doğmuş bir bebeği

annesinin bağrından alıp 

o annenin gözleri önünde; 

önce kemiklerini teker teker kırıp

sonra o küçücük bedeni diri diri düdüklü tencerede haşlayacak

ve o leş kokuyu içine çekerek 

bundan zevk alacak kadar sadistsin.””” 

sen tüm eşrafınla bir eziyet müptelasısın

seni Allah yaratmış olamaz 

sen bir insan olamazsın

söyle nesin sen

nesin şeytanın odalığı? 

şimdi bu satırları o hiçbir işe yaramayan yüreğinle okuyup

içini çeke çeke 

ve umursamamaya çalışarak

belki de olumlu düşünüp 

“benim için hala bir şeyler yazacak kadar değer veriyor” diye düşünen

o muhakeme yeteneğinden mahrum küçücük beyninle

bak şu son mısralara:

çünkü 

bu satırların devamında hiçbir şey yok.

tıpkı senin lanetlenmiş hayatının devamında 

iyiliğe dair hiçbir şeyin olamayacağı gibi...

18/04/2005

kıyı', 'sen bir pragmatistsin...  tüm hücrelerinin çekirdeklerine işlenmiş olan  bencillik duygunu da  buna eklersek  ortaya çıkan cismin  bir insan...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-618-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Kal Benimle', 'kal-benimle-salih-ozalasan-kfh5u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim ilk aşkım, ilk heyecanımsın. 

Kalbim seninle dolu. Sen benim ilk göz ağrımsın. 

Çıkmaz oldun aklımdan, yüreğimde bir cansın. 

Seviyorum seni hala ilk heyecanla, 

Kal benimle, gitme kal! benden uzaklara. 

Sen benim sultanım, sen benim ilk aşkımsın. 

Vermez miyim bu canı ben senin için. 

Sevmekten öte bende senin yerin, 

Dünyalara değersin sen  benim için. 

Gitme benden uzaklara  gitme kal benimle 

Sen benim ilk aşkım ilk sevdiğimsin, 

Sen bende teksin! Sen bir tanemsin. 

Filiz TEKİN

yazılım tarihi 20.8. 05 

saat 14', 'Sen benim ilk aşkım, ilk heyecanımsın.  Kalbim seninle dolu. Sen benim ilk göz ağrımsın.  Çıkmaz oldun aklımdan, yüreğimde bir cansın.  Sevi...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kal-benimle-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Şimdi Ölemem *', 'simdi-olemem-serdar-celebi-eac1o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğime hiç acımadan çaktığın kazık hala çıkmadı yerinden,

ama bak hala hayattayım

çünkü bir gün; bana yaşatmış olduğun bu duyguları

sende yaşayacaksın kadınım.

ve o zaman bu bendeki kazığa ihtiyacın olacak

münasip bir yerine sokman için...

o yüzden şimdi ölemem bir tanem

kazığımı sana devredince (söz vermiş gibi olmasın)  belki...

04/05/2005

kıyı', 'Yüreğime hiç acımadan çaktığın kazık hala çıkmadı yerinden, ama bak hala hayattayım çünkü bir gün; bana yaşatmış olduğun bu duyguları sende ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/simdi-olemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* İntikam *', 'i-ntikam-serdar-celebi-4oz4k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman geçer acım bitmez

Yüreğim ağlar intikam diye.

Güneş batar, gece bitmez

Güzüm ağlar intikam diye.

Hakkın olan mutluluk değil,

Yaptığın insanlığa sığar değil,

Vefasız dişi, yalnız dostlar değil

Düşman ağlar intikam diye.

Canımın biricik cananıydın 

Bu kahpeliği bana nasıl yaptın

Hayatımın tek anlamıydın

Duyan ağlar intikam diye.

Vurup gittin bir şerefsiz gibi

Bunca sene oyun oynamış gibi 

Sanki kendine yapılmış gibi

Dostum ağlar intikam diye.

Kanın damarında durmaz akar,

Yaptıklarını Rabbim elbet sorar

Mezarına tükürmeden bu can nasıl yaşar

Her an ağlar intikam diye.

Aşağılık varlığın attı bana pençe,

Yaşantım oldu paramparça

Ölmedikçe, var oldukça

Serdar ağlar intikam diye.

05/05/2005

kıyı', 'Zaman geçer acım bitmez Yüreğim ağlar intikam diye. Güneş batar, gece bitmez Güzüm ağlar intikam diye. Hakkın olan mutluluk değil, Yaptığın ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/intikam-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Sakın Gelme *', 'sakin-gelme-serdar-celebi-jk4s0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir daha bana geri gelme

o ihanet ve aşksızlık kokan nefesini hissetmek istemem.

satılık ruhuna verecek beş kuruşum yok

yok artık sana delice aşık yüreğim.

tek dermanım olsan da 

gelme bana....

seni göresim kalmadı artık

yaşayasım kalmadı bu lanet hayatta

hiçbir şeyim kalmadı senin nefretinden başka

nefretimi sonlandıracak tek kişi olsan da 

gelme bana...

ben kıyıdayım gittin gideli

kıyıya vurmuş bir balığım artık

beni kıyıdan tekrar denize yollayacak tek insan olsan da

gelme bana...

senin elinde yaşamın anlamı biliyorum

ama anlatma istemem.

ilacım sen olsan da 

gelme bana...

senin vereceğin mutlulukla yaşayacağıma

mutsuz ve yapayalnız gebermeyi beklerim

sakın ola gelme bana...

14,05,2005 

kıyı', 'bir daha bana geri gelme o ihanet ve aşksızlık kokan nefesini hissetmek istemem. satılık ruhuna verecek beş kuruşum yok yok artık sana delic...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sakin-gelme-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Cehennem *', 'cehennem-serdar-celebi-j0w6y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gecenin en koyu kabusu 

ürkütücü bir müziğin notası olup

doluyor kulaklarıma

yürüyorum

umutsuzlukların 

aldanışların peşi sıra... 

yanımda bir aşkın çürümeye yüz tutmuş soğuk cesedi

karşımda tüm ihtişamıyla şehrin kahpe ışıksızlığı

büyüyorum gitgide

kocaman bir ürperti oluyorum

doğamıyorum sabaha...

ışıksızlık huzurumu kaçırıyor

engelliyor beni

hep gecede kalıyorum.

kulaklarımda hep o ürkütücü nota 

beynimi kemiriyor

bir türlü doğamıyorum sabaha

silinmez bir umutsuzluk karaladın

kaderimin en güzel sayfalarına.

sonu gelir mi artık gecelerin? 

artık nasıl uyanabilirim ki kabuslardan? 

geceler ışıksız 

geceler sonsuz

geceler sensiz

eğer yaşamak buysa 

ben bu yaşamı reddediyorum

kulaklarımda o ürkütücü notayla

gidiyorum

kabusumun gerçeğe döneceğe yere



19/05/2005 

cehennem', 'gecenin en koyu kabusu  ürkütücü bir müziğin notası olup doluyor kulaklarıma yürüyorum umutsuzlukların  aldanışların peşi sıra...  yanımda b...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cehennem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanırsın', 'sanirsin-omer-arslan-x4fte', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her beyazı kefen her kırmızıyı kan sanırsın

Geçen geceyi gündüzü kısacık bir ansanırsın

Gurbetin kucağında yıllarca yaşarsında

Biraz hasret giderdiğin yeri yuvan sanırsın

                   (Tılsımlı Gözler)', 'Her beyazı kefen her kırmızıyı kan sanırsın Geçen geceyi gündüzü kısacık bir ansanırsın Gurbetin kucağında yıllarca yaşarsında Biraz hasret ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sanirsin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Seni Arıyorum *', 'seni-ariyorum-serdar-celebi-iik8p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'düştü düşecek artık bedenim,

eksildikçe eksiliyorum

suretim siliniyor sanki aynalarda

ki hangisine baksam 

aynadaki ben değilim.

eski dostlarda unuttu gitti beni

ve ben

şimdi kıyımın tenhalarında

yalnız başıma seni arıyorum.

her gece artarak büyüyor umutsuzluğum

hiçbir şeyin rengi eskisi gibi canlı değil

değişiyor güzel olan her şey

ve ben 

yavrusunu kaybetmiş ana gibi

buruk bir yürekle seni arıyorum.

yağmurlar yağıyor karanlığıma alabildiğine sert,

gördüğüm tüm insanlar ağlamaklı

kadehler sarhoş etmez oldu

gözyaşları içimdekileri dışa atmaz oldu

Bitmiş yaşama hevesi

Bitmiş umutlar

Yarınlarda koca bir bilinmezlik dururken

Ölümün soğuk yüzünde seni arıyorum.

Soğuk bir yatakta yalnızım

Soğuk bir odada

Ve soğuk bir dünyada 

Gözlerimden yaş hiç eksilmiyor

Dudaklarım konuşamıyor,  ben susuyorum

Gel artık! ne olur gel de al şu canımı

Gölgem bile gölgeni arıyor.

4.11.2002 

kıyı', 'düştü düşecek artık bedenim, eksildikçe eksiliyorum suretim siliniyor sanki aynalarda ki hangisine baksam  aynadaki ben değilim. eski dostla...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seni-ariyorum-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Yok Oluyorum *', 'yok-oluyorum-serdar-celebi-5cek3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gitgide siliniyor aynalardaki suretim 

uyuşukluk tüm vücuduma yayılıyor 

buna bir türlü engel olamıyorum

yaşam artık sadece uyumak

yemek yemek 

ve yediklerimi hazmedip; 

hazmedemediklerimi boşaltmaktan ibaret oldu 

hep aynı yerde 

yaşamla ölüm arasındaki o ince çizgide yürüyorum 

adımlarımı dışa taşırmadan 

bir uçurumun en uç noktasında 

yere çömelmiş cevabı olmayan sorular soruyorum kendime 

zihnimin algılayabilme kapasitesini aşıp 

o cevapsız sorularımı yanıtlamaya çalışıyorum 

ama bir şey mani oluyor sonuca ulaşamıyorum. 

tam anlayacakken anlamsızlaşıveriyor hayat 

her şeye en başından başlamam gerekiyor 

ve her başlangıçta daha çok sürükleniyorum kıyılara 

bu belirsizlik sonum olacak 

göz göre yok oluyorum

22/06/2005 

kıyı', 'gitgide siliniyor aynalardaki suretim  uyuşukluk tüm vücuduma yayılıyor  buna bir türlü engel olamıyorum yaşam artık sadece uyumak yemek yem...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yok-oluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Kaptan Sağda İndir Beni *', 'kaptan-sagda-i-ndir-beni-serdar-celebi-6od72', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kaptan sağda indir beni

biliyorum daha çok uzun bir yol var önümüzde

üstelik burada inersem kaybolacağım 

ve başka seferde yok bu düzergahta

ama yinede indir beni kaptan

daha fazla insanlığımı yitirmek istemiyorum.

ilençli bir kabustu katettiğimiz yüzbinlerce kilometre

hesabını tutamadım.

dikiz aynasından bir bak; 

geldiğimiz yer başlangıç noktamızdan bile geride...

yolda ilerlemek için bir amaç olmalıydı aslında

amaç içinde bir sebep

oysa benim hiçbir sebebim yoktu

sebepsizken bir amaç uğruna yollara düşmek 

hayal kırıklığının en büyüğü oldu benim için

başaramadım işte.

daha fazla insanlığımı yitirtmeden 

anla beni ve indir sağda

24/08/2003

kıyı', 'kaptan sağda indir beni biliyorum daha çok uzun bir yol var önümüzde üstelik burada inersem kaybolacağım  ve başka seferde yok bu düzergahta...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaptan-sagda-indir-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Sanal *', 'sanal-serdar-celebi-4ptbu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yenilenen acılarla iç içeyim,

mutlu olmak yada üzülmek herhangi bir şeye

nedir unuttum...

milyonlarca acı çekiyorum ama 

çektiğim acıların hiçbiri artık canımı yakmıyor

ve ben hiçbir şeyi umursamıyorum...

nötrleştim yaşama karşı....

hayata olan duyarlılık katsayım, 

sevenlerimin zihinlerdeki yerim,

ve aynalardaki görüntüm silindi gün be gün 

sanal oldu artık her şey 

bu yapaylıkta kayboldum.

oysa söz vermiştim kendime 

hiç etkilenmeyecektim sert esen rüzgarlarda 

yönümü asla kaybetmeyecek 

yaşama hiç pasif kalmayacaktım

ama olmadı

ne yaparsam yapayım 

kendimi bir girdabın kıyı kenarında 

yalın ayak yürürken buldum....

yapaylığa doğru attığım adımlarda

ayaklarıma batan her çakıl taşı 

bir gözyaşıma mal oldu 

ve ben tükettim artık göz yaşlarımı...

bundan sonra artık ağlarsam sanal ağlarım

gülersem artık sanal...

18/07/2005

kıyı', 'yenilenen acılarla iç içeyim, mutlu olmak yada üzülmek herhangi bir şeye nedir unuttum... milyonlarca acı çekiyorum ama  çektiğim acıların h...', ARRAY['Türk Edebiyatı','Şiir','Serdar Çelebi']::text[], 8.5, '{"poet":"Serdar Çelebi","poet_slug":"serdar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sanal-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Şimdi Başbakan', 'o-simdi-basbakan-salih-celik-q0b7d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz …

En karasını sende gördük sevdanın

Hasretin en yürek yakanını…

Sende gördük başkanım; 

Yüreğin en delikanlısını.

Dikenleri gördük bu yolda 

Umutların üzerinde gölgeleri,

Kara kapkara zindanları gördük belki de

Belki de…

Ölümüne havasız hücreleri

Seni kimi zaman; 

Bağdaş kurup yemek yerken görürdük 

Hakkarili Osman dayıyla 

Kimi zaman; 

Sakaryalı Mehmet amcayla çay içerken,

En demli saatinde gecenin.

Kimi zamanda; 

Elini öperken görürdük,

Gecekondulu Fatma ninenin.

Biz…

Seninle el eleydik başkanım.

Gönül gönüle diz dize.

Aldığımız hava; 

İçtiğimiz su kadar  yakındın bize.

Çamlıca dayız…

Cıvıl cıvıl kuş sesleri…

Kulağımızda en güzel nağmeleri müziğin.

Ilık bir rüzgar esiyor yine

Sıcak bir Ağustos gecesinde.

Sen geliyorsun aklımıza başkanım

Eş dost sohbet ederken

Çamlıca da bir çay bahçesinde.

Konuşuyoruz da! 

Bir bardak çay neredeydi

Biz neresindeydik bir fincan neskafenin

Neresindeydik,

Rüzgarla oynaşan yapraklar arasından,

Boğazı seyretmenin.

Hani bazen bir kar yağar başkanım

Yükseklere çok yükseklere

Erimek nedir bilmez

Bizde ki sevdan, öyledir işte,

Ateşe atsan erimez.

Sana söz veriyoruz başkanım.

Gökyüzüne resmini çizeceğiz mutluluğun

Sevgi çiçeklerinin,

Kokularını süreceğiz bulutlara

Notalarını yazacağız kardeşlik şarkılarının; 

Ufuklara.

Biliyoruz başkanım

Bir gül tomurcuğu kadar masumsun,

Bir su damlası kadar berrak,

Öyle temiz; 

Öylesine temizsin ki,

Bir ananın sütü kadar ak

Güzel yarınlar var düşlerimizde

Düşünceler hür,

Fikirler serbest,

Şiirler suç sayılmayacak.

Bilirsin başkanım; 

Yaşayamayacağımız düşler kurmayız.

Ya olacak,ya olacak

Ekleriz başkanım,

Günü güne ekleriz; 

Seni öylesine çok seviyoruz ki

Ölene dek bekleriz.

                         Ümraniye', 'Biz … En karasını sende gördük sevdanın Hasretin en yürek yakanını… Sende gördük başkanım;  Yüreğin en delikanlısını. Dikenleri gördük bu yo...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/o-simdi-basbakan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık edilmiş aşklar kervanı', 'yazik-edilmis-asklar-kervani-sair-son-ruzgar-3qpgl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazık Edilmiş Aşklar kervanı

Yazık edilmiş aşklar kervanına katıldık…

Şimdi hangi cephede arasan,

 Hatta bulsan bile aşkı,

Yitirmiş olacak anlamını bizim gibi...

Kırıntılara bakıp toplamak isteyecek aşk,

Sen çekeceksin,saklayacaksın yüreğini …

Kendinden kaçarak kurtulmanın yollarını bulamadığında,

Düşeceksin en sarp kayalıklara! 

Ne diyebilirim ki adaletsizliğini anlıyorum çünkü sen değişemezsin,

Benim aşk’dan anladığım sen değildin,

Görmek istediğim gibiydin

 Ve ben seni değil, aşk’ı sevdim.', 'Yazık Edilmiş Aşklar kervanı Yazık edilmiş aşklar kervanına katıldık… Şimdi hangi cephede arasan,  Hatta bulsan bile aşkı, Yitirmiş olacak a...', ARRAY['Türk Edebiyatı','Şiir','Şair Son_rüzgar']::text[], 8.5, '{"poet":"Şair Son_rüzgar","poet_slug":"sair-son-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yazik-edilmis-asklar-kervani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
