INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerde Şarkılarda Aşk Adın', 'siirlerde-sarkilarda-ask-adin-umut-gungor-b9ak1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreklere vurgun olup inersin,

Pusu kurup bir köşeye sinersin,

Bir gönülden diğerine geçersin,

Şiirlerde şarkılarda aşk adın.

Zevk alırsın ateş atıp kaçmaktan,

Kıvılcımı kalplerine saçmaktan,

Gönüllere derin yara açmaktan,

Şiirlerde şarkılarda aşk adın.

Neden bilmem garipleri seçtiğin,

Kötüleri çiğneyipte geçtiğin,

Keyiflenip yudum yudum içtiğin,

Şiirlerde şarkılarda aşk adın.

Vazgeçtim bak sana kafa yormaktan,

Gelene geçene seni sormaktan,

Pınarlarda ağaç gibi durmaktan,

Şiirlerde şarkılarda aşk adın.', 'Yüreklere vurgun olup inersin, Pusu kurup bir köşeye sinersin, Bir gönülden diğerine geçersin, Şiirlerde şarkılarda aşk adın. Zevk alırsın a...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siirlerde-sarkilarda-ask-adin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim', 'seni-sevdim-cansu-sevda-ozbey-aokfe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşümdüm gecelerce, 

Sevgilerin 

En güzelini vermek için. 

En güzel düşlerimde yaşattım seni. 

Yüreğimin her zerresini sana adadım. 

Gözlerime işledim gözlerini, 

Seni gördüm nereye baksam. 

Yalnız sen sev istedim beni. 

Yarınlarımda tek sana yer verdim. 

Seni yazdım, 

Kaderim diye alnıma. 

Seni istedim her şeyden çok. 

Yoksan anlamsız dünya, 

Anlamsız sensiz yaşamak. 

Mutluysam gülüyorsam, 

Bunca çileye inat, 

Bilirim ki bu senin eserin. 

Yaşamayı seviyorsam 

Acıları siliyorsam, 

Kollarındayken senin, 

Bilirim ki bu senin eserin. 

İnkâr etmen faydasız. 

Benden çok sevmen imkansız. 

Hece hece 

Dilime yazmışım adını. 

Anlatamam hiçbir şeyle, 

Seni sevmenin tadını. 

Doymaz yüreğim. 

Doymaz ellerim. 

Seni sevmeye doymaz bedenim. 

Bunca sene sonra, 

Seviyorsam kendimi, 

Sen sevdiğin içindir beni. 

Ve seviyorsam seni, 

Sevmeyi öğrettiğin içindir bana. 

Seviyorsam seni, 

Sevebildiğim 

Tek insan olduğun içindir. 

Biliyorum, 

Ne zaman dolsa gözlerim, 

Sen sileceksin akan göz yaşlarımı. 

Ne zaman 

Sarılacak bir beden arasam, 

Sen olacaksın beni 

Koynuna alan. 

Senin sıcaklığında bulacağım şefkati. 

Seninle gülüp, 

Seninle ağlayacağım. 

Gerçeğim sen olacaksın. 

En güzel şiirlerimi sana saklayacağım. 

Seninle kuracağım en güzel düşlerimi. 

Yarınlarda da, 

Bu günkü gibi sev beni. 

Senin sarhoşluğundan, 

Hiç ayılmasın yüreğim. 

Ve ecele kadar benimle kal. 

Yalnız benimle ol. 

Seviyorum seni de, 

En sevdalı şiirleri söyle. 

Yaşatacağım bir ömür, 

Sevgini yüreğimde 

Yaşatacağım bir tanem… 

 Cansu Sevda ÖZBEY', 'Seni düşümdüm gecelerce,  Sevgilerin  En güzelini vermek için.  En güzel düşlerimde yaşattım seni.  Yüreğimin her zerresini sana adadım.  Gö...', ARRAY['Türk Edebiyatı','Şiir','Cansu Sevda Özbey']::text[], 8.5, '{"poet":"Cansu Sevda Özbey","poet_slug":"cansu-sevda-ozbey","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/seni-sevdim-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arazi', 'arazi-mikdat-bal-8crth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstirahatteydik, tüfek çatmıştık

Kimimiz gölgede gidip yatmıştık

Sevindik, zıpladık takla atmıştık

Sanki bir savaştan muzaffer gibi

Kimi susamıştı suya giderdi

Kimisi oturmuş sohbet ederdi

Yarın sinemaya gidelim derdi

Eğitime çıktık her sefer gibi

Garanti yok hiç birinin sözünde

Zaten ne garanti dünya yüzünde

Nöbet var gecede hem gündüzünde 

Ben de nöbet tuttum her nefer gibi

Birden alarm çaldı arazi dendi

Beş dakka da toplanmamız istendi

Bölük komutanı önden gidendi

Ben de hazırlandım bir şoför gibi

Takım edevatı omuza aldık

On saat yürüdük ormana daldık

Siperlere yattık kırkbeş gün kaldık

Kepi kullanırdık bir miğfer gibi

Mikdat der bu canım fedadır yurda

Biti tanımazdık tanıdık orda

Dışarda kalmıştık yağmurda karda

Çamur deryasında bir lüfer gibi', 'İstirahatteydik, tüfek çatmıştık Kimimiz gölgede gidip yatmıştık Sevindik, zıpladık takla atmıştık Sanki bir savaştan muzaffer gibi Kimi sus...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/arazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nihat Behram (Az Eylemiş)', 'nihat-behram-az-eylemis-yusuf-ter-icxyb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nihat Behram (Az Eylemiş) 

Gökyüzüne ağız verip gecesini gün eylemiş 

Ya neylesin gün görmeyen ya neylesin 

Daraldıkça yüreğini zor eylemiş 

Zaman olmuş hırçınlığı huy eylemiş 

Ya neylesin durgun suda çağıltısız ya neylesin 

Yorulanlar dili bülbül kini sümbül eylemiş 

Yaş eylemiş şaş eylemiş düzenbazı baş eylemiş 

Direnenler yılı yıla derdi derde taş eylemiş 

Uykuları kuş eylemiş özgürlüğü düş eylemiş 

Zaman olmuş sızıları usul usul boş eylemiş 

Acıları aş eylemiş bir dilimi beş eylemiş

Nihat Behram 

Not: bu şiiri indirmemin nedeni sevgili Nihat Behramın kendi sesinden

Az Eylemiş sesli olarak dinlemeniz için  ekledim MP3 olarak...

sevgilerimle Yusuf Ter', 'Nihat Behram (Az Eylemiş)  Gökyüzüne ağız verip gecesini gün eylemiş  Ya neylesin gün görmeyen ya neylesin  Daraldıkça yüreğini zor eylemiş ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nihat-behram-az-eylemis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sensiz Bırakma', 'beni-sensiz-birakma-cansu-sevda-ozbey-wzb5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu yüreğimi,sana adadım bir tanem. 

Saçımın her bir telini, 

Senin için uzattım. 

Sende buldum,sevgilerin en yücesini. 

Umut etmeyi öğrettin, 

Sevmeyi sen öğrettin bana. 

Bana aşkların en güzelini yaşattın, 

Bütün zamanlarımda. 

Beni sensiz bırakma, 

Bırakma! ne olur bir tanem… 

Seninle doğdum yeniden. 

Yaşayacaksam seninle yaşarım. 

Gülersem seninle güler, 

Ağlarsam seninle ağlarım. 

Çünkü! sevmedi hiç kimse beni 

Senin sevdiğin kadar… 

Beni sensiz bırakma, 

Bırakma! ne olur bir tanem… 

Yüreğine dağlar sığar. 

Denizlerin sevgi dolar. 

Sensiz nefes alamıyorum, 

Yıkarsa beni bir gün, sensizlik yıkar. 

Al götür beni, 

Yüreğinin zindanlarında zincire vur. 

Görsünler ki! 

Esirinim güneşsiz odalarda. 

Bilsinler ki! 

Hiç ayrılmayacağız. 

Duysunlar ki! 

Destanlar yazılsın aşkımıza. 

Beni sensiz bırakma, 

Bırakma! ne olur bir tanem… 

Cansu Sevda Özbey', 'Sevgi dolu yüreğimi,sana adadım bir tanem.  Saçımın her bir telini,  Senin için uzattım.  Sende buldum,sevgilerin en yücesini.  Umut etmeyi ...', ARRAY['Türk Edebiyatı','Şiir','Cansu Sevda Özbey']::text[], 8.5, '{"poet":"Cansu Sevda Özbey","poet_slug":"cansu-sevda-ozbey","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beni-sensiz-birakma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim', 'seni-ozledim-cansu-sevda-ozbey-7qhhq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç gecem sabahlara hasret kaldı 

Sensiz zamanlarımda. 

Kaç gecem uykusuz dört duvar arasında 

Özledim seni delicesine, 

Aklım sende kaldı. 

Pencereme mahkum, yolunu bekledim. 

Sesini dinledim kapılarda. 

Dost aradı gözlerim,haberini verecek. 

Kaç gecem sensiz çıktı sabahlara. 

Kaç sabah geçti. 

Kaç ikindi sardı akşamları. 

Tükendi umutlarım her hüzün vakti. 

Tükendim sevgilim her gün batımları. 

Sensiz kaldım bu odalarda. 

Gece lambasında aradım gözlerini. 

Duvarlarda resmini aradım. 

Vazomda ki çiçeklerde kokunu, 

Göğsünü aradım yastığımda. 

Özledim seni delicesine, 

Aklım hep sende kaldı. 

Özledim seni delicesine… 

Cansu Sevda Özbey', 'Kaç gecem sabahlara hasret kaldı  Sensiz zamanlarımda.  Kaç gecem uykusuz dört duvar arasında  Özledim seni delicesine,  Aklım sende kaldı. ...', ARRAY['Türk Edebiyatı','Şiir','Cansu Sevda Özbey']::text[], 8.5, '{"poet":"Cansu Sevda Özbey","poet_slug":"cansu-sevda-ozbey","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-ozledim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk=Özgürlük', 'ask-ozgurluk-bekir-mutlu-gokcesu-f4kdc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha iyi anlıyorum şimdi

Hiç kasıtsız ve kısıtsız

Özgürlüğündü vazgeçemediğin...

Sen gerçek misin derdin

Öfkesizliğimi, gülüşümü severdin

Doğallığımızı bir de...

Hiç koşulsuz ve beklentisiz

Sevdin işte, sadece sevdin

Fark etmedi senin için ne dedimse...

Düştüm, güçtüm oysa içimde

Kolaylandım seninle

Şimdi daha iyi anlıyorum

Özgürlüğündü vazgeçemediğin bende...

Benim de...', 'Daha iyi anlıyorum şimdi Hiç kasıtsız ve kısıtsız Özgürlüğündü vazgeçemediğin... Sen gerçek misin derdin Öfkesizliğimi, gülüşümü severdin Do...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nuro''ya', 'nuro-ya-ercan-cengiz-b9fq1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrı zamanlardı, iki karanfil buluştuğunda

Sıcak, çıplak tepe başında

Boylu boyunca düştüler, yan yana

Beyaz Dağ''ına Dersim''in,

Bir karanfil kendi renginde

Bedenine saplanmış kör bir kurşun...

Uzak diyarlardan adres sorulurdu

Ve saplanırdı bedenine, bir kurşun daha. 

Son mermisiydi Beyaz Dağ''da 

Çarpışmadan arta kalan 

İndirmeden kirpiğini, onu da Hüseyin aşkına

Sıkıyordu karanlığın bekçisine.

Dizleri dermansız, doğrulamazdı yerinden

Son nefesine yakın, hayat bir film şeridi gibi 

Ama bitmemişti haykırmalar

Ve mavzerini kırıyordu kayalara vura vura

Sonra, fırlatıyordu uzaklara

Parça parça,

Ki geçerse de ellerine kör kurşunun 

Kullanılamaz halde geçsindi gaye...

Ayrı zamanlardı dağlarda iki karanfil buluştuğunda

Karanfillerle

Kör kurşundu yıkılası Eleziz sokaklarında 

Saplanmıştı bedenine,

Kan anonsu geçilirken mahalle sakinlerinden

Sokaklara pusu atılmıştı

Korkaklardı, doymamışlardı kana

Karanlığın ortasındaydılar kana doymayanlar.

İlk kurşundu sırtından giren

Kalbinden vurup geçerdi

Ve nabzın son atışlarında çevirirdi gözlerini yoldaşça,

Yarasını kaparken bir eliyle

Sıcak gülümsemesine diğer eliyle 

Pusuya yatanları gösterirdi.

Korkaklardı, doymamışlardı

Salya akıtır, kanla beslenirlerdi

Kabarırdı ulumaklı sesler

Eleziz sokaklarında... 

Şimdilerde portreleri ellerindedir ora insanının

Duvarlara renk verirken gülümsemesi

Dağlar aşılırdı O iki karanfille,

Toprağa - güneşe - ateşe

Yağmurun çiselemesinde

Ayrı ayrı zamanlarda gülümsediler

Rüzgarın okşayışında inlerken çınar

Gülün rengine...

İki karanfil düştü ateşe

Bahara ton verdiler, daha da verecekler

Dersim''in dağlarında...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'Ayrı zamanlardı, iki karanfil buluştuğunda Sıcak, çıplak tepe başında Boylu boyunca düştüler, yan yana Beyaz Dağ''ına Dersim''in, Bir karanfil...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/nuro-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Hesabın Sorulacağı Günlerde Gelecek', 'hesabin-sorulacagi-gunlerde-gelecek-veli-dalbudak-9val1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey  insanoğlu, sana bir çift sözum var,

Sayılı günlerin biteceği günlerde gelecek,

Sanmaki ömründe olacak hep bahar,

Renginin solacağı, günlerde gelecek.

Avare dolaşıp boşa harcama günlerini,

Başkasının malına dikme gözlerini,

Sakın haa hırsızlığa alıştırma ellerini,

Ellerin konuşacağı günlerde gelecek.

Gençlikdir diye nefs´ini boş bırakma,

Yalandır bu dünya sakın kanma,

Helali bırakıp harama bakma,

Gözlerin konuşacağı günlerde gelecek.

Ahlak ile donat, yetiştir, kızını oğlunu,

Unutma canının sende emanet olduğunu,

Sağlam bas ayağını, sapıtma yolunu,

Yolların konuşacağı günlerde gelecek.

Yetim hakkı yiyip kar ediyorum sanma,

Gerçekleri unutup hulyalara dalma,

Sen, sen ol, mazlumun ahını alma,

Mazlumun konuşacağı günlerde gelecek.

Kazancını iyi harca,savurganlık yapma,

Şükretmesini bil, sitemkarlık yapma,

Hesabı hilesiz yap, sahtekarlık yapma,

Hesabın sorulacağı günlerde gelecek.

(Stockholm 2005)', 'Ey  insanoğlu, sana bir çift sözum var, Sayılı günlerin biteceği günlerde gelecek, Sanmaki ömründe olacak hep bahar, Renginin solacağı, günl...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hesabin-sorulacagi-gunlerde-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Eğlencene', 'senin-eglencene-ercan-cengiz-g45pp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin eğlencene denirdi

Balık da olsa

Yani 

Nehirdeki balık, Okyanustaki... 

Meşe diplerinden, kayalardan fışkırıp 

Toprağın yüzüne çıkan

Su içindeki balık...

İçtiğin sudaydı balık 

Boğazına duracak.

Sofrandaydı,

Tabağındaki yemekte...

Sudaki balık,

İsmi diline geldiğinde

Kendisiydi tepende duran

Ecdadının aklı almadı,

Bilirim ki senin de almaz...', 'Senin eğlencene denirdi Balık da olsa Yani  Nehirdeki balık, Okyanustaki...  Meşe diplerinden, kayalardan fışkırıp  Toprağın yüzüne çıkan Su...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-eglencene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızdım Ben Ya', 'kizdim-ben-ya-bekir-mutlu-gokcesu-lul4b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir taş atsam her gün denize

Ya rüzgar savurur ya dalga vurur

Döner gelir biri elime...

Günde bir kez gülsem

Körün taşı bir tebessüm düşer

Biri olsun güler yüzüme...

Pes be kardeşim pes yani ilahi

Lazım olduğundan değil ilgin, vefan ama

Pes vallahi...', 'Bir taş atsam her gün denize Ya rüzgar savurur ya dalga vurur Döner gelir biri elime... Günde bir kez gülsem Körün taşı bir tebessüm düşer B...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kizdim-ben-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün burada cumartesi', 'bugun-burada-cumartesi-gokhan-bagislar-ammbe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün burada cumartesi 

ben mutsuzum

ben aşığım 

ve senin benim seni özlediğim kadar özlemediğini biliyorum 

Bugün burada cumartesi

sigaramın dumanı bile kederli 

gece hiç olmadığı kadar uzun 

senin şarkın çalıyor 

sabah hiç gelmeyecekmiş, gün doğmayacakmış, yeni bir güne adım atamayacakmışım gibi geliyor.

Bugün burada cumartesi

sokaklar ıssız 

3-5 sarhoş kaygısız 

erkekler ağlamaz diyenlere inat ağlıyorum 

fotoğrafındaki ışıl ışıl gözlerine bakıyorum 

seni arayıp köpek gibi yalvarmaya korkuyorum 

ne olur gitme, ne olur beni bana bırakma demek istiyorum.

gitarıma bakıyorum 

tekte olsa elini tutmak, avazım çıktığı kadar bağırmak, sana aşık olduğumu  tüm dünyaya haykırmak istiyorum. 

Bugün burada cumartesi 

sensiz geçireceğim günleri düşünüyorum.Mutsuz, tatsız, uykusuz, katıksız 

bir daha asla aşık olmak istemiyorum. 

bu şiir son şiirim olsun istiyorum. 

Bugün burada cumartesi

notaların esrarengiz tılsımı geceyi süslesin, gitarım yine en iyi dostum, bu şiir şarkı olsun 

ve sen gidiyorsun 

ve ben mutsuzum 

Bugün burada cumartesi

elimdeki şarabın şişesi kadar soğuk, içindeki şarap kadar sıcağım 

balıkçı Ahmet’ in  çaparisine takılmış balık gibi çırpınıyorum. 

artık büyük tavsiyesi dinliyorum. 

Bugün burada cumartesi 

şuan için istemesende seni seviyorum', 'Bugün burada cumartesi  ben mutsuzum ben aşığım  ve senin benim seni özlediğim kadar özlemediğini biliyorum  Bugün burada cumartesi sigaramı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bağışlar']::text[], 8.5, '{"poet":"Gökhan Bağışlar","poet_slug":"gokhan-bagislar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bugun-burada-cumartesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Bunalım', 'bunalim-fatma-caglayan-m1cb3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Otur kalk arada sırada tuşlara dokun 

Ayağa kalk biraz gez 

Dışarıya çık biraz hava al 

Telefon aç canın sıkılsın 

Açarmış gibi yap hemen kapa 

Tekrar tekrar etrafı gez 

Of! Of! Allah’ım 

Otur hızlı hızlı nefes alıp ver 

Sessizlik... 

Tekrar telefonu aç 

Kız dişlerin gıcırdasın 

Sonra okkalı bir küfür 

Yüzün sinirden on yedi köşe 

Kendi kendine konuş, anlamsız bir şeyler mırıldan 

Sonra sinirden gül otuz iki dişin görünsün 

Veya ne kadar kaldıysa göster 

Arada sırada masaya, sandalyeye tekme at 

Sinir hala içinde 

En iyisi mi sen 

Kendini köprüden aşağıya at', 'Otur kalk arada sırada tuşlara dokun  Ayağa kalk biraz gez  Dışarıya çık biraz hava al  Telefon aç canın sıkılsın  Açarmış gibi yap hemen ka...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bunalim-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gibi', 'sen-gibi-gokhan-bagislar-sql0a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulutları parçalarcasına süzülen ay ışığı 

Sonunu göremediğim hırçın deniz 

Atakuledeki o park çok güzel dediğimiz

Sen gibi 

Uzak diyarlarda yetişen nadide çiçekler

Akıllara durgunluk veren dünyanın 7 harikası 

Kalbime vurulmuş olan aşk prangası 

Sen gibi

Uzaktan bakıp ürker diye korktuğum Yalıçapkını 

Yolumu kaybettiğimde baktığım çoban yıldızı 

Her zaman sığındığım alnımın yazısı 

Sen gibi

Çocukluğumda düşlediğim elma şekeri

Elime alıp çalmaya cesaret edemediğim gitarım 

Sevincim, hüzünüm, kaygılarım 

Sen gibi 

Gece kuytu köşelere saklanmış güneş 

Sanki herbirinde adının yazdığı kaldırım taşları

Gideceğim dediğinde döktüğüm gözyaşları 

Bu sabah aynaya baktım birtanem uzaktan,

karşıdaki silüet sana delicesine tapan

kaybetmekten korkan 

Ben gibi', 'Bulutları parçalarcasına süzülen ay ışığı  Sonunu göremediğim hırçın deniz  Atakuledeki o park çok güzel dediğimiz Sen gibi  Uzak diyarlarda...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bağışlar']::text[], 8.5, '{"poet":"Gökhan Bağışlar","poet_slug":"gokhan-bagislar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-gibi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Darmadağın', 'darmadagin-fatma-caglayan-rdwf8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevinçlerin darmadağın 

Gül, eğlen 

Bırak ağlamayı 

Bak nasıl yazıyor kalem 

Yazamadığın bütün sırları 

Dünya sırlarla dolu 

Bir iğne deliği 

Oradan bakabilirsen 

Gör 

Tadına, neşene bak 

Sıkılma her zaman 

Gül 

Yıldızlar o kadar da uzakta değiller aslında 

Sen uzaktasın 

Onlar hep yakınında 

Güneş de öyle 

Sensin uzakta olan 

Onlara suç bulma bırak 

Bırak sıkıntıyı 

Somurtmayı bırak', 'Sevinçlerin darmadağın  Gül, eğlen  Bırak ağlamayı  Bak nasıl yazıyor kalem  Yazamadığın bütün sırları  Dünya sırlarla dolu  Bir iğne deliği...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/darmadagin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Güneş', 'gunes-fatma-caglayan-a03rm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey! Güneş, sana sesleniyorum! Sana 

Duyuyor musun? Beni 

Ama nerden duyacaksın ki 

Bana o kadar uzaktasın ki 

Ve ben her daim karanlıktayım 

Ey! Güneş, sana sesleniyorum! Sana 

Işık saç! Benim de kapkaranlık dünyama…', 'Ey! Güneş, sana sesleniyorum! Sana  Duyuyor musun? Beni  Ama nerden duyacaksın ki  Bana o kadar uzaktasın ki  Ve ben her daim karanlıktayım ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gunes-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelibolu', 'gelibolu-halil-colak-breh9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ahi yan-ı Rum meşhur olan adında senin.

Esnafa ticari ahlak nasıl olur onu sen öğrettin.

Osman Gazinin dualarla sen kuşattın

Osmanlı denilen ulu çınarının temelini birlikte attın

Her köşende birçok ulu kahraman yatıyor Gelibolu

Ahilik teşkilatını mükemmel kurdun

Ticari ahlakı nizama soktun

Bir çınar gibi kok salıp durdun

Yedi iklimi ruma şan verip durdun

Süleyman Paşanın adım atığı yer Gelibolu

Her köşende birçok ulu kahraman yatıyor Gelibolu

Bacı yan-ı denilen Türkmen kadını

Rum diyarına İslam ahlakıyla yaydı adını

Evinde ana, savaş meydanlarında cengâver idi

Güzel ahlakıyla kadınlar arasında baş tacı idi.

Kadınlarında kahramandır senin Gelibolu

Her köşende birçok ulu kahraman yatıyor Gelibolu

Abdalan –ı Rum denilen horasan ereni

Ağzından eksik olamazdı Allah kelamı

Kalender Baba başka bir irşat ereni

Şerbetçi Baba denilen Akıncı eri

Tahta kılıçlarla mucahitler savaş ederdi

Her köşende birçok ulu kahraman yatıyor Gelibolu

Abdurrahman Gazi, Akbaş denilen Alp yiğitlerinden

Kara Oğlan, Kara Mürsel gibi koç yiğitlerinden

Yahsılu, Kara Beg, Şeyh Mahmut gibi âlimlerinden

Gal Mihmit, Kara Tekin gibi serden geçtilerinden

Alp erenleri bağrında olan sen Gelibolu

Her köşende birçok ulu kahraman yatıyor Gelibolu

Gazi Süleyman paşa sallarla geçip vatanda yaptı

Senin topraklarına Türk İslam mührünü bastı

Hüseyin Kelamı paşa sende hakka da vardı

Kum Baba kerametiyle kumlardan ada yaptı 

Keramet ehlinin sen otağısın Gelibolu 

Her köşende birçok ulu kahraman yatıyor Gelibolu

Rum eli fütuhatının ileri gelenlerinden

Bola yırı dilere destan kahramanlığı ile alanlarından

Ece abat ta adını veren Ece Beyim sende yatanlarından.

Piri Baba askere şevk ve heyecan katanlarından.

Savaşırken sende şehitlik mertebesine erenlerinden

Her köşende birçok ulu kahraman yatıyor Gelibolu

Hüseyin Bece Geliboluluyu irşat edenlerinden

Salı pazarını ebedi istirahat seçenlerinden

Kalender Baba gönül kapısını açanlarından

Bin bir kerameti sende olanlarından

Allah’ın huzuruna gönül rahatlığı ile gidenlerinden

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

Bayraklı Baba şanına yakışır şekilde binlerce bayrakla dolu.

Gelibolu savaşında bayrak düşmana geçmesin diye yemiştir onu

Mezarımda bayrak eksik olmasın diyen tarihte tek vasiyet onun

Her bayrak asanın dileği olur dillere destandır keramet onun

Türbesi bayraklarla dolu evliya sende yatar Gelibolu

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

Emir Ali babadır fetihte bulunan kaptanıderya

Fetihlerinden biride adıyla alınan İmranlı ada

Gemiler geçerken dudak çalarak selamlar onu

Denizlerin bir zaman hâkimi dillere destandır unu

Yüksek bir tepeden gözetler Geliboluluyu

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

Rumeli fatihi Süleyman paşanın odur sancaktarı

Sancaktar Babadır ünlü cengâver yiğidin adı

Çimpa kalesi, Bol ayır kalesi alınınca düşman aman diledi

Gelibolu’nun her tarafına bayrağı dikti rüzgâra saldı

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

Hamza köye nazar eder yüksek bir tepeden

Hatıra kalmıştır Kaptanıderya sarıca paşadan

Ondan hatıra kalmıştır birçok hamam bedesten

Niğbolu savaşında Yıldırım Beyazıtla yazmıştı destan

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

Yeşil Etekli İmamdır asker arasında meşhur onun lakabı

Kendisi Horasan ereni Ethem Bin Abdullah piri Hz. Adı

Fetih sırasında şehit düşenleri defnederdi bu Allah dostu

Heybeti ve büyük cesaretiyle düşmanın yüreğine korku salardı

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

İbn-i Şimşit Hz.leri denilen Allah’ın o güzel dostu

Rum diyarında İslami manevi köprüler kurdu

Yeşil Etekli İmamla aynı bahçede ebedi istirahat gahi oldu

İnşallah cennette iki cengâver komşu olarak birbirini buldu

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

Gelibolu da medfum’dur Hamza paşada

Hz..Hamza ile Mahşerde Allah komşu etsin yan yana

Namı değer ismi Damat Sinan Paşa o da Gelibolu da

Sultan Beyazıt’ı veli mührü vermiştir Sinan Paşaya

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

Horasan ereniyim gezemedim tüm evliyaları

Allah nasip ederse dua ile ziyaret ederim onları

İnşallah Mevla onları şefaatiyle bağışlar bizleri

Anadolu’yu İslamlaştırdı bu horasan erenleri 

Her köşende birçok ulu kahraman yatıyor Gelibolu’m

Halil Çolak 19.5.2005 Gelibolu', 'Ahi yan-ı Rum meşhur olan adında senin. Esnafa ticari ahlak nasıl olur onu sen öğrettin. Osman Gazinin dualarla sen kuşattın Osmanlı denilen...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/gelibolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi canım', 'hadi-canim-fatma-caglayan-188wp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Okumak istiyorum hay Allah 

Işık da öyle loş ki 

Bir türlü okuyamıyorum 

Hadi canım sende 

Işığa ne gerek var 

Biliyorsun ya ezbere', 'Okumak istiyorum hay Allah  Işık da öyle loş ki  Bir türlü okuyamıyorum  Hadi canım sende  Işığa ne gerek var  Biliyorsun ya ezbere...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hadi-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orkide', 'orkide-atilla-guler-nq1xd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her şey...bir kez daha 

yeniden başladı yaşanmaya 

aynı teraneler...yine aynı sancılar 

su/tersine akamaz ki 

nasıl ki döndüremezsen geriye 

geçen zamanı 

tik…tak…tik….tak 

aşk mı yanlış/ben mi ters geliyorum aşka 

insanlar mı dönek/yoksa bana mı yanlış öğretildi/ “insan” mefhumu 

buysa eğer... insan/ben neyim 

eğer ben insansam...onlar ne…aşk nerede? 

bu saatinde günün/yak bir sigara daha 

parçalanıyor ciğerlerim her nefeste 

dumanında kayboluyor çizgi 

penceremin önündeki pervazda...yine sorular takılı 

ses yok! ...dünya susuşlarda... 

nasıl olur ki... 

cevapsız sorulara bir çözüm…y o k 

kahinlerde bir telaş 

çocuklar en güzel düşlerinin tam ortasında 

bir kaç soluk kaldı 

karabasanlara 

kırmızı gökyüzü...güle rengini verirken 

bir orkide daha açtı yapraklarını aşka 

aşk mı daha güzel 

...orkide mi? 

her 

sözcüğün 

ardına 

gizli 

sevda 

sözlerine 

saklanmış 

bir 

dizede 

sunuldu 

y ü r e k 

sevgiliye 

dökülmeye başladı 

yarına yeşeren yapraklar 

bir…bir 

…sarı şarkıların esaretini karlar kapladı 

mevsimsizim artık 

her 

gün 

açılır 

bir orkide daha 

hercai 

yalancı 

…a ş k? 

y o k…mevsimler y i t i k', 'her şey...bir kez daha  yeniden başladı yaşanmaya  aynı teraneler...yine aynı sancılar  su/tersine akamaz ki  nasıl ki döndüremezsen geriye ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/orkide-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler - II -', 'dortlukler-ii-talip-sinecikli-c5dri', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerim bembeyaz, tenim bembeyaz,

Kanım çekiliyor sanki yavaş yavaş,

Ölüyormuyum ne? 

Yüzüm bembeyaz.', 'Ellerim bembeyaz, tenim bembeyaz, Kanım çekiliyor sanki yavaş yavaş, Ölüyormuyum ne?  Yüzüm bembeyaz....', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortlukler-ii-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayılar', 'sayilar-fatma-caglayan-1rcue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah! Şu sayılar, rakamlar 

Birbirinizle yarış mı yapıyorsunuz? Yoksa 

Kavga mı? Kiminiz çarpıyorsunuz 

Kiminiz eksiliyorsunuz 

Sonuçta toplanıyorsunuz 

Yığılıyorsunuz 

Çık çıkabilirsen bu işin içinden', 'Ah! Şu sayılar, rakamlar  Birbirinizle yarış mı yapıyorsunuz? Yoksa  Kavga mı? Kiminiz çarpıyorsunuz  Kiminiz eksiliyorsunuz  Sonuçta toplan...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sayilar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül ile bezerim seni!', 'gul-ile-bezerim-seni-ozan-si-ar-agdasan-p8fhg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarınlara sarkacak, çağlar boyu anıta, 

Yar kazıta kazıta, kazarım seni seni

Canım uğruna kurban, gerek var mı kanıta? 

Kalbime mühür ile kazarım seni seni! ... 

Sevdanla öğütüldüm, girdim aşk çuvalına

Piştim aşk ekmeğinle, severim yar ay seni

Güven olmaz dünyanın, bin türlü ahvaline

Dikenli aşk gülünle, döverim ben vay beni! 

Şiar can ardın sıra, meler kuzu me''sinde

Yüreğimi hoplatan bir nağme var sesinde

Sen bağ olsan, ben bağban gönüller kafesinde

Yediveren gül ile bezerim seni seni! ..

Kalbime mühür ile kazarım seni seni

Yar kazıta kazıta, yazarım seni seni! ...

Söz ve Müzik: Ozan Şiar Can-Ağdaşan

Yorum: ŞAh Turna Şahturna

''İnadına Sevdamız'' Kitap...Gül ile bezerim seni Şiir albüm

Yolunda köprü olsam- Barışak: Müzik albüm', 'Yarınlara sarkacak, çağlar boyu anıta,  Yar kazıta kazıta, kazarım seni seni Canım uğruna kurban, gerek var mı kanıta?  Kalbime mühür ile ka...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-ile-bezerim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Nankör', 'nankor-fatma-caglayan-f1vbf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O senden daha esaslı 

Gözü kördür 

Kulağı sağır 

Beklemeyi sever 

Hareketliyken ayağı, sana takılır düşersin 

O devam eder 

Sen olduğun yerde kalırsın 

Ağzın açık bilmem kaç metre 

Onunda yürüyüşü öyle 

Körlüğü, sağırlığı gitmiştir, ilerler 

O kendince çok ama çok esaslı', 'O senden daha esaslı  Gözü kördür  Kulağı sağır  Beklemeyi sever  Hareketliyken ayağı, sana takılır düşersin  O devam eder  Sen olduğun yerd...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nankor-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Sayalım', 'var-sayalim-meral-vurgun-m2kjw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aslında şöyle kemikleri kırasıya 

sarılmayı getirirdi bu muhabbet

var sayalım...

farzet ki

yani sen dayanamayıp bir şarap açtın

şaşırtmak için bütün serapları

dudakların da kenarında kadehin

ilk yudumundan ikram ettin bana 

ve sarhoşuz ikimiz de

düşün ki

usulca sokulmuşum sol kaburgana

alnında gökyüzü, dudakların ay

gülüşlerin yıldız sağanağı, gözlerin evren

ve gece susmuş dinlencede

uzatıyorsun ellerini

başlıyor yolculuğumuz

o galaksi senin, bu galaksi benim

yeryüzü kanatlarımızın altında

deniz kuzeyden esiyor 

dağlar da 

yanaklarından süzüyor olsun güneşi

ve ben bir serseri kuş olup 

dolaşıyor olayım vadilerini

say ki 

başı boş bir martıyım bu gece

çırpındıkça kanat vuruyorum kıyılarına

ya da bir dişi aslanım, ormanlarını dolanan

yahut da düşün ki

bir telli turnayım gözlerine süzülen

göğsün üstü çayır çimen

ben kır çiçekleri ekiyorum durmadan 

ve bahar kesiliyorsun sen

yürü diyorsun bana, yürü

yaz gelmez sevşilimeden

farzet ki 

yağmura dönüşüyoruz ansızın

sırılsıklam ıslanıyor öpüşlerimiz

derimizi soyunup asıyoruz güneşe

ve kalıyoruz çırılçıplak, yerle gök arasında

bütün evren susuyor

bir tek ben duyabiliyorum 

pır pır şarkı söylüyorsun uçarak

ve yine farzet ki

çocuk olmuşuz yeniden

bildiğimiz-bilmediğimiz ya da

yarım kalmış bütün oyunları yeniden oynuyoruz 

sabahın köründe ip atlıyoruz örneğin

öğlen sıcağında çelik-çomak atıyoruz

kartopu olup yuvarlanıyoruz Zemheri’de

ve kenetleniyoruz büsbütün birbirimize

say ki

zamanın durduğu bir yerdeyiz o an

dizlerini dayamışsın dizlerime

dört mevsim yemiş veren bir ağaç gibi duruyorsun

ben dalında bir serçe ve sarhoşum zil zurna

İblis ölüm uykusunda, Tanrı bağışlamış bizi

ve Tabular dibinde okyanususun

bütün canlılar sevip sevilmede –sevişmede-

ay hilal, ay dolu dulu, gün kıpkızıl

gök masmavi

yerde yeryüzü yemyeşil 

desene yaşama zamanı bu değil mi

bir kadeh daha doldur...', 'aslında şöyle kemikleri kırasıya  sarılmayı getirirdi bu muhabbet var sayalım... farzet ki yani sen dayanamayıp bir şarap açtın şaşırtmak iç...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/var-sayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi İsyan', 'asi-i-syan-mehmet-koc-4abpk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'vuruyorum sensizliği

gecenin gizemiyle

gözlerinin ortasından.

seni alan karanlığı

siliyorum dünyadan

gözler artık

karanlığa gömülmeyecek

benki ayrılıkların

yıkamadığı

sevda yıldızlarının

amansız fedaisi

gömeceğim artık

ayrılıkları

geceyle aynı mezara

kimse ağlamayacak

sevdiğinin ardından

kimsenin dili yanmayacak

sonuna nokta 

konmamış aşklardan.

ve kimse umursamayacak 

gündüzlerinde geceleri', 'vuruyorum sensizliği gecenin gizemiyle gözlerinin ortasından. seni alan karanlığı siliyorum dünyadan gözler artık karanlığa gömülmeyecek ben...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koç']::text[], 8.5, '{"poet":"Mehmet Koç","poet_slug":"mehmet-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/asi-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmişsin', 'gitmissin-alper-torun-89b3q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kime sorayım kim tanır

Kim bilir seni? 

Sanki bu şehirde hiç yaşamamış,

Kaldırımlarında dolaşmamışsın

Yağmurlarında ıslanıp,

Sokaklarında ağlamamış gibisin.

Sen değil misin sanki

Akşam serinliklerinde uğradığın

Tophane kahvelerinde fal baktıran; 

Ortaköy’de denize nazır kurulup

Çayını içerken sigarasının küllerini

Poyraza savuran? 

Sanki hep kendin gitmişsin

Uzak diyarlara,

Esenler garajından

Binilen otobüslerle.

Kimseye el sallayıp uğurlamamışsın

Selamet duaları okuyup gidene

Vardığında haber ver diye

Tembihlememiş gibisin.

Göz pınarlarına gelip oturan

Yaşları silerken gülümsememişsin.

Gidenin bir gün dönmesini

Belli ki hiç beklememişsin

Bir iz, bir haber bırakmadan

Sadece 

Gitmişsin…

26.08.2005', 'Kime sorayım kim tanır Kim bilir seni?  Sanki bu şehirde hiç yaşamamış, Kaldırımlarında dolaşmamışsın Yağmurlarında ıslanıp, Sokaklarında ağ...', ARRAY['Türk Edebiyatı','Şiir','Alper Torun']::text[], 8.5, '{"poet":"Alper Torun","poet_slug":"alper-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gitmissin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni beklerken…', 'seni-beklerken-alper-torun-yqgoe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dingin maskelerin ardında

âsude akşamlara inat

bir fırtınadır kopup giden.

Gözlerim ışıltılı bakmıyor

gittiğin yollardan seni beklerken.

Gözyaşlarım,

yüzyıllık hüzünlere bürünüp,

sessiz ve sinsice damlıyor

içimdeki çocuğun parmaklarına.

Birikmiş çığlıklarım

düğüm düğüm oluyor,

yutkunuyorum…

Bir feryat, bir figan olamadan

haykırışlarım,

kuru bir tebessüme dönüşüyor 

dudaklarımda.

Adın, akıl barikatlarıma

çarparak küçülüyor,

fısıltılı çağırmalarım,

tütünün dumanına karışıyor; 

Savrulup kaybolurken

peşin sıra yollarında

dönmeni bekliyorum inatla.

Korkulu bir ümitle 

ya “Gel! ” derse

gider miyim diye kuruyorum sessizce.

Küskün bir vedayı

yorgun bekleyişlerle

besleyip büyütüyorum.

Ve sakladığım kavuşmak hayaliyle

beynimin arka sokaklarında,

avunuyorum gizlice…

26.08.2005', 'Dingin maskelerin ardında âsude akşamlara inat bir fırtınadır kopup giden. Gözlerim ışıltılı bakmıyor gittiğin yollardan seni beklerken. Göz...', ARRAY['Türk Edebiyatı','Şiir','Alper Torun']::text[], 8.5, '{"poet":"Alper Torun","poet_slug":"alper-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seni-beklerken-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakılacak Mektuplar 8', 'yakilacak-mektuplar-8-mehmet-tas-zxtrg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen, bir bahar yağmuru kadar ılık, bir gül goncası kadar sevecensin.

Sen sevgisin…Umutsun umutsuzlar için.

Ve sen tüm yaratılmışların üstünde yegane varlık, teksin..

Benim zavallı beynimde çok bilinmeyenli bir denklemsin.

Seni çözmek, kainatın sırrını çözmektir..

Ilık bir bahar sabahıydı.Sen benim varlığımdan habersiz, ben seninle dopdoluydum.Tam sokağın köşesini döndüğümüzde karşılaşmıştık.Bu bir tesadüf değildi.Bunu sen bilmiyordun. Sen beni de bilmiyordun. Gözlerini aradı zavallı gözlerim.

Söyler misin, neden, neden bir kere olsun dönüp bakmadın? 

Eteklerinde akşam rüzgarı efil efil, gözbebeklerinde toprağın suya hasretince arzu. 

Ya dudakların…

Dudakların sahralar kadar sıcak. Öpmedim, öpemedim ama yinede beni yaktı, yakacak…

Bir şiirde mi okumuştum, yoksa bir şarkı sözümüydü? “bir zamanlar bizim de başımızda kavak yelleri eserdi” diyor.

Benim de başımda esen bir kavak yelimiydi acaba? 

Sen kavak yelinden de öte bir fırtına oldun. Estikçe yıkan, yıktıkça zevk  alan bir fırtına..

Es…Durma daha hızlı, daha hızlı es! ! 

Yıkacağın başka ne kaldı?', 'Sen, bir bahar yağmuru kadar ılık, bir gül goncası kadar sevecensin. Sen sevgisin…Umutsun umutsuzlar için. Ve sen tüm yaratılmışların üstünd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yakilacak-mektuplar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fani Dünya…', 'fani-dunya-yurdagul-kurnaz-cv2i5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelmisiz üclük faniye 

Kalici kim! ebediy_ye? 

Zulm ve kini at denize 

Köpüklerinde kaybolsun! 

Sevgidir kalpte abide 

Sultan, saraydir gönülde 

Serefiyle yürüyene 

Acilsin gözdeki perde! 

Acizis______________Insanoglu 

Ak süttür____________Helal kokusu 

Yasamaksa__________Ecel korkusu 

Pismek icin, yanmaya geldik! 

Hesabini kim verecek! ? 

Günahin/ 

_______Sevabin 

Askin/ 

_______Nefretin 

Senin/ 

_______Benim 

Onun/ 

______Bunun 

Egrin______________Senin 

Dogrun____________Senin 

Gittigin yol ise______________________________________ 

_________________''KENDI BENIN”____________________', 'Gelmisiz üclük faniye  Kalici kim! ebediy_ye?  Zulm ve kini at denize  Köpüklerinde kaybolsun!  Sevgidir kalpte abide  Sultan, saraydir gönü...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fani-dunya-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun güneş', 'yorgun-gunes-elazigli-mustafa-kaya-381qd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ruhuma ayna sanki yorgun güneş 

geçtim kendimden 

al boyanmış 

bir taze gelin gibi 

hazırlanıp bir yolculuğa 

güneşe çıkıyorum 

siz gidin 

ben tek başıma gelirim 

ne hızlı…ne de yavaş.. 

haberini bir güvercin getirdi 

ruhumu çınlatan bir boşluk bırakarak 

içimi yakıyor sensiz şimdi seyre dalmak 

şehrin ardına çekilen güneşi. 

ve, 

hüzne boğuldum bu akşam 

yine sensiz saatlere giriyor gecem 

kırmızı güle benzer..                

                                          26.08.2005 / çamlıca

                                           mustafa kaya', 'ruhuma ayna sanki yorgun güneş  geçtim kendimden  al boyanmış  bir taze gelin gibi  hazırlanıp bir yolculuğa  güneşe çıkıyorum  siz gidin  b...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yorgun-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyre dalmak akşamı', 'seyre-dalmak-aksami-elazigli-mustafa-kaya-uss51', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'duydum

saf...masumca  uğraşını

bir,

evin içinde.

bir,

evin bahçesinde.

ve seninle daha beyaz

değdiğin herşey.

aydınlanmış gördüm çevreni

neşe sinmiş ağaçlara

toprak seni beklemiş

çiçekler şarkılarını özlemiş

ve ocak taşları,

razı olmuş yanmaya..

ve bu hayal içinde

bir sofrada başbaşa seninle

ve sonrasında

seyre dalmak akşamı..

istediğim bu benim

seninle olmak.....seninle sevgilim..

                                                               26.05.2005 / üsküdar

                                                                mustafa kaya', 'duydum saf...masumca  uğraşını bir, evin içinde. bir, evin bahçesinde. ve seninle daha beyaz değdiğin herşey. aydınlanmış gördüm çevreni neş...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seyre-dalmak-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem Kuşları', 'deprem-kuslari-i-brahim-ozgan-8caeq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ardısıra yürüdüğüm deprem kuşları 

gözlerimde endişeler hayata dair 

korkulardan değil bilirim 

benimkisi papatyanın yaprağındaki kımıldanış 

susuz yaz akşamlarında 

demir bir oluktan akan soğuk su gibi 

özlediğim sevdalı bir yürek 

ve ona dair bir endişe içimde 

hiçte yanlız değilim aslında 

solmuş güllerim var başucumda 

ve defterimde karalanmış şiirlerim 

ve cem karaca 

''sevda kuşun kanadında ürkütürsen tutamazsın'' 

bilmem kaç sevda ürküttüm 

bilmem kaçını yüreğimden çaldılar 

nazlı seher uykularımı hançerlediler 

tamda sevdalı zamanlarımda 

bilmem kaçı oyunlar oynadı kendi gönlünce 

yürek kıymeti bilmeyenler 

yinede bıkmadım sevdalanmaktan 

yinede solmadı bu yürek 

yorulmadı taşlara değmekten 

bilmem bilirmisin 

sevdalı bir yüreğin nasılda ezildiğini 

kayalar arasına sıkışmış yosunlar gibi 

ardısıra yürüyorum deprem kuşlarının 

yürek depremler yaşamadan 

olgunlaşmazmış sevda üzerine 

yürek yaralanmadan bilmezmiş kadir kıymet 

şimdi artık yeni depremler yaşamalıyım 

ve görmeliyim aşkın gözbebeğini 

bir gözelin yürek ortasında 

''sevda kuşun kanadında ürkütürsen tutamazsın''........

                  2005 ölüdeniz', 'ardısıra yürüdüğüm deprem kuşları  gözlerimde endişeler hayata dair  korkulardan değil bilirim  benimkisi papatyanın yaprağındaki kımıldanış...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/deprem-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötelerdeki Sen', 'otelerdeki-sen-i-brahim-ozgan-hcgwx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğim çırılçıplakken.......... 

dizelerimde ölümün kokusu 

dudaklarımda acımıtrak türküler 

ve böğrümde amansız sancılar varken 

ta ötelerden yüreğinle 

sen çıkageldin 

bütün benliğinle............ 

önce meltemler esti gecelerime 

selamın asilaneydi 

vede sızılı 

harfler birbir anlamlaştı flu camda 

yüreğim kelimelerinle elbiseler giyindi sonra 

ki bir büyü idi sanki 

narin ellerinden gelenler 

kelimelerinin barınağı oldu yüreğim 

uzaklardaydın aslında yoktun varlığınla 

ama biliyorumki sen fizik ötesiydin 

yıldızlarda gökyüzünde ve uzaktalar 

ama en zifiri karanlıklarda en parlak halleriyle 

doğar içimize ışıklarıyla 

sen süreyyam oldun işte 

en zifiri karanlığını yaşarken kalbim 

ve hislerini kaybetmiş tenim 

ışığında kavuştu benliğine............. 

kimsin? ........... 

sahi kimsin sen? ..... 

ne demeliyim sana? .............. 

ve nasıl olduda kankırmızı gözlerimde 

berrak izler bıraktın uykusuz geçen gecelerimde 

ve nasırlı ellerimde hisler................ 

kimsin? ............

gaipten duyulan bir sesmi? ................ 

yedi deniz ötesindeki tayepre mi? .............. 

yeryüzünün bilmem hangi 

muhteşem vadisinde açmış 

kokusu taa burnumda tüten bir zambakmı? ? ? ? ? ? 

kimsin? ............ 

kimsin? ......... 

yüreğime çoşku veren bilinmez 

bir öykümü? 

             2005 ölüdenz', 'yüreğim çırılçıplakken..........  dizelerimde ölümün kokusu  dudaklarımda acımıtrak türküler  ve böğrümde amansız sancılar varken  ta öteler...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/otelerdeki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşmak', 'kavusmak-i-brahim-ozgan-fz9cw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gün karşı tepeye ulaşmadan kavuşavağız sevgili 

kayadiplerinden akan 

ve şarıltılarla yükseklerden dökülen 

şelalelerde bulacağız kendimizi 

bir su zerreciği olup karışacağız denizlere 

ve buluta ve yağmura 

sonra yeryüzüne elele ineceğiz 

gün karşı tepeye ulaşmadan kavuşacağız sevgili 

bie kırlangıcın kanatlarında 

havalanacağız gökyüzüne 

oradan arşıalaya 

ve gezegenlere ve aya ve güneşe 

bir ışık olup doğacağız tan vakti 

koyun koyuna simalara vuracağız 

gün karşı tepeye vurmak üzre sevgili 

şimdi yüreği tazeleme vakti 

eşyanın mahkumiyetinden kurtulma vakti 

ruhuların sevişme vakti 

ruhların aklanıp bedenden uzakta 

birleşme vakti 

aşkın vakti yani sevginin 

üzerimize çullanan karabulutlardan 

ve ansızın çöken sislerden kurtulma vakti 

şimdi ellerimiz yukarda 

gözlerimiz maviliği seyrederken 

ruhumuzun aydınlığını seyretme vakti 

hadi hadi hadi...........

işte ruhlar havalandı kendi indinde 

ve göklerde buluşuyor işte vaktinde.........

2005', 'gün karşı tepeye ulaşmadan kavuşavağız sevgili  kayadiplerinden akan  ve şarıltılarla yükseklerden dökülen  şelalelerde bulacağız kendimizi ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kavusmak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim', 'benim-i-brahim-ozgan-7711h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hey canım....... 

varlığından sevdakar 

vede azade maddeden 

dağlarda koçero yalım yalım kılıcıyla 

vede köroğlu rüzgarla yarışan kıratıyla 

su başlarında ferhat 

vede mecnun çöllerde kurumuş dudaklarıyla 

benim benim....... 

hey canım......... 

sırça sarayda atlası biçen mavera dede 

vede musa kızıldenizi yaran asasıyla 

diyar diyar dolaşan yunus 

vede mevlana can deyişiyle 

benim benim......... 

hey canım....... 

bazan serçeyim kanadı kırık 

bazan bir kırlangıç avcışlar peşimde 

bir turnayım işte nebileyim 

ben bir canım 

her zerresine sevda işlenmiş 

her zerresinde dostane türküler 

ve yetmişyedi rengin senteziyim özüyüm 

hey canım ben bir ademoğluyum 

ben bir canım...........

                     2005 ölüdeniz', 'hey canım.......  varlığından sevdakar  vede azade maddeden  dağlarda koçero yalım yalım kılıcıyla  vede köroğlu rüzgarla yarışan kıratıyla ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/benim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazdıklarına', 'yazdiklarina-i-brahim-ozgan-fc5xc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'işte yazıyorsun yine 

işte bukle saçların; 

kimbilir nasıl duruyordu yüzünde 

bir imbikten süzülür gibi 

sevdalı türkülere 

bulana bulana geliyor 

devleşiyor adeta kelimelerin 

yazmamak ne mümkün 

can atmamak ne mümkün 

yazacaklarını beklemeyi 

susuz çölde su gibi 

dağlarda kızıl ateş gibi 

kabuslu uykulara 

tılsımlı bir el gibi 

dokunuyor her yanıma 

ıstıyor serinletiyor 

sarıyor sarmaşıklar gibi 

ve bir can oluyor 

ölmüş kokuşmuş kalbim 

işlememek ne mümkün 

yürek dolu harflerini 

sen harflerinle yazdırıyosun 

kelimelerine ise 

yüreğim kifayetsiz 

hünerli ellerine 

ve çoşkun yüreğine sağlık.........

2005 ölüdeniz', 'işte yazıyorsun yine  işte bukle saçların;  kimbilir nasıl duruyordu yüzünde  bir imbikten süzülür gibi  sevdalı türkülere  bulana bulana ge...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yazdiklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Yakacak Tenimi', 'ozlemin-yakacak-tenimi-hatice-bediroglu-rdnzp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerimde tatlı bir özlem,

Koşa koşa geliyorum sana.

İpek gibi  duygularım,

Okşayacak seni.

Deli bir sevinç kaplıyor,

Yüreğimi,

Çoğalıyor kanat sesleri,

Çığlık çığlığa duygularım.

Az sonra...

Gülen gözlerin gözlerimde,

İçime sığdırmak istercesine,

Kollarım sarmalayacak seni.

Yüreklerimiz buluştuğunda,

Okuyacak...

Birbirine en güzel nağmeleri.

Coşacak...

Akan kan damarlarımızda.

Özlemin yakacak tenimi.

Hep rengarenksin içimde.

Yağmur sonrası gökkuşağı gibi.

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Gözlerimde tatlı bir özlem, Koşa koşa geliyorum sana. İpek gibi  duygularım, Okşayacak seni. Deli bir sevinç kaplıyor, Yüreğimi, Çoğalıyor k...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozlemin-yakacak-tenimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurban Niye Şaşıyoruz', 'gurban-niye-sasiyoruz-sahin-yilmaz-sszg9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beynimizde seksen tilki,

En ciddi sözümüz, belki,

Ne hedef var, ne de ülkü,

Amaçsızca koşuyoruz,

Gurban niye şaşıyoruz? 

Ekrana olmuşuz köle,

Kültürümüz televole,

Haksızları bile bile,

Sırtımızda taşıyoruz,

Gurban niye şaşıyoruz? 

Yurdumuzdan sürseler de,

Defterimiz dürseler de,

Sırtımızdan vursalar da,

Sessiz kalıp kaşıyoruz,

Gurban niye şaşıyoruz? 

Estik, muhalif  kalınca,

Sustuk, iktidar olunca,

Kargadan rehber bulunca,

Gidip b.ka düşüyoruz,

Gurban niye şaşıyoruz? 

Bize layık kazma kürek,

Düşünmek nemize gerek,

Her sakala uygun tarak,

Kişiliksiz yaşıyoruz,

Gurban niye şaşıyoruz? 

Başımızda sultan, emir,

Haydi demokrasi kemir,

Vicdanlar buz, kalpler çamur,

Sokaklarda üşüyoruz,

Gurban niye şaşıyoruz? 

Açlıkla terbiye olduk,

Düdükle hizaya geldik,

Birkaç kez bedava öldük,

Kaynamadan taşıyoruz,

Gurban niye şaşıyoruz? 

Şahin derki küstürüldük,

Bir köşeye kıstırıldık,

Azarlanıp susturulduk,

Altımıza işiyoruz,

Gurban niye şaşıyoruz?', 'Beynimizde seksen tilki, En ciddi sözümüz, belki, Ne hedef var, ne de ülkü, Amaçsızca koşuyoruz, Gurban niye şaşıyoruz?  Ekrana olmuşuz köle...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gurban-niye-sasiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Direniş', 'direnis-mehmet-dogan-9-vcdd4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerini acıyorsun

baslıyorsun yasamaya

kapatıyorsun baslıyorsun unutmaya

ve şimdilerde sen varsın

bedenimde

ve ben direniyorum

gözlerimi kapamamaya', 'gözlerini acıyorsun baslıyorsun yasamaya kapatıyorsun baslıyorsun unutmaya ve şimdilerde sen varsın bedenimde ve ben direniyorum gözlerimi k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/direnis-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak2', 'yasak2-mehmet-dogan-9-8tt76', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yasak artık 

elini tutumak 

gözüne bakmak 

tenini tatmak 

senin karasularında olmak yasak 

yasak artık göğüsünde yatmak 

nefesini hissetmek 

rüyana girmek 

umuma kapalı yerlerde olmak yasak', 'yasak artık  elini tutumak  gözüne bakmak  tenini tatmak  senin karasularında olmak yasak  yasak artık göğüsünde yatmak  nefesini hissetmek ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasak2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-mehmet-dogan-9-pxpv4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dur durak bilmeden konustun 

saydın saydın saydın 

ne kadar karsı cıktıysam 

o kadar içime bagırdım 

sen saydıkca ben sustum 

basımı one egdim 

ne kadar sustuysam 

o kadar sevdim seni 

ben sustukca sen geldin ustume 

saydın herseyi yuzume yuzume 

ne kadar gozlerim dolduysa o kadar 

yagmur yagdı ustume', 'dur durak bilmeden konustun  saydın saydın saydın  ne kadar karsı cıktıysam  o kadar içime bagırdım  sen saydıkca ben sustum  basımı one egd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahit', 'sahit-mehmet-dogan-9-m2264', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben işten eve yetişmeye calısırken 

sen evde sofrayı hazrılıyordun 

yemekler tabakta tabaklar masadaydı 

yasadiklarimisa sen ben ve masadan 

baska sahit yoktu 

yemekten sonra kanepedeki ben 

dizlerimde uzanana sen 

elim sacinda dolanirken 

yasadıklarımısa sen ben ve kanepeden 

baska sahit yoktu 

saatler geceyi gecince 

seytan bedene girince 

bizden baskasının olmadıgı evde 

yasadıklarımısa sen ben ve yataktan 

baska sahit yoktu', 'ben işten eve yetişmeye calısırken  sen evde sofrayı hazrılıyordun  yemekler tabakta tabaklar masadaydı  yasadiklarimisa sen ben ve masadan ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sahit-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kütahya - Esas Kitabından', 'kutahya-esas-kitabindan-omer-ekinci-micingirt-pm05f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mecnundur toprağı yandı tutuştu

Mevlâna beldesi hilim Kütahya 

Şairi ozanı şöleni hoştu

Yüreğe dokunuş hâlim Kütahya 

Çağların öpüşü Hititler burda 

Çeyizler bezenir gözdeki nurda 

Porselen ebruli dağılmış yurda 

Nakış nakış sevda kilim Kütahya

Antik Roma Kenti durur ayakta

Sütunlu caddede yürür ayakta 

Şanlı uygarlığı görür ayakta 

Sevdalım yavuklum gülüm Kütahya

Şair Şeyhi yazar şehre girişte

Erenler burada şeyhlik bu işte 

Özlem hüzün telaş sarar dönüşte 

Gözyaşım sükûtum dilim Kütahya

Gölgeler gerçekler şiir ve şair 

Dumlu Hoca ile sohbet vesair

Kütahya dualı efsunlu şehir 

Şeyhi Şöleni’nde yolum Kütahya 

Kütahya’’ Şâir Şeyhi Şöleni ‘’ 24 Ağustos 2005', 'Mecnundur toprağı yandı tutuştu Mevlâna beldesi hilim Kütahya  Şairi ozanı şöleni hoştu Yüreğe dokunuş hâlim Kütahya  Çağların öpüşü Hititle...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kutahya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucuz Satmış!', 'ucuz-satmis-muharrem-cetinkaya-t6kbf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün birine rastladım:

İnsanlığını satmış,

Tüm değerlerini...

Kendine bir gözlük almış,

Etrafa farklı bakıyor,

Herkeste ona...

............................

o gözlüğü

Kaça aldıysa; 

Ucuz almış! ...

dostluğu da

ucuz satmış(!)', 'Dün birine rastladım: İnsanlığını satmış, Tüm değerlerini... Kendine bir gözlük almış, Etrafa farklı bakıyor, Herkeste ona... .................', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ucuz-satmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum Birtanem', 'seni-seviyorum-birtanem-levent-nalcacioglu-8jw7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni Seviyorum Birtanem 

  



S ensizliğin içinde doğmuşum, 

E skiden hiç ağlamazmışım ben... 

N edenini bilmediğim korkularım var... 

i syanlar, bitip tükenmeyen haykırışlar... 

S evginin anlamını gözlerinde öğrendim, 

E llerinde buldum sıcaklığını, 

V ahşidir benim ihtiraslarım, 

İ sterler ki sarsın kolların bedenimi sımsıkı 

Y anlızlık, bitip tükenmeyen haykırışlar... 

O lmayan rüyalarımda yaşatırdım seni, 

R üyalarımda dokunurdum gök yüzüne, 

U zanırdım bulutların üstüne, 

M asallar dünyasında yaşardım adeta... 

B unları düşünürken birden bir ürpertiyle irkildim, 

i çim içime sığmıyordu, 

R üyalarım gerçek oluyordu galiba, 

T eslim oluyordu sanki ruhum sonsuzluğa... 

A ma... 

N edenini anlamalıydım... 

E zelden beri dokunduğum gökyüzüydün sen... Fakat; 

M utluluğu yakalayamadan kaybetmiştim... 

Olsun; 

Yinede Seni Seviyorum BİRTANEM...', 'Seni Seviyorum Birtanem     S ensizliğin içinde doğmuşum,  E skiden hiç ağlamazmışım ben...  N edenini bilmediğim korkularım var...  i syanl...', ARRAY['Türk Edebiyatı','Şiir','Levent Nalçacıoğlu']::text[], 8.5, '{"poet":"Levent Nalçacıoğlu","poet_slug":"levent-nalcacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-seviyorum-birtanem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki Seninle Güldü Yüzüm', 'bil-ki-seninle-guldu-yuzum-huseyin-erdogan-3l7g8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bil ki seninle güldü yüzüm

artık akmıyor hiçbir gözüm

yeter ki sevelim birbirimizi

inan ki sevdan uğrunda

bana vız gelir ölüm

her sabah bir güneş gibi

doğacağım dünyana

aydınlatacağım ısıtacağım seni

yüreğimdeki bütün sevgiyi

vereceğim yalnızca sana

sen de beni seveceksin değil mi? 

keşke o güzel gözlerin ben olsaydım

benimle baksaydın dünyaya

ellerin ellerime kaynasaydı da

hiç ayrılmasaydık ömrümüz boyunca

                                     26.08.2005', 'bil ki seninle güldü yüzüm artık akmıyor hiçbir gözüm yeter ki sevelim birbirimizi inan ki sevdan uğrunda bana vız gelir ölüm her sabah bir ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bil-ki-seninle-guldu-yuzum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...YaĞMuRLa...', 'yagmurla-levent-nalcacioglu-znyby', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'EğeR BiR GüN ViRaN OLuRSaM, 

BiL Ki SeVGiLiM Bu SeNiN EseRiN,

ÜzüLMe LüTFeN, ARkaMDaN AğLaMa,

BeN BiR GüN YaĞMuR OLuR, YiNe GeLiRiM...', 'EğeR BiR GüN ViRaN OLuRSaM,  BiL Ki SeVGiLiM Bu SeNiN EseRiN, ÜzüLMe LüTFeN, ARkaMDaN AğLaMa, BeN BiR GüN YaĞMuR OLuR, YiNe GeLiRiM......', ARRAY['Türk Edebiyatı','Şiir','Levent Nalçacıoğlu']::text[], 8.5, '{"poet":"Levent Nalçacıoğlu","poet_slug":"levent-nalcacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yagmurla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalana Dönerken Söz', 'yalana-donerken-soz-suna-aras-u6nu8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve yalanla boşlanan aşktı

Duygu durgunluğuna düşünce

Şiirin evrensel sesi

Güne bakan yüzümle 

Dönüyorum oraya

Aşk

Olmalı diyorum.

Yer kaçıyor durmadan

İhaneti yüklenen ayak oluyor

Duruyoruz aynı kesitte

Dönüyoruz un ufak

Şiir ve aşk telaşlıyım.

İze düşüyor

Sevince dönüşüyor

Daralıp genişliyor

Değişiyor.

Ömrün her gününe

Acıya hayıflana

Zamanın altın demine

Bakır tefler çalıyorduk

Dağınıktık

Şaire irkilmeyen ve irkiltmeyen

Bir dönüş yaşıyorduk.

Gönüllü unutkanlığımızdı şiir

Aşka nasipsizdik

Kapılara kapatıyorduk

Pencerelere yöneliyorduk sonra

Sırt ağrısıydık birbirimizin

Ertelerken her ışığı insana dair

Kendimize erteleniyorduk

Kendi kaçağımızdık

Sıkılıyorduk

Koltuk altlarımıza ellerimizi.

Yalana dönerken söz

Tere

Soğumuş göz ucuydu bakışımız

Emekçiydi yalanına sendika

Evet açıkça

Açlığına ücretti işçi

Kör talihlere yükleniyordu

Kör düğüm

Kör işi.', 'Ve yalanla boşlanan aşktı Duygu durgunluğuna düşünce Şiirin evrensel sesi Güne bakan yüzümle  Dönüyorum oraya Aşk Olmalı diyorum. Yer kaçıyo...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yalana-donerken-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende İstiyorum', 'bende-i-stiyorum-nalan-kahraman-66zgc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine hüsran çöktü içime,

Sıkıntılar kederler başladı yine,

Yalnızlık tak etti canıma,

Bir eş,bir dost istiyorum bende.

Mutluluk rüzgarlarının estiği,

Pembe gözlüklerin atıldığı,

Işıkların saçıldığı bir dünyada

Bir eş,bir dost istiyorum bende.

Sevip sevilemeyecek kadar kötü,

Mutlu olamıyacak kadar berbat,

Terk edilmeye mahkum birimiyim? 

Bir eş, bir dost istiyorum bende', 'Yine hüsran çöktü içime, Sıkıntılar kederler başladı yine, Yalnızlık tak etti canıma, Bir eş,bir dost istiyorum bende. Mutluluk rüzgarlarını...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bende-istiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açılacak Has Bahçende Güllerin En Güzeli', 'acilacak-has-bahcende-gullerin-en-guzeli-kamil-soylemez-lib3w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel,Gel de Otur Yanıma

Gel geç gönül değil

İnan ki sevdan bana

Gecemde,gündüzümde

Hayalin karşımda

Yalvarıp,yakarıyorum sana

Gel aşkım gelde tut ellerimden

Bak yıkılıyorum senin özleminden

Canım yanıyor 

Kanım kaçıyor

Yaşamın tadı acılaşıyor

Bir zemheri sarıyor

Bir ağıstos sıcağı 

Haydi gelde bulalım bunların ortasını

Kah gülüyor

Kah ağlıyorum yokluğuna

Bak kurudu güller döküldü diyorsun

Bağrımda

Filizlenirmi ki bu güller bir daha

Ben uzatıyorun zembille sevgimi

Suluyorum filizlensin diye gülerini

Biraz da sen gayret etsen

Biliyorum açılacak 

Has bahçende güllerin en güzelleri', 'Gel,Gel de Otur Yanıma Gel geç gönül değil İnan ki sevdan bana Gecemde,gündüzümde Hayalin karşımda Yalvarıp,yakarıyorum sana Gel aşkım gelde...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/acilacak-has-bahcende-gullerin-en-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum Can…', 'geliyorum-can-zulfikar-yapar-kaleli-nami9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'img src= http://www.antoloji.com/siir/media/34/www_antoloji_com_304034_551.JPG

font face=''Comic Sans MS'' color=''black'' size=''0,5''

Sevgin acım, sızın sızım

Bak seraba boşuna can

Sanırsın ki vefasızım

Çabam heba, boşuna can

Sağa bakın, sola bakın

Dost iline varış yakın

Unutulmaz deme sakın 

Gayret, çaba boşuna can! 

Kurtlar kuzuyu güdeli

Kuzucuklar oldu deli

Kaç yıl oldu sen gideli

Dost akraba boşuna can! 

Kabul ettim, senin dostun

Bendeki dost benden üstün

Bana ise bütün kastın? 

Annen baban boşuna can! 

Özledim can, çok özledim

Gelir diye çok gözledim

Bunu herkesten gizledim

Mert maraba boşuna can! 

Geliyorum bekle gülüm

Kanda olsa iki elim

Ucunda olsa da ölüm

Çölde aba boşuna can!', 'img src= http://www.antoloji.com/siir/media/34/www_antoloji_com_304034_551.JPG font face=''Comic Sans MS'' color=''black'' size=''0,5'' Sevgin acı...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/geliyorum-can-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iskalanmış Zamanlar', 'iskalanmis-zamanlar-bahri-yildirim-an2bf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bağlamıştım tüm umudumu

Her gün her gün başa döndü

Sevda ateşten bir gömlek

Sen giyince kışa döndü.

Ne ki ömür  dediğimiz

Elde solan güle döndü

Yaktı kendini ve beni

Çok içmiş,sarhoşa döndü.

Anladımki boşa geçmiş

Bunca günler,bunca aylar

Peşpeşe geçince yıllar

Iskalanmış tüm zamanlar

Geçmiş şimdi de karşıma

Diyorki hiç sıkılmadan:

Yalandan kaç insan ölmüş.

...', 'Sana bağlamıştım tüm umudumu Her gün her gün başa döndü Sevda ateşten bir gömlek Sen giyince kışa döndü. Ne ki ömür  dediğimiz Elde solan gü...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iskalanmis-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokuzyüzlüler....', 'dokuzyuzluler-mehmet-demir-atmali-c4gzq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birçok insanın iki yüzü vardır,

Bir tek yüzünü vitrine çıkarır...

İkinci yüze rıza göstermezken; 

Dokuzyüzlü Telefonlar bıktırır...

Önce Dokuzyüzlüleri bilmezdim,

Dokuzuncu Köyü zaten sevmezdim...

Bilseydim, Onuncu Köyden gelmezdim.

Dokuzyüzlüler, her malı götürür...

19.7.1997', 'Birçok insanın iki yüzü vardır, Bir tek yüzünü vitrine çıkarır... İkinci yüze rıza göstermezken;  Dokuzyüzlü Telefonlar bıktırır... Önce Dok...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dokuzyuzluler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Kaderden', 'hepsi-kaderden-figen-aydogmus-w1bv1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hep birseyler eksilir hayatınmdan 

hep saplantılar içinde çırpınırım 

yıkıktır zaten gönlümdeki viran olmuş şehrim 

çırpınışlarda yok olan bir gelecekteyim

sanane ömrüm geçsede böyle 

sana kim ne dedi de nasıl kurtardın 

bırakta huzuru yalın ayak, toprakda arayım 

uzak diyarlara kim fırlat dedi 

sırça bir yüreğim bir de bilinmezliğim 

kimine gizemli kimine açık 

beni bu hale getiren, kaderim 

ben ne seni ne bir başkasını suçlayabilirim 

sitemdir bu hayatın kendisine 

oda kendini bilmez nedeyim 

bıraktım rüzgarın kanatlarına 

savursun beni böyle öleyim', 'hep birseyler eksilir hayatınmdan  hep saplantılar içinde çırpınırım  yıkıktır zaten gönlümdeki viran olmuş şehrim  çırpınışlarda yok olan b...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hepsi-kaderden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldürmedi ki Okşarken Dalgalar', 'guldurmedi-ki-oksarken-dalgalar-ahmet-nural-ozturk-9zyj5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hiç birgün güzel olmadı ki deniz 

hamağında uvutmadı ki beni

güldürmedi ki okşarken dalgaları

öperken titretmedi ki yakamozlari

ne sürdüm sefasını ne gördüm vefasını 

ben ne zaman aşık olsam

deniz havlar

birdenbire fırtına çıkar

içim yanar

ödüm kopardı

ve ben orhan veli''yi arardım 

kulağını çeksin diye hatice''nin

ama nafile

o yine bildiğinden caymaz

hep dertleri içe atardı

ve beni ayırmazdı ne varsa yanında', 'hiç birgün güzel olmadı ki deniz  hamağında uvutmadı ki beni güldürmedi ki okşarken dalgaları öperken titretmedi ki yakamozlari ne sürdüm se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guldurmedi-ki-oksarken-dalgalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Görüşte Aşk', 'i-lk-goruste-ask-can-ceylan-mlnfq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk görüşte aşk olmaz

Yaşanmadan aşk doğmaz

Gözler bağlanır belki

Gönül buna aldanmaz', 'İlk görüşte aşk olmaz Yaşanmadan aşk doğmaz Gözler bağlanır belki Gönül buna aldanmaz...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilk-goruste-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamları Bir Başka Yaşarım', 'aksamlari-bir-baska-yasarim-turk-oger-koc-iia4l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her sabah

gün ışığı

dokunan

saçlarına

değdiririm

dudaklarımı

çekerim nefesimi

sen olursun içimde

gözlerin 

gözlerime 

dalar

bir ürperti

olursun

terkedilmişliğinde

düşlerin

ilk busen

dokunur 

yanaklarıma

sessizce

açılır kapı

kapıdan dışarı

alarak kalbime

fırtınaları

savururum kendimi

kentin sokaklarına

sokaklar sen lenir

gün sen lenir

günü sen de 

yaşarım

öfkesi alınmış

külhan varidir

yürüyüşüm

yere değmez

adımlarım

çok uzakta

kalır

akşam zamanı

güneşe laf atarım

lafım erişmez

zaman kendi keyfinde

nefesim yetmez

uzun soluklu yollara

tene dokunmak ister

özleme başlamış ellerim

çocuk olur

kaprislerle dolar içim

gelmeyen

akşamlara küserim

güneşe küserim

bilmezler küskünlüğümü

bir otomobil geçer

korna çalarak önümden

akrep gibi sokar

saatin kadranları

ne tik tak 

sesini duyarım 

bu zamanlar

ne de şehrin

sesini

sessizleşir her şey

duyarsam ben

yüreğimle duyarım

akşamları ben

bir başka yaşarım

2005', 'her sabah gün ışığı dokunan saçlarına değdiririm dudaklarımı çekerim nefesimi sen olursun içimde gözlerin  gözlerime  dalar bir ürperti olur...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/aksamlari-bir-baska-yasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel …', 'gel-ali-riza-unal-kucju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel her ne ile nasıl istersen onun ile gel

Nerdesin diye sormam nasıl olduğun yeter

İster bulut ister şimşek ister yağmur ile gel

Gel ister fırtına ister bad-ı pürgür ile gel

Senin bad-ı pürgürün bad-ı saba dır bana

Gel hışmına vefa olayım yeterki sen gel 

Eğer yağmur ile gelirsen ben bağistan

Renç-berinim  tarlada hemde hasadın

Sen gerçeğimsin  hayelim değil gel

-------  lügât --------------

bad-ı pürgür  :hışırtılı esen ürpertici huzur bozan rüzgâr.

Bad-ı saba    : çokk hoş esen insana esenlik veren

 feyz veren  uhrevi duygular taşıyan rüzgâr.

Hışm      :   öfke, hiddet,gazap,kızgınlık.

Renç ber   :sıkıntı zahmet ber çeken tarla ve bahçede

Taş toprak işi ekme biçme kazma kürek işleri ile uğraşan 

Gündelükçi amele ırgat çiftçi.

Bağistan     : bağlık bakçelik yer', 'Gel her ne ile nasıl istersen onun ile gel Nerdesin diye sormam nasıl olduğun yeter İster bulut ister şimşek ister yağmur ile gel Gel ister ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-202-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kahvesi', 'ask-kahvesi-sahin-yilmaz-crepr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana bir kahve yap türkü tadında,

Kırk yıl değil, yüz yıl hatırı olur.

Meşhur olsun “aşk kahvesi” adında,

Kırk yıl değil, yüz yıl hatırı olur.

Sevdamızın ateşinde pişirsen,

Üzerine cemâlini düşürsen,

Gözlerime dalıp biraz taşırsan,

Kırk yıl değil, yüz yıl hatırı olur.

Cezvesini kinden uzakta tutsan,

Şekerin yerine tatlı dil atsan,

İçine birazda muhabbet katsan,

Kırk yıl değil, yüz yıl hatırı olur.

Fincan yoksa avucunda içerim.

Bir sigara yakar, zevkten uçarım,

Sana niyet tutar fal da açarım,

Kırk yıl değil, yüz yıl hatırı olur.

Göğsüne yaslansam seni yormadan,

Gönül bardağınla su ver, kırmadan,

Bir küçük öpücük kimse görmeden,

Kırk yıl değil, yüz yıl hatırı olur.', 'Bana bir kahve yap türkü tadında, Kırk yıl değil, yüz yıl hatırı olur. Meşhur olsun “aşk kahvesi” adında, Kırk yıl değil, yüz yıl hatırı olu...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-kahvesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Öfkem', 'sevgili-ofkem-omer-golge-fbhan', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öfkeler çocuklara benzer

Emek vermeden büyümez.

Birazda sevgi katmalıyız...

Bizi biz eden öfkemize

Yaşamın tam ortasında

Dimdikdururken.....

Solumaya çalışmak güzellikleri..

Öfkeyide almayı gerektirir yedeğimize.

Öfkemiz olmasaydı....

Nasıl haykırabilirdik....

Fırsatcının.hortumcunun.hainin

Tükürülesi yüzlerine.', 'Öfkeler çocuklara benzer Emek vermeden büyümez. Birazda sevgi katmalıyız... Bizi biz eden öfkemize Yaşamın tam ortasında Dimdikdururken........', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgili-ofkem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milenyum anneleri', 'milenyum-anneleri-mehmet-halil-8m9pj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Medya ve siyasi liderler

Yepyeni bir gelecek vadettiler

Bir gecede, bir saatte,

Hatta bir anda.

Her şey değişecek dediler.

Milyonlarca insanın kaderi 

bir gecede değişecekti.

Sanki herkesin cebinde 

büyük ikramiye bileti.

O gece uyku tutmadı kimseleri

Yanar yanmaz sabahın feneri.

Sokağa döküldüler,

Bir arayış içinde bütün gözler.

Bütün dünya duymuş da,

Tanrı duymamış, uyumuş o gece,

Ne defterine yazmış milenyumu,

Ne de görmüş rüyalarında,

Bir fırtına koptu,

Bilim adamları bile sustu.

Her şey bir bilmece.

Yarı uykulu,

Gözlerini uğuşturarak sokağa çıkmış biri

Bir değişiklik arayışı içinde…

Mutlu insanları, gülen gözleri

Arayıp durdu çevrede.

O da ne? 

El arabasıyla, bir seyyar satıcı,

Anlaşılan çocuklarının isteğine,

Onların,

Probaganda ile canlanan hayallerine,

Cevap verebilmek için,

Erken çıkmış o gün işine.

Arabasında 

dünden kalmış meyveler.

satıcıya aynı anda iki kişi yaklaştı.

Biri orta yaşlı bir bay

Diğeri 80’lik bir bayan.

Seyyar satıcı; 

Buyur anne dedi.

Anne ağırdan aldı.

Biraz durakladı,

Bir iki adım geri attı.

Seyyar satıcı diğer müşteriye baktı.

O da ‘’annenin işini gör’’ dedi.

Onun ayakta beklemesini istemedi.

Anne, ‘’sen al yavrum sen al’’ dedi.

Adam meyvesini alıp uzaklaşırken

Annenin sesini duydu.

‘’yavrum çok açım, bir tane ver ne olur’’

Seyyar satıcı meyveyi verirken,

‘’al hayır duası et..’’ dedi.

Bunu duyan adam dönüp, 

Anneye poşetinden iki meyve verdi.

Anne titreyerek ağlamaya başladı.

…………………..

rüyadan uyanmış gibiyiz

Kesildi bütün milenyum haberleri.

Her cilalı ambalajın içi,

Saatli bomba gibi…

Şimdi sokaklarda 

yüzbinlerce milenyum anneleri.

Bir de; 

Hala kayıp çocuklarını arayan

annelerin adını verdiği

hüzünlü cumartesi

kapanmıyor

kalplerdeki izleri.', 'Medya ve siyasi liderler Yepyeni bir gelecek vadettiler Bir gecede, bir saatte, Hatta bir anda. Her şey değişecek dediler. Milyonlarca insan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/milenyum-anneleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* KaR TaNeM *', 'kar-tanem-levent-nalcacioglu-c7hqm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kartanem



İlk dansımızda kar yağıyordu. 

Sen ve ben, 

Küçük, beyaz kar tanelerinde gizliydik. 

Güneş, gri bulutlara rağmen ortaya çıktı. 

İkimizin sevgisi, 

Milyonlarca, saniyelik, göz alıcı pırıltılarda... 

İlk dansımızı yapmıştık. 

Sevgilisinin yalnız bıraktığı kardelenin 

Bir yaprağına sen, diğerine ben kondum. 

Kardelen bekledi, bizde... 

Kardelen ağladı, bizde... 

Kardelen gitti, bizde... 

Ayrılık vakti geliyordu. 

Söz verdin kartanem, 

Bir daha ki karda dans edeceğimize... 

Hercai gibi olmamanı diledim. 

Ama oldu... 

Bir bahar çiçeğine tutulup, 

Nisan yağmurlarıyla gittin. 

O çiçeğe...Kartanem... 

İlk dansımızdaki pırıltılar yok, 

Güneş blie üzüntüsünden görünmez oldu. 

İçimin yangını beni eritmeye yetmedi, 

Kartanem. 

Senin yokluğunun soğukluğu yeterince dondurdu beni kartanem...', 'Kartanem İlk dansımızda kar yağıyordu.  Sen ve ben,  Küçük, beyaz kar tanelerinde gizliydik.  Güneş, gri bulutlara rağmen ortaya çıktı.  İki...', ARRAY['Türk Edebiyatı','Şiir','Levent Nalçacıoğlu']::text[], 8.5, '{"poet":"Levent Nalçacıoğlu","poet_slug":"levent-nalcacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kar-tanem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmuyor', 'sensiz-olmuyor-mehmet-bicik-t3qim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok üzdün gönlümü,

Aklımdan çıkmaz sözlerin..

Geçse de uzun yıllar,

Boş hâlâ kâlbimde yerin...

Issız gecelerde 

Apansız rüyama girersin..

Tam her şeyden 

El etek çekmişken

Seni özlerim...

Badem gözlerin gelir aklıma...

Sensiz bu gönlü 

Daha fazla yakma.

Her şeyi sineye çektim

Yolunu gözlerim...

Senle

Olmayacağını bilerek,

Senle olmak isterim yeniden...

Rüyalarımda da olsa

Tutmak isterim ellerinden...

Biliyorum,

Senle olmaz...

Anla artık! 

Sensiz de olmuyor...

26 Ağustos 2005, Burhaniye', 'Çok üzdün gönlümü, Aklımdan çıkmaz sözlerin.. Geçse de uzun yıllar, Boş hâlâ kâlbimde yerin... Issız gecelerde  Apansız rüyama girersin.. Ta...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensiz-olmuyor-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azap Diyarları', 'azap-diyarlari-ozer-senodeyici-fu5jl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Taş zemini yosun tutmuş zindanlarda,

Küflenir ışıklar köhne şamdanlarda,

Etten duvarlar; kemikten parmaklıklar...

Hapseder ruhumu bazı zamanlarda.

Nabzım şakaklarıma gülleler vurur,

Donmuş bakışlarımda güller savrulur,

Üç köşeli bir taş çöker boğazıma,

Bir köşesi aşk; 

Diğeri hasret; 

Öteki gurur...

Ufkuma gerilirken siyah perdeler,

Koşuşur sokaklarda uzun gölgeler,

Gölgeler...bir zamanın hoş hatırası...

Artık şuurumdan öte bir yerdeler! 

Çiğ taneleri düşer alnıma birden,

Kavrulur tenim ateş renkli nehirden,

Azap diyarlarını seyre dalarım:

Bu diyarların

Yeri tunçtandır

Göğü demirden...

İdrakimin hayata küstüğü yerde,

Ruhumun bedenimi astığı yerde,

Izdırab ülkesine koşar giderim; 

Ayağımın toprağa bastığı yerde!', 'Taş zemini yosun tutmuş zindanlarda, Küflenir ışıklar köhne şamdanlarda, Etten duvarlar; kemikten parmaklıklar... Hapseder ruhumu bazı zaman...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/azap-diyarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın Bir Gün Ayrılığı', 'anlarsin-bir-gun-ayriligi-gurcan-gunay-ze0jb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç ayrılık yaşadın mı ki dilinde bir gitmektir 

Pervasızca dökülüverir sancılı zamanlarda? 

Bilir misin ki ayrılık gün be gün eriyip bitmektir

Nedamet hissiyle buruk kör zindanlarda? 

Ellerimi özlemez mi ellerin bir gün olsun

Kim örter üzerini üşürsünde ayaz gecelerde

Yolumu gözlemez mi gözlerin akşam üstleri

Ayrılık hiç koymaz mı yalnız akşamlarda? 

Sıcacık bir tas çorbayı yalnız içtin mi hiç

Derin derin iç çekip kendinden geçtin mi hiç

Bilir misin nedir yalnız yürümek sokaklarda

İçini büsbütün kaplayan o kara hüzünle? 

Gördün mü kısacık ömründe sen hiç ayrılık 

Gitmek düşüncesi nasıl da avutur seni böyle? 

Hangi boş odalarda kiminle söyleşirsin

Yanmaz mı için geride bıraktığın bana hiç? 

Demek yine de gidiyorsun göze alıp herşeyi

Durma o zaman bir an bile canımın yarısı

Al bendeki seni haydi usulca çık kapıdan

Sendeki ben sende kalsın götür yanında

Sen beni kendinde yaşa ben sensiz ölürüm

Son bir sözüm var dilerim kalır aklında

Bir gün gelir sen de anlarsın elbet gülüm

Dediydi dersin ayrılığın diğer adı ölümdür...', 'Hiç ayrılık yaşadın mı ki dilinde bir gitmektir  Pervasızca dökülüverir sancılı zamanlarda?  Bilir misin ki ayrılık gün be gün eriyip bitmek...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlarsin-bir-gun-ayriligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Hasreti', 'kir-hasreti-cetin-ozyurek-xh0y3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kır hasretin zincirlerini

Kır gururunu

Haykır dünyaya

Sevdiğini

Utanma sevmekten

Korkma sevipte yıkılmaktan

Unutma hatırla hep

içindeki duygularını

Sen duygularına değil

Duyguların sana 

Hükmetsin

Doyasıya yaşa sevdayı', 'Kır hasretin zincirlerini Kır gururunu Haykır dünyaya Sevdiğini Utanma sevmekten Korkma sevipte yıkılmaktan Unutma hatırla hep içindeki duyg...', ARRAY['Türk Edebiyatı','Şiir','Çetin Özyürek']::text[], 8.5, '{"poet":"Çetin Özyürek","poet_slug":"cetin-ozyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kir-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-ozer-senodeyici-3wvxc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünce yol gözleyen toprağın kollarına,

Günleri gecelere aşkla ekleyeceğim...

Bedenim karışınca güllerin yaprağına,

Mezarımda güllerle seni bekleyeceğim! 

Her adımda yavaşça yaklaşacaksın bana,

Dökülen yaprak gibi süzüleceksin sona,

Ömrünce yürüdüğün yollar bittikten sonra; 

Yolların ötesinde seni bekleyeceğim!', 'Düşünce yol gözleyen toprağın kollarına, Günleri gecelere aşkla ekleyeceğim... Bedenim karışınca güllerin yaprağına, Mezarımda güllerle seni...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bekleyecegim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-ozer-senodeyici-8sj71', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göklerde yığıldıkça bulutlar bini aşkın,

Bir başka garîb etti bu akşam beni aşkın.

Ruhum da paramparça sürüklendi semâda,

Mehtâp sular üstünde durunca serenâda...

Ömrüm de akıp gitti bulutlarla bu akşam,

Öksüz bırakıp gitti umutlar da bu akşam...

Düştükçe karanlık göğün âvîzelerinden,

Sarsıldı felek kuşların âvâzelerinden! 

Solgun güneşi aksi sulardan çekilirken,

Meydanlara billur gibi yaşlar dökülürken; 

Ömrüm de akıp gitti bulutlarla bu akşam,

Öksüz bırakıp gitti umutlar da bu akşam...

Bir başka buruk battı güneş sanki ufuktan,

Bırakmadı nîşâne o mağrur ululuktan.

Her şarkı hüzünlüydü, bütün kelimeler boş! 

Asmâna nazîreydi gözümden boşanan yaş! 

Ömrüm de akıp gitti bulutlarla bu akşam,

Öksüz bırakıp gitti umutlar da bu akşam...', 'Göklerde yığıldıkça bulutlar bini aşkın, Bir başka garîb etti bu akşam beni aşkın. Ruhum da paramparça sürüklendi semâda, Mehtâp sular üstün...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-aksam-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufacık Bir Gülüş', 'ufacik-bir-gulus-cetin-ozyurek-3i7lq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufacık bir gülüştü senden beklediğim

Ufacık bir gülüş

Belki kendi dünyayım kapılarını

Açacak bir anahtardı gülüşün

Yeni bir hayatın başlangıcı

Yeni doğan bir bebeğin

İlk olarak dünyaya bakışıyıd

Belki ufacık bir gülüşün

Küsmüş olduğum bu hayata 

Yeniden sarılışımdı belki

Senin o tatlı gülüşün', 'Ufacık bir gülüştü senden beklediğim Ufacık bir gülüş Belki kendi dünyayım kapılarını Açacak bir anahtardı gülüşün Yeni bir hayatın başlangı...', ARRAY['Türk Edebiyatı','Şiir','Çetin Özyürek']::text[], 8.5, '{"poet":"Çetin Özyürek","poet_slug":"cetin-ozyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ufacik-bir-gulus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-ozer-senodeyici-1kqus', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kafes bülbül arıyor dallarda,

	Bülbül gül derdiyle öter yollarda,

	Yollar izini kaybetmiş yıllarda; 

	Bülbülüm, yollarım, yıllarım nerde?', 'Bir kafes bülbül arıyor dallarda, 	Bülbül gül derdiyle öter yollarda, 	Yollar izini kaybetmiş yıllarda;  	Bülbülüm, yollarım, yıllarım nerde...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilmece-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzluk', 'umutsuzluk-cetin-ozyurek-muy2n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamın karanlığı gibi geldi

Umutsuzluk ve mutsuzluk

Tüm duygularım kayboldu birden

Umutlarım ve mutluluklarım

Yaşamın kör noktası kaldı

Ellerimde yalnızlıklarımla

Paylaşmak istediğim duygularım

Umutsuzluklarımla beraber', 'Akşamın karanlığı gibi geldi Umutsuzluk ve mutsuzluk Tüm duygularım kayboldu birden Umutlarım ve mutluluklarım Yaşamın kör noktası kaldı Ell...', ARRAY['Türk Edebiyatı','Şiir','Çetin Özyürek']::text[], 8.5, '{"poet":"Çetin Özyürek","poet_slug":"cetin-ozyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umutsuzluk-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Kalbimdeki Sızımsın', 'sen-benim-kalbimdeki-sizimsin-huseyin-erdogan-67p0a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni öylesine özledim ki

çorak toprakların yağmuru

özlediği gibi...

seni sevince anladım ki

insan doğduğu şehirde bile

kendisini gurbette 

hissedebiliyormuş meğer

sevdiği yanında değilse eğer

beni sevindirmek istersen

bir gün bana çıkıp geliver

bil ki sıcacık bir yuvadır

sevenin  yüreği sevilen için

hem de ölünceye değin

yılın dört mevsimi

karakış olsa da

üşümesin asla

vallahi yanarsın adeta

kendini hissedersin

çöl sıcaklığında 

sevip seviliyorsan eğer

ellerini tutanın yoksa

Ağustos''un sıcağında bile

donar kalırsın bir köşede

sen benim kalbimdeki sızımsın

yüreğime tek kazıdığımsın 

ne olursun artık geliver de

gönlümdeki bahar solmasın

ömrüm sensiz dolmasın

                            26.08.2005', 'seni öylesine özledim ki çorak toprakların yağmuru özlediği gibi... seni sevince anladım ki insan doğduğu şehirde bile kendisini gurbette  h...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sen-benim-kalbimdeki-sizimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlanır Belki', 'canlanir-belki-hasan-gorgu-709vw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybetmemek için seni elini tuttum

Kalabalığa karıştın beni unuttun

Yeni açmış gül gibiydi bizim aşkımız

Yağmadı aşk yağmurları onu kuruttun

Tekrar canlanır mı bilmem biraz zor gibi

Ayrılık acısı beter yakar kor gibi

Gözyaşlarımla suladım ümit var gibi

Bir yağmurda sen yağdırsan canlanır belki', 'Kaybetmemek için seni elini tuttum Kalabalığa karıştın beni unuttun Yeni açmış gül gibiydi bizim aşkımız Yağmadı aşk yağmurları onu kuruttun...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/canlanir-belki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmeyen Bir Yerdesin', 'bilinmeyen-bir-yerdesin-seyfettin-bilal-ozluk-eqwbb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vakitsiz açan hercai çiçeği gibi

Hem yokluk hem de varlıksın

Uzakta bilinmeyen bir yerde

Ama her an içimde ve aklımdasın

Sen kimsin nesin

Kanatsız melek misin? 

Güneş her zaman yeniden doğar.

Bulut yoksa gökyüzünde; 

Ay her zaman yukardadır.

Yaşanacaksa yarınlar ne gecede ne gündüzde

Dünya da teksin

Ve bilinmeyen bir yerdesin...

Hep ulaşılmaz olacaksın

Varlığın belki hiç olmayacak

Ama o muhteşem sesin

İnsanın içini yakan o gülüşün

İçimde hep içimde

Derinlerde olacaksın.

Ama dedim ya

Sen uzak diyarlarda

Bilinmeyen bir yerlerdesin...', 'Vakitsiz açan hercai çiçeği gibi Hem yokluk hem de varlıksın Uzakta bilinmeyen bir yerde Ama her an içimde ve aklımdasın Sen kimsin nesin Ka...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilinmeyen-bir-yerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek İstemiyorum', 'olmek-i-stemiyorum-mechul-asik-qa435', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen artık git

Gelme bana

Ne olur

Daha fazla dayanamıyorum

Senin benim olmayışını

Hatta bir arkadaş zerresi kadar sevginin olmayaşını

Bu kalbim dayanamıyorum 

Seni böyle gördükce her dakika her saniye ölüme yaklaştığımın farkındayım

Ben yaşamak istiyorum

Artık gülmek istiyorum

Ben ben ölmek istemiyorum! ! !', 'Sen artık git Gelme bana Ne olur Daha fazla dayanamıyorum Senin benim olmayışını Hatta bir arkadaş zerresi kadar sevginin olmayaşını Bu kalb...', ARRAY['Türk Edebiyatı','Şiir','Meçhul Aşık']::text[], 8.5, '{"poet":"Meçhul Aşık","poet_slug":"mechul-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olmek-istemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Al Sensizliği..', 'gel-al-sensizligi-dilek-egri-q86o0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '../..gel al sevgili bir beden büyük sensizliği.../..

kimse bana bukadar zor olduğunu söylemedi

her gidenin gittiklerinden bir yarısını götürdüklerini

...filmlerde, 

........şarkılarda, 

.............şiirlerde yazılırdı

bir de Leyla''lı Mecnun''lu hikayelerde..

yediğim içtiğim bir tuhaftı bugün

dilimdeki tadı da mı alıp gittin nedir

in cin top oynuyor gözbebeklerimde

ne bir silüet, ne bir ışık

bakışlarımda senle gitmiş..

...............................................................................

başlamadan bitmeli diye bitirdiğim

özürlü hayal kırıklığımla üzmek istemediğim seni

şimdiden özledim! 

/..anla yakışmadı sensizlik üstüme

..............emanet durdu pişmanlığım../

kapıya kadar yolcu et sende ki bensizliği...

ardından çık gel,

gel ve al bendeki sensizliği! 

(25/08/2005)', '../..gel al sevgili bir beden büyük sensizliği.../.. kimse bana bukadar zor olduğunu söylemedi her gidenin gittiklerinden bir yarısını götür...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gel-al-sensizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır / Şiir Perisine', 'sabir-siir-perisine-i-brahim-usta-t93ow', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öfke ne kadar tatlı, sabır ne kadar güzel 

Kırıp dökmek bayağı, sabırsa ulvi bir el 

Ne kadar vazgeçsen de ne olursun yine gel 

Hedef kalpler olunca, başlara taçtır sabır.', 'Öfke ne kadar tatlı, sabır ne kadar güzel  Kırıp dökmek bayağı, sabırsa ulvi bir el  Ne kadar vazgeçsen de ne olursun yine gel  Hedef kalple...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Usta']::text[], 8.5, '{"poet":"İbrahim Usta","poet_slug":"i-brahim-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sabir-siir-perisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet, Bendim…', 'evet-bendim-tunahan-ermihan-bizgu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evet bendim, sesi soluğu kesilen

Ve yüzünden terleri tenine damlayan

Bendim evet dudaklarına her seferinde

Daha bir arzu ile öpüşler konduran

Seviyorum derken ağzından bir seviyorum daha çıkan

Ve herkeslerden çok seni kendime kadın belleyen

Bendim evet gece yarıları uykuya muhtaç günlerinde

Çıplak teninde fırtınalar koparan

Gidişinle hayalinden vurgun yiyen yine benim bebeğim

Konuşmak istediğim her anımda nefesi tükenen yine ben

Uzun bir tatmin anının ardından yığılıp kalan bedenlerimiz misali

Hatıralarla bir başına boşluktan aşağı düşen de ben', 'Evet bendim, sesi soluğu kesilen Ve yüzünden terleri tenine damlayan Bendim evet dudaklarına her seferinde Daha bir arzu ile öpüşler kondura...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/evet-bendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pop Şair', 'pop-sair-ozan-ozel-0sy77', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kalemimden kovduğum kelimeler

başka kalemlere düşmüş

yazılıvermişler mısralara

yazan eller popüler olmuş

pop şair olmuşlar

ve ben hariç

herkes şiirlerini okuyormuş

mış, muş... 

banane yaaa

www.erolayyildiz.tr.gs', 'kalemimden kovduğum kelimeler başka kalemlere düşmüş yazılıvermişler mısralara yazan eller popüler olmuş pop şair olmuşlar ve ben hariç herk...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/pop-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Gün Var', 'kac-gun-var-sahin-erturk-ukr1p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şen,şakraktı kahkahalar

İçten,sıcaktı insanlar

Kalbim bu günleri arar

Şiir,şölene kaç gün var? 

(26.08.2005-Yeni)', 'Şen,şakraktı kahkahalar İçten,sıcaktı insanlar Kalbim bu günleri arar Şiir,şölene kaç gün var?  (26.08.2005-Yeni)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kac-gun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail Kapıda', 'azrail-kapida-sahin-erturk-6u5ms', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle hiç bitmez sevda şarkımız

Yok Mecnun dan,Leyla dan hiç farkımız

Küllenmez artık hasret ateşimiz

Kavuşmamız hayel,zaman kalmadı

AZRAİL KAPIDA,zaman kalmadı

(26.08.2005)', 'Seninle hiç bitmez sevda şarkımız Yok Mecnun dan,Leyla dan hiç farkımız Küllenmez artık hasret ateşimiz Kavuşmamız hayel,zaman kalmadı AZRAİ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/azrail-kapida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözler', 'sozler-ozer-senodeyici-24v2q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ol yâr-i mihr-bânsın ki senin envârınla neşv ü nemâ bulur lâleler; 

Sen ol hûr u ziyâsın ki senin şevkinle mâhı sarar hâleler...

Sensiz bir hayâtın ânı ân mıdır! 

Sensiz bu bedende taşıdığım yük cân mıdır! 

Bahşettiğin huzûru dil mülkünde dâim kıl,

Gözlerimde cûş-ı harâret-i aşkı kâim kıl.

Sen olduğun için var etti beni Hudâ,

Elest bezminde seninle dedim belâ; 

Sen düştüğün gün dünyâya adım adım

Bana geldin de mâmur ettin bünyâdım.

Var mıdır bilmem ki cennette dahi eşin,

Bulunmaz bir eşi daha sen gibi meh-veşin.

Yaprak düşer, ışık solarsa ömrümde bir gün,

Biterse zamansızca fânideki sürgün,

O demde adını yâd ederek der-i hakîkatte,

Söylerim çektiğim çileyi şeb-i firkatte.

İhtiyâç olursa necâtım için bir vekîle,

İnan ki hasretin olur berâtıma vesîle.

Senden ayrı; bedenim sayrı, dostlarım gayrıdır; 

Senden ayrı, çektiğim çile ruhumun hayrıdır. 

Gel, gel benim sebeb-i hayâtım! 

Gel, gel benim imânıma âyâtım.

Seni bana getiren nesne tesadüf olamaz,

Tesadüfle bir yürek bu kadar dolamaz! 

Varlık seninle anlam bulur,

Anlam seninle ilhâm olur; 

Gözüm seninle açılır, kapanır; 

Cümle varlığım huzurunda secdeye kapanır.

Sen delâletsin benim için yaratıcıya,

Sen hem dert hem dermânsın içimdeki acıya.

Bilmiş yaradan kendi güzelliğini,

Sende fark etmiş yaratabildiğini; 

Bana bir çift göz, kalıba sığmaz söz vermiş; 

Secde-gâhım sen olunca hislerim göğe ermiş.

Bir durgun okyanus varmış her yanı çepeçevre saran,

Kalbimin ücra köşelerinden sonsuza uzanan,

Her zerresi aşka gelmiş, boğmuş sükûneti; 

Kaynatmış cümle mahlûkatı onun harâreti.

Birkaç damlası gözyaşım olmuş, kalanı kanımı kaynatmış,

İki dirhem bir aklı oynatmış da oynatmış...

O günden beridir ayakların yere basmadığı bir âlemde,

Olmayan nefeslerin alınıp verildiği her demde,

Yeryüzünde, mehtapta, denizde, her cânipte hem de

Bir elime güneşi bir elime ayı vermeyi vaad ederler de

Değişmem firkat gecesi çektiğim derde.

Elem olsun, keder olsun, hüzün olsun, melâl olsun; 

Sen sök kalbimi, şerha şerha et cismimi helâl olsun.

Sebil değil mi cismim senin yolunda,

Şehit olmaz mı ak pak ruhum senin kolunda? 

Kan kokusu değil mi gülden, nâle değil mi bülbülden? 

Azâd olsam tegâfülden, inler miyim bâr-ı tahammülden.

Ah! Ah ki kalbim yosun tutmuş duvarlara yaslanır,

Döktükçe kahrımı, taşlar benim kadar yaslanır.

Sorsan şimdiden sonra aşık değilim sözde,

Aşkın ta kendisi oldum hem cisimde hem özde! 

Rabbim seni getirmiş olmalı bana ki gönül uslansın,

Kızgın çölde akmayan iki çeşmem ıslansın.

Sen hem dersim, hem kitabım, hem kalemim, hem sayfam, hem uykusuz gecemsin; 

Çok mudur tavaf etsem seni; sen hem Kâbe’m, hem Merve’m, Hem Safâ’m, hem bâğ-ı İremsin

Kocaeli’m, Derince’m, umudum, Ankara’m, sevâbım, günâhım; 

Sensiz hakîr ve fakîr, âciz ve mecâlsiz, dermânsız ve îzânsız, bî-gâh u gümrâhım.

Seviyorum varlığımın en küçük parçasına değin; 

Seviyorum, duyacak kadar kanat seslerini bir kelebeğin. 

Akşamüzerlerine çöken hüznü tadıyorum,

Varlığımı da yokluğumu da aşkım adıyorum. 

Seni bana çok görmez ya hazret-i Yezdân,

Akıp geçmez ya seneler gibi aşkımız da aramızdan? 

Bilsem dönemeyeceksin, bilsem ki olmayacak bir başka vaad-i mülâkat

Olur mu bu canıma bilmem daha elîm bir felâket! 

Yâ Rabbi mebâd! Yok başka bir arzum! 

Yâ Rabbi mebâd! Onsuz kalr mı tadım tuzum! 

Açar mı acaba çiçekler eskisi gibi,

Kan tortusu tutmaz mı denizlerin dibi.

Gözlerim dalar mı ufka, eser mi rüzgâr arsız arsız,

Kalmaz mı fikrim ölmekle sevmemek arasında kararsız? 

Yaşanır mı ucu vuslat olmayan bir emelsiz? 

Dünya yine dünya olur mu çatısız temelsiz? 

Felek yine döner mi aşıkların başına belâ örmek üzere? 

Tüm hıncını yıktıktan sonra çâresiz Özer’e? 

Sevmek üzere bakmayan gözler kör olsun,

Sevgi dolmayan kalplere çakıl taşı dolsun.

Canım, kanım, ruhum, aşkım, öbür dünyâm, cihânım, Sultân’ım

Sevincim, umudum, intizârım, melâlim, hayâlim, gerçeğim, hüsrânım, isyânım!', 'Sen ol yâr-i mihr-bânsın ki senin envârınla neşv ü nemâ bulur lâleler;  Sen ol hûr u ziyâsın ki senin şevkinle mâhı sarar hâleler... Sensiz ...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/sozler-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam Yol Cehennem', 'tam-yol-cehennem-sahin-erturk-unyfn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hopladın,zıpladın MALI GÖTÜRDÜN

Açıldın,saçıldın MALI GÖTÜRDÜN

Yalanla,haramla MALI GÖTÜRDÜN

Dönülmez yoldasın,tam yol cehennem

(26.08.2005-Yeni)', 'Hopladın,zıpladın MALI GÖTÜRDÜN Açıldın,saçıldın MALI GÖTÜRDÜN Yalanla,haramla MALI GÖTÜRDÜN Dönülmez yoldasın,tam yol cehennem (26.08.2005-...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tam-yol-cehennem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delinin Aşkı', 'delinin-aski-ozer-senodeyici-nnkhu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğer bir damla yağmur gözüne kaçarsa,

Yakarım yerde gökte ne kadar su varsa! 

Eğer tek gül yürümene engel olursa,

Budarım hepsini dünyâ kel bile kalsa! 

Güneş, uykunu bölüp rüyâna girerse,

Söndürmeme engel olmaz âlemler gelse! 

Bülbüller senden izinsiz kanat çırparsa,

Kulun yakalar hepsini tıkar mahpusa! 

Aşığım, sevdi mi böyle sevmeli insan,

Sökülmeli kalpler, aşk dolmadan atarsa!', 'Eğer bir damla yağmur gözüne kaçarsa, Yakarım yerde gökte ne kadar su varsa!  Eğer tek gül yürümene engel olursa, Budarım hepsini dünyâ kel ...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/delinin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümüzü Dağtanlar Darman Duman Olsun', 'koyumuzu-dagtanlar-darman-duman-olsun-kamil-soylemez-ggaxz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaybolup,gitti gider kağını sesleri 

Emekçi özü sevgi zembili

Yakılıp,yıkıldı köyde evleri

Tarlalar,tevekler virane şimdi

Oysa tarım ülkesiydik

Şimdi dağıtıldık

Ne öküz kaldı

Ne de koyunumuz

Herşeyimiz hormonlu

Kanseröjenli

Yüzlerden yok oldu gülücükler

Sevgi kayboldu

Kanalınan yüzler şimdi sararıp,soldu

Neğ insanlık kaldı

Nede mertlik 

Her şeyimiz şimdi mezberelik

Baykuşlar tünemiş gör halimizi

Yok olmuş beşikler,çocuklar

Sokaklar bomboş oyunlar 

O güzelim ot kokusu yok 

Türküler yok

Gelinlik kızlar.erkekler yok

Köyler dağıtıldı 

Şehirler doldu yıkık virane bağdan 

Akmaz oldu akar sularımız dereler 

Dağdan

Gözyaşımız oldu acılar işkenceler 

Özledikte gidemedik parasızlıktan 

Virane olup,dağıldı bir bir insanlıklar 

Dos sohbeti yok artık tv çıkartılalı 

Köy konağı yıkıldı kaldı hatıraları 

Bak ses veriyor bir bir basamakları 

Yıkanlar yakanlar virane olsun 

Bizleri peşkev çekenler darman,duman olsun', 'Kaybolup,gitti gider kağını sesleri  Emekçi özü sevgi zembili Yakılıp,yıkıldı köyde evleri Tarlalar,tevekler virane şimdi Oysa tarım ülkesiy...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/koyumuzu-dagtanlar-darman-duman-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Bir Dert', 'garip-bir-dert-ozer-senodeyici-d889t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim yüzüm gülmez, gözüm ağlamaz; 

Ne biçim şairim Allah aşkına! 

Yâr yüzüme gülmez, gönlüm dağlamaz; 

Ne biçim bir aşk bu Allah aşkına! 

Toplayıp yaksam tüm şiirleri,

Kalbinin buzları erir mi bana? 

Söze gelmiyor ki aşkın sırları,

Ne biçim bir dert bu Allah aşkına! 

Sende mi, bende mi, aşkta mı kusur? 

Ne sende ne aşkta bulamam huzur...

Ama emret Özer ölmeye hazır,

Ne biçim âşığım Allah aşkına!', 'Benim yüzüm gülmez, gözüm ağlamaz;  Ne biçim şairim Allah aşkına!  Yâr yüzüme gülmez, gönlüm dağlamaz;  Ne biçim bir aşk bu Allah aşkına!  T...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-bir-dert-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Türkiye', 'bir-turkiye-nalan-kahraman-vab1j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuşların cıvıl cıvıl uçtuğu,

Ağaçların devrilircesine uzadığı,

Sokakların yalanırcasına temizlendiği,

Bir Türkiye''de yaşamak istiyorum.

Çocukların korkusuzca oynatıldığı parkların bulunduğu,

Ağzından bal akan ve uygulama ya geçiren politikicıların olduğu,

Eğitici ve dinlendirici televizyon,radyo yayınlarının olduğu,

Bir Türkiye''de yaşamak istiyorum.

Paramı har vurup,harman savurmadan,

Cebimin,cüzdanımın delikliğini hissetmeden,

Enflasyonun yörüngesini sabit bir yerde göreceğim,

Bir Türkiye''de yaşamak istiyorum.', 'Kuşların cıvıl cıvıl uçtuğu, Ağaçların devrilircesine uzadığı, Sokakların yalanırcasına temizlendiği, Bir Türkiye''de yaşamak istiyorum. Çocu...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-turkiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-ozer-senodeyici-cdv5w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin sihr-i helâldir bunu sâhir çekemez

Hamdülillâh kulun oldum müteşâ’ir çekemez

Öyle bir hamd ü senâ etti ki gönlüm gamına

Alnı harc olsa sücûd râhına şâkir çekemez

Evc-i sînâ-yı me’ânîde benim mazhar-ı nûr

Kim ki boş konuşur içi nâdân dışı mâhir çekemez

◊ ◊ ◊ ◊ ◊ ◊ 

Öyle korkar ezilir şi’r-i dehâmdan kimisi

Önce takdîr ederek ‘ilmimi âhir çekemez

Mahz-ı şi’r nâmına rûhumda çekilmiş çileyi

Ah ne Mecnûn u ne Ferhâd u ne sâir çekemez

Vaslî Bâkî olasın kubbede Gâlib diyeler

Dar olur zirvenin eyvânı misâfir çekemez', 'Gözlerin sihr-i helâldir bunu sâhir çekemez Hamdülillâh kulun oldum müteşâ’ir çekemez Öyle bir hamd ü senâ etti ki gönlüm gamına Alnı harc o...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gazel-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel (İstiğna Makamından)', 'gazel-i-stigna-makamindan-ozer-senodeyici-ywhc4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pîr-i dünyâyız çetin dağları aştıktan beri

Ā h-ı ‘uşşâktan feleğin çarkı şaştıktan beri

Lâne-i sîmurga çıkan râhı bizden sordular

Söyledik vâdî-i pür-mihneti aştıktan beri

Anılır ‘unvânımız mürşid-i kâmil olarak

‘Ā şığın ma’şū kunun peşinde koştuktan beri

Kalmadı ma’nâsı Leylâ’nın o günden sonra ki

Hâr ü zâr Mecnū n bu işret-gâha düştükten beri

Saf tutar müjgânı ve tahrîk-i zülfle saldırır

Gâlibiz kesrette ikrârla savaştıktan beri

Zulmetin semtinde birçok nev-heves oldu telef

Hızr-ı dânâ âb-ı hayvâna ulaştıktan beri

Gör ki Vaslî sırr-ı âşikârı duymak kâr değil

Kördür insân âb u kîl câna karıştıktan beri', 'Pîr-i dünyâyız çetin dağları aştıktan beri Ā h-ı ‘uşşâktan feleğin çarkı şaştıktan beri Lâne-i sîmurga çıkan râhı bizden sordular Söyledik v...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gazel-istigna-makamindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan Bayrakları', 'i-syan-bayraklari-ozer-senodeyici-51vyz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kükreyen şüphemle devrilmiş sütunlar,

Yıkık bir mabeddir önümde gördüğüm.

Tozlu levhalarda çürümüş kanunlar,

Vaadler safsata, düzen bir kördüğüm! 

Talandır ruhumun kutsal toprakları,

Çekilmiş surlara isyan bayrakları! 

Yokluğa göçüyor var olandan kaçan,

Kervanından kopmuş garip yitik benim...

Umduğunu bulsun keşfe yelken açan,

Yol gidenin olsun bu gölgelik benim! 

Talandır ruhumun kutsal toprakları,

Çekilmiş surlara isyan bayrakları! 

Çıkacak canlardan sonsuzluk beklenmez,

Bu âlemde sonsuz; çekilen elemdir...

Batacak gemiye hazine yüklenmez,

Bilmek baş ağrısı, cehalet erdemdir! 

Talandır ruhumun kutsal toprakları,

Çekilmiş surlara isyan bayrakları! 

İsyanım korkmuyor ateşli kuyudan,

Alıştım kılıçtan keskin köprülere...

Kaçıktır bahseden bir başka duyudan,

Gözle gördüğümü sarmam örtülere! 

Talandır ruhumun kutsal toprakları,

Çekilmiş surlara isyan bayrakları!', 'Kükreyen şüphemle devrilmiş sütunlar, Yıkık bir mabeddir önümde gördüğüm. Tozlu levhalarda çürümüş kanunlar, Vaadler safsata, düzen bir körd...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/isyan-bayraklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamam....', 'yasayamam-nurdane-diken-nuuuw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşığım sana, delin ben olurum. 

Toprağın suya, özlemi olurum. 

Güneşin aya, sevgisi olurum. 

Sensiz dünyada, inan yaşayamam.. 

Gönül bahçemin, gülüsün, goncasın. 

Seven kalbimin, baharsa dalısın. 

Seven bedenin, yaşayan nabzısın. 

Sensiz dünyada, inan yaşayamam.. 

Rüzgarla kokun, aşkı fısıldarken. 

Denizde sesin, bana seslenirken. 

Bende nefesin, beni yaşatırken. 

Sensiz dünyada, inan yaşayamam.. 

Senin delindim, zincirlerle koştum. 

Yeminler ettim, yeminimi tuttum. 

Selâm yolladım, selâmını aldım. 

Sensiz dünyada, inan yaşayamam..', 'Aşığım sana, delin ben olurum.  Toprağın suya, özlemi olurum.  Güneşin aya, sevgisi olurum.  Sensiz dünyada, inan yaşayamam..  Gönül bahçemi...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasayamam-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüme Nikâhladım...', 'gonlume-nik-hladim-i-brahim-ethem-bingul-jf2yg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerin dokunmasın tenime

Sonra kokun siner bedenime

Yüreğin koklasın yüreğimi

Aşkım bulaşsın benliğine...

Gözlerime duyurmadım sevgimi

Aşkımız nazara gelmesin diye

Saklarım tüm seslerden sevgimi

Sevgime başka söz sinmesin diye...

Aşkımı sırrıma bohçaladım

Kıymetini heder ederim diye

Gün oldu aşkımla sarmaş dolaştım

Gün oldu gizlendi, ulaşamadım

Yâr seni ebedî seveyim diye

Her saat orada göreyim diye

Ölürsem bu aşkla öleyim diye

Ben seni gönlüme nikâhladım...

www.iebingül.com', 'Ellerin dokunmasın tenime Sonra kokun siner bedenime Yüreğin koklasın yüreğimi Aşkım bulaşsın benliğine... Gözlerime duyurmadım sevgimi Aşkı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonlume-nikahladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefa...', 'vefa-nurdane-diken-iww70', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vefa çıkmış gökyüzüne. 

Salınışına baksana! 

İndirirsen yeryüzüne. 

Kimi çuvala kor, 

Kimi torbaya. 

Çözemezler onu, anlasana. 

Nalıncı keseri önlerinde. 

Yontarlar kendilerine. 

Döndürürler onu kendi, isteklerince! 

Vefa, ey vefa. 

Seni öldürdüler, bir kere. 

Salın gökyüzünde, 

Salınabildiğince. 

Gelme yeryüzüne, 

Bırak anlasınlar, seni. 

Vefasızlıklar, böyle varken, 

İnsanlar birbirlerini,öldürürken, 

Büyük, küçüğü 

Küçük büyüğü tanımazken, 

Sana ne kadar ihtiyacım var, bilsen. 

Yüzyıllar değişirken, 

Bir değişmeyen, ben miyim? 

Ey vefa! 

Ben hangi dünyadayım? .....', 'Vefa çıkmış gökyüzüne.  Salınışına baksana!  İndirirsen yeryüzüne.  Kimi çuvala kor,  Kimi torbaya.  Çözemezler onu, anlasana.  Nalıncı kese...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vefa-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum', 'unuttum-ozer-senodeyici-hewku', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unuttum cefan ile inlettiğin günleri...

Hatırımda hep bir gül bahçesinde,

Binlerce çiçek içerisinde,

Ruhumu teskin eden sesinle,

Şarkımızı söylerken varsın...

Yüreğimdeki ateşi söndürdü gözyaşım...

Şimdi orada yalnızca sen,

Bir engin deniz olup coşarken,

Solmuş rüyalarımı dirilten; 

Bir sabah rüzgarı gibi varsın...', 'Unuttum cefan ile inlettiğin günleri... Hatırımda hep bir gül bahçesinde, Binlerce çiçek içerisinde, Ruhumu teskin eden sesinle, Şarkımızı s...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unuttum-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkayaklar', 'kirkayaklar-ozer-senodeyici-2fwk9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biri, sol yanından delecek kefenini; 

Diğeri, yalayacak soğuk ellerini.

Çok çalışacaksın kurtulabilmek için,

Zalim bir kırkayak oyarken gözlerini.

Yalvar ki Tanrı’ya o gün yağmasın yağmur; 

Sulanmasın mezarın hiç, olmasın çamur.

Kırkayaklar hızlanır nemlenmiş toprakta; 

Deşerler göğsünü, kalbine yazık olur.

Ne geçmişin olacak ne de geleceğin,

Eziyet çekeceksin çürüyene değin.

Aç bir kırkayağın sofrası olacaksın; 

O zaman kırılacak, bükülmez bileğin! ! !', 'Biri, sol yanından delecek kefenini;  Diğeri, yalayacak soğuk ellerini. Çok çalışacaksın kurtulabilmek için, Zalim bir kırkayak oyarken gözl...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirkayaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyet', 'vasiyet-ozer-senodeyici-bn4fo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu dünyadan bir yiğit daha göçtü desinler,

Tanrı sevdi kulunu öyle seçti desinler,

Günahlar eşliğinde giriyorken mezara; 

Ne olur bir kez imama yalan söylesinler!', 'Bu dünyadan bir yiğit daha göçtü desinler, Tanrı sevdi kulunu öyle seçti desinler, Günahlar eşliğinde giriyorken mezara;  Ne olur bir kez im...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vasiyet-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SözHaline Gelememiş Harfler', 'sozhaline-gelememis-harfler-ozer-senodeyici-20h4l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elif, Lâm, Mim..

Ağır bir ilhamla eziliyor yüreğim.

Elif, Lâââm, Mim...

Sözleri parçalıyor dile getiremediklerim! 

Kainatın kaderi çözülüveriyor gözlerimin önünde.

Levh-i mahfuzda kayıtlı sırlar sığınıyor üç harfe:

Elif, Lâââm, Mim...

Haleb’in pazar yerinde yüzülüyor derim! 

Sırtlanıp varlığımı geçiyorum kapılardan,

Çırılçıplak bir aşkı taşıyorum utanmadan.

Rüzgar olup esiyorum,

Ateş olup yanıyorum,

İlkbahar yağmurlarıyla düşüyorum toprağa.

Yukardan bakınca bir oluyor bütün renkler,

Boğuluyor karanlıklar aşkın kızıllığında.

Hep aynı yöne savrulurken köhne felekler; 

Gözlerim, gerçeği keşfetmenin şaşkınlığında:

Elif, Lâââm, Mim..

Aşık benim, ma’şûk benim, yürek benim... aşk benim! 

Ruhumda bir gerçeğin doğum sancıları var,

Damarlarımda aşkımın dikenli telleri...

Bir yıkıma hazırlanıyor patlamak üzereyken tomurcuklar; 

Üç harfe sığınmış varoluşun gizemi:

Elif,Lâââm, Mim...

Elemdir, elemdir, elemdir benim kaderim,

İsyândır, galeyândır, feverândır kabullenişim! ! !', 'Elif, Lâm, Mim.. Ağır bir ilhamla eziliyor yüreğim. Elif, Lâââm, Mim... Sözleri parçalıyor dile getiremediklerim!  Kainatın kaderi çözülüver...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sozhaline-gelememis-harfler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşa Veda', 'yasa-veda-figen-aydogmus-xkqys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yıl daha geçti  kuytusundan hayatın 

Saman gibi savurup bedenimi rüzgara

Bir yıl daha avuçlarımdan uçtu

Gelmeksizin yarna

Son uykusuna daldı 30

Tarancı''nın 35''ine ramak kaldı

Nasılda acımasız yaşam

Nasılda kırbacını şaklattı

Eh bana müsade dedi30 yaş

31''e kapıyı açıp uzaklaştı

Daha 18 sanmıştım oysa 

19-20-21 ve diğerleri nasılda gözümden kaçtı

Akıllı sanıyordum kendimi

Demek Çocukluğum bana yanlış yaptı

31 hoş geldin

Bana hangi acıları üzüntüleri getirdin

Biraz gülüşte alsaydın yanına

acılar arasına serpiştirirdin', 'Bir yıl daha geçti  kuytusundan hayatın  Saman gibi savurup bedenimi rüzgara Bir yıl daha avuçlarımdan uçtu Gelmeksizin yarna Son uykusuna d...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasa-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..AllARA (öyle bir buse ki AllARA) ...', 'allara-oyle-bir-buse-ki-allara-serhat-ayan-dryyh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevdiğim Allara

öyle bir buse kondur ki yanağıma

patlasın içimin volkanik yüzü

ve lavları dökülsün

şakağımdan aşağıya

bu köhnemiş duvar gibi

önümde duruyor çatallı yolağzı

______hep tıkanık

______hep kapanık

çaresizim Allara

beni bana bağışla

alnımın çizgileri kalınlaşmış

gülen yüzüm eksilmiş

öptüğün kadar kalmışım Allara

eski bir çağdan geliyorum

tutku var aşk sandığımda

yalnızca bir defa olsun

kendini bana bağışla

sevdiğim Allara

utanıyorum yokluğunu ısıtmaya

.

.', 'sevdiğim Allara öyle bir buse kondur ki yanağıma patlasın içimin volkanik yüzü ve lavları dökülsün şakağımdan aşağıya bu köhnemiş duvar gibi...', ARRAY['Türk Edebiyatı','Şiir','Serhat Ayan']::text[], 8.5, '{"poet":"Serhat Ayan","poet_slug":"serhat-ayan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/allara-oyle-bir-buse-ki-allara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gâvur Kiraz Ağacı', 'g-vur-kiraz-agaci-hikmet-kavas-tr0bs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bütün kollarıyla

pencereme yaslanmış kiraz ağacı

bilmez miyim ne gâvur olduğunu

geçen gece yalvardım da

vermedin bir sarımlık olsun

kollarını ödünç

bazen öyle oluyorum ki

aciz ve gülünç

utanıyorum iki kolla sarmayı

seni gidi gâvur kiraz 

zibil gibi kolların olsa da

hiç sevdiğin olmayacak

saracak kadar yakında

ve bense

korkarım

idare edeceğim bu iki sıska çubukla', 'bütün kollarıyla pencereme yaslanmış kiraz ağacı bilmez miyim ne gâvur olduğunu geçen gece yalvardım da vermedin bir sarımlık olsun kolların...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gavur-kiraz-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimler Olsun', 'kimler-olsun-ozer-senodeyici-fke9x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günün doğuşunda bir hazırlık var,

Bir başka esiyor bugün rüzgarlar.

His dolu ruhumda bir hınzırlık var,

Kimler olsun şaşkın, ben olmayım da? ..

O masum bakışlar, o göz süzüşler

Simsiyah bir nakşı ruhuma işler

Aşkı haber verir gaipten kuşlar

Kimler olsun aşık, be olmayım da? ...

Bülbüller şakıyor sevda havası,

Hislerim sevdayla şüphe arası,

Bilmiyorum nedir bunun çaresi; 

Kimler olsun dertli, ben olmayım da? ..

		

Yine gökkuşağı, yine denizler...

Gündüz güneş inler gece yıldızlar,

İlhamımda bir de mahveden gözler; 

Kimler olsun şair, ben olmayım da', 'Günün doğuşunda bir hazırlık var, Bir başka esiyor bugün rüzgarlar. His dolu ruhumda bir hınzırlık var, Kimler olsun şaşkın, ben olmayım da?...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimler-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vahşet', 'vahset-ozer-senodeyici-s6phx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kan ekeyim yollarına, güller bitsin; 

Kırmızı halılar üzerinden gel bana! 

İki cihan aşkın destanını seyretsin; 

Emret, olmaz iki cihan engel bana! ! !', 'Kan ekeyim yollarına, güller bitsin;  Kırmızı halılar üzerinden gel bana!  İki cihan aşkın destanını seyretsin;  Emret, olmaz iki cihan enge...', ARRAY['Türk Edebiyatı','Şiir','Özer Şenödeyici']::text[], 8.5, '{"poet":"Özer Şenödeyici","poet_slug":"ozer-senodeyici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vahset-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Son Ağlamamdır', 'bu-son-aglamamdir-bahtiyar-arslan-ry2na', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iyi bak...

bu son ağlamamdır.

İzin ver,

izin verde

düşeyim gözlerinden...', 'iyi bak... bu son ağlamamdır. İzin ver, izin verde düşeyim gözlerinden......', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bu-son-aglamamdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yobaza Bakın', 'yobaza-bakin-suleyman-zaman-7xbmw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mülhidisin diyerek, sövdüler bana

Nice müfsit geldi- gitti bu hana

Rafızî dediler kıydılar cana

Kendini bilmeyen, yobaza bakın

Hacı-Bektaş hikmetiyle dolmuşum

Pir Sultandan feyzimi almışım

Mansur ile Enel-Hakka varmışım

Özünü görmeyen yobaza bakın

Bütünsel evrenin özünü bilmez

Özünde nefreti sonsuzca silmez

Kazanıp ta bir dost gönlüne girmez 

Düşmanca davranan yobaza bakın

O yaratmış gibi, verir fetvayı

Sorsan asla bilmez Güneşi Ay’ı

Yaşatmaz sevene, aşkı sevdayı

Hayatı zül sayan yobaza bakın

Tanımaz özün, atar cakayı

Uzak espriden, bilmez şakayı

Yükledi Zamanım’a nice belayı

Kendini bilmeyen yobaza bakın

                    15.06.2005', 'Mülhidisin diyerek, sövdüler bana Nice müfsit geldi- gitti bu hana Rafızî dediler kıydılar cana Kendini bilmeyen, yobaza bakın Hacı-Bektaş h...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yobaza-bakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel de Anla', 'gel-de-anla-murat-demir-ttdb0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hele bakın dostlar benim delime

Ağzına dolayıp birkaç kelime

Ziyade aklıyla, aklı selime

Vay zillet vay zillet vay zillet diyor

Kökünden bihaber yaprağı yanık

Durulmak bilmezken suyu bulanık

Alemin gülüne gelmişte anık

Vay illet vay illet vay illet diyor

Derdinin üstüne derdi koydukça

Yanardı daha dün, yokluk oydukça

Şimdi irfan ile karnı doydukça

Vay kafir vay kafir vay kafir diyor

Altında araba cepinde para

Belki uçaktayken yarın da sıra

Yine de bilgeye, bakın hınzıra

Vay gavur vay gavur vay gavur diyor

Kendisinden gayrı, herkesi yerip

Üstüne çöküyor post gibi gerip

Ele, el eliyle beslenen garip

Vay zındık vay zındık vay zındık diyor', 'Hele bakın dostlar benim delime Ağzına dolayıp birkaç kelime Ziyade aklıyla, aklı selime Vay zillet vay zillet vay zillet diyor Kökünden bih...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-de-anla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ahu', 'bir-ahu-elazigli-mustafa-kaya-f2lrg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'esir alır bir ahu gecelerimi 

gezinmelerim bundandır 

boynu eğik. 

bende aşk,anka kuşudur,

sonra dolunaydır,

geceyle oynaşan,

şafakla biten....

                                                  mustafa kaya

                                                  27.08.2005', 'esir alır bir ahu gecelerimi  gezinmelerim bundandır  boynu eğik.  bende aşk,anka kuşudur, sonra dolunaydır, geceyle oynaşan, şafakla biten....', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-ahu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanma', 'utanma-i-brahim-kilinc-sowm4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tel anlatıyorken aşkı, sevdayı

Gözünden dökülen yaştan utanma

Dil anlatıyorken son elvedayı

Gözünden dökülen yaştan utanma

Bu sevda ar değil inan gönüle

Bir sevda değermiş bin boş ömüre

Ümitsiz olsa da, verse de çile

Gözünden dökülen yaştan utanma

Görmek için yüzde bir tebessümü

Talipsen almaya derdi, hüzünü

Görünce uzaktan güzel yüzünü

Gözünden dökülen yaştan utanma

Hiç ayrılık olmayacak bu aşkta

Vuslat olmadı ki çünkü en başta

Beden karakışta, gönül ataşta 

Gözünden dökülen yaştan utanma', 'Tel anlatıyorken aşkı, sevdayı Gözünden dökülen yaştan utanma Dil anlatıyorken son elvedayı Gözünden dökülen yaştan utanma Bu sevda ar değil...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/utanma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi', 'hadi-caglar-demir-s50ug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey! ahali

Duyun beni

Anlayın

Yargılamayın

Ve istiyorum ki

Alın okyanuslarınızI

Bana Deniz''imi verin

Bogulacaksam bile onda bogulayım...', 'Ey! ahali Duyun beni Anlayın Yargılamayın Ve istiyorum ki Alın okyanuslarınızI Bana Deniz''imi verin Bogulacaksam bile onda bogulayım......', ARRAY['Türk Edebiyatı','Şiir','Çağlar Demir']::text[], 8.5, '{"poet":"Çağlar Demir","poet_slug":"caglar-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hadi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '= LEYLA = Bile...', 'leyla-bile-ayse-i-smetoglu-9ms95', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Leyla bile uyurken  ben seni düşünürüm..***

.................

Artık bedenler zindan, yürekler birer bodrum,

Leyla bile bulur  yol,  ben sende kaybolurum! 

__________________

kefelere koyup 

müddeti dolmuş endişelerimi 

tartarım, dengesiz! 

üstün bir ırk gibiydi, bendeki sen 

çabalarım elimden tutsa da 

ulaşmak, yetersiz! 

içimde büstü kurulur, bu ciğer yanığının 

sarar dört bir yanımı kokusu 

nergis nergis...

bil ki; şu coğrafyaları sarsan 

büyük aşkları bile küçük görür 

içimdeki kimsesiz..

kırılır belkemiğime dayanan inat 

kırılır törelerin cahil fayları 

çiğnenir ruhum, sensiz....

____________________

Aşksız! cansız bedendir, geri kalan cesedim,

Leyla bile yaşarken, ben ruhumu çiğnerim..! 



***  Bu dize Kevser adlı bir arkadaşıma aittir...bu şiiri o dizeden esinlenerek yazmıştım..\\ 2003', 'Leyla bile uyurken  ben seni düşünürüm..*** ................. Artık bedenler zindan, yürekler birer bodrum, Leyla bile bulur  yol,  ben send...', ARRAY['Türk Edebiyatı','Şiir','Ayşe İsmetoğlu']::text[], 8.5, '{"poet":"Ayşe İsmetoğlu","poet_slug":"ayse-i-smetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/leyla-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyada Düşün Beni', 'papatyada-dusun-beni-kamil-soylemez-094in', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinde düşün beni

Her kestiğin göz yaşında

İlk tuttuğun sevda fallarında

Papatyada düşün beni! 

Arzuların coştuğunda

Tenindeki yangınlarda

Öpüldüğünde düşün  beni

Dudaklarım dudaklarında

Aynada düşün beni 

Süslerken yerine yüreğimi

Göz kırpmalarında düşün 

Sana yangın yeri yüreğimi

Yutmak isteyipte yutamadığın lokmalarda

Düşün beni düşün ki suyun olayım

Sana gem vurulan zincirleri kırayım

Burukluklarda düşün beni

Martı çığlıklarında

Geceyi öperken ay ile yıldızlarda

Anadoluda bir köy pınarında düşün beni

Avuç avuç içtiğim seni

Çığlık çığlık anne kuşta düşün

Çatlayan yumurtada

Öptüğüm anne sevgimde düşün beni

 Maden ocağında....

Zeytin gözlerimi düşün, karanlıkta

Yüreğimi düşün sana nasıl yandığını

Dünya çekirdeğinde düşün

Bin altıyüz santigırat larda, kalbimi

Çocukluğun da düşün beni

İlk aşık olduğun yürekte

Düştüğün yerde düşün beni

Damlayan yaşlarda

Senin yerine ağladığımı

Çekip hançeri sende beni yaraladığımı

Sensiz seninle geçen zamanı

Yaktığım sigarayı düşün

Dalgınlıkla yaktığım dudaklarımı

Gelmeyişlerinde ki sancıda düşün beni

Çekip çıkarttığım pc de

Yangın yerinde düşün beni

Har,har sana yandığımı

Her baktığın yerde 

Sana gülerek baktığımı

Sevgini gör tan yerinde

Sende kalan aklımı yüreğinde

Düşün ki özüne ulaşayım

Özüm diye sana çılgınca akayım', 'Gözlerinde düşün beni Her kestiğin göz yaşında İlk tuttuğun sevda fallarında Papatyada düşün beni!  Arzuların coştuğunda Tenindeki yangınlar...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/papatyada-dusun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Çeşmenin Tatlı Suyu', 'kucuk-cesmenin-tatli-suyu-rifki-kaymaz-xm8zs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çeşmeden şırıl şırıl

	Nereye koşuyorsun? 

	Kimsecikler yokken yanında,

	Susuyorsun.

	Ama,

	Eğilip avuç avuç

	İçince coşuyorsun.

	Susuzluktan ağzın kuru.

	Koşup yanına gelince,

	İki kardeş gibi özlemle,

	Elimi, yüzümü 

	Ve sonra 

	Yüreğimi okşuyorsun.

	Kim bilir kaç yıldır böylesine,

	Hiç bitmez türkülerle seslendiğin...

	Ağaca, toprağa, çiçeğe.

	Bana ümit ve mutluluk,

	Onlara kan taşıyorsun.

	Bir elin kaynaklara uzanmış,

	Arkanda kır çiçekleri.

	Yanı başında  ağaç, bahçede meyve,

	Az ötede şu oynayan çocuklar...

	

	Dostça, kardeş kardeşe,

	Ne güzel yaşıyorsun!', 'Çeşmeden şırıl şırıl 	Nereye koşuyorsun?  	Kimsecikler yokken yanında, 	Susuyorsun. 	Ama, 	Eğilip avuç avuç 	İçince coşuyorsun. 	Susuzluktan...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kucuk-cesmenin-tatli-suyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-osman-kilic-yx6fg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eskiler, severmiş sadece

Konuşmadan sevda üzerine..

Ve biz onların ters aksiyiz sanki,

Her cümlemizin medyanı aşk

Bu korkutur beni işte

Tarihin bir yerine,

Ayna mı konmuş yoksa? 

Bu kadar düşünmezdim inanın,

Bir ayna da arkamızda olsa..

12.09.03', 'Eskiler, severmiş sadece Konuşmadan sevda üzerine.. Ve biz onların ters aksiyiz sanki, Her cümlemizin medyanı aşk Bu korkutur beni işte Tari...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayna-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınımsın!', 'kadinimsin-sadi-yilmaz-oc46s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim aşkım, benim kara sevdam,

Kadınımsın! 

Benim kanım, benim canım,

varlığımsın! 

Susamış gönlümün yağmuru,

Issız dağlarımın ıslığı,

Hasta kalbimin çınarısın! 

Sar dallarını benliğime,

Başka güneşler ruhuma sızmasın! 

Olsun! onurudur, bırak da ben aşığın,

Sana bağımlı yaşasın! 

Arada bir de kucakla onu,

Yazıktır, fakir oyalansın! 

İnsanlar bu sevdayı birbirine anlatsın! 

Sevdiğime göz koyanlar,

Çatır çatır çatlasın! 

Mudurnu - 2005', 'Benim aşkım, benim kara sevdam, Kadınımsın!  Benim kanım, benim canım, varlığımsın!  Susamış gönlümün yağmuru, Issız dağlarımın ıslığı, Hast...', ARRAY['Türk Edebiyatı','Şiir','Sadi Yılmaz']::text[], 8.5, '{"poet":"Sadi Yılmaz","poet_slug":"sadi-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kadinimsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki Ben', 'bil-ki-ben-cigdem-altinoz-vgkae', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle sen olmanın ötesinde

Bölük pörçük anıların sarhoşluğu

Kaplarsa benliğimi

Bil ki ben

Bende değilim

Yaşamın her zerresini

Su gibi içiyorsam aldırmadan

Dudaklarım kavruluyorsa

Adını anarken

Özgürce tutuyorsam ellerini

Bil ki ben

Seviyorum

Karanlıklarla gelen hayaller

Gündüzleri kaplarsa benliğimi

Açık saçık sözler söylüyorsam

Ve kırık dökük birkaç satır

Okuyorsam

En olmadık yerde

Bil ki ben

Bende değilim

Seninle

Sen olmanın ötesinde

Seviyorum', 'Seninle sen olmanın ötesinde Bölük pörçük anıların sarhoşluğu Kaplarsa benliğimi Bil ki ben Bende değilim Yaşamın her zerresini Su gibi içiy...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bil-ki-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Küçük Fidanlar', 'biz-kucuk-fidanlar-rifki-kaymaz-v0hvy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz, yeşil bahçenin küçük fidanları,

	Gün gelince dal dal büyüyeceğiz.

	Gölgemizde oturup dinlenenlere,

	Büyük büyük ağaçlardan duyduğumuz, 

	Masallar söyleyeceğiz.

	Biz küçük fidanlar, her gün dinleriz,

	Büyük ağaçların anlattığını...

	Ferhat’la Şirin’i, Battal Gazi’yi,

	Tilkinin kargayı aldattığını.

	Bir rüzgar esiverir birden,

	Bükülürüz, kırılırız, ah deriz.

	Uzanır dallarıyla büyük ağaçlar,

	Tutup kaldırırlar ayağa bizi,

	Teşekkürler ederiz.

	Büyük ağaçlardan öğrendik elbet,

	Büyük ağaç olmayı, meyve vermeyi...

	Bizden küçük, bizden körpe  fidanlara,

	Kol kanat germeyi...', 'Biz, yeşil bahçenin küçük fidanları, 	Gün gelince dal dal büyüyeceğiz. 	Gölgemizde oturup dinlenenlere, 	Büyük büyük ağaçlardan duyduğumuz, ...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/biz-kucuk-fidanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsam', 'olsam-cigdem-altinoz-r3fwd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buğday olsam

Avuç avuç savursan

Çorak topraklarına.

Yeşillensem.

Elin cebinde

Bir tepeden seyretsen

Rüzgarla büküldüğümü

Dansıma gelsen.

Başak olsam

Yeşil , dolgun

Bir türkü tuttursan

Yansa bağrım.

Olgunlaşsa tanelerim.

Sevginin bereketiyle

Sararsam 

Harmanıma gelsen.

Keklik olsam

Kuytu kayalıklarda.

Sabahın alacasında

Rüyalara yenik düşmüşken

Kapında şakısam.

Uyansan.

Elinde, bir avuç buğday

Savursan rüzgara karşı.

Uyansan

Ah bir uyansan

Açlığıma gelsen.

Kalem olsam

Yazılmamışı yazan.

Ellerinde kırılsam.

İdam hükmünde gibi.

Doymadan seni yazsam 

Destan destan

Çizsem senin kaderini

-	ki kaderime eş.

Doğmamış cümlelerde

Bulsam seni

Şiirime gelsen.

Kitap olsam

Okusan usul usul

Her satırda 

Yeniden bulsan

Sevgimin yüceliğini

düşürmesen elinden

Başucundan ayırmasan

Huzuru bulsan varlığımda

Kelamıma gelsen

Çiçek olsam

Koksam her dem

Yakana taksan beni

Vazonda kurusa bile duran

Rengime vurgun

Kokularıma mest

Bülbül misali yanık

Bahçeme gelsen

Hasta olsam

Haberler salsam sana

Ateşlere

Kör ateşlere yansam

Suyuna muhtaç.

Soğuk terler

Yaksa gözlerimi

- ki o gözler uykuna hasret.

Ölüme yenilirken çaresiz.

Dermanıma gelsen

Ağaç  olsam

Gölgemde şenlense çocuklar

Yaşlansam 

Sevginin sonsuzluğunda

Oysalar biçim biçim

Beğendiğin ustalar.

Koysalar evinin köşeciğine

Al örtüler serseler üzerime

Başucumda çıngırak

Ve mavi boncuklarla bezeli

Beşiğime gelsen

Dağ  olsam

Yüce yüce

Beyazlara kesse başım

Dumanlar içinde

Mor akşamlar olsa üstüme

Yeşillerimde kuzular melese

Kavalını çalsa çobanlar

Yanık yanık

Eteğime gelsen.

Ateş olsam

Dumansız.

Ormana,çiftçiye dost.

 Anadolu’mun

Ayazında gezinirken

Ve bakarken

Güneşin battığı yere doğru

Üşüsen yokluğumda

Titreyerek

Ocağıma gelsen.

Su olsam

Çağıl çağıl

Aksam kayalıklardan

Ceylanlar dolaşsa pınarlarımda

Bülbüller figanda

Güller tarumar

Yansan kor ateşler gibi

Günahının sıcağından

Kaynağıma gelsen.

Kumaş olsam

Dallı,güllü,allı,morlu

Dikseler 

Nasırlı elleriyle Köyünün kadınları.

Koyunların sıcağından

Lif lif etseler yünü

Doldursalar bağrıma

Alsam içime

Sevginin sıcağını.

Gözlerinde 

Uykunun sarısı,koyusu

Döşeğime gelsen

Ana olsam

Anadolu gibi

Asena gibi

Açılsa kollarım kocaman

Bolluğum,bereketim

Süt dolmuş memelerim

Açlığında sızlar durur

Savunmasız

Korunmasız

Azıksız 

Ve anasız olsan

Kucağıma gelsen.

Gelin olsam

Avuçlarımda 

Mis kokulu kınalar.

Davullar vursa gümbür gümbür

Gençler deli dolu

Halaylar çekseler akşama dek.

Kadınlar

Ağlatan türküler söyleseler.

Tepsilerce yemişler saçılsa avuç avuç.

Mor dağlara yayılsa

Kavalın yanık sesi.

Başıma parlayan teller taksalar

-	ki kör karanlıklarda göresin diye

Belimde kızıl kuşak

Alnımda  sarı liralar dizili.

Yüzüme ak örtü serseler

Ve deseler ki; 

Seni seven açacak bunu

Ahh... 

Duysan da

Düğününü,toyunu

Yaşmağıma gelsen.

Duvağıma gelsen

Toprak olsam

Üstünde gezindiğin

Bağrımda taşıyarak her çileyi

Ezilen,hor görülen.

Kah bin bir lezzette yemiş,

Kokladığın kır çiçeği

Kah  yediğin ekmeğin.

Bereketin olsam.

Yangınınla

Yarılsam pare pare

Bir kat re suya hasret

Yağmurunda Rabbımın

Koksam burnuna.

Buram buram.

Beklesem seni

Yüzyıllar boyu

-	Güneşe,rüzgara inat

Bir gün

Huzurla uzansam

Bir selvi altına

Seriliversem kapkara

Üzerimde

Adı bilinmez otlar bitse

Ve güvercinler dolaşsa

-	Kara kargalara inat

Çağırsam seni

Selalarla

Ezanlarla.

Açılan avuçlarında

Sevenlerinin. 

Dualarla uğurlansan bağrıma

-ki hasretinle yanmaktadır amansız.

Mezarıma gelsen.', 'Buğday olsam Avuç avuç savursan Çorak topraklarına. Yeşillensem. Elin cebinde Bir tepeden seyretsen Rüzgarla büküldüğümü Dansıma gelsen. Baş...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":184,"source_url":"https://www.antoloji.com/olsam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplaşma', 'hesaplasma-rifki-kaymaz-rgf16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir iç hesabına dalıver artık,

Doğruyu, güzeli alıver artık.

Alıp hakikatten sönmez ışığı,

Huzur deryasında kalıver artık.', 'Bir iç hesabına dalıver artık, Doğruyu, güzeli alıver artık. Alıp hakikatten sönmez ışığı, Huzur deryasında kalıver artık....', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hesaplasma-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Ağlar mı?', 'oluler-aglar-mi-cigdem-altinoz-fu7t6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşarken

Zamanın akışında korkusuz

Severken, sevilirken,

Gülerken,

Üzülürken,

Sevgisizken,

Beklerken,

Bekletirken bilerek.

Özlerken

Özletirken insafsız.

Yalanlarla boğuşarak

Kendisiyle oynarken

Ya da oyun sanarak hayatı

Keşfederken telaşsız.

Düşünmezken gitmeyi

Akla gelmezken ölüm.

Durursa birdenbire

Kopsa zamanın ipi

Ölüler şaşar mı? 

Bakıp da bekleyenlere

Bir musalla taşından

Kimi gözde yaş

Kiminde yalan hüzün

Bir köşede sevenler

Diğerinde yerenler

Görüntü olsun diye

Saflarda görünenler

Tanıdık bildik yüzler

Bir telaş, bir kalaba

Bir namaz ve bir dua

Bir helallik dileme

Çıkılan son yolculuk

Sonunda sona varış.

Bakıp da bu işlere

Şaşırıp bir an bile

Kimdir bu giden diye

Ölüler sorar mı? 

Dokununca beden toprağa

Isınmasız,

Savunmasız

Kör karanlıklar içinde

Yapayalnız ve soğuk,

Bilinmez bir diyarda

Duyulmaz çığlıklar atar mı? 

Kapanınca gözler

Hiç açılmazcasına

Nefes nefes açan can

Uçarsa kuşçasına

Solarsa renk

Batan güneş hüznünde

Ölüler ağlar mı?', 'Yaşarken Zamanın akışında korkusuz Severken, sevilirken, Gülerken, Üzülürken, Sevgisizken, Beklerken, Bekletirken bilerek. Özlerken Özletirk...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/oluler-aglar-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-alaattin-ceylan-ao3u1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yanımdayken

İçim içime sığmıyordu

Her şey o kadar güzeldi ki

Her mevsim baharı yaşıyordum sanki

Yüzünün halesi aydınlatıyordu odamı

Gözlerinin pırıltısı,çılgın kahkahaların,

Teninin sıcaklığı,deli dolu konuşmaların,

Su kadar temiz kalbinle

Mutluluk kaynağımdın benim

Sen yanımdayken kederi hiç tanımadım

Hiç bir şey meşgul etmedi beni

Dağ kadar güçlü hissediyordum kendimi

Ne ev,araba sevdam vardı ne de zenginlik

Beni mutsuz eden hiçbir şey yoktu

Hayat olabildiğince sade ve huzur doluydu

Âşık da değildim sana ama

Varlığın ne kadar önemliymiş yanımda

Neden kaybedince anlaşılır bütün güzellikler

Nerden çıktı bu ayrılık bu gitmeler

Hiç tanımadığım hüzünle karşılaştım yokluğunda

Bensiz olamayacak kadar bağlıdır bana

Ayrılmaz ikiliyiz anlayacağın

Hiç sevmediğim, 

Aşk ve ayrılık şarkıları dinliyorum şu anda

Nedendir bilmiyorum

Sevdiğimi de söylememiştim sana

Affet farkında da değildim

Bir gün döner de gelirsen bana

Seni seviyorum diyeceğim sana', 'Sen yanımdayken İçim içime sığmıyordu Her şey o kadar güzeldi ki Her mevsim baharı yaşıyordum sanki Yüzünün halesi aydınlatıyordu odamı Gözl...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Ceylan']::text[], 8.5, '{"poet":"Alaattin Ceylan","poet_slug":"alaattin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seni-seviyorum-282-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gider', 'gider-rifki-kaymaz-above', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yollar kıvrım kıvrım bükülür gider

Acılar, özlemler, dökülür gider

İnsan çilelerle yoğrulur her dem,

Ölüm ötesine sökülür gider.', 'Yollar kıvrım kıvrım bükülür gider Acılar, özlemler, dökülür gider İnsan çilelerle yoğrulur her dem, Ölüm ötesine sökülür gider....', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gider-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-cigdem-altinoz-5219b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yatıyordun

Gözlerinde korkular

Ak çarşaflar içinde

Rengin onlardan ak.

Taş oturdu yüreğime

Taş.

Yatıyordun

Öylece, sessiz, sakin.

Serin çarşaflar üstünde

Boşluğa bakıyordun.

Kahroluyordum.

Filmler geçiyordu gözümden.

Bana ilk sarılışın,

İlk öpüşün,

İlk gülüşün

Dünyayı ilk görüşün.

Sarıyordum makarasını filmin.

Bu sefer ilk adımı atıyordun.

Öğrenirken yürümeyi düşerek.

Açılmış kollarım 

Kocaman kocaman.

Bana doğru koşuyordun.

Bundan 

Yıllar önce

Ak önlüklü kızlara

Açmıştın gözlerini

Alışıktın onlara

Korkmuyordun.

Oysa ben.

Ah bir bilsen...

Korkudan geberiyordum

Başında doktorlar

Başında serum şişeleri

Sen uyuyordun

Ağlıyordun

Sonra yine uyuyordun.

Bense, ölüyordum.

Filmin bir başka karesi.

Denize giriyordun.

Biz, ikimiz.

Bir de deniz.

Biz dondurmayı da severiz.

Yatıyordun.

Kapalıydı gözlerin

Rengin beyaz.

Çarşaflardan da beyaz.

Yüreğime kuşkular doluyordu.

Boş vererek güçlülüğe.

Ağlıyordum.

Bazen aralanıyordu gözlerin

Sonra kayıyordu boşluğa

İçimde isyan.

Sana sesleniyordum

Duymuyordun.

Öylece

Sakin, sessiz

Serin çarşaflar üstünde

Yatıyordun.

Rüzgarlar esiyordu yüreğimde

Deli rüzgarlar

Ciğerlerim patlayacak sanıyordum

Sessizce

Ağlıyordum

Sen, uyuyordun.

Saatler geçiyordu

Zamandan çalarak

Gelenler oluyordu

Gidenler oluyordu

Sen uyuyordun.

Ne sessiz feryadımı

Ne sevda şarkımı 

Duymuyordun.

Derin, dipsiz kuyulara çekilir gibi

Boşluklara kayıyordun.

Gitme diyordum,

Gitme

İçim çığlık çığlık...

Gitme.

Sana ulaşamıyordum bir türlü

Hani rüyalarda olur ya...

Uzanırsın 

Tutamazsın

Koşmak ister,

Çakılırsın.

Seslenirsin 

Sesin çıkmaz hani...

Usul usul gidiyordun.

Çarşaflar serin

Ellerin daha serin.

Saatler geçiyordu

Ömrümüzden çalarak

Dışarıda kara bir gece

Hükmünü sürmekte zamanda

İçim geceden kara

Sabah olmak bilmiyordu

Belki de

Bana öyle geliyordu

Belki sen uyudukça

Sabahlar bile karaydı.

Çırpınsa içindeki kuş

Mavilere kanat açarak

Karalara inat

Köpürse dalgalar

Bembeyaz

Dallar yeşillense

Çiçekler açsa yüzünde

Solgun benzine inat

Saatler geçiyordu 

Beni benden çalarak

Zaman,

Acımasızca geçiyordu.

Benden seni çalarak.

Gözümde yaşlar

Hayalimde filmler tükeniyordu.

Gelenler, gidenler oluyordu

Sen uyuyordun

Giderek daha derin

Sanki

Hiç uyanmayacak gibi

Sana sesleniyorum sevdiğim

Karabasanlara döndürme

Rüyalarımı, hülyalarımı

Aç gözlerini

Ses ver yüreğime

Ne olur, ne olur

Gitmeeeeeeeeeeeee..', 'Yatıyordun Gözlerinde korkular Ak çarşaflar içinde Rengin onlardan ak. Taş oturdu yüreğime Taş. Yatıyordun Öylece, sessiz, sakin. Serin çarş...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":126,"source_url":"https://www.antoloji.com/kizima-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebedi Sevinç', 'ebedi-sevinc-rifki-kaymaz-kc1st', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsana son toprak, “kara toprak”tır.

Mezarsa, dökülen, solan yapraktır.

İyiyle,  doğruyla, güzelle dolan,

Ebedi sevinçle yıkanacaktır.', 'İnsana son toprak, “kara toprak”tır. Mezarsa, dökülen, solan yapraktır. İyiyle,  doğruyla, güzelle dolan, Ebedi sevinçle yıkanacaktır....', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ebedi-sevinc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Dönene dek...', 'sen-donene-dek-cigdem-altinoz-omkko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kendime söz verdim

Biliyorsun

Kaybetmeyeceğim yüreğimi

Hani

Sevdalara tuz basan bir şiir var ya

İşte öyle...

Tuz basacağım yaralarıma

Sen dönene dek.

Sen dönene dek

Dostlarımın rüyalarına

Gülüp geçeceğim

Sabah hayırlarına yoracağım

Çok kereler.

Kendi rüyalarımı ise

Kendime saklayacağım

Sen dönene dek.

Yitmesine izin vermeyeceğim

Güçlülüğümün

Korkularıma tuz basacağım bu kere.

Hele akşamın kör alacasında

Yapayalnızken

Büyüyen korkularımın.

Sen gelene dek

Şarkılarım olacak yüreğimde

Oynak,kıvrak,

Şen şakrak değil belki

Hüzünlü, ağırbaşlı

Kim bilir...

Ama güzel şarkılar olacak

Besbelli.

Sen dönene dek

Kuşların kanatlarına

Takılacak gönlüm.

Seyredecek dünyayı mavilerden

Senden haberler bekleyerek

Kuş misali

Titreyerek

Sen gelene dek,

Kötü düşünmeyeceğim

Kara bulutlar

Olmayacak beynimde.

Söz verdim bir kere,

Beyaza kesecek

Yüreğim.

Sen dönene dek

Şiirler yazacağım aşka dair

Yağmurlar olacak içinde

Rüzgarlar olacak.

Ve güneş doğunca

Yeniden

Gökkuşağı çıkacak diye

Bekleyeceğim.

Sen dönene dek

Alışveriş yapacağım

Çay içeceğim çok kez.

Müzik dinleyeceğim

Yemek yiyeceğim.

Uyuyup, uyanacağım

İş de yapacağım elbet.

İşe de gideceğim.

Geceler olacak

Sabahlar olacak

Fırtınalar olacak.

Korkular,

Ümitsizlikle savaşacak.

Parasız kalacağım.

Çaresiz kalacağım.

Zorda kalacağım

Anlayacağın.

Kızma sakın...

Bazen ağlayacağım.

Çok değil be gülüm.

Sen dönene dek.

Sen dönene

Sen.', 'Kendime söz verdim Biliyorsun Kaybetmeyeceğim yüreğimi Hani Sevdalara tuz basan bir şiir var ya İşte öyle... Tuz basacağım yaralarıma Sen dö...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/sen-donene-dek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekişme', 'cekisme-sait-kucuk-xsuov', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'doğru:

-kul dilinde

 allah''ın düşmanı

 ilan edildin

 n''aber

yalan:

-senin kovulduğun köyde

 ben baştacıyım

 senden

 n''aber', 'doğru: -kul dilinde  allah''ın düşmanı  ilan edildin  n''aber yalan: -senin kovulduğun köyde  ben baştacıyım  senden  n''aber...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cekisme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yağmurum', 'ben-yagmurum-cigdem-altinoz-79v42', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kararır gökyüzü ansızın, 

Çarpar bulutlar kahrederek, 

Ve bir ateş yanar... 

Bulutlar yanar, 

Yürek yanar. 

Sonra tek tek düşer damlalar, 

Toprak kokar, 

Yağmur kokar. 

Bir ateş yanar rüzgarında, 

Bin ateş söner. 

Ben yağmurum 

- gününe ve gecene yağan. 

Kararırsa bulutların ansızın, 

Ve şimşekler çakarsa özünde, 

Bak gözündeyim. 

Önce tek tek, 

Sonra sel olurum göğsüne... 

Aydınlanırsa yüreğin, 

Güneşler açarsa yüzünde, 

Neşeyim şimdi özünde. 

Yürürken bahtının yollarında 

Yalnız ve dalgın, 

Ve görürsen açmış

Bir dal çiğdem 

 -üzerinde çiğ damlası. 

O, benim.

Sabahları dağılırken bulutlar 

Yürüyorsan sokaklarda 

Düşünüyorsan 

Nisan yağmurlarını 

Havayı kokla 

O, benim. 

Ararsa ellerin ellerimi gözlerinde yağmurlar, 

Üzülme. 

Yum gözlerini usuldan. 

Bak yüreğindeyim. 

Estirme hüzün rüzgarlarını

Kov sahilinden deli dalgaları 

Sakin serin pınarlarda çağlar damlalarım. 

Dağlardan esen meltemlerde, 

Akan çeşmende benim.

Yıka yüreğini temiz sularımda, 

Gönlünde melankoli kalmasın 

Şifalıdır damlalarım, 

Ben yağmurum, 

Yağmur, 

Benim...', 'Kararır gökyüzü ansızın,  Çarpar bulutlar kahrederek,  Ve bir ateş yanar...  Bulutlar yanar,  Yürek yanar.  Sonra tek tek düşer damlalar,  T...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ben-yagmurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de mi Mona! ....! ?', 'sen-de-mi-mona-abdullah-acar-rsnfv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay ışığından almış yüzün rengini

Ah! O gözlerdeki hançer pırıltısı..

Lime lime edecek bir rüya beni

İşte bu, ölümün ölümsüz sancısı

Ah! O gözlerdeki hançer pırıltısı..

Yok, tarifi yok işte, duygularımın

Seni sevmiyor, seni sevmiyor gibi seviyorum

Sen ki sevimli katili uykularımın

Işığın ardında ateş var, biliyorum

Seni sevmiyor, seni sevmiyor gibi seviyorum

Şu ölüm, nede güler yüzlü bugün

Ne kadar da cana yakın, sıcak ne kadar

Ufuklarda bir alay, bir şenlik, bir düğün

Benimse ateş sıçrar canevime kadar

Şu ölüm, nede güler yüzlü bugün...

Enli palasında bölünen, acı sözlerin

İlkin ipek yoluymuş kalpleri bağlayan

Kapılıp işvesine o sahte denizlerin

Gittin! Seni de çekti, o sinsi yalan

Kapıldın işvesine o sahte denizlerin

Niçindir sonsuzluğa el uzatışım? 

Aynalara yüz verişim neden? 

Sebep seni sen değil, seni o sen sanışım

Ah! Ben ne kadar da aymazmışım..

Seni meğer sen değilsin sanmışım...

Uyku, kıvrandığım soluk, dehlizlerinde

Orada sen, orada her kaybettiğim

Bir karanlık yokuşun o soluk izlerinde

İşte görüyorum, işte! takibettiğim..

Orada sen, orada her kaybettiğim...

Yağmur, bir eski şarkı gibi kulaklarımda

Çınlar durur sabahlara kadar

Rüzgar almış kokunu Cebeci sokaklarında

İnler durur sabahlara kadar

Rüzgar almış kokunu Cebeci sokaklarında

Saatler pusmuş, saatler susmuş bugün

Akrepler yelkovanlarına ihanet etmiş 

Yelkovanlar akreplere küsmüş bugün

Akrepler kendilerine lanet etmiş

Saatler pusmuş, saatler susmuş bugün

Alın yazım gibi başucumdasın

Yağmurlu havalarda dizlerimde

Ben bir ucunda dünyanın sen bir ucundasın

Boşuna arama beni izlerimde

Alın yazım gibi başucumdasın..

Lakin, doldu vakit gün devrildi

Ayakta bir o kalmıştı, dün devrildi

Umudum yıkılmaz dağlar gibiydi

Karlar gibi eridi, dün, eridi

Ayakta bir o kalmıştı dün, devrildi.

(Ekim 1994, Ankara)', 'Ay ışığından almış yüzün rengini Ah! O gözlerdeki hançer pırıltısı.. Lime lime edecek bir rüya beni İşte bu, ölümün ölümsüz sancısı Ah! O gö...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sen-de-mi-mona-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Sevda', 'zor-sevda-birsen-i-brahimhakkioglu-7u8lb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitap düştü yüreğim

Hayallerim

Umutlarım

Adımlarım geri gidiyor

Ey heybetli ayrılıklar

Gücüm yeter sandım size 

Ardına gizlenen duyguları hafife mi almalı

Yüreğimde asılı kalan hasret

Özlemin sonu kavuşmayla biter mi? 

Susmayın 

Durmayın öyle

Söyleyin 

Biter biter değil mi? 

Umut sırtını dönmüş olsa bile bana

Hasretim ayrılığı yener mi? 

Ayrılık rüzgârına kalkan olabilir mi? 

Başkaldırır mı umutsuzluğa

Aşkın gücünde ayrılık titrer mi? 

Ardına gizlenen duygular

Yüreğimde kol gezer mi? 

Yoksa terk edip gider mi? 

Sevdam umutsuzluğundan soyunup

Umudu giyinip aşka gülümser mi? 

Zor mu aşka sahip çıkmak

Zor mu? 

Gerçek sevdaya tutunmak

Zor mu seven yüreğe kucak açmak

Zor mu çaresizlikten sıyrılmak

Ben zor olanı yaptım

Zor olana sevdalandım

Adımlarımla engelleri aştım

Asıl olana vardım

Ayrılığım

Hasretim

Umutsuzluğum

Sizlere hüznümle 

Son vedamı yaptım

Gözlerimdeki yası kaldırdım

En parlak yıldızı 

Gözlerime aldım

Işığımla

Aşkımla

Sizleri yok saydım', 'Bitap düştü yüreğim Hayallerim Umutlarım Adımlarım geri gidiyor Ey heybetli ayrılıklar Gücüm yeter sandım size  Ardına gizlenen duyguları ha...', ARRAY['Türk Edebiyatı','Şiir','Birsen İbrahimhakkıoğlu']::text[], 8.5, '{"poet":"Birsen İbrahimhakkıoğlu","poet_slug":"birsen-i-brahimhakkioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/zor-sevda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melekyüzlüm', 'melekyuzlum-yurdagul-kurnaz-f9416', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen

Melekyüzlüm

Nerdesin! 

Seni tanidim/

_____________Kendimi unuttum

Kara gözlerinde aydinlik

Yasamin sevinc doluydu

Azim desen; sende boldu

Umuttu yarinlar! ! ! 

_____________Ve apansiz gelen yürek yangini

_____________Allahim, dindir bu sancimi

Biliyorum simdilerde

Meleklerle gökyüzünde

Canin acitmiyor! 

Maviliklerde

Pamuk kanatlar altinda

Cicekler; her bir yaninda

Serceler cocuk tadinda

Seni hep sevecegim Atakan diyor! 

Dualarim seninle devam ediyor

''Melekyüzlüm''', 'Sen Melekyüzlüm Nerdesin!  Seni tanidim/ _____________Kendimi unuttum Kara gözlerinde aydinlik Yasamin sevinc doluydu Azim desen; sende bold...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/melekyuzlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimal Yıldızı', 'simal-yildizi-kenan-taskin-w0gep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vakit

Canım kızım bir öğlen yemeğinde kanını içmektir gençlerin

Ankaranın upuzun asfalt kaldırımlarında

Yerde yatan gencin daha kurumamış kınası elinde

Şimalim vurulan sensin, senin yüreğin

Vakit 

Bir yıldızlı akşamdır kızım

Memet önce çocuğunun karnını doyurur

Sonra yaban ekmekle kendini

Ve karısı ıstmadan kıvranıp seni doğurur

Vakit

Şimalimin annesinin gülüşüdür

Ellerin pas kokar, pasın yanlızlık

Dünyada satılan tüm simitleri ben satarımm

Hatta bu küflü ankara sabahının kızarmış ekmeğinide

Bu paslı sendada büyüyen sensin kızım

Vakit

Şimalimin annesinin doğum sancısıdır

Ankaranın bulutsuz bir ayyaş günü

Sarımsak kokan sarhoşlar bam telinden

Tutuyorlar hayatı

Sen doğuyorsun kızım 

Zifir kokan şişelerde

Vakit

Bir papatya kokusudur kızım

Senin kalbinde büyür prematüre bebekler

Ve açlık ucu kaplı kitap

Ankaranın göbeğinde

Beyaz işçi sepetlerinde doğan sensin kızım

Vakit

Bit tohum atmaktır kızım toprağa

Ve mantar şapakasına benzer

çöp tenekesinin kapağı

Ve içinde 6 yaşlarında bir çoçuk

Siyah gözlerini senden almış isminide

Vakit

Şimalimin ilk bakışıdır hayata

Sarı kadın sarı çoçuk doğurur

Kürt kızının pulludur eteği ve gözleri karadır

Süt içmez üç gün ve karnındadır rıskı

Sensin kızım  karlı yollarda dere kenarında doğan çoçuk

Vakit

Kara madendir kızım

İşçisi babandır bu mineralin

Evde ağlayıp bekleyen sen

Ve tavşan ürkekliğinde annen açar kapıyı saat dörtte

Seni doğurur yerin binlerce metre altında

Vakit

Canım kızım şimalim deprem sabahıdır

Bir ayakkabı boyacısının süpürmesidir 

Ankarayı

Gökyüzünün en derin yerinde 

Bulutların içinde

Kalbinin durmasıdır annenin

Ve senin bir park kenarında göbeğin kesilmiştir kızım

O

Pembe şireli evde

O

Bacası kırık

O

Ekmeği dert

O

Açlık içinde

Sen doğdun ve dünyanın bütün bebekleri sevindi doğumuna

Annende, bende! ! !', 'Vakit Canım kızım bir öğlen yemeğinde kanını içmektir gençlerin Ankaranın upuzun asfalt kaldırımlarında Yerde yatan gencin daha kurumamış kı...', ARRAY['Türk Edebiyatı','Şiir','Kenan Taşkın']::text[], 8.5, '{"poet":"Kenan Taşkın","poet_slug":"kenan-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/simal-yildizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Londra 1998', 'londra-1998-umit-isikdag-feeuk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bambaşka bir dünyada

Sevdalı bir biçimde

Elimde bir fener var

Kalbim yanar içinde

Duvaksız bir gelinin

Ellerini tutarken

Hesapsız bir aşkımın

Acısı var içimde

Sensiz düşen yaprağın

Sensiz karanlıkların

Umutsuz sevdaların

Tadı başka biçimde

Kendi yalnızlıklarım

Acıyla dost olurken

Bir ben benle kalırdım

Evvelzaman içinde', 'Bambaşka bir dünyada Sevdalı bir biçimde Elimde bir fener var Kalbim yanar içinde Duvaksız bir gelinin Ellerini tutarken Hesapsız bir aşkımı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Işıkdağ']::text[], 8.5, '{"poet":"Ümit Işıkdağ","poet_slug":"umit-isikdag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/londra-1998-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onaltıncı yolcu', 'onaltinci-yolcu-mehmet-halil-hhff8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun yıllar geçti aradan

Kara denizin kara suları 

Kıvrandı yıllarca sıkıntıdan

Yükseldi dağlar gibi dalgaları.

Yine de dinmedi acıları.

Ağıtlar yakıldı hep bir ağızdan

Karadeniz’in bağrında acı

Onbeş yolcu çıktı takadan,

Bir sır gibi saklandı onaltıncı.

Ses yok, tek kadın yolcudan.

Korsanlar için o bir ganimetti

Bu kadardı devrimin zihniyeti

Bu kadardı kadının hürriyeti.

Halkın uğrunda kan döktüğü,

Bu günkü bağımsızlık gibi…', 'Uzun yıllar geçti aradan Kara denizin kara suları  Kıvrandı yıllarca sıkıntıdan Yükseldi dağlar gibi dalgaları. Yine de dinmedi acıları. Ağı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/onaltinci-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastahane', 'hastahane-nalan-kahraman-32fzn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün.......

Hastahaneye gittim.....

Tek tek bütün odalara girdim,

Acı çekenleri,ağlayanları gördüm......

Birde............

Beyaz çarşafa sarılmış biri vardı.......

Çevresinde de ağlayanlar........

Yüzünde tebessüm olan hiç yoktu...

Bizler dışarda gönlümüzce gülebilirken......

Oradakilerin içi kan ağlıyordu....

Bugün bende hastahaneye yattım.....

Şimdi..........

Benimde çevremde bekleyenler var.

Ve........

Anladım ki hastahaneye yatmayan,

Buranın durumunu anlayamaz da,yaşayamaz da...........', 'Dün....... Hastahaneye gittim..... Tek tek bütün odalara girdim, Acı çekenleri,ağlayanları gördüm...... Birde............ Beyaz çarşafa sarı...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hastahane-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm Diye', 'olurum-diye-nalan-kahraman-6d0al', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzülüyorum,

Endişeleniyorum,

Heyecanlanıyorum,

Ve..............

Korkuyorum; 

Ölürüm diye,

Ölürüm de 

Tüm güzelliklerden,

Mutluluklardan,Sevinçlerden,

Dostluklardan,

Ve......

En kötüsü de

Sevip sevilmekten

Mahrum kalırım diye 

Ölmekten korkuyorum..........', 'Üzülüyorum, Endişeleniyorum, Heyecanlanıyorum, Ve.............. Korkuyorum;  Ölürüm diye, Ölürüm de  Tüm güzelliklerden, Mutluluklardan,Sevi...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olurum-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkla Yas', 'askla-yas-kiymet-sonmez-4da84', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkla yas kardeş gibidirler,

İkiside acı verir insana

İkisinin de tam kırk mumu vardır

Hepsi sönse de bir tanesi yanar  ömür boyu 

Kalbinin derinliklerinde

İşte o otuzdokuz mum

Hayatın devam ettiğini gösterir

Yine severiz, yine seviniriz,

Yerine göre güler hatta çığlıklar atarız.

Mutluluk saçarız hem kendimize, 

Hem başkalarına

O kalan mum o ışığı verir bize.

Ya intikam için yanar,

Ya yüreklendirmek,ya da  cesaretlendirmek için

Otuzdokuz tane ile geçmişi bir kenara bırakmak,

Yanan bir tane ile hayata sıkı sıkı sarılmak gerek.

Çünkü hayat önce bizim hayatımız.

Biz olduğumuz için o aşklar yaşandı,

Biz olduğumuz için o yasların acısını çektik.

Onlar artık yok ama biz hala varız.

O halde niye olmayanın peşinden gidelim,

Onları zaman zaman analım

Hatta güzel günlerden iyiki yaşamışız diye söz edelim,

Kötü günlerden de nerde yanlış yaptık diye ders çıkaralım.

Hala var olan kendimizi 

Kendimize layık olacak şekilde yaşayalım.', 'Aşkla yas kardeş gibidirler, İkiside acı verir insana İkisinin de tam kırk mumu vardır Hepsi sönse de bir tanesi yanar  ömür boyu  Kalbinin ...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/askla-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Maddiyat Değildir', 'ask-maddiyat-degildir-kiymet-sonmez-revfx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herşeyin maddiyata dönüştüğü bu dünyada

Ertelemeyin sevgiyi,

Acaba ne alacağım,

Acaba bana ne alacak diye düşünmektense

En değerli olan bir şeyinizi

Yüreğinizi ve zamanınızı vermeyi deneyin

Ne alırsanız alın

Sevginizin ölçüsü değildir o

Maddi gücünüzün ölçüsüdür.

Oysa size ait yüreğiniz ve zamanınız

Hiç bir maddiyatla ölçülmez

Gerçekten birine sevgi besliyorsanız

Bu şimdilik bir hardal tanesi kadar bile olsa

Geliştirebilirsiniz

Zamanınızı ve yüreğinizi vererek

Tüm içtenliğinizle

Yarına ertelemeyin sevginizi söylemeyi

O değerli zaman

Gerçekten çok değerli

Çok uzun gibi gelsede insana 

Çok kısada olabilir

Sevginizi bir an bile söyleyemeden 

Uçup gidiverir

Sadece kendinize saklamayın sevginizi

Bırakın herkes duysun

Sevgiden utanılmaz

Haykırın, bağırın

SEVİYORUM 

Diye

Korkmayın kimse sizi ayıplamaz

Belki başkalarına cesaret bile vermiş olursunuz

Hani sever sever de bir türlü söyleyemez insan

Niye sizin bir haykırışınız

Başkalarının haykırışlarınada sebep olmasın

Bırakın ne alayım diye düşünmeyi

Allah aşkına bırakın

Bir arayın,sevginizi söyleyin

Gerçekten seven insan

Başka şey beklemez

Bekliyorsa şayet

Onunkide sevgi değil

O güzelim sözcüğü

Maddi çıkarlar için kullanmaktır yalnızca

Ne olur yalın bırakın sevgiyi

Yalnız sevgi olarak kalsın

Onu gösterin sevdiğinize yeter

Yeterki onu ertelemeyin

Şu maddiyata gömülmüş dünyada

Sevmeye ve sevilmeye o kadar ihtiyacımız varki

Yunus senelerdir der

Sevelim sevilelim diye

Sevilmediğinizi zannediyorsanız da sevin

Sevdiğiniz takdirde

Sevilen de olduğunuzu göreceksiniz.

Hadi ne duruyorsunuz

Arayın sevdiğinizi

Sesinizi duymak yeter ona

Hadi 

Uzaktaysanız alın telefonu elinize

Yakındaysanız koşun yanına

Mesafeler engel değil sevgiye

Hadi

Nerde olursanız olun

Ne kadar çok işiniz olursa olsun

24 saatin içinde bir dakikanızı ayırın hiç olmazsa 

Yalnızca bir dakika 

Herkesin bir dakikası vardır

Yeterki onu sevgiye ayırmayı bilin.

Siz ayırın bir dakikanızı

Başkalarıda sizin için ayıracak unutmayın

Öyle bir an gelecekki

Değil 24 saat 

Ömrünüz bile yetmeyecek', 'Herşeyin maddiyata dönüştüğü bu dünyada Ertelemeyin sevgiyi, Acaba ne alacağım, Acaba bana ne alacak diye düşünmektense En değerli olan bir ...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/ask-maddiyat-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Kuş', 'bir-garip-kus-nalan-kahraman-7plxd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün.....

Uzaktan çok uzaktan

Bir garip kuş geldi yanıma

Çaresiz ve bitkin di

Yardım ister gibiy di...

Ona sıcak kalbimi,

Nasihatle beraber şefkatimi,

Yardım elimi,

Vereceğimi söyledim.

Benim sahibim......

Uzaklarda çooook uzaklar da

Ver ver de götüreyim,

Gülsün,neşelensin sahibim,

Kafasına takmasın her sorunu,

Bilsin ki bura da Nalan dostu var

Dedi.........

Dedi ve gitti....

O çaresiz sahibinin garip kuşu....', 'Dün..... Uzaktan çok uzaktan Bir garip kuş geldi yanıma Çaresiz ve bitkin di Yardım ister gibiy di... Ona sıcak kalbimi, Nasihatle beraber ş...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-garip-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğinde', 'sensizliginde-abdullah-atay-6wzub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hazanım bahar oldu

Tutunca ellerimi

Vuslat çiçeğim soldu

Unutunca sen beni...

Yürek yandı kül oldum

Suya hasret çöl oldum

Bir garipce kul oldum

Unutunca sen beni...

Kefen sarsa bedeni

Toprak çürütse teni

Sen yaşamın nedeni

Unutamam ben seni...

Onca gönle aksamda

Has gülleri koksamda

Her güzele baksamda

Avutamam kendimi...

Tanrı cenneti verse

Her yanım huri sarsa

Ömür bin yıl da sürse

Avutamazlar beni...

Ecel şerbetin içince

Can bedenden göçünce

Kabrimde gül açınca

Unutma sen de beni...', 'Hazanım bahar oldu Tutunca ellerimi Vuslat çiçeğim soldu Unutunca sen beni... Yürek yandı kül oldum Suya hasret çöl oldum Bir garipce kul ol...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensizliginde-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Dünya', 'bos-dunya-nalan-kahraman-6x0sg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...Dünyayı durdurmak istiyorum,

Karamsarlığı yok etmek,

Doya doya eğlenmek,

Tüm insanlara mutluluğu koklatmak,

Sevip sevilmesini bilmek için....

Sonra da.........

Bırak dönebildiğince dönsün.....

Bu düzensiz boş dünyamız.............', '...Dünyayı durdurmak istiyorum, Karamsarlığı yok etmek, Doya doya eğlenmek, Tüm insanlara mutluluğu koklatmak, Sevip sevilmesini bilmek için...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bos-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey ırmak kendini anlat bana', 'ey-irmak-kendini-anlat-bana-umit-isikdag-0z5cd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen dur

Ey ırmak dur

Dur demekle 

Hangi ırmak durur

Sen çağla

Ey ırmak çağla

Damla suyun anlam yüklü

Deniz bulamadın mı? 

Ağla ırmak ağla

Sen berrak

Ey ırmak dayan 

Günün kara olsa da, denizin ak

Bulacaksın denizi

Ya bir damlanda ya da bir zaman

Sen zaman

Sen beni sonludan alıp

Sonsuza koyan

Kendi anlamında gizli

Bir damlan

Ve kendi damlanda gizli bir anlamın

Sen sev 

Beni sana taşıyan kendini sev

Var olmanı sev

Yolculuğunu sev

Sen taşı 

İster beni ister kendini taşı

Anlamın bu

Anlamını taşı

Sen yak

Ey ırmak yak

Ateşi yak ve,özünde söndür

Sen ateşinde özüsün

ırmağında özüsün

Sen cetvel

Sen eğriyi doğrudan ayıran hat

Seni anlamak ilim de

Anlamamak mı kabahat

Sen yor

Kendini değil,senden olmayanı yor

Sonra senden sor,ve ondan sor

Gör kim anlamış seni

Sen gizem

Sen hem gizleyen hem gösteren

Sen anlaması güç olan

Ey ırmak

Hadi kendini anlat bana...', 'Sen dur Ey ırmak dur Dur demekle  Hangi ırmak durur Sen çağla Ey ırmak çağla Damla suyun anlam yüklü Deniz bulamadın mı?  Ağla ırmak ağla Se...', ARRAY['Türk Edebiyatı','Şiir','Ümit Işıkdağ']::text[], 8.5, '{"poet":"Ümit Işıkdağ","poet_slug":"umit-isikdag","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ey-irmak-kendini-anlat-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gel de Gör', 'gel-gel-de-gor-nalan-kahraman-vu868', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl oldu bilmiyorum

Bağlandım sana tamamen

Sensiz bir an bile düşünemiyorum,

Acı ve ızdıraptan duramıyorum.

Yıldızlar da ay da güneş de

Gezdiğim,gördüğüm her yerde

Bir tek sen varsın

Yalnız hayalin ile sen varsın.

Gel gelde gör halimi

O neşeli,şen kardeşini,

Artık yaşamıyor sanki,

Artık uyumuyor,konuşmuyor sanki.

Her telefon çalışın da

Her sesini duyuşun da

İşte o zaman yaşıyor,

O zaman gülüyor.

O zaman çok,çok iyiyim diyor,

Sensiz bir hayatta ruhlarla tek başına.............', 'Nasıl oldu bilmiyorum Bağlandım sana tamamen Sensiz bir an bile düşünemiyorum, Acı ve ızdıraptan duramıyorum. Yıldızlar da ay da güneş de Ge...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-gel-de-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gibi..', 'sen-gibi-neslihan-i-sler-4pw4h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin gözlerinden görmek  dünyayı

Gölgen olmak  bastığın heryerde adım adım

Ellerin olmak herzaman  ihtiyaç duyduğun,,,

Yüreğin olmak heran atışını hissettiğin

Ya da engüzel rüyan asla unutamadığın,,,', 'Senin gözlerinden görmek  dünyayı Gölgen olmak  bastığın heryerde adım adım Ellerin olmak herzaman  ihtiyaç duyduğun,,, Yüreğin olmak heran ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-gibi-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyayı Aşk Sarmış', 'dunyayi-ask-sarmis-tulay-sustam-zz8zy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'rüzgâr! ...

gökyüzüne kızmış, delirmiş yine bugün

gökyüzü

kalmış ayaz da, üşümüş koca gövdesi 

üzerine çekmiş yorganını

şehrin parmak uçları kalmış açıkta

ay; 

tutulmuş aşka, evreler geçiriyor.

o da bir âlem kendisini kandırıyor...

güneş; 

bulutun yokluğundan saçlarını yoluyor

sen

her şeyden habersiz

-en büyük aşkı ben yaşıyorum- diyorsun! ...

kendinden -bir ben - yaratmışsın...

beni hiçe sayarak...

aşk 

en çok senin yüreğine vurmuş yâr...

yosun gözlerine

yağmuru misafir etmiş...

kov gitsin yağmuru, ben geldim...

bende ki seni de yanıma alarak...

25.08.2005 İstanbul (gece üç-beş nöbetleri)', 'rüzgâr! ... gökyüzüne kızmış, delirmiş yine bugün gökyüzü kalmış ayaz da, üşümüş koca gövdesi  üzerine çekmiş yorganını şehrin parmak uçları...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dunyayi-ask-sarmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle İşte', 'oyle-i-ste-berrak-su-kz5up', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir anki,

Uyku tüm bedenimde.

Doğrular bilinçaltımda tutsak,

Yavaştan süzülmüş ne zaman bilmem! 

Işıklarını yenilemeyen yıldızlara 

Köprüler kurarım köpüklerden.

Görümü öteleyen geçişler yaparım.

Dar kalyonlarda ufak bir patik yüreğim,

Sıkışmış gerçeğine,

Gerçeğine inat.

Üç kat yabancıların titreyen kemikleri,

Ladeslenmiş enime.

Barınaklarım, yağmacıların ayakyolu,

Yoldan geçenler,

Çokça,

Kalabalıkça...

Berrak Su', 'Öyle bir anki, Uyku tüm bedenimde. Doğrular bilinçaltımda tutsak, Yavaştan süzülmüş ne zaman bilmem!  Işıklarını yenilemeyen yıldızlara  Köp...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oyle-iste-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlenemem Ya!', 'evlenemem-ya-nalan-kahraman-wk30k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum,

Sensiz olamam,

Benimle gel,

Evlenelim diyorsun.

Bense seni sevmiyorum,

Seninle olmak istemiyorum,

Seninle gitmektense nefret ediyorum,

Ve......

Seninle evlenemem anlıyormusun

Ev-len-e-mem

Evlenemem yaaaaa! !', 'Seni seviyorum, Sensiz olamam, Benimle gel, Evlenelim diyorsun. Bense seni sevmiyorum, Seninle olmak istemiyorum, Seninle gitmektense nefret...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/evlenemem-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuval', 'tuval-zafer-mutlu-6zfad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gölgenin,

 uzunluğu ile bastığın

 toprağın... 

 ilgisi yok be oğlum

İster Doğuda..

ister Batıda..

Kuzeyde,Güneyde..

Ağaçlar gibi 

Ormanlar gibi... 

Güneşi  gördüğün

her yerde

Gölgeni de  göreceksin

ve diyeceksin ki;

Güneşin renkleri yüzümüzde

ya... 

varsın olsun toprağa düşsün

gölgemiz

Yaşıyoruz, yaşayacağız

beraberce...', 'Gölgenin,  uzunluğu ile bastığın  toprağın...   ilgisi yok be oğlum İster Doğuda.. ister Batıda.. Kuzeyde,Güneyde.. Ağaçlar gibi  Ormanlar g...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tuval-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamıyorum Birtanem', 'unutamiyorum-birtanem-nalan-kahraman-bhzxn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O günü hatırlıyormusun birtanem? 

Birlikte sahile indiğimiz,

Öpüşüp,koklaştığımız,

Saatlerce birlikte olduğumuz o günü? 

Ben asla unutmadım birtanem

Seni,cesaretimizi ve kokunu,

Unutmak istesem de unutamam ki,

Çünkü sen benim ilk ve tek erkeğimsin,

Evet birtanem......

Seni unutmak istediğim de...

Burnumda kokunu,

Dudaklarım da dudaklarını,

Ellerimde ellerini ve sıcaklığını

Vücudum da ise tüm bedenini

Hissediyorum,

Ve...............

birtanem.............

Seni unutamıyorum ben..........', 'O günü hatırlıyormusun birtanem?  Birlikte sahile indiğimiz, Öpüşüp,koklaştığımız, Saatlerce birlikte olduğumuz o günü?  Ben asla unutmadım ...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutamiyorum-birtanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fakir Olacaksın Fakir', 'fakir-olacaksin-fakir-ahmet-nural-ozturk-ghfvg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vallahi 

Malla 

Billahi 

Mülkle 

Geçilmez o köprü 

Ayağına varmadan düşer kalırsın 

Fakir olacaksın fakir

Günah fakiri

Yemeyeceksin yetimin hakkını

Ve utanmayacaksın dürüst olmaktan

Aç kalsa da bedenin

Fakirlik dediğin yüksüzlüktür 

Arınmışlıktır günahtan 

İşte işin kolay o zaman 

Sorgusuz sualsiz 

Geçer gidersin Allah katına

Pasaport göztermeden

Ve yakmadan yüreğini

Dünyanıni yangınından', 'Vallahi  Malla  Billahi  Mülkle  Geçilmez o köprü  Ayağına varmadan düşer kalırsın  Fakir olacaksın fakir Günah fakiri Yemeyeceksin yetimin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/fakir-olacaksin-fakir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaradılışım', 'yaradilisim-berrak-su-elsbl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neye yaratılmışsam,

Güçlü, zayıf.

Yaşamalıyım.

Kanatlarım olmalı,

Uçmadan yürümeyi öğrenen.

Tüm yönelmelerde istençli.

Ve kıvrak, kavrayamadığım çılgınlıklarda.

Neye yarar yaratık,

Yaradılmanın ardında kalmışsa.

Çok hızlı,

Çok yavaş,

Yaşadım,

Neye yaratılmışsam...

Berrak Su', 'Neye yaratılmışsam, Güçlü, zayıf. Yaşamalıyım. Kanatlarım olmalı, Uçmadan yürümeyi öğrenen. Tüm yönelmelerde istençli. Ve kıvrak, kavrayamad...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yaradilisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırattan', 'sirattan-sinan-karakas-pgok9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Harab-ı dıl(gönül)   olanlar,  revanı hun olurlar,

Hun(kan)    içenler elbette, birer hunnar olurlar,

Nadim(pişman)   olmak, her nasın(insan)  kârı olabilir mi,

Sırattan rahat geçer, vicdanları  olanlar,', 'Harab-ı dıl(gönül)   olanlar,  revanı hun olurlar, Hun(kan)    içenler elbette, birer hunnar olurlar, Nadim(pişman)   olmak, her nasın(insan...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sirattan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöstalji', 'nostalji-nalan-kahraman-1xok8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tüm bağımsızlığımla,

Gezdiğim,

Gördüğüm,

Rahat bir nefes aldığım,

O günleri unutamıyorum,

Gönlümce eğleniyor,

Su gibi para harcıyor,

Ve......

Büyük bir zevkle,

Özgürlüğün tadını çıkarıyordum.

Şimdi.............

Tüm özgürlüğüm ve bağımsızlığım,

Sınırlı,her şeyden mahrum,

Nöstaljik duygularla yaşıyorum...........', 'Tüm bağımsızlığımla, Gezdiğim, Gördüğüm, Rahat bir nefes aldığım, O günleri unutamıyorum, Gönlümce eğleniyor, Su gibi para harcıyor, Ve........', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nostalji-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeme Yetimin Hakkını', 'yeme-yetimin-hakkini-ahmet-nural-ozturk-kbckn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vallahi 

Malla 

Billahi 

Mülkle 

Geçilmez o köprü 

Ayağına varmadan düşer kalırsın 

Fakir olacaksın fakir 

Günah fakiri 

Yemeyeceksin yetim hakkını 

Ve utanmayacaksın dürüst olmaktan 

Aç kalsa da bedenin

Sürünsen de ortalıkta

Fakirlik dediğin yüksüzlüktür 

Arınmışlıktır günahtan 

İşte işin kolay o zaman 

Sorgusuz sualsiz 

Geçer gidersin sırattan

Allah kendini bile men etmiştir

Yüksüze  sual sormaktan', 'Vallahi  Malla  Billahi  Mülkle  Geçilmez o köprü  Ayağına varmadan düşer kalırsın  Fakir olacaksın fakir  Günah fakiri  Yemeyeceksin yetim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yeme-yetimin-hakkini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşer', 'mahser-aysel-cakar-2dpwe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gittiğin günden beri,

Günleri sayar oldum.

Günün,batışını hiç beklemezken, bekler oldum.

Ömrümden ömür gitse de farketmez,

Yalnızca geleceğin günü bekler oldum

Söyle! Bu bekleyiş,bir gün biter mi? 

Ruhumu yakan hasretin; bir gün sona erer mi? 

Geleceğim diyorsun.Bekle! Diyorsun.

Beklemeye bu ömür,

Söyle! Geleceğin güne,bu can yeter mi? 

Nasip olmazsa kavuşmak bize; bu dünyada,

Bekle! Geleceğim. Mahşerde ben, sana.

Bil ki,aşkından eridi bu can yana yana,

Her iki cihanda da olsa farketmez.

Hep seveceğim Seni, doya doya!', 'Sen gittiğin günden beri, Günleri sayar oldum. Günün,batışını hiç beklemezken, bekler oldum. Ömrümden ömür gitse de farketmez, Yalnızca gele...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çakar']::text[], 8.5, '{"poet":"Aysel Çakar","poet_slug":"aysel-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mahser-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durakları Unuttum Sende', 'duraklari-unuttum-sende-kamil-soylemez-ex5pd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensin bilirim

Şarkılarda hep dinlediğim

Unuttuğumdur duraklar sende

İnip,inip,bindiğim

Arabesktir yada slov parçalar

Hepsinde sen resmolursun

Kadehimde hiç bitmez

Gecesindir yada gündüz

Benim için hiç fark etmez 

Vapurdur,tirendir sal

Hep hatırladığım hayat

Ormandır düşlerim

Sana sırtımı dayadığım

Bir fincan çaydır

Zehir zembelek birde sigara

Seni düşünürken yudumladığım

Gözdür, düğmedir iliklediğim

Ama sendin yüreğime çıt, çıt ladığım Eminim', 'Sensin bilirim Şarkılarda hep dinlediğim Unuttuğumdur duraklar sende İnip,inip,bindiğim Arabesktir yada slov parçalar Hepsinde sen resmolurs...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duraklari-unuttum-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda Yürüyüş', 'yagmurda-yuruyus-kenan-demirel-qra37', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gümrah bir yağmur yağar. 

Tenhada yürürüm sırılsıklam. 

Islanır arzuyla saçlarım.

Alnıma dökülüp bezenir.

Sel yürür yokuş aşağı.

Çakıllar yürür.

Ben yürürüm,

Yağmur durur da, 

Bir güneş doğar ışıl ışıl,

Bulutların arasından,

Grilik dağılır parıltıyla,

Huzurla yatışır mavilik.

Ben yürürüm.

Bir serap gibi süzülür varlık,

Ilgıt ılgıt buharlaşır,

Elbisem kurur,

Ben yürürüm.

Bir nefes çekerim,

Yağmurdan artakalan kokudan,

Yağmur içimde çoğalır.

Ben yürürüm.', 'Gümrah bir yağmur yağar.  Tenhada yürürüm sırılsıklam.  Islanır arzuyla saçlarım. Alnıma dökülüp bezenir. Sel yürür yokuş aşağı. Çakıllar yü...', ARRAY['Türk Edebiyatı','Şiir','Kenan Demirel']::text[], 8.5, '{"poet":"Kenan Demirel","poet_slug":"kenan-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-yuruyustur-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimene meyhanesi', 'kimene-meyhanesi-erol-buker-v5z18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimene meyhanesinde her akşam

tanıdığım insanlar toplanır

aşıklar, berduşlar, şairler

birde arada bir yolunu şaşıranlar.

Muhabbetin kitabının yazıldığı yerdir 

kimene meyhanesi.

Kimene meyhanesinde her akşam

sokak  çalgıcıları  dolaşır masaları

sarhoşsan vede  efkarlıysan

öyle yanıkdır ki sarkıları

ama keyifliysen çakırsan

fıkır fıkır yakası açılmadık roman havaları

''''çal bana çakır gaydayı 

oyna oyna çal çal gaydayı

aa  be yoksa ye yorganları ''''

alemdir kimene meyhanesi.

Gecenin bir vakti

bir berduş  ayışığı parıltılı sustalısını çeker          böğrüne  saplar gecenin 

bir damla kan akmaz geceden

ve bir  kurşun sesi

bozar  gecenin sessizliğini

bir sarhoş yıldızları vurur

teker teker.

Bir başka masada  bir şair 

henüz yazdığı şiirini okur 

''''evet dilenciyim

aşk dilencisi

ne koparsa gönlünden ''''

diye sıralar dizelerini.

Bir sarhoş 

orhan abisinden bir teselliyi söyler detone sesiyle

oda bilir ki

ne  içtiği rakı 

ne söylediği şarkı

nede  masadakiler 

olamazlar bir teselli

yarında aranacak bu besbelli.

Kimene meyhanesinde 

her sabah  gün ağarırken 

masalar boşalmıştır

garsonlar toplamaya başlar 

tahta masalarda unutulan

ne varsa geceden kalan.

umutlar, sevinçler, hüzünler

yarım kalmış şiirler

yaşanmamış aşklar.

Kimene meyhanesi  her sabah

yeni bir akşama

yeni bir umuda  sevince ve hüzüne

yeni bir aşka hazırlanmaktadır

bir gelin gibi.

Ama her akşam tanıdığım insanlar toplanır

aşıklar, berduşlar,şairler

bir de arada bir yolunu şaşıranlar.

muhabbetin kitabının yazıldığı yerdir 

kimene meyhanesi.



.', 'Kimene meyhanesinde her akşam tanıdığım insanlar toplanır aşıklar, berduşlar, şairler birde arada bir yolunu şaşıranlar. Muhabbetin kitabını...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kimene-meyhanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hayal kipinde dörtnala', 'hayal-kipinde-dortnala-yildiz-yildiz-16j92', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doru atlar doğurdum

Issız dağ doruklarından   boşanmış 

dörtnala

doru atlar...

Hayalden yelelerinde

Maviydi rüzgar

Mavi şarkılar doğurdum

Ay ışığından

Hüznü âzam

İnce sazdan...

Hüzmelerden 

Sarı ışıklar süzen şarkılar

Kendimden  kadınlar doğurdum 

Sarı ve sayısız

Kocaman gözlü, 

dilleri lâl…

elleri boş,

elleri ateş,

kalpleri kül,

kalpleri güneş,

eflatun saçlı  kadınlar.

Ve hasreti öldürüp

Dipsiz düşler doğurdum

eflatun.

Görsen...! 

Dağ gölleri gibi titrerdi bakışın', 'Doru atlar doğurdum Issız dağ doruklarından   boşanmış  dörtnala doru atlar... Hayalden yelelerinde Maviydi rüzgar Mavi şarkılar doğurdum Ay...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hayal-kipinde-dortnala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdilik Dur', 'simdilik-dur-firuze-keles-mj3qa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni unuttuğum zaman unut beni

Seni sevmediğim zaman sevme.

Ama şimdilik dur, şimdilik bekle...

Yüreğimde kaldığın kadar kalayım sende...', 'Seni unuttuğum zaman unut beni Seni sevmediğim zaman sevme. Ama şimdilik dur, şimdilik bekle... Yüreğimde kaldığın kadar kalayım sende......', ARRAY['Türk Edebiyatı','Şiir','Firuze Keleş']::text[], 8.5, '{"poet":"Firuze Keleş","poet_slug":"firuze-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/simdilik-dur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trenler', 'trenler-ozgur-celik-xwgw9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'trenler gelip geçerken yanımdan, 

sanki senide götürüyorlar 

ben ardından adını bağrıyorum 

trenler gelip geçerken yanımdan, 

aslında benim içimden geçiyorlar 

bunu ezilen damarlarımdan anlıyorum.', 'trenler gelip geçerken yanımdan,  sanki senide götürüyorlar  ben ardından adını bağrıyorum  trenler gelip geçerken yanımdan,  aslında benim ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/trenler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeminim var', 'yeminim-var-orhan-kutlu-p57fj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey çakallar sürüsü bu ne doymaz iştiha

Bebelerle mehmetlerin kanı yetmedimi

Büyük Yeminim vardır  Rabbim olan Allaha

Yaşamak haramdır sonuncunuz bitmedimi

İçimizde yaşattık  ermeniyi urumu

Dönmelerin Cümlesi kalleş nankörmü nankör

Ah Milletim ah hala göremiyor durumu

Bir aymazlık içindeler hem sağır hem kör

Nasıl doğduysa ondokuz mayısta bir güneş

Şaşırdı tüm dünya Türkün attığı silleye

Saklansın kim çekiyorsa bu vatanı peşkeş

Ya İstiklal Ya ölüm der Kuvvay-ı milliye.

Her şey Türk için Türk’e göre Türk tarafından

Yakışmaz bize emperyalin donu gömleği

Almasın canımı kurban olduğum Yaradan

Katillerin başına geçirmeden ilmeği

Ey düşman üstümdeki elbise kefenimdir

Vatan için her zaman çarpışmaya hazırız

Bütün sermayem yalnız Türklüğümdür dinimdir

Ne kadar yansakta külllerimizden doğarız', 'Hey çakallar sürüsü bu ne doymaz iştiha Bebelerle mehmetlerin kanı yetmedimi Büyük Yeminim vardır  Rabbim olan Allaha Yaşamak haramdır sonun...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeminim-var-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Artık Beni', 'anla-artik-beni-mahya-sultan-tosun-ey86z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle değil

Yüreğinle verdiğim bir savaş bu

Zaman zaman sıcak

Zaman zaman soğuk

Yılmadım

Yılmayacağım da

İşte sen bunu anlamıyorsun

Anlamak istemiyorsun

Kendini bana veriyorsun

Yüreğini vermek istemiyorsun

Vermeyeceksin de

Bilmek istemesem de

Duymak istemesem de 

Bu böyle biliyorum

Sonuçta ben

Seninle de yalnızım

Seninle de

Ne acı!', 'Seninle değil Yüreğinle verdiğim bir savaş bu Zaman zaman sıcak Zaman zaman soğuk Yılmadım Yılmayacağım da İşte sen bunu anlamıyorsun Anlama...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anla-artik-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varoşlarda Bir Aşk Hikayesi', 'varoslarda-bir-ask-hikayesi-erol-buker-ar1h2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben alamam bebek 

alamam sana ince topuklu ayakkabı

alsamda yürüyemezsin bu çamur deryasında

kaybedersin yolunu

kaybedersin bebek.

Biliyorum bu defa şaka yapmıyoruz

bu defa gercekten ayrılıyoruz

offf bebek offf.

Bir kavgada olsam şimdi en kalleşinden 

hani sırtımdan vursalar 

inan canım yanmazdı bu kadar

Beni düşünme 

ben yolumu bulmuşum giderim

ne çıkar sen yanımda olmasan

ellerini tutmasam

benim için üzülme

sevgisiz kalmam

ben  ikimizin yerinede severim



Nemi yaparım senden  sonra

bilmem ki hiç düşünmemişdim  sensizliği 

kimbilir yıllar sonra

mahellenin yeni sevdalanan gençlerine

hikayemizi anlatırım.

varosların leyla ile mecnunun hikayesini

Yarın gelin arabasında

mahalleden geçerken 

hani şu arkasında mutluyuz yazan

mahalleli seni uğurlayacak

gurur duyacaklar seninle

analar kızlarına dilek  tutarken

bebek gibi bahtı açık olsun diyecekler

ama benim neler çektigimi 

hiçmi hiç  bilmeyecekler.

oysa bir ben bileceğim

o arabanın içinde mutsuz olduğunu.

Senin gözlerin son kez beni arayacak

ama göremiyeceksin

ben bir köşede

gözyaşlarımı içime akıtarak

sessizce ağlayacağım bebek.

Her an seni düşüneceğim

düşündükçe düseceğim bebek

düseceğim  meyhane diplerine

yanıma yaklaşan her kadında seni arayacağım 

ama bulamayacağım

işte o zaman kahrolacağım bebek

kahrolacağım.

Ayrılık vakti geldi

birazdan gelirler seni almaya 

sil gözyaşlarını

bugün senin  en mutlu günün

bugün düğünün.

Hadi gül biraz

en cokda sana yakısıyor gülmek

güle güle git 

mutluluklar dilerim sana

güle güle bebek.', 'Ben alamam bebek  alamam sana ince topuklu ayakkabı alsamda yürüyemezsin bu çamur deryasında kaybedersin yolunu kaybedersin bebek. Biliyorum...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/varoslarda-bir-ask-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fındık Kabuğu', 'findik-kabugu-taner-nisanci-lksz0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne çok sevmiştim seni bir hatırla

Dön bak maziye var mı fındık kabuğu

Toplanıp gitmişsin binbir kahırla

Sözlerim ile dolar mı fındık kabuğu

Gülmüyorsam ben yüzüm solgunsa

Halimse perişan gönlüm yılgınsa

Terki viran senin akıl algınsa 

Sözlerim ile dolar mı fındık kabuğu

Senin üstüne ben,Gül mü kokladım

Gönül otağımda adın sakladım

Hallaştım derdimle özü yokladım

Sözlerim ile dolar mı fındık kabuğu

Kırmak istemezdim asla yüreğin

Çekip de gitmekmiş asıl dileğin

Belki oyunu bu bana feleğin

Sözlerim ile dolar mı fındık kabuğu

Gözümde tütüyor şimdi kızlarım

Boz boran kara kış yılda yazlarım

Ayrılık bestesi çalar sazlarım

Sözlerim ile dolar mı fındık kabuğu

Yıktın, geçtin öyle neymiş fırtına

Saçımda aklar var, varmam farkına

Akmak dileğimdi gönül arkına

Sözlerim ile dolar mı fındık kabuğu

Yüklendim omuza bütün dertleri

Gördüm acı tatlı nice sertleri

Halimi anlamaz dostun mertleri

Sözlerim ile dolar mı fındık kabuğu

Yeni sayfa açtım gurbet yolunda

Mutluluk ararım oğul balında

Sual eyleseler mevta salında

Sözlerim ile dolar mı fındık kabuğu

23/08/205', 'Ne çok sevmiştim seni bir hatırla Dön bak maziye var mı fındık kabuğu Toplanıp gitmişsin binbir kahırla Sözlerim ile dolar mı fındık kabuğu ...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/findik-kabugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybedeceksem', 'kaybedeceksem-mine-karabatak-e5daw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaybedeceksem sei; 

ne düşünmek mümkün

ne de nefes almak

ne gitmek için hazırlık 

ne de varmak için telaş...

ne düşünmek mümkün uğraşları 

ne de uğraşacak birşey bulmak.

ne bahara sevinmek

ne de hazırlığına başlamak güzün

ne silmek mümkün gözyaşlarımı

ne de susmaya sebep bulmak

yok içimde yaşamaya sevinç

ne de ölmeye takat

yarına kaybedeceksem seni

ne mümkün yarınlara umut bulmak

ya da bir umutla yaşamak..

Mine KARABATAK', 'Kaybedeceksem sei;  ne düşünmek mümkün ne de nefes almak ne gitmek için hazırlık  ne de varmak için telaş... ne düşünmek mümkün uğraşları  n...', ARRAY['Türk Edebiyatı','Şiir','Mine Karabatak']::text[], 8.5, '{"poet":"Mine Karabatak","poet_slug":"mine-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaybedeceksem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin İki Yakası', 'hasretin-i-ki-yakasi-cenk-aksal-ebxl2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yalazlanmış 

kızgın bir kor yüreğim,

uçurumlar 

girmiş te vuslatımız arasına,

sen bir yakada 

ben bir yakada

çaresiz gözlerle bakışıyoruz,

fincancı katırları,

geçiyor uzaklardan aheste,

hasret türküleri yankılanıyor

kulaklarımda,

gözlerin batıyor sanki gözlerime..

yıldızlar kadar parlak,

sen kadar uzak diyarlardan:

bir çift turna kanat çırparak,

süzülüyor uçsuzluğuna gecenin,

nasıl da seviniyorum görsen,

ellerim kanatlanıp uçacakmışım

sanki uçurumun karşı ucuna..

patavatsız bir baykuş:

bozuyor birden sessizliği,

kötürüm kalmışım sanki

dizlerim bükülüyor çöküyorum...

öyle yumuşak ki,

oturduğum bembeyaz örtü,

sanki bulutlarda geziniyorum...

az önce geçen bir çift turna,

öyle yakın ki,uzatsam ellerimi,

kanatlarına değeceğim sanki,

öyle güzel ki gözleri:

biri sen biri benim sanki...

nasıl da mutluluk doluyor içim,

yüreğimde yalazından eser yok,

uçurumdan ötesi,

sanki küçük bir zeytin tanesi,

çevremde beyazlıklar çoğalıyor

binlerce pamuk yığılı sanki...

huzur la gözlerimi kapatıyorum,

bir başka alemdeyim şimdi...

kulağıma birisi fısıldıyor,

uçurum insanı oldun sende şimdi..

gülüyorum sessizce,nedensiz..

''''isyanlarım da olacak mutlaka''''

''''senden yana,uçurumumuza''''''

''''melül gözlüm sen sakın yılma''''

''''aşkımızı yükledim bir çift turnanın''''

''''vuslata çırpılan uzun kanatlarına''''

''''aramızda uçurumlar olsa da''''

''''belki bir uçurum dibin de''''

''''belki gökler de biryerler de''''

 buluşacağız mutlaka', 'yalazlanmış  kızgın bir kor yüreğim, uçurumlar  girmiş te vuslatımız arasına, sen bir yakada  ben bir yakada çaresiz gözlerle bakışıyoruz, f...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/hasretin-iki-yakasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusuf Ter (Pire Nuri )', 'yusuf-ter-pire-nuri-yusuf-ter-1j61n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaban elde gurbet yaşar

Göçer gider Pire Nuri

Engel bilmez engel aşar

Uçar gider Pire Nuri

Selam söyler Yusuf Ter’e

Sohbet kurar sıcak yere

Gönül verir yüz bin kere

Geçer gider Pire Nuri

Ormanların çınarından

Erciyes’in  kenarından 

Dost dağın pınarından

İçer gider Pire Nuri

Pire Nuri böyle dedi

Yusuf Ter’dir asıl adı

Damağında dostluk tadı

Saçar gider Pire Nuri

Pire Nuri bu ellerde

Namı gezer tüm dillerde

Gül misali gönüllerde

Acar gider Pire Nuri

Yusuf Ter

14/ 07/ 04  Türkiye

Saat 23:25 Imran / 

Not  bu şiirimi 

MP3 olarak  ekledim 

sesli dinleti için 

sevgilerimle yusuf ter', 'Yaban elde gurbet yaşar Göçer gider Pire Nuri Engel bilmez engel aşar Uçar gider Pire Nuri Selam söyler Yusuf Ter’e Sohbet kurar sıcak yere ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yusuf-ter-pire-nuri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatmadılar', 'anlatmadilar-murad-aktas-hpkid', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalında  açılan güller de solar

Bizim de aşkımız böyle soldu yar

Aşkımı kalbinden söküp attılar

Sana da aşk nedir anlatmadılar.

Ne zaman bitecek bu ayrılıklar

Gözlerim her zaman yaşlrla dolar

Kalbimde aşkımın hatırası var

Bize de aşk nedir anlatmadılar

Nedense aşkımız çok kısa sürdü

Bizler ağlıyorken eller güldü yar

Mecnunla leylanın sevgisi kadar

Bize de aşk nedir anlatmadılar', 'Dalında  açılan güller de solar Bizim de aşkımız böyle soldu yar Aşkımı kalbinden söküp attılar Sana da aşk nedir anlatmadılar. Ne zaman bit...', ARRAY['Türk Edebiyatı','Şiir','Murad Aktaş']::text[], 8.5, '{"poet":"Murad Aktaş","poet_slug":"murad-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlatmadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Melek', 'uc-melek-sezai-sengonul-g8ydn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökten

Üç elma yerine

Üç misket

Bombası düştü

Biri Ramallah da

Biri Grozni de

Biride Körfezde

Uyuyan çocuğun

Düşüne

Parçalandı 

Uykuları

Yarım kaldı

Sıcacık sabi gülüşleri

Düşledikleri gibi olmadı

Düşleri

Yangını annelere

İçlerine su serpmek

Gözlerine düştü

Çocuksuz kaldı

Kimlere küstü

Kimlere kin kustu

Üç Melek.', 'Gökten Üç elma yerine Üç misket Bombası düştü Biri Ramallah da Biri Grozni de Biride Körfezde Uyuyan çocuğun Düşüne Parçalandı  Uykuları Yar...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uc-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arındım Bak', 'arindim-bak-nalan-kahraman-k1ncr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bitirmek, 

dünü yok saymak, 

her yeni güne başlar gibi, 

hayata yeniden başlamak, 

yarını beklememek, 

ummamak, 

noktalamak 

ve……

hemen ardından satır başı yapmak gibi 

bir bitirmek mi? ? 

mantığımı koydum rafa geldim bu kez, 

iyiyi, 

doğruyu, 

eğriyi, 

büğrüyü, 

kötüyü, 

çirkini, 

bakmadan,

görmeden, 

at gözlüklerimi de fırlatıp attım, 

gemlerimi de, 

bol virgüllü, 

ruhumla, 

geldim bu kez sana. 

kabul buyurursanız, 

o içten, 

o samimi, 

o haykırışlarla gelen 

evetlere karşılık 

arındım bak.....', 'Bitirmek,  dünü yok saymak,  her yeni güne başlar gibi,  hayata yeniden başlamak,  yarını beklememek,  ummamak,  noktalamak  ve…… hemen ardı...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/arindim-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilendi', 'bilendi-sezai-sengonul-uqgrs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdim yürekten

Uyumadım günlerce

Sensiz gecelerde

Sessiz gecelerde

Sevgin yaktı

Özlemin yaş oldu

Taştı gözümde

Aktı dinmeden

Kimse bilmeden

Kimse silmeden

Umudumu kesmedim

Kanadı yaram

Dağladım

Ben ağladım

Bel bağladım

Acıdıkça canım

Seni aradım

Hıçkırdı gönlüm

Kederinden derinden

Yalnız ben dinledim

Yalnız ben inledim

Kök gibi söküldü

Dalları büküldü

Ezildi büzüldü

Kopmadı direndi

Yaprakları döküldü

Bir kök kaldı derinde

Yaralı ezik

Bıkmadı dönmedi

Gönül sevdandan

Bilendi.

(Anemon isimli kitabından)', 'Sevdim yürekten Uyumadım günlerce Sensiz gecelerde Sessiz gecelerde Sevgin yaktı Özlemin yaş oldu Taştı gözümde Aktı dinmeden Kimse bilmeden...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bilendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Bahçem', 'dus-bahcem-nalan-kahraman-oixnt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşasııınnnn…… 

artık benimde bir düş bahçem var 

arkadaşımdan, 

yıldızlara, 

yıldızlardan 

gözlerime, 

gözlerimden 

bahçemize, 

uzanan 

parıl,parıl, 

pırıl,pırıl, 

ruhumla 

ruhumuzla, 

özlemlerimle,

özlemlerimizle,

duygularımla, 

duygularıımızla, 

veee

arzularımla, 

arzularımızla, 

dört bir yanına döşenip, 

parıltılar saçtığım,saçtığımız bir bahçemiz.

düş bahçem,

Düş bahçemiz.', 'Yaşasııınnnn……  artık benimde bir düş bahçem var  arkadaşımdan,  yıldızlara,  yıldızlardan  gözlerime,  gözlerimden  bahçemize,  uzanan  par...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dus-bahcem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Kent', 'yitik-kent-ozgur-celik-zvl39', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu ilk şiir değil ardından 

bir çocuk kadar masum 

bir cellat kadar zalim 

gözlerine yazılan... 

gözlerin ki; 

yitik bir kentin sokakları gibidir, 

örselenmiş 

yürüdükçe 

canımı acıtır dökülen ceviz yaprakları 

rüzgar bir hışımla geçer 

saçlarının kokusunu getirir 

o an 

ölüm öyle büyük bir özlemdir ki içimde 

anlatamam...', 'bu ilk şiir değil ardından  bir çocuk kadar masum  bir cellat kadar zalim  gözlerine yazılan...  gözlerin ki;  yitik bir kentin sokakları gi...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yitik-kent-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Güne Bir Mektup 1', 'her-gune-bir-mektup-1-mehmet-haluk-hisli-vaeie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...

İnternet arkadaşlıkları bir ilanla başlar. Pek farkı yoktur; eski zamanlardaki tanışmalardan ve yaşananlardan, yalnızca teknoloji değişmiştir. Duygular, düşünceler hayatta nasılsa orda da öyledir. İnsanların hayat karşısındaki duruşları neyse burada da öyledir. Neden mi, çünkü sözcükler ve cümleler aslında bizizdir, ne kadar saklamaya çalışırsak çalışalım kendimizi, onlar bizi ele verir; okumasını bilen dikkatli bir okuyucudan kaçamayız. Yani kısaca değişen yalnızca  tekniktir. 

Bir ilanla başlar yazışmalar…

İlan

kadınlar yazın bana, birlikte öpelim hayatı, hoyrat ama aşk dolu bir ağızla... rüzgarlarımız serinletsin içimizi, ateşimiz ısıtsın... ve hayat aksın bütün damarlarımıza ağız dolusu bir coşkuyla... HAYDİ YAZIN BANA! ! ! ... 

ISLAK GÜL 

”Seninle paylaşmak uykularda en büyük günahları 

Seninle uyanmak nice çılgın gecelerden sonra 

Alır götürür beni kokun uzaklara en uzaklara 

Ağzın dudaklarimda ıslak bir güldür sabahları 

Tenin çekiyor beni tenin tutmuş saçlarımdan

Afrikali kölenim senin, esirinim, mecburunum 

Gozlerin değmese gözlerime kahrolurum 

Ölürüm çekersen ellerini avuçlarımdan 

Dönsün başım tutuşsun damarlarımda kanım

Gel otur yanıbaşıma erişilmez kadınım 

Yum iri gözlerini, devir kirpiklerini 

Ser önüme bir hazine gibi güzelliklerini 

Sana en muhtaç oldugum şu anda gel 

Yaşamak olsan da gel, ölüm olsan da gel.”

...', '... İnternet arkadaşlıkları bir ilanla başlar. Pek farkı yoktur; eski zamanlardaki tanışmalardan ve yaşananlardan, yalnızca teknoloji değişm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/her-gune-bir-mektup-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 10', 'guncel-beyitler-10-huseyin-avdic-xgy5v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aradigini Bulacagin Yer

Bekâyi fenâda arama dostum, fena olursun.

Aradigini ancak öteye inancta bulursun.

******

Acsin

Dünyaya doymazsin,

Cünkü âhrete acsin.

******

Olmasaydi A$k Ve Sevgi

Evrendeki denge ve düzen, kaynaklanir a$k ve sevgiden.

Olmasaydi seven, sevilen; yikilir giderdi bu evren.

******

Allahsiz Sevgi Sahteliktir

Allah''i bilmeyenin bilgisi, bilgisizliktir.

O''nu sayip sevmeyenin sevgisi, sahteliktir.

******

''Iyi Yolculuklar'' Diyemem

Sen bir yolcusun; fakat cehenneme, ate$e dogru gidiyorsun.

Sana ''iyi yolculuklar'' diyemem, cünkü Rabb''a kul olmuyorsun...

Berlin, Agustos 2005.', 'Aradigini Bulacagin Yer Bekâyi fenâda arama dostum, fena olursun. Aradigini ancak öteye inancta bulursun. ****** Acsin Dünyaya doymazsin, Cü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guncel-beyitler-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbret Tablosu', 'i-bret-tablosu-omer-arslan-71i1y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İBRET TABLOSU

	Çileden büküldü belimiz

                Zulümden kırıştı yanaklarımız

                Birer ibret tablosudur

                Saçımızda aklarımız.

                Allah’ı anmak için yaratılmıştır

                Çürüsün ama el öpmeye uzanmaz

                Dudaklarımı.

	Yardım beklemeyiz dosttan akrabadan

	Yakından ve   uzaktan

	Dualarımız kabul olur

	Bize yardım gelir haktan.

	Kör olur gözümüz,haya ederiz

	Hayasızlara bakmaktan.

                                   Şerare ve Şule

                                 http://sairarslan.sitemynet.com', 'İBRET TABLOSU 	Çileden büküldü belimiz                 Zulümden kırıştı yanaklarımız                 Birer ibret tablosudur                 ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ibret-tablosu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın belki', 'yarin-belki-sair-yatakkusu-na6ja', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarın dönersin belki

Ben de açarım kapıyı

Birşeyler olmamış gibi

Tek bir laf etmeden

Ellerim poponda

Tek bir laf etmeden

Kapının arkasında

Seni öperim

Belki', 'Yarın dönersin belki Ben de açarım kapıyı Birşeyler olmamış gibi Tek bir laf etmeden Ellerim poponda Tek bir laf etmeden Kapının arkasında S...', ARRAY['Türk Edebiyatı','Şiir','Şair Yatakkuşu']::text[], 8.5, '{"poet":"Şair Yatakkuşu","poet_slug":"sair-yatakkusu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yarin-belki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağları Bilirler', 'daglari-bilirler-memet-karabalik-boj82', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Selam verdiğim bir sabah vakti

Henüz oyuna çıkmayan çocukların bağırtılarını duymadan daha

Koşmaya hazır bir bacak taşımıyorum

Tükenemeyen yollarını sonunu görür gibi

Sorgulanmadan geçecek bir günün mutluluğunu bilmek istiyorum

Güneşin kavruk çocuklarını tanıyorum ben

Avuçlarındaki taşları saydım

Meta Sute’nin kovalayamadıklarını bilirim ben

Şakıro’nun türkülerini dinleyerek büyüdü onlar

Her yeni güne eski ve yırtık kazakları ile başladılar

En çok dağları bilirler

En çok da vurulmayı esmer tenli Kürt kızlarına

Bir de vuruşmayı düşman bildikleri ile

Rüzgara tutulmuş bir puşinin serinliğine sarılırlar

Sarmaş dolaş  olmayı  zaferden  sonra  hatırlarlar

Biri aşkını  söylemeye görsün

İdam saati kurulur dağlara

İnlemeyi bile onursuzluktan soyarlar

Kurşuna gelen yerleri şerefleridir

Bu bir dağ hikayesidir

Halaya durmuş bir avuç yürektir

Bir minik yürekte çarpar

Bir koca isyandır aleme

Elini ateşe sarmaktır

Kimseye değil şehre isyandır

Şaşı bakan gözlere acı manzaralar sunarlar

Şehre bakmaz gözleri

Şeytanın vazgeçtikleridir

Günahın değil

Güneşin kavruk çocuklarıdır onlar', 'Selam verdiğim bir sabah vakti Henüz oyuna çıkmayan çocukların bağırtılarını duymadan daha Koşmaya hazır bir bacak taşımıyorum Tükenemeyen y...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/daglari-bilirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak', 'kacak-omer-arslan-l5jhn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatın yükü gibi omuzlarımda

	Kaçak şalım

	Demlikte kaçak çayım

	Damarlarımdaki kan kadar 

	Sıcak olmasa da

	Tabakamda kaçağım

	Ve ben kaçağım

	Demlikteki çayın buharıyla

	Sigaramın dumanının karıştığı an kadardır

                                                Mutluluğum…….

	Kanadı kırık bulut gibiyim

	Çekip gidecek cesaretim yok

	Mücadele edecek gücüm de

	Rüzgarla

	Bak saclarımı dağıtıyor

	Duygularım dağıttığı gibi

	Bana ancak ağlamak düşüyor

	Ve ben kaçağım

	Kendimden kaçıyorum

	Ve aşktan

	Ne kadar kaçacaksam

                                          (Şerare ve Şule)  Şiirler

                http://sairarslan.sitemynet.com', 'Hayatın yükü gibi omuzlarımda 	Kaçak şalım 	Demlikte kaçak çayım 	Damarlarımdaki kan kadar  	Sıcak olmasa da 	Tabakamda kaçağım 	Ve ben kaça...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kacak-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun İşte!', 'yoksun-i-ste-burhanettin-akdag-pmtje', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine yoksun aşkım, 

Ne hayalimde

Ne beynimde

Ne yüreğimde

Ne de tenimde

     

         Yoksun işte! Sensizim! 

Yine yoksun aşkım,

Ne heyecanımda

Ne soluğumda

Ne dermanımda

Ne de sabrımda

       Yoksun işte! Sensizim

Yine yoksun aşkım,

Ne gecelerimde

Ne sevincimde

Ne inadımda

Ne de kavlimde

       Yoksun işte! Sensizim! 

Yine yoksun aşkım,

Ne gözlerimde

Ne gözyaşımda

Ne yıkılışımda

Ne de acılarımda

       Yoksun işte! Sensizim! 

Yine yoksun aşkım,

Ne hüznümde

Ne gururumda

Ne yangınımda

Ne de isyanımda

       Yoksun işte! Sensizim! 

Yine yoksun aşkım,

Ne grubun kızıllığında

Ne çağlayanın hiddetinde

Ne gülün kokusunda

Ne de kalbimin yamacında.

    Yoksun işte! Sensizim! 

(28.09.2004)', 'Yine yoksun aşkım,  Ne hayalimde Ne beynimde Ne yüreğimde Ne de tenimde                Yoksun işte! Sensizim!  Yine yoksun aşkım, Ne heyecan...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yoksun-iste-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör oldum sende', 'kor-oldum-sende-melek-bagac-9gk73', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kayboldum seni severken sende 

oysaki bir cok seyi görmüyordum

seviyor ve inaniyordum

zamanla kendimi buldum

görmediklerimi görmeye basladim

icim acidi kirildim

kirginligim geciyor derken

seni tanimaya baslarken 

bu kez yikildim

yasarken görmediklerimi

gördügümde anlamaya calistim

nedenler aradim

hatami aradim ama bulamadim

simdi düsünüyorum

bir cözüm bulamiyor

mantikli olmaya calisiyor

duygularima yeniliyorum

senden vazgecmem 

seni unutmam 

yeni bir sayfa acmam gerekiyor

ikilemler icinde cok canim yaniyor

noktalamaya calisirken

seni aslinda ne kadar sevdigimi görmek

senin ne kadar önemli oldugunu hissetmek

beni tarifi imkansiz duygulara itiyor

biliyorum

herseye ragmen 

seni dünde birakip

yeni bir yarina yelken acarken

bugünün acisini dünde birakmam gerekiyor

28.03.05  22:36', 'kayboldum seni severken sende  oysaki bir cok seyi görmüyordum seviyor ve inaniyordum zamanla kendimi buldum görmediklerimi görmeye basladim...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kor-oldum-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus! ....', 'sus-ugur-deniz-ulkegul-unejw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sus! 

Dudaklarında kalsın gülüşüm

Sessizliğine göm beni, yüreğine

Say ki henüz uyanmadığın bir düş''üm..

Bir martı sesiyim Denizlere sevdalı

Ay ışığıyım usulca pencerene vuran

Bir şiirim sözleri gözlerine prangalı

Esip gidişiyim rüzgarın, saçlarına dokunan...

Zaman Sus! 

Özleminde yer tutsun, bıraktığım iz

Bildiğine yor beni, yüreğine sor

Üzeri küllenmiş kor, yenildiğimiz...

Kim ki yol keser menzilime

Hangi soysuz tetik düşer gölgeme

Ölür mü şair, yiter mi aşk

Yeter mi sustuğum söz, sensizliğime..

Sus! 

Kıyına çarpan dalga seslerimi dinle

Kumlara basan çocuğun ayak iziyim

Balık tutan adamın efkarındayım ben

İçinde haykıran sesin, sessizliğiyim...

Sus! 

Belki yarında saklıdır umut dediğin

Dokunmasız aldanışlar vaktinde gün

Duyulmaz sanma ey can, her söylediğin

Ağladığın benim, benim güldüğün..............................', 'Sus!  Dudaklarında kalsın gülüşüm Sessizliğine göm beni, yüreğine Say ki henüz uyanmadığın bir düş''üm.. Bir martı sesiyim Denizlere sevdalı ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sus-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Moskova''da Sabah Oluyor', 'moskova-da-sabah-oluyor-memet-karabalik-5ov8e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Moskova''da sabah oluyor

Uykumun en derin yerinde çalıyor çanlar

Bir minicik yalnızlık uçuyor benden

Bir insan kapımı çalıyor

Bir yerlerde kalem çatırdıyor

Bir kefende burada dikiliyor

Mecnun’un sustuğu yerde bitiyor silah

Aşk bir kurşunda görünüyor

Leyla’nın vurulduğu yerde mecnun ölüyor

Bir kör masal anlatıyor

Masalda körler ölüyor

Köhne bir vapur yanaşıyor

Ben bekliyorum

İçinden inecek bir sevgilim yok oysa

İçime içime sığınıyor yalnızlık

Bir koca şehir

Bir minik yalnızlık

Bir zavallı ben

Moskova’da sabah oluyor', 'Moskova''da sabah oluyor Uykumun en derin yerinde çalıyor çanlar Bir minicik yalnızlık uçuyor benden Bir insan kapımı çalıyor Bir yerlerde ka...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/moskova-da-sabah-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderimisin desem', 'kaderimisin-desem-melek-bagac-d0myy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gitme desem gitmez misin

gitmeyip gözlerime bakarmisin

bakipta görürmüsün

görüpte gülümser misin

gel desem gelirmisin

gelipte sararmisin

saripta sever misin

sevipte benim olur musun

kal desem kalir misin

kalip beni tamamlar misin

tamamlayip saklarmisin

saklayip iyi bakarmisin

bakip bir ömür gecirir misin

kaderimsin  desem

gitmez

gelir 

kalir misin

16.08.05

23:41', 'gitme desem gitmez misin gitmeyip gözlerime bakarmisin bakipta görürmüsün görüpte gülümser misin gel desem gelirmisin gelipte sararmisin sar...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kaderimisin-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin icin', 'senin-icin-melek-bagac-q2buj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ara sonra yine cikip geldin

Ilk zamanlardaki gibi güzeldi

Ilgin sevkatin sicacikti

Alismistim yine sana

Sonra bir zaman gecti

Hala hersey ayniydi

Hislerin düsüncelerin

Hic birsey degismemisti

Zaman gecip giderken

Icime bir sikinti girerken

Yine senin gidisine hazirlanirken

Sessiz seyretmek zordu

Bir ara sonra yine cekip gittin

Sen öyle istiyorsun diye

Alisirim diyor

Eksik hissetsemde

Senin icin sessiz kaliyorum

28.01.2005

22:30', 'Bir ara sonra yine cikip geldin Ilk zamanlardaki gibi güzeldi Ilgin sevkatin sicacikti Alismistim yine sana Sonra bir zaman gecti Hala herse...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/senin-icin-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köysüzlük Öldürür Adamı', 'koysuzluk-oldurur-adami-memet-karabalik-cys7n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I.

Soğuk bir güne merhaba demiyor kimse

Gri bir asfalt götürüyor sevincimizi

Fabrikalara sokulmuyor umutlarımız

Uzayan sakalımızı kabul etmiyor şehir

Secdelerimizi çalıyor mesailer

Kaçsak, ayaklarımızı bırakmıyor kravatlar

II.

Yemyeşil ovaları yok şehrin

Çocuklara kahkaha alanı yok

Bir ırmak kendini aştı mı felaketi oluyor şehrin

Ölsek, gömerler mi toprağa? 

III.

Ne zaman bir köy yeri anlatsa birİ

Sabaha duran yerlerim acır

Ne zaman bir köylü geçse caddeden

Cadde tuz buz olur yağar üstüme

IV.

Mezarımı gömdüm kalbime

Yitik köylerin ardından

V.

Bir deli gömlek örter beni

Bir ucube isyan sarar şehri

Bir kol düğmesidir kopar benden

Bir karış yol kalmış seyrine ölümün

VI:

Bazı, şehre dalar elim

Bir fahişe ihanet bulurum

Bazı, şehre bakar gözüm

Bir yitik köydür bendeki', 'I. Soğuk bir güne merhaba demiyor kimse Gri bir asfalt götürüyor sevincimizi Fabrikalara sokulmuyor umutlarımız Uzayan sakalımızı kabul etmi...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/koysuzluk-oldurur-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Methiye', 'olume-methiye-memet-karabalik-xem73', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölüm güzeldir

İnadına yaşıyorken

Ölmek 

Yıkarken kirlenen hayattır

Koşarken tükenen bizdir

Yoksa, bir tüketim malı değildir asfalt

Bir gülü okşamaktır sevgili 

Ve sevmek sevgiden ölmektir

Bülbül gülü sevmemiştir oysa

Türküye yakışan mekandır

Bülbül mekanı sevmiştir yani

Uyku hiç de ihtiyaç değildir 

Aslolan hayattan kaçmaktır belki

Su içmek zahmettir 

Yemek, çin işkencesi

Neden susadığını bilir mi insan? 

Acıkmak,

Ölümü arzulama biçimi olamaz mı yani? 

Ölüm güzeldir

Ölmek hayattır.', 'Ölüm güzeldir İnadına yaşıyorken Ölmek  Yıkarken kirlenen hayattır Koşarken tükenen bizdir Yoksa, bir tüketim malı değildir asfalt Bir gülü ...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olume-methiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Geçmek', 'senden-gecmek-sezai-sengonul-aq7la', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kolaymı sandın

Tutulmaz olanı tutmayı

Çiğnemeden lokma yutmayı

Kolay mı sandın

Kurşun delmişken

Nefes almayı

Kolay mı sandın

Dikenli güle dokunmayı

Kokusunu almayı

Ve o gülün

İçine sinmiş

Kokusunu çıkarmayı

Kolay mı sandın

Severken gülü

Dikenini kandırmayı

İçindeyken güneş

Kavuruken yavaş yavaş

Kurtuluşmu sandın

Gölgede olmayı

Kolay mı sandın

Senden ayrılmayı

Seni unutmayı!', 'Kolaymı sandın Tutulmaz olanı tutmayı Çiğnemeden lokma yutmayı Kolay mı sandın Kurşun delmişken Nefes almayı Kolay mı sandın Dikenli güle do...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senden-gecmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur davulcu davula', 'vur-davulcu-davula-ali-riza-unal-8ok5i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vardım evlerine haz bulamadım

Kevdime göre naz bulamadım

Çal zurnazı zurnayı vur davulcu davula

Kendime göre kız bulamadım

deli karı hased oldu yar olamadım 

el deliyi ben akıllıyı bulamadım

çal zurnacı zurnayı vur davulcu davula

kendime göre kız bulamadım.

      ******************************

-bizde bir değişiklik olsun diye türkü söyleyelim dedik

 ha nasıl oldu acep

sakın ibrahim duymasın.', 'Vardım evlerine haz bulamadım Kevdime göre naz bulamadım Çal zurnazı zurnayı vur davulcu davula Kendime göre kız bulamadım deli karı hased o...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vur-davulcu-davula-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçeklerim', 'gerceklerim-caglar-demir-6mkst', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İzmirdeyim

Karadullar ağlıyor

Yağmur yağıyor 

Bu sehir sen kokuyor

Bu sehir ayrılık kokuyor

İliklerim ayrılıyor 

lime lime birleşiyorum sonra

Seni düşünüyorum 

Nikotin bastım yaralarıma 

Bu sehrin kanattığımız yanlarına tükürdüm

Yürüdüğümüz yollardan,

Ömrümün üzerinden,

Tinerli beyinlerden geçtim...

Rakım yazan tabelalarda 

yitirdim benliğimi

İyi bak bulursun belki

Perdeyi aralayıp dışarıya göz at 

Bahçende bir cocuk ölüyor 

Che prosunu içiyor

Fahişeler aşırı dozdan ölüyor

Bir oğlan çocuğu içten içe ağlıyor 

Yağmur yağıyor

Arap kızına tecavüz ediyor biri

İyi bak: Gerçekler pencerende sevişiyor 

İyi bak: Benim gerçegim 

senin pencerende başlıyor...', 'İzmirdeyim Karadullar ağlıyor Yağmur yağıyor  Bu sehir sen kokuyor Bu sehir ayrılık kokuyor İliklerim ayrılıyor  lime lime birleşiyorum sonr...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Demir']::text[], 8.5, '{"poet":"Çağlar Demir","poet_slug":"caglar-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gerceklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim O!', 'sevdigim-o-necla-i-lhan-stuat', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kızdığında köpürür

Denizler gibi hışımla

Sonra,durulur sessizce.

Gözlerine bakmak yeter

Bana olan aşkını anlatır gülünce.

Bazen bulut olur,

Sevda yağmurlarına gebe

Bazen fırtınadır ruhu özgürcesine.

Irmak olur bazen,

Akar yüreğime işlercesine.

Onu tanımak zordur

Sır dolu dünyasında

Seviyorum onu ölürcesine.', 'Kızdığında köpürür Denizler gibi hışımla Sonra,durulur sessizce. Gözlerine bakmak yeter Bana olan aşkını anlatır gülünce. Bazen bulut olur, ...', ARRAY['Türk Edebiyatı','Şiir','Necla İlhan']::text[], 8.5, '{"poet":"Necla İlhan","poet_slug":"necla-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdigim-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miras', 'miras-gokay-ciftcioglu-jfjum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni unutmak için

edilmiş bir sürü yemin

geride kalmış

seni unutmak

bir yalanmış 

bu sevdaya

gözyaşları

şahit gösterilmiş

ve geriye

bir tek

gözyaşları 

miras kalmış.', 'seni unutmak için edilmiş bir sürü yemin geride kalmış seni unutmak bir yalanmış  bu sevdaya gözyaşları şahit gösterilmiş ve geriye bir tek ...', ARRAY['Türk Edebiyatı','Şiir','Gökay Çiftçioğlu']::text[], 8.5, '{"poet":"Gökay Çiftçioğlu","poet_slug":"gokay-ciftcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/miras-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Söyle Be İhtiyar', 'hadi-soyle-be-i-htiyar-doner-ozeke-l0uov', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Söyle bana be ihtiyar 

Sevmeden ölünür mü? 

Bak işte seviyorum 

Adı ne denilirmi

Adını sorma bana 

Kırarım incinirsin 

Adını demem sana 

Ne olur susuta dinle

Derdini anlat bana 

Candan seni dinlerim 

Derdin ne diye sorma

Oturda beni dinle 

Çileden çıktım yine 

Bir defaki sefere 

Misafirim ol dinle 

Dert kimlerde var imiş 

Dinlede bana söyle 

                               

                       DÖNER ÖZEKE

                           27.082005', 'Söyle bana be ihtiyar  Sevmeden ölünür mü?  Bak işte seviyorum  Adı ne denilirmi Adını sorma bana  Kırarım incinirsin  Adını demem sana  Ne ...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hadi-soyle-be-ihtiyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Ara', 'simdi-ara-ahmet-kesici-fmiyj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum da,

İnsanı kendine bağlayan ne kadar çok şey var hayatta.

Örneğin,sigara.

Bırakmaya çalışıyorum.

Hiç içmek istemesem bile o hareketleri yapma ihtiyacı duyuyorum.

Cebimden paketi çıkarıp bir sigara yakmak.

O dumanı havaya salmak.

Sonra çöküp bir köşeye ayrıldığım sevgiliyi hatırlamak.

Nerede tanışmıştık,Neler yaşayıp bir gün nasılda ayrılmıştık.

Belki çok saçma bir sebepti.

Evet ben suçluydum.

Ama onun içinde haklı denmezdi.

Şu an onu çok özlüyorum.

Sadece şu an olsa iyi,işin kötü yanı onu bir an unutamıyorum ki.

Gülüşünü,sesini.

Olmadık yerlerde bir kedi gibi yanıma sokulup başını omzuma yaslamasını.

Bazen kızıyordum ama hoşuma da gidiyordu zamansız arayışları.

Şimdi arasam,

ve onu unutamadığımı anlatsam.

acaba konuşur mu benimle? 

Ya tersleyip de daha derinden acı verirse yüreğime.

Şuraya bak ya.! 

Bir zamanlar yaşadıklarımı,sevincimi,derdimi,kederimi,her şeyimi anlatıp paylaştığım kişiyi arayamıyorum bile.

Oysa el ele yürümüştük bu şehrin yüreğine.

Yağmur yağmıştı ıslanmıştık.

Sinemalara girmiş,birlikte resimler çektirmiştik.

Ne saf sevgiydi bizimkisi,ak,bak,

İhaneti aklımızdan bile geçirmemiştik.

Dostlarımıza aşk bulaştırmış,sevmeleri öğretmiştik.

Beraber ağlayıp,acılara göğüs germiştik.

Oysa şimdi yolda görse görmezlikten gelir.

Belki görürde bir merhaba deyip geçiştirir.

Aşk bumudur yani.? Sevmek böyle bir şey mi.? 

Böyle mi bitmeliydi.! ! ! 

Ooff Off.

şimdi arasam,

merhaba,eee,ben,şey için aramıştım.,

Biliyormusun,ben,seni unutamıyorum.

Şu an seninle ilk tanıştığımız yede,o ağaca yaslanmış oturuyorum.

Ve sana çok ihtiyacım var.

Şu an yanımda olmanı istiyorum.

Lütfen gelirmisin.? 

Geldi,evet geldi.

Ve benim yaslandığım ağacın ardına yaslandı.

Ve sordu.''''Ne işin var burada,beni unutmaya kararlı değilsin galiba''''

O an onu görmüyor,

sadece sesini duyuyor,fakat varlığını canımda hissediyordum.

Evet unu unutamamıştım.

Ve ayrı kaldığımız süre içersinde onu ne kadar çok sevdiğimi anlamıştım.

Ve yine sordu.

''''Başkasıyla çıktın mı''''.? 

Sorduğu sorular beni korkutuyordu.

Sanki birazdan kalkıp gidecekmiş gibi konuşuyordu.

Sanki o bir hakim,ben bir suçlu,beni yargılıyordu.

Tekrarladı.

''''Başkasıyla çıktın mı''''.! ! ! 

Evet.! ! ! 

Nasıl böyle bir hata yaptım.

Senin gülüşlerini,ellerinin sıcaklığını nasıl oldu da bir başkasında aradım.

Gerçi uzun sürmedi,oda anlamıştı zaten hala seni sevdiğimi.

Peki sen diye sorduğumda,

''''Ben o kadar aciz olmadım.

Başka biri,seni bana unutturamazdı ki''''diyerek yanıma yaklaştı.

Başını omzuma yasladı.

Ellerini tuttum.

Ve öyle sıkı tuttum ki sanki bir daha bırakmayacağıma yeminler edercesine.

Ve gözlerimiz güneşin batışına daldı.

Şimdi sıra sende.

Ayrıldıysan,

ve onsuz hayat senin için bomboşsa.

Herkes de onu arıyor,

fakat her seferinde hüsranlara çarpıyorsan 

şimdi sende sıra.

Onu hemen

...................Şimdi Ara...', 'Düşünüyorum da, İnsanı kendine bağlayan ne kadar çok şey var hayatta. Örneğin,sigara. Bırakmaya çalışıyorum. Hiç içmek istemesem bile o hare...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/simdi-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Damlıyor Gecemden', 'sensizlik-damliyor-gecemden-murat-nail-guney-y7f60', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak yine uykusuzum Akdeniz akşamlarında,

Buğulu gözlerinle çıkıyorsun düşlerime,

Gözümü yumduğumda karanlığı boğuyorsun,

Kor ateş düşüyor özlemin yüreğime,

Ben yandıkça sen soğuyorsun...

Sigaramın dumanında sen,

Kahvemin telvesinde sen,

Bak kalemim bile vazgeçmiyor senden,

Sıksam sen fışkıracak her satırımdan, hecemden...

Mumlarım tükendiğinde, 

Ateş böcekleri aydınlatıyor kuytuları.

Yıldız alacalarında bir garip oluyor yüreğim,

Sen beni unutsan da, ben seni hep seveceğim...

Seni haykırıyorum karanlıklara,

Ay ışığı gizleniyor Mor dağlara hicabından

Yakamozlar öksüz kalacak bu mevsimde,

Falezlerde yankılanıyor martı çığlıkları,

Dalgalar bir başka hırçın dövüyor sahili,

Sensizlik damlıyor gecemden; 

Ey Akdenizin en şahane kızı:

Seni Özlüyorum....Özlüyorum...Özlüyorum...

murat nail güney

25/08/2005    Anamur / Mersin', 'Bak yine uykusuzum Akdeniz akşamlarında, Buğulu gözlerinle çıkıyorsun düşlerime, Gözümü yumduğumda karanlığı boğuyorsun, Kor ateş düşüyor öz...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sensizlik-damliyor-gecemden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kehanet', 'kehanet-kerem-kayar-dzg5a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kehanetler, sarıyor uyuklayan gölgelerimi...

Gözlerime inen,

Yağmur kuşları kaçışlarım oluyor...

Gidiyorum yaşlanmaya,

Oysa dün çocuktum ve masum düşlerim vardı....', 'Kehanetler, sarıyor uyuklayan gölgelerimi... Gözlerime inen, Yağmur kuşları kaçışlarım oluyor... Gidiyorum yaşlanmaya, Oysa dün çocuktum ve ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kehanet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrep ölümde', 'akrep-olumde-kerem-kayar-uaacy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesleri birbirine karışan martılar,

Çılgınca kumsalla sevişiyor dalgalar.

Elinde köpek öldüren şarabıyla,

Hayatı unutmaya çalışan sarhoşlar...

Ve öte yanda—

Bir dilim ekmeğe muhtaç,

Ağlayan çocuklar.

Ey hayat!

Sevgi devrimini kaybetti.

Belki de bundan sonra

Aşkın hiçbir anlamı kalmadı.

Bir zamanlar sevgiyi kutsal sayanlar,

Önünde diz çökenler...

Şimdi birer birer

Denize dökülüyorlar—

Bir veda gibi.

Küflenmiş sayfalarda

Rafa kaldırılmış aşk masalları...

Dört duvar arasında asılı

Donmuş bir karede

Kilitli kalmış sevdalar.

Nerede kaldı

Önünde diz çökülecek sevgiler?

Kıblesini arayan yürekler

Öylesine yorgun,

Öylesine umutsuz ki—

Sanki ruhlarını teslim etmeden

Ölmüşler.

Bedenler buz kesmiş,

Aşklar yosun tutmuş.

Suyun dövdüğü taşlar gibi

Sessiz...

Şimdi biz,

İçimize hapsettiğimiz sevgiyi

Arar olduk yeniden.

Bekliyoruz...

Belki bir Süleyman çıkar,

Koparır zincirleri.

Belki bir asa dokunur

Taş kesilmiş yüreklere.

Ama gelmiyor.

Ne Süleyman var,

Ne de bir asa.

Belli ki bu da

Bir ayrılık.

Ve bu kez

Hiç dönmeyecek.

Oysa şimdi

Saatin akrebi

Yalnızlığı gösteriyor,

Yelkovanı ise

Ölümü.', 'Sesleri birbirine karışan martılar, Çılgınca kumsalla sevişiyor dalgalar. Elinde köpek öldüren şarabıyla, Hayatı unutmaya çalışan sarhoşlar....', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/akrep-olumde-evrime-ugrayan-askti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İz', 'i-z-kerem-kayar-gzce6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatın vitrininden 

gitmek alıyorum 

paha biçilmez yaşantımdan 

veda mı alıyorum omuzlarıma 

Serinlik tadında şimdi günler 

bu son şiir 

yazmadım bir yere 

yazılmayacakta 

yüzünü çiziyorum boş tuvale 

pastel renklerden bir gülüş 

konduruyorum dudağının kenarına.. 

Ağırlaşıyor aciz bedenim 

sen el sallama 

gidişlerime, 

yarım sigara paketim 

çakmağım bile yok elinde 

çetelesini tuttuğum dip notlarımda 

bir bu şiir kalacak sana ardımdan 

yüreğin hafifler belki 

değdikçe bu şiire.. 

Gece üzerine üzeri ne çökünce 

belki elin telefona gidecekte 

defalarca 

olmayan numaramı çeviremeyeceksin 

kahretmesin bu seni 

sen boşluğa konuş 

olmadığım zamanlarda 

ben duyarım bütün sağırlığımla.. 

İçine bağdaş kuran ayrılığım 

incitmesin seni 

tüm ettiğin sitemleri 

unut gitsin 

ben çoktan unuttum bile 

bir sözünü defnedemedim içimden 

bir sözün ölü gibi dudak aralarımda 

buz kesiyor, 

sen biliyorsun onu 

söylemeyeceğim 

unutturacağım kendime 

ama sen unutma (...)', 'Hayatın vitrininden  gitmek alıyorum  paha biçilmez yaşantımdan  veda mı alıyorum omuzlarıma  Serinlik tadında şimdi günler  bu son şiir  ya...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/iz-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şurda Duran Benim', 'surda-duran-benim-volkan-yoruc-m2yg1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızım, şurda duran benim

Saat bilmem kaç olmuş, umurumdamı

Yalnızım ve üşümekteyim

Gözlerim arar gözlerini

Kulaklarım duymak ister sesini

Ya ellerim? 

Yalnızım, üşürken senin ellerini hayal ederim

Sonra gözlerini

Sesini

Ve gülümseyişini

Yalnızım, şurda duran benim

Üşüyende, özleyende

Ve seni düşleyende

Kadere isyanım yok, çekerim

Sensiz bilmem şu geceyi nasıl geçiririm? 

Ve hala yalnızım, şurda durupta bekleyen benim

25/08/2005 saat: 04:21', 'Yalnızım, şurda duran benim Saat bilmem kaç olmuş, umurumdamı Yalnızım ve üşümekteyim Gözlerim arar gözlerini Kulaklarım duymak ister sesini...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/surda-duran-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara kaşların', 'kara-kaslarin-atilla-gozukucuk-o6d1w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kara kaşların yaktı beni

sevdana attı beni

iflah etmez bu dert beni

vay beni beni', 'kara kaşların yaktı beni sevdana attı beni iflah etmez bu dert beni vay beni beni...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kara-kaslarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Şimdi Anlarım Yada..', 'ya-simdi-anlarim-yada-volkan-yoruc-6qyey', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabahın ilk ışığı vuruyor balkonumun kıyısından

Ya şimdi anlarım yada bir daha gelmez belki bu an

Güneşi bekliyorum

O Issız bekleyişteyim işte anlarsan

Sen güneşi yakaladınmı böyle mahmurken? 

Soğuğa bakmazsızın usanmadan

Şimdi sabahın en bebek olduğu zaman

Ya şimdi anlarım yada bir daha gelmez belki bu an

Elalem uyku tünellerinde

Elalem düşler ireminde

Ben ise loş karaltıda beklemede

Artık yıldızlarda silik hayallerde

Hala ben hayata yeni ümitlerle güneşi bekliyorum

Ve bugün acaba kaç saniye mutlu olucam, bilmiyorum', 'Sabahın ilk ışığı vuruyor balkonumun kıyısından Ya şimdi anlarım yada bir daha gelmez belki bu an Güneşi bekliyorum O Issız bekleyişteyim iş...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ya-simdi-anlarim-yada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırdım Kalemi mi', 'kirdim-kalemi-mi-atil-kesmen-13w97', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmiştim

Hem de  gönül gözlerimle

Neler oldu, neler dokundu gönlüme

Yıkıldım kendim de 

Gidiyorum sensizliğine

Bir tuhafım artık bu gündüz ve gecelerde

Yüzüm de bir hüzün gölgesi

Adımların kısa düşüyor gönlüm de

Tutunamıyorum bir türlü

Hayat dallarına

Sinsi esen meltem rüzğarları ıslaklığı

Nefesimi kesmiş

Dalıp dalıp gidiyorum

Sevdamın karanlıklarına

Zindan soğukluğu esiyordu

Çaresiz gönlüm de

Seven gözlerim de 

Seni saklasam da

Yıkılıp gidiyordum senin gerçeklerinle

Evet…

Yoğundum artık

Ve kırmıştım kalemi mi

Yakıp yırtmıştım tüm beyaz sayfalarımı

Yoktun ve olamazdın

Benim ne bir beyaz sayfam da

Ne de

Seni yazacak bir kalem ucum da

Bir zamanlar

Seni

Zamansız 

Zaman saatine saklamıştım 

Gönül nefesimle yıkamıştım

Kalp atışlarımla beslemiştim

Sevgi çiçekleri kokusun da

Acılarını sevmiştim

Sen ise

Beni

Aşk rehberine çevirmiştin

Sayfa sayfa açılıp okunacak

Sonra da

Bir kenarıya fırlatıp atılacak

Aşk sofrasında sevmiştin

Bundan böyle

Yüreğim de hiçbir sevdaya yer yok

Görmüyormusun? 

Gözlerim bomboş titriyor yüreğim de

Kırdım kalemi mi 

Yaktım yırttim tüm beyaz sayfalarımı

Yoksun ve olamassın artık 

Gidiyorum

Nefes alıp güç vereceğim güzelliklere

Ne olur

Sakın gönül koyupta kırılma bana

Boş ver

Beni unut gitsin

Sana estikçe

Senin anlaşılmaz düşüncelerinde gezdikçe

Tıkanıyordu gönlüm sen de

Gülmeyi değil

Hep ağlamayı öğremdim gözlerim de

Sevmiştim

Sevmedim diyecek olursam

Yalan olurdu

Sen de yanan asil gerçeklerim

Seni

Yıllanmış nefesimle

Bıçak sırtın da yarğıladım

Gönül fermanım olarak hep seni yazdım

Şah, padişah gibi seni gönlümde ağırladım

Ama…….Ne yazık ki

Kalemi mi sende kırdım

Beyaz sayfalarımı sende yakım

Yoksun ve olamassın

Görmüyor seni gözlerim

Duymuyor artık sesini kulaklarım

Yazmiyor

Yazmiyor

Evet yazmıyor

Senin için

Beyaz sayfalarım da nöbet bekleyen

Damla damla

Sen akan kalem uçlarım…………….', 'Sevmiştim Hem de  gönül gözlerimle Neler oldu, neler dokundu gönlüme Yıkıldım kendim de  Gidiyorum sensizliğine Bir tuhafım artık bu gündüz ...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/kirdim-kalemi-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asortik', 'asortik-mehmet-osman-erol-unal-pq441', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben,

Ne gün saydım, ne heves tuttum

Adımlar attım doğru, yanlış...

Arada bir günahkâr da oldum

................................(Allah affetsin! ...) 

Gün oldu

Bir bakışa aldandım...

Gün oldu

Göz yaşımı sakladım...

Gün oldu 

Gülerken, dondum kaldım...

Her kaçışta bir bahanem mutlaka olurdu

..............................  (hem de en geçerlisinden...)

Üzülürdüm, yanardım da susuturamazdım içimdeki sesi

............................(ya hep, ya hiç... ya hep, ya hiç... ya hep, ya hiç...)

Seni terkedişim böyle  olmadı

O bunlardan hariç...

Sevdin mi sarmalı seni hüzün, delicesine

Gözlerinde yaş olmalı, yaş...

Yüreğin ağzına gelmeli ölürcesine

Böylesi sevemiyorsan aldanırsın

Bir damla göz yaşına hasret kalırsın...

Bundan gerisi boş be ''Asortik! ... ''

Hepsi hikâye...

...............................

Bilir misin,

Nerde bir ışık görse, âşık olur 

.............................. - döner, döner durur da -

Can verir sonra pervâne...

Sevdin mi can vermelisin, can! ..

Yoksa bir pervâne bile olamazsın...

Sen,

Beni hiç tanımadın Asortik! ...

''Neden? '' diye sorma.

Desem de anlamazsın

Hayat, sanki bir tabanca

Ve her an, parmak ucunda tetik

Yedin mi kurşunu böğrüne

İflâh olmazsın...

Ben, 

Ne gün saydım, ne yemin tuttum

Kapılar çaldım doğru yanlış

Arada bir dost ta buldum

....................................... (Allah için...)

Gün oldu

Ense kökümden inmedi yalnızlık...

Gün oldu

Paçamı sıyırdı geçti insanlık...

Gün oldu

Çektik kafayı

''Bilmem neyin anasını ağlattık...''

.......................................... (kulakları çınlasın! ...) 

Ben, gönlümce yaşadım be Asortik! ...

Pişman değilim

Ama, 

Bir seni sevdim dosdoğru, yalanım yok

Kalleş değilim...

Şimdi sen,

Çok uzaklarda... bir beyaz ışık...

Ben,

Bir garip pervâne

Hâlâ döner durur

Ve,

Hâlâ... sana âşık...

(İstanbul, Mayıs 1998)', 'Ben, Ne gün saydım, ne heves tuttum Adımlar attım doğru, yanlış... Arada bir günahkâr da oldum ................................(Allah affets...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/asortik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlığa Özlemdir Gece', 'aydinliga-ozlemdir-gece-yusuf-pekol-9flpl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sövmek geliyor içimden

Kahpe karanlığa.

    -ki bu ışıklara özlemin çığlığıdır-

İçimde geceye haykıran

Karanlıkta çürümeye yüz tutmuş

İsyanıdır bence.

Baykuşun sesi sanki

Geceye protestodur.

Gece kördür, sağırdır

Sinsi bir ölümdür gece.

Ve...

hiçliktir gece

Aydınlığımın,

Umutlarımın sonudur.

Ve... 

Gece Sövmüşlüğümdür.

Aleyhinde şiir yazdığımdir.

Ve...

Bana, bu loş odada

Yumruklarımı, kanatırcasına

Duvarlara vurdurandır

    -ki sanki duvarlarmış gibi suçlu-

     yada gece duvarlara saklanmış

İşte böyle sinsidir gece

Adidir gece

Kahpe karanlıktır gece.

Ama aydınlığa özlemdir

GECE...', 'Sövmek geliyor içimden Kahpe karanlığa.     -ki bu ışıklara özlemin çığlığıdır- İçimde geceye haykıran Karanlıkta çürümeye yüz tutmuş İsyanı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aydinliga-ozlemdir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlıyormusun', 'hatirliyormusun-mehmet-emin-altun-wix4k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani o akşam varya 

Elimde bir demet beyaz gül

Ve sen kapıda bekliyordun

Beni görünce şaşırıp baktın

Ve dündüm sana ben

Beyaz gülleri uzattım 

Sana uzattım

Şaşırmıştın bir an 

Banamı diye

Ama koyacak vazom yok demiştin

Ve bende sana söylemiştim

Kalbinin küşesindeki vazoya 

O vazoya koy demiştim

Orada bir ümür boyu canlı 

Canlı kalacaklar diye

Bana kocaman 

Kocaman bir teşekür etmiştin

Ve dündüm sana ben

Beyaz gülün anlamını sormuştum

Dürüstlüktür sadeliktir dedin

Bak güllerdende anlıyorum 

Demiştin

Ve bana beyaz güllerin 

Beyaz gülün anlamını söylemiştin

Neden diye devam etmiştin

Kırmızı gül yokmuydu dedin

Ve bende sana 

Aramızda aşkmı var

Diye söylemiştim

Kırmızı gül 

Evet kırmızı gül

Aşkı sevgiyi birlikteliği  çağrıştırır diye

Gülerek sende bana

Bana sende az değilsin demiştin

Bak güllerden bende anlıyormuşum 

Dediğimde

Gülücükler saçmıştın orada sen

Ve beyaz gülleri alıp gittiğimde

Hoşça kal demiştim ben

Hani o akşam varya........

Hatırlıyormusun hostes kız

                    hatırlıyormusun

                                        MEA

                                 24.08.2005', 'Hani o akşam varya  Elimde bir demet beyaz gül Ve sen kapıda bekliyordun Beni görünce şaşırıp baktın Ve dündüm sana ben Beyaz gülleri uzattı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Altun']::text[], 8.5, '{"poet":"Mehmet Emin Altun","poet_slug":"mehmet-emin-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/hatirliyormusun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cadı', 'cadi-mehmet-emin-altun-phser', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dili uzundur bir karış 

Ne yazzı düşünür ne kara kış

Babasıyla bile yapıyor yarış

Kavgacıdır bir türlü istemiyor barış

Ev işlerini beceremiyor kısır

Çarşı pazar gidemiyor sıfır

Misafirperverliğinde yok hayır

Kavgacıdır kavgaya her zaman hazır

                        02.03.1999', 'Dili uzundur bir karış  Ne yazzı düşünür ne kara kış Babasıyla bile yapıyor yarış Kavgacıdır bir türlü istemiyor barış Ev işlerini beceremiy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Altun']::text[], 8.5, '{"poet":"Mehmet Emin Altun","poet_slug":"mehmet-emin-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cadi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Ve Kolay', 'zor-ve-kolay-huseyin-gul-pawqa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ZOR VE KOLAY

Akıllı yada aptal

Fark etmez ne olduğun

Kötülük elinde

İstersen kolay iş

İyilik akıldadır

Aptal işi değil

İstesen de zor iş

               Hüseyin Gül

'' Bu kitabın Adı Yok '' Şiir kitabından', 'ZOR VE KOLAY Akıllı yada aptal Fark etmez ne olduğun Kötülük elinde İstersen kolay iş İyilik akıldadır Aptal işi değil İstesen de zor iş    ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Gül']::text[], 8.5, '{"poet":"Hüseyin Gül","poet_slug":"huseyin-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zor-ve-kolay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbir Hayal Bu Kadar Güzel Olmadı', 'hicbir-hayal-bu-kadar-guzel-olmadi-volkan-yoruc-3y6lg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dokundur elini göğsüne yavaşça

Vuruyormu hiç ellerine? 

Bir kıpırtı varmı içinde? 

Usulca bak aynaya

Dal gözlerine, bakışına

Neler anlatıyor sana? 

İçinden geçenler gözlerindemi? 

Ağlama

Ama gülümsemede

Dal gözlerine ellerin göğsünde

Bak bir daha kıpırtı varmı içinden? 

Bir hayale takıl

Ama sakın çekme ellerini göğsünden

Ve gözlerini gözünden

Anlat kendine 

Ama konuşmadan, sessizden

Yani gözlerinden

Bul o çocuğu, tut ellerinden

Bırakma

Sen ona konuş, ve dinle ama gülümseyerekten

Bak neler anlatıyor sana

Ömrünü, anneni, neneni

Hayalindeki sahilini, sevgini

Hani ömrü bitmez sevgini

Sonra sarıl ona

Ama sıkıca

Bırakma

Bırakırsan kaçar gider sonra

Ve geri gelmez belki bir daha

İçindeki çocuğu unutma

O yollarda seninleydi 

Seninle ağladı

Seninle gülümsedi

Ve unutma, hiçbir hayal bu kadar güzel olmadı', 'Dokundur elini göğsüne yavaşça Vuruyormu hiç ellerine?  Bir kıpırtı varmı içinde?  Usulca bak aynaya Dal gözlerine, bakışına Neler anlatıyor...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hicbir-hayal-bu-kadar-guzel-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün', 'bu-gun-nurten-koroglu-jo40w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün bir çocukluk yapacağım

Sevdamı avuçlarımın içine alıp

Gönlüne giden

 Bir uçak yapacağım

Bu günde seni seveceğim

Sevmeyi bilmeyen taş kalbine inat

Seni sevdiğimi 

Herkese haykıracağım

Bir gün seni anacağım

Seni göremeden,

Geçtiğim o tozlu yollardan

Elbet bir gün, intikam alacağım', 'Bu gün bir çocukluk yapacağım Sevdamı avuçlarımın içine alıp Gönlüne giden  Bir uçak yapacağım Bu günde seni seveceğim Sevmeyi bilmeyen taş ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-gun-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacı Bektaş', 'haci-bektas-yusuf-ter-rfp9m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolun yokuş değil ey Hacı Bektaş

Ozanların yolu hep senden geçer

Pirim Abdal demiş bir olun canlar

Bir olmanın günü dünden geçiyor

Sana gelip yüzün sürenler için

Cezamı çekeyim erenler için

Kırk gün aç kalayım görenler için

Yar olmanın günü  dünden geçiyor

Hacı Bektaş derler ilmin ışığı 

Ben de bir  ozanım onun aşığı

Kapında kul olsam olsam eşiği

Kar olmanın günü dünden geçiyor

Yusuf’um kurulmuş dar ağacımda

Kesilmiş kollarım sır ağacımda

Yanıyor yüreğim  mor ağacımda

Kor olmanın günü dünden geçiyor

Yusuf Ter 21.08.05

Saat 02:22 İsviçre 

Hacıbektaş-i Veli de der ki:

''Her ne arar isen kendinde ara,

 Kudüste, Mekke''de, Hac''da değildir...''', 'Yolun yokuş değil ey Hacı Bektaş Ozanların yolu hep senden geçer Pirim Abdal demiş bir olun canlar Bir olmanın günü dünden geçiyor Sana geli...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/haci-bektas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Yaşadın', 'ne-guzel-yasadin-cumhur-boratav-x7caz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne kadar güzel yaşadın

göğsünde çuval ipliğinin izi 

ne güzel yaşadın

ayaklarının altında 

yerin sertliğine benzeyen

çuval

ne güzel yaşadın

göğsüne hapsedilmiş çuvalda 

gezinen lağım faresi

ayaklarının altında, biraz daha yukarda

daha yukarda

ne güzel yaşadın

ısırığı hayalarındaki 

belinde

senden izinsiz açılan deliği

sen artık insan değilsin

hiç bir şey insan olduğunu söyleyemez

karnında değil

belindeki bir göbek deliği

bir fare ısırığı

acının ruhuna sorduğu yer

bunu hiç bir şey anlatamaz

bir insan değilsin artık

ne güzel yaşadın

içinde gezinen bir lağım faresi

gezinen içindeki

ne güzel yaşadın

-haksızlık-', 'ne kadar güzel yaşadın göğsünde çuval ipliğinin izi  ne güzel yaşadın ayaklarının altında  yerin sertliğine benzeyen çuval ne güzel yaşadın ...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ne-guzel-yasadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Assak', 'geceyi-assak-yusuf-pekol-qq28s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün

Çıkıp gelsen.

Kapımı çalsan.

Baksan gözlerime

Yüreğime dolsan

Usulcacık sarılsan

Ve artık

Sevgini geceye anlatmasam.

Özlemimi sana fısıldasam.

Gecelerime güneş olsan.

Geceleri söküp atsan

Bu loş odadan.

Ve her anıma sen dolsan.

Yatağımda geceye değil

Sana sarılsam.

Doya doya yüzüne baksam.

Geceyi assam.

Elektrikli sandalyeye bağlasam.

Mitralyözle tarasam.

Uçurumdan atsam.

Hayalini geceyle paylaşmasam

Sevgini geceye anlatmasam.

Gece bana sensizliği

Sinsi sinsi uğuldamasa.

Bir gün çıkıp gelsen.

Beni kollarınla sarsan.

Geceyi assan.

Geceyi assam.

Geceyi assak.', 'Bir gün Çıkıp gelsen. Kapımı çalsan. Baksan gözlerime Yüreğime dolsan Usulcacık sarılsan Ve artık Sevgini geceye anlatmasam. Özlemimi sana f...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/geceyi-assak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Xyapennakzisairokapi ….. gezegeni', 'xyapennakzisairokapi-gezegeni-mehmet-akif-gulhan-wu1jz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arka bahçemize indi

Önce gözleri kör eden bir ışık gördüm

Sonra o devasa uzay gemisini

İçinden o çıktı

Adım xas dedi

Anlamadım adını

Ama dediğini anladım

O bir başkası

Hani merak ettiklerimiz

Korktuklarımız

Bizden ileriler mi 

Yoksa ilkeller mi dediklerimizden

Korkmadım

Korku hissi duymadım,

Sadece merak vardı içimde

Yüzyılların acaba-ları

Sonra sırları verdi bana

Her şey big bang ile başladı

O(sıfır)   noktası

Sonra ilahi emir geldi-yok olmak-

Sizden farkımız 

Siz var olma emrine takılı kaldınız 

Biz ise yok olma emrine

Var olma çabasını terk ettik biz

Var olma savaşı veren sizler

Yok ettiniz her şeyi

Yok olacağımızı bilen bizler ise

Var etmeye çalıştık her şeyi

Bizim gezegenimizde savaş olmaz

Yarış hiç olmaz

Madde ve mana asla var olmadı

Salt o günün değeri var oldu

Yeni gezegenlerde aramıyoruz

Hepsi yok olacak

Neondertaller homosapiensler

Tekamülü yanlış seçimlerdi

Yaradan mükemmeli hala yaratma çabasında

Sizler de bizler de kötü örnekleriz

Dinazorlar ve diğer türler gibi yok olacağız

Bundan kaçış yok

Zenginlik,hakimiyet boş şeyler

Size çarpacak gök taşını

Tabiatın gücünü kontrol edecek güç yok

Başka gezegen hiç aramayın

Gemiler çoktan yakıldı

Geri dönüş,kaçış yok

Sığınacak liman; asla

Bu günü güzel yaşayın

Teslimiyet ve yok oluş mutlak

Zulüm ve hakimiyet anlamsız

Hiçbir teknoloji yeterli değil

Anlamsız,anlamsız,anlamsız

Ses kulaklarımda çınlıyor

Gözleri kör eden ışık gitti

Çalar saatim 07 00 yi gösteriyor

Sizden bu olaya,başka şahit var mı

Mehmet Akif Gülhan 26.08.2005', 'Arka bahçemize indi Önce gözleri kör eden bir ışık gördüm Sonra o devasa uzay gemisini İçinden o çıktı Adım xas dedi Anlamadım adını Ama ded...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/xyapennakzisairokapi-gezegeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rıza', 'riza-yusuf-pekol-lv19e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gördüm evet gördüm.

Bugün ilk kez

Bir çocuğun gözlerinde

Kendimi gördüm.

Ben sandım onu

O sandım kendimi.

Parlıyordu sanki gözlerinde

Bütün hayatımın ışıltıları

Ve dökülüyordu gözlerinde

Umut dolu hayatımın kırıntıları.

Her bakışıyla hayatımdan

Bir ok fırlatıyordu sanki

Daralan yüreğime; 

Tükenen ümitlerime.

Ve ben olabildiğince

Tedirgin ve...

Evet gördüm

Görülmek için gözlerime

Baktığını çocuğun.

Ben senim

Deyişini

Rıza''nın...', 'Gördüm evet gördüm. Bugün ilk kez Bir çocuğun gözlerinde Kendimi gördüm. Ben sandım onu O sandım kendimi. Parlıyordu sanki gözlerinde Bütün ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/riza-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Yeniden Gelecek, Bir Gün Hiç Beklemeden', 'bir-gun-yeniden-gelecek-bir-gun-hic-beklemeden-cumhur-boratav-adxrn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gün yeniden gelecek

bir gün, seni hiç beklemeden

senin için çok yeni bir duyguyla 

hep yaşadığım benim 

güneşle henüz 

tanışmadığı zamanda

o zamandaki sabahının 

sen korkunu bile hissedemeden

sevgilinin kollarından alındığın bir gün,

uyanan kuşların keskin cıvıltısıyla

arka penceresinden

bindirildiğin arabanın

yüzünü dönerek bizi hatırla

üstündeki tozu üfle 

seni anlatan şiirlerimizin

artık bizi 

yaşamaya başlıyorsun

öyle gelir

bir gün, hiç beklemeden

bir gün, 

yeniden', 'bir gün yeniden gelecek bir gün, seni hiç beklemeden senin için çok yeni bir duyguyla  hep yaşadığım benim  güneşle henüz  tanışmadığı zaman...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-gun-yeniden-gelecek-bir-gun-hic-beklemeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-mehmet-osman-erol-unal-ch8vl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEN

Fevkalâde zamanlarımın 

Hiç şaşmayan saat başısın...

Ne kadar saat varsa yeryüzünde

Akrepler seni gösteriyor...

VE,

Bütün yelkovanlar sana âşık

Hepsi, tam onikide seni bekliyor...

BEN

Ya seni beş geçe geliyorum

Ya da  sana beş kala duruyor zaman

Yetişemiyorum...

VE

Hep aksilik... bitmedi, bitemedi...

Oynuyor zaman benimle sanki

O, acımadı, beni tüketti

Ben de  boş verdim artık

Savurdum zamana 

Avucumda sıktığım son ümitleri...

AŞKIMIZ

Sonsuza doğru  hızla yol almakta

Ve ben, bütün zamanlarımı harcadım senin için

Zaman yoksuluyum artık...

Anlasana...

KAYBOLDUK! ...

Sen ve ben... ve, aşkımız...

Yenik düştük zamana

Böyle gitmezdi belliydi ya

Boşuna sevdik, yorulduk

Boşuna...

(İstanbul, Ocak 1995)', 'SEN Fevkalâde zamanlarımın  Hiç şaşmayan saat başısın... Ne kadar saat varsa yeryüzünde Akrepler seni gösteriyor... VE, Bütün yelkovanlar sa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-ve-ben-130-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A- Miraç Gecesi Duası', 'a-mirac-gecesi-duasi-mikdat-bal-3cg22', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şairler aciz kaldı, dile getiremedi 

Edipler bitab kaldı deyip bitiremedi 

Alimler hayran kaldı, sırrına eremedi 

Miracı Nebevinin, müjdesi hürmetine 

Ya Rab ihsanda bulun Muhammed ümmetine! 

Bu gece öyle gece, bizlere nasip ettin 

Yüce peygamberinle bize müjdeler verdin 

Tövbe edicileri affedeceğim dedin 

Tövbe ettik, el açtık Yüce azametine 

Ya Rab mağfiret eyle Muhammed ümmetine! 

Bu gece başka gece, güller seni zikreder 

Gönüllerde sen varsın, diller seni zikreder 

Rahmetine uzanan eller seni zikreder 

Allah’ım sen bizleri gark eyle rahmetine 

Ya Rab in’amda bulun, Muhammed ümmetine! 

Tevfikin ile bizi doğru yola ilettin 

Habibin Muhammede bizi ümmet eyledin 

Miraçta ümmetini bağışladım söyledin 

Allah’ım nail eyle bizi şefaatine 

Ya Rab ikramda bulun Muhammed ümmetine! 

Hüsrana düşenlerden etme bizi Allah’ım! 

Kulluğundan kovarak atma bizi Allah’ım! 

Yolunu sapmışlara katma bizi Allah’ım! 

İltica ettik Rabb’im engin merhametine 

Ya Rab merhamet eyle Muhammed ümmetine! 

Ya Rab ikram etmezsen bize kim yardım eder! 

Gamdan kurtulamayız, kaplar kasavet, keder 

Biz sana kul olalım, bu şeref bize yeter 

Ya Rab bağışla bizi, dahil et cennetine! 

Miracı mübarek kıl, Muhammed ümmetine!', 'Şairler aciz kaldı, dile getiremedi  Edipler bitab kaldı deyip bitiremedi  Alimler hayran kaldı, sırrına eremedi  Miracı Nebevinin, müjdesi ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mirac-kandili-duasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Ordusu''na', 'turk-ordusu-na-mehmet-osman-erol-unal-jb9a1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sanmayın gözlerindeki yaş acıdandı

Onlar,

Yiğitçe gittiler ölüme

Bebekler uykudaydı...

Arkalarına bile bakmadılar...

Deldiler karanlığı sessizce her biri bir yerden

Şafağın sökmesine daha çok vardı...

Allah Allah! ... 

O ne gururdu, o ne aşktı... o ne inançtı...

Sevdâları yalnızca vatandı! ...

Gözlerindeki yaş,  işte ondandı...

Nöbete durmuştu gökte ay ve yıldız

Kan kokuyordu sanki toprak...

Pusuya düştüler kalleşce...

.............................

Ağlıyordu gökte ay ve yıldız

Bir teki bile geri dönmedi o gece...

Öldüler...

Her biri mukaddes şehit...

Gökte ay ve yıldız şâhit...

Yiğitçe, Türk gibi, askerce kurşun sıkarak...

Türkü söyler gibiydi yüzleri, tek bir yürek, tek bir ağız...

Ne demişlerdi giderken; 

............................. ''annem beni yetiştirdi, bu ellere yolladı...''

Biz bu gün için doğduk, bu gün için varız...

............................................

Gün ışıyordu,

Bebekler hâlâ uykudaydı...

Vatan; sağdı...

Kana kucak açmıştı toprak

Her biri âbide gibi yatıyordu

Bedenleri sımsıcak...

Ve,

Her birinin göğsünde 

Kan kırmızı gül gibi açmıştı bayrak...

(İstanbul, Ocak 1999)', 'Sanmayın gözlerindeki yaş acıdandı Onlar, Yiğitçe gittiler ölüme Bebekler uykudaydı... Arkalarına bile bakmadılar... Deldiler karanlığı sess...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/turk-ordusu-na-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geride Kalan Kalp', 'geride-kalan-kalp-nobel-sairi-m53jq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Farzet ki hiç kurulmadı gözlerinden gözlerine bir köprü,

Farzet ki kalbin çarpmadı değince elleri ellerine,

Farzet ki yaşadıklrının hepsi birer hayal ürünüydü,

Ey gönül; o bırakıp gittiğinde gün senin günündü....

Sanki sana koşarak dönse geri,

Olacak mı artık herşey eskisi gibi,

Hem ne malum aldatmayacağı yine seni,

Ey gönül; parla bir yıldız misali,düşün ki o bir zalimdi....

Beraberken ne sözler veriliyor değil mi? 

Hiç bırakmayacağız birbirimizi,

Ve daha niceleri,

Ey gönül unut artık onun tatlı dilini ve sözlerini....

A benim biricik gönlüm! ! ! 

Kendine zarar vermyi artık bırak,

Sen de biliyorsun kionu düşündükçe yaşayacak sevgin gün geçtikçe artarak....

O da her gelen gibi gitmek için gelmişti,

Ve gittiğinde geride nasıl bir kalp bıraktığını hiiiç bilmeyecekti.....', 'Farzet ki hiç kurulmadı gözlerinden gözlerine bir köprü, Farzet ki kalbin çarpmadı değince elleri ellerine, Farzet ki yaşadıklrının hepsi bi...', ARRAY['Türk Edebiyatı','Şiir','Nobel Şairi']::text[], 8.5, '{"poet":"Nobel Şairi","poet_slug":"nobel-sairi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geride-kalan-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah mavi gece', 'siyah-mavi-gece-elazigli-mustafa-kaya-fwirj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sırılsıklam bir gökyüzüydü gözlerin,

koymak için başını

aradığın omuz bendim.

ve kederler geziyor yüzünde..

bir büyüye uğramış gibi rengin..

bu gece neden böylesin..? 

içimde ağlayan sendin..

ve bir taş attım senin için

niyetimi anladı deniz

dalgalar ve gece söylendi

dalgalara sinmiş sesin.

bütün gece benimleydin

ve gecenin esmer teninde

dudaklarımı gezdirdim….

                                                    27.08.2005 / Kandilli

                                                      Mustafa KAYA', 'sırılsıklam bir gökyüzüydü gözlerin, koymak için başını aradığın omuz bendim. ve kederler geziyor yüzünde.. bir büyüye uğramış gibi rengin.....', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siyah-mavi-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz akşamı', 'yaz-aksami-elazigli-mustafa-kaya-1qtel', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'martıları kıskandırdım

uzaktan geçtiler.

bugün Üsküdar’daydım.

serin bir yaz akşamı

yosun kokusuyla siniyor gece

ve akşam simitleri gevrek

kağıt helvalar uçup geldi

ve elma şekerleri…

çoğalan gülücüklerin arasında

ne kadar gezindik,

yetinmedik.

kuzguncuk-Beylerbeyi-Çengelköy

kandilli-Kanlıca…

sahil sahil dolaştık

gölgeli yollardan geçtik

hayal Kahvesi’nde

kaç çay içtik…

gece uzun…gece İstanbul

uzaklarda benim gülüm,

göğsümde bir hüzün,

diz çöküyorum sahilde,

yanılıp kayan bir yıldızı tuttum.

kalbimi ürperten dokunuşu,

ve siyah mavi gece

sendin sevgilim,

sendin biriciğim...sendin…

                                                            

                                                            

                                                        

Mustafa kaya / 27.08.2005

Kanlıca', 'martıları kıskandırdım uzaktan geçtiler. bugün Üsküdar’daydım. serin bir yaz akşamı yosun kokusuyla siniyor gece ve akşam simitleri gevrek k...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yaz-aksami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aman! Ha!', 'aman-ha-zulfikar-yapar-kaleli-ebo0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kulak ver sözüme, mazluma dikkat 

“Kurban olum” deme darılır, aman! 

Gönül kırmak yasak, cezası kat kat

Sabır et köpüren durulur, aman! 

Mazlumda gönül gül, yeşerir, solmaz

Mazlumun duası havada kalmaz

Mazlumu ezenin ahiri olmaz

Gün olur düz yolda yorulur, aman! 

Ayırtmak da lazım samanı saptan

Suçlamak doğru mu herkesi hepten

Yoksa kurtuluş yok, cezadan, ipten

Önyargıyla nere varılır? Aman! 

Haklı olduğunuz yer yok mu? Vardır.

Bu durum da zaten adama ardır

Mümin ki dostuna sadıktır, yardır

Günahı sevabı sorulur, aman! .

Hisse almalısın dediklerimden

Yoksa bağış olmaz Yüce Kerim''den

Yaraladın beni birkaç yerimden

Nasıl bu vaatte durulur, aman! .

Ben biri söylerim, sen bini anla

Hedefe varılmaz ithamla, zanla

Kanı yuyarlarsa mutlaka kanla

Muhakkak gönüller kırılır, aman! .

Kaçış yok hesaptan, kulluktan öte

Gönül mükmin yaşar bolluktan öte

Bir yol açılır ki yolluktan öte

Mizan terazisi kurulur, aman! .

Bir deliden bin ders almazsa insan

Gün olur ki olur yer ile yeksan

Ben bana söylerim, anla be Hasan 

İnsan ta beyninden vurulur, aman! !', 'Kulak ver sözüme, mazluma dikkat  “Kurban olum” deme darılır, aman!  Gönül kırmak yasak, cezası kat kat Sabır et köpüren durulur, aman!  Maz...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/aman-ha-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Dostum Yıldızlar', 'tek-dostum-yildizlar-nobel-sairi-o9ifz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Of! ! Kalbime söz geçmiyor be yıldızlar...

Ne yapsam ne etsem olmuyor; çıkıyor ona bütün yollar,

Allahım ne zor şey bu aşk dedikleri; eğiliyor önünde bütün kullar; 

Her şarkıda,her şiirde neden o aklıma geliyor be yıldızlar...

Neden söz geçmiyor şu gönlüme,

Neden her yaşadığım saniyede o aklımda,

Hep böyle mi geçecek ömrüm be yıldızlar...

Acaba gönlüm parlayacak mı sizin gibi bir başkası için,

Sevebilecek miyim bir başka kalbi,

Bulabilecek miyim acaba onun gibisini,

Geceleyin tek dostum sizlersiniz; dinleyin beni,

Siz de olmasanız ben derdimi kime anlatacağım be yıldızlar; 

Kime anlatacağım....', 'Of! ! Kalbime söz geçmiyor be yıldızlar... Ne yapsam ne etsem olmuyor; çıkıyor ona bütün yollar, Allahım ne zor şey bu aşk dedikleri; eğiliy...', ARRAY['Türk Edebiyatı','Şiir','Nobel Şairi']::text[], 8.5, '{"poet":"Nobel Şairi","poet_slug":"nobel-sairi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tek-dostum-yildizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Domaniç', 'domanic-ahmet-kurt-b67bf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açtın kollarını, bağrına bastın,

Ata yurdum, yadigarım Domaniç.

Ne çehren değişti, ne yüzün astın,

Ata yurdum, yadigarım Domaniç.

Çınarlarım dağlarından sulandı,

Kaç asır koynundan devler uyandı,

Tarihim yeşerdi, renk renk boyandı,

Ata yurdum, yadigarım Domaniç.

Cömertçe harcadın bizi büyüttün,

Cihana çadırdan ordu yürüttün,

Mazluma şefkatli, zulmü çürüttün,

Ata yurdum, yadigarım Domaniç.

Hasretim, sevdamsın ruhuma dolan,

Gözümde gecedir, seninle solan,

Bir ben miyim, sende bahtiyar olan,

Ata yurdum, yadigarım Domaniç.

Kurdoğlu her türlü acıya hazır,

Bu aşkı kalbine kanıyla kazır,

Sende imiş meğer beklenen huzur,

İşte buldum, bahtiyarım Domaniç.', 'Açtın kollarını, bağrına bastın, Ata yurdum, yadigarım Domaniç. Ne çehren değişti, ne yüzün astın, Ata yurdum, yadigarım Domaniç. Çınarlarım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/domanic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzansam Şöyle Bir Gözlerine', 'uzansam-soyle-bir-gozlerine-atilla-guler-1cht2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen yokken

harman oldu düşevurum arsız yüreğimin koynunda

alına al moruna mor sabahlara selam ettim yıllarca

hedef oldu yürek tüm oklara nişan tahtasında

her zehir dolu kadeh bana sunuldu…içtim 

uçurtmalarımın kopan kuyruğunda savruldu yaşam

zalim ellerinde oyuncak aramadı zaman/ben vardım

azgın nehirlerin arsız akıntısında yitiyordu düş(ünce) ler

noktalara varılıyordu virgülleri koymadan

imgesiz…sayıklamalarımın ötesinden kopup gelen bir melodiye düştü şiir

annemin sesinde yankılandı ninniler

mesafelerde kaybolan bir sis çaresizliğin sessizliği 

şehvetimin her rengini çaldı benden geceler

…renksiz saatlerde bir başıma

özlem har vurduğunda yüreği harman savrulmadı

…savrulan sevdamın çiçekleri

yapışıp kaldı…hiç çıkmadı yanık kokusu üzerimden

lakin anlayan bilir…bozuldu akrostişler…bilemedin

epopelerde gerçekleşen mucizelere kaldı umudun sapkın tutkusu 

çürümüş kokusu bedenin yayıldıkça kaçtım…kaçamadım 

izlerinde büyüdü gözlerinin büyüsü…her şey sen gibi…su gibi

mıh gibi çakıldın alnıma

…silemedi seni süzülen kanlar…her şey kızıla büründü

ellerine verdiğim her günümü götürdüğünde hiç olmadı itirazım

nefes nefes çektiğim dumanların ötesinde seyre daldım ufku

lacivert gökyüzünün kara bulutlarından düşen yağmur damlaları doldu göz pınarlarıma

er yada geç güldüğünde şans yüzüme çok geç olacak biliyorum

ruhun tazeliği ne kadar yansır bedeninde

enini düşünüp sonuna varamadığım bir düş bu

süslü laflar öyle çok edildi ki senin için

eskimeyen öyle çok öyküde okudum ki ayrılığın sonunda mutluluk olduğunu

inanç yitti öykülere de

yitirilen her sevinç kanadı içimde…ondan kırmızı güllerin rengindeki sıcaklık

rastladığım her yüzde senin gözlerini aradım…her sözde senin sesin

ezip geçen anlarda patladı kurşun…son bakışına yazdım aşk şarkısını

duydun mu

delip geçen bir ışığın gölgelerine yansıdı yalnızlığın karası

akşam saatlerine tutsak oldum

…yarasa misali gecelerde bir seyyah artık mecnun

lime lime olmuş bir ruh karşında şimdi…sev sevebildiğince

…sev

silik sokakların dili yok ki anlatsın ıslaklığımı sensiz yağmurlarda

aykırı gülüşlerin yankısı kulaklarımda…silemedim

minik bir serçenin cılız ötüşüne saklanmıştı bahar…duyamadım

girdaplarda boğuldu sana sakladığım sevinçler

yandığımca uçamadım göklere kırık kanatlarla

özgür bıraktığım her düş düştü peşime

kim tutar ellerimi soğuk kış günlerinde

yeni yıldızların pırıltısı gökyüzünde…senden bihaber

üstelik dünlerde unutulan ateş sönmüş artık

zor…yalnızlığın kıskacında soluk almaya çalışırken sana tutunmak 

üzerime çöken laneti silsem artık şöyle bir

nar çiçeklerinin kızılına söylesem türkümü

üzüm gözlerine uzansam şöyle bir/seyre dalsam gökleri

seni ne çok özlemişim…öyle özlemişim', 'sen yokken harman oldu düşevurum arsız yüreğimin koynunda alına al moruna mor sabahlara selam ettim yıllarca hedef oldu yürek tüm oklara niş...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/uzansam-soyle-bir-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki yosun dalı', 'i-ki-yosun-dali-elazigli-mustafa-kaya-qdjl6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'iki dal..iki yosun dalıyız biz 

iki ateş..iki lav parçası 

siyah mavi gecede 

ve iki çay..iki su..

delta olup akarız körfeze 

ve iki parçayız ay ın bölünmüşlüğünde..

tutamaz bizi vadiler, 

sıra dağlar,

bendleri dinlemeyiz 

ne kalyonlar aştık,

çağıldayıp iki sevdalı. 

ve buluşacağımız yer,

bizim andımız.

ve kavuştuğumuz zaman, 

en güzel yerindeyiz toprağın 

kaç konak kurulu..

gittikçe kabaran yüreğimizi taşıdık 

durulduk bir söğüt gölgesinde.

ve aynı rüzgarın sesiyiz 

aynı türkünün iki kıtasıyız biz..

                                                                          27.08.2005 / çubuk

                                                                           Mustafa kaya 

www.mustafa kaya.net', 'iki dal..iki yosun dalıyız biz  iki ateş..iki lav parçası  siyah mavi gecede  ve iki çay..iki su.. delta olup akarız körfeze  ve iki parçayı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iki-yosun-dali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-fatih-ozkonyali-5igjl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey ağaç

Sar yıldızlarını yavaş yavaş aya

Hüzünlü mahzenlerinde gezinen sessizliği

Tek tek say kaybolan yılları mazinin kollarında

Bu doğumun sancısını beyaz yelkenlere yay

Bekleme solacak güllerin vadesini bu akşam

Ne ok vurur başını bu savaşta taşa ne de yay

Kurumuşsa dudaklarım hecelerden bu değildir gurur

Aç ellerini yüzüne kapanan semaya

Kulaç kulaç kaçsın senden gecenin bensizliği 

Çal bütün renklerimi sarı, mavi, al

İçini sızlatan köklerini toprağıma sal

Ey ağaç

Ey ağaç

Dallarında titreyen serçelerin ötüşüyle

Irmağın gerdanını süsleyen yaprağınla gel

Avucunda bir sevda yavrusu, kızıl toprağınla gel

Şu karanlık bulutlar ürkütüyor içimi 

Kuşan diline öykülerini, karanlığı del

Aksın elinden yüreğime oluk oluk tohumların

Kesilsin nefesi benden soluk serzenişin

Süzülsün ılık ılık üstümden rüzgarın 

Kafesinden uçur ümitsiz yarınları

Gelinciklerin dualarıyla gel

Ey ağaç

Ey ağaç 

Gölgele üstümden beynimi yakan güneşi

Serinliğin koynuna uzat beni 

Dolansın boynuma gizemli ihtişamın

Kaybolsun ülkesinde yalancı kahramanım

Resimlerin mahyalarında boğma hasretimi

İsminle doğ yalancı ömrüme ey dağların kâhyası

Bütün isimler sende kaybolsun

Sende solsun her cismin müptelalığı 

Ve ey ağaç…

Hüzünlü mahzenlerinde gezinen sessizliği

Yay yıldızlara yavaş yavaş ve aya…', 'Ey ağaç Sar yıldızlarını yavaş yavaş aya Hüzünlü mahzenlerinde gezinen sessizliği Tek tek say kaybolan yılları mazinin kollarında Bu doğumun...', ARRAY['Türk Edebiyatı','Şiir','Fatih Özkonyalı']::text[], 8.5, '{"poet":"Fatih Özkonyalı","poet_slug":"fatih-ozkonyali","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/agac-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Yandı', 'canim-yandi-ebru-temizkan-114ze', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün batarken 

 Seni gördüğümde

Anladım ki benim olmalıydın 

Denize bakıp gözlerini gördüğümde

Benim olman kaçınılmazdı 

Günü dinleyip sesini duyduğumda 

Hayatım olmalısın diye düşünmüştüm 

Ellerinin sıcaklığıyla 

Yüreğinin güzelliği örtüştüğünde ise

Benimdin

Sonra bir baktım 

Hava karardı 

Gözlerin bulutlandı 

Griydi

Sesin çatallaştı 

Kırbaçtı 

Ellerin soğudu

Yabancıydı 

Gün ışıdı 

Hayaldin 

Yalanmış her şey 

Canım yandı …', 'Gün batarken   Seni gördüğümde Anladım ki benim olmalıydın  Denize bakıp gözlerini gördüğümde Benim olman kaçınılmazdı  Günü dinleyip sesini...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/canim-yandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-meral-vurgun-49bxk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'mavi gülüşüne kur sehpayı

ve as üstüne yüreğimi

gül dalında al ipek bir kurdela gibi sallansın

umduğum, umarım ol 

ufukları güneş gibi yırtan sözcüklerle gel dünyama

uzak dediğin nedir ki

iki adım bir uçtan bir uca iki kutup

koyunkoyuna yatıp da 

yanyana gelemeyenleri bilirsin

bırak dudaklarını

kırmızı şarap gibi bırak ağzıma

yüreğime aldım ışınlarını 

güneşten bir susku dolu içim 

ah! diyorum ah! 

şu yaşamak ne mendebur bir iş

bak! Yüzüm Kuzey’de bir yıldız bu gün

iğreti bir yaprak gibi korkuyorum

toprakta bir çığlık

bu kentin sokakları zifir karanlık

bana bir avuç güneş yolla sevgili

bekliyorum...', 'mavi gülüşüne kur sehpayı ve as üstüne yüreğimi gül dalında al ipek bir kurdela gibi sallansın umduğum, umarım ol  ufukları güneş gibi yırta...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bekliyorum-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken ardından', 'giderken-ardindan-tekin-tayanc-39zqo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Giderken ardından

Kendinden düşen binlerce parça bıraktın

Geride kalanlar için..

Hasret bıraktın hiç bitmeyen

Uzayıp giden bir ömür boyu 

İç çekercesine

Gözyaşı bıraktın hiç dinmeyen

sel olup akan yüreğime

ve ardından

Umut bıraktın hiç sönmeyen

belki dönersin diye

hep yaşattığım...', 'Giderken ardından Kendinden düşen binlerce parça bıraktın Geride kalanlar için.. Hasret bıraktın hiç bitmeyen Uzayıp giden bir ömür boyu  İç...', ARRAY['Türk Edebiyatı','Şiir','Tekin Tayanç']::text[], 8.5, '{"poet":"Tekin Tayanç","poet_slug":"tekin-tayanc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/giderken-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Parkında', 'cocuk-parkinda-tekin-tayanc-159kp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalıp dalıp gider gözlerim ardından

ıslak ve yorgun... 

Anılarımız gelir aklıma

Seni o ilk öptüğüm

Çocuk parkında

Biz neydik ki

Farkımızmı vardı çocuklardan? 

Onlar gibi şen,

Onlar gibi kaygısız,

Onlar gibi iyimserdik hayata karşı

sallanırdık boşluğunda

çocuksu tavırlarımızla

bir ileri, bir geri...', 'Dalıp dalıp gider gözlerim ardından ıslak ve yorgun...  Anılarımız gelir aklıma Seni o ilk öptüğüm Çocuk parkında Biz neydik ki Farkımızmı v...', ARRAY['Türk Edebiyatı','Şiir','Tekin Tayanç']::text[], 8.5, '{"poet":"Tekin Tayanç","poet_slug":"tekin-tayanc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuk-parkinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Babama', 'can-babama-tekin-tayanc-jhshq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürüyorum

Buz gibi bir şubat akşamında

yalnızlığımla...

Sokak lambalarının ışıkları altında

Sis tutmuş istanbul sokaklarında

Lapa lapa kar yağıyor

Yüzüme düşüyor binlercesi okşarcasına 

Dostça

Sokaklar yalnız ben yalnız

Bir başımıza

Düşünüyorum...

Yalnızlığımı, acı tatlı hatıralarımı

Çocukluğumu,gençliğimi

Doyamadan kaybettiğim,canımdan öte 

Can babamı

Oysa...

Ne kadar kızardım babama

Beni anlamaz,sevmez sanırdım

Acısını gömdüm yüreğime 

Kıymetini bilemediğim her değeri

yitirdikten sonra', 'Yürüyorum Buz gibi bir şubat akşamında yalnızlığımla... Sokak lambalarının ışıkları altında Sis tutmuş istanbul sokaklarında Lapa lapa kar y...', ARRAY['Türk Edebiyatı','Şiir','Tekin Tayanç']::text[], 8.5, '{"poet":"Tekin Tayanç","poet_slug":"tekin-tayanc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/can-babama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırşehir`im', 'kirsehir-im-atilla-gozukucuk-eg5np', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her tarafta lale sümbüllerin açar

Güzel kokuların dört bir yana saçar

Seni görenlerin tedbili şaşar

Eşin benzerin bulunmaz Kırşehir.

Bir yanında Mucur,bir yanında Kaman

Senden ayrı düşenin halleri yaman

Dağlarıyın başından gitmez hiç duman

Aşıklar methini eder Kırşehir her zaman

Bahar gelince türlü çiçeklere bezenin

Çatıkkaş olur hep senin güzelin

Kokar burcu burcu güllerin dalında

Aşıklar gider senin yolunda Kırşehir.

Türkmeniz,bizim aslımızı sorarsan

Eğer yolun düşer de bu diyara uğrarsan

Karakurtta,Termede,Hamamözünde yunarsan

Dertlerden kurtarır seni Kırşehir.

Kış gelince yüce dağın başında kar boran boran

Senden ayrı düşenin halları yaman

Aşıkpaşam,Cacabeyim,Ahievranım sana gelinir her zaman

Hayaline yeldirir güzel Kırşehir.

Atilla`m da çekti senin hasretini 

Hep duymak istedi aşıkların sesini

Senin her zaman yaptı methini

Kavuşur sana birgün Kırşehir.', 'Her tarafta lale sümbüllerin açar Güzel kokuların dört bir yana saçar Seni görenlerin tedbili şaşar Eşin benzerin bulunmaz Kırşehir. Bir yan...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kirsehir-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dduyuru', 'dduyuru-akin-akca-ovq0z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir süreliğine, bazı şiirler üzerinde düzeltmeler yapabilirim ve bir şiir üzerinde çalışıyorum sevgili dostlar. ara ara ekleyebilirim. tatile çıkacağım ama henüz değil.

candan sevgiler', 'bir süreliğine, bazı şiirler üzerinde düzeltmeler yapabilirim ve bir şiir üzerinde çalışıyorum sevgili dostlar. ara ara ekleyebilirim. tatil...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/dduyuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '! ! ! CaReSiZiM! ! !', 'caresizim-zubeyde-fakili-x5ji2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha dün gibi hatirliyorum maziyi! 

Unutamadim yasanan dünleri

Cok bekledim geriye dönmeni! ! ! 

Caresizim sevdigim

                              söküp atamiyorum Seni! ! ! 

                          Nereye baksam seni görüyorum

                          Bakisini,o gülüsünü Masum yüzünü...

                               Cok sevmisdim seni Cok

                          Icime sindiremiyorum beni caresiz

                                                           Terk edip gidisini! ! ! 

Vicdanin sizlamiyormu? 

Sanki sen hic sevmedinmi? 

Yüregime kapanmayan bir yara actin! 

Merhemi olmak istemezmisin? ? ? 

Senden sonrasi HARAMDIR bana

                CaReSiZiM sevdigim inan buna! ! !', 'Daha dün gibi hatirliyorum maziyi!  Unutamadim yasanan dünleri Cok bekledim geriye dönmeni! ! !  Caresizim sevdigim                         ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Fakili']::text[], 8.5, '{"poet":"Zübeyde Fakili","poet_slug":"zubeyde-fakili","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/caresizim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert yol dertli yolcu', 'dert-yol-dertli-yolcu-umit-isikdag-fgv4t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dert yol, dertli yolcu

Bu Adem aciz hancı

Kırk saatte kırk bulut

Kırk yağmur kırk fırtına

Kırk tarumar kırk sefil ve

Kırk dertli geçti burdan

Sevda yol,Kerem yolcu

Bu Adem aciz hancı

Kırk günde kırk kervan

Kırk kırık kalp,kanayan

Kırk Aslı kırk Kerem ve

Kırk sevda geçti burdan

İlim yol alim yolcu

Bu Adem  aciz  hancı

Kırk ayda kırk kelam

Az hakikat çok yalan

Kırk efendi geçti de

Bir alim geçmedi burdan', 'Dert yol, dertli yolcu Bu Adem aciz hancı Kırk saatte kırk bulut Kırk yağmur kırk fırtına Kırk tarumar kırk sefil ve Kırk dertli geçti burda...', ARRAY['Türk Edebiyatı','Şiir','Ümit Işıkdağ']::text[], 8.5, '{"poet":"Ümit Işıkdağ","poet_slug":"umit-isikdag","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dert-yol-dertli-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Hali', 'dunya-hali-atilla-gozukucuk-6gi6e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne söyleyim şu dünyanın halına,

Gurbet ayrı,sıla ayrı,el ayrı,

İnsanoğlu bölüşmüşler dünyayı,

Hudut ayrı,il ayrı yol ayrı.

İnsanlar belli ki kötülüğe kapılmış,

Nice canlar kastına silahlar yapılmış,

Tetikler çekilip bombalar atılmış,

Düşman ayrı, dost ayrı,el ayrı.

Kardeş kardeşe düşman oluyor,

Gençlik elden gidip hayat soluyor,

Ömür geçiyor vade doluyor,

Ölüm ayrı zulüm ayrı çöl ayrı.

Atilla`m artık son sözün söyle,

Dünya halıdır işte böyle,

Gördüğün kullara sen nasihat eyle,

Aşk ayrı sevgi ayrı gül ayrı.', 'Ne söyleyim şu dünyanın halına, Gurbet ayrı,sıla ayrı,el ayrı, İnsanoğlu bölüşmüşler dünyayı, Hudut ayrı,il ayrı yol ayrı. İnsanlar belli ki...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-hali-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyim Var', 'neyim-var-atilla-gozukucuk-w29w5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Garip geldim, bu ele gene garip giderim,

Azrail gelip canım isterse benden,

ölmemek için elde fermanım mı var,

Yoksa canım vermeye dermanım mı var.

Cevher yüklü kervanım yok,

Kahır çekecek dermanım yok,

Haktan başka sevdiğim yok,

Hakka ulaşmaya niyazım var.

Dağlardan aşacak yolum mu var,

Ayrılık mı var ölüm mü var,

Bana hergün böyle zulüm mü var,

Huzuru mahşerde suçum mu var.', 'Garip geldim, bu ele gene garip giderim, Azrail gelip canım isterse benden, ölmemek için elde fermanım mı var, Yoksa canım vermeye dermanım ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neyim-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül ve Diken', 'gul-ve-diken-yurdagul-kurnaz-q2tdk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülün dikeniyle cizdim seni kalbime 

Siirin gök_kusagi rengi, mavilikte 

Ahengine; gülün kokusunu vermekte 

Seni gördüm, her baktigimda penceremde 

Her gün uyandigimda 

Mavili Merhabayla 

Sen___gözümün topragi 

Sen___gözümün bebegi 

Sen___kalbimin gözü 

Sen___benligimin özü 

___________________Sen bilmedin 

___________________Sevdin 

Sevildigini 

___________________Bilmedin 

___________________Bilemedin 

Ne cok sevdim 

___________________Aklina getir 

____________________________Bilseydin 

___________________________________Gelirdin 

Gülün rengi kirmizi 

Yesili ise dikeni

Gül&Diken___________________________________Ben', 'Gülün dikeniyle cizdim seni kalbime  Siirin gök_kusagi rengi, mavilikte  Ahengine; gülün kokusunu vermekte  Seni gördüm, her baktigimda penc...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gul-ve-diken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar/Sonbahar', 'i-lkbahar-sonbahar-yurdagul-kurnaz-awhn4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '*Ilkbaharim 

Renksiz dünyanim 

Tek rengisin 

Gözlerinde isik 

Dudaklarinda hayat var 

Dökülsün dudagindan, 

En umutlu sarkilar 

Acinca baharin disi gülleri 

Duy cilginca öten bülbülleri 

Ciceklerin en güzeli 

Gül 

Güllerin en güzeli 

Sen 

Sevginle gonca güldür yüregim 

Her sevdigini söylediginde 

Tomurcuk gül olur 

Özlem dökülür ellerime... 

°Sonbaharim 

Bir cift göz istiyorum 

Can evimi görecek 

Bir görebilsem gözlerini 

Beklenmedik bir anda 

Ne yaprak düser sonbaharda 

Ne yagmur 

Ne aci kalir yürekte 

Ne gözyasi 

Bir degse gözlerin 

Gözlerime 

Ne sitem kalir gecemde 

Ne matem 

Ne kadar özledim, bir bilsen! 

Yagan yagmurum ol 

Beyaz düslerime 

Bekledigim 

Özledigim 

Bir gün mutlaka....', '*Ilkbaharim  Renksiz dünyanim  Tek rengisin  Gözlerinde isik  Dudaklarinda hayat var  Dökülsün dudagindan,  En umutlu sarkilar  Acinca bahar...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ilkbahar-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Yangini', 'yurek-yangini-yurdagul-kurnaz-au81y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüregim yaniyor 

Söküp atasim geliyor 

Okyanusun en derinine 

Tuz bassam kanayan yaralarima 

Kabuk baglar anilarim 

Ve zaman, zaman 

Kanasada 

Zamani durdurup 

Derin bir uykuya dalarim 

Hic u_yan_ma_ma_si_ya!', 'Yüregim yaniyor  Söküp atasim geliyor  Okyanusun en derinine  Tuz bassam kanayan yaralarima  Kabuk baglar anilarim  Ve zaman, zaman  Kanasad...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yurek-yangini-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Divane Gönlüm', 'deli-divane-gonlum-atilla-gozukucuk-9ueuw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deli gönlüm geze geze yorulup gelirsin,

Nerede bir güzel görsen eğlenir kalırsın,

Arı gibi her çiçekten balın alırsın,

Uslanmadın mı divane gönlüm.

Gönül çıkıp şu dağlara bakmak istersin,

Azgın sular gibi akmak istersin,

Her gördüğün güzelle kalmak istersin,

Çekilmez kahrın senin gönlüm.

Yüce Mevlam nasip eyle ölümü,

Terk edeyim vatanımı ilimi,

Yarden ayrı düşürdün yolumu,

Ne deyim ben sana divane gönlüm.', 'Deli gönlüm geze geze yorulup gelirsin, Nerede bir güzel görsen eğlenir kalırsın, Arı gibi her çiçekten balın alırsın, Uslanmadın mı divane ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deli-divane-gonlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güze dargınım', 'guze-darginim-i-lhami-arslantas-4i224', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bam  telini kırdı gönül sazımda,

Mızraba dargınım saza dargınım.

Zemheri yaşadım ömür yazımda,

Bahara dargınım  yaza dargınım.

Düşürdü ayazı bahtıma, sıngın,

Ayağım ayazda  içimde yangın,

Nedendir bilemem olmuyor engin,

Yüreğime düşen köze dargınım.

Dağlarda çiçektim,ormanda çınar,

Neden yaralarım durmadan kanar,

Canımın cananı gel  gönlüm onar,

Sevilip sevmeyen göze  dargınım.

Emekleyen dizim koşar diyerek,

Bir cemre gönlüme düşer diyerek,

Güldü bana geçti beşer diyerek,

Şu kalbimi kıran söze  dargınım.

Der İlhami  gece kara  kömürden

Göğsüm çelik imiş özüm demirden,

Bu sene kırk beşi düştük ömürden,

Başımda dolanan güze dargınım.', 'Bam  telini kırdı gönül sazımda, Mızraba dargınım saza dargınım. Zemheri yaşadım ömür yazımda, Bahara dargınım  yaza dargınım. Düşürdü ayazı...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guze-darginim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesiftir', 'kesiftir-akin-akca-9hq3j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geçmiş denen bir inanç, 

bilmek adına gelecekte bugün yazılmıştır.

kadın anlık yaşar, prangasına suskun erkek de. 

ama pençe hayatı dürter ve 

istikbaline geçmişin isyan eder

o her daim selam duran uğurböceğine 

lanet ile:

o, yukarıda; 

olamaz görevimiz

ancak idamemiz,

baykuştur uğurböceği; 

istekler çatışması, değil.

dağcının yolu girifttir,

bağdaş çıkarken bilinçtir.

emek yadeder

kaçı anlaşılmıştır

karizma arı peteklerinden,

döğme tanımlamayan efsununda

intizar kızılderilinin

geçmişte …', 'geçmiş denen bir inanç,  bilmek adına gelecekte bugün yazılmıştır. kadın anlık yaşar, prangasına suskun erkek de.  ama pençe hayatı dürter v...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kesiftir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Gençlik', 'giden-genclik-atilla-gozukucuk-rq1te', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Heba ettim geçirdim günümü,

Nideyim gitti gençliğim,

Seninle süremedim demimi,

Nideyim gitti gençliğim.

Ömür geçiyor bilemedim,

Hep ağladım gülemedim,

Bülbül olup bir dala konamadım,

Nideyim ah gitti gençliğim.

Günahım sevabım yazılır,

Ömrüm yıllara dizilir,

Bedenim bende bozulur,

Ömrüm nidem gitti gençlik.

Gitti geri gelemez,

Gelip beni bulamaz,

Bu bedenim sermayesini,

Ömrümü versen geri getiremez.', 'Heba ettim geçirdim günümü, Nideyim gitti gençliğim, Seninle süremedim demimi, Nideyim gitti gençliğim. Ömür geçiyor bilemedim, Hep ağladım ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/giden-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Armağan Olsun', 'adi-armagan-olsun-mehmet-sait-akkus-lgtt3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinde eriyorum

Kar tanesi gibi

Senden bir şey istiyorum

Nur tanesi gibi

Pamuk gibi elleri

Gözleri sana benzesin

Parıldasın gözleri

Gülüşü sana benzesin

Hazırla sen papuçları

Ayakları üşümesin

Ufacık avuçları

Soğuktan büzülmesin

Allahım,ilk doğan

Üzülmem kız olursa

Adını koyalım Armağan

Oğlan değil kız olursa

Gözleri yumuk yumuk

O gizemli gülüşü

Büyümüşte çarçabuk

Badi badi yürüyüşü', 'Gözlerinde eriyorum Kar tanesi gibi Senden bir şey istiyorum Nur tanesi gibi Pamuk gibi elleri Gözleri sana benzesin Parıldasın gözleri Gülü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adi-armagan-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silik Hayaller', 'silik-hayaller-yavuz-bayram-caliskan-eda2y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayal bıçaklarına bilenir günler

Bu gözyaşları artık çok geç

Sen öldürmek ister misin seni? 

Seninle yaşayan sensizliği

Can acıtıcı gerçekler kuru ve soğuk

Hayallerini kırbaçlayan kim? 

Yüreğinden çekip çıkarılan ne? 

Günleri yiyen zaman denen açlık durur mu sanırsın? 

Yağmurunu bekleyen toprakların sabrı biter mi? 

İçinde kırılan camlar seninle değil mi? 

Söküp atılır mı pencereler? 

Herkes denizlerle yaşar ama denizler gibi yaşayamaz.

Hüzünleniyorum, dokunsan gözlerim yaşaracak,

Neyi özlediğimi hissetmiyorum

İklimlerini, dağlarını, şefkatini özlüyor,

Dağınık ve ince ışıklarıyla dolunay.

İnsanı çaresizleştiren ölüm mü? 

Yaşama kızgınlığımın gizli yansıması,

Cehennemin en dibine,

Ateşin en kor yerine bırakıyorum ölümü,

Ve soluk alıyorum,

Silik hayaller, ömür denen zaman gözlerime ışıyor', 'Hayal bıçaklarına bilenir günler Bu gözyaşları artık çok geç Sen öldürmek ister misin seni?  Seninle yaşayan sensizliği Can acıtıcı gerçekle...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/silik-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkın Demleri', 'kirkin-demleri-yavuz-bayram-caliskan-x3t8x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nazlıca eğildi o yüce çınar,

Kaçınılmaz alın yazısı,

Sırtında yılların ağırlığı,

Düştü saçlarına sıra sıra,

Yapraklara döküldü sevdalarım.

Sürüklenmiş gemiler barınağı,

Terkedilmiş mevsimler hep yan yana,

Zaman harcanmış,

Yapayalnız kalmış hatıralar,

Terkedilmiş genç zamanlar,

Sefalete giden yolcu,

Ömrün sürüklediği bir can,

Hüzünlü beklemelerin sabahı,

Su götürmez çalkantıların dinişi,

Kırkın demleri şekersiz ve tatsız,

Nasıl da yansıyor kırışmış alınlara,

İşgaller yaşanıyor tüm bedende,

Nefretin fitili ateşlenmiş bir kere,

Ölüme gider bu yol tek yön,

Tetiği çekilmiş tabanca,

Namlusunu terk eden kurşun,

Yıllar delik deşik, ömür ağır yaralı.

Hiç aklımdan çıkmıyor yaşanmış hatıralar,

Kırkın demleri sarhoş, başını eğer ve gider.

Hancı ''getir ömürden yaşanmış bir acı''

Gözlerin solgun ışığı teslim olmaya gidiyor.

Kentin sokakları yaşamın tadında,

Bu devir bu devran böyle döner,

Bir can doğar bir can söner.', 'Nazlıca eğildi o yüce çınar, Kaçınılmaz alın yazısı, Sırtında yılların ağırlığı, Düştü saçlarına sıra sıra, Yapraklara döküldü sevdalarım. S...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kirkin-demleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esaret Yürekleri', 'esaret-yurekleri-yavuz-bayram-caliskan-e4ark', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dallarında tomurcukları, cilveleşen kuşlar,

Bülbül nameleri, gün batımının kızıllığı,

Çuha çiçekleri, mor menekşeli sabahlar,

Çığlıklı kırlangıç uçuşları,

İlk tren yolcuları gelir,

Ay çatıma düştüğü zaman,

Kuşların göçüdür, sefil kuşların,

Sefil sürüklenmeleri uzak iklimlere.

Çıkışları yakala bacalardan çıkmasın kara dumanlar,

Koruluklardan gelir esintinin sesi,

Nemli ve yeşil kokulu suları duru bir ırmak,

Dağlar baharında nefeslenir,

İçimdeki yağmurun su birikintileri,

Sevdanın bıraktığı anıların dünyası,

Ve bütünüyle silinemeyenler,

Sürüklendim, bekledim,

Senin yeşillendiğin gökyüzü altında yürüyen bir adamım,

Ruhumun sükuneti, selviler, çamlar, meşeler,

Rengini sergiliyor derin maviler,

Alaca karanlığın ilk ışıkları,

Umutlar izdihamı sokaklarım.

Aştığım yol doruklar değil mi? 

Anılarım sevda vahası,

Güzelliğin bana sunulan bir gül mü? 

El sallayan hüzünler mi çocuk? 

Yağmurları terk ettik, sisle inen yağmurları,

Yıllara yazdığım mektuplar bir kutuda,

Kurdeleli kara çiçekler,

Dört duvarın gizleri, hazin ölümlerde,

Sevgi ektiğimiz yaşam bahçelerinde,

Boy atıyor sevda esaret yüreklere,

İçime ılık rüzgarlar geliyor,

Arkamda güneş var,

Koşulsuz bağımlılık aşkın esir kanatları,

Uçup gidecek yıllara yelkenler,

Doğru ışığı gören bizler,

Çekiliyoruz mevsimlerden.', 'Dallarında tomurcukları, cilveleşen kuşlar, Bülbül nameleri, gün batımının kızıllığı, Çuha çiçekleri, mor menekşeli sabahlar, Çığlıklı kırla...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/esaret-yurekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmısın?', 'varmisin-nalan-kahraman-ocj6a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgimidir hayatı var eden,

Hayatmıdır sevgiyi var eden,

Kişilermidir saygıyı var eden,

Saygımıdır Kişileri var eden? 

Ne hayat yaşanıyor,

Ne de sevgiler yaşanıyor yürekten,

Ne kişiler anlaşılabiliyor,

Nede saygılar duyulabiliyor yürekten.

Varmısınız sevmeye,

Varmısınız hayatı yaşamaya,

varmısınız saygı duyup duyulmaya yürekten? 

Ben varım da.........', 'Sevgimidir hayatı var eden, Hayatmıdır sevgiyi var eden, Kişilermidir saygıyı var eden, Saygımıdır Kişileri var eden?  Ne hayat yaşanıyor, N...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/varmisin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zenginim Ben', 'zenginim-ben-nalan-kahraman-x5ocn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine eve geldim,

Balkonu yıkadım,

Defter,kalem,kitap,kahve ve sigaramla

Masamı kurdum.

Rüzgar gülüm ile konuştum biraz,

Bugünümü anlattım.

Gülümser gibi ses verdi şıkırdayarak.

Yıldızlar geldi,her akşam olduğu gibi,

Ay dede gelmedi bu akşam,

demek bu sabah güneşi yıldızlar teslim edecek,

Ne kadar şanslıyım ben ya! 

Rüzgar gülüm,

Yıldızlar,

Ay dede,

Güneş,

Kitaplarım,

ve....

Defterim var........

Meğer ben ne zenginmişim.

Ya fakir olup da,

Duvarlarla konuşuyor olsaydım..............', 'Yine eve geldim, Balkonu yıkadım, Defter,kalem,kitap,kahve ve sigaramla Masamı kurdum. Rüzgar gülüm ile konuştum biraz, Bugünümü anlattım. G...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zenginim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın', 'anlarsin-nalan-kahraman-5wfgx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdim, sevilmedim

Sevildim,sevemedim.

Sev dediler,

Sevil dediler,

Karşılık beklemeden sev,

Karşılık vererek sevil dediler.

Bir şey anlamadım dedim.

Bir gün anlarsın dediler.....', 'Sevdim, sevilmedim Sevildim,sevemedim. Sev dediler, Sevil dediler, Karşılık beklemeden sev, Karşılık vererek sevil dediler. Bir şey anlamadı...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlarsin-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidermisin', 'gidermisin-suleyman-yavuz-ztobx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Git desem gider misin? 

Unutur musun beni

Siler misin kalbinden

Söyle gider misin? 

Deliler gibi seviyorsan 

Âşıksan 

Söyle yapabilir misin? 

Belki sen yaparsın

Gidersin unutursun

Silersin beni

Ama sen bunu benden bekleme

Gidemem 

Gitsem bile unutamam seni

Silemem asla kalbimden 

Çünkü aşığım 

Seviyorum seni deliler gibi

Seni unutmak seni silmek

Buralardan çıkıp gitmek

En iyisi inan 

Tabancayı dayayıp şakağıma

Ateşlemek

İnan bu seni unutmaktan silmekten 

Terk edip gitmekten 

Daha iyi', 'Git desem gider misin?  Unutur musun beni Siler misin kalbinden Söyle gider misin?  Deliler gibi seviyorsan  Âşıksan  Söyle yapabilir misin?...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidermisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-sezai-sengonul-nebt5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki eli iki yakamda

Vijdanımın

Med-Cezir duygular

Kıskacında

Kuytu bir kuyuda

Saklıyordum kendimi

Türkistanlı

Filistinli

Keşmirli

Bosnalı

Ve yüreği yanan

Yüreği bende atan

Mazlumların tümünden

Bir gün gördü bir çeçen

Tanımıştı beni

Yöneldi Allah''a

Gösterdi beni

Dedi sobe

Sobelenmiş

Kekelemiştim

Utancımdan.', 'İki eli iki yakamda Vijdanımın Med-Cezir duygular Kıskacında Kuytu bir kuyuda Saklıyordum kendimi Türkistanlı Filistinli Keşmirli Bosnalı Ve...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/saklambac-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boyalı Basın', 'boyali-basin-mehmet-demir-atmali-axezv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Aşağıda adını zikrettiğimiz boyalı basın,

sırası ile neşredildiklerinde nasıl bir mesajın

ortaya çıktığını birilkte görelim.Yorumsuz...

GÜNAYDIN

_________HEY

____________ŞEY

_______________TAN

''GÜNAYDIN HEY ŞEYTAN''

not: Yaşı küçük olanlar hatırlayamayabilirler,

ancak bu gazeteler ülkemizde sırası ile yayınladı.

1989', '-Aşağıda adını zikrettiğimiz boyalı basın, sırası ile neşredildiklerinde nasıl bir mesajın ortaya çıktığını birilkte görelim.Yorumsuz... GÜN...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/boyali-basin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Ayrılık', 'zamansiz-ayrilik-cetin-ozyurek-nyhar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamansız ayrılık varmış 

Yaşamın her anında

Ummadığın bir olaymış

Zamanı gelip çatınca

Acı duymak varmış

Ömrünün bir anında

Birdaha görmemek varmış

Hasretin başladığı anda

Bırakmış olduğu hatıralar varmış

Yalnızca hatıralar

Onunla yaşamak varmış

Bundan sonraki hayatta', 'Zamansız ayrılık varmış  Yaşamın her anında Ummadığın bir olaymış Zamanı gelip çatınca Acı duymak varmış Ömrünün bir anında Birdaha görmemek...', ARRAY['Türk Edebiyatı','Şiir','Çetin Özyürek']::text[], 8.5, '{"poet":"Çetin Özyürek","poet_slug":"cetin-ozyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zamansiz-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplama-Çıkarma', 'toplama-cikarma-halil-i-brahim-ozdemir-iueqq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yarınımı bilmeden  hep dünlere bakardım...

Payladım, paylaştırdım,hergün yine bıkardım

Dere tepe düz sanıp giderken karanlıkta,

Hesabım çıkarmadır, topladıkça çıkardım..', 'Yarınımı bilmeden  hep dünlere bakardım... Payladım, paylaştırdım,hergün yine bıkardım Dere tepe düz sanıp giderken karanlıkta, Hesabım çıka...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/toplama-cikarma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-cetin-ozyurek-1l7u9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman gelirki çaresizlik

içinde bulunduğun zamanda

En mutsuz olduğun  anda

Yanında görmek istediğin kişi

Çıkar gelir karşına

İşte o zaman anlarsın

Dostluğun arkadaşlığın

Ne kadar kutsal

Ne kadar değerli olduğunu', 'Zaman gelirki çaresizlik içinde bulunduğun zamanda En mutsuz olduğun  anda Yanında görmek istediğin kişi Çıkar gelir karşına İşte o zaman an...', ARRAY['Türk Edebiyatı','Şiir','Çetin Özyürek']::text[], 8.5, '{"poet":"Çetin Özyürek","poet_slug":"cetin-ozyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dostluk-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-cetin-ozyurek-agqb1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok zaman oldu görüşmeyeli

Daha çokda zaman olacak

Ama biliyorum elbet

Bir gün bir yerde

Yeniden görüşeceğiz

Şu an belki çok erken

Belkide zamanı geldi

Seninle kavuşacağım 

Son yer kara toprak 

Bunuda iliyorum

Bu yüzden kendimi

Hep avutuyorum', 'Çok zaman oldu görüşmeyeli Daha çokda zaman olacak Ama biliyorum elbet Bir gün bir yerde Yeniden görüşeceğiz Şu an belki çok erken Belkide z...', ARRAY['Türk Edebiyatı','Şiir','Çetin Özyürek']::text[], 8.5, '{"poet":"Çetin Özyürek","poet_slug":"cetin-ozyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlem-246-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dicle', 'dicle-esref-uzulmez-njo38', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çığlıklar bile irkilir

Dilsiz kuyularda

bütün zamanların haykırışıdır.

Asi,bir o kadarda naif,

sınırsızlığım

hançerin gölgesidir; 

zulamda,sakladığım,

kanıma düşen

Dicle! 

sen,duy ve temizle

temizleki kurusun,

kanla yıkanan,çocuksu bakışlarım', 'Çığlıklar bile irkilir Dilsiz kuyularda bütün zamanların haykırışıdır. Asi,bir o kadarda naif, sınırsızlığım hançerin gölgesidir;  zulamda,s...', ARRAY['Türk Edebiyatı','Şiir','Eşref Üzülmez']::text[], 8.5, '{"poet":"Eşref Üzülmez","poet_slug":"esref-uzulmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dicle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum da Cuma', 'erzurum-da-cuma-halil-colak-d2vpu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüksek minarelerden şakır bülbül sesleri

İnsanların gönüllerinde açar hakkın gülleri

Kalplere açılır hakkın hakikat sırları

Erzurum da bir hoş olur dadaş Cuma günleri

Müezzinler yanık sesleriyle sala veriyor

Gönül sultanların şimdi hakka varıyor

İmamların minberden irşat ediyor.

Erzurum da bir hoş olur dadaş Cuma günleri

Sanki bayramdır bir telaş kaplar.

Sala ile birlikte abdestler başlar

Camiler tıklım tıklım dolmaya başlar

Erzurum da bir hoş olur dadaş Cuma günleri

Horasan ereni Cuma özlemiyle yanıp tutuşur

Elbet o güzel cemaat la bir gün buluşur

Hep gönül birliği ile imamla secdeye varılır

Erzurum da bir hoş olur dadaş Cuma günleri

Halil Çolak 26.8.2005 Cuma  Ankara', 'Yüksek minarelerden şakır bülbül sesleri İnsanların gönüllerinde açar hakkın gülleri Kalplere açılır hakkın hakikat sırları Erzurum da bir h...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/erzurum-da-cuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-zafer-mutlu-jz2iz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bırakın beyler,

altını,üstünü...

Çekiç havalanmış bir kere

vurdu vuracak çiviye...

Kaldıran sadece aracı..

Dan-dun vuracak ise

Çekiç.....

Çivi hiç yaralamaz mı

zannediyorsunuz

deldiği yeri.....', 'Bırakın beyler, altını,üstünü... Çekiç havalanmış bir kere vurdu vuracak çiviye... Kaldıran sadece aracı.. Dan-dun vuracak ise Çekiç..... Çi...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kimlik-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azerbaycan.', 'azerbaycan-gulnare-leman-lfh3j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azerbaycan odlar yurdu, doğma vatan

Senin için bu dünyaya gelmişim  ben,

Bu toprakda ben doğmuşum,senin için 

Can veririm,.ölürüm ben,Vatan için! ! ! 

Azerbaycan benim canım,göz bebeğim,

Damarımda akan kanım,varım,yokum,

Her şeyimsin,mutluluğum,gerçeğimsin

Can veririm,her taşın,her çiçeğin için..

Duşman gelip, at oynatır sinende,

Ağlıyorum yürek yanır sinemde.

Söyleyin siz nasıl  değim, gülüm de? 

Şehit artar her gün burda. bu yerde....

Karabağlı,azeriyim, Azerbaycan  kızıyım,

Vatanim  için ben her şeye hazırım..

Duşman korksun ben silaha razıyım,

Ben bir türküm,kan  dökürüm,Vatan için!', 'Azerbaycan odlar yurdu, doğma vatan Senin için bu dünyaya gelmişim  ben, Bu toprakda ben doğmuşum,senin için  Can veririm,.ölürüm ben,Vatan ...', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/azerbaycan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Doluyor', 'gozlerim-doluyor-osman-i-nci-144mo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün gidip beni, yalnız bırakacağını,

Mutluluklar içinde, başkasını saracağını,

Kâbuslarımın zamanla, gerçek olacağını,

Düşününce kahrımdan, gözlerim doluyor..

Birlikte büyüttüğümüz, gülleri sökeceksin,

Belki de bana sen, hep lanetler edeceksin,

Aslında seni sevdiğimi, hiç bilmeyeceksin,

Düşününce kahrımdan, gözlerim doluyor..

Kendi dünyanı kuracak, sileceksin maziyi,

Unutacaksın sana yazdığım, her bir heceyi,

Beynimi kemirip duran, cevapsız bilmeceyi,

Düşününce kahrımdan, gözlerim doluyor..

Nasıl dayanır bu gönül, senin yokluğuna,

Razıyım birlikte olmaya, karın tokluğuna,

Bakma kalbimin böyle, sakin durduğuna,

Düşününce kahrımdan, gözlerim doluyor..', 'Bir gün gidip beni, yalnız bırakacağını, Mutluluklar içinde, başkasını saracağını, Kâbuslarımın zamanla, gerçek olacağını, Düşününce kahrımd...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerim-doluyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-sahin-vural-6wfya', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gitmek,senden ayri uzak olan her yere.

Ardına bakmadan,asmak acı mavi denizleri.

Sana tutsak bu yüregi,sökmek yerinden acıtmadan.

Yitmek gözlerinden,agır agır mum misali.

Silmek,tüm hatıralari tek bir kalemde.

Sevmek yeniden korkusuzca,asıl şimdi zor olan.', 'Gitmek,senden ayri uzak olan her yere. Ardına bakmadan,asmak acı mavi denizleri. Sana tutsak bu yüregi,sökmek yerinden acıtmadan. Yitmek göz...', ARRAY['Türk Edebiyatı','Şiir','Şahin Vural']::text[], 8.5, '{"poet":"Şahin Vural","poet_slug":"sahin-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kacis-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahu Gözlerin Kaldı', 'ahu-gozlerin-kaldi-osman-i-nci-upgm2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşam sensiz asla, devam etmeyecekti,

Bu gönül yokluğunda, hiç gülmeyecekti,

Bir gün ayrılan da, geriye dönmeyecekti,

Senden geriye şimdi, ahu gözlerin kaldı…

Sevdalara düşmek, çok basitmiş sandım,

Gönlümü bir verdim ki, uğrunda yandım,

Söylenen yalanlara ben, nasılda inandım,

Senden geriye şimdi, ahu gözlerin kaldı…

En güzel günler, yalnız sende sanırdım,

Güvenilir dost diye, bir tek seni tanırdım,

En bilinmez anıları, hep sana anlatırdım,

Senden geriye şimdi, ahu gözlerin kaldı…

Sabır ile katlandım, belki düzelirsin diye,

Muhtaçtın her zaman, bir küçük sevgiye,

En nankörü senmişsin, iftiraymış kediye,

Senden geriye şimdi, ahu gözlerin kaldı…', 'Yaşam sensiz asla, devam etmeyecekti, Bu gönül yokluğunda, hiç gülmeyecekti, Bir gün ayrılan da, geriye dönmeyecekti, Senden geriye şimdi, a...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ahu-gozlerin-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkının Büyüsü', 'askinin-buyusu-osman-i-nci-w8ar1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bendeki tek gerçeksin, gerisi yalan,

O bakışlarındır beni, sevdaya salan,

Beynimin içinde öylece, çakılı kalan,

Gözlerin rengine, kapılıp geldim…

Kimseyi duymadım, kulak tıkadım,

Yüreğimi tertemiz, aşkınla yıkadım,

Yaptıklarıma hiç, pişman olmadım,

Kaşların karasına, vurulup geldim…

Ne arkadaş kaldı, nede dostlarım,

Ayrılık var demiyor, artık fallarım,

Sana götürür beni, bütün yollarım,

Saçların peşinden, savrulup geldim…

Yaşam yeni başladı, beyaz sayfa ile,

Üzmüyor artık beni, en acı olay bile,

Ne korkum kaldı, ne bir dirhem çile,

Aşkının büyüsüne, kapılıp geldim…', 'Bendeki tek gerçeksin, gerisi yalan, O bakışlarındır beni, sevdaya salan, Beynimin içinde öylece, çakılı kalan, Gözlerin rengine, kapılıp ge...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askinin-buyusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soramadım Ben', 'soramadim-ben-osman-i-nci-unqeq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana umutları verip, önce güldürdün,

Sonra mezarımı kazıp, her gün öldürdün,

Hayatımdan on dokuz yıl, aldın götürdün,

Bunun hesabını sana, soramadım ben…

Öylesine güzeldi o, yaşam zevkimiz,

Sonsuza dek sürecekti, tatlı keyfimiz,

Neden böylece bitti, bizim hikâyemiz,

Bunun hesabını sana, soramadım ben…

Yalanmış her sözlerin, kandım deli gibi,

Tüm evrene savurdun, seher yeli gibi,

Katlandım acılara, ermiş bir veli gibi,

Bunun hesabını sana, soramadım ben…

Bak senin yüzünden, başımı taşa vurdum,

Dar oldu bana, bunca yaşadığım yurdum,

Bütün cezasını aşkın, çektim de durdum,

Bunun hesabını sana, soramadım ben…', 'Bana umutları verip, önce güldürdün, Sonra mezarımı kazıp, her gün öldürdün, Hayatımdan on dokuz yıl, aldın götürdün, Bunun hesabını sana, s...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soramadim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Döneceğini Söyle', 'bana-donecegini-soyle-sahin-vural-rlgcr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yer sesiz,sakin,uykuda

Sende uzaklarda bir yerlerde uyuyorsun

Ve ben her zamanki gibi

Seni düşünüyorum

Gök yüzüne bakıp

Kimbilir belki sende uyanıksındır

Belki beni düşünüyor

Beni özlüyorsundur

Sakın kaçırma gözlerini yıldızlardan

Çünkü seni görüyorum o en parlak yıldızda

Pırıl pırıl parlayan gözlerini görüyorum

Eğer sende biraz sevdiysen beni

O en parlak yıldıza bakıp

Bana döneceğini söyle 

 AŞKIM', 'Her yer sesiz,sakin,uykuda Sende uzaklarda bir yerlerde uyuyorsun Ve ben her zamanki gibi Seni düşünüyorum Gök yüzüne bakıp Kimbilir belki s...', ARRAY['Türk Edebiyatı','Şiir','Şahin Vural']::text[], 8.5, '{"poet":"Şahin Vural","poet_slug":"sahin-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bana-donecegini-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-osman-i-nci-xnz1y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Döneceğini sanıp, onca yıl sabrettim,

Bir yıldız kaydı gökte, sana benzettim,

Bak işte şimdi seni, hepten kaybettim,

Yokluğuna alışmak, mümkün mü söyle? ..

Korkutucu bir, kâbus olur bu akşamlar,

Karşımda cellat gibi, sanki bütün anılar,

Etrafımı sarar, dayanılmaz büyük acılar,

Yokluğuna alışmak, mümkün mü söyle? ..

O günleri unutmak, imkânsızdır bana,

Bu kısa zamanda, doymadım ben sana,

Yüreğim savrulur durur, dört bir yana,

Yokluğuna alışmak, mümkün mü söyle? ..

Beklenmeyen gidişin, yıktı deli gönlümü,

Üzüntün ile, yaş doldurdu bak iki gözümü,

Hicran oldu bu aşkımızın, her bir bölümü,

Yokluğuna alışmak, mümkün mü söyle? ..', 'Döneceğini sanıp, onca yıl sabrettim, Bir yıldız kaydı gökte, sana benzettim, Bak işte şimdi seni, hepten kaybettim, Yokluğuna alışmak, mümk...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soyle-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz', 'yakamoz-sair-salma-e9cef', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yakamozu....bilirmisin...

İşte  ben  oyumm....

Yürekli  sevdalara....

Olsun  ilk  oyumm....', 'Yakamozu....bilirmisin... İşte  ben  oyumm.... Yürekli  sevdalara.... Olsun  ilk  oyumm.......', ARRAY['Türk Edebiyatı','Şiir','Şair Salma']::text[], 8.5, '{"poet":"Şair Salma","poet_slug":"sair-salma","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yakamoz-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onu ondan almışsın', 'onu-ondan-almissin-sair-gaddar-16-p276e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onu alıp getirmişsin uzak diyarlara,

Girmişsin yüreğinin en derin noktalarına,

Sıkmışsın mermileri duygularına,

Ne yapmışsın böyle,

Onu ondan almışsın.

...

Acımadın mı hiç ona,

Yazık yazık demedin mi,

Yüreğinde seni taşıdığını bilmedin mi,

Neden kıydın ona,

Bak ne yapmışsın,

Onu ondan almışsın.

...

Geçen rastladım,

Bi deri bi kemik,

Yaşlar vardı yüzünde,

Her tarafı delik teşik.

...

Gözleri kapalıydı görmüyordu,

Eliyle  solunu tutmuştu,

Kanlar çindeydi,

Vuruldum.

...

Yaklaştım usulca,

Seni sayıklıyordu,

Aylar olmuş,

Kanlar akmakta,

Bu ateş alevlenmekte.

...

Elini kaldırdım solundan,

Kaldırmaz olaydım,

Uzun bi boşluk vardı,

Yüreği yoktu,

Ama adın hala vardı,

Ne yapmışsın böyle,

Kendini ondan almışsın.

...

Kırmışsın elini kolunu,

Parçalamışsın vücudunu,

Kapamışsın aydınlık yolunu,

Yaralamışsın solunu

Ne yapmışsın böle,

Dünyasını yıkmışsın.

...

Biliyormusun hala seviyor,

Hala seviyor,

Anlamadın hiç sevgisini,

Bilmedin kıymetini,

Hep kötülediğini,

Ateşlere vermişsin.

...

Kırmışsın içindeki umudunu,

Kurutmuşsun yaşama suyunu,

Bırakmamışsın gökte bulutunu,

Ne yapmışsın zalim,

Onu ondan almışsın.

...

Acıları yük yapıp yüklemişsin,

Göğe çıkartıpta itmişsin,

Fırtına misali kopupta gitmişsin,

Ne yapmışsın böyle,

Onu ondan almışsın.

...

Bak bi etrafına,

Varmı seni onun gibi sevenin,

Sor bi zamana,

Varmı senin için hergün ölenin.

...

Bulamazsın aşkına sadık,

Kandırırlar,atarlar sana kazık,

Kalırsın ortada aşkına yazık,

aldın onu ondan yeter artık.

...

Onun için bir gülsün,

Gülden güzel meleksin,

Belkide kır çiçeği yeni açmış,

Belkide değişiyle yaşantısısın sen,

Ama benim için katilsin sen.

...

Belkide konuşmam yerine,

Seni parçalamam gerek,

Sana onu anlatacağıma,

İki gözünü çıkarmam gerek.

...

Belkide bir kurşun,

Belkide diri diri mezara seni gömmem gerek,

Uçurumdan itmek,

Dağa taşa vurmam gerek.

...

Unutmuş olsaydı seni,

Kalbini alırdım senden,

Elini kolunu alıp,

Seni karanlığa mahkum etmem gerek,

Biliyormusun yapardım bunları gülerek,

Çünkü sen onu ondan almışsın.

...

Zincirlere vurmuşsun,

Ateşlerde tutmuşsun,

Sanki o bir hedef,

Tam on ikiden vurmuşsun,

Ah! ulan hayırsız,

Olduğun yerden vurmuşsun.

...

Git şimdi git, hadi git defol,

Bırakmadın onda bırakmadın,

Ne göz ne kol,

Bak gezmekte dağlarda,

Karanlık gözlerle yol yol,

Sana son cümlem olmasın bi daha,

Ah! ulan zalim,

Bak ne yapmışsın,

Dağlara sürgün etmişsin.

...', 'Onu alıp getirmişsin uzak diyarlara, Girmişsin yüreğinin en derin noktalarına, Sıkmışsın mermileri duygularına, Ne yapmışsın böyle, Onu onda...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":113,"source_url":"https://www.antoloji.com/onu-ondan-almissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretemezsin', 'ogretemezsin-sahin-erturk-qgwor', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen güzel evet,evet sen

Öğretemezsin bana aşkı

Öğretemezsin bana

Acı çekmeyi? 

Öğretemezsin,hasreti

Öğretemezsin

Ne yazacağımı? 

AYŞE yede yazarım

FATMA yıda severim

Kime ne bundan? 

Kime zararı var bunun? 

NERMİN kim biliyormusun? 

Kalbime girdin mi? 

Gördün mü CESUR ŞAİRİ? 

Öğretemezsin güzelim

Ben aşkı ezbere bilirim

Sen daha aşkın

İlk sayfalarında

A,B,C lerdesin? 

Oysa ben,oysa ben

Son sayfaya geldim

Bir değil,on değil

Sayısını unuttum

Kaç kere HATİM ettim aşkı? 

Sus ne olur sus güzelim

Daha fazla yazdırma bana

Güldürme kendine

Sen bana hiç birşeyi

Öğretemezsin,öğretemezsin

(27.08.2005-Yeni)', 'Sen güzel evet,evet sen Öğretemezsin bana aşkı Öğretemezsin bana Acı çekmeyi?  Öğretemezsin,hasreti Öğretemezsin Ne yazacağımı?  AYŞE yede y...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ogretemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-sezai-sengonul-1lrh8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşı dağlara konsam

Yamaçlarında dolaşsam

Yoklayıp börtü böceği

Hal hatır sorsam

Varsa kar yukarda

Kızakla kaysam

Hemen orada

Bir Ebabilin kanadında

Yükselsem göğe

Güneşe selam verip

Gölgesinde iki kelam edip

Misafir ederse yatıp

Bir kuşluk vakti

Kalmadan sarı sıcağa

Çiçeklere doğru 

Yol alsam

İnince aşağıya

Koklasam çiçekleri

Toplasam başıma

Solmayı sorsam

Onlara

Sonra bir çırpıda

Çıksam ağaçlara

Yorsam sincapları

Alsam pelitlerini

Topaç yapsam

Yukarda 

Bir dalda yaylanıp

Zıplasam bulutlara

Pamuk şeker alsam

Top top yapıp

Üç-beş tanede

Arkadaşlara atsam

Yorulmuşken

Yokken uçaklar

Kıvrılsam bir köşeye

Uykuya dalsam

Seher vakti uyanıp

Bulsam Süheyl yıldızını

Sevip gıdıklasam

Üzerine çiyinin

Resmimi yapsam

Üzerinden çiselesem

Rüzgarla

Çıvgın olsam toz toz

İnsem yüreğine Şairlerin

Şiir olsam Söz söz.

Çıvgın:Fırtınayla karışık savrulan ince yağmur tanecikleri..', 'Karşı dağlara konsam Yamaçlarında dolaşsam Yoklayıp börtü böceği Hal hatır sorsam Varsa kar yukarda Kızakla kaysam Hemen orada Bir Ebabilin ...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/dus-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkilem', 'i-kilem-zafer-mutlu-f49zy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biraz hüznün 

bana zararı yok

kendime dönüyorum...

fazlaca gülmemin

bana faydası yok

yanlış anlaşılıyorum....', 'biraz hüznün  bana zararı yok kendime dönüyorum... fazlaca gülmemin bana faydası yok yanlış anlaşılıyorum.......', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ikilem-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silemedim Sensizliği', 'silemedim-sensizligi-ahmet-nural-ozturk-0d93g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin unutulmuşluğunda anımsadım adını

Sevgiydi

Kimbilir kimlerin kimsesiz dudaklarında

Sancıydı

Çağlardı dere suları deryada 

Dulda kirpikler ağlardı

Anımsadım adını

Nerdesin sevgi

Silemedim sensizliği', 'Gecenin unutulmuşluğunda anımsadım adını Sevgiydi Kimbilir kimlerin kimsesiz dudaklarında Sancıydı Çağlardı dere suları deryada  Dulda kirpi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/silemedim-sensizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim Sana....', 'hasretim-sana-nurdane-diken-ikze9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mah yüzüne, 

O güzel gözlerine, 

Hasretim sözlerine. 

Maziden gelen izine, 

Yağmurun ağlayan, sesinde 

Saçının her teline, 

....................Hasretim, 

Hasretim Sana. 

Bahçemde derlenen güllere, 

Özlemim bir tek güle. 

Şans kapımı çalsa bir kerre, 

Özlem ırmakları, birleşse göllerle. 

Bir tek gel diyen, sözüne 

Koşar giderim, gülüme. 

...................Hasretim. 

Hasretim sana. 

Soldurma beni, anlasana 

Çürürsün sende, 

Bitersin sende. 

İnadın, mutluluğumun katlinde, 

Yıllar benim katlimde. 

Beklerim aşk sahilinde. 

...................Hasretim. 

Hasretim sana. 

Anlatamıyan bir dile, 

Anlamayan bir gönüle, 

Esir oldum. 

Bittim. 

Sevdan da bende soldum. 

....................Hasretim. 

Hasretim sana......', 'Mah yüzüne,  O güzel gözlerine,  Hasretim sözlerine.  Maziden gelen izine,  Yağmurun ağlayan, sesinde  Saçının her teline,  ...................', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hasretim-sana-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet...', 'i-hanet-nurdane-diken-c8utr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana ihanet edersem eğer, 

Varlığım sensiz kalsın. 

Sensiz kalsın, tüm benliğim. 

Ellerim, ellerinden uzak. 

Bu ihanet, bana tuzak. 

Bunca sevmişken, bu bana uzak. 

Sen varlığımın yasası. 

Sen ciğerlerimin nefesi. 

Sen yirmidört saat ibâdetim. 

Sen sonsuz aşkım, hevesim. 

Arzularım, isyanlarım, sevincim. 

Sen benden, içeri ben. 

Ben olan ben, hiç kendisine, 

ihanet eder, varlığını yok eder mi? 

Sevgilim.', 'Sana ihanet edersem eğer,  Varlığım sensiz kalsın.  Sensiz kalsın, tüm benliğim.  Ellerim, ellerinden uzak.  Bu ihanet, bana tuzak.  Bunca s...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ihanet-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'doluNay', 'dolunay-baykal-kaanalp-mdctv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne gün bilir senin 

Sevdalı bakışlarını

Ne de dışarıda kalmış

Bir çanak dolunay', 'Ne gün bilir senin  Sevdalı bakışlarını Ne de dışarıda kalmış Bir çanak dolunay...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dolunay-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O(kuma) lar', 'o-kuma-lar-baykal-kaanalp-e7uxx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çaresizlik hedef

Kapışmalar yersiz

Kan durur

Damar kurur

Yolculuk belirsiz

Yetişmez bu bağırda

Bir erkek evlat

Okumalar son bulur

Kitaplar kapalı tutulur

Gelmiştir beklenen milat

Taze bir gelin güne

Zincirler gergin

Halkalar sıralı

Kavaklar çıralı

Kızlar ergin

Yaş uzun bir yol

Yeni bir endam bulunur

Heyecan hiç bitmez

Gelinler evden gitmez

Sıralar durdurulur', 'Çaresizlik hedef Kapışmalar yersiz Kan durur Damar kurur Yolculuk belirsiz Yetişmez bu bağırda Bir erkek evlat Okumalar son bulur Kitaplar k...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-kuma-lar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim', 'gelirim-haydar-okur-408e0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölmez de yaşarsam bir gün mutlaka

Zulmeden geceleri aşar gelirim 

Lale, gül, karanfil daha solmadan

Engelleri tınmaz koşar gelirim

Mordağlar ötesi cananın yurdu

Karşıma çıkıyor dağların kurdu 

Onulmazlık arttı dertler kudurdu

Razıyım her şeye düçar gelirim

Kış, kar, ayaz bastırsa mevsim

Mevsimler içinde sevdiğim sensin

Açılır dillerin duyarsam sesin

Zannetme ki gelmem uçar gelirim', 'Ölmez de yaşarsam bir gün mutlaka Zulmeden geceleri aşar gelirim  Lale, gül, karanfil daha solmadan Engelleri tınmaz koşar gelirim Mordağlar...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelirim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liana Ebru', 'liana-ebru-haydar-okur-ekcag', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Leylak açtı pembe tona büründü

İğde kokusuna sarındı ebru

Arzuladı kekik, çiğdem baharda

Narlar salkım saçak çiçeğe durdu

Aşka boyandılar  dediler ebru

El ele verdiler çiçekler bütün

Bal rengi gözlerden damladı ebru

Ruhuna doluştu gökkuşakları

Uçan kelebekler seslendi ebru', 'Leylak açtı pembe tona büründü İğde kokusuna sarındı ebru Arzuladı kekik, çiğdem baharda Narlar salkım saçak çiçeğe durdu Aşka boyandılar  d...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/liana-ebru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SuDe', 'sude-haydar-okur-lv8la', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana yayla kokulu sevda çiçekleri taşıyacağım 

Sen gökkuşağı şarkılar dinlemelisin, mavi, yeşil, pembe, mor

Uyanmadan tan basımında ve uykunun en tatlı bir yerinde

Uyanışlara yürümelisin,  çiçekçe öpüşleriyle aydınlığın

Doyurmaz  bunlar bilirim,  seviye susamışlığını

Dolsa da ay ışığı, yıldız pırıltıları  dünyana 

Ellerinde durulmalı uçarsuların tınıları  nota nota

Esmelisin meltemlerce yeğnik ve kelebek kanatlarınca

Ah! asude gönüllüm, evren çiçeğim

Sensiz yaşam külrengi, dünya ise ölü mor

Ukbada sen, ikbalde sen, nefes nefes düşlerde sen

Devranın çim-çiçek taze bahar,

Sevdikçe esrikleyen  en güzel sevgi ve  sevi de sen

Sede Asudem

KÖMEN', 'Sana yayla kokulu sevda çiçekleri taşıyacağım  Sen gökkuşağı şarkılar dinlemelisin, mavi, yeşil, pembe, mor Uyanmadan tan basımında ve uykun...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sude-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş düşmüşse bir yere', 'ates-dusmusse-bir-yere-erol-buker-nuj40', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ateş düşmüşse bir yere 

direnmeler nafile

yakar kül eder 

onulmaz bir yaradır

sevdalar yüreklerde.

şarkı olur, şiir olurlar

yazarsın istemesende.

Ben de öyle yazdım

oysa  yemin etmiştim yazmamaya 

ama gördüğünüz gibi

siz yazmıyorsunuz  ki

o sizi yazıyor satır satır

kalemi eline almış bir kere

Ateş düşmüşse bir yere

direnmeler nafile.', 'Ateş düşmüşse bir yere  direnmeler nafile yakar kül eder  onulmaz bir yaradır sevdalar yüreklerde. şarkı olur, şiir olurlar yazarsın istemes...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ates-dusmusse-bir-yere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-sezai-sengonul-npi84', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdaymış sonunda buldum adını

Elem acı hüzün koydum adını

Nedensiz niçinsiz teslim olunca

Yaralı kalbimde duydum adını.', 'Sevdaymış sonunda buldum adını Elem acı hüzün koydum adını Nedensiz niçinsiz teslim olunca Yaralı kalbimde duydum adını....', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevda-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim', 'mevsim-haydar-okur-ong5c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mızrabı vurdukça  gönlün teline, 

Yürek alkor olur, köz bayram eder

Eller uzandıkça, sevda düşüne, 

Şiir şölenlenir, söz bayram eder

Visalin vuslatın mevsimlerinde 

Yadlar bungunlaşır, dost bayram eder

Sığındığım vefasızlar yurdunda 

Dallar çiçek açmaz, çöl bayram eder 

İnsan gönlü taydurmaz bir eşkındır 

Uçar çiçek çiçek, yol bayram eder

Mevsimler de bir bir gelip geçtikçe 

Can figana durur, yer bayram eder

KÖMEN', 'Mızrabı vurdukça  gönlün teline,  Yürek alkor olur, köz bayram eder Eller uzandıkça, sevda düşüne,  Şiir şölenlenir, söz bayram eder Visalin...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mevsim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakma', 'yakma-tuncay-akdeniz-r8gux', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönülden çekersin aşkı sevdayı

Sazında inletip telini yakma

Aşk elinden içemesen badeyi

Uğruna dökülen selini yakma

Ahu zar figanı vermiş bülbüle

Onunda çektiği cefayla çile

Çekme sevdasını boşa nafile

Sevda ateşiyle çölünü yakma

Her gönül çekemez aşkın nazını

Geceye gündüze katar hüzün‘ü

Uykulara hasret koyar gözünü

Ömrünü tüketip yılını yakma  

Sevgi sevda denen hepsi aşktadır

Ne baharda nede kara kıştadır

Sevgi ile gönül aynı yaştadır

Soldurup dalında gülünü yakma

Tuncay diyor uzat sevgi elini

Hayatın sonuna götür yolunu

Seviyorsan gerçek aşkın gülünü

Büyüt o fidanı dalını yakma', 'Gönülden çekersin aşkı sevdayı Sazında inletip telini yakma Aşk elinden içemesen badeyi Uğruna dökülen selini yakma Ahu zar figanı vermiş bü...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıçak Yarası....', 'bicak-yarasi-hasan-akin-48vjy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İt Durmaz''da dört altı...

-Nöbete tutulmuşum-

Bir yanım Arat Dağı

Öte yanım Fırat...

Vurgun yüzüm biraz esmer; 

Kaderin yazdığı kadar kurşun

Kaderin yazdığı ne varsa 

Kader...

Beni de ayık tutarmı bu keder

Bu çelimsiz yalnızlık

Bu günahsız ihanet

Beni de eşiğine salar mı? 

Keşişlerin koynunda ki esaret! ! 

Hiçbir kelimen, elimden tutup da

karşıya geçirmedi beni....

(Mazı''ya)                 Birecik....', 'İt Durmaz''da dört altı... -Nöbete tutulmuşum- Bir yanım Arat Dağı Öte yanım Fırat... Vurgun yüzüm biraz esmer;  Kaderin yazdığı kadar kurşun...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bicak-yarasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Ülkesinde Bir Kent', 'gunes-ulkesinde-bir-kent-kadir-sen-v6v9j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1.

Gecenin

On ikisinden beri

Bir ses var ki…

Tarlalarda saban izi

Midesi boş.

Umurunda mı Sandon’un

Gemiler,beton parkeler

Kim sildi ayak izlerini? 

2.

Lacivert bir yağmur yağıyor

Tarse’ye

Ve lacivert bir tango 

Dudaklarımda

Kydnos dinliyor

hüzünlü…

Karanlık damlıyor,

Sekizgen kaideli

Kaymakam Ziya Bey’in

Saat kulesinden.

Unutma,

Bir avuç yıldızla 

Geleceğim sana

Sarı hüzünlerin kenti.

3.

Bir rüzgar esince

Sarıyor her yanını

Gece,

Turunç ve okaliptüs kokuları…

Yine de her şeye karşı 

Koruyamaz bu kenti

Toprağı ezer 

Kurşun gökyüzü.

4.

Bir tanıdık 

Elimi sıkıyor

Diodoros,

Mavi bir mektup 

Yazmak istiyor 

Memleketine…

5.

Yerinde duruyor mu hala

Desenleri çizilen

Kuşlar,

Yoksa öldüler mi? 

Betonlara çarparak.

6.

Uzaklaşıyor

Turuncu bir hüzün

Bulutların,

Kydnos’un ve kalbimin

Üzerinden…

İstanbul.2003', '1. Gecenin On ikisinden beri Bir ses var ki… Tarlalarda saban izi Midesi boş. Umurunda mı Sandon’un Gemiler,beton parkeler Kim sildi ayak iz...', ARRAY['Türk Edebiyatı','Şiir','Kadir Şen']::text[], 8.5, '{"poet":"Kadir Şen","poet_slug":"kadir-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/gunes-ulkesinde-bir-kent-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-fevzi-kunucen-olkax', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olurdu

Bırakıp gitmeseydin beni

Verseydin ellerini avuçlarıma

Baksaydın içine gözlerimin

Eskisi gibi barışsaydık-ne olurdu-

Hiç böyle bitmezdi kavgalarımız

Bir veda pusulası-hem de selamsız

Ah vefasız

Nasıl açarım kapısını o evin

Penceresine nasıl bakarım

Gayri sen yoksun içinde

Sokak lambalarını severdin

İşte yandı-sensiz bakamam

Bir gemi kalkacak

Sabaha karşı-sisler içinde

Ev''i-bark''ı

İşi gücü terkedip gideceğim

Yalnız-sevdan kalacak içimde', 'Ne olurdu Bırakıp gitmeseydin beni Verseydin ellerini avuçlarıma Baksaydın içine gözlerimin Eskisi gibi barışsaydık-ne olurdu- Hiç böyle bit...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Künüçen']::text[], 8.5, '{"poet":"Fevzi Künüçen","poet_slug":"fevzi-kunucen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kacis-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın tarifi', 'askin-tarifi-i-brahim-kilinc-0i9ek', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir mum ışığı gibi hafif rüzgârla

Sönecek kadar cılız ve hassas

Bir orman yangını gibi hafif rüzgârla

Her şeyi kül edecek kadar güçlü ve zalim

Su gibi en küçük engel önünde

Durgunlaşacak kadar sessiz ve sakin

Sel gibi önüne gelen tüm engelleri

Yıkacak kadar güçlü ve coşkun

Herkeste bir tarifi

Elbet var aşkın

Biri diğerini tutmaz

Oldum ben şaşkın', 'Bir mum ışığı gibi hafif rüzgârla Sönecek kadar cılız ve hassas Bir orman yangını gibi hafif rüzgârla Her şeyi kül edecek kadar güçlü ve zal...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askin-tarifi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Çoban', 'garip-coban-hasan-gorgu-6hudb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koyunların kuzuların

Yayılıyor yaylalarda

İçli çalıyor kavalın

Yankılanıyor dağlarda

Acıların kahırların

İnildiyor kavalında

Sen hep böyle yalnız mısın 

Çiçeklerin baharında

Bazen dalıyor gözlerin

Sanki için için ağlar

Söyle bana garip çoban

Seni de bir güden mi var', 'Koyunların kuzuların Yayılıyor yaylalarda İçli çalıyor kavalın Yankılanıyor dağlarda Acıların kahırların İnildiyor kavalında Sen hep böyle y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-coban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar Senin', 'yollar-senin-mehmet-koc-7q6e8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gideceğim diyorsun,

Git! 

Yakamozlarını da al,

yağmur damlaların kalmasın

git! 

Işıklarına ihtiyacım yok

sana yok! 

Unutacağım sana inat! 

Senli zamanlarımı saniyelerimi.

Gideceksin ha? 

Git o zaman,

yollar senindir..

Ama ben; 

ama yüreğim, 

asla senin olmayacak.

Ezerim bu yüreği,

oyarım bu gözleri

seni ararsa.

Yakarım dünyayı,

sen dönerse,

sene kokarsa

sen yaşarsa...

Git haydi,

yüreğim acıyor.', 'Gideceğim diyorsun, Git!  Yakamozlarını da al, yağmur damlaların kalmasın git!  Işıklarına ihtiyacım yok sana yok!  Unutacağım sana inat!  S...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koç']::text[], 8.5, '{"poet":"Mehmet Koç","poet_slug":"mehmet-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yollar-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yutturur', 'yutturur-hasan-geneyikli-n0sfe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sakalıma güldü, tarağı sandım

Nazı, hoşvarına, tarzına kandım

Görünçü bal sandım, zehire bandım

Çençüney* her öğün, zehir yutturur

Yumulup düştükçe*, kaptı çemkirdi*

İt kıçı çıkardı*, candan bezdirdi

Yazımı kararttı, bezgin gezdirdi

Çençüney geyinir, gendin yutturur

İp ilmek tutturmaz*, varım batırır

Dutun gölgesinde, itnen yatırır

İt kılı* yedirmez, yavan tattırır

Çençüney tatlı der, yavan yutturur

Sahı çölden gelik, tomusun* yazı

Garagışta esen, karlı ayazı

Huysuz kör, kel gimi, çekilmez nazı

Çençüney el vermez, naznan yutturur

Anası samısak, babası soğan

Gadderesin goyup*, hısleyin boğan*

Söze getmez sakar, gendinden doğan

Çençüneyden doğan, çalar yutturur

Geneyikli kem, küm eder diyemez

Evlatlı, ayelli, yimek yiyemez

Üsdüne başına, yeni geyemez

Evladı, ayeli, al gan yutturur

Çençüney: Ufak tefek. Çemkirmek:Azarlamak,yüz 

vermemek. İtkıçı çıkarmak:Engel çıkarmak. İp il-

mek tutmamak:İyi hal getirmemek. İt kılı:Cimri.

Tomus: Temmuz. Cenderesin  goymak: Sıkıntıya

Koymak. Hısleyn: gizli, bildirmeden. Yumulup düşmek

:Aşırı istemek', 'Sakalıma güldü, tarağı sandım Nazı, hoşvarına, tarzına kandım Görünçü bal sandım, zehire bandım Çençüney* her öğün, zehir yutturur Yumulup d...', ARRAY['Türk Edebiyatı','Şiir','Hasan Geneyikli']::text[], 8.5, '{"poet":"Hasan Geneyikli","poet_slug":"hasan-geneyikli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yutturur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydın', 'aydin-hasan-geneyikli-s507m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aydın aydınlıktır, zannedip yandık

Lobi aydınına, yıllarca kandık

Benden olamayan, senden usandık

Benden ayrı durma, benden ol aydın

Kimisi vakıflı, dışardan bağlı

Gizli servisten yer, göbeği yağlı

Pimsiz canlı bomba, örümcek ağlı

Ben senle ulusum, patlama aydın

Kültürü yabancı, yerli denilmez

Halkın kültürünü, namusu bilmez

Batının meyvesi, tatsız yenilmez

Kültürünü beğen, başım ol aydın

Mektubumuz güven, söze hakimdik

Sözümüz dinlenmez, durmazsın dimdik

Tuttuğumuz altın, olmuyor şimdik

Dilinle incitme, sözüm ol aydın

Alın teri katmaz, tezin alıntı

Makale, buluşun, dıştan çalıntı

Başın, kalbin, elin, gayri, kalıntı

Aldattığın yeter, çarem ol aydın 

Erozyona sebep, sonuç bilensen

Din, devlet düşmanı, açık görensen

Ülkeyi, insanı, şartsız sevensen

Geneyikli çalış, aydın adam ol', 'Aydın aydınlıktır, zannedip yandık Lobi aydınına, yıllarca kandık Benden olamayan, senden usandık Benden ayrı durma, benden ol aydın Kimisi ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Geneyikli']::text[], 8.5, '{"poet":"Hasan Geneyikli","poet_slug":"hasan-geneyikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben buyum', 'ben-buyum-hasan-geneyikli-o2wyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hava yoğunlaşıp, tozu kakmadan

Yerle gök ısınıp, güneş yakmadan

Dermanımı kesen, terim akmadan

İşe er başlayıp, çalışıp yedim

Her hayir kerrene, bir tip asardım

Tip üvezi yoksa, kepek saçardım

Piç dalları keser, dibin açardım

Hayirler ballandı, fıstıknan yedim 

Kavun, karpuz, acir, diktik bekledim

Kemik yaktım, duman verdim üfledim

Hıtta acir çıt, çıt, büyür dinledim

Kelek güneş emdi, bal kavun yedim

Üzüm şiresinden, dal dal sucuğu

Künefe, katmere, serpik konuğu

Pestil muskasında, içe konuğu

Gıdam fıstık oldu, severek yedim

Keklik, tavşan, davar, peşinde kaçtım

Duvar, çit üstünden, hoplayıp aştım

Sensizken edemiym, nedicim şaştım

Se diy deli oldum, aklımı yedim

Bıldır askerlemi, yaptım çavıştım

Hasretliğin çektim, yeten kavıştım

Bana çok hoş geldin, aşknan sıvaştım

Ben senden gopamam, bu haltı yedim

Geneyikli der ki, işte beyleyim

Kötü huyum yoktur, neyi söyleyim

Sende sevdiğini, dede bileyim

Galbim, ganım temiz, ev gurak dedim', 'Hava yoğunlaşıp, tozu kakmadan Yerle gök ısınıp, güneş yakmadan Dermanımı kesen, terim akmadan İşe er başlayıp, çalışıp yedim Her hayir kerr...', ARRAY['Türk Edebiyatı','Şiir','Hasan Geneyikli']::text[], 8.5, '{"poet":"Hasan Geneyikli","poet_slug":"hasan-geneyikli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-buyum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkilem', 'i-kilem-necmettin-sari-emboy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-  ölmek kolay, zor ölmek,

                                          ya korkuyu öldürmek  -

Bir başkasının kaçan uykusuyla çiftleşiyor düşlerim,

Ben kaçan uykularımı arıyorum ve düşlerimi

soluk kemik rengiyle geliyor üzerime yalnızlık,

kemik rengiyle öpüyor dişlerimi.

bütün ayrılıkları öldürüyorum,

bütün ölümleri ayırıyorum

ve balyoz ellerimle iniyorum ayrılığa

ve ayrılığı bir balyoza çevirip elime alıyorum

düşlerim soğuyor, avuçlarım yanıyor

ve yeni ve henüz doğmuş bir yaşam

kocaman elleriyle kapıyor gözlerimi.

Gözlerimle öpüyorum,

gözlerimle gülüyorum,

ve gözlerimle korkuyorum ölümden

- ölümünse ağlayacak gözleri hiç olmadı,

dökecek gözyaşları, tutacak elleri de –

gözleri benim bugün ölümün,

gözyaşları ruhum,

ve elleri birazdan ışıksız bir yaylaya çıkıyor,

dört günlüğüne,

turnalar, begonyalar,

helizler bitiren elleri birazdan

ışıksız bir yaylaya çıkıyor dört günlüğüne 

bugün ölmek için çok yalnız bir gün,

ve ölümü çağırmak için biraz geç,

gülümseyen yanlarım çok uykusuz yüzümde

yüzümü öldürmek! , ışıksız bir yaylada,

taşta yürü, suda yüz

mor mantarlar, dağ çilekleri

böğürtlen güneşinde kızaran gölge

yok artık! 

Gelmez ölüm, ben kendim öleceğim

ölmek için korkumu içimden sökeceğim.

                                                                       

                                                                                 (2001)', '-  ölmek kolay, zor ölmek,                                           ya korkuyu öldürmek  - Bir başkasının kaçan uykusuyla çiftleşiyor düşle...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Sarı']::text[], 8.5, '{"poet":"Necmettin Sarı","poet_slug":"necmettin-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ikilem-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Ağrıyan', 'zamansiz-agriyan-babur-pinar-d6zht', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamansız geldik

cemre gibi düştük gökyüzüne ilk 

Düşün ki düş gördü çocuklar zemheride 

soğuk bir rüzgar ısırdı yanaklarını 

Üşüdü elleri çatladı endişe

yazamadım ardına düştüğüm ezberi

Kar altında kalan yeryüzü gibi 

bekledim ürpererek baharını

Üzerinden yangın geçmiş tenimde

sakladım ateş kokusunu 

koklarsın açılırsın diye

Ellerim gülden saklar korkusunu

gel çocukluk etme 

Gitme 

Sarı sıcak pencere önü 

mahpushanede görüş günü 

voltada yan yana düşen dostluklar 

yoluma çıkmış gitmemiş gün çoğalması 

Sevdam çeliğe su veren ustanın sevdası 

sokakta okulda çocuklar 

uzayan dövüşün dinmez çavlanı 

ABECE gibi öğrenilir 

ölümün yalnız gidilen zamanı 

Gelip dayanır kapımıza çıvgın

haziran yağmurları bereketli

Akşamdan sabaha yürürken leyli 

daha çok can alır kurşun seli 

Kimse büyütemez sessizliğini dargın 

koyma beni ortalarda

zamansız gelen çiçek açmalarda 

kucağına atma umarsızlığın 

Gel çocukluk etme 

Yağmur yağabilir kuşlar susabilir 

bıyıklarım ıslanırsa üşürüm gitme

Kanlı mayıslara bırakma beni 

Su gibi sabah gibi 

bir mevsimlik olsun sıcaklığına sarınayım 

Gel dokun alnımın çatına 

Gözlerin kınalı bir mermi

vur gözlerimi 

ısınayım 

Munzur dağında çocukluğum kaldı 

Karasu’da  kanlı gömleğim 

En zehir zamanımdır leylim

Geldim dayandım kapına

medet umduğum sensin sürgün ardı 

Gel çocukluk etme 

gitme

  

               

(Eylül/1984- UMUT PAS TUTMAZ-şiir kitabı,Dayanışma yay./64 s.)', 'Zamansız geldik cemre gibi düştük gökyüzüne ilk  Düşün ki düş gördü çocuklar zemheride  soğuk bir rüzgar ısırdı yanaklarını  Üşüdü elleri ça...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/zamansiz-agriyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-siyar-ozisiklar-fh9yn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şeydasıydı ömrümün

büyülü ve kara sevdalı,

paslı öyküsü – nü

ben bütün hayatımı sana yazdırdım

bir sis gibi serildi aramıza, 

seni bana, beni sana gecikmiş kılan bütün nedenlerim

küçümsediğim dünya

korkularım

yıldızlı bir gece,

sana anlamını veren, kendime attığım bütün yalanlar

hayatta, aşk gibi güldü bana

neredesin ya güzelim

içim de bir sen varsın da, 

karşı vaha da,

koynum da,

resmin aslı sen nerdesin

bir soru düşer aklıma,merak düşer

sen olurum

bir çocuk koşar, bir yıldız kayar,

bir kadın üşür,

sen olurum

simge, büyü ve ayin

ben nerdeyim ya güzelim, ben neyim

bir sözle bağladım kendimi sana

ay ve nur

mavi ve sarı

alkol ve tütün kokar tapınağım

ibadeti susmak olan teoloji

sen ömrümün günahı

ardından gizemli bir bulmaca

yanıtsız bir sürü soru bıraktın bana

bilirsin, aşk da tanrı gibidir sorgulanmaz

mistik bir fahişe

masalsı bir başkaldırırdır.

Tenimiz de izi kaldı içinden geçtiğimiz iklimlerin

ıslandığımz yağmur,

büründüğümüz sis,

karıştığımız orman

herşey ama herşey,şimdi bize yoksuluğumuzu hatırlatıyor,

yanlızlığımızı

yüzümüzü gizlediğimiz vadilere benziyoruz zamanla,

derin ve ıssız

yaralarımızdan tanıyorlar,

geçmişimizi ele veriyor kimsesizliğimiz

efsane gerçek oluyor.

tılsım tamamlanıyor

yüsük ve kaos

yeniden bölüştürülüyor kıtalar

uzak ufuklar

dipsiz denizlere düşüyoruz

diller ayrıştırılıyor yeniden

parçalanıyoruz.

dokunmadan  geçiyoruz zamana

unutuluyor acılarımız

tekrar anlaşılmaz kılıyor bizi

ikimiz de biliriz ama söylemeyiz

an gelir

bir deneyimin ardından gidersin

öyle tutkulu ve öyle yanlız

çalar seni ben den istanbul

yitersin

yine de kızamam sana sevgilim

çünkü çok mahsum kalır bana yaptıkalrın

hayatla kıyaslandığın da 

ben bütün hayatımı sana yazdırmış olsam da

EYLÜL  2002

SIYAR OISIKLAR', 'Şeydasıydı ömrümün büyülü ve kara sevdalı, paslı öyküsü – nü ben bütün hayatımı sana yazdırdım bir sis gibi serildi aramıza,  seni bana, ben...', ARRAY['Türk Edebiyatı','Şiir','Siyar Ozisiklar']::text[], 8.5, '{"poet":"Siyar Ozisiklar","poet_slug":"siyar-ozisiklar","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/sen-619-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Gelir Bahar', 'yine-gelir-bahar-babur-pinar-egh5n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağlardan kalkan kar

dağlara çekilen kuşlar

umurumdadır 

Yediveren güldür gövdemde hayat

kırk çiçek açan duvar önü yastadır

Evin içinde küstüm çiçeği bir afat

kendini bin nazla koklatır 

Gizlisinde ateş yakan avcının

hayra yorulmaz düşü

Cevahir ömrü çürütemez zindan

Sevdasız her kuş ötüşü

işkence olur güle

Bir yaralı düşle 

göğsünde gül büyütür yaren

Yaşanılası ve Ferhat

bir düğün kurulur dağlara 

Çiçek alaylı gelin

bahçe kapısına iner sepken

zor ölümlü zorba saltanat

yüz görümlük sevinç ister

düş arsızı beton evden

Gülümse gülüm zamanıdır

koy saksıları tara

Karşılasın iki mevsim arası demi kalbin 

pencereni aç avunmaz rüzgara

Yine gelir bahar 

Uçurumda eriyen kar

can verdiği nehre akar



(Eylül/1984-UMUT PAS TUTMAZ-Şiir Kitabı)', 'Dağlardan kalkan kar dağlara çekilen kuşlar umurumdadır  Yediveren güldür gövdemde hayat kırk çiçek açan duvar önü yastadır Evin içinde küst...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yine-gelir-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanarken', 'sanarken-ozan-turk-d5h6y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanarken

Geceyi gerçek gibi

Hayatın ta kendisi hatta 

Bir yolculuk sonudur öğreneceksin

Ne denli büyük kahpeliğini

Sezerken

Eylül’ün korkunç fısıltısını

Gidiyor sanki yeniden binlerce turist anılarından

Bir hüznün sona erişidir göreceksin

“Sanki hiç olmadı” bile demeyeceksin

Süzerken 

İçindeki sahili

Aşılanmalı artık olmayan palmiye ağaçları

Binlerce adımı koşarak tüketsen de anlayacaksın

Birinci bitirdiğin bu yarışın

Sevinç çizgisinden sonra yalnızsın…', 'Sanarken Geceyi gerçek gibi Hayatın ta kendisi hatta  Bir yolculuk sonudur öğreneceksin Ne denli büyük kahpeliğini Sezerken Eylül’ün korkunç...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sanarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksilmeli Şiir', 'eksilmeli-siir-sait-kucuk-s6qv9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eksiliyor

her gün ömür takviminden bir yaprak

eksiliyor

yediğimiz ekmek içtiğimiz su

eksiliyor

ağızsız bitkiler dilsiz hayvanlar

eksiliyor

dünyanın ömrü de bizim ki gibi

eksiliyor

yaşam ve insanlık

insan arttıkça..', 'eksiliyor her gün ömür takviminden bir yaprak eksiliyor yediğimiz ekmek içtiğimiz su eksiliyor ağızsız bitkiler dilsiz hayvanlar eksiliyor d...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eksilmeli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güne Aya Ömre (Annemin şiiridir)', 'gune-aya-omre-annemin-siiridir-ozan-turk-rxh5e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güne yılların acılarını sığdır,

Aya ömrün…

Gün içinde günü ararsında bir boğuşma içerisinde

Dönüp bakıverirsin şöyle bir 

Ne çocukluk ilk gençlik

Ne doyumsuz bir gülücük…

                Melahat EROĞLU', 'Güne yılların acılarını sığdır, Aya ömrün… Gün içinde günü ararsında bir boğuşma içerisinde Dönüp bakıverirsin şöyle bir  Ne çocukluk ilk ge...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gune-aya-omre-annemin-siiridir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Şarkı', 'yitik-sarki-nil-su-16x6c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yitik bir kentin kaldırımlarını adımlarken

Güz sarısında,

Yüzün beliriyor siste

Bulut gibi,

Mavi biraz da..

Adını bildiğimiz hüzünlerde,

Yitik sevgilerde,

Ararken kendimizi,

O yitik ülkenin ülkenin 

Çocuklarından oluvermişiz çoktan.

Biz yalnızca 

O çok soğuk kış kentinde mi yaşadık

Özgürlüklerimizi,

Büyük umutlara yol alan paylaşımlarımızı

Seninle 

Aynı gökyüzünde söylemek vardı şarkılarımızı,

Ama bizim şarkılarımız hiç aynı olamadı ki.

(Kasım/2000)', 'Yitik bir kentin kaldırımlarını adımlarken Güz sarısında, Yüzün beliriyor siste Bulut gibi, Mavi biraz da.. Adını bildiğimiz hüzünlerde, Yit...', ARRAY['Türk Edebiyatı','Şiir','Nil Su']::text[], 8.5, '{"poet":"Nil Su","poet_slug":"nil-su","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yitik-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şiir', 'ah-siir-ertugrul-sakar-njh32', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Su bardakta ne kadar gerçek

Taş bir heykelde

Neden kendimi tanıyamıyorum

Kalıplar içinde

Gelin arabasından bir dua yükselir

İner bir basamak daha bir gelin

Dostlar tanımam için vardır

Betonu delmiş bir çiçek

Başıboşluğun adını cumartesi koydum

Zaman hamağında ki keyfim

Kaçamak gibi yüzümde ki pembe

Ah merak, ah aşk, ah şiir', 'Su bardakta ne kadar gerçek Taş bir heykelde Neden kendimi tanıyamıyorum Kalıplar içinde Gelin arabasından bir dua yükselir İner bir basamak...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ah-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soyum', 'soyum-arafat-arik-kqvv6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben yıkık ocakların rüzgârlarında ıslık,

Ben tenhanın gözleri, ben meydanın oğluyum.

Ben mahkûm bakışların sükûtlarında çığlık,

Ben isyanın nefesi, ben tufanın oğluyum.

Ben sessiz ağıtlarda, akan birkaç damla yaş,

Ben hoyratça ezilen ama eğilmeyen baş,

Ben hüzünde müebbed, melankoliye yoldaş,

Ben çatlayan yüreğin, ben figanın oğluyum.

Ben mühürlü yüreğe hapsolanın acısı,

Ben batık kervanların muvazzaf kervancısı,

Ben muratsız yazgının kaç asırlık sancısı,

Ben aşkın tecellisi, ben sevdanın oğluyum.

Ben ah çekip yananın, dikiş tutmaz yarası,

Ben onulmaz bahtların yu, yu gitmez karası,

Ben evham padişahı, ben sükûn fukarası,

Ben eyvahın bedeli, ben amanın oğluyum.

26 Ağustos 2005', 'Ben yıkık ocakların rüzgârlarında ıslık, Ben tenhanın gözleri, ben meydanın oğluyum. Ben mahkûm bakışların sükûtlarında çığlık, Ben isyanın ...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Bağlı Bir Seherdeyim', 'gozleri-bagli-bir-seherdeyim-fidan-bulut-rribe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözleri bağlı bir seherdeyim.

Ellerimin arasında başım

Çatılmış keman olmayan kaşlarım

Tam ortası! Seni, orda saklamışım.

Uykusuzluktan mahmur gözlerimi,

Öpüp uyandırdın uykusuzluğumdan beni.

Nur şafağım; 

Gözümün yaşında saklamışım.

Sıkışmış kentin orta yeri gibi,

Kalabalık kalbimin kaldırımları,

Geçmişimin durakları.

Seni; gelecek tek durağa saklamışım.

Derinim, 

Ellerimi, kokumu, yüreğimi,

Bölünmüşlüğümle sevdin beni.

Aşkını benliğimde bencilce saklamışım

Uzanmışlığımda yaşamın her dalına,

Sinsi kasırgaların karşısında setken

Korkak bir kedi gibi, asri saklamışlığımla, 

Beni de sana saklamışım.

Taşıyabilirsen, yiğidim bendeki senle beni; 

     ...........................Çöz seherimin gözlerini.', 'Gözleri bağlı bir seherdeyim. Ellerimin arasında başım Çatılmış keman olmayan kaşlarım Tam ortası! Seni, orda saklamışım. Uykusuzluktan mahm...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gozleri-bagli-bir-seherdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle Diyenim Mi Var..?', 'gule-gule-diyenim-mi-var-hasan-basri-kale-tqlqf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çöken hüzne inat

uçuşmuş umut

güzünü bir adım geçtik ömrün

gönlüme bakıp dinleyenim mi var..? 

kayıp geceler

varmaz sabaha

gün doğsa ne olur

nerdesin deyip özleyenim mi var..? 

yol biter

ömür biter

geri döner gelenler

yol gözleyip bekleyenim mi var..? 

iki damla yaş

bir avuç toprak

gider olmuşum alaca sabahla

el sallayıp güle güle diyenim mi var..?', 'çöken hüzne inat uçuşmuş umut güzünü bir adım geçtik ömrün gönlüme bakıp dinleyenim mi var..?  kayıp geceler varmaz sabaha gün doğsa ne olur...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gule-gule-diyenim-mi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahuzar', 'ahuzar-mahmut-ulusoy-njusv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu ahuzarımı kime diyeyim

Ararım şafaklar atana kadar

Fırtına da yelkenimi çevirdi

Dalarım deryaya batana kadar

Silme didem yaşı aksın yüzüme

Daha uyku girmez iki gözüme

Ne söylesem inanmadı sözüme

Aldattı yanarım yatana kadar

Dünyayı devranda dostun bağında 

Bülbülem defin et gülün yanında

MESULİ esirdir senin kapında

Beklerim müddetim dolana kadar', 'Bu ahuzarımı kime diyeyim Ararım şafaklar atana kadar Fırtına da yelkenimi çevirdi Dalarım deryaya batana kadar Silme didem yaşı aksın yüzüm...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ahuzar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G.Z''nin Gecmemis $iirleri 7', 'g-z-nin-gecmemis-iirleri-7-huseyin-avdic-ksy5x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelmis Gecmis Gelecek

Gelmis gurupta.

Gecmis dorukta.

Gözünü ac bak! 

Gelecek ufukta.

******

Gelecek

Gelecek gelecek

Gelecek gececek

Gececek gelecek

Gelecek gelecek

******

Gelecektim

Gelecektim geldim

Geldim gidecektim

Gidecektim gittim

Gittim gelecektim

Bati Berlin, 1980-85.', 'Gelmis Gecmis Gelecek Gelmis gurupta. Gecmis dorukta. Gözünü ac bak!  Gelecek ufukta. ****** Gelecek Gelecek gelecek Gelecek gececek Gececek...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/g-z-nin-gecmemis-iirleri-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor gelen aşk', 'zor-gelen-ask-yunus-isikoglu-4tl0y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya nın bir saati

Uzay da bin saat miş.

Sen gelince sevgilim

Ben uzay da yaşarım

Gelsen haftada iki saatcik

Ben yaşarım seni ikibin kere

Çok görme bana iki dünya saatini

Seni

Yaşarım uzay saatiyle doyasıya

Saçının tellerini eklerim bir bir

Ben den sana yol yaparım.

O yol da 

Hiç bıkmadan sana koşarım

Bir hesap yaparım saç tellerinden yollar da

Ay da sekiz, uzay saati sekiz bin

Yıl da etti doksanaltı bin saat

Bak geçecek bu gidişle kısacık ömrüm

Saç tellerinden yollar da

Bak güzelim

Bu aşk bana zor gelecek

En güzeli sevgilim

Bana ilk gelişin de

Saçlarını kabak gibi kökünden

Usturayala kazıtarak öyle gel.', 'Dünya nın bir saati Uzay da bin saat miş. Sen gelince sevgilim Ben uzay da yaşarım Gelsen haftada iki saatcik Ben yaşarım seni ikibin kere Ç...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zor-gelen-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çabuk Gel', 'cabuk-gel-mahmut-ulusoy-tyazv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dedim nazlı yare yazam arzuhal

Kaybettim kalemi yitti çabuk gel

Güneş aştı ay buluta yaklaştı

Sabah oldu şafak attı çabuk gel

Kolay bozulmuyor feleğin fendi

Dert ile savaştım o beni yendi

Çile çeke çeke ömrüm tükendi

Günlerim azaldı bitti çabuk gel

Yare varmak için kalmadı gücüm

Der MESULİ bilmem ne idi suçum

Dizildi katarım gidiyor göçüm 

Yüklendi kervanım gitti çabuk gel', 'Dedim nazlı yare yazam arzuhal Kaybettim kalemi yitti çabuk gel Güneş aştı ay buluta yaklaştı Sabah oldu şafak attı çabuk gel Kolay bozulmuy...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cabuk-gel-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Dusunmek', 'seni-dusunmek-hakan-i-ldan-uazur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ayin yarama dùsmesi gibidir. seni dùsùnmek,

kayan bir yildizda dilek tutmaktir.

kirilgan bir tùrkùye dokunmak,

garip bir siire takilmak bir romanla suruklenmektir. 

bahardir seni dùsùnmek, hic kis gormemis

dokuz virgul bilmem kac siddetinde  bir depremin,

enkaz yiginlari altinda kalmis bir yurektir. seni dùsùnmek,

bir tufandir.

baharda yagan sagnak bir yagmurdur. sellerle birlikte 

gùlùn feryadini anlamaktir

ferhatin gùrzùnù savurmaktir. 

yada mecnunun colùne ayak basmaktir. seni dùsùnmek,

bilinmeyene yolculuktur 

kaf dagini bulmaktir. 

masallardaki kocaman deve kafa tutmaktir 

anka kusunun kùlleriyle savrulmaktir. seni dùsùnmek,

bir okyanustur uçsuz bucaksiz ve masmavi

seni dùsùnmek

birde gozlerine vurulmak

birde gùlùsùne tutulmak varya.....', 'ayin yarama dùsmesi gibidir. seni dùsùnmek, kayan bir yildizda dilek tutmaktir. kirilgan bir tùrkùye dokunmak, garip bir siire takilmak bir ...', ARRAY['Türk Edebiyatı','Şiir','Hakan İldan']::text[], 8.5, '{"poet":"Hakan İldan","poet_slug":"hakan-i-ldan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-dusunmek-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçti', 'gecti-mahmut-ulusoy-tgzk8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir bilmem bu gönlümün meramı

Hayat geçti zaman geçti iş geçti

Bir fırtına gibi aşkın tufanı

Hayal geçti rüya geçti düş geçti

Ben de bu dünyaya geldim sağ gibi

Çiçek açtım gazel döktüm bağ gibi

Başı para pare yüce dağ gibi

Duman geçti boran geçti kış geçti

Çektiklerim nedir felek elinden

Didem ceyhun olmuş aşkın selinden

MESULİ''yem doğrulamam yerimden

Ömür geçti gençlik geçti yaş geçti', 'Nedir bilmem bu gönlümün meramı Hayat geçti zaman geçti iş geçti Bir fırtına gibi aşkın tufanı Hayal geçti rüya geçti düş geçti Ben de bu dü...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecti-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakın Hele', 'bakin-hele-yavuz-agir-c191k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu gönlüme bakın hele

Daldan dala konar gider.

Duygularım sele benzer

Deryalara akar gider.

Şu halime bakın hele

Günden güne erir gider.

Günlüm  bir rüzgar olmuş

Sağa sola eser gider.

Şu zamana bakın hele

Su gibi akar gider.

Ulaşmak mümkün değil

Dağı taşı aşar gider....', 'Şu gönlüme bakın hele Daldan dala konar gider. Duygularım sele benzer Deryalara akar gider. Şu halime bakın hele Günden güne erir gider. Gün...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bakin-hele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Dusunurken', 'seni-dusunurken-hakan-i-ldan-4jqpl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni dùsùnùrken ùrkùtmeyecegim artik

incitmeyecegim

usul usul dùsùnecegim

bir kaval sesi gibi

bir cicegi incitmeye kiyamadigim gibi

bir deniz gibi 

bir irmak

bir col bir dag gibi

yagmur gibi

bilmiyorum daha ne gibi

ve yine seni dusunuyorum yeryuzuguzelim....', 'Seni dùsùnùrken ùrkùtmeyecegim artik incitmeyecegim usul usul dùsùnecegim bir kaval sesi gibi bir cicegi incitmeye kiyamadigim gibi bir deni...', ARRAY['Türk Edebiyatı','Şiir','Hakan İldan']::text[], 8.5, '{"poet":"Hakan İldan","poet_slug":"hakan-i-ldan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-dusunurken-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Yarim', 'guzel-yarim-yavuz-agir-ssdea', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaktın kül eyledin

Sordun sır eyledin

Aldın kul eyledin

Kara kaşlı güzel yarim

Gurbeti mesken eyledin

Derdini kime söyldin.

Ah... bunu bir bileydim

Kara kaşlı güzel yarim....', 'Yaktın kül eyledin Sordun sır eyledin Aldın kul eyledin Kara kaşlı güzel yarim Gurbeti mesken eyledin Derdini kime söyldin. Ah... bunu bir b...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guzel-yarim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-gorkem-kizir-irfod', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sev delicesine arkadaş

Tuttuğun yerden sıkıca sarıl ona

Oyunu kuralına göre değil

Kendine göre oyna 

Öylesine sevki sanki bir daha sevemeyeceksin

Öylesine sarılki ona sanki hiç bırakmayacaksın

Öylesine yaşaki onu sanki her an öleceksin

Ve öylesine mutlu etki onu bir daha böylsini bulamasın

Bekleme karşılığını ondan 

Bekleme ondan mutluluk, heyecan

Sen ver herşeyini

Sanki mahrum kalacaksın bir gün ondan

Bir gün gelecek sana başkasının kollarında

Üzülme, mutluluk dile gerçekten ve içten ona

Bırak o da sevsin delicesine arkadaş

Bırak o da oynasın oyunu kendine göre

Sen yine sev onu sanki bir gün dönecek diye', 'Sev delicesine arkadaş Tuttuğun yerden sıkıca sarıl ona Oyunu kuralına göre değil Kendine göre oyna  Öylesine sevki sanki bir daha sevemeyec...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kizir']::text[], 8.5, '{"poet":"Görkem Kizir","poet_slug":"gorkem-kizir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/arkadas-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kisacasi', 'kisacasi-hakan-i-ldan-3g09j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yani kisacasi 

yani en uzun 

hadi farzzet en uzun ve en kisa 

yalniz seni sevmek varmis 

yalniz yeryuzuguzelimi', 'yani kisacasi  yani en uzun  hadi farzzet en uzun ve en kisa  yalniz seni sevmek varmis  yalniz yeryuzuguzelimi...', ARRAY['Türk Edebiyatı','Şiir','Hakan İldan']::text[], 8.5, '{"poet":"Hakan İldan","poet_slug":"hakan-i-ldan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kisacasi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gokyuzumsun', 'gokyuzumsun-hakan-i-ldan-j7u3w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yasadigim en gùzel hayatsin sen

bùtùn acilarina ragmen

ugrunda her sey birakilan 

bir dileksin sen (dilek) 

bir siirsin sen 

hissedilince yazilan

bir çiçeksin sen 

bùtùn mevsimlerde açan

bir ruzgarsin sen bir kasirga 

estimi tas ùstùnde tas birakmayan 

ve bir yagmursun sen

her gece her gece 

yùregime gozyasi olup yagan

ve gokyùzùmsùn sen

sabahi ve aksamiyla

ve bùtùn yildizlariyla

yeryuzuguzelimsin sen 

                        seni seviyorum...', 'yasadigim en gùzel hayatsin sen bùtùn acilarina ragmen ugrunda her sey birakilan  bir dileksin sen (dilek)  bir siirsin sen  hissedilince ya...', ARRAY['Türk Edebiyatı','Şiir','Hakan İldan']::text[], 8.5, '{"poet":"Hakan İldan","poet_slug":"hakan-i-ldan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gokyuzumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutu', 'kutu-ese-ese-k4v4s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kutu

kutu içinde soru

soru içinde yanıt

yanıt içinde yaşam

yaşam içinde

kutu', 'kutu kutu içinde soru soru içinde yanıt yanıt içinde yaşam yaşam içinde kutu...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kutu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahin tam 7 sinde', 'sabahin-tam-7-sinde-husamettin-guven-5lp6u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'o gun kalktim sabahtan

bu ne buyuk feryat gam

birde baktim ne gorem

sabahin tam 7 sinde

anam yatmis uzanmis

gozlerini kapatmis

az icik nefeskalmis

sabahin tam 7 sinde

hemen kostum doktora

ne yazikki bos yere

anam coktan gitmisti

sabahin tam 7 sinde', 'o gun kalktim sabahtan bu ne buyuk feryat gam birde baktim ne gorem sabahin tam 7 sinde anam yatmis uzanmis gozlerini kapatmis az icik nefes...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sabahin-tam-7-sinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aa', 'aa-ese-ese-smfcv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kesik

kör

doku

yangın

hep acı-tasyon', 'kesik kör doku yangın hep acı-tasyon...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutarme Betonlar', 'bulutarme-betonlar-eyup-karabulut-g2415', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zemin hayatları çok zor.

Bulutlar betonarme…

Asfaltlar pamuk şeker mi? 

Yoksa elma şekeri mi? 

Günahsızların günahları

Fakirlerin servetleri

Zengin olmak zor değil mi? 

İpliğin oryantali

Kuşların ağlayışları

İnsanların ötmeleri 

Ne garip değil mi? 

Betonların sessizliği

Tüm taşların çiçekleri

Toprağın hareketi

Bizim için değil mi?', 'Zemin hayatları çok zor. Bulutlar betonarme… Asfaltlar pamuk şeker mi?  Yoksa elma şekeri mi?  Günahsızların günahları Fakirlerin servetleri...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Karabulut']::text[], 8.5, '{"poet":"Eyüp Karabulut","poet_slug":"eyup-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bulutarme-betonlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne bu yahu?', 'ne-bu-yahu-ese-ese-els4x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sensizlik

özgürlüğü

getiriyor.

özgürlük

sensiz

çekilmiyor,', 'sensizlik özgürlüğü getiriyor. özgürlük sensiz çekilmiyor,...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ne-bu-yahu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaaaaaaaaaaz…', 'olmaaaaaaaaaaz-eyup-karabulut-kgvh0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızlar usanıp senden

Düşse ayaklarımın önüne

Yinede gitmem olmaz

Ben zalim kızın yönüne

Ellerim etten kesilse

Boğazım ipe asılsa

Cehennemliğim nasılsa

Yine olmaz ah olmaz

Paralardan yastık yapsam

Haşa şeytana tapsam

Daha neler neler yapsam 

Yinede Olmaz ah olmaz

Üstüme asfalt dökseler

Tırnaklarımı sökseler

Koluma çivi çaksalar

Yine de olmaz ah olmaz

Kara zindanlara atsalar

Her gün pusuya yatsalar

Köle diye beni satsalar 

Yine de olmaz ah olmaz

tüm yıllar aklımda kalsa

aklımı şeytan da alsa

tek dostum ağaçtaki dalsa

yinede olmaz ah olmaz', 'Yıldızlar usanıp senden Düşse ayaklarımın önüne Yinede gitmem olmaz Ben zalim kızın yönüne Ellerim etten kesilse Boğazım ipe asılsa Cehennem...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Karabulut']::text[], 8.5, '{"poet":"Eyüp Karabulut","poet_slug":"eyup-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olmaaaaaaaaaaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabristan', 'kabristan-husamettin-guven-gzo60', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dolumlere,dagarlara

sigmiyorsun adalara

ne tarlaya ne arsaya

senin yerin kabristan

baban mali olmadimi

bu dunyada kalmadimi

evlatlari bolmedimi

senin yerin kabristan

dunya mali neye gerek

al hepsini sana verek

sukretmezsen biz ne edek

senin yerin kabristan', 'dolumlere,dagarlara sigmiyorsun adalara ne tarlaya ne arsaya senin yerin kabristan baban mali olmadimi bu dunyada kalmadimi evlatlari bolmed...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kabristan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleme Odası', 'bekleme-odasi-ese-ese-4at73', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'karıştırıyorum aklımı

sümbülle gülle

kuşla kediyle

batı yakası değişken değil

herşeyin seçildiği gün

seçtik

tüm korku böceklerinin

tüylerinin tüylerimize

değdiği masum uykularımızın

huzurunda

uyanışların şirin şımarıklığında

değişen

anlamlar ya

sen de biliyorsun

bilmediklerinin

bilmediklerimle

buluşmasını

bekle - bekleme

işte bunun dışındaki

olasılıktayım', 'karıştırıyorum aklımı sümbülle gülle kuşla kediyle batı yakası değişken değil herşeyin seçildiği gün seçtik tüm korku böceklerinin tüylerini...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bekleme-odasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gülüm Olamassın', 'sen-gulum-olamassin-mehmet-aslan-s81fw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani derler ya; 

“Kopartma gülleri dalında kalsın”

Onları kopartsan da solar, kopartmasan da

Dalda ya da vazoda,

Ne fark eder ki.

Sonuçta solacaklar.

Sen benim gülüm olamasın,

Çünkü sen solamasın.

Hani derler ya; 

“Gülü solana dek, Seni ölene dek”

İşte öyle bir şey benimkisi.

Sen benim gülüm olamasın,

Çünkü seni ölene dek seveceğim.

Hani derler ya; 

“Gülü seven dikenine katlanır”

Sen benim gülüm olamasın.

Çünkü tatlı dilli ve de dikensizsin.', 'Hani derler ya;  “Kopartma gülleri dalında kalsın” Onları kopartsan da solar, kopartmasan da Dalda ya da vazoda, Ne fark eder ki. Sonuçta so...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gulum-olamassin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'X files', 'x-files-ese-ese-p0tf8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her yalnız

bir çokluk

her çok

bir yalnız

1 yalnız

yalnız çok

yalnızlık çok

her biri çok

her biri yalnız

bir yalnız

bir çok

nasılsın?', 'her yalnız bir çokluk her çok bir yalnız 1 yalnız yalnız çok yalnızlık çok her biri çok her biri yalnız bir yalnız bir çok nasılsın?...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/x-files-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Bilirmisin', 'aski-bilirmisin-mehmet-aslan-vtmyq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk nedir bilirmisin? 

Bilmessin

Birden çok kişiye 

Aşkım benim dermisin

Söylemezsin.

Çünkü sen

Aşk nedir bilmiyorsun.

Sen benim aşkımsın

Şaşırdın değil mi

Evet şaşırdın

Çünkü sen

Aşk nedir bilmiyorsun

Senin bildiğin aşk

Bir oyundan ibaret

Ama iki kişilik bir oyun.

Benim aşkım çoktur

Yine şaşırdın değil mi

Evet şaşırdın

Çünkü sen aşk nedir bilmiyorsun.

Bende aşk çoktur

Allah aşkı, vatan aşkı

Doğa aşkı, insan aşkı….

Tabi birde sen

Şaşırdın değil mi

Evet şaşırdın

Çünkü sen aşk nedir bilmiyorsun.', 'Aşk nedir bilirmisin?  Bilmessin Birden çok kişiye  Aşkım benim dermisin Söylemezsin. Çünkü sen Aşk nedir bilmiyorsun. Sen benim aşkımsın Şa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aski-bilirmisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan dünya', 'yalan-dunya-sair-gaddar-16-3z9ro', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herşeyi ele alan dünya,

Dünyanın değeri beş kuruş paraya,

Değmez bu dünya boş bi kutuya,

Elveda yalan dünya.

...

Ahiret bile bir dünya,

Dünya hep sahte rüya,

Dünya bu sert kaya,

Elveda yalan dünya.

...

Hani aşkın şefkatin dünya,

Bilmeliydim bu dünya bir rüya,

Hep acı çektirdin bana,

Elveda yalan dünya.

...', 'Herşeyi ele alan dünya, Dünyanın değeri beş kuruş paraya, Değmez bu dünya boş bi kutuya, Elveda yalan dünya. ... Ahiret bile bir dünya, Düny...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalan-dunya-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Yıllar', 'gecen-yillar-mehmet-aslan-s76wk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günler geçiyor sanardım

Boş hayallerle

Hep geçen günlere yanardım

Oysa bir baktım ki maziye

Yıllar geçmiş

Yıllar çabuk geçmez sanardım

Öyle geçmiş ki saniyelerle

Farkında bile olmadan

Bir solukta kırk yıl geçmiş aradan

Geçmez diye sanarken

Öyle çabuk geçmiş ki yıllar

Hem de bana hiç sormadan

Bir film şeridi gibi

Geçip gitmiş yıllarım

Geriye kalan bir hiç gibi

Bir ben birde ağaran saçlarım.', 'Günler geçiyor sanardım Boş hayallerle Hep geçen günlere yanardım Oysa bir baktım ki maziye Yıllar geçmiş Yıllar çabuk geçmez sanardım Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecen-yillar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak', 'hak-ese-ese-2eg5p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hiçbir an

bir öncekinden

daha haklı değildir', 'hiçbir an bir öncekinden daha haklı değildir...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hak-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanma Nolur!', 'i-nanma-nolur-abdulkadir-karaca-rg0df', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine kaybetmeye gebe bu bakış

Hayır yalan bunlar,inanma nolur

Beni en mahrem yerimden vurdular

Yani senden

Bu kara günlerim geçecek birgün

Ama korkuyorum seni kaybetmekten

Hafakanlar satın aldı uykularımı

Bunca zaman tanıdığın ben

Yapmam öyle şey

İnanma! iftira! 

Diyemem sana

Sen hala beni tanımadınsa

Söylemediklerim var sana inan

Ama söylediklerim bu değil

Ne zaman mutluluk için

Bir düş azad etsem gönlümden

Mutlaka sevdamdır çalınan

Yalan bu sözler

Üstümdeki bakış masum

Nolur bana inan

Artık anla demek istediğimi

Artık bil

Yıkamayacak bu lanet beni

Evet cesaret edemediklerim var

Ama cesaretim bu değil

Belki bir kırmızı gül

Belki hasretim

Anlatır sana derdimi bir gün

Artık inanma demeyeceğim sana

Sen benim kapanmaz  yaramsın

Bir yılan pususu kurdular

Bağışla birtanem,kaybettim seni

Beni kanayan yanımdan vurdular

(27.08.2005)', 'Yine kaybetmeye gebe bu bakış Hayır yalan bunlar,inanma nolur Beni en mahrem yerimden vurdular Yani senden Bu kara günlerim geçecek birgün A...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/inanma-nolur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Senin', 'bugun-senin-mehmet-aslan-5eyo6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim için; 

sıradan bir gün bugün.

senin ise doğum günün.

Mutsuzsun biliyorum

onun yokluğunun

burukluğunu yaşıyorsun

Sil gözyaşlarını bugün

çünkü senin doğum günün.', 'Benim için;  sıradan bir gün bugün. senin ise doğum günün. Mutsuzsun biliyorum onun yokluğunun burukluğunu yaşıyorsun Sil gözyaşlarını bugün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bugun-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örgü', 'orgu-ese-ese-ojml2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşantıma örüyorum seni

bir düz

bir ters

ve takılıyor ucun

bir yerlere

sökülüyorsun

yaşamımdan', 'yaşantıma örüyorum seni bir düz bir ters ve takılıyor ucun bir yerlere sökülüyorsun yaşamımdan...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/orgu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bahçemiz', 'sevgi-bahcemiz-mehmet-aslan-pntef', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geniştir bizim sevgi bahçemiz

Hepinize vardır yerimiz.

Unutmayanları unutmayız biz,

Sevgiyle doludur yüreğimiz.

Yalnız bir köşesidir özelimiz,

onundur orası, kimse prensesimiz.', 'Geniştir bizim sevgi bahçemiz Hepinize vardır yerimiz. Unutmayanları unutmayız biz, Sevgiyle doludur yüreğimiz. Yalnız bir köşesidir özelimi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgi-bahcemiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-ese-ese-hv9vk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', ''' bekliyorum

öyle bir havada gel ki

vazgeçmek mümkün olmasın ''

demiştin

geldim öyleyse

vazgeçme

dönmek mümkün olmasın', ''' bekliyorum öyle bir havada gel ki vazgeçmek mümkün olmasın '' demiştin geldim öyleyse vazgeçme dönmek mümkün olmasın...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/davet-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiskanirim', 'kiskanirim-husamettin-guven-upupo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kiskanirim dogrusu budur

insanim insanligin kanunudur

evlilikte tore odur

oyleyse bende kiskanirim

bana kiskanc diyorlar 

sevgimi hic bilmiyorlar

sonra birde sucluyorlar

oyleyse bende kiskanirim

esim dostum varsanirdim

megerse ben aldatildim

ondan ote hor goruldum

oyleyse bende kiskanirim

ne olur biraz anlayisla bakin

beni dertlerimle yalniz birakin

bende boyleyim kinamayin sakin

oyleyse bende kiskanirim', 'kiskanirim dogrusu budur insanim insanligin kanunudur evlilikte tore odur oyleyse bende kiskanirim bana kiskanc diyorlar  sevgimi hic bilmiy...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiskanirim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gürültü', 'gurultu-ese-ese-ir1lc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gürültü

daha olsun

hayatında

kalp atışlarımı

dinle', 'bir gürültü daha olsun hayatında kalp atışlarımı dinle...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gurultu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olan', 'olan-ese-ese-1e3hh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'olan olmuştur

olan

olunmazlık

olunamamazlık''tır belki de

boşver

olanla olunmaz', 'olan olmuştur olan olunmazlık olunamamazlık''tır belki de boşver olanla olunmaz...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-ese-ese-1xe7j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir soruya

bir kerede

bir doğru yanıt verebilmenin

olasılığı nedir? 

bir düşünün.', 'bir soruya bir kerede bir doğru yanıt verebilmenin olasılığı nedir?  bir düşünün....', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/soru-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoğun', 'yogun-ese-ese-f1jyw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yoğundan

daha yoğun

bir yoğun

var mıdır?', 'yoğundan daha yoğun bir yoğun var mıdır?...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yogun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdam masasına oturtmuşsun', 'i-dam-masasina-oturtmussun-sair-gaddar-16-tv3cf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanki bir sandık,

Hep acılarla doldurmuşsun,

Üstüne kendini yazıp,

Anahtarı kırmışsın.

...

Açmamış kırmamışsın,

Bırakmışsın aylarca,

Arkana bile bakmadan,

Çekip gitmişsin.

...

Onun için hiç ağlamamış,

Biraz olsun yanmamışsın,

Üstüne zındanlara kapatıp,

Sensizliğe mahkum etmişsin.

...

Dört duvar arasında,

Onu yanlız bırakmışsın,

Ziyaretçilere kapalı,

Tek hücreye atmışsın.

...

Elektiriğe vermiş,

Canını almışsın,

Cezası idam cezası,

Asın gitsin demişsin.

...

Bırakmayın hiç onu,

Vurun öldürün demişsin,

Son kelimesinde Ezgim derken,

Kurşunlara verip sandalyeyi çekmişsin.

...', 'Sanki bir sandık, Hep acılarla doldurmuşsun, Üstüne kendini yazıp, Anahtarı kırmışsın. ... Açmamış kırmamışsın, Bırakmışsın aylarca, Arkana ...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/idam-masasina-oturtmussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-ese-ese-ee7p9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gerçek geliyor ve dost

oluyor

yalnızlık gerçek ve ben

içiyoruz

iyi de anlaşıyoruz

gündüz oluyor

gerçek uyuyor

yalnızlık yanımda

benim başım ağrıyor', 'gerçek geliyor ve dost oluyor yalnızlık gerçek ve ben içiyoruz iyi de anlaşıyoruz gündüz oluyor gerçek uyuyor yalnızlık yanımda benim başım ...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gercek-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin o gün bitmişti', 'gittigin-o-gun-bitmisti-zubeyde-uzuner-f5d7c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gittiğin o gün bitmişti her şey

yüreğim bir kuş gibi çırpındı ardından

umutlarım vicdansızlığında boğulmuştu

ben geç olsada seni o gün tanımıştım

gittiğin o gün bitmişti herşey

sevgim, kinim, nefretim.

sen gittikten sonra bu kalp dolmadı

bu kilitli kutuyu kimse açmadı

ne sen nede başkası anladı

yüreğim her zamanki gibi buruktu

postacıyıda sevmiyorum artık

bana mektup getirmeyi unuttu

gittiğin o gün bitmişti herşey

sevgimin boynu bükük kaldı

aşkım öksüz kanadı kırıktı

ne yapsın sevmişti bir kere

seni götüren trenede küskünüm

seni geri getirmedi diye', 'Gittiğin o gün bitmişti her şey yüreğim bir kuş gibi çırpındı ardından umutlarım vicdansızlığında boğulmuştu ben geç olsada seni o gün tanım...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Uzuner']::text[], 8.5, '{"poet":"Zübeyde Uzuner","poet_slug":"zubeyde-uzuner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gittigin-o-gun-bitmisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan,yalan,yalan', 'yalan-yalan-yalan-husamettin-guven-a9q5w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yalan atip durma sakin

halinden belli bakin

bakin gozler ne diyor

yalan, yalan, yalan

o sahtekar guluslerin

halinden belli senin

aldanmayin ona sakin

yalan,yalan,yalan

gozlerini sozersin

yalanciktan gulersin

gunlercede kusersin

yalan,yalan,yalan

nasil ettin bana oyle

sevmedimmi seni soyle

sevsemde bundan boyle

yalan,yalan,yalan', 'yalan atip durma sakin halinden belli bakin bakin gozler ne diyor yalan, yalan, yalan o sahtekar guluslerin halinden belli senin aldanmayin ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalan-yalan-yalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı', 'sari-ese-ese-rrpuw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'senkronik yalnızlıklarımız vardı

sen kronik yalnızdın', 'senkronik yalnızlıklarımız vardı sen kronik yalnızdın...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sari-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olabilmek', 'olabilmek-ese-ese-96mv2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşamı anlamaya

başladığın andır

durabilmek ayak üstünde

sorunda bu zaten

başkası olmak

başkasıyla olmak

başkasının olmak

değil

kendi başına başkasıyla

başkasıyla kendin olmak', 'yaşamı anlamaya başladığın andır durabilmek ayak üstünde sorunda bu zaten başkası olmak başkasıyla olmak başkasının olmak değil kendi başına...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olabilmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trepanasyon Yazılımları', 'trepanasyon-yazilimlari-ese-ese-l4b7d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düşlerin prensesi

ile bendik

bu geceyi

paylaşan

ve gündüzü

bekleyen

kumrular

teslim oluyoruz', 'düşlerin prensesi ile bendik bu geceyi paylaşan ve gündüzü bekleyen kumrular teslim oluyoruz...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/trepanasyon-yazilimlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piç', 'pic-ese-ese-e5s3a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'anlatacak

ne olabilir ki

kalıntı

bir hayat

alıntı

bir bırakıt''tan

başka

ne var

bana

ait

biliyor musun

hiçliğin piçliği', 'anlatacak ne olabilir ki kalıntı bir hayat alıntı bir bırakıt''tan başka ne var bana ait biliyor musun hiçliğin piçliği...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pic-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin', 'guvercin-ese-ese-py4ba', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'konmuş bir güverteye

bedavaya getiriyor

bir göçü

kanat çırpmak yok

yorulmak yok

süzülmek yok', 'konmuş bir güverteye bedavaya getiriyor bir göçü kanat çırpmak yok yorulmak yok süzülmek yok...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guvercin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lük-Lik', 'luk-lik-ese-ese-oqyxu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kötülük

bin yaşına bastı

az önce

biraz önce

mumları

söndürene kadardı

iyilik', 'kötülük bin yaşına bastı az önce biraz önce mumları söndürene kadardı iyilik...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/luk-lik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdam', 'i-dam-ese-ese-qygw3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 've kar bütün kötülükleri örttü

giz ve siyah saklanıverdi

karın altına

gün geldi

güneş bütün iyilikleri eritti

giz yok oldu

siyah tutklandı

ve tüm belirsiz

suçları

itiraf etti

güneşe

SİYAH''ı astılar', 've kar bütün kötülükleri örttü giz ve siyah saklanıverdi karın altına gün geldi güneş bütün iyilikleri eritti giz yok oldu siyah tutklandı v...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/idam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çerçeve', 'cerceve-ese-ese-jpagp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zaman çerçeveliyor

beni

duvarına asıyor

sonsuzluğunun', 'zaman çerçeveliyor beni duvarına asıyor sonsuzluğunun...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cerceve-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S harfi', 's-harfi-ese-ese-apyro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hayattan

birkaç ''S''

daha düştü

sövgüler

övgülerin

sevgiler

evgilerin

yerini aldı

ve

sen

en

sanıların

anılarısın

S-özgürüm', 'hayattan birkaç ''S'' daha düştü sövgüler övgülerin sevgiler evgilerin yerini aldı ve sen en sanıların anılarısın S-özgürüm...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/s-harfi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İp', 'i-p-ese-ese-jhlt0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-bir intihar esnası-

boynumdaki ipi

sana veriyorum

beni yaşama bağla', '-bir intihar esnası- boynumdaki ipi sana veriyorum beni yaşama bağla...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ip-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanım', 'sultanim-cemaleddin-ozmen-df2e1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana sevgim aciz kalıyor.

Yüreğimde ki gül mürekkebe yön veriyor.

Vallahi zerre hükmündeki sevgim,

Seni malımdan canımdan öte biliyor.

Her akşam kaldırım döşeli yollarda yürüyorum.

Her adımda aşkını gördüğümü zannediyorum.

Aslını göremiyorum bari,

Hayalinden mahrum eyleme sultanım.

Yağmur gibi damla damla akan göz yaşlarım var.

Her damla kayalar altından filiz çıkartıyor.

Sel vurup,rüzgarlar esiyor.

Gel beni de gül cemalinle güldür.Sultanım

Sensiz siper aldık hedefe koştuk.

Hiç bilmedik hançeri bize çevirdik.Yüreğimize soktuk

Sensiz dağ eteklerinden aştık.yerlere düştük.

Elimizden tutan olmadı.Gel al bizi sultanım.

Sensiz benlikler doğdu,heybetleri büyüttük.

Adem''in çocuklarını bir birlerine kanlı düşürdük.

Bizdik ben olduk nasihatini unuttuk.

Gel,yanında hiç olan sahabene çevir bizi sultanım.

Sensiz yediler yetmiş yedi oldu.

Çocuklar büyüdü torunları öldü.

Biz o torunların çocukları,şimdi çöle düştü.

Yağmur ol gel,bir damla ver sultanım.', 'Sana sevgim aciz kalıyor. Yüreğimde ki gül mürekkebe yön veriyor. Vallahi zerre hükmündeki sevgim, Seni malımdan canımdan öte biliyor. Her a...', ARRAY['Türk Edebiyatı','Şiir','Cemaleddin Özmen']::text[], 8.5, '{"poet":"Cemaleddin Özmen","poet_slug":"cemaleddin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sultanim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öykü', 'oyku-ese-ese-b4re4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiçbir şey söyleme

önceye ait

sus ve yaşa

geçmiş

-miş''li bir geç''lik

artık

geleceğin

ne takısı var

ne öyküsü', 'hiçbir şey söyleme önceye ait sus ve yaşa geçmiş -miş''li bir geç''lik artık geleceğin ne takısı var ne öyküsü...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oyku-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
