INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıklarım', 'ayriliklarim-mucahit-gulbas-tzh9k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dönmek mümkün mü geriye

Aşılan yolları vermek geride kalmayanlara

Ne denli uzaktık ayrılığa

Ne denli uzak kaldık gör..

Kahrolası maskeler ör haklılıklardan 

Ve  kurtuluver sıkıysa

Geriye kalmaklardan.

Bilirim sen de bana benzersin ya biraz

Aynı çan sesine uyanırız kabuslarımızdan

Ve bakmayız  çıktığımızda yola

Bakmayız Bir daha geriye

Peh...Peh...Peh

İşte bu yüzdendir

Ayrılıklarımızın cümle rivayeti...

1994 İzmir', 'Dönmek mümkün mü geriye Aşılan yolları vermek geride kalmayanlara Ne denli uzaktık ayrılığa Ne denli uzak kaldık gör.. Kahrolası maskeler ör...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Gülbaş']::text[], 8.5, '{"poet":"Mücahit Gülbaş","poet_slug":"mucahit-gulbas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayriliklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-ese-ese-ypz5v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aşk ilişir

ilişki olur

biter

yara olur

kurur

kabuk olur

kalkar

iz olur

biri sorar

ne olur?', 'aşk ilişir ilişki olur biter yara olur kurur kabuk olur kalkar iz olur biri sorar ne olur?...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-olur-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Dakika/ 7. Mektup', 'bes-dakika-7-mektup-mucahit-gulbas-bu3qj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ahh! Anlamak gözün çıksın

Nasıl oluyor bir yılı beş dakikaya sığdırmak....? 

Tam oniki ay sonra bu gün.Yani dolu dolu bir yıl.

Değişenin ne olduğunu bir anlayabilsem.

Sıyrılıversem ayrılıkların nedenini,Doğruluklarımın sırtana yüklemekten.

İşte tam oniki ay önce bu gündü.Gerçekten o kadar oldu mu.? 

Kesik kesik hatırladıklarımı toplasam beş dakika bile yapmıyor.

Yani şimdi biz, tam bir sene önce bu gün. Geçen seneyi beş geçe mi oluyor

yada bu güne beş var...Bu gün,

Teneke sesli cihazda bir şarkı çalıyor,Çalmıştı

Tam bir sene önce bu gün düşlerimizi pazarladığımız bir yerde,kaçmakların mum alevine sığınıp

kuş uçuruyorduk.Senin gözlerinde keder benimkinde nem aynı şarkıyı duyuyorduk....

 İşte şimdi..Tam bir sene geçti diye söylüyor takvimde yapraklar.Oysa olsa olsa üstünden beş dakika geçmiş,

Yahu nasıl oluyor su beş dakikaya bir yılı sığdırmak 

Sevdiğim  en iyisi mi sen,geçen son beş dakikanın uzunluğuna aldırma.Unutulmak koyuyor adama. Bir iki satır bişey yaz,beş dakikanı bile almaz takrar beni hatırla olmaz mı..

Sadece beş dakika

15.12.96.Pazar 17,24  Yalova', 'Ahh! Anlamak gözün çıksın Nasıl oluyor bir yılı beş dakikaya sığdırmak....?  Tam oniki ay sonra bu gün.Yani dolu dolu bir yıl. Değişenin ne ...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Gülbaş']::text[], 8.5, '{"poet":"Mücahit Gülbaş","poet_slug":"mucahit-gulbas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bes-dakika-7-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tırnak', 'tirnak-ese-ese-9q9qs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'varlığın

önce yüreğime

oradan beynime

ve ruhuma bulaştı

şimdi ise bedenime

tıpkı tırnak gibi

uzuyor kesiyorum

ama yine uzuyor', 'varlığın önce yüreğime oradan beynime ve ruhuma bulaştı şimdi ise bedenime tıpkı tırnak gibi uzuyor kesiyorum ama yine uzuyor...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tirnak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevdadır Batman', 'bir-sevdadir-batman-tuncay-akdeniz-j0nja', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tarihten öğrendim Elakhan adı

Asırlık çınarın dalı BATMAN dır

Medeniyet şehri yaşamın tadı

Kültürün libası tülü BATMAN dır

Yavuz Selim hanla aynı yaştasın

Adın İLUH köyü sen bir başkasın

Altından değerli gözde kaştasın

Türkiye’nin gözde ili BATMAN dır

İlahi bir sırdır beştir ilçesi

Evliya diyarı köyü beldesi

Hasankeyf  kalesi ayrı bir süsü

İslam’ı alimler gölü BATMAN dır

İnsana sevgiyle dostlukla bakar

Doğudan diclesi  sevdayla akar

Raman kuyusundan petrolü çıkar

Türkiye’nin eli kolu BATMAN dır

Kimseler sormamış nasıl geçimi

Köyleri kazası vermiş göçünü

Şiirle ağıtla dökmüş içini

Hasret yaşlarının seli BATMAN dır

Sevginin yuvası doğruluk özü

Yatırıma uygun ovası düzü

Misafir gidince gülüyor yüzü

Dostluk bağlarının gülü BATMAN dır

Tuncay dan hediye yazdım şiirin

Kadım dost edindim iki şairin

Anlatamam seni tarihin derin

Söyletsem tarihi dili BATMAN dır', 'Tarihten öğrendim Elakhan adı Asırlık çınarın dalı BATMAN dır Medeniyet şehri yaşamın tadı Kültürün libası tülü BATMAN dır Yavuz Selim hanla...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-sevdadir-batman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-ese-ese-emq62', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşam bir bilmece

belki de bilmemece

her an

herşey olabilirmiş

hiç bir an

hiçbir şeyin olamayacağı

gibi', 'yaşam bir bilmece belki de bilmemece her an herşey olabilirmiş hiç bir an hiçbir şeyin olamayacağı gibi...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bilmece-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskeler Sırıtkan / Yüzler Mağdur...', 'maskeler-siritkan-yuzler-magdur-i-mdat-ozcan-ndzft', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayda bre… 

Abalıya vurulsun… 

Diz üstü çökertilsin umut 

Kafasına sıkılsın beş – on mermi 

Maskeler sırıtkan 

Yüzler mağdur 

Bahar uzanan ellere düşman kuytu 

Değersize değer verilir 

Sevdasıza sevda 

Adımlar kırılsın vuslata atılan 

Uykularım tedirgin 

Hayda bre… 

Rüyalar yorulsun… 

Matem havası eser gönüllerde 

Yas tutulsun 

Üryan çığlıklar 

Eylül kuşatılmışlığında 

Gözlerinden kan kızılı yaşlar boşalır 

Saçlarına ömür takılı sevgilinin 

Ömrüne eklediğim ömrüm kurşunlanır sevgili 

Sevdanın yoluna koyduğum başım ezilir 

Yüreğim / sürgün 

Mahrem sayıldı hayallerim 

Gülmelerim / tutsak 

Hayda bre… 

Etrafım sarılsın… 

Hoyrat eller yumruk olup yağsın üstüme 

Hasret bırakıldığım yar kokusu prangalansın 

Haykırsın babayiğitleri (!)  devrin 

Kırsın yaşanmış anıları 

Dizginlesin yaşanacakları 

Hayda bre… 

Abalıya vurulsun… 

Hayda bre 

Sevdalıya vurulsun… 

26/07/2005 - Kartal...', 'Hayda bre…  Abalıya vurulsun…  Diz üstü çökertilsin umut  Kafasına sıkılsın beş – on mermi  Maskeler sırıtkan  Yüzler mağdur  Bahar uzanan e...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/maskeler-siritkan-yuzler-magdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Fotoğrafın Arka Yüzü', 'bir-fotografin-arka-yuzu-babur-pinar-7q5ps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimizde sürgün zamanı inci avcıları 

bulduklarını mavi bir sese verirdi  Yenişehir’de

Akşamüstü sokağı  bürüyünce menekşe

tanıdık bir yüzü hatırlatırdı kuş cıvıltıları 

İmgenin arka bahçesinde oturup gece

düş ormanından getirdiklerimizi paylaşırdık

Herbirimizin bir kardeşi vardı kayıp

sonsuzluğa resmedilmiş bir yıldızda

Ceplerimizdeki kristal bilyeleri kırıp 

küçük yangınlar çıkarırdık

arka sokaklara dalıp gizlice

Serin diplere çekilirdi karanlık

Sevinçli dudaklarımızı öperken keder 

öykümüzü ısırarak kapkara

gölgemizin izini sürerdi köpekler

Düşünde gördüğü celladını arardı gül

kaldırımları laciverde boyardı ihanetçisi

Gece gelen ayak sesleriyle sevişirdi hüzün

Sevgilisini ellerinden tutup bütün gün

delicesine öperdi zamana yenilmiş serüvenci 

ve sanıldığı kadar uzak değildi eylül

Gerçeğin kıyısına oturup beklerdik romanı

Hayaları sıkılarak iğdiş edilirken imge

bahara adak giysileri atardık ateşe

Düşerdik soluk soluğa gelen güne

yeni hayatlar zamanı

Sokak kapısına ak mendil düşmüş

ateşi çalan Prometeus’un armağanı

Getirip gök mavisini kente bıraktı düş

yine yolculuklar zamanı 

                                                         

(Haziran/2005- DAMAR  San.Ed. Dergisi)', 'Gözlerimizde sürgün zamanı inci avcıları  bulduklarını mavi bir sese verirdi  Yenişehir’de Akşamüstü sokağı  bürüyünce menekşe tanıdık bir y...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-fotografin-arka-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Koşalım', 'haydi-kosalim-deniz-yavuz-kwplv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haydi koşalım 

Soluğumuz boğazımızı yırtıncaya

Çatlayıncaya 

Patlayıncaya kadar, 

Ardımızdakileri görmeyinceye kadar,

Koşalım koşalım...

Haydi koşalım

Nereye mi? 

Ne bileyim ben!', 'Haydi koşalım  Soluğumuz boğazımızı yırtıncaya Çatlayıncaya  Patlayıncaya kadar,  Ardımızdakileri görmeyinceye kadar, Koşalım koşalım... Hay...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yavuz']::text[], 8.5, '{"poet":"Deniz Yavuz","poet_slug":"deniz-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/haydi-kosalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Güne Bir Mektup 2', 'her-gune-bir-mektup-2-mehmet-haluk-hisli-8s3xs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...

Ve çağrı böylece yapılmıştır... İnsan nerede olursa olsun, neye sahip olursa olsun bir biçimde başka insanlara ihtiyaç duyar; yazıyla da olsa, sözle de olsa bir insan sıcaklığıdır hissetmek istediği...  Birilerinin onun varlığına öyle ya da böyle tanıklık etmesini ister.  Birileri bir biçimde bulaşsın ister varlığına... Birileri sen varsın, sen bir değersin ve ben sana zaman, emek ve enerji harcıyorum desin ister. Ne kadar güçlüysek o kadar da zayıf ve kırılganızdır ve o kadar muhtacızdır birilerinin bize bulaşmasına; öyle ya da böyle...

Ve nihayet beklenen yanıt gelmiştir, biri varlığımıza tanıklık etmek istemiş ya da aynı şeyleri kendi varlığı için istemiştir.

“Özgür bir dille yazmışsınız, sizi tebrik ediyorum... 

Fakat hiç düşündünüz mü, çoğu kadınlar bu özgür dilden ürkerler,çekinirler ve siz yine ıslak gülünüzün özlemiyle kalırsınız... 

başarılar dilerim...”

...', '... Ve çağrı böylece yapılmıştır... İnsan nerede olursa olsun, neye sahip olursa olsun bir biçimde başka insanlara ihtiyaç duyar; yazıyla da...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/her-gune-bir-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapımdaki heybe', 'kapimdaki-heybe-can-ozcan-ozkan-6hiem', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat 

Yağmur damlasına asılmış

Baharda esen yürekler suya susamış

Su 

Gözlerde saklanmış bir gece

Gece

Yıldız yüklenmiş…

Sevda 

Kapıma yar kokusunda 

Yıldız dolu heybe bırakmış', 'Hayat  Yağmur damlasına asılmış Baharda esen yürekler suya susamış Su  Gözlerde saklanmış bir gece Gece Yıldız yüklenmiş… Sevda  Kapıma yar ...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kapimdaki-heybe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaten Ben Yokum', 'zaten-ben-yokum-deniz-yavuz-s686h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Madem ben olmasamda her şey seyrine devam edecek 

Yaşamamın ne gayesi olsa gerek 

Soruyorum ben neden varım 

............... zaten ben yokum...

Dünya yine dönecek 

En güzel anlar yine olacak 

Niçinler yine cevapsız kalmayacak

İnsan yine gülecek, yine sevecek 

Ben olmasam da 

Yalnızlıklar yeni sahip bulacak belki kendisine 

Aşklar yine yaşanacak kimi yeni

Var olmalar yine dar gelecek insanoğluna

Umut etmek, umutla yaşamak yine olacak 

Ben olmasam da 

Peki o zaman ben neden varım...

...................  zaten ben yokum...

Yaşamak için yaşamın bir gayesi olması gerek 

Ben yaşıyorum 

O halde yaşamamın bir gayesi var 

Ama ne?', 'Madem ben olmasamda her şey seyrine devam edecek  Yaşamamın ne gayesi olsa gerek  Soruyorum ben neden varım  ............... zaten ben yokum...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yavuz']::text[], 8.5, '{"poet":"Deniz Yavuz","poet_slug":"deniz-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaten-ben-yokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-nalan-kahraman-7exgc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzündeki bulutlar da,

Bulutların kızgınlığını püskürterek ıslattığı caddeler de,

Islak caddeye birine sitem edercesine yapraklarını döktüğü ağaçların altında,

Seni ve beraberliğimizi arıyorum.

Masvami yüzeyini kapkara çarşafa devreden gökyüzün de,

Issız loş gecelerin arasında,

Kara çarşaf da her biri bir umut ışığı gibi parlayan yıldızların için de,

Seni ve beraberliğimizi arıyorum.

Vücudumun dört bir yanın da  hissettiğim soğuğun her ürpertisin de,

Isınmak için yaktığım ateşden çıkan her kıvılcım tanesinde,

Seni ve beraberliğimizi arıyorum.

Bir zamanlar saray dediğimiz,

Mutlulukların en güzelini tatdığımız,

Şimdi ise kodese  dönen kulübebiz de

Seni, beraberliğimizi  ve anılarımızı..........

tekrar tekrar yaşıyor.....

O güzellikler ve seni arıyorum....', 'Gökyüzündeki bulutlar da, Bulutların kızgınlığını püskürterek ıslattığı caddeler de, Islak caddeye birine sitem edercesine yapraklarını dökt...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ariyorum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-avni-aydin-25h91', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gittiğinde farkettim...

evim çok genişmiş...

fazlaymış bana 2 oda.

neydi bana her şeyi farklı gösteren? 

artık biliyorum,

mutlu günlerimiz oldu seninle...

acı günlerimiz fazlaydı keza...

herşeye rağmen akşam döndüğümde sen vardın...

sabah uyandığımda; 

nefesini göğsümde hissetmek kadar güzel bir duygu yokmus...

işe zorla giderken akşamı hayal edişim...

herşey bir şekilde seni barındırıyordu...

nedenini bilmiyorum ama,

hayatımın bir köşesinde sen vardın...

bir akşam döndüğümde evimiz bomboştu...

yatağım soğuktu o gece...

yatağımız...

sabah erkenden uyandım,

evden kaçtım adeta...

neredeydin, neredesin? 

seni aramak istiyorum şu koskoca kentte...

bulamıyorum ama...

bulamıyorum çünkü çok uzaksın...

neden gittin ki? 

sorun neydi? 

seni sevmediğimden şikayet ederdin...

bişeyleri duymak isterdin hep...

söylemediğimde kızardın,

sen kırılmasından korktuğum kanatlarımdın...

neden kırıldın?', 'gittiğinde farkettim... evim çok genişmiş... fazlaymış bana 2 oda. neydi bana her şeyi farklı gösteren?  artık biliyorum, mutlu günlerimiz o...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ozledim-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Çığlıklarım...', 'sessiz-cigliklarim-tulay-eker-psqok', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '_ Neye alışılıyor hemen anlamadım? 

___İnsan insana 

- Çoğunlukla böyle olmaz biliyorsun 

___ Aradaki bağ önemli 

_ Bağı tutmak gibi 

__ Bağlanmak gibi 

- Varlığını hissettirmek gibi 

__ Hisleri gerçek kılmak gibi

Çekmece çekmece içinde 

Yanıklar kırıklar kir pas 

Vurulmuşluğun yankısı 

Sesiz çığlık 

El yanar dokunamazsın 

Can çeker kanamazsın 

Kana kana bul beni 

Sar beni 

Al beni 

__Sessiz çığlık gibi? 

_Uzanıp yakalamak son an da 

__ Çırpınırken mi? 

_ Garip bir düşüşün sonunda 

__ Düş düşüyorken belki de 

_ Düşen gözkapaklarıysa evet 

__ Kirpiklerin arasında sıkışmış iki damla 

_ Bir parmak ucunda 

Dokundukça zamana hasret yanık tütün kokusu doluşuyor damarlarıma 

Yaşanmışlıkları alıp koynuma gidesim var nereye deme ben de bilmiyorum

Sadece... 

Kaçmalıyım hatta koşmalı belki de uçmalı kanatlanıp sonsuz vadilerin

Kollarında konaklamalı ne yar kokmalı ne sancı duymalı ne de yel almalı 

Saçlarımdaki acı tanelerini 

__ Ya donarsa 

_ Dokunur işte o zaman 

__ Donuyorum belki de 

_ Uzaklaştıkça güneşten üşür insan 

__ Güneş çok uzakta 

_ Uzat elini dokun 

_ Parmağının ucunda 

__ Dokunsam kaçacak gibi 

__ Ellerim yumuk 

_ Okşa elinin tersiyle 

Korkutuyor zaman beni yakamdan tutmuş sensizliğin eli gittin gideceksin 

gibi... Kollarım fersiz dudaklarımda sana dair sözler 

yer gök boynuma dolanmış gitme diyen titrek ses..ses...sessiz çığlık... 

Ha desem akıp gideceğim bir yanımda kollarını açmış ölüm diğer yanımda 

dizleri kapaklanmış düşlerim ha desem ha desem gideceğim...

Seni öyle özledim ki sessizce düşüyorum ölümüne...

Geliyorum bekle!', '_ Neye alışılıyor hemen anlamadım?  ___İnsan insana  - Çoğunlukla böyle olmaz biliyorsun  ___ Aradaki bağ önemli  _ Bağı tutmak gibi  __ Bağ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sessiz-cigliklarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Sevdim İnsanlık', 'cok-sevdim-i-nsanlik-mehmet-dag-46fn3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÇOK SEVDİM İNSANLIK

Vursunlar bırakın vursunlar beni

İsterse bir pula versinler beni

İsterse çarmıha gersinler beni

Çok sevdim insanlık çok sevdim seni

Aç kalıp sürünsen özlemim sensin

Sarı, siyah, beyaz her şeyim benim

Varlığım hayalim bir tek tutkumsun

Çok sevdim insanlık çok sevdim seni 

İstemem çekmesin hiç kimse acı

Kol kola gezilsin hep kardeş bacı

İsterim hep gülsün yaşlısı genci

Çok sevdim insanlık çok sevdim seni

Hapisler boşanıp okullar dolsun

Yanlışı doğruyu herkes öğrensin

Karakol yerine hastane olsun

Çok sevdim insanlık çok sevdim seni

Tüm ırmaklar aksın sular durulsun

Sevgi aşılansın silahlar sussun

Atomlar kahrolsun fabrika gelsin

Çok sevdim insanlık çok sevdim seni

Değerin ölçülmez parayla pulla

Yeni doğmuş çocuk kalbi seninle

O yeni nesile hep çiçek yolla

Çok sevdim insanlık çok sevdim seni', 'ÇOK SEVDİM İNSANLIK Vursunlar bırakın vursunlar beni İsterse bir pula versinler beni İsterse çarmıha gersinler beni Çok sevdim insanlık çok ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cok-sevdim-insanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahh val', 'ahh-val-cafer-petek-azs3w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir garip hal içindeyim

vuslat-ı muhal içindeyim

halim bildiğin haldir

bir malum-u ahh_val

bir hal-i pür melal içindeyim', 'Bir garip hal içindeyim vuslat-ı muhal içindeyim halim bildiğin haldir bir malum-u ahh_val bir hal-i pür melal içindeyim...', ARRAY['Türk Edebiyatı','Şiir','Cafer Petek']::text[], 8.5, '{"poet":"Cafer Petek","poet_slug":"cafer-petek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ahh-val-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir Köle Gerek', 'bana-bir-kole-gerek-ahmet-nural-ozturk-6kxxn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana bir köle gerek gözleri kömür elmas olsun

Yitirilmişleri kazısın gelsin en derinden umut olsun

Bakışlarında hava biraz da cilve olsun 

Boyu fazla uzun değil saçları da kara olsun

Bana bir köle gerek işte aynen böyle olsun

Yüreğimle taşırım istediği kadar ağır olsun

Bir köleye bin kere canım fada olsun', 'Bana bir köle gerek gözleri kömür elmas olsun Yitirilmişleri kazısın gelsin en derinden umut olsun Bakışlarında hava biraz da cilve olsun  B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bana-bir-kole-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy bu sesi.', 'duy-bu-sesi-i-shak-ozlu-y8atl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayağımda pranga,sicimle bağlı elim kolum,

Şimalden cenuba,garptan şarka sanadır yolum.

Nereye baksam cemalin kalmadı sağım solum,

Duy bu sesi çok sevdiğini söylüyor yüreğim.

Doğan yavrusunu yalayıp ayağa kaldıran,

Doymadan sevgisine aç bir aslana kaptıran,

kurtarmak için ölümü göze alıp saldıran,

Anne ceylanın yüreğince yanıyor yüreğim.

Onbinlerce metre toprağın altında kaynayan,

Kudurup öfkesinden cidarlarını zorlayan,

Yüce dağların en zirve noktasında patlayan,

Kankırmızı lav sellerince kanıyor yüreğim.

Bataklık çamurunda açıp son demine eren,

Susuz kalınca naçar yaprağını yere seren,

Gözü bulutta bir damla suya hasret can veren,

Nilüferlerin öldüğünce ölüyor yüreğim.', 'Ayağımda pranga,sicimle bağlı elim kolum, Şimalden cenuba,garptan şarka sanadır yolum. Nereye baksam cemalin kalmadı sağım solum, Duy bu ses...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duy-bu-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yağmuru', 'nisan-yagmuru-harun-senel-4cbu2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine nisan yağmurunda ıslanacağım

Sensiz ve sabaha kadar...

Unuttuğumu mu sandın? 

Sen papatya falına bakardın

Bense gözlerine bakardım

Unuttuğumu mu sandın? 

Islak caddelerde dolaşırken

Şarkı söyleyişini ve ''''Seni seviyorum'''' diye

Haykırışını...

Unuttuğumu mu sandın? 

Güneş gözlerini,yufka yüreğini,

O nisan yağmuru kokan saçlarını...

Gözümden gitmiyor şimdi

Çam sokağı''ndaki dilenciye para verişin

Hep o gittiğimiz yerde,

Deniz kenarındayım her gün

Denize yansıyan güneşi izliyorum

Ama araya giren buluta isyan ediyorum

Çünkü güneşte seni görüyorum be gülüm

İşte kaybettim seni

Martılar,sandallara,dalgalara soruyorum,

Ve hatta güneşe soruyorum

Arıyorum ama bulamıyorum

Gözyaşlarımı döktüm denize

Belki sana gelir diye

Belki haber salar diye

Bekledim seher vaktine kadar,

Sabahlara kadar,

Aç,susuz yine bekledim,sen gelmedin

Benki suya hasret dağlar gibiyim

Sana susadım ve san hasretim

Benki rüzgara hasret dallar gibiyim

Senin nefesini özledim,hadi dön

Yar ecelim olacaksın acımı bil

Sevdamı bil

Aşkımın içinde kaybolup gidiyorum

Her biten günle bende bitiyorum

Şimdi ise çam sokağı''nın dilencisi benim

Şimdi sevda dileniyorum

Seni dileniyorum be gülüm

Belki gelirsin diye

Belki seni,seni bulurum diye

   nisan 2004', 'Yine nisan yağmurunda ıslanacağım Sensiz ve sabaha kadar... Unuttuğumu mu sandın?  Sen papatya falına bakardın Bense gözlerine bakardım Unut...', ARRAY['Türk Edebiyatı','Şiir','Harun Şenel']::text[], 8.5, '{"poet":"Harun Şenel","poet_slug":"harun-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/nisan-yagmuru-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sevinci Acılardan Çaldık Biz', 'bu-sevinci-acilardan-caldik-biz-numan-eksioglu-pd3qs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şarkılar içermedi

			Şiirler dışladılar

			Tuvale yansımadı bizim çektiklerimiz

			Bu sevinci acılardan çaldık biz

				

			Bu kulak yürek sesi duymuştur yanlış duymaz

			Bu eller bu gözleri şartlı baksa çıkarır

			Bu dilek adımların öğretmeni

			Sürekli adresimiz

			

			Sis görmeyi engeller ama ömrü ne kadar

			Güneş Rizeli’ye  de göstermez mi kendini

			Ötelere varmaya hisler düşler el ele

			Ve coşku ilk dersimiz', 'Şarkılar içermedi 			Şiirler dışladılar 			Tuvale yansımadı bizim çektiklerimiz 			Bu sevinci acılardan çaldık biz 				 			Bu kulak yürek se...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-sevinci-acilardan-caldik-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Şarkı Sevgi Ve En güzel Şiir Aşk', 'en-guzel-sarki-sevgi-ve-en-guzel-siir-ask-numan-eksioglu-hi0sh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oğlum Ethem’e

Yıldızları yan yana getirerek

Adın yazılsa azdır

İnanmadığın şeyler tozdur küftür enkazdır

En güzel şarkı sevgi

Ve en güzel şiir aşk

İşte ondan büyüksün

Senin duyduğun yalnız

Yüreklerin söyledikleri sözdür

Senin karşında gül mü

Şarkıdan acizdir o

Bülbül kırık bir sazdır

İçini gören ayna kendi içine küser

Güzün bahardır senin

Keskin ayazın yazdır

Tüm çiçekler bir araya gelerek

Bir çiçek oluştursa

Senin çiçeğin yanında birazdır

Matematik en sevdiğin ders senin

Madalya takmış sana okulun yönetimi

Ölümün çaresini formüle ettiğinde

Bir madalya da benden

Çünkü ölüm o en büyük arazdır', 'Oğlum Ethem’e Yıldızları yan yana getirerek Adın yazılsa azdır İnanmadığın şeyler tozdur küftür enkazdır En güzel şarkı sevgi Ve en güzel şi...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/en-guzel-sarki-sevgi-ve-en-guzel-siir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evren Yok Mudur Çevren', 'evren-yok-mudur-cevren-numan-eksioglu-7j3gv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beden ruhtan hiç sapma

		Dilek yüreğe yönlen

		Güneş geceye de doğ

		Av avcıyı yakalamayı öğren

		

		Yanak aç kucağını nemlenmiş dudaklara

		Hüzün artık neşelen

		Aşk kendini her yürekte yinele

		Basamak diz omuz baş olmasın materyalin

		Acı kendine kinlen

	

		Şiir şarkıya dönüş

		Şarkı şiirden öğren

		Kendi en büyük ödül birisi oluver sen

		En kısa yol düşlerinin doğrusu

		

		Evren yok mudur çevren', 'Beden ruhtan hiç sapma 		Dilek yüreğe yönlen 		Güneş geceye de doğ 		Av avcıyı yakalamayı öğren 		 		Yanak aç kucağını nemlenmiş dudaklara 	...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/evren-yok-mudur-cevren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkese Pasta Aşkta', 'herkese-pasta-askta-numan-eksioglu-ba0fw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiirin bildirisi

			Kimsenin aldırısı

			Olduğundan işte böyle

			Ses hasta

			

			Enstrümanlar aceminin elinde

			Keman küs

			Şarkı yasta

			Acının saldırısı

			Sevincin çıldırısını sağlamış

			Zulüm işinde usta

			Az düş fazla yokoluşu getirir

			Sına kendini düşte

		

			Aç olana ekmeği sevgi sağlayabilir

			Herkese pasta aşkta', 'Şiirin bildirisi 			Kimsenin aldırısı 			Olduğundan işte böyle 			Ses hasta 			 			Enstrümanlar aceminin elinde 			Keman küs 			Şarkı yasta ...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/herkese-pasta-askta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret Sevdaya Rende', 'nefret-sevdaya-rende-numan-eksioglu-qgoib', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başkasında olmayan kendini bulmamıştır

		Ben giderim siz kalırsınız bende

		Oysa cırcır böceği en çok karınca için

		Çalmıştı çalgısını

		İnsanın sanatçıya verdiği değer belli

		Karınca da mı öyle

		Kin sevgilere törpü

		Nefret sevdaya rende

		Acının acıtması

		Yüreği incitmesi yanında önemsizdir

		Acı bizi duymuyor

		Ben iyimser biriyim

		Diyorum ki duysaydı acıtmazdı

		Kıstırılmış bir mutluluk bizimki

		Tüm filizleri budanmış bir sevinç

		Ah yinede kalbimiz doğru yönde

		Gözyaşlarını merhem yapmalı yaralara

		Yoksa tüm yaralara közler sargılanacak

		Ve her insana bir ezgi yapmalı

		Yapılsaydı insan giderdi önde', 'Başkasında olmayan kendini bulmamıştır 		Ben giderim siz kalırsınız bende 		Oysa cırcır böceği en çok karınca için 		Çalmıştı çalgısını 		İn...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nefret-sevdaya-rende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ovada Çöl Havası', 'ovada-col-havasi-numan-eksioglu-0zfws', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdinin sonrası yok

			Zaman yaktıklarının küllerini okşuyor

			Bozuştukça büzüşüyor insanlar

			Bir sevecen bakışa bin şiir yazan nerde

			Derde çareye tuzak

			Soruna çözüm zorda

			Ne zaman her parçamız bir bütün olacak ah

			Ne zaman öpücükler adres şaşırmayacak

			Ovada çöl havası baharın yarısı güz

			Artık ne dik ne doğru

			Gecelerin içinde kayboluvermiş  gündüz

			Şarkılarda zaman çalmakta artık

			Kalem yatay yazmakta

		

			Örtüşünce şiirin anlattığı anladıklarımızla

			Ancak o zaman düzelecek dünya', 'Şimdinin sonrası yok 			Zaman yaktıklarının küllerini okşuyor 			Bozuştukça büzüşüyor insanlar 			Bir sevecen bakışa bin şiir yazan nerde 		...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ovada-col-havasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpmek Varken Isırma', 'opmek-varken-isirma-numan-eksioglu-tap0r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıkarları çıkınca çıkılacak çıkmazdan

		Sesi sesli kılmalı suskunluğuysa yaslı

		Gök siyah ufuk kara bizler yerde yersizler

		Öpmek varken ısırma

		Şarkılara bile  veren şiirdir

		Yırtılmayınca örtü eksiltiyor artılar

		Ah özürlüce geçmiş ah kusurluca şimdi

		Okşamak varken vurma

		Yarına sarılmayan şimdi darılacaktır

		Her cümleye bir ezgi yapılacak ilerde

		Tüm zamanlar sevişirken alınan kadar zevkli

		Herkeste çocuklarca uygar olma çabası

		Bu yıllar bu yollara verilmeyecek artık

		Sarılmak varken itme', 'Çıkarları çıkınca çıkılacak çıkmazdan 		Sesi sesli kılmalı suskunluğuysa yaslı 		Gök siyah ufuk kara bizler yerde yersizler 		Öpmek varken ı...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/opmek-varken-isirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renksiz', 'renksiz-numan-eksioglu-lkz66', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırmızı  mı

				Siyaha boyadılar

				Mavi mi

				Körlerin görmesi serbest

				Yeşil mi

				Üstüne örtü örttüler

				Beyaz mı

Kolay saf dışı oldu

Turuncu  mu

Önüne duvar ördüler', 'Kırmızı  mı 				Siyaha boyadılar 				Mavi mi 				Körlerin görmesi serbest 				Yeşil mi 				Üstüne örtü örttüler 				Beyaz mı Kolay saf dışı ...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/renksiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ta ezelden yanmışız melâmetin narına', 'ta-ezelden-yanmisiz-mel-metin-narina-ali-riza-unal-a81zl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ta ezelden yanmışız melâmetin narına

Gamsız gönül meftun O Ahmet’in nuruna

Ne sırdır ki dil söylemez O Halik’ın arına

Mevla ile dem budur sanma sakın yarına

Alem şaşkın koşarken, zannındaki yarına

Damla coşar meşk ile ummandaki varına

Sen bendesin ben sende, ne garip bir hilkat bu

Firkat içre vuslat bu koyma sakın yarına

Sevmek dağlar aşmaktır O aşkın uğruna

Na ehil haram diyor bu aşığın şarabına

Bilemezsin tende canı sen anda teni sen

Çıkmaz isen ölmeğe o maşukun darına

---divan-ı süphaniyeden ---

tasavvuf müziği bestesidir söz ve müzik

 abdi aciz hadumul fukara Ali Rıza Ünal.

                  Nisan  2004.', 'Ta ezelden yanmışız melâmetin narına Gamsız gönül meftun O Ahmet’in nuruna Ne sırdır ki dil söylemez O Halik’ın arına Mevla ile dem budur sa...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ta-ezelden-yanmisiz-melametin-narina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmediğim Birine', 'sevmedigim-birine-numan-eksioglu-61joz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıkanmamış bir bakış atsam sana

		Gözümün kapakları bir daha aralanmaz

		Bir kerecik kaş çatsam

		Kaşlarım öyle kalır

		Sesimi yükseltirsem şiirlerim şarkılarım alçalır

		Gölgede bırakırsam güneşim görev yapmaz

		Gülmesem gülünürüm sarılmasam kınanır

		Aşağılasam seni

		Çiçeklerin aklından tarih boyu ilk defa

		Birine küsmek geçer

		Seni dövsem senden fazla ağlarım

		Dıştalasam ölürüm

		Aynadaki görüntü birazda sen değilse

		Ben hiç görünmeyeyim

		Yalnız bıraksam seni

		Sevişmeyi unuturum o saat

		Yarana sargı diye sarılacaksa eğer

		Derim yüzülebilir

		

		Ben umutlu ve sabırlı biriyim

		Gözlerimin gözüne yazdığını 

		Kalbin okuyacaktır', 'Yıkanmamış bir bakış atsam sana 		Gözümün kapakları bir daha aralanmaz 		Bir kerecik kaş çatsam 		Kaşlarım öyle kalır 		Sesimi yükseltirsem ...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevmedigim-birine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir 8', 'siir-8-numan-eksioglu-ok9j4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Var olun diye var etmem

		Var edin diye var ederim

		

		Anlayın diye anlatmam

		Anlatın diye anlatırım

		

		Konuşun diye konuşmam

		Şarkı söyleyin diye konuşurum

		Sevdiğinizde sevinmem

		Aşık olduğunuzda sevinirim

		Gerçeklere göre düşüm

		Düşere göre gerçek

	

		Aramayı öğretirim

		Bulmak sizin işiniz', 'Var olun diye var etmem 		Var edin diye var ederim 		 		Anlayın diye anlatmam 		Anlatın diye anlatırım 		 		Konuşun diye konuşmam 		Şarkı sö...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siir-8-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğe Bitişik Dil', 'yurege-bitisik-dil-numan-eksioglu-yzxoz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çarka tutuldu sevinç

			Rendelendi gülücük

			Huzur özürlü artık

			Yıllar yol alamıyor

			

			Gözler közler içinde

			Dil şiire kulak şarkıya küsmüş

			Hapis bedene ruhlar

			Ve yürekler dileksiz

			Adım yön bulamıyor

			Kemanın içi saman

			Zaman mı aman aman

			Fakir fukara fikir

			Sevgi aşk olamıyor

			Dilleri yüreklere bitiştirmeliyiz biz

			Kulakları dudağa

			Ayna gözlerimizi görünce yatışmalı

			Ve kalemle kazılar yapmalıyız', 'Çarka tutuldu sevinç 			Rendelendi gülücük 			Huzur özürlü artık 			Yıllar yol alamıyor 			 			Gözler közler içinde 			Dil şiire kulak şarkı...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yurege-bitisik-dil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulme Zarar Aşka Ve Düşlere Yar', 'zulme-zarar-aska-ve-duslere-yar-numan-eksioglu-xcazv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Erkan Başaran’a

			

			

			Baktığı her noktaya sevgi yazar bu gözler

			Bu nedenle verdiği aldıklarından fazla

			Geceye sözü yoktur gündüze sızmamışsa

			Ve varlığı çerçevenin dışında

			Her bütünde bir parçası var onun

			Şimdiden çok sonrası

			Yükünü indirişi daha ağır olanı sırtlanmalar içindir

			Sabun onla yıkanır

			Camdır kırılsa bile ışık geçirebilir

			Koldur yorulsa bile sarılacak güç bulur

			Koltuklara ayak olmaması var

			Enkazlara dayak olmaması var

			Zulme zarar aşka ve düşlere yar', 'Erkan Başaran’a 			 			 			Baktığı her noktaya sevgi yazar bu gözler 			Bu nedenle verdiği aldıklarından fazla 			Geceye sözü yoktur gündüze...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zulme-zarar-aska-ve-duslere-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulüm Aşkı da Bulur', 'zulum-aski-da-bulur-numan-eksioglu-p02u7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güllerin küllerine katlanamaz bu devran

		Gülün külü yakılır

		Bülbülün şarkısını duyana türlü vahşet

		Uçurtmalar ağaçlara takılır

		Şiirler eksiltirler kendi saygınlığını

		Şarkılar kulaklara süngüler sokuverir

		Kin mutlu ve gelecekten umutlu

		Kahkahanın tadına en çok bombalar varır

		Söylem en güzel eylem bilinmez kimselerce

		Enlem daralır canda boylam küçücük kalır

		Ve yalnızca yürümeyen yol alır

		Göz perdenin ve gölgenin ardında

		Dilleri yara kaplar söylerse kanar durur

		

		Bu sürü bu çobanı gütmediği sürece

		Zulüm aşkı da bulur', 'Güllerin küllerine katlanamaz bu devran 		Gülün külü yakılır 		Bülbülün şarkısını duyana türlü vahşet 		Uçurtmalar ağaçlara takılır 		Şiirle...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zulum-aski-da-bulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerini Bana Bırak', 'ellerini-bana-birak-nevzat-erkol-3gfvc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boş bir mayın gibiysen yaşamda

Salıngan bir bulut

Çaresiz bir ispinoz,

Fırtınaya güdümlü bir yelkenliysen ya da

Çok şey var sana anlatacağım.

Otur yanıma

Gözlerime bak,

Dinle

Ve 

Ellerini bana bırak.

Çaresizliğin açmazındaysan hele

Vuruyorsan gecelerde sokaklara kendini

Duyuyorsa bir yerin gün gün tükendiğini

Dalıp da gidiyorsa anlamsızca gözlerin

Dayanmaya çalış,

Haydi, topla kendini.

Umarın, dönüşün olabilirim belki

Ve yeniden başlayışın her şeye.

Otur yanıbaşıma

Hep sor dilersen

Susma, dök içini

Anlat, çok anlat.

Uysal bir kumru gibi

Daya başını göğsüme,

Yüzüne ateş vursa

Gözlerin çekinse de

Yaralıymışcasına

Ellerini bana bırak...

Yüreğin dayanır, iyi bilirim

Bin beter sevdalara

Sağalmaz acılara,

Göçse de beden

Geçse de yıllar

Yürektir, dayanır iyi bilirim,

Yenilmez zorluklara

Zorlu ayrılıklara.

Öyle bir güç doğar ki

Çatlayan tohum gibi,

Gözlerin ışıl ışıl

Öyle hazır ki

Birazdan doğacak güne.

Bir yürek nasıl direnir

Sen de şaşarsın,

Yalnız

Bırak ellerini

Değsin elime.', 'Boş bir mayın gibiysen yaşamda Salıngan bir bulut Çaresiz bir ispinoz, Fırtınaya güdümlü bir yelkenliysen ya da Çok şey var sana anlatacağım...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Erkol']::text[], 8.5, '{"poet":"Nevzat Erkol","poet_slug":"nevzat-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ellerini-bana-birak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair', 'sana-dair-reyhan-sak-60xo0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Verdim hayatımı ellerine

Gelmedikçe sen 

Mevsimsiz esen rüzgarlar gibi savruldum deli deli

Güneşlerimi karlara teslim ettiğim günden beri 

Sessizce ağlar oldum sana

Oysa ben senden hiç bir şey istememiştim.

Hayatın senindi, hayatım senin...

Sadece bir bakıştı günlerdir senden beklediğim

Aslında gelmen neyi neleri değiştirecek onu da bilmiyorum

Ben ki bu kadar acılar içinde yaşamışsam bunca zaman

Daha da yaşarım kim bilir kaç zaman? 

Bölük pörçük rüyalarım gibisin

Sabaha karşı gördüğüm ve hatırlayamadığım

Sen misin şu hayatımın en mevsimli döneminde

Acılar çekmeme sebep

Ben miyim yoksa ilkbaharlarımı karlara teslim eden? 

Gözümü açıp kapayıncaya kadar az bir zamanda

Giriverdin hayatıma

Şimdi gözlerimi dağlasalar bile çıkaramam seni

Bir güvercin kanadından kopan tüy misalidir gövdem

Usulca teslim etmek istiyor kendini deli rüzgara.

Bencil derler insanoğlu için YALAN! 

Başka bir insanı kendinden çok sevebiliyor oysa...

Ben ki Mecnun''numu bulmuşsam tek bir farkla,

Çok farkla Leyla''sını arayan çoktur dışarda.

Bu yürek ki ne sevdalar saklıdır bağrında...

Bir kendi sevdası kendine gelmiştir fazla.

Muallaktayım çoğu zaman

Kim için atar bu yürek? 

Benim sevdam delidir bir sana gelince ürkek...', 'Verdim hayatımı ellerine Gelmedikçe sen  Mevsimsiz esen rüzgarlar gibi savruldum deli deli Güneşlerimi karlara teslim ettiğim günden beri  S...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sak']::text[], 8.5, '{"poet":"Reyhan Sak","poet_slug":"reyhan-sak","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sana-dair-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettim Hepsini', 'kaybettim-hepsini-hulya-ellikci-200x4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Temiz duygularım vardı

Saf bir sersemliğim

Hiç olmadığım kadar aşık

Hiç olmadığım kadar dalgındım...

Bu dalgınlıkta kaybettim

Duygularımı, saflığımı...

Çılgın bir zihniyete kurban ettim hepsini 

Sonra da kendimi...

Sevdiğim insanlar vardı

Beni seven insanlar...

Hiç olmadığım kadar mutlu,

hiç olmadığım kadar neş''eliydim.

Gözümde çocukluğumdan kalan

Pırıl pırıl bir ışıltı...

Zorba bir zihniyete kurban ettim hepsini 

Sonra da kendimi...

Vazgeçemediğim umutlarım vardı

Hiç bir engelin yıkamadığı umutlar...

Hiç olmadığım kadar inançlı,

hiç olmadığım kadar hırslıydım.

Yüreğimde bir kuş çırpıntısı

Dilimde şarkılar...

kaybettim hepsini sonra da kendimi...', 'Temiz duygularım vardı Saf bir sersemliğim Hiç olmadığım kadar aşık Hiç olmadığım kadar dalgındım... Bu dalgınlıkta kaybettim Duygularımı, s...', ARRAY['Türk Edebiyatı','Şiir','Hülya Ellikçi']::text[], 8.5, '{"poet":"Hülya Ellikçi","poet_slug":"hulya-ellikci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kaybettim-hepsini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bunu Yapma', 'bana-bunu-yapma-reyhan-sak-oh9co', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana bunu yapma! 

Alıştırıp kendine,kokuna,tenine

Bırakıp gitme.

Ağlatma beni geceler boyu

Düşündürme üzme...

Sonra gelip sevindirip

Yine gitme...

Ya bırak beni acılarımla

Ya da yanımdan hiç ayrılma.

Ya sev beni durmadan bıkmadan

Ya da dokunma yaralarıma

Ya gelme bir daha 

Ya da gelince gitme...

22/08/05

veda', 'Bana bunu yapma!  Alıştırıp kendine,kokuna,tenine Bırakıp gitme. Ağlatma beni geceler boyu Düşündürme üzme... Sonra gelip sevindirip Yine gi...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sak']::text[], 8.5, '{"poet":"Reyhan Sak","poet_slug":"reyhan-sak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bana-bunu-yapma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Serseri', 'yeni-bir-serseri-hulya-ellikci-gw7fl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evet...

İşte sonuna geldik, gidiyorum

Her şeyimi yanıma alıp gidiyorum.

Ve bil ki unutmayacağım seni...

Ne seni unutacağım; 

Ne de yaşadıklarımızı...

Geriye dönüp baktığımda

Bir serseri vardı diycem

Adam gibi adamdı,

Ne ben ondan vazgeçebilirdim,

Ne de o benden...

Ama oldu işte

Şimdi ayrıdünyalara gidiyoruz. 

Seni, seni bulduğum yerde; 

Aşkımızın başladığı yerde bırakıyorum

Ben kendi dünyama dönüyorum

Kendime yeni dünyalar bulmaya gidiyorum

Ben yeni bir serseri bulmaya gidiyorum...', 'Evet... İşte sonuna geldik, gidiyorum Her şeyimi yanıma alıp gidiyorum. Ve bil ki unutmayacağım seni... Ne seni unutacağım;  Ne de yaşadıkla...', ARRAY['Türk Edebiyatı','Şiir','Hülya Ellikçi']::text[], 8.5, '{"poet":"Hülya Ellikçi","poet_slug":"hulya-ellikci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yeni-bir-serseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-mehmet-selim-bataroglu-kuf5k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bedenim ağır ruhuma, 

kanım dolaşmakta isyankar, 

taşıyamayacak kadar zayıfım artık kendimi habersiz 

ufukta sanki bir duman 

sanki birden belirecek umudun karartısı, 

belirecek mi? 

Çocukca sevinç çığlıklarım da olacak mı? 

Büyüyünce ölecek miyim yine? 

Yoruldum ölmekten, 

Arkamdan edilen dualar canımı yakıyor. 

Üşüyorum,

çok

üşüyorum...', 'Bedenim ağır ruhuma,  kanım dolaşmakta isyankar,  taşıyamayacak kadar zayıfım artık kendimi habersiz  ufukta sanki bir duman  sanki birden b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Bataroğlu']::text[], 8.5, '{"poet":"Mehmet Selim Bataroğlu","poet_slug":"mehmet-selim-bataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/usuyorum-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-harun-senel-9vcdc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şehir sıkar beni

Gitmek istesem de gitmek elimde değil

Acı hatıraları olduğu gibi

Tatlı hatıraları da oldu

Gidemiyorum işte

Ayaklarım yönlendiriyor

Kalbim asla diyor

Söküp atamıyorum bu kalbi

Gidemiyorum

Bu şehirde senin sesin,

Bu şehirde senin izin,

Bu şehirde senin kokun var

Mutluluğun kokusu var bu şehirde

Mutluluk senin kokunmuş bence

Bu şehrin ıslak caddelerinde dolaşırken

Seni,kokunu sokak sokak aradım

Geceleri sokak lambalarına sordum

Çisil çisil yağan yağmura sordum

Esen rüzgara,dökülen yaprağa sordum

Sonra anladımki

Ey gönül boşuna bu arayışın

Yar senin kalbinde

Ve ondan itibaren

Kalbimde taşıdım seni

Kalbimde sakladım seni

Dilimde sakladım seni

Konuşmadım kimseyle

İçimde sakladım seni

Kimseye içimi dökmedim

Ta ki sen gelinceye kadar dökmemde

Gelki gitmeyeyim bu şehirden

Gelki kalbim yoruldu artık

Gelki mutluluğun kokusu

Her tarafa bürünsün

Gelki ümit çiçeklerim solmasın

   mayıs 2004', 'Bu şehir sıkar beni Gitmek istesem de gitmek elimde değil Acı hatıraları olduğu gibi Tatlı hatıraları da oldu Gidemiyorum işte Ayaklarım yön...', ARRAY['Türk Edebiyatı','Şiir','Harun Şenel']::text[], 8.5, '{"poet":"Harun Şenel","poet_slug":"harun-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bu-sehir-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümsemek', 'gulumsemek-ufuk-bayraktar-6wpzq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her şey çocukluk düşlerinde mi kaldı; 

bütün heyecanlar...

dünyanın güzel renkleri hala duruyor da

biz büyüdük de

karalar mı bağladık gözbebeklerimize...

olmayacak şeyler düşlüyorum yine; 

seni düşünüyorum...

işte karşımda gizli kalmış tüm renkleri hayatın! 

gökkuşağının bittiği yerdeki hazineyi buldum gözlerinde,

sen her şeyimsin artık

anlıyor musun? 

bütün özlemlerim,

susamışlığımsın.

çoculuğuma dönmek istiyorum seninle

bütün yetişkinliğimle...

anımsamak istiyorum imkansız düşlerimi; 

gülümsemek; 

gülüm seni sevmek istiyorum doyasıya...', 'her şey çocukluk düşlerinde mi kaldı;  bütün heyecanlar... dünyanın güzel renkleri hala duruyor da biz büyüdük de karalar mı bağladık gözbeb...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gulumsemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Duvarı', 'dostluk-duvari-hulya-ellikci-31lmo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Böyle mi söz vermiştik birbirimize

Hani bir ömür boyu ayrılmayacaktık

Hani umutların sona erdiği yerde

Yeni umutlara yelken açacaktık...

Bu kadar zayıf mıydı arkadaşlığımız? 

Hani yıkılmaz bir duvardı bu? 

Kim derdi ki böyle bir duvar 

Küçük bir depremle yıkılacaktı? 

Birbirimizden bir şey saklamayacaktık 

Ama oluyordu bunlar

Bütün dostluklara oluyordu

Ama bu duvar yıkılırsa bir daha asla...

Hep paylaşırdık ya hani

Sevgililerimizi, aşklarımızı, yarınlarımızı...

Artık paylaşamayacağız bunları,çünkü; 

Bu duvar yıkılırsa bir daha asla...

Şimdi siz olmasanız da yanımda

Mazinin tozlu yapraklarında hep benimlesiniz.

Asla unutmayacağım bunları, çünkü; 

Bizim duvarımız yıkılmamalı...

Yeminler kaldı şimdi mazide

Yaşanmışlıklar kaldı orada

Uçamayacağız bir daha yarınlara

Duvarımız yerde, yaşlar gözlerimde...', 'Böyle mi söz vermiştik birbirimize Hani bir ömür boyu ayrılmayacaktık Hani umutların sona erdiği yerde Yeni umutlara yelken açacaktık... Bu ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Ellikçi']::text[], 8.5, '{"poet":"Hülya Ellikçi","poet_slug":"hulya-ellikci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dostluk-duvari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ''O'' Değilsin', 'sen-o-degilsin-halil-kesken-ugrfy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dediler gidip bak, kapın çalıyor

Tüm ömrünü senden çalan geliyor

Şimdi ne söylesen yalan geliyor

Sen aşkım dediğim kadın değilsin

Ciğer çalıp dönen kedigibisin

Kuyruğunu kısıp gelen sen misin? 

Hani çok sevdiğim, değer verdiğim

Sen aşkım dediğim kadın değilsin

Git geldiğin yere, bırak inadı

Artık sevda değil, sevdanın adı

Yakışmıyor sana melek kanadı

Sen aşkım dediğim kadın değilsin

Evimin önünden geçerken gördüm

Köşedeki barda içerken gördüm

Senin defterini ben çoktan dürdüm

Sen aşkım dediğim kadın değilsin

Yanağında açan pembe güllerdi

Yüzüme bakarken gözü gülerdi

Af değil, aşk değil, umut dilerdi

Sen aşkım dediğim kadın değilsin

Ben gönlümü onun ruhuna verdim

Bedeninden fazla huyunu sevdim

Ben tenine değil, kalbine derdim

Sen aşkım dediğim kadın değilsin

Nerden vardın bilmem sen bu kanıya

Boşyere güzelim bakma aynaya

Kızıl saç, yeşil göz hala aynı ya

Sen aşkım dediğim kadın değilsin', 'Dediler gidip bak, kapın çalıyor Tüm ömrünü senden çalan geliyor Şimdi ne söylesen yalan geliyor Sen aşkım dediğim kadın değilsin Ciğer çalı...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-o-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Defasında', 'her-defasinda-hulya-ellikci-juzly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnan denedim

Seni unutmaya çalıştım 

Ama başardığım tek şey 

Gururumu ayaklar altına almak oldu

Karşında, o masum bakışlarının karşısında

Kendimi unutmak oldu.

Ama elime hiç bir şey geçmedi.

her defasında sana koştum

Bir tutkuydun benim için

Asla yaklaşmamam gereken

Ben hiç uzaklaşamadım bu tutkudan

Ve bu tutku beni içine aldı

Bir daha kaçamadım kurtulamadım ondan

Her defasında yakaladın beni

Başkalarının oldun zaman zaman

Ama ben başkalarının olamadan

Tekrar döndün bana

Bense saf bir kız gibi

Hep oradaydım, beni aradığın yerde

Seni bekliyordum 

Her defasında ölüyordum...', 'İnan denedim Seni unutmaya çalıştım  Ama başardığım tek şey  Gururumu ayaklar altına almak oldu Karşında, o masum bakışlarının karşısında Ke...', ARRAY['Türk Edebiyatı','Şiir','Hülya Ellikçi']::text[], 8.5, '{"poet":"Hülya Ellikçi","poet_slug":"hulya-ellikci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/her-defasinda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderemediğim mektup-1', 'gonderemedigim-mektup-1-guler-atas-u6evq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GÖNDEREMEDİĞİM MEKTUP

                                                    CEMAL ATAŞ’A

Bir aydır uzaksın bizden. 

Uyuduğun yerleri bilsem 

ipek çarşaf sererdim yattığın yataklara. 

Canın acımasın isterdim. 

Acıyan yerlerime tuttum çıktığın yolculukları. 

Bulutlardaysan bir göz kırp yeter. 

Başım inmiyor yere. 

Gündüz güneşte gece ayda arıyorum yüzünü. 

Yıldızlardan göz yapıyorum; 

Gör diye beni.

Başımın üstündeysen uzat elini, 

Hissederim. 

Çocukluğuma dönerim böyle her gün. 

Her gün acır ikiz yanım.

Her gün gider beklerim bir cezaevi önünde. 

Öperim bütün tahliyecileri alınlarından, 

kardeşim kokar mı diye. 

Bilirim, aynıdır küf kokusu içerde. 

Belki sen kokar burnumda. 

Sana benzemez ya hiç kimsenin hasreti, 

Yine de ayaklarım götürür, 

gözlerim seçer mi siluetini bir görüş gününde diye.

Bir aydır haber yok senden.

 “Aşkııım” deyişini özledim, biliyorsun. 

Biliyorsun ki biz hep haber bekledik yıllarca. 

Her kapı vuruşuna çarptık yüreğimizi, 

Her telefona titredi sesimiz, 

Sessizce ağladık bütün faili meçhullere... 

Arşivler yaptık, çetele tuttuk kırkı aşan göz altılarına.

Kırkladılar seni canımın yarısı. 

Her girişin içeri bir yıl aldıysa senden 

Biliyorlardı ki kırkında susacak 

Kabına sığdıramadığın yüreğin.

Bana bir ses ver bu eylül. 

Eylüller sarıdır, hüzündür. 

Kasım patına gebedir eylüller 

Susuşudur  İnsan yanımızın.

Bir ses ver küçüğüm ve elini  ve yüreğini  ver 

Bu bahar seninle gideceğim 1 mayısa. 

Yeniden doğursun diye yattığın topraklar seni 

İnandığım bütün değerlerle yalvaracağım 

İçimdeki suskunluğa.

Uzun yolculuk diyorlar gittiğin yollara. 

Yanık bir türküymüşsün dilimde, 

sevdiğim ama korktuğum söylemekten.

Cemalım algınım yangınım.

Kıyamazsın bana dönersin, 

Yolculuk neki, 

İçimde bıraktım seni 

Damarlarımda kaldığın sürece 

Rahat uyu olduğun yerde, 

Birlikte götüreceğim seni bütün kavgalara, 

Bütün aşklara 

Tutup elini ellerimden 

Yarım bıraktığın her şeye vereceğim seni 

Tamamla diye.

.................................................

aşağıdaki ling''den slayt olarak indirebilirsiniz.

http://www.hemenpaylas.com/download/694209/gonderemedigim_mektuplar1....', 'GÖNDEREMEDİĞİM MEKTUP                                                     CEMAL ATAŞ’A Bir aydır uzaksın bizden.  Uyuduğun yerleri bilsem  i...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/gonderemedigim-mektup-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta gül bıraktım', 'dosta-gul-biraktim-mehmed-sahin-odyoq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir körpe goncasın kışıma geldin

Göklerde savaşırdım senin adına

Hangi bahire gitsen bulursun 

Senin için yelken açtım, savaş açtım

Nerdeydin

Her dağa seni anlattım

Güle sor bülbüle sor nerdeydim

Her dinde seni dua ile aradım

Bazen ayda bazen süreyyada

Nur çeşmesi nazarın aradım

Nerdeydin

Gökleri gezdim arşa çıktım

Levhü kalemde adın gördüm

Asude bir çiçek yazmışlar adın 

hakime Çöllerde seni bekledim

Neydeydin

Gözlerin şimdi hangi ülkede

Kimin şemsi kimin ayı

Kim görür gözlerinde öte seni

Saçlarına kim takar yıldızları

Nerdesin

Didelerin güle inat kızarırken

Göğsünde açan ayva ile narın

Ben büyüttüm sen uyurken

Şimdi ben oldum ağyar

Nerdesin', 'Bir körpe goncasın kışıma geldin Göklerde savaşırdım senin adına Hangi bahire gitsen bulursun  Senin için yelken açtım, savaş açtım Nerdeydi...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Sahin']::text[], 8.5, '{"poet":"Mehmed Sahin","poet_slug":"mehmed-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dosta-gul-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-hulya-ellikci-h7qho', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni kimsenin sevemeyeceği kadar

Kimsenin cesaret edemeyeceği kadar sevdim

Hak ettiğine inandığım için sevdim

Seveceğine inandığım için sevdim

Ama sen hiç sevmedin

Hak etmedin sevgimi

Ona değer vermedin

Onu umursamadın bile

Beni umursamadığın gibi

Ama ben yine de sevdim seni

Bekledim beni sevmeni

Beni seveceğin günü bekledim

O günün gelmeyeceğini bile bile...

Ben bekledim, sen gelmedin

Yine beklerim, inan bin yılda beklerim

Yeter ki bir gün geleceğini bileyim

Hiç bir şey acı vermiyor 

Ne beklemek ne de özlemek

Acı veren sonunu bilmeden beklemek

Kavuşacağını bilmeden özlemek

Bekleme desen bile

Kendimi tutamıyorum

Kahretsin ki seni unutamıyorum..

                                                               16.03.2004', 'Seni kimsenin sevemeyeceği kadar Kimsenin cesaret edemeyeceği kadar sevdim Hak ettiğine inandığım için sevdim Seveceğine inandığım için sevd...', ARRAY['Türk Edebiyatı','Şiir','Hülya Ellikçi']::text[], 8.5, '{"poet":"Hülya Ellikçi","poet_slug":"hulya-ellikci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdim-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firar ettim', 'firar-ettim-guler-atas-79uyj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapımı çaldığında o kış günü 

bir mahkumun günlüğünü tutmaktaydım, beş yıldır

ne güneşin farkındaydım, ne ayın

ne kendimi fark ediyordum aynalarda

ne insanların farkındaydım

önümden geçmişler, kapımdan geçmişler

aklımdan geçmemişler yıllardır.

ben, benim için sen gelene kadar

bir mahkumun günlüğüne düşmüş

notlardan ibarettim.

sabah dokuz işe gideceksin

gün içi fatura düşüneceksin

akşam dokuz eve döneceksin

ve yorgun bezgin, her hangi bir kağıda

bir günü daha unutmamak için 

notlar halinde düşeceksin.

kapımı çaldığında o kış günü

arkandaki kalabalığı gördüm

gözlerinden aynalara bakmayı öğrendim.

kendime güzel bakıyorum artık.

bir tünel kazdım,firar ettim

 o mahkumun günlüğündeki notlardan

kurtuluş sandım seni

karda üşümem yağmurda ıslanmam sandım.

sevindim,  özgürlüğüne kavuşmuş kuş gibi

oysa şimdi,  bir hayat hastalığına yakalandım

ne bir doktoru var reçete yazsın

ne bir hastahanesi var üç gün misafir etsin

ve anlıyorumki artık

sendende gitmeliyim.', 'Kapımı çaldığında o kış günü  bir mahkumun günlüğünü tutmaktaydım, beş yıldır ne güneşin farkındaydım, ne ayın ne kendimi fark ediyordum ayn...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/firar-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Ne Oldu Nasıl Oldu?', 'ne-oldu-nasil-oldu-songul-ucar-54pih', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevda sözcüğüydü,

Uçtu gönlüme kondu.

Erdemli bir yemindi,

Yürekte mühür oldu.

Arındı tüm kirlerden,

Akpak bir bebek gibi,

Doğdu bakir bir kucağa,

İlklerden çelenk oldu.

Ay doğdu,

Güneş battı...

Güneş doğdu,

Ay battı...

Saflığına taptığım,

Küçük bir kelebeğin,

Kanadında düş oldu...', 'Bir sevda sözcüğüydü, Uçtu gönlüme kondu. Erdemli bir yemindi, Yürekte mühür oldu. Arındı tüm kirlerden, Akpak bir bebek gibi, Doğdu bakir b...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-oldu-nasil-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göremedim gecede Dost', 'goremedim-gecede-dost-kerem-kayar-80gva', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söndü sokak lambaları, yandı mumlar 

Gece yarıları insan ürkek ve şaşkın 

Gönül anlamsız yere sözlere kırgın 

Şeytan beklemekte, bir günahın peşine 

Korkular ve ümitlere vurgun işte gece 

Mum ışığında çekilen anlamsız serseniş 

Dışarıda sabahın ezanı, kuşların müjdesi 

İşte insan, İşte insanın geceden alıntısı 

Virgül yok güne sadece merhaba; 

Güneş nereden doğacak habersiz yönde 

Başağında telin rüzgarın emrinde 

Esen rüzgarda güneşin habercisi, ışık esti 

Virgül yok güne sadece merhaba; 

İnsan mahur, kamaşmış istirahati biter göz 

Şimdi, yolu gözlenen güneş murada erer 

Hayır ola sevgilide uyanmıştır vakit 

Dönüyor kelebek gelincik köşegönder 

Çekil artık; 

Kara bulut yârim güneşi göster 

Korkarım geceden, korkutur ölümden 

Her yanımda isterim ki 

Üç beş mum olsun 

Mumdan kastım dost ola 

Göreyim her birini 

yönüne baktığım pencereden...', 'Söndü sokak lambaları, yandı mumlar  Gece yarıları insan ürkek ve şaşkın  Gönül anlamsız yere sözlere kırgın  Şeytan beklemekte, bir günahın...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/goremedim-gecede-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarkan Küpelim.', 'sarkan-kupelim-kadir-kaya-ry80l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allı, morlu sıra  sıra dizilir,

Süt beyaz gelinlik giymiş süzülür,

Bir gün konuşmasam inan  üzülür,

Sevgiyi yansıtan  fener küpelim.

Sevgiyle uyandım bir sabah erken,

Çiçeğime selam güzelim derken,

Sinekleri gördüm, yaprağı yerken,

Sana bakabilmek hüner küpelim.

İlaçladım, beyaz sinek ıslandı,

Bir daldan. bir dala geçti yaslandı,

Kanadını silkti, sonra süslendi,

Hüzünle, kedere banar küpelim.

Huzurumu bozdu, vaktimi çaldı,

Pencereden kovdum, kapıdan daldı,

Bire yüz yavruyu üstüme saldı,

Bin bir ızdırapla yanar küpelim.

Ziraatçı dostum İbrahim Kara,

Koştum sana geldim düşünce dara,

Küpelimin hali  yürekte yara,

İnşallah dertlerin diner küpelim.

Uzmanım anlardı çiçek dilinden

Küpelime ilaç verdi elinden,

Şükür ayırmadı beni gülümden,

Bakana teşekkür sunar küpelim.', 'Allı, morlu sıra  sıra dizilir, Süt beyaz gelinlik giymiş süzülür, Bir gün konuşmasam inan  üzülür, Sevgiyi yansıtan  fener küpelim. Sevgiyl...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sarkan-kupelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kare Kare', 'kare-kare-guler-ilgaz-lkgd1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Binbir çeşitliliğin

Binbir benzersizliğin

Binbir bilinmezliğin

İçinde gezindim.

Gittiiiim geldiiiim

Aldı beni götürdü

Kimbilir kaçıncı kez

..................................

Gözlerim sarhoş oldu

Benden önce

Unutmasın bedenim diye

Kattıkları anlamları

İçtim yuduuuum yuduuuum

Gözlerimi kapayarak

İçimde seyre daldım

..................................

Tadı damağımdayken

Bu kez dağıldı

Bedenimden içeri sarhoşluk

Sallandım sakraç gibi

Rüzgarla birlikte

Şarkı söyleyen bir dal gibi

Karıştım

Karmakarışık duyguların içine

Aradım

İçimdeki çeşitliliğin

Benzersizliğin

Bilinmezliğin seyrine daldım

.........................

Zengin mi zengin

Dünya mutfağı gibiydi

Dillere destan düğün gibiydi

Her baharda, kışta, yazda

Kendini sunan doğa gibiydi

Bir aşk filmi gibiydi yani

.....................................

Filmin içinde

Gitttiiim, geldiiiim

Rüya gibiydi, gerçek gibiydi

Anlayacağınız

Bir dile, söze, bakışa,

Dokunuşa, yalvarışa, haykırışa

Hasret herkes gibi

İçim geçivermişti ansızın

Ellerim anlatmak istedi

Sevgiye muhtaç herkes gibi

Paylaşmak istedi

BİR AN yani ŞU AN...

Yüreğim ellerimdeyken hala

Binbir çeşitliliğin büyüsü içimdeyken

Kare kare...', 'Binbir çeşitliliğin Binbir benzersizliğin Binbir bilinmezliğin İçinde gezindim. Gittiiiim geldiiiim Aldı beni götürdü Kimbilir kaçıncı kez ....', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kare-kare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rakı Şişesi', 'raki-sisesi-huseyin-gul-79ik5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'RAKI ŞİŞESİ

Sen rakı şişesinde balık

Orhan Velim

Ben bilemiyorum

Ne olacağım

Kardeşin olayım 

Bir yetmişlik şişede

Birimiz Ali

Birimiz Veli

Seninle Orhan Veli’m

Ve şiirle olmak

Ne güzel

Bir şişede ömür boyu

              Hüseyin Gül

'' Bu Kitabın Adı Yok '' Şiir kitabımdan', 'RAKI ŞİŞESİ Sen rakı şişesinde balık Orhan Velim Ben bilemiyorum Ne olacağım Kardeşin olayım  Bir yetmişlik şişede Birimiz Ali Birimiz Veli ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Gül']::text[], 8.5, '{"poet":"Hüseyin Gül","poet_slug":"huseyin-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/raki-sisesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksunluğun Şiiri', 'yoksunlugun-siiri-ufuk-bayraktar-n6bt6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'eylüle doğru yol alıyor zaman

sayılı bir kaç gün kaldı; 

senden bana hiç bir şey! 

oturmuş sahil kenarında bu akşam

denizin eylül sakinliğindeyim şimdiden; 

durulmuş delidalgaları samandağ''ın,

kalbimde inanılmaz bir acı; 

dayanılmaz bir çırpınış! 

rüzgarın savurduğu kum taneleri gibiyim

savruldukça seni buluyorum yeniden,

gidecek başka yerim yok; 

yine enginliğinde boğuluyorum! 

ayrılığın da sevdaya dahil olduğunu öğrendim şairden,

ya hiç kavuşamamak; 

o da dahil mi?', 'eylüle doğru yol alıyor zaman sayılı bir kaç gün kaldı;  senden bana hiç bir şey!  oturmuş sahil kenarında bu akşam denizin eylül sakinliğin...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yoksunlugun-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dünya Arıyorum', 'bir-dunya-ariyorum-huseyin-gul-w6omr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BİR DÜNYA ARIYORUM

Bir sevda arıyorum

Dengi dengine

Eli yaprak, kolu dal

Çiçeği bol olsun

Bir dost arıyorum

Eline, diline, beline

Kendini yorsun

Yüzünden değil

Özünden olsun

Bir yol arıyorum

Dur durak olmasın

Dağa taşa vurmasın

Hancısıyla, yolcusuyla

Hasretleri bir olsun

Bir dünya arıyorum

Gönül zenginliğine

Altı üstü bir 

İçi dolu gül olsun

                   Hüseyin Gül

'' Bu kitabın Adı Yok '' şiir kitabımdan', 'BİR DÜNYA ARIYORUM Bir sevda arıyorum Dengi dengine Eli yaprak, kolu dal Çiçeği bol olsun Bir dost arıyorum Eline, diline, beline Kendini yo...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Gül']::text[], 8.5, '{"poet":"Hüseyin Gül","poet_slug":"huseyin-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-dunya-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-fatih-akici-aqfkv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece gözlerden halvet, örtüdür günahlara

Gece sessiz bir rahmet örtülür günahlara', 'Gece gözlerden halvet, örtüdür günahlara Gece sessiz bir rahmet örtülür günahlara...', ARRAY['Türk Edebiyatı','Şiir','Fatih Akıcı']::text[], 8.5, '{"poet":"Fatih Akıcı","poet_slug":"fatih-akici","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gece-165-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalin', 'hayalin-oktay-akar-0e8xr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonsuzluğun içinde kaybolurken

Gözlerin,

Dönüp arkada bakmamı bekledim.

Saatlerce; 

Soğuktan dondu ellerim.

İstemedim, istemezdim de

O yağmurlu, o karanlık

O soğuk gecede

Yalnız kalmayı.

Belki ağladım saatlerce saatlerce.

Haberin olmadı hiç,

Gözyaşlarım düşerken yere.

Ellerim resminin üstünde 

Gezinirken,

Hissetmedin tenimi,

Belki; 

Aramadın bile

Sana dokunan ellerimi.

Gözlerini kaçırmıştın hep 

Son zamanlarda

Artık, gözlerimi tanımıyordu

Gözlerin

Ben yine aynı yerdeyim,

Aynı değilim belki,

Ama yine soğuktan donmuş ellerim,

Ararken ellerini.

Yine boşlukta kayboldu hayalin.', 'Sonsuzluğun içinde kaybolurken Gözlerin, Dönüp arkada bakmamı bekledim. Saatlerce;  Soğuktan dondu ellerim. İstemedim, istemezdim de O yağmu...', ARRAY['Türk Edebiyatı','Şiir','Oktay Akar']::text[], 8.5, '{"poet":"Oktay Akar","poet_slug":"oktay-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayalin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Mezar', 'yeni-mezar-yildiray-pilint-08fd6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Selvilerden bir ormanın içindeyim

Selvilerden ve soğuk mermerlerden

Taze kazılmış toprak kokusu

Hocanın yanık sesi karışmış havaya

Uzaktan uzağa ağlamalar sızlamalar

Cırcır böceklerinin sesine karışan 

Ter fışkırıyor koltuk altlarımdan

Bembeyaz çarşaflar içindesin

Yağmurlu bahar kokan bir gecede de

Giymiştin bu kıyafeti 

Gelinlik sana ne kadar yakıştı

Öyle demişlerdi o gece 

Kimse bilmesin ama 

Sarılıp sarmalandığın bu kefenlede

En az o kadar güzelsin.', 'Selvilerden bir ormanın içindeyim Selvilerden ve soğuk mermerlerden Taze kazılmış toprak kokusu Hocanın yanık sesi karışmış havaya Uzaktan u...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Pilint']::text[], 8.5, '{"poet":"Yıldıray Pilint","poet_slug":"yildiray-pilint","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yeni-mezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bir Gece', 'sensiz-bir-gece-i-lknur-er-howua', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz bir gece

Hep

Bir yanım eksik

Karanlıklar kaplamış yokluğunu

Kelimelerim yarım sensizlikte

Uzansam tutacaksın sanki

Tutunacağım sana

Oysa 

Yokluğun aklıma geldiğinde

Çıldırıyorum

Olmadığını bilmek ne acı

Sabahlar olmasın

Güneş

Sensizliğime doğmasın istiyorum

Sensiz gelen günden korkuyorum', 'Sensiz bir gece Hep Bir yanım eksik Karanlıklar kaplamış yokluğunu Kelimelerim yarım sensizlikte Uzansam tutacaksın sanki Tutunacağım sana O...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensiz-bir-gece-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerinde Aşk', 'ellerinde-ask-i-lknur-er-ish88', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gittiğin gün gibi

Yağmurlu bir kasım sabahında

Saçlarını

Arnavut kaldırımlarına savurarak

Geleceksin

Dudaklarında

Gittiğiğin günden kalan

Yarım cümleler, ellerinde aşk

Konuşmana izin vermeyeceğim

Geldin ya

Ne Önemi Var

Yokluğunda yazdığım şiirleri okuyacağım

Ürkerek

Tekrar gitmenden korkacağım

Dönmemenden

Oysa daha yeni geldin

Yinede saldın içime korkuları

Yağmurlu bir kasım sabahı

Temiz toprak kokusunu içine çekip

Ellerinde aşk

Kapımı çalacaksın

Yada ben hep

Bu umutla yaşayacağım', 'Gittiğin gün gibi Yağmurlu bir kasım sabahında Saçlarını Arnavut kaldırımlarına savurarak Geleceksin Dudaklarında Gittiğiğin günden kalan Ya...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ellerinde-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-i-lknur-er-g5wba', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk

En büyük Oyuncu

Tüm rolleri yakıştırırda kendine

Şöyle bir döner etrafında

Nerden gelmiş, nereye gidiyor

Anlayamazsın

En süslü kelimeleri takar takıştırır

Ayaklarını keser yerden

Kuşmusun be mübarek

Nasılda uçarsın

Kendini tanıyamazsın ya

Sen sen değilsindir artık

AŞK sındır

Tüm eksilerin üzerine bir çizgi

İşte nasılda güzelleşti hayat

Dertmiş, tasaymış aldırma geçer

Aşk var ya senin ya yeter

Ey aşk

Damarlarımda gezinirsin ya

Geçtiğin yerde izini bırakırsın

Toz duman edersin 

Varlığınla şad edersin ruhları

Keşke gitmelerinde olmasa

Yerini sevgiye bırakmasan

Aşk doğup

Aşk Kalsan

Aşk', 'Aşk En büyük Oyuncu Tüm rolleri yakıştırırda kendine Şöyle bir döner etrafında Nerden gelmiş, nereye gidiyor Anlayamazsın En süslü kelimeler...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aska-dair-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paris´te Geceydi', 'paris-te-geceydi-serhat-karadumanli-n9qmt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Paris'' te geceydi

Sokaklar cıvıl cıvıl,

Rengarenk neon lambalarıyla.

Gece boyu kaçak sevişmelerin yorgunluğu bedenimdeydi sevgililerin

Onlara hazzını bırakmıştım

Firuze renkli hedıye paketlerine sarılmış...

Paris''te geceydi

Ve ben bir otelin penceresinden seyrediyordum Sein'' i

Kapkaranlık bir odanın gözlerinden bakıyordum insanlara

Cebimde sahte bir pasaport

Yüreğimde tuz buz olmuş kristal hayaller,

Umudunu yitirmiş kuru güller...

Paris'' te geceydi

Orleans garı'' nda bir peronda yüklemiştim umutlarımı vagonlara

Nereye gideceklerini bilmeden

Öylesine rastgele

Ben ise başka bir peronda

Gelmeyecek bir treni bekliyordum...

Paris'' te geceydi

Bavulumda kaybedilmiş geçmişin ağırlığıyla

Bir çocuk suskunluğuyla

Alkışlarla kapanan perdenin gerisindeki

Palyaçonun gözyaşlarıyla

Sokak müzisyenlerini dinlıyordum...

Paris'' te geceydi

Ve ben kaybolmak istiyordum

Yağmur bulutlarına asılan öpücüklerinde

Yada

Notre-Dame köprüsünün üstünde

Sein'' in ışıltılı yakamozlarında...

(2005 agustos)', 'Paris'' te geceydi Sokaklar cıvıl cıvıl, Rengarenk neon lambalarıyla. Gece boyu kaçak sevişmelerin yorgunluğu bedenimdeydi sevgililerin Onlar...', ARRAY['Türk Edebiyatı','Şiir','Serhat Karadumanli']::text[], 8.5, '{"poet":"Serhat Karadumanli","poet_slug":"serhat-karadumanli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/paris-te-geceydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adak', 'adak-elazigli-mustafa-kaya-bahc2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'günahların sahibiyim

seni buldum

sen varsın şimdi 

zamanı durdurdum

sevgi yağmuruna tutuldum

bir anlık mıydı mutluluğum

hiç olmazsa

bir hatıra gülümse

gözlerinin renginden 

bir resmin olsun masamda

bir adak gibi diz çökeyim

diz çökeyim aşkın önünde…

                                              28.08.2005 / Çengelköy

                                                                Mustafa kaya', 'günahların sahibiyim seni buldum sen varsın şimdi  zamanı durdurdum sevgi yağmuruna tutuldum bir anlık mıydı mutluluğum hiç olmazsa bir hatı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma düşsen', 'aklima-dussen-elazigli-mustafa-kaya-hrvnf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne zaman aklıma düşsen,

bahçeye çıkıyorum.

sahile iniyorum.

ya,

renk renk çiçeklerdir sevdiğim,

ya da, yosun kokusu ve martılardır.

veya,

seni beni bağlayan şarkılardır

tekrarlayıp durduğum..

                                                  28.08.2005 / üsküdar

                                                  Mustafa kaya

www.mustafakaya.net', 'ne zaman aklıma düşsen, bahçeye çıkıyorum. sahile iniyorum. ya, renk renk çiçeklerdir sevdiğim, ya da, yosun kokusu ve martılardır. veya, se...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aklima-dussen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-guler-sarici-nwwvq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UNUTMAK

Mazi ellerimde bir kuş uçtu uçacak

Öyle unutacağım ki seni aklın duracak

Bir daha yok sana koşmak sarılmak

Bana düşen kaş çatıp, dudak büküp darılmak

Mazi ellerimde bir kuş uçtu uçuyor

Saçlarımda aklar eteklerime düşüyor

Seni unutmak istedikçe aklım şaşıyor

Bana sen değil seni unutmak düşüyor…

                                                    Güler Sarıcı', 'UNUTMAK Mazi ellerimde bir kuş uçtu uçacak Öyle unutacağım ki seni aklın duracak Bir daha yok sana koşmak sarılmak Bana düşen kaş çatıp, dud...', ARRAY['Türk Edebiyatı','Şiir','Güler Sarıcı']::text[], 8.5, '{"poet":"Güler Sarıcı","poet_slug":"guler-sarici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unutmak-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim insan', 'zalim-insan-elazigli-mustafa-kaya-nhzah', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'arşa çıkmayı denedi Haman 

yıkıldı kulesiyle 

yer ile yeksan

bir kahine kanıp kesti insanları

getiremedi güneşi firavun batıdan.

diriltmesi de yalan dı.

hadi batsın dı güneş doğudan.

ne firavun ne haman

doğru olmadılar hiçbirzaman

dün ne iseler bugünde

gerçeği saklayan...hakk  ı örten ...zalim insan...

                                                                   mustafa kaya

                                                                   28.08.2005 / eyüp

www.mustafakaya.net', 'arşa çıkmayı denedi Haman  yıkıldı kulesiyle  yer ile yeksan bir kahine kanıp kesti insanları getiremedi güneşi firavun batıdan. diriltmesi ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zalim-insan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş...', 'bos-zulfikar-yapar-kaleli-a5oc6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Arzular, istekler, hevesler bir bir,

Hayalin peşine takılır gider.

Dünya yarım temiz, iki kere kir,

Şöyle ervahına bakılır gider! !', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Arzular, istekler, hevesler bir bir, Hayalin peşine takılır gider. Dünya yarım temiz, iki...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bos-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı', 'ayni-fatma-caglayan-temzw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sağına bakıyorsun aynı şey 

Soluna bakıyorsun aynı 

Sen iyisi mi daima önüne bak 

Bakarsın değişir', 'Sağına bakıyorsun aynı şey  Soluna bakıyorsun aynı  Sen iyisi mi daima önüne bak  Bakarsın değişir...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayni-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Gömleklerime Mürekkep Damlamış', 'beyaz-gomleklerime-murekkep-damlamis-tunahan-ermihan-y0b1o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen susmuşsun mesela

Tüm kuşlar ölmüş

Sonbaharda gökyüzü yapayalnız

Göç alan her iklim sessiz

Kırık kanatlarında kalmış

Kuş cıvıltıları hatıralarımızın

Sen bana gözlerini yummuşsun mesela

Geceler çökmüş üzerine sokak çocuklarının

Ayı birileri sahiplenip perdelerini çekmiş

Güneşe nazar değmiş mum misali erimiş

Bir poşet balinin içindeki havai nefes gibi

Beynim kararmış umudum sönmüş

Sen koyu bir yalnızlığı seçmişsin mesela

Beyaz gömleklerime mürekkep damlamış

Masmavi gökyüzüme yağmur bulutları dolmuş

Deniz bile yalnızlığın kadar kararmış

Odamda yanan gece lambasının feri sönmüş

Karanlıkta kalan tüm yerlerimize hasretlik girmiş

Sen susmuşsun mesela

Tüm kuşlar ölmüş

Baharlar beni sen gibi terk eylemiş

Gözlerinde doğan her güneşim

Adını telaffuz etmeye çalışan

Kanadı kırık yüreğime

Kara saplı bir hançer misali batmış', 'Sen susmuşsun mesela Tüm kuşlar ölmüş Sonbaharda gökyüzü yapayalnız Göç alan her iklim sessiz Kırık kanatlarında kalmış Kuş cıvıltıları hatı...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beyaz-gomleklerime-murekkep-damlamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedensiz Çıkışlarım', 'nedensiz-cikislarim-avni-aydin-cq05z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nedensiz çıkışlarım oluyordu hayatımda...

saçma çıkışlarım, anlamsız kaçışlarım; 

anlamını bilmediğim iç çekişlerim oluyordu...

nerede, ne zamandaydı bilmiyorum...

nasıl usulca yanaşıp kulağıma sıcacık sesinle merhaba dedin? 

nasıl ürperdi içim? 

bi şekilde hayatın köşesinden tutunuyordum...

birden elimden o ince ip kaydı senle...

bocaladım...

neydi beni şaşkına çeviren? 

ne olabilirdi? 

çekim alanın benimkine yaklaşıyordu...

çaresiz etkileniyordu benim alanım senden...

vücudumda belli belirsiz...

ve yersiz kuvvet çizgileri oluşuyor..

beni sana çekiyor...

bırakmalımıyım kendimi bu kaynaga dogru 

ya da kaçmalı mıyım vakit varken? 

bilmiyorum...

ve ben hala sana yavaş yavaş kayıyorum...', 'nedensiz çıkışlarım oluyordu hayatımda... saçma çıkışlarım, anlamsız kaçışlarım;  anlamını bilmediğim iç çekişlerim oluyordu... nerede, ne z...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nedensiz-cikislarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan Gitmiştin', 'coktan-gitmistin-birsen-ates-zyljt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çoktan gitmiştin.

.

.

.

gider misin yüreğimden de 

usulca düşürdüm gözlerimden

aşkımı

sensiz gecelerimden

rüyalarımdan

gider misin yüreğimden de 

içimi acıtan düş kırıkların

gerçekle hayal arası

sessizlik

boşluk

dolmuyor

tükendim.

intiharında kelimelerin

martılarda gelmiyor artık

mavilerde küsmüş

artık,

korkmuyorum

karanlıklardan

inatla yürüyorum 

olsun

çıkarım bu karmaşadan

ölüme bile giderim

yüzün ruhuma sarılmasa', 'çoktan gitmiştin. . . . gider misin yüreğimden de  usulca düşürdüm gözlerimden aşkımı sensiz gecelerimden rüyalarımdan gider misin yüreğimde...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/coktan-gitmistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraf', 'fotograf-mehmet-yasar-a-6l6sm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'onları yok sayma ya da gittiler

belki sisler arasında beklemekteler

nice anılar var ki yaşamamışız

biz doğmadan önceydiler

bak işte karşında bir çerçeve

konuş, korkma seni dinlemekteler

gülümse, gökyüzü ağarsın gözlerinde

ne de mahzun görünmekteler

gülümse, gün gelir

gelebilirler.', 'onları yok sayma ya da gittiler belki sisler arasında beklemekteler nice anılar var ki yaşamamışız biz doğmadan önceydiler bak işte karşında...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yaşar A']::text[], 8.5, '{"poet":"Mehmet Yaşar A","poet_slug":"mehmet-yasar-a","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/fotograf-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim', 'mevsim-fatma-caglayan-jy84b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimler gibisiniz 

Bazen ilkbahar, bazen yaz 

Aniden olmuşsunuz 

Sonbahar, kış 

Ve ben bunları, sizlerle yaşıyor 

Hasta oluyorum', 'Mevsimler gibisiniz  Bazen ilkbahar, bazen yaz  Aniden olmuşsunuz  Sonbahar, kış  Ve ben bunları, sizlerle yaşıyor  Hasta oluyorum...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mevsim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıprandım', 'yiprandim-mikdat-bal-ww025', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baş eğmedim bu güne dek bir kula

Zaman beni eğdi büktü, bitirdi

Yıprandım satsalar gitmem bir pula

Bu mağrur kul kıymetini yitirdi

Dağlar yıkılırdı, çektiklerimden

Ah ederim sızlarım kederimdem

Şikayetim vardır  birkaç yerimden 

Doğduğuma beni pişman ettirdi

Hastalıktan zor işten sakınmazdım

Çalışırdım doktora bakınmazdım

Ufak tefek bir şeyden yakınmazdım

Zaman duman etti, aman dedirtti

Bal der ben eskiden, çok gencim derdim

Canımın istediğini ederdim

Nerde şenlik ben oraya giderdim

Bu gaflet başıma neler getirdi', 'Baş eğmedim bu güne dek bir kula Zaman beni eğdi büktü, bitirdi Yıprandım satsalar gitmem bir pula Bu mağrur kul kıymetini yitirdi Dağlar yı...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yiprandim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki tanrı da ağlar', 'belki-tanri-da-aglar-mehmet-yasar-a-gjdt3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hafif ve doğal görünümlü keder

dağda zeytin toplayan Çineli bir kadının

parmak uçlarından yüreğine

kanatırcasına ilerler

güneş dağın arkasında kırmızı

yangınlar yaratır, bizi terk eder

kentin dar sokaklarında iri göz bebekleri

ölü çocuklar

anneler, binip acının gemilerine

ağlamaz, sessizce çekilirler

kimsenin bilmediği dehlizlerine

belki tanrı gökyüzünde 

sert bakışlarla, ölü çocuklar

kirpikleri uzun gösteren maskara

			

birkaç kişi yürür mezarlığa kederli ama yaşsız                             

belki ben de büyürüm

bakıp da ölü çocuklara.', 'hafif ve doğal görünümlü keder dağda zeytin toplayan Çineli bir kadının parmak uçlarından yüreğine kanatırcasına ilerler güneş dağın arkasın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yaşar A']::text[], 8.5, '{"poet":"Mehmet Yaşar A","poet_slug":"mehmet-yasar-a","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/belki-tanri-da-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda Yolculuk', 'umuda-yolculuk-fatma-caglayan-iyafq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir garip trenim ben 

Sıkıntı durağından başlar yolculuğum 

İlerlerim yavaş yavaş… 

Dururum dertliler durağında 

Bir bir yüklenirim bütün dertleri… 

Varırım her şey bomboş durağına 

Bakarım etrafıma 

Her şey gerçekten bomboş… 

İlerlerim yavaş yavaş 

Gelirim huzursuzlar durağına 

Bakınırım sağıma bir de soluma 

Huzursuzluk dolar içim baştan ayağa 

Gelirim ağlayanlar durağına 

Ağlayan ağlayana… 

Son durak umutsuzluk 

Ama duramam 

Geçerim umursamadan 

Umutsuz bakışların 

O mutsuz durağından…', 'Bir garip trenim ben  Sıkıntı durağından başlar yolculuğum  İlerlerim yavaş yavaş…  Dururum dertliler durağında  Bir bir yüklenirim bütün de...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umuda-yolculuk-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Es', 'es-meral-vurgun-w5pdv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hangi dağdan esersin ey deli rüzgar

fırtına ol da gel

es savur beni

es ve del geç bedenimi

iç içe geçen gölgeler gibi

sar ruhunu ruhuma

es deli rüzgar

es süpür bu kirli yapışkanlığını dünyanın

es süpür tatlı dilinin kelamıyla

söylenmemiş sözler söyle

söyle ne söyleyeceksen

nasıl söyleyeceksen

es de yak bakalım 

ne kadar ateş olur cürmüm sana

ey deli rüzgar

bir ferman çıkar hükmüne yasakların

gökten mi yağar bu tabu sağanakları

al yüreğimi avuçlarına

bak içine

ne bir zerre duman izi

ne İblis’in kalesi

es deli rüzgar

es geç

savur beni düşler ülkesine

bir parça Ilgaz’ın boranı

bir parça Munzur’un isyanı

ille de hırçın dalgaları Karadeniz’in

seni görüyorum

bak aynamda gökyüzü

bak 

gözlerine bak çocukların

toplamış çölleri dağlara yaslamış

kirpiği kaşı sevda pınarı

es deli rüzgar

gece yarıları devrilirken sabaha

gel yokla sol yanımı

bilirsin bekler seni o dağların maralı

şimdi hoşum ve sen varsın

sen varsın içinde derimin

gözlerimin

yani sen

arama seni sende 

sen ben’im

bana dairsin sen

tam şuramda sakladığım küheylan

es deli deli

sana kim benden başka deli derse desin 

bilmez

bilemez seni benim kadar 

es deli deli

kırmadan yelkenleri

kırmadan fora et 

zulana al 

alda beni gidelim

uçalım evrenin derinlerine 

bak senin için yaktım bu elleri...', 'hangi dağdan esersin ey deli rüzgar fırtına ol da gel es savur beni es ve del geç bedenimi iç içe geçen gölgeler gibi sar ruhunu ruhuma es d...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/es-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende mevsim hep hazan', 'bende-mevsim-hep-hazan-nizami-sunguroglu-8eexc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ak dolan saçlarımda 

Taze bahar arama

Rüzgarlar nazar eder

Saçlarını tarama

Bende  mevsim hep hazan

Sende ise hep bahar

Gamlandı bak yüreğim

Bul kendine yeni yar

Yüreğin kıpır kıpır

Ne dikeni görürsün 

Ne güldeki lekeyi

Hep eser kavak yeli

Hep yaşarsın neşeyi

Çıktığım merdiven bu

Saymadım kaç basamak

Belki bir kaçı kaldı

Belki de son sağanak

Ne bakarsın gözüme

Perçem düşmüş yüzüne

Vaz geç sen bu sevdadan

davul bile dengine...

Nizami  Sunguroğlu

18/07/2005

Hollanda', 'Ak dolan saçlarımda  Taze bahar arama Rüzgarlar nazar eder Saçlarını tarama Bende  mevsim hep hazan Sende ise hep bahar Gamlandı bak yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Nizami Sunguroğlu']::text[], 8.5, '{"poet":"Nizami Sunguroğlu","poet_slug":"nizami-sunguroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bende-mevsim-hep-hazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aşkın Adı Başka', 'bu-askin-adi-baska-zafer-sik-11drs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben hiç büyümedim anne 

gözlerim büyüdü, çizgilerim büyüdü 

melekler sağanak sağanak inerken  bahçemize 

ellerim büyüdü 

ellerim ve hayâllerim… 

Nerde kaldı cennetin ölümsüz sabahları 

sen nerde kaldın anne? 

avuçlarımda sıcak bir duâ ve pamuk şekeri 

gülmelerin tadı başka 

rengi başkadır ağlamaların senin şefkatli tokadında 

cennet renkli yüzünü göster bana 

bak büyüdü ellerim anne 

çamurlu sokaklarda büyüdü ayaklarım 

gözlerim büyüdü 

ben büyüdüm anne, kar beyazı duâlarınla 

Bugün top oynarken arka mahallede 

yine kirlettim tişörtümü, şortumu 

sakın amcama söyleme 

içimden Kara Kartal’ı tuttuğumu. 

ıslak gözlerini sil anne 

inan, büyüdüm bak 

artık dar geliyor bana 25 numaralı ayakkabım 

Gece, karabasanlar çöreklendi üstüme 

çok korktum anne 

bağırmak istedim

sana sarılmak istedim ama 

uzattığımda ellerimi, sen yine yoktun 

off! yine ellerin kanayacak portakal bahçelerinde 

sen aldırmasan da buna 

çok acıyacak biliyorum 

Ben büyüdüm anne 

bak ellerim de büyüdü 

bundan sonra her okul sonrası 

çarşıda/pazarda ayakkabı boyarım 

bakkal amcaya yardım eder, simit satarım 

evin erkeği ben değil miyim 

sen evde oturacak, ben çalışacağım 

artık limonlu dondurma için ağlamam, söz. 

ağlamam anne, sen ağlamadıkça. 

sabah gözlerimi açtığımda 

senin kucağında uyanmak istiyorum

karabasanlar annelerden korkar değil mi? 

‘Baban, uzaklara çok uzaklara gitti 

bize daha güzel yer bulmak için 

başka diyarlara gitti’ demiştin ya 

gidenler bir daha geri gelmez mi? 

uzaklar neden hiç bitmiyor anne 

geçenlerde arkadaşım Ali’nin babası İstanbul’a gitmiş 

iki gün sonra geri dönmüş 

ama dönerken de güzel mi güzel 

kırmızı bir araba getirmiş ona 

anne, İstanbul uzak mı bizim memlekete? 

ben oyuncak istemem anne 

babam dönsün yeter 

zaten bir çocuğa en güzel hediye 

anne-babasının yanında olması değil mi? 

Bak anne, şu benim beşiğim 

şu ayakkabım, hem de 26 numara 

onlar da oyuncaklarım

burası kocaman oyuncak bahçesi, görüyor musun? 

ne olur artık ağlama

gözyaşı yakışmıyor sevgi taşıyan gözlerine 

hadi git, bak akşam oldu

beni hiç merak etme 

keyfim yerinde 

ama yarın yine gelirsin değil mi? 

kuştüylü kalbinle sev beni olur mu 

ben hiç büyümedim anne, ben ölmedim 

ben cennetin ''yeşil kuş’uyum anne

Anne görüyor musun

ben ölmedim

ben büyümedim anne.', 'Ben hiç büyümedim anne  gözlerim büyüdü, çizgilerim büyüdü  melekler sağanak sağanak inerken  bahçemize  ellerim büyüdü  ellerim ve hayâller...', ARRAY['Türk Edebiyatı','Şiir','Zafer Şık']::text[], 8.5, '{"poet":"Zafer Şık","poet_slug":"zafer-sik","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/bu-askin-adi-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Tensiz Bir Dokunuş**', 'tensiz-bir-dokunus-hulya-simsek-0nslt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I.

Tutunamadı Aşk,

Bakire Meryem’in rahminde

Düş-tü.

Kendi ilahisini okurken çatladı kabuk

Kim bilir kaç kez kendini doğurdu

Bir mabet daha gömüldü

aşkın bağrına

Çığlık çığlık…

II.

Tüyden göğünü serdi tanrıça

Argos ’un gözleriyle bezeli

Peçesini takındı Hera.

Bir tanrıyı daha vurdular

Aşk uğruna…

III.

“Bir varmış bir yokmuş..”

diye başlayan düşümde

Aşk nedir? dedi çocuk

IV.

Divan altlarında aradı aşkı

Göğe bakıp tanrıyı…

Bulamadı.

Tensiz bir dokunuşu vardı

Aşkın ve tanrının

Cisme sığmadı

V.

Gecenin dilsiz uğultusu…

Kanına karışan korku…

Pencerelerden sızan

Bebek ağlayışı sanırdı

Rüzgârı..

Açılsa gözleri

Gölgeler değecekti alnına

Artardı yalın yüreğin seğirmesi…

Sonra dil/l/enirdi 

Tanrı aşkına ettiği dua…

VI.

Bir gün…

Leylili bir kadın geçti

Yaz bahçesinden

Ardında hanımeli kokusu…

Bakışları uzandı çocuğun

Sonra uzadı uzadı…

Aşk sanrıları…

VII.

Anları çoğaldıkça büyüdü çocuk

Öğrendi zamanla

Herkesten fazla yalnız değildi

Herkes kadar alıştı

Hüzne ve acıya…

VIII.

İstediği her an gebe kaldı

Kafatasından doğurdu tanrıçayı

Aşk, tensiz bir dokunuştu.', 'I. Tutunamadı Aşk, Bakire Meryem’in rahminde Düş-tü. Kendi ilahisini okurken çatladı kabuk Kim bilir kaç kez kendini doğurdu Bir mabet daha ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/tensiz-bir-dokunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Aşkım', 'yaz-askim-burhanettin-akdag-ki07v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine bir yaz akşamındayım

Sahilde, seni bekliyorum aşkım

Her zamanki yerimizde, kumsalda

Gözlerim takılmış gurubun kızıllığına

Seni arıyorum mahzun günbatımında

Sanki almış götürüyor seni benden

Tam bir yıl geçmiş aradan aşkım

Yaz sıcağıyla alev alev duygularım

Ama gel gör ki durmamışsın sözünde

Hayaline bile razıyım oysa ki

Değil seni görmek 

Eline dokunmak

Veyahut ta sesini duymak

Razıydım...

Yaz aşkı diyorlar ya adına

Sözleşmiştik oysa ''seneye'' diyerek

Tutmadın sözünü aşkım

Öksüz bıraktın denizi, ellerimi

Gözlerime ihanet ediyor ufuklar

Denizin mavisi bile kar etmiyor

Durgunum, duygusuzum

Aldattın beynimi aşkım

Yıktın hayallerimi

Okyanusa gömdün sevgimi...

Nerede uzun saçlı kız görsem

Kolundan tutup bakar olmuşum

Sonrasında peşpeşe özürler, ''afedersin'' ler

Şaşırmış haldeyim, neden burdayım? 

Neden yoksun, niye gelmedin aşkım? 

Yok oluyor umutlarım, yavaş yavaş...

Bir gemi geçiyor bu arada açıktan

Hüznüme ayak uydurarak yarıyor suları

Sessiz, ağır ağır, yarım yol

Seni ve hayallerimi almış güvertesine

Gidiyor uzaklara 

Geri gelmemecesine bir daha

Sonsuza dek belki de

Beni anılarımla başbaşa bırakıp

Uzaklaşıyor benden ''sen''

Uzaklaşıyor, uzaklaşıyor

Kayboluyorsun hayal ufkumdan

Gidiyorsun...

(28.08.2005)', 'Yine bir yaz akşamındayım Sahilde, seni bekliyorum aşkım Her zamanki yerimizde, kumsalda Gözlerim takılmış gurubun kızıllığına Seni arıyorum...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yaz-askim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Virgül yerine noktasal hayalete mahsus, köprü maruz olunma''nın; bir kerelik bir ''sen'' ve ''ben''', 'virgul-yerine-noktasal-hayalete-mahsus-kopru-maruz-olunma-nin-bir-kerelik-bir-sen-ve-ben-akin-akca-9bq0w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'i.

Tuhafça onu doğuruyor şiir.

Halbuki sana eziyet etmiş o,

onu yıktın işte buraya yine.

Bunun için danıştın sanki kim''e? * 

Ne kendine, ne bana.*

Sadece patinaj yapan 

yağmurun suyuna,

değil aşkın alev kırmızısına.

Sevgiye de değil. Çünkü

saf su değil, yağmur suyu.

Yine de tüm sular akıyor,

aşağıda bir kuyu.

Topluyor bizi allahtan,

kova kova çıkacağız 

daracık şu maşrapadan.

ii.

Ne kendine, ne de bana:

Demek geliyor içimden; 

bu, ateş gibidir, suyun yanı sıra.

Çünkü sen danışsan sana, bana:

“Biz” uzaklaştırmadan ‘biz’i; 

gideceğiz sen yerine “Biz” uzağa.

*

Çok karışık bir olgu bir seferlik,

aldığında eline sağlığını senin; 

savunabilecek misin, 

yaşayabilecek misin …

Cılız iletişimde, gerekli mi ağlamak:

şaşkın güvercinin paytak gözlerinde; 

gece, kanatları arasında 

uyumaya uğraşan kuğunun.

buhranın şenliğe açı 

habise-katran cahil kevgirdir zaten

kendinden zaruri.

sorsan...

-

habise-katran: iyi huycul', 'i. Tuhafça onu doğuruyor şiir. Halbuki sana eziyet etmiş o, onu yıktın işte buraya yine. Bunun için danıştın sanki kim''e? *  Ne kendine, ne ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/virgul-yerine-noktasal-hayalete-mahsus-kopru-maruz-olunma-nin-bir-kerelik-bir-sen-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben insan', 'ben-insan-elazigli-mustafa-kaya-buukn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben sonsuzdum,

sonlu olmayı ben istedim.

ben ölümsüzdüm,

ölenleri gömerdim. 

barış,sevgi,mutluluk yurdunu ben çiğnedim

pusular kurmayı, 

kan dökmeyi ben öğrendim..

Kabil  oldum

Neron''da oldum

Nemrut''da

ve lanetlendim yıllarca..

Habil olmak vardı,

temiz

masum ve insanca

müslümanca...

                                                                               28.08.2005 / eyüp

                                                                                  Mustafa kaya

Www.mustafakaya.net', 'ben sonsuzdum, sonlu olmayı ben istedim. ben ölümsüzdüm, ölenleri gömerdim.  barış,sevgi,mutluluk yurdunu ben çiğnedim pusular kurmayı,  kan...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KADIN ve ÇOCUK', 'kadin-ve-cocuk-nilgun-akcay-q7c7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar Önce..

Bir kadın varmış

Çaresiz,yapayalnız…

Yaşanmamışlarını

Yaşanmışlarını sorgulayan

Keşkeleriyle savaşan

Bir kadın.

Her nedense ölüme aşıkmış ölesiye

Yaşam Senfonisi çalarken

Hep dans edermiş Ölümle.

Şiirler yazarmış ölüm üzerine,

Çağırırmış onu gündüz gece.

Ve Bir gün…

Biri gelmiş aniden.

Adı yokmuş bilinen.

Kadın, “ÇOCUK” demiş ona.

Ve Çocuk…

Işık olmuş karanlığına,

Dost olmuş yalnızlığına,

Yıkmış keşkelerini birer birer,

Susmuş Ölüm haykıran dizeler.

Ama Bir gün..

“Çocuk” geldiği gibi

Sessiz ve zamansız gitmiş uzaklara.

Ve Kadın…

Son şiirini yazmış gözyaşlarıyla,

Gömmüş ruhunun karanlıklarına.

Hep beklermiş O günden beri.

“Çocuk” Gelir diye belki..

Ve “Çocuk” çıkagelmiş aniden.

Kadın şaşkın sevincinden

“Çocuk” ise hüzünlü ve kaygılı

Konuşmuşlar eskiden,yeniden

Akıtmışlar Hayat Okyanusuna

Acılarını,Umutsuzluklarını

Nefretlerini damla damla.

Bitmiş kelimeler..

Kırılmış kum saati..Dolmuş zaman.

Ve Sonra..

Kadınla Çocuk elele

Yelken açmışlar BİLİNMEYEN’e..', 'Yıllar Önce.. Bir kadın varmış Çaresiz,yapayalnız… Yaşanmamışlarını Yaşanmışlarını sorgulayan Keşkeleriyle savaşan Bir kadın. Her nedense öl...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kadin-ve-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Policy of Truth', 'policy-of-truth-akin-akca-jacuf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'The Policy Of Truth

Depeche Mode

You had something to hide

Saklanmak için bir şeyin var

Should have hidden it, shouldn''t you

Saklamışsın, yapmamalı mısın? 

Now you''re not satisfied

Şimdi, tatmin olmadın

With what you''re being put through

İçinden doğru koyulduğun ile.

It''s just time to pay the price

Bedel ödemenin tam zamanı şimdi

For not listening to advice

Tavsiye dinlememek için

And deciding in your youth

Ve karar vermek için senin gençliğinde

On the policy of truth

Doğruluk politikasına dayanan.

Things could be so different now

Şeyler, çok değişik olabilir şimdi

It used to be so civilised

Çok uygar olurdu.

You will always wonder how

Her zaman, nasıl olduğunu merak edeceksin

It could have been if you''d only lied

Sadece uzanmışlarında gerçekleşebilirdi.

It''s too late to change events

Olayları değiştirmek için çok geç.

It''s time to face the consequence

Sonuçla yüzleşmek zamanı şimdi

For delivering the prof

Kanıtı iletmek için,

In the policy of truth

Doğruluk politikasında! 

Never again

Asla bir daha.

Is what you swore

Yemin ettiğindi

The time before

Önceki zaman.

Never again

Bir daha asla

Is what you swore

Yemin ettiğindi

The time before

Önceki zaman

Now you''re standing there tongue tied

Şindi orada duruyorsun dili-bağlı

You''d better learn your lesson well

Dersini öğrensen (daha)   iyi olur

Hide what you have to hide

Sakla, saklaman gerekeni sakla

And tell what you have to tell

Ve söyle, her ne söylemen gerekiyorsa! 

You''ll see your problems multiplied

Göreceksin, sorunların katlandı; 

If you continually decide

Eğer devamlıca karar verir isen.

To faithfully pursue

Sadık bir biçimde tekibetmek için

The policy of truth

Doğruluk politikasında

Never again...

Asla bir daha …

From: [email protected]

Çeviri, akın akça', 'The Policy Of Truth Depeche Mode You had something to hide Saklanmak için bir şeyin var Should have hidden it, shouldn''t you Saklamışsın, ya...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/policy-of-truth-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Valsına erdi gönül', 'valsina-erdi-gonul-ali-riza-unal-a7vx8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doyulurmu şêvkîne yarîn, biçilmez paha

Yandı firak-ı narâ,yandıda uslandı gönül

Meylim saldım varlığa, dönmem zar-ı aha

Görmez oldu basiret,yad-ele puslandı gönül

Bir garip cuş-oldum, bir meşk daha bir  daha

Boyandı visâli varın rengine,yaslandı gönül

Aymayım  bu nuş-u hazza, tükendi çöl ile vaha

Hayeli serâp şimdi hakikât, valsına erdi gönül

----lügât   ----------------

şevk        :bir şeyi şiddetle yapma isteği bir şeye çok neş-e ve

istekle ulaşma arzusu

Meşk      :muhabbet*  seven ve sevilenin bir arada halvetiyalnız

Olduğu zaman yapılan aşk sohbeti muhabbeti*dem.

Firak   :  ayrılık.

Nar       :ateş.

Nuş      : manevi şarhoşluk

Cuş      : coşku taşmak şiddetli coşku hali.

Visâl      :sevdiğine ulaşma onun ile hemdem olma

Valsına ermek:   vuslat buluşma mahremiyetin ortadan kalkışı

Serâp     : çok sıcakta çölde  şiddetli susuzluk anında su ve yeşillik

Görmek hayelin bir değişik çeşidi.

Paha    : değer bir şeyin ücret veya mal karşılığı..

Vaha      :çöl ortasında yeşilliği ve suyu olan yer

Basiret  :üstün görüş hikmetli bakış aklı selim zekâ.

Puslandı gönül :net;  duru olumlu dengeli anlayışın gitmesi.', 'Doyulurmu şêvkîne yarîn, biçilmez paha Yandı firak-ı narâ,yandıda uslandı gönül Meylim saldım varlığa, dönmem zar-ı aha Görmez oldu basiret,...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/valsina-erdi-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı evlatmış', 'adi-evlatmis-meryem-i-sler-gejnc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varlığına bir değer biçemedim

Bu candan da öte bir sevgi dedim

Adına söylenecek sözü seçemedim

Ben böyle bir servet ömrümce görmedim

Dünya bir yana siz bir yana 

Aşkınızdan  ölünür binlerce defa

Günüm güneşim soluk kalır yanınızda

Evladın yerini hiç birşey tutamaz asla

Siz  yokken ben ruhsuz bir bedenmişim

Anladımki canıma can veren sizlersiniz

Bana yaşmanın anlamını öğrettiniz

Benim için siz canımdan da kıymetlisiniz

Gözümden bile sakınırım sizi

Kanatlarımın altında saklarım kuş gibi

Dünyayı taşırım sırtımda yinede ezdirmem sizi

gözümün nurusunuz ciğerimin nefesi

Şu emanet canım feda olsun size

Saçınızın  bir telini degişmem hiç bir şeye

Annen derki evlat sevgisi bambaşka

Benzemiyor asla hiç bir aşka', 'Varlığına bir değer biçemedim Bu candan da öte bir sevgi dedim Adına söylenecek sözü seçemedim Ben böyle bir servet ömrümce görmedim Dünya b...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adi-evlatmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzyılın Mecnunu', 'yuzyilin-mecnunu-sahin-erturk-2ikqf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya bir manyağım,ya sevmeyi bilen

Bir ölüye şiirler yazıyorum

Bir ölüyle hala dolaşıyorum

Manyağın tekimi,aşkı bilen mi? 

Yoksa yüzyılın,Mecnun u benmiyim? 

(28.08.2005-Yeni)', 'Ya bir manyağım,ya sevmeyi bilen Bir ölüye şiirler yazıyorum Bir ölüyle hala dolaşıyorum Manyağın tekimi,aşkı bilen mi?  Yoksa yüzyılın,Mecn...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yuzyilin-mecnunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Sana Kaydı', 'kalbim-sana-kaydi-sahin-erturk-tjp9s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün yaşadım büyük deprem

Düşünmekten oldum verem

ASLI sensin,benim KEREM

Kalbim sana kaydı SİBEL

Uzun zaman direnmişti

Senden önce güvendeydi

Kimse kolay girmemişti

Kalbim sana kaydı SİBEL

On sekizlik heyacanım

Şiirlere ilhamımsın

Bugünümsün,yarınımsın

Kalbim sana kaydı SİBEL

Kaydı Sibel sana kaydı

Duygularım sana kaydı

Şiirlerim sana kaydı

Kalbim sana kaydı SİBEL

(28.08.2005)', 'Dün yaşadım büyük deprem Düşünmekten oldum verem ASLI sensin,benim KEREM Kalbim sana kaydı SİBEL Uzun zaman direnmişti Senden önce güvendeyd...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalbim-sana-kaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİRAC (Lâ İlâhe İllellah)', 'mi-rac-l-i-l-he-i-llellah-ramazan-ece-bkaz1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylardan  Recep  idi

Muhammed Haremdeydi

Melek  yanına  geldi

Göğsünü feth eyledi

(Lâ İlâhe İllellah Muhammed Rasulüllah) 

İlim  hikmet  edindi

Sübhânellezi  esrâ

İlâhi emir  geldi

Miraç mucize büşrâ

(Lâ İlâhe İllellah Muhammed Rasulüllah) 

Büraka ‘Ruh’ bindirdi                                        

Mescid Aksa’ya indi

Rusüle  İmam  oldu

Sevgi hürmeti buldu

(Lâ İlâhe İllellah Muhammed Rasulüllah) 

Resul Aksadan çıktı

Miracına  başladı

‘Ruh’la göklere çıktı

Kab-ı Kavseyne vardı

(Lâ İlâhe İllellah Muhammed Rasulüllah) 

Yüce Rab huzuruna

Mazhar oldu lutfuna

Görüştü mevlâsıyla

Konuştu Hak zatıyla

(Lâ İlâhe İllellah Muhammed Rasulüllah) 

Miraçtan Resul döndü

Bir Âmenerrasulü

Beş namaz ve tahyeti

Ümmete hedye etti

(Lâ İlâhe İllellah Muhammed Rasulüllah)  

Miracın sabahında

Anlattı ashabına

Mümin sevip inandı

Kâfir, münâfık azdı

(Lâ İlâhe İllellah Muhammed Rasulüllah)  

‘ECE’ der ey Peygamber! 

Ümmete sensin önder

Mahşerde sen et mehder

Selâm sana ey Rehber! 

(Lâ İlâhe İllellah Muhammed Rasulüllah) 

     Ramazan Ece  Danimarka/Odense', 'Aylardan  Recep  idi Muhammed Haremdeydi Melek  yanına  geldi Göğsünü feth eyledi (Lâ İlâhe İllellah Muhammed Rasulüllah)  İlim  hikmet  edi...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ece']::text[], 8.5, '{"poet":"Ramazan Ece","poet_slug":"ramazan-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mirac-la-ilahe-illellah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadım', 'olmadim-sahin-erturk-zz5iv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Olmadım hiç aşk tan kaçan

Olmadım hiç aşka küsen

Seven kalbe hasar veren

Olmadım güzel olmadım

(28.08.2005-Yeni)', 'Olmadım hiç aşk tan kaçan Olmadım hiç aşka küsen Seven kalbe hasar veren Olmadım güzel olmadım (28.08.2005-Yeni)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/olmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıp Değil', 'ayip-degil-sahin-erturk-0hvxh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayıp değil,seni sevmek

Herkese seni anlatmak

Şiir yazıp,kurlar yapmak

Ayıp değil,ayıp değil

Kolay değil,böyle aşklar

Efsaneler böyle başlar

Gözden gitmez olur yaşlar

Kolay değil,seni sevmek

Aşkımda yok tek bir hile

Sen güzel sen kızsan bile

Seni sevmek ayıp değil

Ayıp değil,ayıp değil

(25.08.2005-Yeni)', 'Ayıp değil,seni sevmek Herkese seni anlatmak Şiir yazıp,kurlar yapmak Ayıp değil,ayıp değil Kolay değil,böyle aşklar Efsaneler böyle başlar ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayip-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı Mı?', 'olmadi-mi-sahin-yilmaz-ycvxe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düzeltiriz diye başa gelip te,

Evvela düzgüne tıklamadık mı? 

Yetkimizi bu milletten alıp ta,

Milleti arkadan oklamadık mı? 

Çıkar için güçlüleri kayırdık,

Ne giydirdik, ne fakiri doyurduk,

Hırsızları vekil seçip ayırdık,

Millet Meclisinde aklamadık mı? 

Millete yıllarca masal uydurduk,

Ninni çaldık, kaydıraktan kaydırdık,

Hazineyi holdinglere soydurduk,

İMF''den yardım beklemedik mi? 

Üç kâğıtta kupaları kaldırdık,

Düşünceyi eğitimle öldürdük,

Çocukları ahırlara doldurduk,

Hayvan pisliğini koklamadık mı? 

Alay edenleri, gülüşenleri,

Oturup seyrettik bölüşenleri,

Vatanı bölmeye çalışanları,

Meclis lojmanında saklamadık mı? 

Sağ-sol olduk kendimize çullandık,

Ya zindana, ya da ipe yollandık,

Nice yiğitleri önce kullandık,

İşleri bitince haklamadık mı?', 'Düzeltiriz diye başa gelip te, Evvela düzgüne tıklamadık mı?  Yetkimizi bu milletten alıp ta, Milleti arkadan oklamadık mı?  Çıkar için güçl...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olmadi-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(Yüreğimi Yalnız Ona Bıraktım', 'yuregimi-yalniz-ona-biraktim-umut-gungor-nstgw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzelliği beni aşka koşdurdu,

Şarkılarla türkülerle coşturdu,

Gönül resmi çerçevemde hoşdurdu,

Yüreğimi yalnız ona bıraktım.

Dili ile fetheyledi yüreği,

Aşk ile çektim kayığında küreği,

Beni mutlu etmek imiş dileği,

Yüreğimi yalnız ona bıraktım.

Şiirleri yazıverdim aşkından,

Korunmuyor yürek böyle taşkından,

Açıklama beklemeyin şaşkından,

Yüreğimi yalnız ona bıraktım.

Kaşa göze şirin söze vuruldum,

Davet ile yar gönlüne kuruldum,

Sakin duran göller gibi duruldum,

Yüreğimi yalnız ona bıraktım.', 'Güzelliği beni aşka koşdurdu, Şarkılarla türkülerle coşturdu, Gönül resmi çerçevemde hoşdurdu, Yüreğimi yalnız ona bıraktım. Dili ile fethey...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregimi-yalniz-ona-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Budur Anlamadığımız', 'i-ste-budur-anlamadigimiz-ahmet-nural-ozturk-yjkt3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çözülmezliği yaşamın vazgeçilmezliği de

İnıp çıkıp düşüp kalkıp dalışlarımız

Ölümde ağlamak gülmek düğünde 

Yarin gözünden ellere

Ellerden yare varışlarımız

Bir gün gibi sevişlerimiz

Karanlıkta kaybolan ışıltımız

Birbirini aldatan alınğanlık

Sonrası kaçışlarımız

Düşmekte var kalkmakta işte budur anlamadığımız', 'Çözülmezliği yaşamın vazgeçilmezliği de İnıp çıkıp düşüp kalkıp dalışlarımız Ölümde ağlamak gülmek düğünde  Yarin gözünden ellere Ellerden y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iste-budur-anlamadigimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbinde bana da yer aç', 'kalbinde-bana-da-yer-ac-ali-orkac-nu4yy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk, hayatın kendisi olmaya aday olan çizimli yoldur. 

Alın yazısını arayan ve içinde kaybolması gereken bir duygu,aşk. Beklentilerimiz aslında bu duygu çerçevesinde şekil alıyor. Renkten renge giriyor. Kişide var olan bu duygu insanı sürekli kışkırtıcı bir edilgenliğe sürüklüyor. Aşıksındır,gözlerin onun dünyasından başka bir dünyayı göremiyor. O duygu sarmıştır tüm benliğini,sevilmek istiyorsun,ama sevildiğini hissetmek isteyişini bir türlü sevemiyorsun ya da ona aşkını aktarmaktan korkuyorsun. “ kendini sevdirmek isteyenin, kendi sevgisini peşin peşin ödemesi gerektiğini unutuyorsun.” Kendi sırrını açığa çıkartmaktan endişe duyuyorsun. Bu duygu sende birtakım şüpheler uyandırıyor,çünkü içinde sırını ona aksettirsem o sır ondan uzaklaşmış ve sır olmaktan çıkmıştır,başkaları bu sıra sahiplenmiş,dolayısıyla benim sırımı saklamayanla kalp sancısını çekemem düşüncesi sende hakim olur. Bu endişeyle sevilme isteyişini erteliyorsun,karşı tarafında sevilme isteyişini bu bağlamda ihanet olarak değerlendiriyorsun.'' 

Aşık,aşkını sevgiliye ilan ettiği anda aşkı sır olmaktan çıkmıştır. “aşık sırrını verdiği sevgilisinin o sırrı muhafaza edeceğini düşünüyor. Oysa o sır başkalarına aktarılmak üzere ondan sızdırılmıştır. Aşık aslında kendine tevdi edilmiş olan emanete ihanet etmekte beis görmüyor; fakat sevgilisinin aynı emanete ihanet etmesi onu hüsrana uğratıyor,ihanet ihanettir. Ve de aşığın ihaneti ile maşuğun ihaneti aynı makuldendir.”diyen R. ÖZDENÖREN işin her iki tarafının da beklenenin aksine davrandıkları yani ikisine ait sır, sır olmaktan çıkarak kendilerini deşifre ediyor,çünkü bir söylemi biri biliyorsa ve karşı tarafa izahiyette bulunmuşsa zaten bu söylem ya da sır açıklandığı için artık o gizlilik açığa çıkmıştır. 

Şimdi sevgilinin bu noktada sevgiliye: kalbinde bana yer aç! söylemi aşıkların var olan sırrı açığa vurdukları gerçeği ortaya çıkarmış olur. Bu duyguyu derinlere götürürsek aşkın kışkırtıcı yanını daha da körüklemiş oluruz. Buna paralellik gösteren: “ şarkılarınızda bana da yer açın ve daha da genişlesin avuçlarımdaki harita,serip o haritayı yemek yediğimiz masaya savaş planları yapalım birlikte.'' 

''Aşk bir savaştır ve iki kişilik bir ordu bile yeter zafer kazanmaya.Beni zaferinize kabul edin bayan,yaralarınıza yakın tutun ve bir kör kurşunu birlikte ısıralım. Aynı kurşunu bölüşmektir benim aşkım,cephanem bitince sizin kurşunlarınızla doldurayım tüfeğimi,siz tüfeğinizi bir şehri yakmanın çılgınlığıyla doldurun.”İdris ÖZYOL’un bu hakikate parmak bastığı ve içinde beraberinde vurguladığı paylaşımı,aslında kalbinde bana yer aç duygusunu sürekli öne alarak aşığın sırını yaşamın her tarafına aksettirip, açığa çıkmasını bir nevi sergilenmiş oluyor. 

Evet, kalbinde bana yer aç, sıcaklığını sıcaklığımla hisset; ama hissettiğini belli etme. Yaralarımıza aynı teşhis konulsun,ısınsın yüreklerimiz kendi ısımızla kalbimize kan fışkırsın, aşkımıza birileri sahiplenmesin,birlikte analım andıklarımızı, paylaşmaya kapalı tutalım sırlarımızı; ama ihanete tahammül edelim gizliden. Bunu yaparken, ne olur! kendimizden uzak ve o kadar da sınırları gözden kaçırmadan yapalım.sevgimizi sırımız gibi sevelim, 

ben,''sev'' dediğimde sen ''sevmeği gönlümde bil'' de.haritamızda sadece iki kişilik bir sevgi savaşçısı kalsın. 

........', 'Aşk, hayatın kendisi olmaya aday olan çizimli yoldur.  Alın yazısını arayan ve içinde kaybolması gereken bir duygu,aşk. Beklentilerimiz aslı...', ARRAY['Türk Edebiyatı','Şiir','Ali Orkaç']::text[], 8.5, '{"poet":"Ali Orkaç","poet_slug":"ali-orkac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalbinde-bana-da-yer-ac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsa', 'i-sa-emin-acil-0jcdr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hey nasıralı dilenci 

çarmıhı sırtlamış nereye

bir kuşun ki kadar yüreğin yok 

bir kuşun ki kadar beynin

şanslısın ama

milyonlarca aç dilencinin

kuş beyinlinin yegane sevgilisisin 

meyremin kutsal rahmi aşkına 

dogruyu söyle isa

piç bir ulustan sevgi dilenmek

hangi erdemin sırrı

ya magdelenaya ihanetin 

hangi dogrunun gereği

kaçırt gözlerini isa 

karçırt korkak dilenci

sen de biliyorsun ki 

zeustan daha yüce değildir baban

ve hiç de masum değildir meyrem anan

                                      eylül 2003 

                                      Emin açıl', 'hey nasıralı dilenci  çarmıhı sırtlamış nereye bir kuşun ki kadar yüreğin yok  bir kuşun ki kadar beynin şanslısın ama milyonlarca aç dilenc...', ARRAY['Türk Edebiyatı','Şiir','Emin Açıl']::text[], 8.5, '{"poet":"Emin Açıl","poet_slug":"emin-acil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Dair', 'olume-dair-zeki-altas-zc8sc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sefere çıkmışız,

başaçık,yalınayak.

Tipiler eser pek yaman,

dallarımız ıslak...

Sarp kayalar aşılmaz,

dalgalar boğar bizi.

Yılanlarla dost olduk,

Acımaz,

sokar bizi...

Bir sefere çıkmışız,

dipsiz uçurumlardan.

Sonsuzluk önümüzde,

hayat denizinde...

Bir dünya sevdamız vardı,

ahengiyle yaşadık yıllar yılı.

Salındı sevdalara hayallerimiz,

avunduk oyuncaklarla,

ıslandı ümitlerimiz...

Bir sefere çıkmışız,

kefen koltukta gideriz.

Gün olur tel tel dökülür,

gün olur ummanlarda çağlarız...

Bir sevdayla haşlandık,

kavruldu ciğerimiz.

Ufka bakarız geçmişten,

yanıyor yüreğimiz.

Bir sefere çıkmışız,

ağlıyor gözlerimiz...

Ve toprak basar bağrına,

bir gün sarmalar ukba.

mertekler vurur başımıza...

Son sefere çıkmışız,

Ağlıyor geçmişimiz...

Allah''ım,

affet bizi!', 'Bir sefere çıkmışız, başaçık,yalınayak. Tipiler eser pek yaman, dallarımız ıslak... Sarp kayalar aşılmaz, dalgalar boğar bizi. Yılanlarla do...', ARRAY['Türk Edebiyatı','Şiir','Zeki Altaş']::text[], 8.5, '{"poet":"Zeki Altaş","poet_slug":"zeki-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/olume-dair-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslatın Hüdâdandır', 'vuslatin-hud-dandir-ali-riza-unal-hdhoe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'cemâlin gördüm göreli

hayat sensiz olmuyor

ne olur firâk eyleme

gönlüm sükûn olmuyor

seni sevmenin kadri

bade-i cüdâdandır

aşkın celâli belâdan

lütfûn ikrâm ı alâdandır

tövbeyim sana tövbaye

kabul et ricâlarım

gafletim acı ıdırap

vuslatın hüdâdandır

-bu bir teceli üzere hazırlanmıştır---------

tasavvuf miziği güfte ve bestesidir

28-ağustos-2005-saat-12-10--

hadumul fukara abdi acizâr

Ali Rıza Ünal', 'cemâlin gördüm göreli hayat sensiz olmuyor ne olur firâk eyleme gönlüm sükûn olmuyor seni sevmenin kadri bade-i cüdâdandır aşkın celâli belâ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vuslatin-hudadandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yârim İstanbul', 'y-rim-i-stanbul-mehmet-osman-erol-unal-jmcsw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bu şehrin kadınısın, yaşıyorsun rûhumda

İstanbul''u gözlerinden tanıyorum

Yıldız çeşmelerinden sular akıyor hâlâ

Doyasıya ellerinden içiyorum

Kızkulesi''nde asılı duruyor  hayâlin

Gece, gündüze sarılmış deniz soluyor

İstanbul''un âşıkları bir garib olmuş

Kim görse bana, seni soruyor...

Çamlıca''dan yükselen kahkahalar

Üsküdar  yollarında ayak seslerin 

Beyoğlu''na çıksan peşinde günahlar

Sen, İstanbulsun... İstanbul senin...

Oyalı da mendilini yolda düşürür

Çapkınca bakar bir türkü tutturur

Sesini duyarım İstanbul''un... içim burkulur

Ver elini derim  vermez... kaçar, sır olur

Cumbanın ardından gözün süzersin

Ah İstanbul beni nasıl üzersin

Sarıyerden Ortaköy''e dilde gezersin

Sen İstanbulsun, vefâ bilmezsin

Rüzgârlara taratır ipek saçını

Kıskandığımı bilir de umarsamaz beni

Çığlık çığlığa İstanbul''un martıları

Adını söyler, çağırır, ağlatır beni

Sen, İstanbul... ben sana âşık

Yanağı benlim, çiftetellim

Bahçemdeki âşüfte sarmaşık

Sen İstanbul, sevgili yârim

Sen bu şehrin kadınısın bütün rûhunla

İstanbul''u gözlerinden tanıyorum

Al yüreğimi sık avuçlarında

Ne varsa senden aldığım... sana adıyorum

(İstanbul, Nisan 1994)', 'Sen bu şehrin kadınısın, yaşıyorsun rûhumda İstanbul''u gözlerinden tanıyorum Yıldız çeşmelerinden sular akıyor hâlâ Doyasıya ellerinden içiy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yarim-istanbul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tatlı Tesâdüf', 'bir-tatli-tes-duf-mehmet-osman-erol-unal-0tj8r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimi ısıtan o tatlı bakışlar

Dudaklarımda sanki ılık nefesin

Koşarcasına geçen ürkek adımlar

Önüme düşüyor savrulan eteklerin

Dalgın, mütebessim ve biraz mahzûn

Bir şeyler sorar gibiydi sanki gözlerin

Ne zaman dalıp gitsem ölesi yorgun

Aklıma düşüyor iri gözbebeklerin

Sonbahar rüzgârısın rûhumda esen

Sararıp savrulan yapraklar gibisin

Ne zaman seni düşünüp şarkı söylesem

Peşime düşüyor sanki ayak seslerin 

(İstanbul, Aralık 1989)', 'İçimi ısıtan o tatlı bakışlar Dudaklarımda sanki ılık nefesin Koşarcasına geçen ürkek adımlar Önüme düşüyor savrulan eteklerin Dalgın, müteb...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-tatli-tesaduf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun...', 'gidiyorsun-kazim-simsek-1-5mhti', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Giderken,

Birkelime süzüldü dudaklarından.

''hoşçakal''

Hiç düşündünmü? 

''Hoşça'' kalınabilirmi ardından...

Giderken..

''Güle güle'' mi gidiyorsun,

Beni böyle bir başıma 

Ve yapayalnız bırakırken..

Ne garip bir veda şarkısı bu,

Bozuk bir senfoni...

Anlam veremedim,hiçbir şeye

Tiz bir ses yüreğimi acıttı sadece...

Söyle bana; 

''Hoşça'' kalınabilirmi? 

Sensiz,

Bu netameli hayat ezgisinde..', 'Giderken, Birkelime süzüldü dudaklarından. ''hoşçakal'' Hiç düşündünmü?  ''Hoşça'' kalınabilirmi ardından... Giderken.. ''Güle güle'' mi gidiyorsu...', ARRAY['Türk Edebiyatı','Şiir','Kazım Şimşek 1']::text[], 8.5, '{"poet":"Kazım Şimşek 1","poet_slug":"kazim-simsek-1","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gidiyorsun-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinsi, Sinsi...Sinsice...', 'sinsi-sinsi-sinsice-mehmet-osman-erol-unal-5chss', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinmeyen bir sızı var

Yüreğimin orta yerinde

Büyüyor, büyüyor, büyüyor...

Gece, gündüz

Sinsi, sinsi... sinsice...

Bitmiyor hiç göz yaşım

Hasretim yola koyulmuş

Gidiyor, gidiyor, gidiyor...

Gece, gündüz

Sessiz, sessiz... sessizce...

Yine yağmur yağıyor

Ben, yine yollardayım

Bir damlası değmiyor üstüme

Seni arıyorum

Bildiğim / bilmediğim her yerde

Gece, gündüz

Deli, deli...delice...

(İstanbul, Haziran 1992)', 'Dinmeyen bir sızı var Yüreğimin orta yerinde Büyüyor, büyüyor, büyüyor... Gece, gündüz Sinsi, sinsi... sinsice... Bitmiyor hiç göz yaşım Has...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sinsi-sinsi-sinsice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azman Doktor', 'azman-doktor-i-smail-hakki-cengiz-noxca', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlerdir burnum tıkalı, boğazım yara, 

Görünsem gerek diye bir uzman doktora…

Bornova Özel Tıp’ın kapısına vardım,

Göremedim bir kimse, boştu önüm, ardım.

Bakınırken ben sağa sola, önümde durdu

Genç bir bayan, “ne ararsın burada? ” diye sordu.

Dedim “hastayım, bir güzel muayene olayım.”

Dedi “ver sağlık karneni, kopyasını alayım! ”

Çekti iki adet fotokopi, elime verdi,

Adres, telefon, imzamı almaktı derdi.

Yadırgadım tavrını, çünkü bana yazdırdı,

İçimde saklı şikayet arzusunu azdırdı.

Yazdım adres, telefon, sonra imzamı çaktım,

Yine gözden kaybolmuştu bayan, etrafa baktım.

İçeride gazete okurken yakaladım,

İmza ettiğim kopyaları eline tokaladım.

Aldı lâkayt tavırlarla, kaydetti deftere,

Sonra gönderdi beni, yandaki mesul müdüre…

Müdür, doktor aynı zamanda, sevk etti KBB’ye,

Ayrıldım oradan, teşekkür ederek hekim beye.

Çıktım ikinci kattaki KBB uzmanına, 

Surat duvar, varmak cesaret ister yanına…

Toplayıp cesaretimi, hazrete yaklaşırken,

Tısladı “şikayetin ne? ”, ses değil diken.

Dedim “efendim, hem burnum tıkalı, hem boğazı…”

Bitiremedim cümlemi, kesti haşin avazı:

“Uzan şu koltuğa! ”, korku değdi, iliklerime,

Sayın uzman baktı hızla burun deliklerime.

Oldu-bitti muayene tam kırk beş saniyede,

Böyle sürat görmedi alem, ilm-i tıpbiyede.

Talimat verdi hemşireye “kan tahlili, röntgen”

Uzmanımız döndü “küçük ilanlar”ına hemen.

Didik didik ediyor gazeteyi, yaşardı gözlerim,

Böldü keyfini boğazdan şikayet eden sözlerim.

Başını kaldırmadan gürledi, “tahlil yazdık işte! ”

Sabrettim, bir hayır görmesem de bu gidişte! 

Kanımı vermek için birinci kata indim,

Güler yüzlü bir hemşire görünce sevindim.

Sakınmadan verdim bir şırınga kanımı,

İşin ehli hemşire acıtmadı hiç canımı.

Tebrik ederim kendisini, hem saygılar sunarım,

Ömrüm oldukça en iyi dileklerle anarım.

Röntgen de çekilince, bitti sabahki fasıl,

Sanırım, muayene öğleden sonra asıl! 

Saat iki olunca tahlillerimi aldım,

Sayın uzmanın örtük ceviz kapısını çaldım.

Hazret, misafir koltuğunda, elinde gazete,

Araştırmaya ne hacet, kafada hazır reçete! 

Filme, kan tahliline şöyle bir göz attı,

Hastalığımın ne olduğuna aklı yattı.

Duymadan herhangi bir açıklama gereğini,

Başı önünde emretti “ver sağlık karneni! ”

Dedim ya reçete hazır, uzman yazmaya koyuldu,

Kan beynime çıkarken, ruhum oyuk oyuk oyuldu.

Bir daha denedim; boğaz derdimi açmayı,

Yine kesti sözümü. “bırak der gibi saçmayı! ”

“Kullan ilaçları, geçmezse göğüse git” dedi.

Tabii bu baştan savma beni hiç tatmin etmedi.

Baksanıza ilacına kendisinin yok inancı,

Hem hastaya kaba davranıştan acep nedir kazancı? 

Sizlere şikayet ediyorum bu “azman” doktoru,

Sayesinde(!)    incindi hem insanlık, hem hekimlik onuru.

                                                    20 Ağustos 2005 / Bornova

hacengizgmail.com', 'Günlerdir burnum tıkalı, boğazım yara,  Görünsem gerek diye bir uzman doktora… Bornova Özel Tıp’ın kapısına vardım, Göremedim bir kimse, boş...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Cengiz']::text[], 8.5, '{"poet":"İsmail Hakkı Cengiz","poet_slug":"i-smail-hakki-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/azman-doktor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kelime - Dört Hece', 'bir-kelime-dort-hece-mehmet-osman-erol-unal-2lb3b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daracık, kaldırımsız yollarda

Senden arta kalan anıları arıyorum

Karabasanlar çöküyor içime

Tutmaz oluyor dizlerim

Ağlıyorum...

Her köşebaşı yeni bir umut

Gördüğüm her yüze seni soruyorum

Sen olmayınca,  olmuyor işte bak

Yaşamaksa...işte öylesine

Gelişigüzel... yaşıyorum...

Şeytan bile diyor ki sen delisin

Vaz geç! ...

Yoksa çâresi koyver gitsin

Ama...

Uymuyorum...

Aslında,

Ne varsa söylenecek

Toplasan,

Hepsi bir kelime, dört hece eder...

Bir daha, bir daha... bir daha söylüyorum

Sen, bilsen de, bilmesen de

Sen, duysan da duymasan da

Yanımda olsan da, olmasan da

Seni

''se - vi - yo - rum '' 

(İstanbul, Şubat 1994)', 'Daracık, kaldırımsız yollarda Senden arta kalan anıları arıyorum Karabasanlar çöküyor içime Tutmaz oluyor dizlerim Ağlıyorum... Her köşebaşı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-kelime-dort-hece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilitledim Gönlümü Derinliklere', 'kilitledim-gonlumu-derinliklere-muhammet-faruk-koca-4itt4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kilitledim gönlümü güneşin ahengine, 

Kin tutmuş yüreklere inat, 

Anlatılması güç bilinmez, 

İçimde yarım kalan yangınım nerdesin? 

Bazen bir bulut olur yüreğim ahenginde, 

Şimşekler çakar yüreğimin üstüne üstüne, 

Başlar bir yağmur ıslatır avuçlarımı yokluğunla, 

Uzanmak istemiyor ellerim sonsuzluğa nerdesin? 

Dönülmez bir gemi misin yoksa sende, 

Sessizce limandan kalkışın sessizliğe, 

Sisli bir havada denizin ansızın seni alışımıydı benden, 

Eski bir İstanbullu söylüyor şarkılar şimdi bana yokluğunda, 

Nameler hep matemli çalıyor, 

Neydi? Seni benden ansızın koparan, 

Kopuk bir yaşantıya bırakan, 

Neydi? Ellerinin seni her görüşte terlemesi neydi? 

Aşk mı ızdırap mı neydi ansızın çıkıp gidişin İstanbul’dan, 

Şimdi bir hüzzam şarkısı çalıyor yüreğim, 

Bir tarafta ucu yırtık bir resim diğer uçta gaz yaşlarım, 

Hani bir dönseydin İstanbul’a, 

Yarım kalan büyümeyen çocukluğum kaldı sende, 

Hani bir dönsen diyorum ya, 

Ellerin ansızın ısıtsa yüreğimi, 

Hani o bakışların bölse beni yine ikiye, 

Nerdesin? 

Şimdiler de yalnızlığa yenik düşmüşüm ben, 

Belki şimdi sen yoksun İstanbul’da, 

Belki bir daha omluya çaksın oysa 

kayan bir yıldız yüreğim, 

Sensizliğin acısıyla bir sağa bir sola çarpan, 

Sensizliğin verdiği ızdırapla dolanıyorum, 

Gezdiğimiz, oturduğumuz, konuştuğumuz mekânlarda, 

Yüreğim ellerimde eriyor işte, 

Hani okul çıkış oturduğumuz park, 

Şimdi öyle yalnız öyle mahsul, 

Yıkılmış bir şehir gibi, yüreğimde öyle 

Nerdesin? 

Bakışında yarım kalan gülüşüm nerdesin? 

Şimdi sensizim biliyorum 

Bir asla olmayacaksın 

Ben seninle kilitliyorum gönlümü, 

Seninle olan anıları belki açılmamak üzere, 

Biliyorum zamanı hiç yakalı yamayacak ellerim, 

Zaman zindan gibi odamda, 

Duvarlar bir yandan resmin bir yandan bakıyor bana, 

Ellerimden kayıyor zaman tutamıyorum, 

İşte ben böyle sensizliğe kilitliyorum gönlümü, 

Aşka susayan şair gibi, 

Satır satır işliyorum seni, 

İşte ben yalnız sokak sarhoşu, 

Yoksun işte biliyorum, 

Artık sonu geldi filimin, 

Nerdesin? 

Ben bıraktığın yerde o parktayım, 

Yıkık bir şehir onarılmaz, işte sırf bu yüzden, 

Gömdüm gönlümü derinliklere. 

Yüreğinde yarım kalan bakışa. 

28.08.2005', 'Kilitledim gönlümü güneşin ahengine,  Kin tutmuş yüreklere inat,  Anlatılması güç bilinmez,  İçimde yarım kalan yangınım nerdesin?  Bazen bi...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/kilitledim-gonlumu-derinliklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G.Z''nin Gecmemis $iirleri 8', 'g-z-nin-gecmemis-iirleri-8-huseyin-avdic-6w4gw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Genclik Bo$lukta

Genclik varlikta.

Varlik darlikta.

Darlik yoklukta.

Yokluk lo$lukta.

Lo$luk bo$lukta.

******

Silahim

Kur$unum, kur$un kalem.

Tüfegim, dolma kalem.

Istemem ba$ka âlem.

Atomum, tükenmez kalem.

******

Insanligin Bembeyazligi

Kaldirin Ayi, Günesi, yildizlari.

Geri kalir, dünyanin simsiyahligi.

Indirin Nuru, Resûlü, Kitaplari.

I$te bu, insanligin bembeyazligi.

Bati Berlin, 1980-85.', 'Genclik Bo$lukta Genclik varlikta. Varlik darlikta. Darlik yoklukta. Yokluk lo$lukta. Lo$luk bo$lukta. ****** Silahim Kur$unum, kur$un kalem...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/g-z-nin-gecmemis-iirleri-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ol', 'ol-sedat-akguden-wcsf7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ol

Bütünlüğümü böl böl ikiye

Paylaş benimle beni

Yanımdaki yakınımdaki

Kolumdaki koynumdaki ol

Okuduğum yazdığım

Yazarken yaşadığım

Bir yanım hep senin

Yaşarken paylaştığım ol

Yanımdayken özleyeceğim

Koynumdayken düşleyeceğim

Onurum gururum

Duygum tutkum hüznüm ol', 'Ol Bütünlüğümü böl böl ikiye Paylaş benimle beni Yanımdaki yakınımdaki Kolumdaki koynumdaki ol Okuduğum yazdığım Yazarken yaşadığım Bir yanı...', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ol-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-i-lhan-koruyucu-94xgx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Masal

Kaf dağının ardında bir dev yaşarmış

Bizim keloğlan az gitmiş uz gitmiş

Altı ay, bir güz gitmiş 

Bir de bakmış ki 

Bir arpa boyu yol gitmiş

Masal bu ya

Bütün çocuklar can kulağıyla dinlermiş

Hülyalara dalmak ta varmış

Bu masaldan biz büyüklerde pay almalıymış

Dünya da sadece kötülükler yokmuş

İyilikler her zaman sonunda kazanırmış

Prensler ve prensesler mutlu olurmuş

Kötüler  elbette cezalarını çekerek

Onlara sorulurmuş

Kırk katır mı? 

Yoksa kırk satır mı? 

Tabi ki can tatlı kim seçer kırk satır’ı

Bari kırk katır olsun diyerek

Bizim dünyamızda iyilikler, güzellikler galip olup

Kırk gün kırk gece düğün edip

İyilikler prensi ile prensesine

Diyelim bizlerde onlar ermiş muradına

Bizde çıkalım kerevetine

Gökten üç elma düştü

Biri bizim prense

Diğeri prensesimize

En son elmamızda 

Bu dünyada iyiliğin, 

Güzelliğin gücüne yürekten inanların başına.

İlhan Koruyucu.', 'Masal Kaf dağının ardında bir dev yaşarmış Bizim keloğlan az gitmiş uz gitmiş Altı ay, bir güz gitmiş  Bir de bakmış ki  Bir arpa boyu yol g...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/masal-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa Kemal''im', 'mustafa-kemal-im-i-lhan-koruyucu-kn4k3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mustafa Kemal’im

Adın titretir cihanı

Şanın yüceltir vatanı

Çanakkale de yatan şehidim

Dalga dalga al bayrağım

Şerife bacımın kağnısındaki mermim

Elif Elif diye esen rüzgarın sesi

Mehmetçiğin süngüsündeki eseri

Çakmak bakışlı o komutan Mustafa Kemal''im

Anadolu da yayılır özgürlük sesin

Bandırma''dan kalkıp Samsuna varan sen

Esen özgürlük, milliyetçilik milletinle birliktesin

Allah Allah nidalarıyla cephede en önde

Savaşıp yine barışı getirensin

Türk milletine en çok inanansın

Yurtta ve dünyada barışa güvenensin

Mustafa Kemal''sin adın ve şanın büyük

Dizi dizi devrimlerin hep Türk milletin’e

Bilirim ki gençliğine güvenensin

Dünyada çocuklara ilk bayram hediye edensin

Nasıl anlatırım ben seni nasıl? 

En büyük komutansın, devlet adamısın

Yüce Türk milletinin ve dünyanın ender yetiştirdiği

Ne büyük dehasın

Mustafa Kemal’im, Atatürk’üm.

İlhan Koruyucu.', 'Mustafa Kemal’im Adın titretir cihanı Şanın yüceltir vatanı Çanakkale de yatan şehidim Dalga dalga al bayrağım Şerife bacımın kağnısındaki m...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mustafa-kemal-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manifesto', 'manifesto-omer-golge-a1rt4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siz insansılar işitin....

Bundan böyle bütün iyi niyetlerimi

Süresiz tehir edip yaşayacağım

Güvensiz ve paronayak bir hayata

Sayenizde alışacağım.....

Yarınlara dair bütün umutlarımı.,

Yalnız kendimde taşıyacağım

Geceler boyu uzun uzun..

Kendime postalanmış 

Mektuplar yazacağım

Zannetmeyin siz olmayınca....

Doğru bildiklerimden şaşacağım.

Karar verdim sizin yüzünüzden...

Bütün kirli yüreklerle........

Tek başıma savaşacağım....', 'Siz insansılar işitin.... Bundan böyle bütün iyi niyetlerimi Süresiz tehir edip yaşayacağım Güvensiz ve paronayak bir hayata Sayenizde alışa...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/manifesto-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastalıktan Bükülmüş Belim', 'hastaliktan-bukulmus-belim-memet-karabalik-t5160', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceye yorgan örtmemişim

Gündüze isyan etmiş güneşe çıkmamışım

Bir aydınlık odadır benimkisi

Yapıp- etmelerim yoktur

Yazıp- çizmelerim avutur saatleri

Ayakucumda sevdiğimi hayal eder

Ellerimle aklımı taşırım yüreğime

Taşı çocukluğumdan bilirim

Her soluk ölümü çağırır bana

Birilerine kızdığımdan değil isyanım

Çatık kaşlarım sevgimin eseri

Atmosferi kirlenmiş bir dünya var diye içerim sigarayı

Kirli bir dünya var diye aldım kalemi

Hayata dair bildiklerim var

Varla yok arasında aranmaz gerçek

Ya vardır yanarım

Ya yoktur yanarım

Aşığına küsmüş kız aşkına patlar ya

Borçlu doğmuşsam küserim

Küstürülmüş her bebek gibiyim

Ağlarsam silahıma ağlarım', 'Geceye yorgan örtmemişim Gündüze isyan etmiş güneşe çıkmamışım Bir aydınlık odadır benimkisi Yapıp- etmelerim yoktur Yazıp- çizmelerim avutu...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hastaliktan-bukulmus-belim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiirin Son Mısrasını Okuyor Kız', 'bir-siirin-son-misrasini-okuyor-kiz-memet-karabalik-0jc1k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şiirin son mısrasını okuyor kız 

İçinde biriken nehirlerin şahlanışıdır

Göğe yerden bakmaz şair 

Leçeğinde bir dünya saklıyor anam

Leçek bir dünyadır belki

Bir savaşçı sığar mı dünyanın yüreğine

Yürekler acır mı birbirine

Ve acı bir yüreği savaşçı kılar

Benim dediğin topraklarda kayar

Bir evlatta sen kaybedersin

Hüzün gözyaşı salar yüreğine 

Bir gün senin Hasan’ın da dönemezse eve 

Yüreğine bir savaşçı doğar o gün 

İsyan dünyaya yürektir

Kıyametin kopmamasına sebep vardır

İsrafili durduran aka boyanmış yaşlılar değildir

Onsekizinde bir gencin dünyayı yumruklamasıdır', 'Bir şiirin son mısrasını okuyor kız  İçinde biriken nehirlerin şahlanışıdır Göğe yerden bakmaz şair  Leçeğinde bir dünya saklıyor anam Leçek...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-siirin-son-misrasini-okuyor-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Güne Bir Mektup 3', 'her-gune-bir-mektup-3-mehmet-haluk-hisli-tth4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...

Sizi geç yanıtladığım için affedin...Bundan sonra gecikme olmayacak... Korkmaya gelince, siz yazdınız ya yetmez mi...Demek ki benim gibi özgürler ve SİZİN GİBİ KORKUSUZLAR halen var... Bir diğer mevzuu da “Korkunun ecele faydası var mı...” Elbette yok... Öleceksek ölelim... 

Ayrıca, kadınlar, diye bir genelleme yapılabilir mi, böyle toptancı bir yaklaşım ve tutum takınabilir miyiz diye düşündüm... Sonra bunun hep yapıldığı aklıma geldi. Bence bu doğru bir yaklaşım değil; her zaman istisnalar olduğu gibi, hangi kadın ya da kadınlar diye de sormak gerekiyor. Çalışan kadın, işçi, memur, kariyer sahibi kadın; ev kadını ya da hangi yaşlardaki kadın ya da kadınlar; hangi kültürün kadınları: Alt sınıf, üst sınıf, orta sınıf kadınlar... Kocaman bir soru işareti... Böyle genellemeler bu denli kalın çizgilerle yanlış; ama ötekinden kastımız erkekse,  evet doğru. 

Genel hatları ve kalın çizgilerle iki farklı dünya, kadınla erkeğin dünyası; hormonları farklı çalışır, yaşamdaki rolleri farklıdır, duruşları, ilişkileri, sözcüklere yükledikleri anlamlar farklıdır; ekonomileri, güçleri, erkleri farklıdır. Kadınlara göre daha cesurdurlar, daha ataktırlar; güçlü olmak zorundadır, para kazanmak zorundadır, genelde birilerine bakmak zorundadır ve sıralamaya kalktığımızda uzunca bir liste elde edebiliriz. 

Evet “öteki” kadınsa farklıdır; bence kadınlar, sizin tezinizin aksine böyle cesur ve cüretkar erkekleri severler. Hangi türden kadın olursa olsun geneli bir biçimde korunmak ister ve bunu yapabilecek olanın da cesur erkekler olduğunu söyler dürtüleri onlara. Yalnız bu mu sıra dışı erkekler, boyun eğmeyen cüretkar erkekler çeker kadınları… Kimisi onlara sahip olur; kimisi “Dünya ahiret kardeşim olsun.” gibi sözlere saklanarak bir biçimde bu erkeklere örtük olarak da olsa hislerini belli ederler. Eğer erkek bunun farkındaysa bunu sonuna kadar kullanır. Birçok kadının canını yakar. 

Bu aldırmaz, bu kendine güvenen, bu her şeye biraz tepeden bakan adamın büyüsüne kapılır ve mutsuz ola ola gücünün son damlasına kadar ısrar eder onunla varolmaya… Taa ki tükenene kadar... Sonrasıysa depresyon, intihar, hayattan mola almalar ya da cesur bir kadınsa sen yoksan başkası var der; der, ama o kadar da kolay değil. Zaten böyle diyen kadınların başına bu işler gelmez; çünkü onlar da genelde erkek dilini kullanmayı öğrenmiş kadınlardır  ve bu kadınlar bu nedenle erkekler için caziptir. Aynı dili konuşurlar. Erkekler, yaban bildiği “ötekindeki” bu üslup karşısında şaşırır ve artık bu kadın erkek için cazip kadındır ve o, onun için elde edilmesi gereken kadındır artık.

Aslında bu ilişkilere bir başka açıdan baktığımızda çoğunlukla birbirinden farklı değildir. Basit doğa kuralları işler, hormonlarımızın ayakta olduğu kendimizi iyi hissettiğiniz zamanda karşımıza biri çıkar ve olan olur. Bütün dünyamızı alt üst eder ve biz adrenalin ya da  yaşam enerjisi içinde sarhoş oluruz. Adına da aşk deriz. Artık onun dışında her şey önemini yitirmiştir. 

Ya bundan sonra ne olacak. Bugüne kadar getirdikleriniz kendinizle ve kendiniz dışındaki dünyayla kurduğunuz ilişki yani sizi siz yapan şeyler ilişkinin sonrasını belirler. 

Özgüven ve özsaygınızdan tutun da eğitim, bilgi,birikim, en önemlisi de erkekler açısından fiziğiniz, ne kadar seksi ve çekici olduğunuz ya da vücut denilen enstürümanınızı nasıl kullandığınız gibi... İşte böyle kısaca hangi kadın ya da... Hangi erkek ya da...

Düşün irdele…

Bir yandan da pervasızca, korkusuzca yaşamak gerek bence; korkunun ecele faydası yok … Öleceksek ölelim…', '... Sizi geç yanıtladığım için affedin...Bundan sonra gecikme olmayacak... Korkmaya gelince, siz yazdınız ya yetmez mi...Demek ki benim gibi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/her-gune-bir-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum Sevdiğim, Yarın İçin', 'agliyorum-sevdigim-yarin-i-cin-memet-karabalik-4tey2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmiş günlerin anısına değil güzelim 

Gelecek yılların mutlu çocuklarına armağanımdır bu

Mor dağların ötesinden bir çığlıktır

Sevdaya dair ne varsa odur

Şiirsel bir tını değil

Azgın hayaller peşine koşan korsan denizci

Hançeri acıtmak için bileyler

Bileğine sırt veren güreşçi şefkat diler

Dileğini çaputa bağlayan nine torun ister

Gelecekte oğlun ağlamayasın diyedir yazmalarım

Oysa kolay olmuyor gülmek

Aniden ve apansız doğmuyor güneş

Doğurmadan dokuz ay önce gün sayıyor bir ana

Taşınamayacak hasretlerin başı küçükken ezilemiyor nedense', 'Geçmiş günlerin anısına değil güzelim  Gelecek yılların mutlu çocuklarına armağanımdır bu Mor dağların ötesinden bir çığlıktır Sevdaya dair ...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/agliyorum-sevdigim-yarin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Söylenecek Bunca Laf', 'kime-soylenecek-bunca-laf-memet-karabalik-intrb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kime söyleyecek bunca laf 

Su suya hasret midir ki? 

Sarhoş bir aşkın akıbeti meçhule doğrudur

Yaralı bir ruhun acısını kim paylaşır

Ana desen, doğrudur 

Yar desen, eyvallah

Güzel günlere açsadık

Levhanın durağanlığı nedir ki

Biz gidiyoruz habire

Ufuktan ufuğa bir yolculuk

Satır aralarına sızmış acılar yaşıyoruz

Yaşamın habireliği öldürür çocukları 

Çoğu harcanmış bir gökyüzüne bakarken 

Ayağımızın altına asfalt seriliyor

Rahimden kabre sevda taşıyanlar ötesine de gider 

Öteden beri bilineni bilmek çok şey değiştirir 

Söylenmemiş her sözümüzün sahibidir çocuklar

Çay kıvamında bir sorgulama 

Çerez niyetine coplarla dosttur 

Yemek savcıdır, yutulamaz 

Ağacı bol bir ülkede katil oluyoruz  ya biz 

Suyumuz bolsa içmek için değil elbet

Boğmaya yarar

Su suya hasret midir ki? 

Sen seni anlayasın', 'Kime söyleyecek bunca laf  Su suya hasret midir ki?  Sarhoş bir aşkın akıbeti meçhule doğrudur Yaralı bir ruhun acısını kim paylaşır Ana des...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kime-soylenecek-bunca-laf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Yarın', 'ya-yarin-memet-karabalik-eegst', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir viraneden ötekine giderken de

Bir bir sayarken de yere düşenleri

Ne Türkler anladı

Ne de Kürtler vazgeçti

Yarına bakarken bu günü öldürdük

Çocuk acıları düşünmeden girdik birbirimizin kanına

Geç kaldık sevişmelerimize

Kemiğe dayanan bıçağın soğuk ürpertisine sarıldık

Kafalarımızdan boşalan

Ellerimize doluşan

Meskeni yürek sevdalar tadamadık

Nicedir hapsolduğumuz nefretin gölgesinde

Nasırlı ellerimize bulaşan

Çocuklarımızın kanıydı', 'Bir viraneden ötekine giderken de Bir bir sayarken de yere düşenleri Ne Türkler anladı Ne de Kürtler vazgeçti Yarına bakarken bu günü öldürd...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ya-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arsızlığına Gülen Kadın', 'arsizligina-gulen-kadin-memet-karabalik-6cdyl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arsızlığına gülen kadının dostu kaçar benden

Bana kinlenmiş kadının umudu uçar

Balkondan bir kanat sesi duyulur

Aşk göçe davranır

Soğuyan odamdan başlar kaçış

Sobalı odaların sıcak iklimine sarılır

Arada bir avcı rastlarsa 

Göçebe bir aşkın ölümü vurur kıyıya 

Bir köşebaşı tutmuş adamı 

Bir sigara yakmış efkarına ki

Öbür köşeyi kadınca bir işgal sarmış 

Sarmalanmış yarınları arayan ben miydim

Kadın mıydı yarına küsen 

Adam küfür ediyor bugüne açıktan

Yarına umut vermeyen güne lanet mi lazım

Aşına tuz katan annem miydi sadece

Köşedeki kadın anlar mı yemekten 

Anlamıyorsa sebebi mini eteği midir

Uzun bir tırnağın salata doğrayışını görecek miyim

Bana kalsa derim 

Duraktaki adam kendi tuvaletine kuyu kazamaz

Eline tükürmesini bilmeyen kürek tutamaz 

Oysa adam her gün traş ediyor sakalını 

Kir tutmayan bir yüz kazma sallar mı

Sallamaz derim ben

Sallarsa yalan sallar', 'Arsızlığına gülen kadının dostu kaçar benden Bana kinlenmiş kadının umudu uçar Balkondan bir kanat sesi duyulur Aşk göçe davranır Soğuyan od...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/arsizligina-gulen-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunları Bilin', 'bunlari-bilin-memet-karabalik-855ke', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adını söylemeye utanırsa bir çocuk

Bir adı olmadığından derdi dedem

Anlayamıyorsan bir pamuk işçisini

Kesik bir dil taşıyordur ağzında

Kendi olmuş ırgat dövülüyorsa

Beyninin elleri koparılmıştır

Aşık olamıyorsa deviren yürekler

Diyalektikten değil, didinmektendir

Dinine küfrediliyorsa birilerinin

Ali yoktur ortada, Ömer uyuyordur

Çocukları çalınmış analar varsa

Babasızlıktandır,

Bilesin!', 'Adını söylemeye utanırsa bir çocuk Bir adı olmadığından derdi dedem Anlayamıyorsan bir pamuk işçisini Kesik bir dil taşıyordur ağzında Kendi...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bunlari-bilin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliresim Var', 'deliresim-var-memet-karabalik-bud3a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurun yoğurduğu gecelere sığındım

Sarsılan yere kapaklandım

Hiçbir bahar özlemedim seni

Kaç kış yorgan yaptım hayalini

Her sabah su diye seni çaldım yüzüme

Deliresim var bu gece

Newroza gittik geçen yıl sen yoktun

Geçen ay “Kahrolsun…” diye bağırdım

Sen yoktun

Cumartesi anaları dövdüler, beni de

Bugün dilekçenin birine imza attım

Gözaltından göz ettim

Sen yoktun yine

Deliresim var bu gece', 'Yağmurun yoğurduğu gecelere sığındım Sarsılan yere kapaklandım Hiçbir bahar özlemedim seni Kaç kış yorgan yaptım hayalini Her sabah su diye ...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deliresim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale kahramanları 5', 'canakkale-kahramanlari-5-halil-colak-hb4lv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kahpe İngiliz Anzakları haclı ruhuyla kandırır sürer cepheye

Kader budur Anzaklardan biri esir düşer kahraman Mehmet’e

Yaraları sarılır imanın verdiği merhamet ruhuyla ortak eder erzaka

Savaş biter Anzak Salı verilir hur olarak gider kendi memleketine

Yıllar sonra hasta olur Amerika’da yatar bir hastaneye de

Koluna dövme yaptırmıştır Albayrağı iftiharla gösterir herkese

Doktor Ömer sorar yaşlı ihtiyara baba Türk’müşsün diye 

Yaşlı adam kaşlarını kaldırır Ömer’e hayır dercesine

Ben Anzak’ım der anlatır İngilizlerin Çanakkale de şerefsizliklerini

Civan mert cengâver insanlar karşısında görür yapılan haksızlıklarını

Bayrağa yakışır şekilde adını koyar Anzak Ömer ret eder Hıristiyanlığı

Son nefesinde Anzak Ömer kelimeyi tevhitle ilan eder Müslümanlığı

Halil Çolak 21.8.2005 Gelibolu', 'Kahpe İngiliz Anzakları haclı ruhuyla kandırır sürer cepheye Kader budur Anzaklardan biri esir düşer kahraman Mehmet’e Yaraları sarılır iman...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canakkale-kahramanlari-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale savaşı Menkıbeleri 2', 'canakkale-savasi-menkibeleri-2-halil-colak-yy5vn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cevat Paşa çimenlik iskelesinden tabyalara bakmak için geçer karşı sahile

Cephenin her tarafını gezerek dolaşır adım adım bir yeri bırakmaz bile

Bir nefer dikkatini çeker, nefer paşanın sesini duyar duymaz kendini tanıtır bile

Gözlerine bir şeymi oldu oğlum? Üzülmeyin efendim gözlerim göreceğini gördü bile.

Düşman gemileri Mehmet’in gören gözleriyle düşman gemileri batmış sulara gömülmüş bile

Cevat Paşa ağlıyordu kahraman cengâver asker gözleri görmese bile esas duruşundadır yine 

Halil Çolak 21.8.2005 Gelibolu', 'Cevat Paşa çimenlik iskelesinden tabyalara bakmak için geçer karşı sahile Cephenin her tarafını gezerek dolaşır adım adım bir yeri bırakmaz ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/canakkale-savasi-menkibeleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemim Bunu Yazar Ancak', 'kalemim-bunu-yazar-ancak-memet-karabalik-wszkr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neresinden bakarsan bak

Zaman inanılmaz acılarla dolu

Poliyannacılık yapamayacak kadar incitici yaralar sarmış ovaları

Dağların zirveleri ulaşmak için değil

Bir kere sevmeye dur 

Acılara köprü kurdun demektir

Sevdalar üzerinden ağıt yakarsın

Kapısını açan analar acı süpürür ya 

İdama kurulu saatler satılır tezgahlarda

Mürekkep her defasında acı damıtır beyaza 

Beyaz kefen diye sarılır vücutlara 

Pembe giysem ne değişecek sanki 

Karalığım örtünecek belki

Küçük kız yine de selpak satacak 

Eli coplular dolaşacak orda burda 

Ekmek bulamayanlar olacak 

Kafalarına inen copları sunacaklar midelerine 

Dağlardan ovalardan bahsedeceğim ha

Yarin gülüşüne yollar serecek 

Saçlarına ipek

Gözlerine derya diyeceğim öyle mi

Hayal kurup kendimi mutlu edeceğim

Yok öyle 

Kiminle yaşıyorsam onu çizeceğim kağıda

Boş bir mideden 

Asılmış bir surattan 

Kırılmış bir kemikten

Savaşçı bir yürekten başkası olmayacak 

Beyaz bir sayfaya acı konacak acı bir zamanda', 'Neresinden bakarsan bak Zaman inanılmaz acılarla dolu Poliyannacılık yapamayacak kadar incitici yaralar sarmış ovaları Dağların zirveleri ul...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kalemim-bunu-yazar-ancak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale savaşı Menkıbeleri 3', 'canakkale-savasi-menkibeleri-3-halil-colak-nigm8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüksek tepeyi yoğun bir şekilde beyaz bir bulut kaplar

İngiliz Norfolk alayı bütün hazırlığını yapar hücuma kalkar

Anafartalar ovasında zayiat verir telafi edilmez kayba uğrar

İngiliz askerler yavaş yavaş bulutlu tepeye ilerlemeye başlar 

Bulut tüm birliği içine alır rüzgârın istikametinde yükselir gider.

Aramalara rağmen bulunmaz esrarengiz vaziyette yok ulur gider

Halil Çolak 21.8.2005 Gelibolu', 'Yüksek tepeyi yoğun bir şekilde beyaz bir bulut kaplar İngiliz Norfolk alayı bütün hazırlığını yapar hücuma kalkar Anafartalar ovasında zayi...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/canakkale-savasi-menkibeleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Nereye', 'nereden-nereye-memet-karabalik-7e9b3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereden nereye gideriz kim bilir? 

Savrulan yapraklara inat değil, resmen öykünüyoruz

Bir insanı savuracak rüzgar yine insandır

Yol bizimdir

Ha manastırda papaz ha da camide imam

Ha semere vurulmuş eşek

Ha eşeğe semer

Haince pusular kurmak de bize düşer

Hainin ihanetiyle ölmek de

İnsan dediğin nedir ki? 

İki göz, iki el, iki ayak

Göz görür

El sallanır

Ayak yürür', 'Nereden nereye gideriz kim bilir?  Savrulan yapraklara inat değil, resmen öykünüyoruz Bir insanı savuracak rüzgar yine insandır Yol bizimdir...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nereden-nereye-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik yılları', 'genclik-yillari-i-brahim-kilinc-soxgx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tatlı gülüşün peşinde hergün

Koşup yorulduğum gençlik yılları

Bir güzel uğruna oturup hergün

Hayaller kurduğum gençlik yılları

Gece yarıları loş sokaklarda

Hiç gereği yokken boş duraklarda

Güneş gibi sabah o ufuklarda

Umutla doğduğum gençlik yılları

Şimdi oturmuşum sakin köşemde

Kederim de olgun artık neşem de

Umut çiçekleri gönül bahçemde

Aklımdan çıkmıyor gençlik yılları', 'Bir tatlı gülüşün peşinde hergün Koşup yorulduğum gençlik yılları Bir güzel uğruna oturup hergün Hayaller kurduğum gençlik yılları Gece yarı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/genclik-yillari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Hikayesi', 'olumun-hikayesi-memet-karabalik-zi92n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baştan alalım istersen

Hikaye bir eski zamanda peydahlanmış

Adı bilinmez bir eski şehirmiş mekan

Kadının biri bir oğlan çocuk doğurmuş

Doğumlarda keramet varmış o demler

Çocuk kerametsiz doğmuş ama 

Ne gök gürlemiş gelişine

Ne de nehirler coşmuş doğumuna

Baba dışarıda beklemiş hep

Bir mucize olur diye

İnadına, bir yücelik yaşanmamış o gün

Bir sıradan çocuk

Bir sıradan günde doğmuş

Ölümün hikayesi böyle başlamış

Sevinmemişler ama yine isim vermişler çocuğa

Bir sıradan isim daha girmiş ölüm yoluna

Sıradan çocuklar ağlar ya 

O da öyle yapmış 

Acıkmış ağlamış 

Susamış ağlamış 

Düşmüş ağlamış

Kızmış ağlamış

Sıradan çocuklar güler ya

O da öyle yapmış

Oynamış gülmüş

Koşmuş gülmüş

Gıdıklanmış gülmüş

Sevilmiş gülmüş

Tırtılın koza saltanatı gibi kundaklanmış önce 

Koza açılınca kelebek olsun istemişler 

Çocuk oralı olmamış

Oturmayı öğrenmiş

Emeklemeyi öğrendiği gün yakmış kendini

Yürümeyi öğrendiği gün ise kırmış kolunu

Sokak kapıları açılmış bir gün

Sokağın tavanı kadar gülmüş derler

Tanımadığı çocuklarla kavga etmiş önce 

Sonra koşmaca işgal etmiş mahalleyi

Arkadaşları olmuş çocuğun

Oyun arkadaşları

Kavga arkadaşları

Nehir arkadaşları

Bir yaz günü kara bir gömlek giydirmiş babası

Elinden tutmuş çarşıya götürmüş

Bir kağıda çocuğu sıkıştırmışlar

Kağıttaki çocuk okula kayıt yaptırmış

Çocuğun başka arkadaşları olmuş

Okul arkadaşları

Okul bittiği gün çocuk da bitmiş

Evlendirmişler askerden sonra

Bir güzel karısı bir güzel çocuk doğurmuş

Mucize olmuş o gün

Melekler arşdan arza inmişler

Çocuğun çocuğunu selamlamışlar

Oysa bizim çocuk görmemiş bunu, ne de hissetmiş

Çarşıdan eve bir yolmuş ölüm

Bir kamyonun patlayan freniymiş meğer

Bir hikaye böyle bitmiş

Derler ki çocuk ölmüş

Yirmiüçündeymiş henüz', 'Baştan alalım istersen Hikaye bir eski zamanda peydahlanmış Adı bilinmez bir eski şehirmiş mekan Kadının biri bir oğlan çocuk doğurmuş Doğum...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/olumun-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairim Ve Aşığım', 'sairim-ve-asigim-memet-karabalik-4tqdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah gelebilseydim yüreğine

Verebilseydim topladıklarımı

Hayatı içiyorum ve sarhoşum

Yalınayak ve ceketsiz dolaşıyorum

Geceyi yırtıyor bağırtılarım

Sevdamı yıldızlara haykırıyorum

Hasretimi taşlara vurduruyorum

Ah gelebilseydim şehrine

Silah temizliyorum ve katilim

Namluya sevdanı sürüyorum

Maktul hep ben oluyorum

Sevmiyorum bu oyunu

Kilometreleri sevmiyorum

Telefon direklerini de

Otobüs tekerleklerini de

Ah gelebilseydim semtine

Kitap okuyorum ve entelim

Her cümleye seni yazıyorum

Dipnotlara sığıyorum ancak

Kaypak şairlere küfür ediyorum

Ah gelebilseydim kapına

Çalışıyorum geceleri ve işçiyim

Keten dövüyorum bazı

Yoluna para biriktiriyorum

Sevmiyorum bu oyunu

Hasretleri sevmiyorum

Mektupları da

Bu şehri de

Ah gelebilseydim…', 'Ah gelebilseydim yüreğine Verebilseydim topladıklarımı Hayatı içiyorum ve sarhoşum Yalınayak ve ceketsiz dolaşıyorum Geceyi yırtıyor bağırtı...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sairim-ve-asigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale savaşı Menkıbeleri 4', 'canakkale-savasi-menkibeleri-4-halil-colak-nqbfh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kanlısırt’taki mitralyöz kan kusmaktadır durmadan yine

 Akşehir’in Karapınar köyünden Mehmet oğlu Mustafa

Onlara kan kusturan mitralyöz a kafayı takmıştır bir defa

Kendini siperlerinden atarak karıştı gecenin karanlıklarına

Seven iki hemşerisi yalnız bırakmadı ardından yetişti Mustafa ya

El bombalarıyla ansızın salardılar düşman mevzilerine

Düşman baskına uğradığını sandı paniğe kapıldılar bile

Mustafa aman vermeden mitaryolozu sırtlamıştı bile

Vurulan arkadaşını sırtında bu meret pahalıya oturdu bize

Kan kusan mitralyöz Mustafa sayesinde kalmıştı Türk’e

                                              

Halil Çolak 21.8.2005 Gelibolu', 'Kanlısırt’taki mitralyöz kan kusmaktadır durmadan yine  Akşehir’in Karapınar köyünden Mehmet oğlu Mustafa Onlara kan kusturan mitralyöz a ka...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/canakkale-savasi-menkibeleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni kazıdım yüreğime', 'seni-kazidim-yuregime-hekim-coskun-4nj90', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni kazıdım yüreğime

sen beni sevsen de olur

sevmesen de.

büyük umutlar beslediğim yarın

cadde ve sokaklarında ülkemin

kızlı erkekli el-ele

mutlu ol şarkıları söyleyeceğiz

sen gelsen de olur gelmesen de

seni kazıdım yüreğime

sen  beni sevsen de olur 

sevmesen de.

derin bir iç çekişte gizlediğim

yalnızlığımsın.

hani tüm nehirler denize akar ya

en büyük deniz sen ol istedim

tüm sevgiler sana aksın istedim.

ben duru dingin akarım

bazen hayal kurar 

tıpkı  kuru bir yaprak gibi

savrulurum oradan oraya,

sen beni görsen de olur

görmesen de.

öfkemi kuşanmış asiyim dağların da ülkemin

sen beni vursan da olur

vurmasan da.

ben seni kazıdım yüreğime

sen bana varsan da olur

varmasan da.

www.antoloji.com/hekim_coskun', 'seni kazıdım yüreğime sen beni sevsen de olur sevmesen de. büyük umutlar beslediğim yarın cadde ve sokaklarında ülkemin kızlı erkekli el-ele...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seni-kazidim-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kentin Sokakları', 'kentin-sokaklari-okan-nar-llc49', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soluk yüzlerde; 

Kararmış kalpleri gördüm,

Kentin caddelerinde.

Yürürken kaldırımlarında; 

Sinsi yürüyüşleri ve gülüşleri gördüm,

Kentin sokaklarında.

Gündüzün aydınlığında; 

Karanlık vicdanları gördüm,

Kentin serseri mekanlarında.

Çöplerden ekmek toplayan; 

Çocukları ve nineleri gördüm,

Kentin gecelerinde ve varoşlarında.

Ucuz insanları gördüm; 

Bozzuk paraların sesini duydum,

Kentin insan pazarlarında.', 'Soluk yüzlerde;  Kararmış kalpleri gördüm, Kentin caddelerinde. Yürürken kaldırımlarında;  Sinsi yürüyüşleri ve gülüşleri gördüm, Kentin sok...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kentin-sokaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemen', 'yasemen-nalan-kahraman-y1q7c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi gözlüm,bebek suratlım,

Arkadaşım,yasemenim,

Candaşım,yoldaşım,

Sırdaşım,ev arkadaşım,

Doğum günlerimi asla untmayanım,

Adıma savaşanım,Ağlayanım,

Şimdi senin........

Bu zamansız gidişinle; 

Seni daima özlemleyenim,

Seni hep yad edenim,

Şuleler,Edalar gibi,

Sensizliğe dayanamayanım,

Gözlerinden yıldızlar düşürenim,

Gidişine inanmayanım,

Alışamayanım,

Siroz kelimesini duyamayanım,

Yüreği sızlayan,

Canı yananım,

Mavi gözlüm,Yasemenim.

Biliyorum ki Şu an.......! 

Ben seni göremesem de......! 

Görensin,duyansın,

Mavi gözlüm,Yasemenim.

Kızma bana ne olur..! 

Gözlerimden düşen yaş değil,

Senin geride bıraktığın yıldızlarındır.

Mavi gözlüm,Yasemenim', 'Mavi gözlüm,bebek suratlım, Arkadaşım,yasemenim, Candaşım,yoldaşım, Sırdaşım,ev arkadaşım, Doğum günlerimi asla untmayanım, Adıma savaşanım,...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yasemen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkağaç Kavunu', 'kirkagac-kavunu-i-lhan-koruyucu-hov5c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırkağaç Kavunu

Altın sarısı rengin 

Bulunmaz kavunlar içinde dengin

Tadından yapışır damağına

Ağustos ayından önce çıkmaz kendin

Kırkağaç kavunu bir başkadır 

İnanmazsanız bir parça sizde tadın

Alın elinize çatalı doya doya

O güzelim kavunun tadına varın

Eğer gerçek Kırkağaç kavunu yemek istersen

Erinmeyip varın gidin ve yerinden alın.

İlhan Koruyucu.', 'Kırkağaç Kavunu Altın sarısı rengin  Bulunmaz kavunlar içinde dengin Tadından yapışır damağına Ağustos ayından önce çıkmaz kendin Kırkağaç k...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirkagac-kavunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin?', 'neredesin-i-lhan-koruyucu-o73zj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neredesin? 

Arıyorum arıyorum, bulamıyorum

Ne bendesin ne de kendinde

Nerelerde arasam sorsam seni

Bulabilmek için nasıl çaba harcasam

Sende beni anlamak için biraz anlasan

Neredesin bir tanem sen nerdesin

Bakıyorum gözlerinin içinde yoksun 

Arıyorum gökyüzünde de değilsin

Acaba yerde misin dedim

Sordum çalışkan karıncalara

Çok bilinmeyenli denklem gibisin

Duygularımda olmadığın gibi

Aklımda da yoksun

Öyleyse sen bil ki! 

Hiç olmadın

Olmayacaksın.

İlhan Koruyucu.', 'Neredesin?  Arıyorum arıyorum, bulamıyorum Ne bendesin ne de kendinde Nerelerde arasam sorsam seni Bulabilmek için nasıl çaba harcasam Sende...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neredesin-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve İtiraf Şarkıları16', 'ask-ve-i-tiraf-sarkilari16-yasar-pasaoglu-qlzne', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana inan ben sevgisiz yolu bilemem

Uzak dalgalarda seni süzgeçten arıyorum

Hiç bir zaman başkasına senden gidemem

Soğuk fırtınalar bizden vazgeçer anlıyorum.

Hayret gibisin hayatta benim güzelim

Gece ve gündüz ben seni kuşkusuz avlıyorum

Seni ben duymazsam bil yaş olur gözlerim

Ve görmezsem seni çoçuk gibi ben ağlıyorum.

Bizim dolu şu aşkıdan kaçarlar buğlar

Büyük bu duygumu sana tanrıdan diliyorum,

İki yürek arasında kaynarlar buzlar,

Cennet sırlarında seni yeniden seviyorum!', 'Bana inan ben sevgisiz yolu bilemem Uzak dalgalarda seni süzgeçten arıyorum Hiç bir zaman başkasına senden gidemem Soğuk fırtınalar bizden v...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Paşaoğlu']::text[], 8.5, '{"poet":"Yaşar Paşaoğlu","poet_slug":"yasar-pasaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-ve-itiraf-sarkilari16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve İtiraf Şarkıları17', 'ask-ve-i-tiraf-sarkilari17-yasar-pasaoglu-wxlae', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Esracım benim kınama beni zor olsada,

Sensiz yüreğim benim soğuk,boş leğen 

Sevgiden,senden o yüce Tanrı korusada

Olmuşum senin uzun vadeli gölgen.

Ben gece gündüz göğsümde tatlı of çekerim

Bana ekrandan gelen fantazi melek,

Güneşim seni yirmi dört saat ben severim

Senin önünde bil ben taşfırın erkek.

Rakipsiz Adan Z’ye bir program bitirirken

Canım sen devam et şu harika rolü,

Gönlünden üzülme sen hiç beni ittirirken,

Sen sel,fırtına,ateş,ben canlı ölü!', 'Esracım benim kınama beni zor olsada, Sensiz yüreğim benim soğuk,boş leğen  Sevgiden,senden o yüce Tanrı korusada Olmuşum senin uzun vadeli ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Paşaoğlu']::text[], 8.5, '{"poet":"Yaşar Paşaoğlu","poet_slug":"yasar-pasaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-ve-itiraf-sarkilari17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşimsin', 'gunesimsin-seyfettin-bilal-ozluk-1n9zp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünceler içimde sessizce büyürken

Bir anda çıktın karşıma

Bir peri masalı,

Issız çölde bir serap,

Ve gökyüzünde kaybolmayan güneş...

Sen güneşimsin

Aydınlatan yol gösteren

Gözümdeki sır perdesini kaldıran

Hemde yarınıma yön veren

Kaybolma delhizlerde

Yok olma karanlıklarda

Çünki sen benim güneşimsin

Gecemde olmasanda...', 'Düşünceler içimde sessizce büyürken Bir anda çıktın karşıma Bir peri masalı, Issız çölde bir serap, Ve gökyüzünde kaybolmayan güneş... Sen g...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunesimsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlle gel-İllegal İstek', 'i-lle-gel-i-llegal-i-stek-osman-kilic-l6ayk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İshalden feri sönmüş bebeğe suydu

Sıtmalı köyün gelinine cibinlik

Düzensiz yüreklerin silinmez kabusuydu

Sıkılgan lab-dablara geçici bir serinlik

Ve hep zamansız gitti malum yere olsun

Bir yanımızı biz de yeraltına indirdik...

Eski şaraplar içilsin şimdi

Eski şiirler okunsun

Coşmak ağlamak gülmek her nevi

Hisler eksik yanımıza dokunsun

Kanalım eski aşklara-ebedi

Her gece bir sevgili

Bize kendini sunsun-çok görme ilahi

Geçinip gidelim şimdilik

Susun kalemsiz katipler susun

Daha vaktimiz var birkaç yeminlik...

11.07.2004', 'İshalden feri sönmüş bebeğe suydu Sıtmalı köyün gelinine cibinlik Düzensiz yüreklerin silinmez kabusuydu Sıkılgan lab-dablara geçici bir ser...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ille-gel-illegal-istek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakaret', 'hakaret-nalan-kahraman-5kqer', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mendil uzatıyorsun,

Sil gözyaşlarını diyorsun,

Hakaret ettiğini bilmiyorsun.

Bilmiyorsun,

Ben şirin iken,

Aslı iken,

Leyla iken,

Gözümden akan yaşlara,

Uzatılan tüm mendilleri,

Hakaret saydığımı.

Ben beklerken; 

Ferhatı mı,

Keremi mi,

Mecnunu mu; 

Bana mendil uzatırsa; 

Ferhatım,

Keremim,

Mecnunum.

O hakareti alır,

Silerim gözlerimin 

Tüm yaşını da,pasını da....', 'Mendil uzatıyorsun, Sil gözyaşlarını diyorsun, Hakaret ettiğini bilmiyorsun. Bilmiyorsun, Ben şirin iken, Aslı iken, Leyla iken, Gözümden ak...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hakaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
